import sys
import os
import struct
from collections import deque


def extract_channel(pixel_val, mask):
    if mask == 0:
        return 0
    s = (mask & -mask).bit_length() - 1  # number of trailing zeros
    n = bin(mask).count('1')
    m = (1 << n) - 1
    v = (pixel_val & mask) >> s
    return (v * 255 + m // 2) // m


def get_pixel(data, row_offset, x, bpp, palette, compression, red_mask, green_mask, blue_mask):
    if bpp == 1:
        byte_idx = x // 8
        bit_idx = 7 - (x % 8)
        byte_val = data[row_offset + byte_idx]
        idx = (byte_val >> bit_idx) & 1
        return palette[idx] if idx < len(palette) else (0, 0, 0)
    elif bpp == 4:
        byte_idx = x // 2
        if x % 2 == 0:
            idx = (data[row_offset + byte_idx] >> 4) & 0xF
        else:
            idx = data[row_offset + byte_idx] & 0xF
        return palette[idx] if idx < len(palette) else (0, 0, 0)
    elif bpp == 8:
        idx = data[row_offset + x]
        return palette[idx] if idx < len(palette) else (0, 0, 0)
    elif bpp == 24:
        b = data[row_offset + x * 3]
        g = data[row_offset + x * 3 + 1]
        r = data[row_offset + x * 3 + 2]
        return (r, g, b)
    elif bpp == 32:
        if compression == 0:
            b = data[row_offset + x * 4]
            g = data[row_offset + x * 4 + 1]
            r = data[row_offset + x * 4 + 2]
            return (r, g, b)
        else:  # compression == 3
            pixel_val = struct.unpack_from('<I', data, row_offset + x * 4)[0]
            r = extract_channel(pixel_val, red_mask)
            g = extract_channel(pixel_val, green_mask)
            b = extract_channel(pixel_val, blue_mask)
            return (r, g, b)
    return (0, 0, 0)


def read_bmp(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    if len(data) < 54 or data[0:2] != b'BM':
        return None

    bfOffBits = struct.unpack_from('<I', data, 10)[0]

    dib_size = struct.unpack_from('<I', data, 14)[0]
    width = struct.unpack_from('<i', data, 18)[0]
    height_raw = struct.unpack_from('<i', data, 22)[0]
    bpp = struct.unpack_from('<H', data, 28)[0]
    compression = struct.unpack_from('<I', data, 30)[0]
    colours_used = struct.unpack_from('<I', data, 46)[0]

    # Masks for BI_BITFIELDS
    red_mask = green_mask = blue_mask = 0
    if dib_size >= 108:
        red_mask = struct.unpack_from('<I', data, 54)[0]
        green_mask = struct.unpack_from('<I', data, 58)[0]
        blue_mask = struct.unpack_from('<I', data, 62)[0]
    elif compression == 3 and dib_size == 40:
        red_mask = struct.unpack_from('<I', data, 54)[0]
        green_mask = struct.unpack_from('<I', data, 58)[0]
        blue_mask = struct.unpack_from('<I', data, 62)[0]

    if compression not in (0, 3):
        return {'error': compression}

    top_down = height_raw < 0
    height = abs(height_raw)

    # Read palette
    palette = []
    if bpp <= 8:
        num_colors = colours_used if colours_used != 0 else (1 << bpp)
        palette_offset = 14 + dib_size
        for i in range(num_colors):
            off = palette_offset + i * 4
            if off + 4 <= len(data):
                b, g, r, _ = struct.unpack_from('<BBBB', data, off)
                palette.append((r, g, b))
            else:
                palette.append((0, 0, 0))

    # Row stride padded to 4 bytes
    row_bytes = (width * bpp + 7) // 8
    row_stride = (row_bytes + 3) // 4 * 4

    # Build ink grid
    ink = [[False] * width for _ in range(height)]

    for y in range(height):
        if top_down:
            stored_row = y
        else:
            stored_row = height - 1 - y

        row_offset = bfOffBits + stored_row * row_stride

        for x in range(width):
            r, g, b = get_pixel(data, row_offset, x, bpp, palette, compression,
                                red_mask, green_mask, blue_mask)
            if (299 * r + 587 * g + 114 * b) // 1000 < 128:
                ink[y][x] = True

    return {
        'width': width,
        'height': height,
        'bpp': bpp,
        'dib_size': dib_size,
        'top_down': top_down,
        'ink': ink
    }


def find_components(ink, width, height):
    visited = [[False] * width for _ in range(height)]
    components = []

    for y in range(height):
        for x in range(width):
            if ink[y][x] and not visited[y][x]:
                component = []
                queue = deque()
                queue.append((x, y))
                visited[y][x] = True
                while queue:
                    cx, cy = queue.popleft()
                    component.append((cx, cy))
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = cx + dx, cy + dy
                            if 0 <= nx < width and 0 <= ny < height:
                                if ink[ny][nx] and not visited[ny][nx]:
                                    visited[ny][nx] = True
                                    queue.append((nx, ny))
                components.append(component)

    return components


def main():
    if len(sys.argv) < 2:
        return

    directory = sys.argv[1]
    files = sorted([f for f in os.listdir(directory) if f.endswith('.bmp')],
                   key=lambda f: f.encode())

    for fname in files:
        filepath = os.path.join(directory, fname)
        result = read_bmp(filepath)

        if result is None:
            continue

        if 'error' in result:
            print(f"== {fname}")
            print(f"error: unsupported compression {result['error']}")
            continue

        width = result['width']
        height = result['height']
        bpp = result['bpp']
        dib_size = result['dib_size']
        top_down = result['top_down']
        ink = result['ink']

        ink_count = sum(1 for y in range(height) for x in range(width) if ink[y][x])

        components = find_components(ink, width, height)

        orientation = "top-down" if top_down else "bottom-up"

        print(f"== {fname}")
        print(f"size {width}x{height} bpp {bpp} header {dib_size} {orientation} ink {ink_count}")
        print(f"components {len(components)}")

        for comp in components:
            first = min(comp, key=lambda p: (p[1], p[0]))
            min_x = min(p[0] for p in comp)
            max_x = max(p[0] for p in comp)
            min_y = min(p[1] for p in comp)
            max_y = max(p[1] for p in comp)
            count = len(comp)
            print(f"{first[0]},{first[1]} bbox {min_x},{min_y}-{max_x},{max_y} pixels {count}")


if __name__ == '__main__':
    main()

use std::env;
use std::fs;
use std::io::Read;
use std::path::Path;

fn read_u16(data: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([data[offset], data[offset + 1]])
}

fn read_u32(data: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_i32(data: &[u8], offset: usize) -> i32 {
    i32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn extract_channel(pixel: u32, mask: u32) -> u32 {
    if mask == 0 {
        return 0;
    }
    let s = mask.trailing_zeros();
    let n = mask.count_ones();
    let m = (1u32 << n) - 1;
    let v = (pixel & mask) >> s;
    (v * 255 + m / 2) / m
}

fn process_bmp(filename: &str, data: &[u8]) -> String {
    if data.len() < 14 || data[0] != b'B' || data[1] != b'M' {
        return format!("== {}\nerror: invalid file\n", filename);
    }

    let bf_off_bits = read_u32(data, 10) as usize;
    let dib_size = read_u32(data, 14) as usize;
    let width = read_i32(data, 18);
    let height = read_i32(data, 22);
    let bpp = read_u16(data, 28) as usize;
    let compression = read_u32(data, 30);
    let colors_used = read_u32(data, 46) as usize;

    let bottom_up = height > 0;
    let h = height.unsigned_abs() as usize;
    let w = width as usize;

    if compression != 0 && compression != 3 {
        return format!("== {}\nerror: unsupported compression {}\n", filename, compression);
    }

    // Get masks for BI_BITFIELDS
    let (red_mask, green_mask, blue_mask) = if compression == 3 {
        // For both 40-byte and 108/124-byte headers, masks are at offset 54 from file start
        // (14 + 40 = 54)
        let rm = read_u32(data, 54);
        let gm = read_u32(data, 58);
        let bm = read_u32(data, 62);
        (rm, gm, bm)
    } else {
        (0u32, 0u32, 0u32)
    };

    // Palette offset: right after DIB header
    let palette_offset = 14 + dib_size;
    let palette_entries = if colors_used == 0 {
        1usize << bpp
    } else {
        colors_used
    };
    let _ = palette_entries; // used implicitly when indexing

    // Row size calculations
    let row_bytes = (w * bpp + 7) / 8;
    let row_padded = (row_bytes + 3) / 4 * 4;

    let mut ink = vec![false; w * h];

    for y in 0..h {
        let stored_y = if bottom_up { h - 1 - y } else { y };
        let row_offset = bf_off_bits + stored_y * row_padded;

        for x in 0..w {
            let (r, g, b) = match bpp {
                1 | 4 | 8 => {
                    let byte_idx = row_offset + (x * bpp) / 8;
                    let bit_offset = (x * bpp) % 8;
                    let byte = data[byte_idx];
                    let index = match bpp {
                        1 => ((byte >> (7 - bit_offset)) & 1) as usize,
                        4 => ((byte >> (4 - bit_offset)) & 0xF) as usize,
                        8 => byte as usize,
                        _ => unreachable!(),
                    };
                    let pal_idx = palette_offset + index * 4;
                    let b_val = data[pal_idx] as u32;
                    let g_val = data[pal_idx + 1] as u32;
                    let r_val = data[pal_idx + 2] as u32;
                    (r_val, g_val, b_val)
                }
                24 => {
                    let idx = row_offset + x * 3;
                    let b_val = data[idx] as u32;
                    let g_val = data[idx + 1] as u32;
                    let r_val = data[idx + 2] as u32;
                    (r_val, g_val, b_val)
                }
                32 => {
                    let idx = row_offset + x * 4;
                    if compression == 3 {
                        let pixel = read_u32(data, idx);
                        let r = extract_channel(pixel, red_mask);
                        let g = extract_channel(pixel, green_mask);
                        let b = extract_channel(pixel, blue_mask);
                        (r, g, b)
                    } else {
                        let b_val = data[idx] as u32;
                        let g_val = data[idx + 1] as u32;
                        let r_val = data[idx + 2] as u32;
                        (r_val, g_val, b_val)
                    }
                }
                _ => (0, 0, 0),
            };

            let luminance = (299 * r + 587 * g + 114 * b) / 1000;
            ink[y * w + x] = luminance < 128;
        }
    }

    // Count ink pixels
    let ink_count = ink.iter().filter(|&&v| v).count();

    // Find connected components using BFS/DFS with 8-connectivity
    let mut visited = vec![false; w * h];
    let mut components: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            if ink[idx] && !visited[idx] {
                // BFS
                let mut queue: Vec<(usize, usize)> = vec![(x, y)];
                visited[idx] = true;
                let mut minx = x;
                let mut miny = y;
                let mut maxx = x;
                let mut maxy = y;
                let mut count: usize = 0;

                while let Some((cx, cy)) = queue.pop() {
                    count += 1;
                    if cx < minx { minx = cx; }
                    if cy < miny { miny = cy; }
                    if cx > maxx { maxx = cx; }
                    if cy > maxy { maxy = cy; }

                    for dy in -1i32..=1 {
                        for dx in -1i32..=1 {
                            if dx == 0 && dy == 0 { continue; }
                            let nx = cx as i32 + dx;
                            let ny = cy as i32 + dy;
                            if nx >= 0 && nx < w as i32 && ny >= 0 && ny < h as i32 {
                                let nidx = ny as usize * w + nx as usize;
                                if ink[nidx] && !visited[nidx] {
                                    visited[nidx] = true;
                                    queue.push((nx as usize, ny as usize));
                                }
                            }
                        }
                    }
                }

                components.push((x, y, minx, miny, maxx, maxy, count));
            }
        }
    }

    let mut result = String::new();
    result.push_str(&format!("== {}\n", filename));
    let orientation = if bottom_up { "bottom-up" } else { "top-down" };
    result.push_str(&format!(
        "size {}x{} bpp {} header {} {} ink {}\n",
        w, h, bpp, dib_size, orientation, ink_count
    ));
    result.push_str(&format!("components {}\n", components.len()));

    for (fx, fy, minx, miny, maxx, maxy, count) in &components {
        result.push_str(&format!(
            "{},{} bbox {},{}-{},{} pixels {}\n",
            fx, fy, minx, miny, maxx, maxy, count
        ));
    }

    result
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".bmp") {
            files.push(name);
        }
    }
    files.sort();

    let mut output = String::new();
    for name in &files {
        let path = Path::new(dir).join(name);
        let mut file = fs::File::open(&path).unwrap();
        let mut data = Vec::new();
        file.read_to_end(&mut data).unwrap();

        output.push_str(&process_bmp(name, &data));
    }

    print!("{}", output);
}

import Foundation

func readU16(_ data: Data, _ offset: Int) -> UInt16 {
    return UInt16(data[offset]) | (UInt16(data[offset + 1]) << 8)
}

func readU32(_ data: Data, _ offset: Int) -> UInt32 {
    return UInt32(data[offset]) | (UInt32(data[offset + 1]) << 8) | (UInt32(data[offset + 2]) << 16) | (UInt32(data[offset + 3]) << 24)
}

func readI32(_ data: Data, _ offset: Int) -> Int32 {
    return Int32(bitPattern: readU32(data, offset))
}

func extractChannel(_ pixel: UInt32, _ mask: UInt32) -> UInt8 {
    if mask == 0 { return 0 }
    let s = mask.trailingZeroBitCount
    let v = (pixel & mask) >> UInt32(s)
    let n = mask.nonzeroBitCount
    let m = UInt32((1 << n) - 1)
    if m == 0 { return 0 }
    return UInt8((v * 255 + m / 2) / m)
}

func processFile(_ path: String, _ name: String) {
    guard let data = FileManager.default.contents(atPath: path) else { return }
    guard data.count >= 14 else { return }
    guard data[0] == 0x42, data[1] == 0x4D else { return }

    let bfOffBits = Int(readU32(data, 10))

    guard data.count >= 18 else { return }
    let dibSize = Int(readU32(data, 14))
    guard dibSize == 40 || dibSize == 108 || dibSize == 124 else { return }
    guard data.count >= 14 + dibSize else { return }

    let width = Int(readI32(data, 18))
    let heightRaw = Int(readI32(data, 22))
    let bottomUp = heightRaw > 0
    let height = abs(heightRaw)
    let bpp = Int(readU16(data, 28))
    let compression = Int(readU32(data, 30))
    let coloursUsed = Int(readU32(data, 46))

    if compression != 0 && compression != 3 {
        print("== \(name)")
        print("error: unsupported compression \(compression)")
        return
    }
    if compression == 3 && bpp != 32 {
        print("== \(name)")
        print("error: unsupported compression \(compression)")
        return
    }

    var redMask: UInt32 = 0
    var greenMask: UInt32 = 0
    var blueMask: UInt32 = 0

    if compression == 3 {
        let maskOffset = 14 + 40
        if maskOffset + 12 <= data.count {
            redMask = readU32(data, maskOffset)
            greenMask = readU32(data, maskOffset + 4)
            blueMask = readU32(data, maskOffset + 8)
        }
    }

    let paletteOffset = 14 + dibSize
    let numColors = coloursUsed != 0 ? coloursUsed : (1 << bpp)
    var paletteR = [UInt8](repeating: 0, count: numColors)
    var paletteG = [UInt8](repeating: 0, count: numColors)
    var paletteB = [UInt8](repeating: 0, count: numColors)

    if bpp <= 8 {
        for i in 0..<numColors {
            let off = paletteOffset + i * 4
            if off + 3 < data.count {
                paletteB[i] = data[off]
                paletteG[i] = data[off + 1]
                paletteR[i] = data[off + 2]
            }
        }
    }

    var inkPixels = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var inkCount = 0

    let rowBytes = (width * bpp + 7) / 8
    let paddedRowBytes = (rowBytes + 3) / 4 * 4

    for y in 0..<height {
        let storedY: Int
        if bottomUp {
            storedY = height - 1 - y
        } else {
            storedY = y
        }
        let rowOffset = bfOffBits + storedY * paddedRowBytes

        for x in 0..<width {
            var r: UInt8 = 0, g: UInt8 = 0, b: UInt8 = 0

            switch bpp {
            case 1:
                let byteIdx = x / 8
                let bitIdx = 7 - (x % 8)
                let off = rowOffset + byteIdx
                if off < data.count {
                    let idx = Int((data[off] >> bitIdx) & 1)
                    if idx < numColors {
                        r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
                    }
                }
            case 4:
                let byteIdx = x / 2
                let off = rowOffset + byteIdx
                if off < data.count {
                    var idx: Int
                    if x % 2 == 0 {
                        idx = Int((data[off] >> 4) & 0xF)
                    } else {
                        idx = Int(data[off] & 0xF)
                    }
                    if idx < numColors {
                        r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
                    }
                }
            case 8:
                let off = rowOffset + x
                if off < data.count {
                    let idx = Int(data[off])
                    if idx < numColors {
                        r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
                    }
                }
            case 24:
                let off = rowOffset + x * 3
                if off + 2 < data.count {
                    b = data[off]; g = data[off + 1]; r = data[off + 2]
                }
            case 32:
                let off = rowOffset + x * 4
                if off + 3 < data.count {
                    if compression == 0 {
                        b = data[off]; g = data[off + 1]; r = data[off + 2]
                    } else {
                        let pixel = readU32(data, off)
                        r = extractChannel(pixel, redMask)
                        g = extractChannel(pixel, greenMask)
                        b = extractChannel(pixel, blueMask)
                    }
                }
            default:
                break
            }

            let lum = (299 * Int(r) + 587 * Int(g) + 114 * Int(b)) / 1000
            if lum < 128 {
                inkPixels[y][x] = true
                inkCount += 1
            }
        }
    }

    // Connected components via BFS (8-connectivity)
    var visited = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var components: [(firstX: Int, firstY: Int, minX: Int, minY: Int, maxX: Int, maxY: Int, count: Int)] = []

    let dx = [-1, 0, 1, -1, 1, -1, 0, 1]
    let dy = [-1, -1, -1, 0, 0, 1, 1, 1]

    for y in 0..<height {
        for x in 0..<width {
            if inkPixels[y][x] && !visited[y][x] {
                var queue: [(Int, Int)] = []
                queue.reserveCapacity(width * height)
                queue.append((x, y))
                visited[y][x] = true
                var head = 0
                var count = 0
                var minX = x, maxX = x, minY = y, maxY = y

                while head < queue.count {
                    let (cx, cy) = queue[head]
                    head += 1
                    count += 1
                    if cx < minX { minX = cx }
                    if cx > maxX { maxX = cx }
                    if cy < minY { minY = cy }
                    if cy > maxY { maxY = cy }

                    for i in 0..<8 {
                        let nx = cx + dx[i]
                        let ny = cy + dy[i]
                        if nx >= 0 && nx < width && ny >= 0 && ny < height && inkPixels[ny][nx] && !visited[ny][nx] {
                            visited[ny][nx] = true
                            queue.append((nx, ny))
                        }
                    }
                }

                components.append((firstX: x, firstY: y, minX: minX, minY: minY, maxX: maxX, maxY: maxY, count: count))
            }
        }
    }

    let orientation = bottomUp ? "bottom-up" : "top-down"
    print("== \(name)")
    print("size \(width)x\(height) bpp \(bpp) header \(dibSize) \(orientation) ink \(inkCount)")
    print("components \(components.count)")
    for comp in components {
        print("\(comp.firstX),\(comp.firstY) bbox \(comp.minX),\(comp.minY)-\(comp.maxX),\(comp.maxY) pixels \(comp.count)")
    }
}

let args = CommandLine.arguments
