import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static Map<String, Integer> currencies = new HashMap<>();
    static Map<String, Account> accounts = new LinkedHashMap<>();
    static List<String> rejections = new ArrayList<>();

    static class Account {
        String currency;
        BigDecimal balance;
        BigDecimal limit;

        Account(String currency, BigDecimal balance, BigDecimal limit) {
            this.currency = currency;
            this.balance = balance;
            this.limit = limit;
        }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        BufferedReader br = new BufferedReader(new FileReader(dir + "/ledger.txt"));
        String line;
        int lineNum = 0;

        while ((line = br.readLine()) != null) {
            lineNum++;
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#")) continue;
            String[] parts = trimmed.split("\\s+");
            processCommand(lineNum, parts);
        }
        br.close();

        for (String r : rejections) {
            System.out.println(r);
        }
        System.out.println();

        List<String> names = new ArrayList<>(accounts.keySet());
        Collections.sort(names);
        for (String name : names) {
            Account acc = accounts.get(name);
            int mu = currencies.get(acc.currency);
            System.out.println(name + " " + acc.currency + " " + formatMoney(acc.balance, mu));
        }
        System.out.println();

        Map<String, BigDecimal> totals = new TreeMap<>();
        Map<String, Integer> counts = new TreeMap<>();
        for (String name : names) {
            Account acc = accounts.get(name);
            String code = acc.currency;
            totals.merge(code, acc.balance, BigDecimal::add);
            counts.merge(code, 1, Integer::sum);
        }
        for (String code : totals.keySet()) {
            int mu = currencies.get(code);
            System.out.println("total " + code + " " + formatMoney(totals.get(code), mu)
                    + " (" + counts.get(code) + " accounts)");
        }
    }

    static BigDecimal round(BigDecimal value, int minorUnits) {
        return value.setScale(minorUnits, RoundingMode.HALF_EVEN);
    }

    static BigDecimal parseAmount(String s) {
        return new BigDecimal(s);
    }

    static String formatMoney(BigDecimal value, int minorUnits) {
        value = round(value, minorUnits);
        if (value.signum() == 0) {
            value = BigDecimal.ZERO.setScale(minorUnits);
        }
        boolean negative = value.signum() < 0;
        BigInteger unscaled = value.unscaledValue().abs();
        BigInteger divisor = BigInteger.TEN.pow(minorUnits);
        BigInteger intPart = unscaled.divide(divisor);
        BigInteger fracPart = unscaled.mod(divisor);

        String intStr = intPart.toString();
        StringBuilder sb = new StringBuilder();
        if (negative) sb.append('-');
        int len = intStr.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) sb.append(',');
            sb.append(intStr.charAt(i));
        }
        if (minorUnits > 0) {
            sb.append('.');
            String fracStr = fracPart.toString();
            while (fracStr.length() < minorUnits) {
                fracStr = "0" + fracStr;
            }
            sb.append(fracStr);
        }
        return sb.toString();
    }

    static void processCommand(int lineNum, String[] parts) {
        String cmd = parts[0];
        switch (cmd) {
            case "currency": {
                String code = parts[1];
                int mu = Integer.parseInt(parts[2]);
                currencies.put(code, mu);
                break;
            }
            case "open": {
                String name = parts[1];
                String code = parts[2];
                if (accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT account exists " + name);
                    return;
                }
                int mu = currencies.get(code);
                BigDecimal limit = BigDecimal.ZERO;
                if (parts.length > 3) {
                    limit = round(parseAmount(parts[3]), mu);
                }
                accounts.put(name, new Account(code, BigDecimal.ZERO, limit));
                break;
            }
            case "deposit": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal amount = round(parseAmount(parts[2]), mu);
                if (amount.signum() <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                acc.balance = acc.balance.add(amount);
                break;
            }
            case "withdraw": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal amount = round(parseAmount(parts[2]), mu);
                if (amount.signum() <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                BigDecimal newBalance = acc.balance.subtract(amount);
                if (newBalance.compareTo(acc.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + name);
                    return;
                }
                acc.balance = newBalance;
                break;
            }
            case "transfer": {
                String from = parts[1];
                String to = parts[2];
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                if (!accounts.containsKey(to)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + to);
                    return;
                }
                Account fromAcc = accounts.get(from);
                Account toAcc = accounts.get(to);
                if (!fromAcc.currency.equals(toAcc.currency)) {
                    rejections.add("line " + lineNum + ": REJECT currency mismatch");
                    return;
                }
                int mu = currencies.get(fromAcc.currency);
                BigDecimal amount = round(parseAmount(parts[3]), mu);
                if (amount.signum() <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                BigDecimal newBalance = fromAcc.balance.subtract(amount);
                if (newBalance.compareTo(fromAcc.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                fromAcc.balance = newBalance;
                toAcc.balance = toAcc.balance.add(amount);
                break;
            }
            case "convert": {
                String from = parts[1];
                String to = parts[2];
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                if (!accounts.containsKey(to)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + to);
                    return;
                }
                Account fromAcc = accounts.get(from);
                Account toAcc = accounts.get(to);
                int fromMu = currencies.get(fromAcc.currency);
                BigDecimal amount = round(parseAmount(parts[3]), fromMu);
                if (amount.signum() <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                BigDecimal newBalance = fromAcc.balance.subtract(amount);
                if (newBalance.compareTo(fromAcc.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                BigDecimal rate = parseAmount(parts[4]);
                int toMu = currencies.get(toAcc.currency);
                BigDecimal received = round(amount.multiply(rate), toMu);
                fromAcc.balance = newBalance;
                toAcc.balance = toAcc.balance.add(received);
                break;
            }
            case "interest": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal rate = parseAmount(parts[2]);
                BigDecimal interest = round(acc.balance.multiply(rate), mu);
                acc.balance = acc.balance.add(interest);
                break;
            }
            case "split": {
                String from = parts[1];
                List<String> targetNames = new ArrayList<>();
                List<BigInteger> weights = new ArrayList<>();
                for (int i = 3; i < parts.length; i++) {
                    String[] tw = parts[i].split(":");
                    targetNames.add(tw[0]);
                    weights.add(new BigInteger(tw[1]));
                }
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                for (String tn : targetNames) {
                    if (!accounts.containsKey(tn)) {
                        rejections.add("line " + lineNum + ": REJECT unknown account " + tn);
                        return;
                    }
                }
                Account fromAcc = accounts.get(from);
                for (String tn : targetNames) {
                    if (!accounts.get(tn).currency.equals(fromAcc.currency)) {
                        rejections.add("line " + lineNum + ": REJECT currency mismatch");
                        return;
                    }
                }
                int mu = currencies.get(fromAcc.currency);
                BigDecimal amount = round(parseAmount(parts[2]), mu);
                if (amount.signum() <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                BigDecimal newBalance = fromAcc.balance.subtract(amount);
                if (newBalance.compareTo(fromAcc.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                BigInteger A = amount.movePointRight(mu).toBigIntegerExact();
                BigInteger W = BigInteger.ZERO;
                for (BigInteger w : weights) W = W.add(w);

                int n = targetNames.size();
                BigInteger[] bases = new BigInteger[n];
                BigInteger[] rems = new BigInteger[n];
                BigInteger sumBase = BigInteger.ZERO;
                for (int i = 0; i < n; i++) {
                    BigInteger[] divRem = A.multiply(weights.get(i)).divideAndRemainder(W);
                    bases[i] = divRem[0];
                    rems[i] = divRem[1];
                    sumBase = sumBase.add(bases[i]);
                }
                BigInteger leftover = A.subtract(sumBase);

                Integer[] indices = new Integer[n];
                for (int i = 0; i < n; i++) indices[i] = i;
                Arrays.sort(indices, (a, b) -> {
                    int cmp = rems[b].compareTo(rems[a]);
                    if (cmp != 0) return cmp;
                    return Integer.compare(a, b);
                });

                for (int i = 0; i < leftover.intValue(); i++) {
                    bases[indices[i]] = bases[indices[i]].add(BigInteger.ONE);
                }

                fromAcc.balance = newBalance;
                for (int i = 0; i < n; i++) {
                    BigDecimal share = new BigDecimal(bases[i]).movePointLeft(mu);
                    Account tAcc = accounts.get(targetNames.get(i));
                    tAcc.balance = tAcc.balance.add(share);
                }
                break;
            }
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".bmp"));
        if (files == null) return;
        Arrays.sort(files, (a, b) -> {
            byte[] an = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getName().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        for (File f : files) {
            processFile(f);
        }
    }

    static int readU16(byte[] data, int off) {
        return (data[off] & 0xFF) | ((data[off + 1] & 0xFF) << 8);
    }

    static int readU32(byte[] data, int off) {
        return (data[off] & 0xFF) | ((data[off + 1] & 0xFF) << 8) |
               ((data[off + 2] & 0xFF) << 16) | ((data[off + 3] & 0xFF) << 24);
    }

    static int extractChannel(int pixel, int mask) {
        if (mask == 0) return 0;
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        int v = (pixel & mask) >>> s;
        int m = (1 << n) - 1;
        return (v * 255 + m / 2) / m;
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        System.out.println("== " + f.getName());

        if (data.length < 14) return;
        if (data[0] != 'B' || data[1] != 'M') return;

        int bfOffBits = readU32(data, 10);
        int dibSize = readU32(data, 14);
        int width = readU32(data, 18);
        int height = readU32(data, 22);
        int bpp = readU16(data, 28);
        int compression = readU32(data, 30);

        boolean bottomUp = height > 0;
        int absHeight = Math.abs(height);

        if (compression != 0 && compression != 3) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }
        if (compression == 3 && bpp != 32) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }

        int redMask = 0, greenMask = 0, blueMask = 0;
        if (compression == 3) {
            redMask = readU32(data, 54);
            greenMask = readU32(data, 58);
            blueMask = readU32(data, 62);
        }

        int[] paletteR = null, paletteG = null, paletteB = null;
        if (bpp == 1 || bpp == 4 || bpp == 8) {
            int colorsUsed = readU32(data, 38);
            int numColors = (colorsUsed == 0) ? (1 << bpp) : colorsUsed;
            int tableOffset = 14 + dibSize;
            paletteR = new int[numColors];
            paletteG = new int[numColors];
            paletteB = new int[numColors];
            for (int i = 0; i < numColors; i++) {
                int off = tableOffset + i * 4;
                paletteB[i] = data[off] & 0xFF;
                paletteG[i] = data[off + 1] & 0xFF;
                paletteR[i] = data[off + 2] & 0xFF;
            }
        }

        int rowSize = ((width * bpp + 31) / 32) * 4;

        boolean[][] ink = new boolean[absHeight][width];
        int inkCount = 0;

        for (int y = 0; y < absHeight; y++) {
            int storedY = bottomUp ? (absHeight - 1 - y) : y;
            int rowOffset = bfOffBits + storedY * rowSize;

            for (int x = 0; x < width; x++) {
                int r, g, b;

                if (bpp == 1) {
                    int byteIdx = x / 8;
                    int bitIdx = 7 - (x % 8);
                    int idx = (data[rowOffset + byteIdx] >> bitIdx) & 1;
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 4) {
                    int byteIdx = x / 2;
                    int bitIdx = (x % 2 == 0) ? 4 : 0;
                    int idx = (data[rowOffset + byteIdx] >> bitIdx) & 0xF;
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 8) {
                    int idx = data[rowOffset + x] & 0xFF;
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 24) {
                    int off = rowOffset + x * 3;
                    b = data[off] & 0xFF;
                    g = data[off + 1] & 0xFF;
                    r = data[off + 2] & 0xFF;
                } else if (bpp == 32) {
                    int off = rowOffset + x * 4;
                    int pixel = readU32(data, off);
                    if (compression == 0) {
                        b = pixel & 0xFF;
                        g = (pixel >> 8) & 0xFF;
                        r = (pixel >> 16) & 0xFF;
                    } else {
                        r = extractChannel(pixel, redMask);
                        g = extractChannel(pixel, greenMask);
                        b = extractChannel(pixel, blueMask);
                    }
                } else {
                    r = g = b = 0;
                }

                int lum = (299 * r + 587 * g + 114 * b) / 1000;
                if (lum < 128) {
                    ink[y][x] = true;
                    inkCount++;
                }
            }
        }

        System.out.println("size " + width + "x" + absHeight + " bpp " + bpp +
            " header " + dibSize + " " + (bottomUp ? "bottom-up" : "top-down") +
            " ink " + inkCount);

        boolean[][] visited = new boolean[absHeight][width];
        List<Component> components = new ArrayList<>();

        int[] dx = {-1, 0, 1, -1, 0, 1, -1, 0, 1};
        int[] dy = {-1, -1, -1, 0, 0, 0, 1, 1, 1};

        for (int y = 0; y < absHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (ink[y][x] && !visited[y][x]) {
                    Component comp = new Component();
                    comp.firstX = x;
                    comp.firstY = y;
                    comp.minX = x; comp.maxX = x;
                    comp.minY = y; comp.maxY = y;
                    comp.count = 0;

                    Queue<int[]> queue = new LinkedList<>();
                    queue.add(new int[]{x, y});
                    visited[y][x] = true;

                    while (!queue.isEmpty()) {
                        int[] p = queue.poll();
                        int px = p[0], py = p[1];
                        comp.count++;
                        if (px < comp.minX) comp.minX = px;
                        if (px > comp.maxX) comp.maxX = px;
                        if (py < comp.minY) comp.minY = py;
                        if (py > comp.maxY) comp.maxY = py;

                        for (int d = 0; d < 8; d++) {
                            int nx = px + dx[d], ny = py + dy[d];
                            if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight &&
                                ink[ny][nx] && !visited[ny][nx]) {
                                visited[ny][nx] = true;
                                queue.add(new int[]{nx, ny});
                            }
                        }
                    }

                    components.add(comp);
                }
            }
        }

        System.out.println("components " + components.size());
        for (Component c : components) {
            System.out.println(c.firstX + "," + c.firstY + " bbox " +
                c.minX + "," + c.minY + "-" + c.maxX + "," + c.maxY +
                " pixels " + c.count);
        }
    }

    static class Component {
        int firstX, firstY, minX, maxX, minY, maxY, count;
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".bmp"));
        if (files == null) return;
        Arrays.sort(files, (a, b) -> {
            byte[] an = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getName().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        for (File f : files) {
            processFile(f);
        }
    }

    static int readByte(byte[] data, int off) {
        if (off < 0 || off >= data.length) return 255;
        return data[off] & 0xFF;
    }

    static int readU16(byte[] data, int off) {
        return (data[off] & 0xFF) | ((data[off + 1] & 0xFF) << 8);
    }

    static int readU32(byte[] data, int off) {
        return (data[off] & 0xFF) | ((data[off + 1] & 0xFF) << 8) |
               ((data[off + 2] & 0xFF) << 16) | ((data[off + 3] & 0xFF) << 24);
    }

    static int extractChannel(int pixel, int mask) {
        if (mask == 0) return 0;
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        int v = (pixel & mask) >>> s;
        int m = (1 << n) - 1;
        return (v * 255 + m / 2) / m;
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        System.out.println("== " + f.getName());

        if (data.length < 14) return;
        if (data[0] != 'B' || data[1] != 'M') return;

        int bfOffBits = readU32(data, 10);
        int dibSize = readU32(data, 14);
        int width = readU32(data, 18);
        int height = readU32(data, 22);
        int bpp = readU16(data, 28);
        int compression = readU32(data, 30);

        boolean bottomUp = height > 0;
        int absHeight = Math.abs(height);

        if (compression != 0 && compression != 3) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }
        if (compression == 3 && bpp != 32) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }

        int redMask = 0, greenMask = 0, blueMask = 0;
        if (compression == 3) {
            if (dibSize == 40) {
                redMask = readU32(data, 54);
                greenMask = readU32(data, 58);
                blueMask = readU32(data, 62);
            } else {
                // 108 or 124 byte header: masks are at offsets 54, 58, 62 within the DIB header
                // DIB header starts at offset 14, so masks are at file offsets 14+40=54, 58, 62
                redMask = readU32(data, 54);
                greenMask = readU32(data, 58);
                blueMask = readU32(data, 62);
            }
        }

        int numColors = 0;
        int tableOffset = 14 + dibSize;
        int[] paletteR = null, paletteG = null, paletteB = null;

        if (bpp == 1 || bpp == 4 || bpp == 8) {
            int colorsUsed = readU32(data, 38);
            numColors = (colorsUsed == 0) ? (1 << bpp) : colorsUsed;
        }

        // If bfOffBits is 0, compute it
        if (bfOffBits == 0) {
            if (bpp == 1 || bpp == 4 || bpp == 8) {
                bfOffBits = tableOffset + numColors * 4;
            } else if (bpp == 32 && compression == 3 && dibSize == 40) {
                bfOffBits = 14 + 40 + 12;
            } else {
                bfOffBits = 14 + dibSize;
            }
        }

        if (bpp == 1 || bpp == 4 || bpp == 8) {
            // Limit palette entries to what fits before pixel data and within file
            int maxByPixel = (bfOffBits > tableOffset) ? (bfOffBits - tableOffset) / 4 : 0;
            int maxByFile = (data.length > tableOffset) ? (data.length - tableOffset) / 4 : 0;
            int actualNumColors = Math.min(numColors, Math.min(maxByPixel, maxByFile));
            actualNumColors = Math.max(0, actualNumColors);

            paletteR = new int[numColors];
            paletteG = new int[numColors];
            paletteB = new int[numColors];
            // Default to white (255,255,255) for entries we can't read
            Arrays.fill(paletteR, 255);
            Arrays.fill(paletteG, 255);
            Arrays.fill(paletteB, 255);

            for (int i = 0; i < actualNumColors; i++) {
                int off = tableOffset + i * 4;
                paletteB[i] = readByte(data, off);
                paletteG[i] = readByte(data, off + 1);
                paletteR[i] = readByte(data, off + 2);
            }
        }

        int rowSize = ((width * bpp + 31) / 32) * 4;

        boolean[][] ink = new boolean[absHeight][width];
        int inkCount = 0;

        for (int y = 0; y < absHeight; y++) {
            int storedY = bottomUp ? (absHeight - 1 - y) : y;
            int rowOffset = bfOffBits + storedY * rowSize;

            for (int x = 0; x < width; x++) {
                int r, g, b;

                if (bpp == 1) {
                    int byteIdx = x / 8;
                    int bitIdx = 7 - (x % 8);
                    int idx = (readByte(data, rowOffset + byteIdx) >> bitIdx) & 1;
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 4) {
                    int byteIdx = x / 2;
                    int bitIdx = (x % 2 == 0) ? 4 : 0;
                    int idx = (readByte(data, rowOffset + byteIdx) >> bitIdx) & 0xF;
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 8) {
                    int idx = readByte(data, rowOffset + x);
                    r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx];
                } else if (bpp == 24) {
                    int off = rowOffset + x * 3;
                    b = readByte(data, off);
                    g = readByte(data, off + 1);
                    r = readByte(data, off + 2);
                } else if (bpp == 32) {
                    int off = rowOffset + x * 4;
                    int pixel = (readByte(data, off)) |
                                (readByte(data, off + 1) << 8) |
                                (readByte(data, off + 2) << 16) |
                                (readByte(data, off + 3) << 24);
                    if (compression == 0) {
                        b = pixel & 0xFF;
                        g = (pixel >> 8) & 0xFF;
                        r = (pixel >> 16) & 0xFF;
                    } else {
                        r = extractChannel(pixel, redMask);
                        g = extractChannel(pixel, greenMask);
                        b = extractChannel(pixel, blueMask);
                    }
                } else {
                    r = g = b = 255;
                }

                int lum = (299 * r + 587 * g + 114 * b) / 1000;
                if (lum < 128) {
                    ink[y][x] = true;
                    inkCount++;
                }
            }
        }

        System.out.println("size " + width + "x" + absHeight + " bpp " + bpp +
            " header " + dibSize + " " + (bottomUp ? "bottom-up" : "top-down") +
            " ink " + inkCount);

        boolean[][] visited = new boolean[absHeight][width];
        List<Component> components = new ArrayList<>();

        int[] dx = {-1, 0, 1, -1, 0, 1, -1, 0, 1};
        int[] dy = {-1, -1, -1, 0, 0, 0, 1, 1, 1};

        for (int y = 0; y < absHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (ink[y][x] && !visited[y][x]) {
                    Component comp = new Component();
                    comp.firstX = x;
                    comp.firstY = y;
                    comp.minX = x; comp.maxX = x;
                    comp.minY = y; comp.maxY = y;
                    comp.count = 0;

                    Queue<int[]> queue = new LinkedList<>();
                    queue.add(new int[]{x, y});
                    visited[y][x] = true;

                    while (!queue.isEmpty()) {
                        int[] p = queue.poll();
                        int px = p[0], py = p[1];
                        comp.count++;
                        if (px < comp.minX) comp.minX = px;
                        if (px > comp.maxX) comp.maxX = px;
                        if (py < comp.minY) comp.minY = py;
                        if (py > comp.maxY) comp.maxY = py;

                        for (int d = 0; d < 8; d++) {
                            int nx = px + dx[d], ny = py + dy[d];
                            if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight &&
                                ink[ny][nx] && !visited[ny][nx]) {
                                visited[ny][nx] = true;
                                queue.add(new int[]{nx, ny});
                            }
                        }
                    }

                    components.add(comp);
                }
            }
        }

        System.out.println("components " + components.size());
        for (Component c : components) {
            System.out.println(c.firstX + "," + c.firstY + " bbox " +
                c.minX + "," + c.minY + "-" + c.maxX + "," + c.maxY +
                " pixels " + c.count);
        }
    }

    static class Component {
        int firstX, firstY, minX, maxX, minY, maxY, count;
    }
}

import * as fs from 'fs';
import * as path from 'path';

interface Decimal {
  value: bigint;
  scale: number;
}

function parseDecimal(s: string): Decimal {
  let negative = false;
  let i = 0;
  if (s[0] === '-') {
    negative = true;
    i = 1;
  }
  const dotIdx = s.indexOf('.', i);
  let intStr: string, decStr: string;
  if (dotIdx === -1) {
    intStr = s.slice(i);
    decStr = '';
  } else {
    intStr = s.slice(i, dotIdx);
    decStr = s.slice(dotIdx + 1);
  }
  if (intStr === '') intStr = '0';
  const digits = intStr + decStr;
  let value = BigInt(digits);
  if (negative) value = -value;
  return { value, scale: decStr.length };
}

function roundHalfEven(value: bigint, scale: number, targetScale: number): bigint {
  if (scale <= targetScale) {
    return value * (10n ** BigInt(targetScale - scale));
  }
  const divisor = 10n ** BigInt(scale - targetScale);
  const quotient = value / divisor;
  const remainder = value % divisor;
  const absRemainder = remainder < 0n ? -remainder : remainder;
  const half = divisor / 2n;

  if (absRemainder > half) {
    return value > 0n ? quotient + 1n : quotient - 1n;
  } else if (absRemainder < half) {
    return quotient;
  } else {
    if (quotient % 2n === 0n) {
      return quotient;
    } else {
      return value > 0n ? quotient + 1n : quotient - 1n;
    }
  }
}

function mulDecimal(a: Decimal, b: Decimal): Decimal {
  return { value: a.value * b.value, scale: a.scale + b.scale };
}

function formatMoney(value: bigint, minorUnits: number): string {
  if (value === 0n) {
    if (minorUnits === 0) return '0';
    return '0.' + '0'.repeat(minorUnits);
  }

  const negative = value < 0n;
  const abs = negative ? -value : value;
  const str = abs.toString();

  let padded: string;
  if (str.length <= minorUnits) {
    padded = '0'.repeat(minorUnits + 1 - str.length) + str;
  } else {
    padded = str;
  }

  const intPart = padded.slice(0, padded.length - minorUnits);
  const decPart = padded.slice(padded.length - minorUnits);

  let formatted = '';
  const len = intPart.length;
  for (let i = 0; i < len; i++) {
    if (i > 0 && (len - i) % 3 === 0) formatted += ',';
    formatted += intPart[i];
  }

  if (minorUnits > 0) {
    formatted += '.' + decPart;
  }

  return (negative ? '-' : '') + formatted;
}

const dir = process.argv[2];
const filePath = path.join(dir, 'ledger.txt');
const content = fs.readFileSync(filePath, 'utf-8');
const lines = content.split('\n');

const currencies = new Map<string, number>();

interface Account {
  currency: string;
  balance: bigint;
  limit: bigint;
}
const accounts = new Map<string, Account>();

const rejections: string[] = [];

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  const line = lines[lineNum];
  const trimmed = line.trim();

  if (trimmed === '' || trimmed[0] === '#') continue;

  const fields = trimmed.split(/\s+/);
  const cmd = fields[0];
  const displayLine = lineNum + 1;

  switch (cmd) {
    case 'currency': {
      const code = fields[1];
      const minorUnits = parseInt(fields[2]);
      currencies.set(code, minorUnits);
      break;
    }

    case 'open': {
      const name = fields[1];
      const code = fields[2];
      const limitStr = fields.length > 3 ? fields[3] : '0';

      if (accounts.has(name)) {
        rejections.push(`line ${displayLine}: REJECT account exists ${name}`);
        break;
      }

      const minorUnits = currencies.get(code)!;
      const limitDec = parseDecimal(limitStr);
      const limit = roundHalfEven(limitDec.value, limitDec.scale, minorUnits);

      accounts.set(name, { currency: code, balance: 0n, limit });
      break;
    }

    case 'deposit': {
      const name = fields[1];
      const amountStr = fields[2];

      if (!accounts.has(name)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${name}`);
        break;
      }

      const acct = accounts.get(name)!;
      const minorUnits = currencies.get(acct.currency)!;
      const amountDec = parseDecimal(amountStr);
      const amount = roundHalfEven(amountDec.value, amountDec.scale, minorUnits);

      if (amount <= 0n) {
        rejections.push(`line ${displayLine}: REJECT non-positive amount`);
        break;
      }

      acct.balance += amount;
      break;
    }

    case 'withdraw': {
      const name = fields[1];
      const amountStr = fields[2];

      if (!accounts.has(name)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${name}`);
        break;
      }

      const acct = accounts.get(name)!;
      const minorUnits = currencies.get(acct.currency)!;
      const amountDec = parseDecimal(amountStr);
      const amount = roundHalfEven(amountDec.value, amountDec.scale, minorUnits);

      if (amount <= 0n) {
        rejections.push(`line ${displayLine}: REJECT non-positive amount`);
        break;
      }

      if (acct.balance - amount < -acct.limit) {
        rejections.push(`line ${displayLine}: REJECT insufficient funds ${name}`);
        break;
      }

      acct.balance -= amount;
      break;
    }

    case 'transfer': {
      const fromName = fields[1];
      const toName = fields[2];
      const amountStr = fields[3];

      if (!accounts.has(fromName)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${fromName}`);
        break;
      }
      if (!accounts.has(toName)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${toName}`);
        break;
      }

      const from = accounts.get(fromName)!;
      const to = accounts.get(toName)!;

      if (from.currency !== to.currency) {
        rejections.push(`line ${displayLine}: REJECT currency mismatch`);
        break;
      }

      const minorUnits = currencies.get(from.currency)!;
      const amountDec = parseDecimal(amountStr);
      const amount = roundHalfEven(amountDec.value, amountDec.scale, minorUnits);

      if (amount <= 0n) {
        rejections.push(`line ${displayLine}: REJECT non-positive amount`);
        break;
      }

      if (from.balance - amount < -from.limit) {
        rejections.push(`line ${displayLine}: REJECT insufficient funds ${fromName}`);
        break;
      }

      from.balance -= amount;
      to.balance += amount;
      break;
    }

    case 'convert': {
      const fromName = fields[1];
      const toName = fields[2];
      const amountStr = fields[3];
      const rateStr = fields[4];

      if (!accounts.has(fromName)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${fromName}`);
        break;
      }
      if (!accounts.has(toName)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${toName}`);
        break;
      }

      const from = accounts.get(fromName)!;
      const to = accounts.get(toName)!;

      const fromMinor = currencies.get(from.currency)!;
      const toMinor = currencies.get(to.currency)!;

      const amountDec = parseDecimal(amountStr);
      const amount = roundHalfEven(amountDec.value, amountDec.scale, fromMinor);

      if (amount <= 0n) {
        rejections.push(`line ${displayLine}: REJECT non-positive amount`);
        break;
      }

      if (from.balance - amount < -from.limit) {
        rejections.push(`line ${displayLine}: REJECT insufficient funds ${fromName}`);
        break;
      }

      const rateDec = parseDecimal(rateStr);
      const amountAsDec: Decimal = { value: amount, scale: fromMinor };
      const converted = mulDecimal(amountAsDec, rateDec);
      const convertedMinor = roundHalfEven(converted.value, converted.scale, toMinor);

      from.balance -= amount;
      to.balance += convertedMinor;
      break;
    }

    case 'interest': {
      const name = fields[1];
      const rateStr = fields[2];

      if (!accounts.has(name)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${name}`);
        break;
      }

      const acct = accounts.get(name)!;
      const minorUnits = currencies.get(acct.currency)!;
      const rateDec = parseDecimal(rateStr);

      const balanceDec: Decimal = { value: acct.balance, scale: minorUnits };
      const interest = mulDecimal(balanceDec, rateDec);
      const interestMinor = roundHalfEven(interest.value, interest.scale, minorUnits);

      acct.balance += interestMinor;
      break;
    }

    case 'split': {
      const fromName = fields[1];
      const amountStr = fields[2];
      const targetFields = fields.slice(3);

      const targetInfos: { name: string; weight: bigint }[] = [];
      for (const t of targetFields) {
        const colonIdx = t.indexOf(':');
        const name = t.slice(0, colonIdx);
        const weight = BigInt(t.slice(colonIdx + 1));
        targetInfos.push({ name, weight });
      }

      // Check unknown accounts in order: from, then targets
      let rejected = false;
      if (!accounts.has(fromName)) {
        rejections.push(`line ${displayLine}: REJECT unknown account ${fromName}`);
        rejected = true;
      }
      if (!rejected) {
        for (const t of targetInfos) {
          if (!accounts.has(t.name)) {
            rejections.push(`line ${displayLine}: REJECT unknown account ${t.name}`);
            rejected = true;
            break;
          }
        }
      }
      if (rejected) break;

      const from = accounts.get(fromName)!;
      const minorUnits = currencies.get(from.currency)!;

      // Check currency mismatch
      for (const t of targetInfos) {
        const tgt = accounts.get(t.name)!;
        if (tgt.currency !== from.currency) {
          rejections.push(`line ${displayLine}: REJECT currency mismatch`);
          rejected = true;
          break;
        }
      }
      if (rejected) break;

      const amountDec = parseDecimal(amountStr);
      const amount = roundHalfEven(amountDec.value, amountDec.scale, minorUnits);

      if (amount <= 0n) {
        rejections.push(`line ${displayLine}: REJECT non-positive amount`);
        break;
      }

      if (from.balance - amount < -from.limit) {
        rejections.push(`line ${displayLine}: REJECT insufficient funds ${fromName}`);
        break;
      }

      // Distribute amount among targets
      const W = targetInfos.reduce((s, t) => s + t.weight, 0n);
      const bases: bigint[] = [];
      const remainders: bigint[] = [];
      let totalBase = 0n;

      for (const t of targetInfos) {
        const product = amount * t.weight;
        const base = product / W;
        const rem = product % W;
        bases.push(base);
        remainders.push(rem);
        totalBase += base;
      }

      let leftover = amount - totalBase;

      const indices = targetInfos.map((_, i) => i);
      indices.sort((a, b) => {
        if (remainders[a] > remainders[b]) return -1;
        if (remainders[a] < remainders[b]) return 1;
        return a - b;
      });

      for (let i = 0; i < leftover && i < indices.length; i++) {
        bases[indices[i]] += 1n;
      }

      from.balance -= amount;
      for (let i = 0; i < targetInfos.length; i++) {
        const tgt = accounts.get(targetInfos[i].name)!;
        tgt.balance += bases[i];
      }
      break;
    }
  }
}

