import sys
import os
import struct
import socket
import random


def build_query(name, qtype_num, qid):
    header = struct.pack('!HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    qname = b''
    n = name
    if n.endswith('.'):
        n = n[:-1]
    if n:
        labels = n.split('.')
        for label in labels:
            qname += struct.pack('!B', len(label)) + label.encode('ascii')
    qname += b'\x00'
    qtype_class = struct.pack('!HH', qtype_num, 1)
    return header + qname + qtype_class


def parse_name(data, offset, visited=None):
    if visited is None:
        visited = set()
    labels = []
    while True:
        if offset >= len(data):
            break
        length = data[offset]
        if length & 0xC0 == 0xC0:
            if offset + 1 >= len(data):
                break
            pointer = struct.unpack('!H', data[offset:offset + 2])[0] & 0x3FFF
            if pointer in visited:
                break
            visited.add(pointer)
            sub_labels, _ = parse_name(data, pointer, visited)
            labels.extend(sub_labels)
            return labels, offset + 2
        elif length == 0:
            return labels, offset + 1
        else:
            offset += 1
            label = data[offset:offset + length]
            labels.append(label.decode('latin-1'))
            offset += length
    return labels, offset


def format_name(labels):
    if not labels:
        return '.'
    return '.'.join(l.lower() for l in labels)


def format_ipv4(data):
    return '.'.join(str(b) for b in data)


def format_ipv6(data):
    groups = []
    for i in range(8):
        groups.append(struct.unpack('!H', data[i * 2:i * 2 + 2])[0])

    best_start = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            run_len = j - i
            if run_len >= 2 and run_len > best_len:
                best_start = i
                best_len = run_len
            i = j
        else:
            i += 1

    parts = []
    i = 0
    while i < 8:
        if i == best_start:
            if i == 0:
                parts.append('')
            parts.append('')
            i += best_len
            if i >= 8:
                parts.append('')
            continue
        parts.append(format(groups[i], 'x'))
        i += 1

    return ':'.join(parts)


def format_txt_rdata(data):
    parts = []
    offset = 0
    while offset < len(data):
        length = data[offset]
        offset += 1
        string_bytes = data[offset:offset + length]
        offset += length
        s = '"'
        for b in string_bytes:
            if b == ord('"'):
                s += '\\"'
            elif b == ord('\\'):
                s += '\\\\'
            elif 0x20 <= b <= 0x7E:
                s += chr(b)
            else:
                s += '\\' + str(b).zfill(3)
        s += '"'
        parts.append(s)
    return ' '.join(parts)


RCODE_NAMES = {0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'}


def parse_response(data):
    if len(data) < 12:
        return None
    resp_id, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', data[:12])
    rcode = flags & 0x000F

    offset = 12
    for _ in range(qdcount):
        _, offset = parse_name(data, offset)
        offset += 4

    records = []
    for _ in range(ancount):
        owner_labels, offset = parse_name(data, offset)
        if offset + 10 > len(data):
            break
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', data[offset:offset + 10])
        offset += 10
        rdata_start = offset
        rdata = data[offset:offset + rdlength]
        offset += rdlength

        owner = format_name(owner_labels)

        if rtype == 1:
            type_name = 'A'
            data_str = format_ipv4(rdata)
        elif rtype == 28:
            type_name = 'AAAA'
            data_str = format_ipv6(rdata)
        elif rtype == 5:
            type_name = 'CNAME'
            target_labels, _ = parse_name(data, rdata_start)
            data_str = format_name(target_labels)
        elif rtype == 15:
            type_name = 'MX'
            preference = struct.unpack('!H', rdata[:2])[0]
            exchange_labels, _ = parse_name(data, rdata_start + 2)
            data_str = f"{preference} {format_name(exchange_labels)}"
        elif rtype == 16:
            type_name = 'TXT'
            data_str = format_txt_rdata(rdata)
        else:
            type_name = f'TYPE{rtype}'
            if rdlength == 0:
                data_str = '\\# 0'
            else:
                data_str = '\\# ' + str(rdlength) + ' ' + rdata.hex()

        records.append((owner, ttl, type_name, data_str))

    return rcode, records


def main():
    directory = sys.argv[1]
    port = int(sys.argv[2])

    queries_file = os.path.join(directory, 'queries.txt')
    with open(queries_file, 'r') as f:
        lines = f.readlines()

    TYPE_MAP = {'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5}

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = line.split(' ')
        name = parts[0]
        qtype_str = parts[1]
        qtype_num = TYPE_MAP[qtype_str]

        qid = random.randint(0, 65535)
        query = build_query(name, qtype_num, qid)

        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.sendto(query, ('127.0.0.1', port))

        while True:
            data, _ = sock.recvfrom(65535)
            if len(data) >= 12:
                resp_id = struct.unpack('!H', data[:2])[0]
                if resp_id == qid:
                    break
        sock.close()

        flags = struct.unpack('!H', data[2:4])[0]
        tc = (flags >> 9) & 1

        if tc:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect(('127.0.0.1', port))
            sock.sendall(struct.pack('!H', len(query)) + query)

            length_data = b''
            while len(length_data) < 2:
                chunk = sock.recv(2 - len(length_data))
                if not chunk:
                    break
                length_data += chunk

            msg_len = struct.unpack('!H', length_data)[0]

            msg_data = b''
            while len(msg_data) < msg_len:
                chunk = sock.recv(msg_len - len(msg_data))
                if not chunk:
                    break
                msg_data += chunk

            sock.close()
            data = msg_data

        result = parse_response(data)
        if result is None:
            continue

        rcode, records = result

        display_name = name.lower()
        if display_name.endswith('.') and display_name != '.':
            display_name = display_name[:-1]

        rcode_str = RCODE_NAMES.get(rcode, f'RCODE{rcode}')

        print(f"{display_name} {qtype_str} {rcode_str}")
        for owner, ttl, type_name, data_str in records:
            print(f"  {owner} {ttl} {type_name} {data_str}")


if __name__ == '__main__':
    main()

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        List<String[]> queries = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(Paths.get(dir, "queries.txt").toFile()))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;
                String[] parts = line.split(" ", 2);
                if (parts.length == 2) {
                    queries.add(new String[]{parts[0].trim(), parts[1].trim()});
                }
            }
        }

        for (String[] q : queries) {
            processQuery(q[0], q[1], port);
        }
    }

    static void processQuery(String name, String type, int port) throws Exception {
        int id = new Random().nextInt(65536);
        byte[] query = buildQuery(id, name, type);

        byte[] response = sendUdp(query, id, port);

        int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
        if ((flags & 0x0200) != 0) {
            response = sendTcp(query, id, port);
        }

        parseAndPrint(name, type, response);
    }

    static byte[] buildQuery(int id, String name, String type) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        bos.write((id >> 8) & 0xFF);
        bos.write(id & 0xFF);
        bos.write(0x01);
        bos.write(0x00);
        bos.write(0x00); bos.write(0x01);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);

        String qname = name;
        if (qname.endsWith(".")) {
            qname = qname.substring(0, qname.length() - 1);
        }
        if (!qname.isEmpty()) {
            String[] labels = qname.split("\\.");
            for (String label : labels) {
                byte[] lb = label.getBytes(StandardCharsets.US_ASCII);
                bos.write(lb.length);
                bos.writeBytes(lb);
            }
        }
        bos.write(0);

        int qtype = typeToCode(type);
        bos.write((qtype >> 8) & 0xFF);
        bos.write(qtype & 0xFF);
        bos.write(0x00);
        bos.write(0x01);

        return bos.toByteArray();
    }

    static int typeToCode(String type) {
        return switch (type.toUpperCase()) {
            case "A" -> 1;
            case "AAAA" -> 28;
            case "CNAME" -> 5;
            case "MX" -> 15;
            case "TXT" -> 16;
            default -> throw new IllegalArgumentException("Unknown type: " + type);
        };
    }

    static byte[] sendUdp(byte[] query, int id, int port) throws Exception {
        DatagramSocket socket = new DatagramSocket();
        socket.setSoTimeout(5000);
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        DatagramPacket send = new DatagramPacket(query, query.length, addr, port);
        socket.send(send);

        byte[] buf = new byte[65535];
        while (true) {
            DatagramPacket recv = new DatagramPacket(buf, buf.length);
            socket.receive(recv);
            byte[] data = Arrays.copyOf(recv.getData(), recv.getLength());
            if (data.length >= 12) {
                int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
                int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
                int qr = (flags >> 15) & 1;
                if (qr == 1 && respId == id) {
                    socket.close();
                    return data;
                }
            }
        }
    }

    static byte[] sendTcp(byte[] query, int id, int port) throws Exception {
        Socket socket = new Socket("127.0.0.1", port);
        socket.setSoTimeout(5000);

        DataOutputStream dos = new DataOutputStream(socket.getOutputStream());
        dos.writeShort(query.length);
        dos.write(query);
        dos.flush();

        DataInputStream dis = new DataInputStream(socket.getInputStream());
        int len = dis.readUnsignedShort();
        byte[] response = new byte[len];
        dis.readFully(response);

        socket.close();
        return response;
    }

    static void parseAndPrint(String name, String type, byte[] msg) {
        int flags = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
        int rcode = flags & 0x0F;
        int qdcount = ((msg[4] & 0xFF) << 8) | (msg[5] & 0xFF);
        int ancount = ((msg[6] & 0xFF) << 8) | (msg[7] & 0xFF);

        String rcodeStr = rcodeToString(rcode);

        String lowerName = name.toLowerCase();
        if (lowerName.endsWith(".")) lowerName = lowerName.substring(0, lowerName.length() - 1);
        System.out.println(lowerName + " " + type + " " + rcodeStr);

        int offset = 12;
        for (int i = 0; i < qdcount; i++) {
            offset = skipName(msg, offset);
            offset += 4;
        }

        for (int i = 0; i < ancount; i++) {
            String owner = readName(msg, offset);
            offset = skipName(msg, offset);

            int rtype = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
            long ttl = ((long)(msg[offset + 4] & 0xFF) << 24) | ((msg[offset + 5] & 0xFF) << 16)
                     | ((msg[offset + 6] & 0xFF) << 8) | (msg[offset + 7] & 0xFF);
            int rdlength = ((msg[offset + 8] & 0xFF) << 8) | (msg[offset + 9] & 0xFF);
            offset += 10;

            int rdataStart = offset;
            String rdata = parseRdata(msg, rdataStart, rdlength, rtype);
            offset += rdlength;

            String typeName = typeCodeToName(rtype);
            System.out.println("  " + owner + " " + ttl + " " + typeName + " " + rdata);
        }
    }

    static String rcodeToString(int rcode) {
        return switch (rcode) {
            case 0 -> "NOERROR";
            case 1 -> "FORMERR";
            case 2 -> "SERVFAIL";
            case 3 -> "NXDOMAIN";
            case 4 -> "NOTIMP";
            case 5 -> "REFUSED";
            default -> "RCODE" + rcode;
        };
    }

    static String typeCodeToName(int code) {
        return switch (code) {
            case 1 -> "A";
            case 5 -> "CNAME";
            case 15 -> "MX";
            case 16 -> "TXT";
            case 28 -> "AAAA";
            default -> "TYPE" + code;
        };
    }

    static int skipName(byte[] msg, int offset) {
        while (true) {
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                offset++;
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                offset += 2;
                break;
            }
            offset += 1 + len;
        }
        return offset;
    }

    static String readName(byte[] msg, int offset) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        int safety = 0;
        while (true) {
            if (++safety > 128) break;
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                int ptr = ((len & 0x3F) << 8) | (msg[offset + 1] & 0xFF);
                String rest = readName(msg, ptr);
                if (!rest.equals(".")) {
                    if (!first) sb.append('.');
                    sb.append(rest);
                }
                break;
            }
            if (!first) sb.append('.');
            sb.append(new String(msg, offset + 1, len, StandardCharsets.US_ASCII).toLowerCase());
            first = false;
            offset += 1 + len;
        }
        if (sb.length() == 0) return ".";
        return sb.toString();
    }

    static String parseRdata(byte[] msg, int offset, int rdlength, int rtype) {
        return switch (rtype) {
            case 1 -> parseA(msg, offset);
            case 28 -> parseAAAA(msg, offset);
            case 5 -> readName(msg, offset);
            case 15 -> parseMX(msg, offset);
            case 16 -> parseTXT(msg, offset, rdlength);
            default -> parseUnknown(msg, offset, rdlength);
        };
    }

    static String parseA(byte[] msg, int offset) {
        return (msg[offset] & 0xFF) + "." + (msg[offset + 1] & 0xFF) + "."
             + (msg[offset + 2] & 0xFF) + "." + (msg[offset + 3] & 0xFF);
    }

    static String parseAAAA(byte[] msg, int offset) {
        int[] groups = new int[8];
        for (int i = 0; i < 8; i++) {
            groups[i] = ((msg[offset + i * 2] & 0xFF) << 8) | (msg[offset + i * 2 + 1] & 0xFF);
        }

        int bestStart = -1, bestLen = 0;
        int curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (groups[i] == 0) {
                if (curStart == -1) { curStart = i; curLen = 1; }
                else curLen++;
            } else {
                if (curLen >= 2 && curLen > bestLen) {
                    bestStart = curStart; bestLen = curLen;
                }
                curStart = -1; curLen = 0;
            }
        }
        if (curLen >= 2 && curLen > bestLen) {
            bestStart = curStart; bestLen = curLen;
        }

        StringBuilder sb = new StringBuilder();
        if (bestStart == -1) {
            for (int i = 0; i < 8; i++) {
                if (i > 0) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
        } else {
            for (int i = 0; i < bestStart; i++) {
                if (i > 0) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
            sb.append("::");
            for (int i = bestStart + bestLen; i < 8; i++) {
                if (i > bestStart + bestLen) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
        }
        return sb.toString();
    }

    static String parseMX(byte[] msg, int offset) {
        int preference = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
        String exchange = readName(msg, offset + 2);
        return preference + " " + exchange;
    }

    static String parseTXT(byte[] msg, int offset, int rdlength) {
        StringBuilder sb = new StringBuilder();
        int end = offset + rdlength;
        int pos = offset;
        boolean first = true;
        while (pos < end) {
            int strLen = msg[pos] & 0xFF;
            pos++;
            if (!first) sb.append(' ');
            first = false;
            sb.append('"');
            for (int i = 0; i < strLen; i++) {
                int b = msg[pos + i] & 0xFF;
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b));
            }
            sb.append('"');
            pos += strLen;
        }
        return sb.toString();
    }

    static String parseUnknown(byte[] msg, int offset, int len) {
        StringBuilder sb = new StringBuilder();
        sb.append("\\# ").append(len);
        if (len > 0) {
            sb.append(' ');
            for (int i = 0; i < len; i++) {
                sb.append(String.format("%02x", msg[offset + i] & 0xFF));
            }
        }
        return sb.toString();
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as dgram from 'dgram';
import * as net from 'net';

const typeMap: Record<string, number> = {
  'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5
};

const rcodeNames: Record<number, string> = {
  0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'
};

function buildQuery(name: string, type: number): { buf: Buffer; id: number } {
  const id = Math.floor(Math.random() * 65536);
  const parts: number[] = [];

  parts.push((id >> 8) & 0xFF, id & 0xFF);
  parts.push(0x01, 0x00);
  parts.push(0x00, 0x01);
  parts.push(0x00, 0x00);
  parts.push(0x00, 0x00);
  parts.push(0x00, 0x00);

  const cleanName = name.replace(/\.$/, '');
  if (cleanName.length > 0) {
    const labels = cleanName.split('.');
    for (const label of labels) {
      parts.push(label.length);
      for (let i = 0; i < label.length; i++) {
        parts.push(label.charCodeAt(i) & 0xFF);
      }
    }
  }
  parts.push(0x00);

  parts.push((type >> 8) & 0xFF, type & 0xFF);
  parts.push(0x00, 0x01);

  return { buf: Buffer.from(parts), id };
}

function parseName(buf: Buffer, offset: number): { name: string; newOffset: number } {
  const labels: string[] = [];
  let currentOffset = offset;
  let jumped = false;
  let returnOffset = offset;

  while (currentOffset < buf.length) {
    const len = buf[currentOffset];
    if ((len & 0xC0) === 0xC0) {
      if (currentOffset + 1 >= buf.length) break;
      if (!jumped) {
        returnOffset = currentOffset + 2;
      }
      const ptr = ((len & 0x3F) << 8) | buf[currentOffset + 1];
      currentOffset = ptr;
      jumped = true;
    } else if (len === 0) {
      if (!jumped) {
        returnOffset = currentOffset + 1;
      }
      break;
    } else {
      const label = buf.slice(currentOffset + 1, currentOffset + 1 + len).toString('ascii');
      labels.push(label.toLowerCase());
      currentOffset += 1 + len;
      if (!jumped) {
        returnOffset = currentOffset;
      }
    }
  }

  const name = labels.length === 0 ? '.' : labels.join('.');
  return { name, newOffset: returnOffset };
}

function formatIPv6(buf: Buffer): string {
  const groups: number[] = [];
  for (let i = 0; i < 8; i++) {
    groups.push((buf[i * 2] << 8) | buf[i * 2 + 1]);
  }

  let bestStart = -1, bestLen = 0;
  let curStart = -1, curLen = 0;
  for (let i = 0; i < 8; i++) {
    if (groups[i] === 0) {
      if (curStart === -1) { curStart = i; curLen = 1; }
      else { curLen++; }
    } else {
      if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }
      curStart = -1; curLen = 0;
    }
  }
  if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }

  if (bestLen < 2) {
    return groups.map(g => g.toString(16)).join(':');
  }

  const before = groups.slice(0, bestStart).map(g => g.toString(16)).join(':');
  const after = groups.slice(bestStart + bestLen).map(g => g.toString(16)).join(':');

  if (bestStart === 0) {
    return '::' + after;
  } else if (bestStart + bestLen === 8) {
    return before + '::';
  } else {
    return before + '::' + after;
  }
}

function escapeTxtString(buf: Buffer): string {
  let result = '"';
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    if (b === 0x22) {
      result += '\\"';
    } else if (b === 0x5C) {
      result += '\\\\';
    } else if (b >= 0x20 && b <= 0x7E) {
      result += String.fromCharCode(b);
    } else {
      result += '\\' + b.toString(10).padStart(3, '0');
    }
  }
  result += '"';
  return result;
}

function sendUDP(query: Buffer, id: number, port: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = dgram.createSocket('udp4');

    const onData = (msg: Buffer) => {
      if (msg.length < 12) return;
      const msgId = (msg[0] << 8) | msg[1];
      const flags = (msg[2] << 8) | msg[3];
      const qr = (flags >> 15) & 1;
      if (qr === 1 && msgId === id) {
        socket.removeListener('message', onData);
        socket.close();
        resolve(msg);
      }
    };

    socket.on('message', onData);
    socket.on('error', (err) => { socket.close(); reject(err); });

    socket.send(query, port, '127.0.0.1', (err) => {
      if (err) { socket.close(); reject(err); }
    });
  });
}

function sendTCP(query: Buffer, id: number, port: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = net.connect(port, '127.0.0.1');
    let data = Buffer.alloc(0);
    let expectedLen = -1;

    socket.on('connect', () => {
      const lenBuf = Buffer.alloc(2);
      lenBuf.writeUInt16BE(query.length);
      socket.write(Buffer.concat([lenBuf, query]));
    });

    socket.on('data', (chunk) => {
      data = Buffer.concat([data, chunk]);
      if (expectedLen === -1 && data.length >= 2) {
        expectedLen = data.readUInt16BE(0);
      }
      if (expectedLen !== -1 && data.length >= 2 + expectedLen) {
        const msg = data.slice(2, 2 + expectedLen);
        socket.destroy();
        resolve(msg);
      }
    });

    socket.on('error', (err) => { socket.destroy(); reject(err); });
  });
}

function parseAndPrint(response: Buffer, queryName: string, queryType: string) {
  const flags = (response[2] << 8) | response[3];
  const rcode = flags & 0x0F;
  const qdcount = (response[4] << 8) | response[5];
  const ancount = (response[6] << 8) | response[7];

  const cleanName = queryName.replace(/\.$/, '').toLowerCase();
  const rcodeStr = rcodeNames[rcode] !== undefined ? rcodeNames[rcode] : `RCODE${rcode}`;
  console.log(`${cleanName} ${queryType} ${rcodeStr}`);

  let offset = 12;
  for (let i = 0; i < qdcount; i++) {
    while (offset < response.length) {
      const len = response[offset];
      if ((len & 0xC0) === 0xC0) {
        offset += 2;
        break;
      } else if (len === 0) {
        offset += 1;
        break;
      } else {
        offset += 1 + len;
      }
    }
    offset += 4;
  }

  for (let i = 0; i < ancount; i++) {
    const ownerResult = parseName(response, offset);
    const owner = ownerResult.name;
    offset = ownerResult.newOffset;

    const rtype = (response[offset] << 8) | response[offset + 1];
    offset += 2;
    offset += 2; // CLASS
    const ttl = response.readUInt32BE(offset);
    offset += 4;
    const rdlength = (response[offset] << 8) | response[offset + 1];
    offset += 2;

    const rdataStart = offset;
    const rdataEnd = offset + rdlength;

    let typeName: string;
    let dataStr: string;

    if (rtype === 1) {
      typeName = 'A';
      dataStr = `${response[rdataStart]}.${response[rdataStart + 1]}.${response[rdataStart + 2]}.${response[rdataStart + 3]}`;
    } else if (rtype === 28) {
      typeName = 'AAAA';
      dataStr = formatIPv6(response.slice(rdataStart, rdataEnd));
    } else if (rtype === 5) {
      typeName = 'CNAME';
      dataStr = parseName(response, rdataStart).name;
    } else if (rtype === 15) {
      typeName = 'MX';
      const pref = (response[rdataStart] << 8) | response[rdataStart + 1];
      const exchange = parseName(response, rdataStart + 2).name;
      dataStr = `${pref} ${exchange}`;
    } else if (rtype === 16) {
      typeName = 'TXT';
      const txtParts: string[] = [];
      let pos = rdataStart;
      while (pos < rdataEnd) {
        const strLen = response[pos];
        pos += 1;
        const strBuf = response.slice(pos, pos + strLen);
        pos += strLen;
        txtParts.push(escapeTxtString(strBuf));
      }
      dataStr = txtParts.join(' ');
    } else {
      typeName = `TYPE${rtype}`;
      if (rdlength === 0) {
        dataStr = '\\# 0';
      } else {
        dataStr = `\\# ${rdlength} ${response.slice(rdataStart, rdataEnd).toString('hex')}`;
      }
    }

    console.log(`  ${owner} ${ttl} ${typeName} ${dataStr}`);
    offset = rdataEnd;
  }
}

async function main() {
  const dir = process.argv[2];
  const port = parseInt(process.argv[3]);

  const content = fs.readFileSync(path.join(dir, 'queries.txt'), 'utf-8');
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === '') continue;

    const spaceIdx = trimmed.indexOf(' ');
    const name = trimmed.substring(0, spaceIdx);
    const typeStr = trimmed.substring(spaceIdx + 1).trim();
    const qtype = typeMap[typeStr.toUpperCase()];

    const { buf, id } = buildQuery(name, qtype);

    let response = await sendUDP(buf, id, port);

    const respFlags = (response[2] << 8) | response[3];
    const tc = (respFlags >> 9) & 1;

    if (tc) {
      response = await sendTCP(buf, id, port);
    }

    parseAndPrint(response, name, typeStr);
  }
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

import Foundation
import Darwin

func toBE16(_ v: UInt16) -> [UInt8] {
    return [UInt8(v >> 8), UInt8(v & 0xFF)]
}

func parseName(_ data: [UInt8], _ offset: Int) -> (name: String, nextOffset: Int) {
    var labels: [String] = []
    var pos = offset
    var nextOffset = offset
    var jumped = false
    var safety = 0

    while pos < data.count {
        safety += 1
        if safety > 128 { break }

        let len = Int(data[pos])
        if (len & 0xC0) == 0xC0 {
            if pos + 1 >= data.count { break }
            if !jumped {
                nextOffset = pos + 2
            }
            let ptr = ((len & 0x3F) << 8) | Int(data[pos + 1])
            pos = ptr
            jumped = true
        } else if len == 0 {
            if !jumped {
                nextOffset = pos + 1
            }
            break
        } else {
            if pos + 1 + len > data.count { break }
            let label = String(bytes: data[pos + 1 ..< pos + 1 + len], encoding: .ascii) ?? ""
            labels.append(label)
            pos += 1 + len
            if !jumped {
                nextOffset = pos
            }
        }
    }

    if labels.isEmpty {
        return (".", nextOffset)
    }
    return (labels.joined(separator: ".").lowercased(), nextOffset)
}

func buildQName(_ name: String) -> [UInt8] {
    var result: [UInt8] = []
    var n = name
    if n.hasSuffix(".") {
        n = String(n.dropLast())
    }
    if n.isEmpty {
        result.append(0)
        return result
    }
    let labels = n.components(separatedBy: ".")
    for label in labels {
        result.append(UInt8(label.count))
        result.append(contentsOf: Array(label.utf8))
    }
    result.append(0)
    return result
}

func typeNumber(_ typeStr: String) -> UInt16 {
    switch typeStr {
    case "A": return 1
    case "CNAME": return 5
    case "MX": return 15
    case "TXT": return 16
    case "AAAA": return 28
    default: return 0
    }
}

func typeName(_ type: UInt16) -> String {
    switch type {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(type)"
    }
}

func formatA(_ bytes: [UInt8]) -> String {
    return "\(bytes[0]).\(bytes[1]).\(bytes[2]).\(bytes[3])"
}

func formatAAAA(_ bytes: [UInt8]) -> String {
    var groups: [String] = []
    for i in 0..<8 {
        let hi = UInt16(bytes[i * 2]) << 8 | UInt16(bytes[i * 2 + 1])
        groups.append(String(format: "%x", hi))
    }

    var bestStart = -1
    var bestLen = 0
    var i = 0
    while i < 8 {
        if groups[i] == "0" {
            var j = i
            while j < 8 && groups[j] == "0" { j += 1 }
            let runLen = j - i
            if runLen >= 2 && runLen > bestLen {
                bestStart = i
                bestLen = runLen
            }
            i = j
        } else {
            i += 1
        }
    }

    if bestStart == -1 {
        return groups.joined(separator: ":")
    }

    var result = ""
    if bestStart > 0 {
        result = groups[0..<bestStart].joined(separator: ":")
    }
    result += "::"
    if bestStart + bestLen < 8 {
        result += groups[(bestStart + bestLen)...].joined(separator: ":")
    }
    return result
}

func escapeTXT(_ bytes: [UInt8]) -> String {
    var result = "\""
    for b in bytes {
        if b == 0x22 {
            result += "\\\""
        } else if b == 0x5C {
            result += "\\\\"
        } else if b >= 0x20 && b <= 0x7E {
            result += String(UnicodeScalar(b))
        } else {
            result += "\\\(String(format: "%03d", b))"
        }
    }
    result += "\""
    return result
}

func makeAddr(_ port: UInt16) -> sockaddr_in {
    var addr = sockaddr_in()
    addr.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr = in_addr(s_addr: inet_addr("127.0.0.1"))
    return addr
}

func udpExchange(_ query: [UInt8], _ id: UInt16, _ port: UInt16) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    if fd < 0 { return nil }
    defer { close(fd) }

    var addr = makeAddr(port)
    let sent = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            sendto(fd, query, query.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if sent < 0 { return nil }

    var buf = [UInt8](repeating: 0, count: 65535)
    while true {
        let n = recvfrom(fd, &buf, buf.count, 0, nil, nil)
        if n < 12 { continue }
        let respId = UInt16(buf[0]) << 8 | UInt16(buf[1])
        let flags = UInt16(buf[2]) << 8 | UInt16(buf[3])
        let qr = (flags >> 15) & 1
        if qr == 1 && respId == id {
            return Array(buf[0..<n])
        }
    }
}

func tcpExchange(_ query: [UInt8], _ port: UInt16) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0 { return nil }
    defer { close(fd) }

    var addr = makeAddr(port)
    let connected = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if connected < 0 { return nil }

    var toSend = toBE16(UInt16(query.count))
    toSend.append(contentsOf: query)
    let sent = send(fd, toSend, toSend.count, 0)
    if sent < 0 { return nil }

    var lenBuf = [UInt8](repeating: 0, count: 2)
    var totalRead = 0
    while totalRead < 2 {
        let n = read(fd, &lenBuf[totalRead], 2 - totalRead)
        if n <= 0 { return nil }
        totalRead += n
    }
    let msgLen = Int(UInt16(lenBuf[0]) << 8 | UInt16(lenBuf[1]))

    var msgBuf = [UInt8](repeating: 0, count: msgLen)
    totalRead = 0
    while totalRead < msgLen {
        let n = read(fd, &msgBuf[totalRead], msgLen - totalRead)
        if n <= 0 { return nil }
        totalRead += n
    }
    return msgBuf
}

func parseResponse(_ data: [UInt8]) -> (rcode: Int, records: [String]) {
    guard data.count >= 12 else { return (0, []) }

    let flags = UInt16(data[2]) << 8 | UInt16(data[3])
    let rcode = Int(flags & 0x000F)
    let qdcount = Int(UInt16(data[4]) << 8 | UInt16(data[5]))
    let ancount = Int(UInt16(data[6]) << 8 | UInt16(data[7]))

    var pos = 12

    for _ in 0..<qdcount {
        let (_, nextPos) = parseName(data, pos)
        pos = nextPos
        pos += 4
    }

    var records: [String] = []

    for _ in 0..<ancount {
        let (owner, nextPos) = parseName(data, pos)
        pos = nextPos

        if pos + 10 > data.count { break }
        let rtype = UInt16(data[pos]) << 8 | UInt16(data[pos + 1])
        let ttl = UInt32(data[pos + 4]) << 24 | UInt32(data[pos + 5]) << 16 | UInt32(data[pos + 6]) << 8 | UInt32(data[pos + 7])
        let rdlength = Int(UInt16(data[pos + 8]) << 8 | UInt16(data[pos + 9]))
        pos += 10

        let rdataStart = pos
        pos += rdlength

        let typeStr = typeName(rtype)
        var dataStr = ""

        switch rtype {
        case 1:
            if rdlength >= 4 {
                dataStr = formatA(Array(data[rdataStart..<rdataStart + 4]))
            }
        case 28:
            if rdlength >= 16 {
                dataStr = formatAAAA(Array(data[rdataStart..<rdataStart + 16]))
            }
        case 5:
            let (target, _) = parseName(data, rdataStart)
            dataStr = target
        case 15:
            if rdlength >= 3 {
                let pref = Int(UInt16(data[rdataStart]) << 8 | UInt16(data[rdataStart + 1]))
                let (exchange, _) = parseName(data, rdataStart + 2)
                dataStr = "\(pref) \(exchange)"
            }
        case 16:
            var txtPos = rdataStart
            let txtEnd = rdataStart + rdlength
            var strings: [String] = []
            while txtPos < txtEnd {
                let strLen = Int(data[txtPos])
                txtPos += 1
                if txtPos + strLen > txtEnd { break }
                let strBytes = Array(data[txtPos..<txtPos + strLen])
                txtPos += strLen
                strings.append(escapeTXT(strBytes))
            }
            dataStr = strings.joined(separator: " ")
        default:
            let rdata = Array(data[rdataStart..<rdataStart + rdlength])
            if rdata.isEmpty {
                dataStr = "\\# 0"
            } else {
                let hex = rdata.map { String(format: "%02x", $0) }.joined()
                dataStr = "\\# \(rdata.count) \(hex)"
            }
        }

        records.append("\(owner) \(ttl) \(typeStr) \(dataStr)")
    }

    return (rcode, records)
}

func resolveQuery(name: String, typeStr: String, port: UInt16) -> (rcode: Int, records: [String]) {
    let id = UInt16.random(in: 0...65535)

    var query: [UInt8] = []
    query.append(contentsOf: toBE16(id))
    query.append(contentsOf: toBE16(0x0100))
    query.append(contentsOf: toBE16(1))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: toBE16(0))
    query.append(contentsOf: buildQName(name))
    query.append(contentsOf: toBE16(typeNumber(typeStr)))
    query.append(contentsOf: toBE16(1))

    guard let response = udpExchange(query, id, port) else {
        return (0, [])
    }

    if response.count >= 4 {
        let flags = UInt16(response[2]) << 8 | UInt16(response[3])
        let tc = (flags >> 9) & 1
        if tc == 1 {
            if let tcpResponse = tcpExchange(query, port) {
                return parseResponse(tcpResponse)
            }
        }
    }

    return parseResponse(response)
}

let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dir = args[1]
let port = UInt16(args[2])!

let queriesPath = dir + "/queries.txt"
let content = (try? String(contentsOfFile: queriesPath, encoding: .utf8)) ?? ""
let lines = content.components(separatedBy: "\n")

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    let parts = trimmed.split(separator: " ", omittingEmptySubsequences: true)
    guard parts.count >= 2 else { continue }
    let name = String(parts[0])
    let qtype = String(parts[1])

    let (rcode, records) = resolveQuery(name: name, typeStr: qtype, port: port)

    var lowerName = name.lowercased()
    if lowerName.hasSuffix(".") {
        lowerName = String(lowerName.dropLast())
    }
    if lowerName.isEmpty {
        lowerName = "."
    }

    let rcodeStr: String
    switch rcode {
    case 0: rcodeStr = "NOERROR"
    case 1: rcodeStr = "FORMERR"
    case 2: rcodeStr = "SERVFAIL"
    case 3: rcodeStr = "NXDOMAIN"
    case 4: rcodeStr = "NOTIMP"
    case 5: rcodeStr = "REFUSED"
    default: rcodeStr = "RCODE\(rcode)"
    }

    print("\(lowerName) \(qtype) \(rcodeStr)")
    for rec in records {
        print("  \(rec)")
    }
}

exit(0)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <stdint.h>

static uint16_t get_u16(const uint8_t *p) {
    return (uint16_t)((p[0] << 8) | p[1]);
}

static uint32_t get_u32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static void put_u16(uint8_t *p, uint16_t v) {
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)(v & 0xFF);
}

static const uint8_t *read_name(const uint8_t *msg, int msglen, const uint8_t *ptr,
                                 char *buf, int bufsize) {
    int pos = 0;
    int jumped = 0;
    const uint8_t *next = NULL;
    int guard = 0;

    while (1) {
        if (guard++ > 200) return NULL;
        if (ptr - msg >= msglen) return NULL;

        uint8_t len = *ptr;

        if ((len & 0xC0) == 0xC0) {
            if (ptr - msg + 1 >= msglen) return NULL;
            if (!jumped) {
                next = ptr + 2;
                jumped = 1;
            }
            int offset = ((len & 0x3F) << 8) | ptr[1];
            if (offset >= msglen) return NULL;
            ptr = msg + offset;
        } else if (len == 0) {
            if (!jumped) {
                next = ptr + 1;
            }
            break;
        } else {
            ptr++;
            if (ptr - msg + len > msglen) return NULL;
            if (pos > 0 && pos < bufsize - 1) {
                buf[pos++] = '.';
            }
            for (int i = 0; i < len && pos < bufsize - 1; i++) {
                buf[pos++] = (char)tolower(ptr[i]);
            }
            ptr += len;
        }
    }

    buf[pos] = '\0';
    if (pos == 0) {
        buf[0] = '.';
        buf[1] = '\0';
    }
    return next;
}

static void format_ipv6(const uint8_t *addr, char *buf, int bufsize) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (uint16_t)((addr[2*i] << 8) | addr[2*i+1]);

    int best_start = -1, best_len = 0;
    int i = 0;
    while (i < 8) {
        if (groups[i] == 0) {
            int j = i;
            while (j < 8 && groups[j] == 0) j++;
            int run = j - i;
            if (run >= 2 && run > best_len) {
                best_start = i;
                best_len = run;
            }
            i = j;
        } else {
            i++;
        }
    }

    int pos = 0;
    for (i = 0; i < 8; i++) {
        if (i == best_start) {
            buf[pos++] = ':';
            buf[pos++] = ':';
            i += best_len - 1;
            continue;
        }
        if (pos > 0 && buf[pos-1] != ':') {
            buf[pos++] = ':';
        }
        pos += snprintf(buf + pos, bufsize - pos, "%x", groups[i]);
    }
    buf[pos] = '\0';
}

static int read_exact(int fd, uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int r = (int)read(fd, buf + total, n - total);
        if (r <= 0) return -1;
        total += r;
    }
    return 0;
}

static int write_exact(int fd, const uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int w = (int)write(fd, buf + total, n - total);
        if (w <= 0) return -1;
        total += w;
    }
    return 0;
}

static int type_to_num(const char *t) {
    if (strcmp(t, "A") == 0) return 1;
    if (strcmp(t, "AAAA") == 0) return 28;
    if (strcmp(t, "MX") == 0) return 15;
    if (strcmp(t, "TXT") == 0) return 16;
    if (strcmp(t, "CNAME") == 0) return 5;
    return -1;
}

static const char *num_to_type(int t) {
    switch (t) {
        case 1: return "A";
        case 5: return "CNAME";
        case 15: return "MX";
        case 16: return "TXT";
        case 28: return "AAAA";
        default: return NULL;
    }
}

static const char *rcode_str(int rc) {
    switch (rc) {
        case 0: return "NOERROR";
        case 1: return "FORMERR";
        case 2: return "SERVFAIL";
        case 3: return "NXDOMAIN";
        case 4: return "NOTIMP";
        case 5: return "REFUSED";
        default: return NULL;
    }
}

static void print_txt_rdata(const uint8_t *rdata, int rdlen) {
    int pos = 0;
    int first = 1;
    while (pos < rdlen) {
        if (!first) putchar(' ');
        first = 0;
        int slen = rdata[pos++];
        if (pos + slen > rdlen) slen = rdlen - pos;
        putchar('"');
        for (int i = 0; i < slen; i++) {
            uint8_t c = rdata[pos++];
            if (c == '"') {
                putchar('\\'); putchar('"');
            } else if (c == '\\') {
                putchar('\\'); putchar('\\');
            } else if (c >= 0x20 && c <= 0x7E) {
                putchar(c);
            } else {
                printf("\\%03d", c);
            }
        }
        putchar('"');
    }
}

static void print_rdata(int type, const uint8_t *msg, int msglen,
                        const uint8_t *rdata, int rdlen) {
    if (type == 1) { /* A */
        if (rdlen >= 4)
            printf("%u.%u.%u.%u", rdata[0], rdata[1], rdata[2], rdata[3]);
    } else if (type == 28) { /* AAAA */
        if (rdlen >= 16) {
            char buf[64];
            format_ipv6(rdata, buf, sizeof(buf));
            printf("%s", buf);
        }
    } else if (type == 5) { /* CNAME */
        char name[1024];
        read_name(msg, msglen, rdata, name, sizeof(name));
        printf("%s", name);
    } else if (type == 15) { /* MX */
        if (rdlen >= 2) {
            int pref = get_u16(rdata);
            printf("%d ", pref);
            char name[1024];
            read_name(msg, msglen, rdata + 2, name, sizeof(name));
            printf("%s", name);
        }
    } else if (type == 16) { /* TXT */
        print_txt_rdata(rdata, rdlen);
    } else {
        printf("\\# %d", rdlen);
        if (rdlen > 0) {
            putchar(' ');
            for (int i = 0; i < rdlen; i++)
                printf("%02x", rdata[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) return 1;

    const char *dir = argv[1];
    int port = atoi(argv[2]);

    char path[4096];
    snprintf(path, sizeof(path), "%s/queries.txt", dir);

    FILE *f = fopen(path, "r");
    if (!f) return 1;

    srand((unsigned)time(NULL));

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        /* strip newline */
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r'))
            line[--len] = '\0';

        /* skip empty lines */
        int i = 0;
        while (i < len && isspace((unsigned char)line[i])) i++;
        if (i >= len) continue;

        /* parse name and type */
        char qname[1024], qtype_str[64];
        if (sscanf(line + i, "%1023s %63s", qname, qtype_str) < 2)
            continue;

        int qtype = type_to_num(qtype_str);
        if (qtype < 0) continue;

        /* build query */
        uint8_t query[2048];
        int qlen = 0;

        uint16_t qid = (uint16_t)(rand() & 0xFFFF);
        put_u16(query + 0, qid);
        put_u16(query + 2, 0x0100); /* flags */
        put_u16(query + 4, 1);      /* QDCOUNT */
        put_u16(query + 6, 0);      /* ANCOUNT */
        put_u16(query + 8, 0);      /* NSCOUNT */
        put_u16(query + 10, 0);     /* ARCOUNT */
        qlen = 12;

        /* encode QNAME: strip trailing dot, split by dots */
        char tmpname[1024];
        strncpy(tmpname, qname, sizeof(tmpname) - 1);
        tmpname[sizeof(tmpname)-1] = '\0';
        int tlen = (int)strlen(tmpname);
        if (tlen > 0 && tmpname[tlen-1] == '.')
            tmpname[--tlen] = '\0';

        if (tlen == 0) {
            query[qlen++] = 0; /* root */
        } else {
            char *p = tmpname;
            while (*p) {
                char *dot = strchr(p, '.');
                int lablen;
                if (dot) {
                    lablen = (int)(dot - p);
                } else {
                    lablen = (int)strlen(p);
                }
                if (lablen > 63) lablen = 63;
                query[qlen++] = (uint8_t)lablen;
                memcpy(query + qlen, p, lablen);
                qlen += lablen;
                if (dot) p = dot + 1; else p += lablen;
            }
            query[qlen++] = 0;
        }

        put_u16(query + qlen, (uint16_t)qtype); qlen += 2;
        put_u16(query + qlen, 1); qlen += 2; /* QCLASS = IN */

        /* send UDP and receive */
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons((uint16_t)port);
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);

        sendto(sock, query, qlen, 0, (struct sockaddr *)&addr, sizeof(addr));

        uint8_t resp[65536];
        int rlen = 0;
        while (1) {
            rlen = (int)recvfrom(sock, resp, sizeof(resp), 0, NULL, NULL);
            if (rlen < 12) continue;
            if (get_u16(resp) != qid) continue;
            if (!(resp[2] & 0x80)) continue; /* QR must be 1 */
            break;
        }
        close(sock);

        /* check TC */
        int tc = (resp[2] & 0x02) ? 1 : 0;

        if (tc) {
            /* TCP fallback */
            int tcp_sock = socket(AF_INET, SOCK_STREAM, 0);
            connect(tcp_sock, (struct sockaddr *)&addr, sizeof(addr));

            uint8_t tcpbuf[2048];
            put_u16(tcpbuf, (uint16_t)qlen);
            memcpy(tcpbuf + 2, query, qlen);
            write_exact(tcp_sock, tcpbuf, 2 + qlen);

            uint8_t tlen_buf[2];
            read_exact(tcp_sock, tlen_buf, 2);
            int tmsglen = get_u16(tlen_buf);
            if (tmsglen > (int)sizeof(resp)) tmsglen = (int)sizeof(resp);
            read_exact(tcp_sock, resp, tmsglen);
            rlen = tmsglen;
            close(tcp_sock);
        }

        /* parse response */
        if (rlen < 12) continue;

        int rcode = resp[3] & 0x0F;
        int qdcount = get_u16(resp + 4);
        int ancount = get_u16(resp + 6);

        /* print header line: lowercase name without trailing dot */
        char outname[1024];
        strncpy(outname, qname, sizeof(outname) - 1);
        outname[sizeof(outname)-1] = '\0';
        int onlen = (int)strlen(outname);
        if (onlen > 0 && outname[onlen-1] == '.')
            outname[--onlen] = '\0';
        for (int j = 0; j < onlen; j++)
            outname[j] = (char)tolower((unsigned char)outname[j]);
        if (onlen == 0) { outname[0] = '.'; outname[1] = '\0'; }

        printf("%s %s ", outname, qtype_str);
        const char *rs = rcode_str(rcode);
        if (rs) printf("%s\n", rs);
        else printf("RCODE%d\n", rcode);

        /* skip question section */
        const uint8_t *ptr = resp + 12;
        for (int q = 0; q < qdcount; q++) {
            char dummy[1024];
            ptr = read_name(resp, rlen, ptr, dummy, sizeof(dummy));
            if (!ptr) break;
            ptr += 4; /* QTYPE + QCLASS */
        }

        /* parse answer section */
        for (int a = 0; a < ancount && ptr; a++) {
            char owner[1024];
            ptr = read_name(resp, rlen, ptr, owner, sizeof(owner));
            if (!ptr) break;
            if (ptr - resp + 10 > rlen) break;

            int rtype = get_u16(ptr); ptr += 2;
            /* int rclass = */ ptr += 2; /* skip CLASS */
            uint32_t ttl = get_u32(ptr); ptr += 4;
            int rdlength = get_u16(ptr); ptr += 2;

            if (ptr - resp + rdlength > rlen) break;

            printf("  %s %u ", owner, ttl);
            const char *tn = num_to_type(rtype);
            if (tn) {
                printf("%s ", tn);
            } else {
                printf("TYPE%d ", rtype);
            }
            print_rdata(rtype, resp, rlen, ptr, rdlength);
            putchar('\n');

            ptr += rdlength;
        }
    }

    fclose(f);
    return 0;
}

import json
import sys
import os


def encode_pointer_token(token):
    return token.replace('~', '~0').replace('/', '~1')


def is_number(val):
    return isinstance(val, (int, float)) and not isinstance(val, bool)


def is_integer(val):
    if not is_number(val):
        return False
    if isinstance(val, int):
        return True
    if isinstance(val, float):
        return val == int(val)
    return False


def deep_equal(a, b):
    if isinstance(a, bool) and isinstance(b, bool):
        return a == b
    if isinstance(a, bool) or isinstance(b, bool):
        return False
    if is_number(a) and is_number(b):
        return float(a) == float(b)
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(deep_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(deep_equal(a[k], b[k]) for k in a)
    if a is None and b is None:
        return True
    return False


def matches_type(instance, type_name):
    if type_name == 'null':
        return instance is None
    if type_name == 'boolean':
        return isinstance(instance, bool)
    if type_name == 'number':
        return is_number(instance)
    if type_name == 'integer':
        return is_integer(instance)
    if type_name == 'string':
        return isinstance(instance, str)
    if type_name == 'array':
        return isinstance(instance, list)
    if type_name == 'object':
        return isinstance(instance, dict)
    return False


def validate(instance, schema, instance_loc, schema_loc, schema_root):
    errors = set()

    if isinstance(schema, bool):
        if schema is False:
            errors.add((instance_loc, schema_loc))
        return errors

    if not isinstance(schema, dict):
        return errors

    # type
    if 'type' in schema:
        type_val = schema['type']
        if isinstance(type_val, str):
            if not matches_type(instance, type_val):
                errors.add((instance_loc, schema_loc + '/type'))
        elif isinstance(type_val, list):
            if not any(matches_type(instance, t) for t in type_val):
                errors.add((instance_loc, schema_loc + '/type'))

    # enum
    if 'enum' in schema:
        if not any(deep_equal(instance, e) for e in schema['enum']):
            errors.add((instance_loc, schema_loc + '/enum'))

    # const
    if 'const' in schema:
        if not deep_equal(instance, schema['const']):
            errors.add((instance_loc, schema_loc + '/const'))

    # Number keywords
    if is_number(instance):
        if 'minimum' in schema:
            if float(instance) < float(schema['minimum']):
                errors.add((instance_loc, schema_loc + '/minimum'))
        if 'maximum' in schema:
            if float(instance) > float(schema['maximum']):
                errors.add((instance_loc, schema_loc + '/maximum'))
        if 'exclusiveMinimum' in schema:
            if float(instance) <= float(schema['exclusiveMinimum']):
                errors.add((instance_loc, schema_loc + '/exclusiveMinimum'))
        if 'exclusiveMaximum' in schema:
            if float(instance) >= float(schema['exclusiveMaximum']):
                errors.add((instance_loc, schema_loc + '/exclusiveMaximum'))

    # String keywords
    if isinstance(instance, str):
        if 'minLength' in schema:
            if len(instance) < schema['minLength']:
                errors.add((instance_loc, schema_loc + '/minLength'))
        if 'maxLength' in schema:
            if len(instance) > schema['maxLength']:
                errors.add((instance_loc, schema_loc + '/maxLength'))

    # Array keywords
    if isinstance(instance, list):
        if 'minItems' in schema:
            if len(instance) < schema['minItems']:
                errors.add((instance_loc, schema_loc + '/minItems'))
        if 'maxItems' in schema:
            if len(instance) > schema['maxItems']:
                errors.add((instance_loc, schema_loc + '/maxItems'))
        if 'uniqueItems' in schema and schema['uniqueItems'] is True:
            found_dup = False
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        found_dup = True
                        break
                if found_dup:
                    break
            if found_dup:
                errors.add((instance_loc, schema_loc + '/uniqueItems'))

        # prefixItems
        if 'prefixItems' in schema:
            prefix = schema['prefixItems']
            for i in range(min(len(instance), len(prefix))):
                child_loc = instance_loc + '/' + str(i)
                sub_loc = schema_loc + '/prefixItems/' + str(i)
                errors |= validate(instance[i], prefix[i], child_loc, sub_loc, schema_root)

        # items
        if 'items' in schema:
            start = len(schema.get('prefixItems', []))
            for i in range(start, len(instance)):
                child_loc = instance_loc + '/' + str(i)
                sub_loc = schema_loc + '/items'
                errors |= validate(instance[i], schema['items'], child_loc, sub_loc, schema_root)

    # Object keywords
    if isinstance(instance, dict):
        if 'minProperties' in schema:
            if len(instance) < schema['minProperties']:
                errors.add((instance_loc, schema_loc + '/minProperties'))
        if 'maxProperties' in schema:
            if len(instance) > schema['maxProperties']:
                errors.add((instance_loc, schema_loc + '/maxProperties'))

        if 'required' in schema:
            for j, name in enumerate(schema['required']):
                if name not in instance:
                    errors.add((instance_loc, schema_loc + '/required/' + str(j)))

        if 'properties' in schema:
            props = schema['properties']
            for name in instance:
                if name in props:
                    child_loc = instance_loc + '/' + encode_pointer_token(name)
                    sub_loc = schema_loc + '/properties/' + encode_pointer_token(name)
                    errors |= validate(instance[name], props[name], child_loc, sub_loc, schema_root)

        if 'additionalProperties' in schema:
            prop_names = set(schema['properties'].keys()) if 'properties' in schema else set()
            for name in instance:
                if name not in prop_names:
                    child_loc = instance_loc + '/' + encode_pointer_token(name)
                    sub_loc = schema_loc + '/additionalProperties'
                    errors |= validate(instance[name], schema['additionalProperties'], child_loc, sub_loc, schema_root)

    # Applicators
    if 'allOf' in schema:
        for i, sub in enumerate(schema['allOf']):
            sub_loc = schema_loc + '/allOf/' + str(i)
            errors |= validate(instance, sub, instance_loc, sub_loc, schema_root)

    if 'anyOf' in schema:
        any_accepted = False
        for i, sub in enumerate(schema['anyOf']):
            sub_loc = schema_loc + '/anyOf/' + str(i)
            sub_errors = validate(instance, sub, instance_loc, sub_loc, schema_root)
            if len(sub_errors) == 0:
                any_accepted = True
                break
        if not any_accepted:
            errors.add((instance_loc, schema_loc + '/anyOf'))

    if 'oneOf' in schema:
        count_accepted = 0
        for i, sub in enumerate(schema['oneOf']):
            sub_loc = schema_loc + '/oneOf/' + str(i)
            sub_errors = validate(instance, sub, instance_loc, sub_loc, schema_root)
            if len(sub_errors) == 0:
                count_accepted += 1
        if count_accepted != 1:
            errors.add((instance_loc, schema_loc + '/oneOf'))

    if 'not' in schema:
        sub_errors = validate(instance, schema['not'], instance_loc, schema_loc + '/not', schema_root)
        if len(sub_errors) == 0:
            errors.add((instance_loc, schema_loc + '/not'))

    if 'if' in schema:
        if_errors = validate(instance, schema['if'], instance_loc, schema_loc + '/if', schema_root)
        if len(if_errors) == 0:
            if 'then' in schema:
                errors |= validate(instance, schema['then'], instance_loc, schema_loc + '/then', schema_root)
        else:
            if 'else' in schema:
                errors |= validate(instance, schema['else'], instance_loc, schema_loc + '/else', schema_root)

    # $ref
    if '$ref' in schema:
        ref = schema['$ref']
        if ref == '#':
            resolved_schema = schema_root
            resolved_loc = '#'
        elif ref.startswith('#/$defs/'):
            token = ref[len('#/$defs/'):]
            name = token.replace('~1', '/').replace('~0', '~')
            resolved_schema = schema_root['$defs'][name]
            resolved_loc = '#/$defs/' + encode_pointer_token(name)
        else:
            resolved_schema = None
            resolved_loc = None
        if resolved_schema is not None:
            errors |= validate(instance, resolved_schema, instance_loc, resolved_loc, schema_root)

    return errors


def main():
    directory = sys.argv[1]

    with open(os.path.join(directory, 'schema.json'), 'r', encoding='utf-8') as f:
        schema = json.load(f)

    with open(os.path.join(directory, 'instances.json'), 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0

    for n, instance in enumerate(instances):
        errors = validate(instance, schema, '#', '#', schema)
        if len(errors) == 0:
            print(f"{n}: valid")
            valid_count += 1
        else:
            sorted_errors = sorted(errors, key=lambda e: (e[0], e[1]))
            print(f"{n}: invalid ({len(sorted_errors)})")
            for inst_loc, sch_loc in sorted_errors:
                print(f"  {inst_loc} {sch_loc}")
            invalid_count += 1

    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == '__main__':
    main()

import Foundation

// MARK: - BigUInt (unsigned big integer, base 10^9)

struct BigUInt {
    static let BASE: UInt64 = 1_000_000_000

    var limbs: [UInt64] // least significant first

    init(_ val: UInt64) {
        if val == 0 {
            limbs = [0]
        } else {
            var v = val
            limbs = []
            while v > 0 {
                limbs.append(v % BigUInt.BASE)
                v /= BigUInt.BASE
            }
        }
    }

    init(limbs: [UInt64]) {
        self.limbs = limbs
        normalize()
    }

    mutating func normalize() {
        while limbs.count > 1 && limbs.last! == 0 {
            limbs.removeLast()
        }
    }

    var isZero: Bool { limbs.count == 1 && limbs[0] == 0 }
    func isOdd() -> Bool { limbs[0] % 2 == 1 }

    static func compare(_ a: BigUInt, _ b: BigUInt) -> Int {
        if a.limbs.count != b.limbs.count {
            return a.limbs.count > b.limbs.count ? 1 : -1
        }
        for i in stride(from: a.limbs.count - 1, through: 0, by: -1) {
            if a.limbs[i] != b.limbs[i] {
                return a.limbs[i] > b.limbs[i] ? 1 : -1
            }
        }
        return 0
    }

    static func + (a: BigUInt, b: BigUInt) -> BigUInt {
        let n = max(a.limbs.count, b.limbs.count)
        var result = [UInt64](repeating: 0, count: n + 1)
        var carry: UInt64 = 0
        for i in 0..<n {
            let av = i < a.limbs.count ? a.limbs[i] : 0
            let bv = i < b.limbs.count ? b.limbs[i] : 0
            let sum = av + bv + carry
            result[i] = sum % BASE
            carry = sum / BASE
        }
        result[n] = carry
        return BigUInt(limbs: result)
    }

    static func - (a: BigUInt, b: BigUInt) -> BigUInt {
        var result = [UInt64](repeating: 0, count: a.limbs.count)
        var borrow: UInt64 = 0
        for i in 0..<a.limbs.count {
            let bv = i < b.limbs.count ? b.limbs[i] : 0
            if a.limbs[i] >= bv + borrow {
                result[i] = a.limbs[i] - bv - borrow
                borrow = 0
            } else {
                result[i] = a.limbs[i] + BASE - bv - borrow
                borrow = 1
            }
        }
        return BigUInt(limbs: result)
    }

    static func * (a: BigUInt, b: BigUInt) -> BigUInt {
        if a.isZero || b.isZero { return BigUInt(0) }
        let n = a.limbs.count + b.limbs.count
        var result = [UInt64](repeating: 0, count: n)
        for i in 0..<a.limbs.count {
            var carry: UInt64 = 0
            for j in 0..<b.limbs.count {
                let prod = a.limbs[i] * b.limbs[j] + result[i + j] + carry
                result[i + j] = prod % BASE
                carry = prod / BASE
            }
            var k = i + b.limbs.count
            while carry > 0 {
                let s = result[k] + carry
                result[k] = s % BASE
                carry = s / BASE
                k += 1
            }
        }
        return BigUInt(limbs: result)
    }

    func mulSingle(_ d: UInt64) -> BigUInt {
        if d == 0 || isZero { return BigUInt(0) }
        var result = [UInt64](repeating: 0, count: limbs.count + 1)
        var carry: UInt64 = 0
        for i in 0..<limbs.count {
            let prod = limbs[i] * d + carry
            result[i] = prod % BASE
            carry = prod / BASE
        }
        result[limbs.count] = carry
        return BigUInt(limbs: result)
    }

    static func divmod(_ a: BigUInt, _ b: BigUInt) -> (BigUInt, BigUInt) {
        if b.isZero { fatalError("division by zero") }
        if compare(a, b) < 0 { return (BigUInt(0), a) }
        if b.limbs.count == 1 {
            return divmodSingle(a, b.limbs[0])
        }
        return divmodMulti(a, b)
    }

    static func divmodSingle(_ a: BigUInt, _ d: UInt64) -> (BigUInt, BigUInt) {
        var quotient = [UInt64](repeating: 0, count: a.limbs.count)
        var remainder: UInt64 = 0
        for i in stride(from: a.limbs.count - 1, through: 0, by: -1) {
            let cur = remainder * BASE + a.limbs[i]
            quotient[i] = cur / d
            remainder = cur % d
        }
        return (BigUInt(limbs: quotient), BigUInt(remainder))
    }

    static func divmodMulti(_ a: BigUInt, _ b: BigUInt) -> (BigUInt, BigUInt) {
        let n = b.limbs.count
        let m = a.limbs.count - n

        let d = BASE / (b.limbs[n - 1] + 1)
        var un = a.mulSingle(d).limbs
        let vn = b.mulSingle(d).limbs

        while un.count < m + n + 1 {
            un.append(0)
        }

        var quotient = [UInt64](repeating: 0, count: m + 1)

        for j in stride(from: m, through: 0, by: -1) {
            var qhat: UInt64
            var rhat: UInt64

            if un[j + n] >= vn[n - 1] {
                qhat = BASE - 1
                rhat = un[j + n] * BASE + un[j + n - 1] - (BASE - 1) * vn[n - 1]
            } else {
                let top = un[j + n] * BASE + un[j + n - 1]
                qhat = top / vn[n - 1]
                rhat = top % vn[n - 1]
            }

            while qhat >= BASE || (n >= 2 && qhat * vn[n - 2] > rhat * BASE + un[j + n - 2]) {
                qhat -= 1
                rhat += vn[n - 1]
                if rhat >= BASE { break }
            }

            var borrow: UInt64 = 0
            for i in 0..<n {
                let prod = qhat * vn[i]
                let sub = (prod % BASE) + borrow
                if un[j + i] >= sub {
                    un[j + i] -= sub
                    borrow = prod / BASE
                } else {
                    un[j + i] = BASE + un[j + i] - sub
                    borrow = prod / BASE + 1
                }
            }

            if un[j + n] < borrow {
                un[j + n] = BASE + un[j + n] - borrow
                qhat -= 1
                var carry: UInt64 = 0
                for i in 0..<n {
                    let s = un[j + i] + vn[i] + carry
                    un[j + i] = s % BASE
                    carry = s / BASE
                }
                un[j + n] += carry
            } else {
                un[j + n] -= borrow
            }

            quotient[j] = qhat
        }

        let remainderLimbs = Array(un[0..<n])
        let (remainder, _) = divmodSingle(BigUInt(limbs: remainderLimbs), d)

        return (BigUInt(limbs: quotient), remainder)
    }

    init(fromString s: String) {
        if s.isEmpty { limbs = [0]; return }
        limbs = [0]
        for ch in s {
            let d = UInt64(ch.asciiValue! - 48)
            var carry = d
            for i in 0..<limbs.count {
                let prod = limbs[i] * 10 + carry
                limbs[i] = prod % BASE
                carry = prod / BASE
            }
            if carry > 0 {
                limbs.append(carry)
            }
        }
        normalize()
    }

    func toString() -> String {
        if isZero { return "0" }
        var result = String(limbs[limbs.count - 1])
        for i in stride(from: limbs.count - 2, through: 0, by: -1) {
            let s = String(limbs[i])
            result += String(repeating: "0", count: 9 - s.count) + s
        }
        return result
    }
}

// MARK: - BigInt (signed big integer)

struct BigInt {
    var negative: Bool
    var magnitude: BigUInt

    static let zero = BigInt(negative: false, magnitude: BigUInt(0))

    init(negative: Bool, magnitude: BigUInt) {
        self.negative = negative && !magnitude.isZero
        self.magnitude = magnitude
    }

    var isZero: Bool { magnitude.isZero }

    static func + (a: BigInt, b: BigInt) -> BigInt {
        if a.negative == b.negative {
            return BigInt(negative: a.negative, magnitude: a.magnitude + b.magnitude)
        }
        let cmp = BigUInt.compare(a.magnitude, b.magnitude)
        if cmp == 0 { return .zero }
        if cmp > 0 {
            return BigInt(negative: a.negative, magnitude: a.magnitude - b.magnitude)
        } else {
            return BigInt(negative: b.negative, magnitude: b.magnitude - a.magnitude)
        }
    }

    static func - (a: BigInt, b: BigInt) -> BigInt {
        return a + BigInt(negative: !b.negative, magnitude: b.magnitude)
    }

    static func * (a: BigInt, b: BigInt) -> BigInt {
        return BigInt(negative: a.negative != b.negative, magnitude: a.magnitude * b.magnitude)
    }

    static func < (a: BigInt, b: BigInt) -> Bool {
        if a.negative && !b.negative { return true }
        if !a.negative && b.negative { return false }
        if a.negative && b.negative {
            return BigUInt.compare(a.magnitude, b.magnitude) > 0
        }
        return BigUInt.compare(a.magnitude, b.magnitude) < 0
    }

    static func == (a: BigInt, b: BigInt) -> Bool {
        if a.isZero && b.isZero { return true }
        return a.negative == b.negative && BigUInt.compare(a.magnitude, b.magnitude) == 0
    }

    static func <= (a: BigInt, b: BigInt) -> Bool { return a < b || a == b }
    static func >= (a: BigInt, b: BigInt) -> Bool { return !(a < b) }
    static func > (a: BigInt, b: BigInt) -> Bool { return !(a <= b) }
}

// MARK: - Decimal parsing and operations

struct DecimalVal {
    var value: BigInt
    var scale: Int
}

func parseDecimal(_ s: String) -> DecimalVal {
    var negative = false
    var str = s
    if str.hasPrefix("-") {
        negative = true
        str = String(str.dropFirst())
    }

    let parts = str.split(separator: ".", maxSplits: 1, omittingEmptySubsequences: false)
    let intPart: String
    let fracPart: String
    if parts.count == 1 {
        intPart = String(parts[0])
        fracPart = ""
    } else {
        intPart = String(parts[0])
        fracPart = String(parts[1])
    }

    let digits = intPart + fracPart
    let mag = BigUInt(fromString: digits)
    let val = BigInt(negative: negative, magnitude: mag)
    return DecimalVal(value: val, scale: fracPart.count)
}

func pow10(_ n: Int) -> BigUInt {
    if n == 0 { return BigUInt(1) }
    var result = BigUInt(1)
    let ten = BigUInt(10)
    for _ in 0..<n {
        result = result * ten
    }
    return result
}

func roundToMinor(_ d: DecimalVal, minor: Int) -> BigInt {
    if d.value.isZero { return .zero }
    if d.scale <= minor {
        let factor = pow10(minor - d.scale)
        return BigInt(negative: d.value.negative, magnitude: d.value.magnitude * factor)
    } else {
        let divisor = pow10(d.scale - minor)
        let (q, r) = BigUInt.divmod(d.value.magnitude, divisor)
        let doubleR = r * BigUInt(2)
        let cmp = BigUInt.compare(doubleR, divisor)
        var result: BigUInt
        if cmp > 0 {
            result = q + BigUInt(1)
        } else if cmp < 0 {
            result = q
        } else {
            if q.isOdd() {
                result = q + BigUInt(1)
            } else {
                result = q
            }
        }
        return BigInt(negative: d.value.negative && !result.isZero, magnitude: result)
    }
}

func roundDiv(_ numeratorMag: BigUInt, _ denominator: BigUInt, negative: Bool) -> BigInt {
    if numeratorMag.isZero { return .zero }
    let (q, r) = BigUInt.divmod(numeratorMag, denominator)
    let doubleR = r * BigUInt(2)
    let cmp = BigUInt.compare(doubleR, denominator)
    var result: BigUInt
    if cmp > 0 {
        result = q + BigUInt(1)
    } else if cmp < 0 {
        result = q
    } else {
        if q.isOdd() {
            result = q + BigUInt(1)
        } else {
            result = q
        }
    }
    return BigInt(negative: negative && !result.isZero, magnitude: result)
}

// MARK: - Money formatting

func formatMoney(_ balance: BigInt, minor: Int) -> String {
    if balance.isZero {
        if minor == 0 { return "0" }
        return "0." + String(repeating: "0", count: minor)
    }

    let prefix = balance.negative ? "-" : ""
    let absVal = balance.magnitude

    let divisor = pow10(minor)
    let (intPart, fracPart) = BigUInt.divmod(absVal, divisor)

    let intStr = intPart.toString()
    var formatted = ""
    let chars = Array(intStr)
    for i in 0..<chars.count {
        if i > 0 && (chars.count - i) % 3 == 0 {
            formatted += ","
        }
        formatted.append(chars[i])
    }

    if minor == 0 {
        return prefix + formatted
    }

    let fracStr = fracPart.toString()
    let paddedFrac = String(repeating: "0", count: minor - fracStr.count) + fracStr

    return prefix + formatted + "." + paddedFrac
}

// MARK: - Main program

let args = CommandLine.arguments
let dir = args[1]
let path = dir + "/ledger.txt"
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
struct AccountInfo {
    var currency: String
    var balance: BigInt
    var limit: BigInt
}
var accounts: [String: AccountInfo] = [:]
var rejections: [(Int, String)] = []

for (idx, line) in lines.enumerated() {
    let lineNum = idx + 1
    let trimmed = line.trimmingCharacters(in: CharacterSet(charactersIn: " \t"))

    // Check blank or comment
    if trimmed.isEmpty { continue }
    if trimmed.first == "#" { continue }

    let fields = trimmed.split(separator: " ", omittingEmptySubsequences: true).map { String($0) }
    if fields.isEmpty { continue }

    let cmd = fields[0]

    switch cmd {
    case "currency":
        let code = fields[1]
        let minor = Int(fields[2])!
        currencies[code] = minor

    case "open":
        let name = fields[1]
        let code = fields[2]
        if accounts[name] != nil {
            rejections.append((lineNum, "account exists \(name)"))
            continue
        }
        let minor = currencies[code]!
        var limit: BigInt = .zero
        if fields.count > 3 {
            let limitDec = parseDecimal(fields[3])
            limit = roundToMinor(limitDec, minor: minor)
            if limit.negative {
                limit = BigInt(negative: false, magnitude: limit.magnitude)
            }
        }
        accounts[name] = AccountInfo(currency: code, balance: .zero, limit: limit)

    case "deposit":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.currency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        accounts[name]!.balance = accounts[name]!.balance + rounded

    case "withdraw":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.currency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBalance = accounts[name]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[name]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(name)"))
            continue
        }
        accounts[name]!.balance = newBalance

    case "transfer":
        let from = fields[1]
        let to = fields[2]
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        if accounts[to] == nil {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        if accounts[from]!.currency != accounts[to]!.currency {
            rejections.append((lineNum, "currency mismatch"))
            continue
        }
        let minor = currencies[accounts[from]!.currency]!
        let amount = parseDecimal(fields[3])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        accounts[from]!.balance = newBalance
        accounts[to]!.balance = accounts[to]!.balance + rounded

    case "convert":
        let from = fields[1]
        let to = fields[2]
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        if accounts[to] == nil {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        let fromMinor = currencies[accounts[from]!.currency]!
        let toMinor = currencies[accounts[to]!.currency]!
        let amount = parseDecimal(fields[3])
        let rounded = roundToMinor(amount, minor: fromMinor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let rate = parseDecimal(fields[4])

        // Check insufficient funds
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        // Compute: rounded * rate * 10^toMinor / 10^(fromMinor + rate.scale)
        let numMag = rounded.magnitude * rate.value.magnitude * pow10(toMinor)
        let den = pow10(fromMinor + rate.scale)
        let result = roundDiv(numMag, den, negative: rate.value.negative)

        accounts[from]!.balance = newBalance
        accounts[to]!.balance = accounts[to]!.balance + result

    case "interest":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let rate = parseDecimal(fields[2])
        let balance = accounts[name]!.balance

        // interest = round_half_even(balance * rateValue, 10^rate.scale)
        let numMag = balance.magnitude * rate.value.magnitude
        let den = pow10(rate.scale)
        let isNeg = (balance.negative != rate.value.negative)
        let interest = roundDiv(numMag, den, negative: isNeg)
        accounts[name]!.balance = balance + interest

    case "split":
        let from = fields[1]
        // Parse targets: fields[3], fields[4], ... are "name:weight"
        var targets: [(name: String, weight: BigUInt)] = []
        for i in 3..<fields.count {
            let parts = fields[i].split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
            let tName = String(parts[0])
            let tWeight = BigUInt(fromString: String(parts[1]))
            targets.append((name: tName, weight: tWeight))
        }

        // Check accounts exist (from first, then targets in order)
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        var unknownFound = false
        for t in targets {
            if accounts[t.name] == nil {
                rejections.append((lineNum, "unknown account \(t.name)"))
                unknownFound = true
                break
            }
        }
        if unknownFound { continue }

        // Check currency mismatch
        let fromCurrency = accounts[from]!.currency
        for t in targets {
            if accounts[t.name]!.currency != fromCurrency {
                rejections.append((lineNum, "currency mismatch"))
                unknownFound = true
                break
            }
        }
        if unknownFound { continue }

        let minor = currencies[fromCurrency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }

        // Check insufficient funds
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        // Distribute
        let A = rounded.magnitude // BigUInt, positive
        var W = BigUInt(0)
        for t in targets {
            W = W + t.weight
        }

        var bases: [BigUInt] = []
        var remainders: [BigUInt] = []
        var sumBases = BigUInt(0)

        for t in targets {
            let product = A * t.weight
            let (q, r) = BigUInt.divmod(product, W)
            bases.append(q)
            remainders.append(r)
            sumBases = sumBases + q
        }

        let leftover = A - sumBases
        let leftoverCount = Int(leftover.limbs[0]) // leftover < number of targets, fits in Int

        // Sort indices by remainder descending, ties by original order
        let n = targets.count
        var indices = Array(0..<n)
        indices.sort { i, j in
            let cmp = BigUInt.compare(remainders[i], remainders[j])
            if cmp != 0 { return cmp > 0 }
            return i < j
        }

        // Apply distribution
        accounts[from]!.balance = newBalance
        for i in 0..<n {
            var add = bases[i]
            if i < leftoverCount {
                add = add + BigUInt(1)
            }
            accounts[targets[i].name]!.balance = accounts[targets[i].name]!.balance + BigInt(negative: false, magnitude: add)
        }

    default:
        break
    }
}

// MARK: - Output

// Rejections
for (lineNum, reason) in rejections {
    print("line \(lineNum): REJECT \(reason)")
}

// Blank line
print("")

// Accounts sorted by name (byte-wise ascending)
let sortedAccounts = accounts.keys.sorted { a, b in
    // Byte-wise comparison (ASCII)
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    let minLen = min(aBytes.count, bBytes.count)
    for i in 0..<minLen {
        if aBytes[i] != bBytes[i] { return aBytes[i] < bBytes[i] }
    }
    return aBytes.count < bBytes.count
}

for name in sortedAccounts {
    let acct = accounts[name]!
    let minor = currencies[acct.currency]!
    let balStr = formatMoney(acct.balance, minor: minor)
    print("\(name) \(acct.currency) \(balStr)")
}

// Blank line
print("")

// Totals per currency
var currencyTotals: [String: (BigInt, Int)] = [:]
for (_, acct) in accounts {
    let code = acct.currency
    if currencyTotals[code] == nil {
        currencyTotals[code] = (.zero, 0)
    }
    currencyTotals[code]!.0 = currencyTotals[code]!.0 + acct.balance
    currencyTotals[code]!.1 += 1
}

let sortedCurrencies = currencyTotals.keys.sorted { a, b in
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    let minLen = min(aBytes.count, bBytes.count)
    for i in 0..<minLen {
        if aBytes[i] != bBytes[i] { return aBytes[i] < bBytes[i] }
    }
    return aBytes.count < bBytes.count
}

for code in sortedCurrencies {
    let (total, count) = currencyTotals[code]!
    let minor = currencies[code]!
    let totalStr = formatMoney(total, minor: minor)
    print("total \(code) \(totalStr) (\(count) accounts)")
}

exit(0)

import Foundation

// MARK: - BigUInt (unsigned big integer, base 10^9)

struct BigUInt {
    static let BASE: UInt64 = 1_000_000_000

    var limbs: [UInt64] // least significant first

    init(_ val: UInt64) {
        if val == 0 {
            limbs = [0]
        } else {
            var v = val
            limbs = []
            while v > 0 {
                limbs.append(v % BigUInt.BASE)
                v /= BigUInt.BASE
            }
        }
    }

    init(limbs: [UInt64]) {
        self.limbs = limbs
        normalize()
    }

    mutating func normalize() {
        while limbs.count > 1 && limbs.last! == 0 {
            limbs.removeLast()
        }
    }

    var isZero: Bool { limbs.count == 1 && limbs[0] == 0 }
    func isOdd() -> Bool { limbs[0] % 2 == 1 }

    static func compare(_ a: BigUInt, _ b: BigUInt) -> Int {
        if a.limbs.count != b.limbs.count {
            return a.limbs.count > b.limbs.count ? 1 : -1
        }
        for i in stride(from: a.limbs.count - 1, through: 0, by: -1) {
            if a.limbs[i] != b.limbs[i] {
                return a.limbs[i] > b.limbs[i] ? 1 : -1
            }
        }
        return 0
    }

    static func + (a: BigUInt, b: BigUInt) -> BigUInt {
        let n = max(a.limbs.count, b.limbs.count)
        var result = [UInt64](repeating: 0, count: n + 1)
        var carry: UInt64 = 0
        for i in 0..<n {
            let av = i < a.limbs.count ? a.limbs[i] : 0
            let bv = i < b.limbs.count ? b.limbs[i] : 0
            let sum = av + bv + carry
            result[i] = sum % BigUInt.BASE
            carry = sum / BigUInt.BASE
        }
        result[n] = carry
        return BigUInt(limbs: result)
    }

    static func - (a: BigUInt, b: BigUInt) -> BigUInt {
        var result = [UInt64](repeating: 0, count: a.limbs.count)
        var borrow: UInt64 = 0
        for i in 0..<a.limbs.count {
            let bv = i < b.limbs.count ? b.limbs[i] : 0
            if a.limbs[i] >= bv + borrow {
                result[i] = a.limbs[i] - bv - borrow
                borrow = 0
            } else {
                result[i] = a.limbs[i] + BigUInt.BASE - bv - borrow
                borrow = 1
            }
        }
        return BigUInt(limbs: result)
    }

    static func * (a: BigUInt, b: BigUInt) -> BigUInt {
        if a.isZero || b.isZero { return BigUInt(0) }
        let n = a.limbs.count + b.limbs.count
        var result = [UInt64](repeating: 0, count: n)
        for i in 0..<a.limbs.count {
            var carry: UInt64 = 0
            for j in 0..<b.limbs.count {
                let prod = a.limbs[i] * b.limbs[j] + result[i + j] + carry
                result[i + j] = prod % BigUInt.BASE
                carry = prod / BigUInt.BASE
            }
            var k = i + b.limbs.count
            while carry > 0 {
                let s = result[k] + carry
                result[k] = s % BigUInt.BASE
                carry = s / BigUInt.BASE
                k += 1
            }
        }
        return BigUInt(limbs: result)
    }

    func mulSingle(_ d: UInt64) -> BigUInt {
        if d == 0 || isZero { return BigUInt(0) }
        var result = [UInt64](repeating: 0, count: limbs.count + 1)
        var carry: UInt64 = 0
        for i in 0..<limbs.count {
            let prod = limbs[i] * d + carry
            result[i] = prod % BigUInt.BASE
            carry = prod / BigUInt.BASE
        }
        result[limbs.count] = carry
        return BigUInt(limbs: result)
    }

    static func divmod(_ a: BigUInt, _ b: BigUInt) -> (BigUInt, BigUInt) {
        if b.isZero { fatalError("division by zero") }
        if compare(a, b) < 0 { return (BigUInt(0), a) }
        if b.limbs.count == 1 {
            return divmodSingle(a, b.limbs[0])
        }
        return divmodMulti(a, b)
    }

    static func divmodSingle(_ a: BigUInt, _ d: UInt64) -> (BigUInt, BigUInt) {
        var quotient = [UInt64](repeating: 0, count: a.limbs.count)
        var remainder: UInt64 = 0
        for i in stride(from: a.limbs.count - 1, through: 0, by: -1) {
            let cur = remainder * BigUInt.BASE + a.limbs[i]
            quotient[i] = cur / d
            remainder = cur % d
        }
        return (BigUInt(limbs: quotient), BigUInt(remainder))
    }

    static func divmodMulti(_ a: BigUInt, _ b: BigUInt) -> (BigUInt, BigUInt) {
        let n = b.limbs.count
        let m = a.limbs.count - n

        let d = BigUInt.BASE / (b.limbs[n - 1] + 1)
        var un = a.mulSingle(d).limbs
        let vn = b.mulSingle(d).limbs

        while un.count < m + n + 1 {
            un.append(0)
        }

        var quotient = [UInt64](repeating: 0, count: m + 1)

        for j in stride(from: m, through: 0, by: -1) {
            var qhat: UInt64
            var rhat: UInt64

            if un[j + n] >= vn[n - 1] {
                qhat = BigUInt.BASE - 1
                rhat = un[j + n] * BigUInt.BASE + un[j + n - 1] - (BigUInt.BASE - 1) * vn[n - 1]
            } else {
                let top = un[j + n] * BigUInt.BASE + un[j + n - 1]
                qhat = top / vn[n - 1]
                rhat = top % vn[n - 1]
            }

            while qhat >= BigUInt.BASE || (n >= 2 && qhat * vn[n - 2] > rhat * BigUInt.BASE + un[j + n - 2]) {
                qhat -= 1
                rhat += vn[n - 1]
                if rhat >= BigUInt.BASE { break }
            }

            var borrow: UInt64 = 0
            for i in 0..<n {
                let prod = qhat * vn[i]
                let sub = (prod % BigUInt.BASE) + borrow
                if un[j + i] >= sub {
                    un[j + i] -= sub
                    borrow = prod / BigUInt.BASE
                } else {
                    un[j + i] = BigUInt.BASE + un[j + i] - sub
                    borrow = prod / BigUInt.BASE + 1
                }
            }

            if un[j + n] < borrow {
                un[j + n] = BigUInt.BASE + un[j + n] - borrow
                qhat -= 1
                var carry: UInt64 = 0
                for i in 0..<n {
                    let s = un[j + i] + vn[i] + carry
                    un[j + i] = s % BigUInt.BASE
                    carry = s / BigUInt.BASE
                }
                un[j + n] += carry
            } else {
                un[j + n] -= borrow
            }

            quotient[j] = qhat
        }

        let remainderLimbs = Array(un[0..<n])
        let (remainder, _) = divmodSingle(BigUInt(limbs: remainderLimbs), d)

        return (BigUInt(limbs: quotient), remainder)
    }

    init(fromString s: String) {
        if s.isEmpty { limbs = [0]; return }
        limbs = [0]
        for ch in s {
            let d = UInt64(ch.asciiValue! - 48)
            var carry = d
            for i in 0..<limbs.count {
                let prod = limbs[i] * 10 + carry
                limbs[i] = prod % BigUInt.BASE
                carry = prod / BigUInt.BASE
            }
            if carry > 0 {
                limbs.append(carry)
            }
        }
        normalize()
    }

    func toString() -> String {
        if isZero { return "0" }
        var result = String(limbs[limbs.count - 1])
        for i in stride(from: limbs.count - 2, through: 0, by: -1) {
            let s = String(limbs[i])
            result += String(repeating: "0", count: 9 - s.count) + s
        }
        return result
    }
}

// MARK: - BigInt (signed big integer)

struct BigInt {
    var negative: Bool
    var magnitude: BigUInt

    static let zero = BigInt(negative: false, magnitude: BigUInt(0))

    init(negative: Bool, magnitude: BigUInt) {
        self.negative = negative && !magnitude.isZero
        self.magnitude = magnitude
    }

    var isZero: Bool { magnitude.isZero }

    static func + (a: BigInt, b: BigInt) -> BigInt {
        if a.negative == b.negative {
            return BigInt(negative: a.negative, magnitude: a.magnitude + b.magnitude)
        }
        let cmp = BigUInt.compare(a.magnitude, b.magnitude)
        if cmp == 0 { return .zero }
        if cmp > 0 {
            return BigInt(negative: a.negative, magnitude: a.magnitude - b.magnitude)
        } else {
            return BigInt(negative: b.negative, magnitude: b.magnitude - a.magnitude)
        }
    }

    static func - (a: BigInt, b: BigInt) -> BigInt {
        return a + BigInt(negative: !b.negative, magnitude: b.magnitude)
    }

    static func * (a: BigInt, b: BigInt) -> BigInt {
        return BigInt(negative: a.negative != b.negative, magnitude: a.magnitude * b.magnitude)
    }

    static func < (a: BigInt, b: BigInt) -> Bool {
        if a.negative && !b.negative { return true }
        if !a.negative && b.negative { return false }
        if a.negative && b.negative {
            return BigUInt.compare(a.magnitude, b.magnitude) > 0
        }
        return BigUInt.compare(a.magnitude, b.magnitude) < 0
    }

    static func == (a: BigInt, b: BigInt) -> Bool {
        if a.isZero && b.isZero { return true }
        return a.negative == b.negative && BigUInt.compare(a.magnitude, b.magnitude) == 0
    }

    static func <= (a: BigInt, b: BigInt) -> Bool { return a < b || a == b }
    static func >= (a: BigInt, b: BigInt) -> Bool { return !(a < b) }
    static func > (a: BigInt, b: BigInt) -> Bool { return !(a <= b) }
}

// MARK: - Decimal parsing and operations

struct DecimalVal {
    var value: BigInt
    var scale: Int
}

func parseDecimal(_ s: String) -> DecimalVal {
    var negative = false
    var str = s
    if str.hasPrefix("-") {
        negative = true
        str = String(str.dropFirst())
    }

    let parts = str.split(separator: ".", maxSplits: 1, omittingEmptySubsequences: false)
    let intPart: String
    let fracPart: String
    if parts.count == 1 {
        intPart = String(parts[0])
        fracPart = ""
    } else {
        intPart = String(parts[0])
        fracPart = String(parts[1])
    }

    let digits = intPart + fracPart
    let mag = BigUInt(fromString: digits)
    let val = BigInt(negative: negative, magnitude: mag)
    return DecimalVal(value: val, scale: fracPart.count)
}

func pow10(_ n: Int) -> BigUInt {
    if n == 0 { return BigUInt(1) }
    var result = BigUInt(1)
    let ten = BigUInt(10)
    for _ in 0..<n {
        result = result * ten
    }
    return result
}

func roundToMinor(_ d: DecimalVal, minor: Int) -> BigInt {
    if d.value.isZero { return .zero }
    if d.scale <= minor {
        let factor = pow10(minor - d.scale)
        return BigInt(negative: d.value.negative, magnitude: d.value.magnitude * factor)
    } else {
        let divisor = pow10(d.scale - minor)
        let (q, r) = BigUInt.divmod(d.value.magnitude, divisor)
        let doubleR = r * BigUInt(2)
        let cmp = BigUInt.compare(doubleR, divisor)
        var result: BigUInt
        if cmp > 0 {
            result = q + BigUInt(1)
        } else if cmp < 0 {
            result = q
        } else {
            if q.isOdd() {
                result = q + BigUInt(1)
            } else {
                result = q
            }
        }
        return BigInt(negative: d.value.negative && !result.isZero, magnitude: result)
    }
}

func roundDiv(_ numeratorMag: BigUInt, _ denominator: BigUInt, negative: Bool) -> BigInt {
    if numeratorMag.isZero { return .zero }
    let (q, r) = BigUInt.divmod(numeratorMag, denominator)
    let doubleR = r * BigUInt(2)
    let cmp = BigUInt.compare(doubleR, denominator)
    var result: BigUInt
    if cmp > 0 {
        result = q + BigUInt(1)
    } else if cmp < 0 {
        result = q
    } else {
        if q.isOdd() {
            result = q + BigUInt(1)
        } else {
            result = q
        }
    }
    return BigInt(negative: negative && !result.isZero, magnitude: result)
}

// MARK: - Money formatting

func formatMoney(_ balance: BigInt, minor: Int) -> String {
    if balance.isZero {
        if minor == 0 { return "0" }
        return "0." + String(repeating: "0", count: minor)
    }

    let prefix = balance.negative ? "-" : ""
    let absVal = balance.magnitude

    let divisor = pow10(minor)
    let (intPart, fracPart) = BigUInt.divmod(absVal, divisor)

    let intStr = intPart.toString()
    var formatted = ""
    let chars = Array(intStr)
    for i in 0..<chars.count {
        if i > 0 && (chars.count - i) % 3 == 0 {
            formatted += ","
        }
        formatted.append(chars[i])
    }

    if minor == 0 {
        return prefix + formatted
    }

    let fracStr = fracPart.toString()
    let paddedFrac = String(repeating: "0", count: minor - fracStr.count) + fracStr

    return prefix + formatted + "." + paddedFrac
}

// MARK: - Main program

let args = CommandLine.arguments
let dir = args[1]
let path = dir + "/ledger.txt"
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
struct AccountInfo {
    var currency: String
    var balance: BigInt
    var limit: BigInt
}
var accounts: [String: AccountInfo] = [:]
var rejections: [(Int, String)] = []

for (idx, line) in lines.enumerated() {
    let lineNum = idx + 1
    let trimmed = line.trimmingCharacters(in: CharacterSet(charactersIn: " \t"))

    // Check blank or comment
    if trimmed.isEmpty { continue }
    if trimmed.first == "#" { continue }

    let fields = trimmed.split(separator: " ", omittingEmptySubsequences: true).map { String($0) }
    if fields.isEmpty { continue }

    let cmd = fields[0]

    switch cmd {
    case "currency":
        let code = fields[1]
        let minor = Int(fields[2])!
        currencies[code] = minor

    case "open":
        let name = fields[1]
        let code = fields[2]
        if accounts[name] != nil {
            rejections.append((lineNum, "account exists \(name)"))
            continue
        }
        let minor = currencies[code]!
        var limit: BigInt = .zero
        if fields.count > 3 {
            let limitDec = parseDecimal(fields[3])
            limit = roundToMinor(limitDec, minor: minor)
            if limit.negative {
                limit = BigInt(negative: false, magnitude: limit.magnitude)
            }
        }
        accounts[name] = AccountInfo(currency: code, balance: .zero, limit: limit)

    case "deposit":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.currency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        accounts[name]!.balance = accounts[name]!.balance + rounded

    case "withdraw":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.currency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBalance = accounts[name]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[name]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(name)"))
            continue
        }
        accounts[name]!.balance = newBalance

    case "transfer":
        let from = fields[1]
        let to = fields[2]
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        if accounts[to] == nil {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        if accounts[from]!.currency != accounts[to]!.currency {
            rejections.append((lineNum, "currency mismatch"))
            continue
        }
        let minor = currencies[accounts[from]!.currency]!
        let amount = parseDecimal(fields[3])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        accounts[from]!.balance = newBalance
        accounts[to]!.balance = accounts[to]!.balance + rounded

    case "convert":
        let from = fields[1]
        let to = fields[2]
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        if accounts[to] == nil {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        let fromMinor = currencies[accounts[from]!.currency]!
        let toMinor = currencies[accounts[to]!.currency]!
        let amount = parseDecimal(fields[3])
        let rounded = roundToMinor(amount, minor: fromMinor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let rate = parseDecimal(fields[4])

        // Check insufficient funds
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        // Compute: rounded * rate * 10^toMinor / 10^(fromMinor + rate.scale)
        let numMag = rounded.magnitude * rate.value.magnitude * pow10(toMinor)
        let den = pow10(fromMinor + rate.scale)
        let result = roundDiv(numMag, den, negative: rate.value.negative)

        accounts[from]!.balance = newBalance
        accounts[to]!.balance = accounts[to]!.balance + result

    case "interest":
        let name = fields[1]
        if accounts[name] == nil {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let rate = parseDecimal(fields[2])
        let balance = accounts[name]!.balance

        // interest = round_half_even(balance * rateValue, 10^rate.scale)
        let numMag = balance.magnitude * rate.value.magnitude
        let den = pow10(rate.scale)
        let isNeg = (balance.negative != rate.value.negative)
        let interest = roundDiv(numMag, den, negative: isNeg)
        accounts[name]!.balance = balance + interest

    case "split":
        let from = fields[1]
        // Parse targets: fields[3], fields[4], ... are "name:weight"
        var targets: [(name: String, weight: BigUInt)] = []
        for i in 3..<fields.count {
            let parts = fields[i].split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
            let tName = String(parts[0])
            let tWeight = BigUInt(fromString: String(parts[1]))
            targets.append((name: tName, weight: tWeight))
        }

        // Check accounts exist (from first, then targets in order)
        if accounts[from] == nil {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        var unknownFound = false
        for t in targets {
            if accounts[t.name] == nil {
                rejections.append((lineNum, "unknown account \(t.name)"))
                unknownFound = true
                break
            }
        }
        if unknownFound { continue }

        // Check currency mismatch
        let fromCurrency = accounts[from]!.currency
        for t in targets {
            if accounts[t.name]!.currency != fromCurrency {
                rejections.append((lineNum, "currency mismatch"))
                unknownFound = true
                break
            }
        }
        if unknownFound { continue }

        let minor = currencies[fromCurrency]!
        let amount = parseDecimal(fields[2])
        let rounded = roundToMinor(amount, minor: minor)
        if rounded <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }

        // Check insufficient funds
        let newBalance = accounts[from]!.balance - rounded
        let minBal = BigInt(negative: true, magnitude: accounts[from]!.limit.magnitude)
        if newBalance < minBal {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        // Distribute
        let A = rounded.magnitude // BigUInt, positive
        var W = BigUInt(0)
        for t in targets {
            W = W + t.weight
        }

        var bases: [BigUInt] = []
        var remainders: [BigUInt] = []
        var sumBases = BigUInt(0)

        for t in targets {
            let product = A * t.weight
            let (q, r) = BigUInt.divmod(product, W)
            bases.append(q)
            remainders.append(r)
            sumBases = sumBases + q
        }

        let leftover = A - sumBases
        let leftoverCount = Int(leftover.limbs[0]) // leftover < number of targets, fits in Int

        // Sort indices by remainder descending, ties by original order
        let n = targets.count
        var indices = Array(0..<n)
        indices.sort { i, j in
            let cmp = BigUInt.compare(remainders[i], remainders[j])
            if cmp != 0 { return cmp > 0 }
            return i < j
        }

        // Apply distribution
        accounts[from]!.balance = newBalance
        for idx in 0..<leftoverCount {
            bases[indices[idx]] = bases[indices[idx]] + BigUInt(1)
        }
        for i in 0..<n {
            accounts[targets[i].name]!.balance = accounts[targets[i].name]!.balance + BigInt(negative: false, magnitude: bases[i])
        }

    default:
        break
    }
}

// MARK: - Output

// Rejections
for (lineNum, reason) in rejections {
    print("line \(lineNum): REJECT \(reason)")
}

// Blank line
print("")

// Accounts sorted by name (byte-wise ascending)
let sortedAccounts = accounts.keys.sorted { a, b in
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    let minLen = min(aBytes.count, bBytes.count)
    for i in 0..<minLen {
        if aBytes[i] != bBytes[i] { return aBytes[i] < bBytes[i] }
    }
    return aBytes.count < bBytes.count
}

for name in sortedAccounts {
    let acct = accounts[name]!
    let minor = currencies[acct.currency]!
    let balStr = formatMoney(acct.balance, minor: minor)
    print("\(name) \(acct.currency) \(balStr)")
}

// Blank line
print("")

// Totals per currency
var currencyTotals: [String: (BigInt, Int)] = [:]
for (_, acct) in accounts {
    let code = acct.currency
    if currencyTotals[code] == nil {
        currencyTotals[code] = (.zero, 0)
    }
    currencyTotals[code]!.0 = currencyTotals[code]!.0 + acct.balance
    currencyTotals[code]!.1 += 1
}

let sortedCurrencies = currencyTotals.keys.sorted { a, b in
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    let minLen = min(aBytes.count, bBytes.count)
    for i in 0..<minLen {
        if aBytes[i] != bBytes[i] { return aBytes[i] < bBytes[i] }
    }
    return aBytes.count < bBytes.count
}

for code in sortedCurrencies {
    let (total, count) = currencyTotals[code]!
    let minor = currencies[code]!
    let totalStr = formatMoney(total, minor: minor)
    print("total \(code) \(totalStr) (\(count) accounts)")
}

exit(0)

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::{SystemTime, UNIX_EPOCH};

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap();

    let queries_path = format!("{}/queries.txt", dir);
    let content = fs::read_to_string(&queries_path).unwrap();

    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .subsec_nanos() as u16;
    let mut id_counter = seed;

    for line in content.lines() {
        let trimmed_line = line.trim();
        if trimmed_line.is_empty() {
            continue;
        }

        let parts: Vec<&str> = trimmed_line.split(' ').collect();
        if parts.len() != 2 {
            continue;
        }

        let name = parts[0];
        let qtype_str = parts[1];
        let qtype = type_str_to_num(qtype_str);

        id_counter = id_counter.wrapping_add(1);
        let id = id_counter;

        let query = build_query(id, name, qtype);
        let addr = format!("127.0.0.1:{}", port);

        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.connect(&addr).unwrap();
        socket.send(&query).unwrap();

        let mut buf = vec![0u8; 65535];
        let mut response = None;
        loop {
            let n = socket.recv(&mut buf).unwrap();
            if n >= 12 {
                let resp_id = u16::from_be_bytes([buf[0], buf[1]]);
                let flags = u16::from_be_bytes([buf[2], buf[3]]);
                let qr = (flags >> 15) & 1;
                if qr == 1 && resp_id == id {
                    response = Some(buf[..n].to_vec());
                    break;
                }
            }
        }

        let mut resp = response.unwrap();

        let flags = u16::from_be_bytes([resp[2], resp[3]]);
        let tc = (flags >> 9) & 1;

        if tc == 1 {
            let mut stream = TcpStream::connect(&addr).unwrap();
            let len_bytes = (query.len() as u16).to_be_bytes();
            stream.write_all(&len_bytes).unwrap();
            stream.write_all(&query).unwrap();
            stream.flush().unwrap();

            let mut len_buf = [0u8; 2];
            stream.read_exact(&mut len_buf).unwrap();
            let resp_len = u16::from_be_bytes(len_buf) as usize;
            let mut tcp_buf = vec![0u8; resp_len];
            let mut total = 0;
            while total < resp_len {
                let n = stream.read(&mut tcp_buf[total..]).unwrap();
                if n == 0 {
                    break;
                }
                total += n;
            }
            resp = tcp_buf[..total].to_vec();
        }

        let out_name = normalize_name(name);
        let (rcode, records) = parse_response(&resp);
        let rcode_str = rcode_to_str(rcode);
        println!("{} {} {}", out_name, qtype_str, rcode_str);

        for (owner, ttl, rtype, rdata_offset, rdlength) in &records {
            print_record(&resp, owner, *ttl, *rtype, *rdata_offset, *rdlength);
        }
    }
}

fn build_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut msg = Vec::new();

    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&0x0100u16.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());

    let trimmed = if name.ends_with('.') {
        &name[..name.len() - 1]
    } else {
        name
    };

    if !trimmed.is_empty() {
        for label in trimmed.split('.') {
            msg.push(label.len() as u8);
            msg.extend_from_slice(label.as_bytes());
        }
    }
    msg.push(0);

    msg.extend_from_slice(&qtype.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());

    msg
}

fn parse_name(msg: &[u8], offset: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = offset;
    let mut end_pos: Option<usize> = None;
    let mut loop_count = 0;

    loop {
        loop_count += 1;
        if loop_count > 128 || pos >= msg.len() {
            break;
        }

        let len = msg[pos];

        if len & 0xC0 == 0xC0 {
            if end_pos.is_none() {
                end_pos = Some(pos + 2);
            }
            let ptr = ((len as usize & 0x3F) << 8) | msg[pos + 1] as usize;
            pos = ptr;
        } else if len == 0 {
            if end_pos.is_none() {
                end_pos = Some(pos + 1);
            }
            break;
        } else {
            let label = String::from_utf8_lossy(&msg[pos + 1..pos + 1 + len as usize])
                .to_lowercase();
            labels.push(label);
            pos += 1 + len as usize;
            if end_pos.is_none() {
                end_pos = Some(pos);
            }
        }
    }

    let name = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    };

    (name, end_pos.unwrap_or(pos))
}

fn parse_response(msg: &[u8]) -> (u16, Vec<(String, u32, u16, usize, usize)>) {
    let rcode = (u16::from_be_bytes([msg[2], msg[3]])) & 0x0F;
    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let mut pos = 12;

    for _ in 0..qdcount {
        let (_, new_pos) = parse_name(msg, pos);
        pos = new_pos;
        pos += 4;
    }

    let mut records = Vec::new();
    for _ in 0..ancount {
        let (owner, new_pos) = parse_name(msg, pos);
        pos = new_pos;

        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        pos += 2;
        pos += 2; // CLASS
        let ttl = u32::from_be_bytes([msg[pos], msg[pos + 1], msg[pos + 2], msg[pos + 3]]);
        pos += 4;
        let rdlength = u16::from_be_bytes([msg[pos], msg[pos + 1]]) as usize;
        pos += 2;
        let rdata_offset = pos;
        pos += rdlength;

        records.push((owner, ttl, rtype, rdata_offset, rdlength));
    }

    (rcode, records)
}

fn print_record(msg: &[u8], owner: &str, ttl: u32, rtype: u16, rdata_offset: usize, rdlength: usize) {
    let rdata = &msg[rdata_offset..rdata_offset + rdlength];

    match rtype {
        1 => {
            let ip = format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3]);
            println!("  {} {} A {}", owner, ttl, ip);
        }
        28 => {
            let ip = format_ipv6(rdata);
            println!("  {} {} AAAA {}", owner, ttl, ip);
        }
        5 => {
            let (target, _) = parse_name(msg, rdata_offset);
            println!("  {} {} CNAME {}", owner, ttl, target);
        }
        15 => {
            let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
            let (exchange, _) = parse_name(msg, rdata_offset + 2);
            println!("  {} {} MX {} {}", owner, ttl, pref, exchange);
        }
        16 => {
            let txt = format_txt(rdata);
            println!("  {} {} TXT {}", owner, ttl, txt);
        }
        _ => {
            let type_str = format!("TYPE{}", rtype);
            let data = format_generic(rdata);
            println!("  {} {} {} {}", owner, ttl, type_str, data);
        }
    }
}

fn format_ipv6(bytes: &[u8]) -> String {
    let mut groups = [0u16; 8];
    for i in 0..8 {
        groups[i] = u16::from_be_bytes([bytes[i * 2], bytes[i * 2 + 1]]);
    }

    let mut best_start = usize::MAX;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len >= 2 && len > best_len {
                best_start = start;
                best_len = len;
            }
        } else {
            i += 1;
        }
    }

    if best_len >= 2 {
        let before: Vec<String> = (0..best_start).map(|i| format!("{:x}", groups[i])).collect();
        let after: Vec<String> = ((best_start + best_len)..8)
            .map(|i| format!("{:x}", groups[i]))
            .collect();
        format!("{}::{}", before.join(":"), after.join(":"))
    } else {
        let parts: Vec<String> = (0..8).map(|i| format!("{:x}", groups[i])).collect();
        parts.join(":")
    }
}

fn format_txt(rdata: &[u8]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut pos = 0;
    while pos < rdata.len() {
        let len = rdata[pos] as usize;
        pos += 1;
        let end = std::cmp::min(pos + len, rdata.len());
        let s = &rdata[pos..end];
        let mut quoted = String::from("\"");
        for &b in s {
            if b == b'"' {
                quoted.push_str("\\\"");
            } else if b == b'\\' {
                quoted.push_str("\\\\");
            } else if b >= 0x20 && b <= 0x7E {
                quoted.push(b as char);
            } else {
                quoted.push_str(&format!("\\{:03}", b));
            }
        }
        quoted.push('"');
        parts.push(quoted);
        pos = end;
    }
    parts.join(" ")
}

fn format_generic(rdata: &[u8]) -> String {
    if rdata.is_empty() {
        "\\# 0".to_string()
    } else {
        let hex: String = rdata.iter().map(|b| format!("{:02x}", b)).collect();
        format!("\\# {} {}", rdata.len(), hex)
    }
}

fn normalize_name(name: &str) -> String {
    let lower = name.to_lowercase();
    let trimmed = if lower.ends_with('.') {
        &lower[..lower.len() - 1]
    } else {
        &lower
    };
    if trimmed.is_empty() {
        ".".to_string()
    } else {
        trimmed.to_string()
    }
}

fn type_str_to_num(s: &str) -> u16 {
    match s {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn rcode_to_str(rcode: u16) -> String {
    match rcode {
        0 => "NOERROR".to_string(),
        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        _ => format!("RCODE{}", rcode),
    }
}

