    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let mut pos = 12;

    for _ in 0..qdcount {
        let (_, new_pos) = parse_name(msg, pos);
        pos = new_pos;
        pos += 4;
    }

    let mut records = Vec::new();
    for _ in 0..ancount {
        let (owner, new_pos) = parse_name(msg, pos);
        pos = new_pos;

        if pos + 10 > msg.len() {
            break;
        }
        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        pos += 2;
        pos += 2; // CLASS
        let ttl = u32::from_be_bytes([msg[pos], msg[pos + 1], msg[pos + 2], msg[pos + 3]]);
        pos += 4;
        let rdlength = u16::from_be_bytes([msg[pos], msg[pos + 1]]) as usize;
        pos += 2;
        let rdata_offset = pos;
        pos += rdlength;

        records.push((owner, ttl, rtype, rdata_offset, rdlength));
    }

    (rcode, records)
}

