fn normalize_name(name: &str) -> String {
    let lower = name.to_lowercase();
    let trimmed = if lower.ends_with('.') {
        &lower[..lower.len() - 1]
    } else {
        &lower
    };
    if trimmed.is_empty() {
        ".".to_string()
    } else {
        trimmed.to_string()
    }
}

fn type_str_to_num(s: &str) -> u16 {
    match s {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn rcode_to_str(rcode: u16) -> String {
    match rcode {
        0 => "NOERROR".to_string(),
        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        _ => format!("RCODE{}", rcode),
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ─── JSON Value Types ───────────────────────────────────────────────
    static abstract class JVal {
        enum Type { NULL, BOOLEAN, NUMBER, STRING, ARRAY, OBJECT }
        abstract Type type();
    }

    static final JVal JNULL = new JVal() { Type type() { return Type.NULL; } };

    static final class JBool extends JVal {
        final boolean v;
        JBool(boolean v) { this.v = v; }
        Type type() { return Type.BOOLEAN; }
    }

    static final class JNum extends JVal {
        final double v;
        JNum(double v) { this.v = v; }
        Type type() { return Type.NUMBER; }
        boolean isInt() { return v == Math.floor(v) && !Double.isInfinite(v); }
    }

    static final class JStr extends JVal {
        final String v;
        JStr(String v) { this.v = v; }
        Type type() { return Type.STRING; }
    }

    static final class JArr extends JVal {
        final List<JVal> el;
        JArr(List<JVal> el) { this.el = el; }
        Type type() { return Type.ARRAY; }
    }

    static final class JObj extends JVal {
        final LinkedHashMap<String, JVal> m;
        JObj(LinkedHashMap<String, JVal> m) { this.m = m; }
        Type type() { return Type.OBJECT; }
    }

    // ─── JSON Parser ────────────────────────────────────────────────────
    static final class Parser {
        final String s;
        int p;

        Parser(String s) { this.s = s; p = 0; }

        JVal parse() { skipWs(); JVal v = val(); skipWs(); return v; }

        void skipWs() {
            while (p < s.length()) {
                char c = s.charAt(p);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p++;
                else break;
            }
        }

        JVal val() {
            char c = s.charAt(p);
            if (c == '{') return obj();
            if (c == '[') return arr();
            if (c == '"') return str();
            if (c == 't') { p += 4; return new JBool(true); }
            if (c == 'f') { p += 5; return new JBool(false); }
            if (c == 'n') { p += 4; return JNULL; }
            return num();
        }

        JNum num() {
            int st = p;
            if (s.charAt(p) == '-') p++;
            while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++;
            if (p < s.length() && s.charAt(p) == '.') { p++; while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++; }
            if (p < s.length() && (s.charAt(p) == 'e' || s.charAt(p) == 'E')) {
                p++;
                if (p < s.length() && (s.charAt(p) == '+' || s.charAt(p) == '-')) p++;
                while (p < s.length() && s.charAt(p) >= '0' && s.charAt(p) <= '9') p++;
            }
            return new JNum(Double.parseDouble(s.substring(st, p)));
        }

        JStr str() {
            p++; // skip "
            StringBuilder sb = new StringBuilder();
            while (p < s.length()) {
                char c = s.charAt(p);
                if (c == '"') { p++; break; }
                if (c == '\\') {
                    p++;
                    char e = s.charAt(p); p++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(s.substring(p, p + 4), 16); p += 4;
                            if (Character.isHighSurrogate((char) hi) && p + 1 < s.length()
                                    && s.charAt(p) == '\\' && s.charAt(p + 1) == 'u') {
                                p += 2;
                                int lo = Integer.parseInt(s.substring(p, p + 4), 16); p += 4;
                                sb.append((char) hi);
                                sb.append((char) lo);
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c); p++;
                }
            }
            return new JStr(sb.toString());
        }

        JArr arr() {
            p++; // [
            List<JVal> list = new ArrayList<>();
            skipWs();
            if (p < s.length() && s.charAt(p) == ']') { p++; return new JArr(list); }
            while (true) {
                skipWs(); list.add(val()); skipWs();
                if (s.charAt(p) == ',') p++; else break;
            }
            p++; // ]
            return new JArr(list);
        }

        JObj obj() {
            p++; // {
            LinkedHashMap<String, JVal> map = new LinkedHashMap<>();
            skipWs();
            if (p < s.length() && s.charAt(p) == '}') { p++; return new JObj(map); }
            while (true) {
                skipWs();
                JStr k = str();
                skipWs(); p++; // :
                skipWs();
                map.put(k.v, val());
                skipWs();
                if (s.charAt(p) == ',') p++; else break;
            }
            p++; // }
            return new JObj(map);
        }
    }

    // ─── Deep Equality ──────────────────────────────────────────────────
    static boolean deepEq(JVal a, JVal b) {
        if (a.type() != b.type()) return false;
        switch (a.type()) {
            case NULL: return true;
            case BOOLEAN: return ((JBool) a).v == ((JBool) b).v;
            case NUMBER: return ((JNum) a).v == ((JNum) b).v;
            case STRING: return ((JStr) a).v.equals(((JStr) b).v);
            case ARRAY: {
                List<JVal> la = ((JArr) a).el, lb = ((JArr) b).el;
                if (la.size() != lb.size()) return false;
                for (int i = 0; i < la.size(); i++) if (!deepEq(la.get(i), lb.get(i))) return false;
                return true;
            }
            case OBJECT: {
                LinkedHashMap<String, JVal> ma = ((JObj) a).m, mb = ((JObj) b).m;
                if (ma.size() != mb.size()) return false;
                for (Map.Entry<String, JVal> e : ma.entrySet()) {
                    JVal bv = mb.get(e.getKey());
                    if (bv == null || !deepEq(e.getValue(), bv)) return false;
                }
                return true;
            }
        }
        return false;
    }

    // ─── Error ──────────────────────────────────────────────────────────
    static final class Err {
        final String il, sl;
        Err(String il, String sl) { this.il = il; this.sl = sl; }
        @Override public boolean equals(Object o) {
            if (!(o instanceof Err)) return false;
            Err e = (Err) o; return il.equals(e.il) && sl.equals(e.sl);
        }
        @Override public int hashCode() { return Objects.hash(il, sl); }
    }

    static int cmpBytes(String a, String b) {
        byte[] ba = a.getBytes(StandardCharsets.UTF_8);
        byte[] bb = b.getBytes(StandardCharsets.UTF_8);
        int n = Math.min(ba.length, bb.length);
        for (int i = 0; i < n; i++) {
            int d = (ba[i] & 0xFF) - (bb[i] & 0xFF);
            if (d != 0) return d;
        }
        return ba.length - bb.length;
    }

    // ─── $ref Resolution ────────────────────────────────────────────────
    static JVal rootSchema;

    static String unescTok(String t) { return t.replace("~1", "/").replace("~0", "~"); }
    static String escTok(String s) { return s.replace("~", "~0").replace("/", "~1"); }

    static JVal resolveRef(String ref) {
        if (ref.equals("#")) return rootSchema;
        if (ref.startsWith("#/$defs/")) {
            String name = unescTok(ref.substring("#/$defs/".length()));
            if (rootSchema.type() == JVal.Type.OBJECT) {
                JVal defs = ((JObj) rootSchema).m.get("$defs");
                if (defs != null && defs.type() == JVal.Type.OBJECT)
                    return ((JObj) defs).m.get(name);
            }
        }
        return null;
    }

    static String refLoc(String ref) {
        if (ref.equals("#")) return "#";
        if (ref.startsWith("#/$defs/")) {
            String name = unescTok(ref.substring("#/$defs/".length()));
            return "#/$defs/" + escTok(name);
        }
        return ref;
    }

    // ─── Validation ─────────────────────────────────────────────────────
    static boolean accepts(JVal inst, JVal sch, String il, String sl) {
        Set<Err> errs = new HashSet<>();
        validate(inst, sch, il, sl, errs);
        return errs.isEmpty();
    }

    static void validate(JVal inst, JVal sch, String il, String sl, Set<Err> errs) {
        if (sch.type() == JVal.Type.BOOLEAN) {
            if (!((JBool) sch).v) errs.add(new Err(il, sl));
            return;
        }
        if (sch.type() != JVal.Type.OBJECT) return;
        JObj so = (JObj) sch;

        // type
        if (so.m.containsKey("type")) {
            if (!chkType(inst, so.m.get("type")))
                errs.add(new Err(il, sl + "/type"));
        }

        // enum
        if (so.m.containsKey("enum")) {
            JVal ev = so.m.get("enum");
            if (ev.type() == JVal.Type.ARRAY) {
                boolean ok = false;
                for (JVal e : ((JArr) ev).el) if (deepEq(inst, e)) { ok = true; break; }
                if (!ok) errs.add(new Err(il, sl + "/enum"));
            }
        }

        // const
        if (so.m.containsKey("const")) {
            if (!deepEq(inst, so.m.get("const")))
                errs.add(new Err(il, sl + "/const"));
        }

        // number keywords
        if (inst.type() == JVal.Type.NUMBER) {
            double nv = ((JNum) inst).v;
            if (so.m.containsKey("minimum")) {
                JVal v = so.m.get("minimum");
                if (v.type() == JVal.Type.NUMBER && nv < ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minimum"));
            }
            if (so.m.containsKey("maximum")) {
                JVal v = so.m.get("maximum");
                if (v.type() == JVal.Type.NUMBER && nv > ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maximum"));
            }
            if (so.m.containsKey("exclusiveMinimum")) {
                JVal v = so.m.get("exclusiveMinimum");
                if (v.type() == JVal.Type.NUMBER && nv <= ((JNum) v).v)
                    errs.add(new Err(il, sl + "/exclusiveMinimum"));
            }
            if (so.m.containsKey("exclusiveMaximum")) {
                JVal v = so.m.get("exclusiveMaximum");
                if (v.type() == JVal.Type.NUMBER && nv >= ((JNum) v).v)
                    errs.add(new Err(il, sl + "/exclusiveMaximum"));
            }
        }

        // string keywords
        if (inst.type() == JVal.Type.STRING) {
            String sv = ((JStr) inst).v;
            int len = sv.codePointCount(0, sv.length());
            if (so.m.containsKey("minLength")) {
                JVal v = so.m.get("minLength");
                if (v.type() == JVal.Type.NUMBER && len < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minLength"));
            }
            if (so.m.containsKey("maxLength")) {
                JVal v = so.m.get("maxLength");
                if (v.type() == JVal.Type.NUMBER && len > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxLength"));
            }
        }

        // array keywords
        if (inst.type() == JVal.Type.ARRAY) {
            List<JVal> el = ((JArr) inst).el;
            if (so.m.containsKey("minItems")) {
                JVal v = so.m.get("minItems");
                if (v.type() == JVal.Type.NUMBER && el.size() < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minItems"));
            }
            if (so.m.containsKey("maxItems")) {
                JVal v = so.m.get("maxItems");
                if (v.type() == JVal.Type.NUMBER && el.size() > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxItems"));
            }
            if (so.m.containsKey("uniqueItems")) {
                JVal v = so.m.get("uniqueItems");
                if (v.type() == JVal.Type.BOOLEAN && ((JBool) v).v) {
                    boolean uniq = true;
                    outer:
                    for (int i = 0; i < el.size(); i++)
                        for (int j = i + 1; j < el.size(); j++)
                            if (deepEq(el.get(i), el.get(j))) { uniq = false; break outer; }
                    if (!uniq) errs.add(new Err(il, sl + "/uniqueItems"));
                }
            }
            int pLen = 0;
            if (so.m.containsKey("prefixItems")) {
                JVal pi = so.m.get("prefixItems");
                if (pi.type() == JVal.Type.ARRAY) {
                    List<JVal> ps = ((JArr) pi).el;
                    pLen = ps.size();
                    for (int i = 0; i < Math.min(el.size(), ps.size()); i++)
                        validate(el.get(i), ps.get(i), il + "/" + i, sl + "/prefixItems/" + i, errs);
                }
            }
            if (so.m.containsKey("items")) {
                JVal is = so.m.get("items");
                for (int i = pLen; i < el.size(); i++)
                    validate(el.get(i), is, il + "/" + i, sl + "/items", errs);
            }
        }

        // object keywords
        if (inst.type() == JVal.Type.OBJECT) {
            LinkedHashMap<String, JVal> mem = ((JObj) inst).m;
            if (so.m.containsKey("minProperties")) {
                JVal v = so.m.get("minProperties");
                if (v.type() == JVal.Type.NUMBER && mem.size() < (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/minProperties"));
            }
            if (so.m.containsKey("maxProperties")) {
                JVal v = so.m.get("maxProperties");
                if (v.type() == JVal.Type.NUMBER && mem.size() > (int) ((JNum) v).v)
                    errs.add(new Err(il, sl + "/maxProperties"));
            }
            if (so.m.containsKey("required")) {
                JVal rq = so.m.get("required");
                if (rq.type() == JVal.Type.ARRAY) {
                    List<JVal> rl = ((JArr) rq).el;
                    for (int j = 0; j < rl.size(); j++) {
                        if (rl.get(j).type() == JVal.Type.STRING) {
                            if (!mem.containsKey(((JStr) rl.get(j)).v))
                                errs.add(new Err(il, sl + "/required/" + j));
                        }
                    }
                }
            }
            Set<String> pn = new HashSet<>();
            if (so.m.containsKey("properties")) {
                JVal pr = so.m.get("properties");
                if (pr.type() == JVal.Type.OBJECT) {
                    for (Map.Entry<String, JVal> e : ((JObj) pr).m.entrySet()) {
                        pn.add(e.getKey());
                        if (mem.containsKey(e.getKey()))
                            validate(mem.get(e.getKey()), e.getValue(),
                                    il + "/" + escTok(e.getKey()),
                                    sl + "/properties/" + escTok(e.getKey()), errs);
                    }
                }
            }
            if (so.m.containsKey("additionalProperties")) {
                JVal ap = so.m.get("additionalProperties");
                for (Map.Entry<String, JVal> e : mem.entrySet()) {
                    if (!pn.contains(e.getKey()))
                        validate(e.getValue(), ap,
                                il + "/" + escTok(e.getKey()),
                                sl + "/additionalProperties", errs);
                }
            }
        }

        // allOf
        if (so.m.containsKey("allOf")) {
            JVal ao = so.m.get("allOf");
            if (ao.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) ao).el;
                for (int i = 0; i < subs.size(); i++)
                    validate(inst, subs.get(i), il, sl + "/allOf/" + i, errs);
            }
        }

        // anyOf
        if (so.m.containsKey("anyOf")) {
            JVal ao = so.m.get("anyOf");
            if (ao.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) ao).el;
                boolean any = false;
                for (JVal sub : subs) {
                    if (accepts(inst, sub, il, sl + "/anyOf/0")) { any = true; break; }
                }
                if (!any) errs.add(new Err(il, sl + "/anyOf"));
            }
        }

        // oneOf
        if (so.m.containsKey("oneOf")) {
            JVal oo = so.m.get("oneOf");
            if (oo.type() == JVal.Type.ARRAY) {
                List<JVal> subs = ((JArr) oo).el;
                int cnt = 0;
                for (JVal sub : subs) {
                    if (accepts(inst, sub, il, sl + "/oneOf/0")) cnt++;
                }
                if (cnt != 1) errs.add(new Err(il, sl + "/oneOf"));
            }
        }

        // not
        if (so.m.containsKey("not")) {
            if (accepts(inst, so.m.get("not"), il, sl + "/not"))
                errs.add(new Err(il, sl + "/not"));
        }

        // if / then / else
        if (so.m.containsKey("if")) {
            boolean ifOk = accepts(inst, so.m.get("if"), il, sl + "/if");
            if (ifOk && so.m.containsKey("then"))
                validate(inst, so.m.get("then"), il, sl + "/then", errs);
            else if (!ifOk && so.m.containsKey("else"))
                validate(inst, so.m.get("else"), il, sl + "/else", errs);
        }

        // $ref
        if (so.m.containsKey("$ref")) {
            JVal rv = so.m.get("$ref");
            if (rv.type() == JVal.Type.STRING) {
                String ref = ((JStr) rv).v;
                JVal resolved = resolveRef(ref);
                if (resolved != null)
                    validate(inst, resolved, il, refLoc(ref), errs);
            }
        }
    }

    static boolean chkType(JVal inst, JVal tv) {
        if (tv.type() == JVal.Type.STRING) return matchT(inst, ((JStr) tv).v);
        if (tv.type() == JVal.Type.ARRAY) {
            for (JVal t : ((JArr) tv).el)
                if (t.type() == JVal.Type.STRING && matchT(inst, ((JStr) t).v)) return true;
            return false;
        }
        return true;
    }

    static boolean matchT(JVal inst, String tn) {
        switch (tn) {
            case "null":    return inst.type() == JVal.Type.NULL;
            case "boolean": return inst.type() == JVal.Type.BOOLEAN;
            case "number":  return inst.type() == JVal.Type.NUMBER;
            case "integer": return inst.type() == JVal.Type.NUMBER && ((JNum) inst).isInt();
            case "string":  return inst.type() == JVal.Type.STRING;
            case "array":   return inst.type() == JVal.Type.ARRAY;
            case "object":  return inst.type() == JVal.Type.OBJECT;
            default:        return true;
        }
    }

    // ─── Main ───────────────────────────────────────────────────────────
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schemaStr = new String(Files.readAllBytes(Paths.get(dir, "schema.json")), StandardCharsets.UTF_8);
        String instStr = new String(Files.readAllBytes(Paths.get(dir, "instances.json")), StandardCharsets.UTF_8);

        rootSchema = new Parser(schemaStr).parse();
        JVal instsVal = new Parser(instStr).parse();
        List<JVal> insts = ((JArr) instsVal).el;

        int vc = 0, ic = 0;
        for (int n = 0; n < insts.size(); n++) {
            Set<Err> errs = new HashSet<>();
            validate(insts.get(n), rootSchema, "#", "#", errs);
            if (errs.isEmpty()) {
                System.out.println(n + ": valid");
                vc++;
            } else {
                List<Err> sorted = new ArrayList<>(errs);
                sorted.sort((a, b) -> {
                    int c = cmpBytes(a.il, b.il);
                    return c != 0 ? c : cmpBytes(a.sl, b.sl);
                });
                System.out.println(n + ": invalid (" + sorted.size() + ")");
                for (Err e : sorted)
                    System.out.println("  " + e.il + " " + e.sl);
                ic++;
            }
        }
        System.out.println("valid=" + vc + " invalid=" + ic);
    }
}

use std::collections::HashMap;
use std::cmp::Ordering;
use std::env;
use std::fs;

#[derive(Clone, Debug)]
struct BigDecimal {
    negative: bool,
    digits: Vec<u8>,
    scale: usize,
}

fn normalize(mut digits: Vec<u8>) -> Vec<u8> {
    while digits.len() > 1 && *digits.last().unwrap() == 0 {
        digits.pop();
    }
    digits
}

fn is_zero(digits: &[u8]) -> bool {
    digits.iter().all(|&d| d == 0)
}

fn bigint_cmp(a: &[u8], b: &[u8]) -> Ordering {
    let a = normalize(a.to_vec());
    let b = normalize(b.to_vec());
    if a.len() != b.len() {
        return a.len().cmp(&b.len());
    }
    for i in (0..a.len()).rev() {
        if a[i] != b[i] {
            return a[i].cmp(&b[i]);
        }
    }
    Ordering::Equal
}

fn bigint_add(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut carry = 0u8;
    let max_len = a.len().max(b.len());
    for i in 0..max_len {
        let da = if i < a.len() { a[i] } else { 0 };
        let db = if i < b.len() { b[i] } else { 0 };
        let sum = da + db + carry;
        result.push(sum % 10);
        carry = sum / 10;
    }
    if carry > 0 {
        result.push(carry);
    }
    normalize(result)
}

fn bigint_sub(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut borrow = 0i8;
    for i in 0..a.len() {
        let da = a[i] as i8;
        let db = if i < b.len() { b[i] as i8 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        result.push(diff as u8);
    }
    normalize(result)
}

fn bigint_mul(a: &[u8], b: &[u8]) -> Vec<u8> {
    if is_zero(a) || is_zero(b) {
        return vec![0];
    }
    let mut result = vec![0u8; a.len() + b.len()];
    for i in 0..a.len() {
        if a[i] == 0 {
            continue;
        }
        let mut carry = 0u32;
        for j in 0..b.len() {
            let prod = result[i + j] as u32 + (a[i] as u32) * (b[j] as u32) + carry;
            result[i + j] = (prod % 10) as u8;
            carry = prod / 10;
        }
        let mut pos = i + b.len();
        while carry > 0 {
            let sum = result[pos] as u32 + carry;
            result[pos] = (sum % 10) as u8;
            carry = sum / 10;
            pos += 1;
        }
    }
    normalize(result)
}

fn bigint_divmod(a: &[u8], b: &[u8]) -> (Vec<u8>, Vec<u8>) {
    let a = normalize(a.to_vec());
    let b = normalize(b.to_vec());
    if is_zero(&a) {
        return (vec![0], vec![0]);
    }
    if is_zero(&b) {
        panic!("division by zero");
    }
    if bigint_cmp(&a, &b) == Ordering::Less {
        return (vec![0], a);
    }
    let mut quotient = vec![0u8; a.len()];
    let mut remainder: Vec<u8> = vec![0];
    for i in (0..a.len()).rev() {
        remainder.insert(0, 0);
        remainder[0] = a[i];
        remainder = normalize(remainder);
        let mut q = 0u8;
        let mut prod = vec![0u8];
        loop {
            let next_prod = bigint_add(&prod, &b);
            if bigint_cmp(&next_prod, &remainder) == Ordering::Greater {
                break;
            }
            prod = next_prod;
            q += 1;
            if q == 10 {
                q = 9;
                break;
            }
        }
        quotient[i] = q;
        if q > 0 {
            remainder = bigint_sub(&remainder, &prod);
        }
    }
    (normalize(quotient), normalize(remainder))
}

fn pow10(n: usize) -> Vec<u8> {
    if n == 0 {
        return vec![1];
    }
    let mut result = vec![0u8; n + 1];
    result[n] = 1;
    result
}

fn bd_zero(scale: usize) -> BigDecimal {
    BigDecimal {
        negative: false,
        digits: vec![0],
        scale,
    }
}

fn bd_rescale(a: &BigDecimal, new_scale: usize) -> BigDecimal {
    if new_scale == a.scale {
        return a.clone();
    }
    let diff = new_scale - a.scale;
    let multiplier = pow10(diff);
    let digits = bigint_mul(&a.digits, &multiplier);
    BigDecimal {
        negative: a.negative,
        digits,
        scale: new_scale,
    }
}

fn bd_add(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let max_scale = a.scale.max(b.scale);
    let a2 = bd_rescale(a, max_scale);
    let b2 = bd_rescale(b, max_scale);
    if a2.negative == b2.negative {
        let digits = bigint_add(&a2.digits, &b2.digits);
        if is_zero(&digits) {
            bd_zero(max_scale)
        } else {
            BigDecimal {
                negative: a2.negative,
                digits,
                scale: max_scale,
            }
        }
    } else {
        match bigint_cmp(&a2.digits, &b2.digits) {
            Ordering::Greater => {
                let digits = bigint_sub(&a2.digits, &b2.digits);
                if is_zero(&digits) {
                    bd_zero(max_scale)
                } else {
                    BigDecimal {
                        negative: a2.negative,
                        digits,
                        scale: max_scale,
                    }
                }
            }
            Ordering::Less => {
                let digits = bigint_sub(&b2.digits, &a2.digits);
                if is_zero(&digits) {
                    bd_zero(max_scale)
                } else {
                    BigDecimal {
                        negative: b2.negative,
                        digits,
                        scale: max_scale,
                    }
                }
            }
            Ordering::Equal => bd_zero(max_scale),
        }
    }
}

fn bd_sub(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let neg_b = if is_zero(&b.digits) {
        bd_zero(b.scale)
    } else {
        BigDecimal {
            negative: !b.negative,
            digits: b.digits.clone(),
            scale: b.scale,
        }
    };
    bd_add(a, &neg_b)
}

fn bd_mul(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let digits = bigint_mul(&a.digits, &b.digits);
    let negative = (a.negative != b.negative) && !is_zero(&digits);
    let scale = a.scale + b.scale;
    BigDecimal {
        negative,
        digits,
        scale,
    }
}

fn bd_round(a: &BigDecimal, target_scale: usize) -> BigDecimal {
    if a.scale <= target_scale {
        return bd_rescale(a, target_scale);
    }
    let k = a.scale - target_scale;
    let divisor = pow10(k);
    let (quotient, remainder) = bigint_divmod(&a.digits, &divisor);
    let half = {
        let mut h = vec![0u8; k];
        h[k - 1] = 5;
        h
    };
    let mut digits = quotient;
    match bigint_cmp(&remainder, &half) {
        Ordering::Greater => {
            digits = bigint_add(&digits, &[1]);
        }
        Ordering::Equal => {
            if digits[0] % 2 == 1 {
                digits = bigint_add(&digits, &[1]);
            }
        }
        Ordering::Less => {}
    }
    if is_zero(&digits) {
        bd_zero(target_scale)
    } else {
        BigDecimal {
            negative: a.negative,
            digits,
            scale: target_scale,
        }
    }
}

fn bd_neg(a: &BigDecimal) -> BigDecimal {
    if is_zero(&a.digits) {
        return bd_zero(a.scale);
    }
    BigDecimal {
        negative: !a.negative,
        digits: a.digits.clone(),
        scale: a.scale,
    }
}

fn bd_cmp(a: &BigDecimal, b: &BigDecimal) -> Ordering {
    let max_scale = a.scale.max(b.scale);
    let a2 = bd_rescale(a, max_scale);
    let b2 = bd_rescale(b, max_scale);
    let a_zero = is_zero(&a2.digits);
    let b_zero = is_zero(&b2.digits);
    if a_zero && b_zero {
        return Ordering::Equal;
    }
    if a_zero {
        return if b2.negative {
            Ordering::Greater
        } else {
            Ordering::Less
        };
    }
    if b_zero {
        return if a2.negative {
            Ordering::Less
        } else {
            Ordering::Greater
        };
    }
    if a2.negative && !b2.negative {
        return Ordering::Less;
    }
    if !a2.negative && b2.negative {
        return Ordering::Greater;
    }
    if !a2.negative && !b2.negative {
        return bigint_cmp(&a2.digits, &b2.digits);
    }
    bigint_cmp(&b2.digits, &a2.digits)
}

fn parse_decimal(s: &str) -> BigDecimal {
    let (negative, s) = if s.starts_with('-') {
        (true, &s[1..])
    } else {
        (false, s)
    };
    let (int_part, frac_part) = if let Some(pos) = s.find('.') {
        (&s[..pos], &s[pos + 1..])
    } else {
        (s, "")
    };
    let scale = frac_part.len();
    let all_digits: String = format!("{}{}", int_part, frac_part);
    let digits: Vec<u8> = all_digits.chars().rev().map(|c| (c as u8) - b'0').collect();
    let digits = normalize(digits);
    if is_zero(&digits) {
        bd_zero(scale)
    } else {
        BigDecimal {
            negative,
            digits,
            scale,
        }
    }
}

fn format_money(value: &BigDecimal, minor_units: usize) -> String {
    if is_zero(&value.digits) {
        if minor_units == 0 {
            return "0".to_string();
        }
        let mut s = String::from("0.");
        for _ in 0..minor_units {
            s.push('0');
        }
        return s;
    }
    let mut s = String::new();
    if value.negative {
        s.push('-');
    }
    let scaled = if value.scale != minor_units {
        bd_rescale(value, minor_units)
    } else {
        value.clone()
    };
    let digits_str: String = scaled.digits.iter().rev().map(|&d| (d + b'0') as char).collect();
    let total_digits = digits_str.len();
    let int_part: String;
    let frac_part: String;
    if total_digits > minor_units {
        int_part = digits_str[..total_digits - minor_units].to_string();
        frac_part = digits_str[total_digits - minor_units..].to_string();
    } else {
        int_part = "0".to_string();
        let pad = minor_units - total_digits;
        let mut fp = "0".repeat(pad);
        fp.push_str(&digits_str);
        frac_part = fp;
    }
    let chars: Vec<char> = int_part.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            s.push(',');
        }
        s.push(c);
    }
    if minor_units > 0 {
        s.push('.');
        s.push_str(&frac_part);
    }
    s
}

fn u64_to_digits(n: u64) -> Vec<u8> {
    if n == 0 {
        return vec![0];
    }
    let mut digits = Vec::new();
    let mut n = n;
    while n > 0 {
        digits.push((n % 10) as u8);
        n /= 10;
    }
    digits
}

fn digits_to_u64(digits: &[u8]) -> u64 {
    let mut result = 0u64;
    for i in (0..digits.len()).rev() {
        result = result * 10 + digits[i] as u64;
    }
    result
}

struct Account {
    currency: String,
    balance: BigDecimal,
    limit: BigDecimal,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/ledger.txt", dir);
    let content = fs::read_to_string(&path).unwrap();

    let mut currencies: HashMap<String, usize> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (line_num, line) in content.lines().enumerate() {
        let line_num = line_num + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        if fields.is_empty() {
            continue;
        }
        let cmd = fields[0];
        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: usize = fields[2].parse().unwrap();
                currencies.insert(code, minor);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let minor = *currencies.get(&code).unwrap();
                let limit_str = if fields.len() > 3 { fields[3] } else { "0" };
                let limit = bd_round(&parse_decimal(limit_str), minor);
                if accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT account exists {}",
                        line_num, name
                    ));
                } else {
                    accounts.insert(
                        name,
                        Account {
                            currency: code,
                            balance: bd_zero(minor),
                            limit,
                        },
                    );
                }
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acc = accounts.get_mut(&name).unwrap();
                acc.balance = bd_add(&acc.balance, &amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, name
                    ));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_balance;
            }
            "transfer" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                let amount_str = fields[3];
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, to_name
                    ));
                    continue;
                }
                let from_cur = accounts[&from_name].currency.clone();
                let to_cur = accounts[&to_name].currency.clone();
                if from_cur != to_cur {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let to_acc = accounts.get_mut(&to_name).unwrap();
                to_acc.balance = bd_add(&to_acc.balance, &amount);
            }
            "convert" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, to_name
                    ));
                    continue;
                }
                let from_cur = accounts[&from_name].currency.clone();
                let to_cur = accounts[&to_name].currency.clone();
                let from_minor = *currencies.get(&from_cur).unwrap();
                let to_minor = *currencies.get(&to_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), from_minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                let rate = parse_decimal(rate_str);
                let to_amount = bd_round(&bd_mul(&amount, &rate), to_minor);
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let to_acc = accounts.get_mut(&to_name).unwrap();
                to_acc.balance = bd_add(&to_acc.balance, &to_amount);
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let rate = parse_decimal(rate_str);
                let interest = {
                    let acc = accounts.get(&name).unwrap();
                    bd_round(&bd_mul(&acc.balance, &rate), minor)
                };
                let acc = accounts.get_mut(&name).unwrap();
                acc.balance = bd_add(&acc.balance, &interest);
            }
            "split" => {
                let from_name = fields[1].to_string();
                let amount_str = fields[2];
                let mut targets: Vec<(String, u64)> = Vec::new();
                for i in 3..fields.len() {
                    let colon_pos = fields[i].find(':').unwrap();
                    let target_name = fields[i][..colon_pos].to_string();
                    let weight: u64 = fields[i][colon_pos + 1..].parse().unwrap();
                    targets.push((target_name, weight));
                }
                // Check 1: unknown accounts
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                let mut found_unknown = false;
                for (target_name, _) in &targets {
                    if !accounts.contains_key(target_name) {
                        rejections.push(format!(
                            "line {}: REJECT unknown account {}",
                            line_num, target_name
                        ));
                        found_unknown = true;
                        break;
                    }
                }
                if found_unknown {
                    continue;
                }
                // Check 2: currency mismatch
                let from_cur = accounts[&from_name].currency.clone();
                let mut mismatch = false;
                for (target_name, _) in &targets {
                    if accounts[target_name].currency != from_cur {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                // Check 3: non-positive amount
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                // Check 4: insufficient funds
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                // Execute
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let a_int = &amount.digits;
                let w_int = {
                    let mut w = vec![0u8];
                    for (_, weight) in &targets {
                        let w_digits = u64_to_digits(*weight);
                        w = bigint_add(&w, &w_digits);
                    }
                    w
                };
                let mut shares: Vec<(Vec<u8>, Vec<u8>, usize)> = Vec::new();
                let mut total_base = vec![0u8];
                for (i, (_, weight)) in targets.iter().enumerate() {
                    let wi = u64_to_digits(*weight);
                    let product = bigint_mul(a_int, &wi);
                    let (quotient, remainder) = bigint_divmod(&product, &w_int);
                    shares.push((quotient.clone(), remainder, i));
                    total_base = bigint_add(&total_base, &quotient);
                }
                let leftover = bigint_sub(a_int, &total_base);
                let leftover_count = digits_to_u64(&leftover) as usize;
                shares.sort_by(|a, b| {
                    let cmp = bigint_cmp(&b.1, &a.1);
                    if cmp != Ordering::Equal {
                        return cmp;
                    }
                    a.2.cmp(&b.2)
                });
                let mut final_shares: Vec<Vec<u8>> = vec![vec![0u8]; targets.len()];
                for (j, (base, _, orig_idx)) in shares.iter().enumerate() {
                    let mut share = base.clone();
                    if j < leftover_count {
                        share = bigint_add(&share, &[1]);
                    }
                    final_shares[*orig_idx] = share;
                }
                for (i, (target_name, _)) in targets.iter().enumerate() {
                    let share_bd = BigDecimal {
                        negative: false,
                        digits: final_shares[i].clone(),
                        scale: minor,
                    };
                    let acc = accounts.get_mut(target_name).unwrap();
                    acc.balance = bd_add(&acc.balance, &share_bd);
                }
            }
            _ => {}
        }
    }

    // Output
    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut sorted_accounts: Vec<&String> = accounts.keys().collect();
    sorted_accounts.sort();
    for name in &sorted_accounts {
        let acc = &accounts[*name];
        let minor = *currencies.get(&acc.currency).unwrap();
        println!("{} {} {}", name, acc.currency, format_money(&acc.balance, minor));
    }
    println!();

    let mut cur_totals: HashMap<String, (BigDecimal, usize)> = HashMap::new();
    for acc in accounts.values() {
        let minor = *currencies.get(&acc.currency).unwrap();
        let entry = cur_totals
            .entry(acc.currency.clone())
            .or_insert((bd_zero(minor), 0));
        entry.0 = bd_add(&entry.0, &acc.balance);
        entry.1 += 1;
    }

    let mut sorted_currencies: Vec<&String> = cur_totals.keys().collect();
    sorted_currencies.sort();
    for code in &sorted_currencies {
        let (total, count) = &cur_totals[*code];
        let minor = *currencies.get(code).unwrap();
        println!(
            "total {} {} ({} accounts)",
            code,
            format_money(total, minor),
            count
        );
    }
}

use std::collections::HashMap;
use std::cmp::Ordering;
use std::env;
use std::fs;

#[derive(Clone, Debug)]
struct BigDecimal {
    negative: bool,
    digits: Vec<u8>,
    scale: usize,
}

fn normalize(mut digits: Vec<u8>) -> Vec<u8> {
    while digits.len() > 1 && *digits.last().unwrap() == 0 {
        digits.pop();
    }
    digits
}

fn is_zero(digits: &[u8]) -> bool {
    digits.iter().all(|&d| d == 0)
}

fn bigint_cmp(a: &[u8], b: &[u8]) -> Ordering {
    let a = normalize(a.to_vec());
    let b = normalize(b.to_vec());
    if a.len() != b.len() {
        return a.len().cmp(&b.len());
    }
    for i in (0..a.len()).rev() {
        if a[i] != b[i] {
            return a[i].cmp(&b[i]);
        }
    }
    Ordering::Equal
}

fn bigint_add(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut carry = 0u8;
    let max_len = a.len().max(b.len());
    for i in 0..max_len {
        let da = if i < a.len() { a[i] } else { 0 };
        let db = if i < b.len() { b[i] } else { 0 };
        let sum = da + db + carry;
        result.push(sum % 10);
        carry = sum / 10;
    }
    if carry > 0 {
        result.push(carry);
    }
    normalize(result)
}

fn bigint_sub(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut borrow = 0i8;
    for i in 0..a.len() {
        let da = a[i] as i8;
        let db = if i < b.len() { b[i] as i8 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        result.push(diff as u8);
    }
    normalize(result)
}

fn bigint_mul(a: &[u8], b: &[u8]) -> Vec<u8> {
    if is_zero(a) || is_zero(b) {
        return vec![0];
    }
    let mut result = vec![0u8; a.len() + b.len()];
    for i in 0..a.len() {
        if a[i] == 0 {
            continue;
        }
        let mut carry = 0u32;
        for j in 0..b.len() {
            let prod = result[i + j] as u32 + (a[i] as u32) * (b[j] as u32) + carry;
            result[i + j] = (prod % 10) as u8;
            carry = prod / 10;
        }
        let mut pos = i + b.len();
        while carry > 0 {
            let sum = result[pos] as u32 + carry;
            result[pos] = (sum % 10) as u8;
            carry = sum / 10;
            pos += 1;
        }
    }
    normalize(result)
}

fn bigint_divmod(a: &[u8], b: &[u8]) -> (Vec<u8>, Vec<u8>) {
    let a = normalize(a.to_vec());
    let b = normalize(b.to_vec());
    if is_zero(&a) {
        return (vec![0], vec![0]);
    }
    if is_zero(&b) {
        panic!("division by zero");
    }
    if bigint_cmp(&a, &b) == Ordering::Less {
        return (vec![0], a);
    }
    let mut quotient = vec![0u8; a.len()];
    let mut remainder: Vec<u8> = vec![0];
    for i in (0..a.len()).rev() {
        remainder.insert(0, 0);
        remainder[0] = a[i];
        remainder = normalize(remainder);
        let mut q = 0u8;
        let mut prod = vec![0u8];
        loop {
            let next_prod = bigint_add(&prod, &b);
            if bigint_cmp(&next_prod, &remainder) == Ordering::Greater {
                break;
            }
            prod = next_prod;
            q += 1;
            if q == 10 {
                q = 9;
                break;
            }
        }
        quotient[i] = q;
        if q > 0 {
            remainder = bigint_sub(&remainder, &prod);
        }
    }
    (normalize(quotient), normalize(remainder))
}

fn pow10(n: usize) -> Vec<u8> {
    if n == 0 {
        return vec![1];
    }
    let mut result = vec![0u8; n + 1];
    result[n] = 1;
    result
}

fn bd_zero(scale: usize) -> BigDecimal {
    BigDecimal {
        negative: false,
        digits: vec![0],
        scale,
    }
}

fn bd_rescale(a: &BigDecimal, new_scale: usize) -> BigDecimal {
    if new_scale == a.scale {
        return a.clone();
    }
    let diff = new_scale - a.scale;
    let multiplier = pow10(diff);
    let digits = bigint_mul(&a.digits, &multiplier);
    BigDecimal {
        negative: a.negative,
        digits,
        scale: new_scale,
    }
}

fn bd_add(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let max_scale = a.scale.max(b.scale);
    let a2 = bd_rescale(a, max_scale);
    let b2 = bd_rescale(b, max_scale);
    if a2.negative == b2.negative {
        let digits = bigint_add(&a2.digits, &b2.digits);
        if is_zero(&digits) {
            bd_zero(max_scale)
        } else {
            BigDecimal {
                negative: a2.negative,
                digits,
                scale: max_scale,
            }
        }
    } else {
        match bigint_cmp(&a2.digits, &b2.digits) {
            Ordering::Greater => {
                let digits = bigint_sub(&a2.digits, &b2.digits);
                if is_zero(&digits) {
                    bd_zero(max_scale)
                } else {
                    BigDecimal {
                        negative: a2.negative,
                        digits,
                        scale: max_scale,
                    }
                }
            }
            Ordering::Less => {
                let digits = bigint_sub(&b2.digits, &a2.digits);
                if is_zero(&digits) {
                    bd_zero(max_scale)
                } else {
                    BigDecimal {
                        negative: b2.negative,
                        digits,
                        scale: max_scale,
                    }
                }
            }
            Ordering::Equal => bd_zero(max_scale),
        }
    }
}

fn bd_sub(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let neg_b = if is_zero(&b.digits) {
        bd_zero(b.scale)
    } else {
        BigDecimal {
            negative: !b.negative,
            digits: b.digits.clone(),
            scale: b.scale,
        }
    };
    bd_add(a, &neg_b)
}

fn bd_mul(a: &BigDecimal, b: &BigDecimal) -> BigDecimal {
    let digits = bigint_mul(&a.digits, &b.digits);
    let negative = (a.negative != b.negative) && !is_zero(&digits);
    let scale = a.scale + b.scale;
    BigDecimal {
        negative,
        digits,
        scale,
    }
}

fn bd_round(a: &BigDecimal, target_scale: usize) -> BigDecimal {
    if a.scale <= target_scale {
        return bd_rescale(a, target_scale);
    }
    let k = a.scale - target_scale;
    let divisor = pow10(k);
    let (quotient, remainder) = bigint_divmod(&a.digits, &divisor);
    let half = {
        let mut h = vec![0u8; k];
        h[k - 1] = 5;
        h
    };
    let mut digits = quotient;
    match bigint_cmp(&remainder, &half) {
        Ordering::Greater => {
            digits = bigint_add(&digits, &[1]);
        }
        Ordering::Equal => {
            if digits[0] % 2 == 1 {
                digits = bigint_add(&digits, &[1]);
            }
        }
        Ordering::Less => {}
    }
    if is_zero(&digits) {
        bd_zero(target_scale)
    } else {
        BigDecimal {
            negative: a.negative,
            digits,
            scale: target_scale,
        }
    }
}

fn bd_neg(a: &BigDecimal) -> BigDecimal {
    if is_zero(&a.digits) {
        return bd_zero(a.scale);
    }
    BigDecimal {
        negative: !a.negative,
        digits: a.digits.clone(),
        scale: a.scale,
    }
}

fn bd_cmp(a: &BigDecimal, b: &BigDecimal) -> Ordering {
    let max_scale = a.scale.max(b.scale);
    let a2 = bd_rescale(a, max_scale);
    let b2 = bd_rescale(b, max_scale);
    let a_zero = is_zero(&a2.digits);
    let b_zero = is_zero(&b2.digits);
    if a_zero && b_zero {
        return Ordering::Equal;
    }
    if a_zero {
        return if b2.negative {
            Ordering::Greater
        } else {
            Ordering::Less
        };
    }
    if b_zero {
        return if a2.negative {
            Ordering::Less
        } else {
            Ordering::Greater
        };
    }
    if a2.negative && !b2.negative {
        return Ordering::Less;
    }
    if !a2.negative && b2.negative {
        return Ordering::Greater;
    }
    if !a2.negative && !b2.negative {
        return bigint_cmp(&a2.digits, &b2.digits);
    }
    bigint_cmp(&b2.digits, &a2.digits)
}

fn parse_decimal(s: &str) -> BigDecimal {
    let (negative, s) = if s.starts_with('-') {
        (true, &s[1..])
    } else {
        (false, s)
    };
    let (int_part, frac_part) = if let Some(pos) = s.find('.') {
        (&s[..pos], &s[pos + 1..])
    } else {
        (s, "")
    };
    let scale = frac_part.len();
    let all_digits: String = format!("{}{}", int_part, frac_part);
    let digits: Vec<u8> = all_digits.chars().rev().map(|c| (c as u8) - b'0').collect();
    let digits = normalize(digits);
    if is_zero(&digits) {
        bd_zero(scale)
    } else {
        BigDecimal {
            negative,
            digits,
            scale,
        }
    }
}

fn format_money(value: &BigDecimal, minor_units: usize) -> String {
    if is_zero(&value.digits) {
        if minor_units == 0 {
            return "0".to_string();
        }
        let mut s = String::from("0.");
        for _ in 0..minor_units {
            s.push('0');
        }
        return s;
    }
    let mut s = String::new();
    if value.negative {
        s.push('-');
    }
    let scaled = if value.scale != minor_units {
        bd_rescale(value, minor_units)
    } else {
        value.clone()
    };
    let digits_str: String = scaled.digits.iter().rev().map(|&d| (d + b'0') as char).collect();
    let total_digits = digits_str.len();
    let int_part: String;
    let frac_part: String;
    if total_digits > minor_units {
        int_part = digits_str[..total_digits - minor_units].to_string();
        frac_part = digits_str[total_digits - minor_units..].to_string();
    } else {
        int_part = "0".to_string();
        let pad = minor_units - total_digits;
        let mut fp = "0".repeat(pad);
        fp.push_str(&digits_str);
        frac_part = fp;
    }
    let chars: Vec<char> = int_part.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (chars.len() - i) % 3 == 0 {
            s.push(',');
        }
        s.push(c);
    }
    if minor_units > 0 {
        s.push('.');
        s.push_str(&frac_part);
    }
    s
}

fn u64_to_digits(n: u64) -> Vec<u8> {
    if n == 0 {
        return vec![0];
    }
    let mut digits = Vec::new();
    let mut n = n;
    while n > 0 {
        digits.push((n % 10) as u8);
        n /= 10;
    }
    digits
}

fn digits_to_u64(digits: &[u8]) -> u64 {
    let mut result = 0u64;
    for i in (0..digits.len()).rev() {
        result = result * 10 + digits[i] as u64;
    }
    result
}

struct Account {
    currency: String,
    balance: BigDecimal,
    limit: BigDecimal,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/ledger.txt", dir);
    let content = fs::read_to_string(&path).unwrap();

    let mut currencies: HashMap<String, usize> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (line_num, line) in content.lines().enumerate() {
        let line_num = line_num + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        if fields.is_empty() {
            continue;
        }
        let cmd = fields[0];
        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: usize = fields[2].parse().unwrap();
                currencies.insert(code, minor);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let minor = *currencies.get(&code).unwrap();
                let limit_str = if fields.len() > 3 { fields[3] } else { "0" };
                let limit = bd_round(&parse_decimal(limit_str), minor);
                if accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT account exists {}",
                        line_num, name
                    ));
                } else {
                    accounts.insert(
                        name,
                        Account {
                            currency: code,
                            balance: bd_zero(minor),
                            limit,
                        },
                    );
                }
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acc = accounts.get_mut(&name).unwrap();
                acc.balance = bd_add(&acc.balance, &amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, name
                    ));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_balance;
            }
            "transfer" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                let amount_str = fields[3];
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, to_name
                    ));
                    continue;
                }
                let from_cur = accounts[&from_name].currency.clone();
                let to_cur = accounts[&to_name].currency.clone();
                if from_cur != to_cur {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let to_acc = accounts.get_mut(&to_name).unwrap();
                to_acc.balance = bd_add(&to_acc.balance, &amount);
            }
            "convert" => {
                let from_name = fields[1].to_string();
                let to_name = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                if !accounts.contains_key(&to_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, to_name
                    ));
                    continue;
                }
                let from_cur = accounts[&from_name].currency.clone();
                let to_cur = accounts[&to_name].currency.clone();
                let from_minor = *currencies.get(&from_cur).unwrap();
                let to_minor = *currencies.get(&to_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), from_minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                let rate = parse_decimal(rate_str);
                let to_amount = bd_round(&bd_mul(&amount, &rate), to_minor);
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let to_acc = accounts.get_mut(&to_name).unwrap();
                to_acc.balance = bd_add(&to_acc.balance, &to_amount);
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, name
                    ));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let rate = parse_decimal(rate_str);
                let interest = {
                    let acc = accounts.get(&name).unwrap();
                    bd_round(&bd_mul(&acc.balance, &rate), minor)
                };
                let acc = accounts.get_mut(&name).unwrap();
                acc.balance = bd_add(&acc.balance, &interest);
            }
            "split" => {
                let from_name = fields[1].to_string();
                let amount_str = fields[2];
                let mut targets: Vec<(String, u64)> = Vec::new();
                for i in 3..fields.len() {
                    let colon_pos = fields[i].find(':').unwrap();
                    let target_name = fields[i][..colon_pos].to_string();
                    let weight: u64 = fields[i][colon_pos + 1..].parse().unwrap();
                    targets.push((target_name, weight));
                }
                // Check 1: unknown accounts
                if !accounts.contains_key(&from_name) {
                    rejections.push(format!(
                        "line {}: REJECT unknown account {}",
                        line_num, from_name
                    ));
                    continue;
                }
                let mut found_unknown = false;
                for (target_name, _) in &targets {
                    if !accounts.contains_key(target_name) {
                        rejections.push(format!(
                            "line {}: REJECT unknown account {}",
                            line_num, target_name
                        ));
                        found_unknown = true;
                        break;
                    }
                }
                if found_unknown {
                    continue;
                }
                // Check 2: currency mismatch
                let from_cur = accounts[&from_name].currency.clone();
                let mut mismatch = false;
                for (target_name, _) in &targets {
                    if accounts[target_name].currency != from_cur {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                // Check 3: non-positive amount
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = bd_round(&parse_decimal(amount_str), minor);
                if is_zero(&amount.digits) || amount.negative {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                // Check 4: insufficient funds
                let (new_balance, neg_limit) = {
                    let acc = accounts.get(&from_name).unwrap();
                    (bd_sub(&acc.balance, &amount), bd_neg(&acc.limit))
                };
                if bd_cmp(&new_balance, &neg_limit) == Ordering::Less {
                    rejections.push(format!(
                        "line {}: REJECT insufficient funds {}",
                        line_num, from_name
                    ));
                    continue;
                }
                // Execute
                accounts.get_mut(&from_name).unwrap().balance = new_balance;
                let a_int = &amount.digits;
                let w_int = {
                    let mut w = vec![0u8];
                    for (_, weight) in &targets {
                        let w_digits = u64_to_digits(*weight);
                        w = bigint_add(&w, &w_digits);
                    }
                    w
                };
                let mut shares: Vec<(Vec<u8>, Vec<u8>, usize)> = Vec::new();
                let mut total_base = vec![0u8];
                for (i, (_, weight)) in targets.iter().enumerate() {
                    let wi = u64_to_digits(*weight);
                    let product = bigint_mul(a_int, &wi);
                    let (quotient, remainder) = bigint_divmod(&product, &w_int);
                    shares.push((quotient.clone(), remainder, i));
                    total_base = bigint_add(&total_base, &quotient);
                }
                let leftover = bigint_sub(a_int, &total_base);
                let leftover_count = digits_to_u64(&leftover) as usize;
                shares.sort_by(|a, b| {
                    let cmp = bigint_cmp(&b.1, &a.1);
                    if cmp != Ordering::Equal {
                        return cmp;
                    }
                    a.2.cmp(&b.2)
                });
                let mut final_shares: Vec<Vec<u8>> = vec![vec![0u8]; targets.len()];
                for (j, (base, _, orig_idx)) in shares.iter().enumerate() {
                    let mut share = base.clone();
                    if j < leftover_count {
                        share = bigint_add(&share, &[1]);
                    }
                    final_shares[*orig_idx] = share;
                }
                for (i, (target_name, _)) in targets.iter().enumerate() {
                    let share_bd = BigDecimal {
                        negative: false,
                        digits: final_shares[i].clone(),
                        scale: minor,
                    };
                    let acc = accounts.get_mut(target_name).unwrap();
                    acc.balance = bd_add(&acc.balance, &share_bd);
                }
            }
            _ => {}
        }
    }

    // Output
    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut sorted_accounts: Vec<&String> = accounts.keys().collect();
    sorted_accounts.sort();
    for name in &sorted_accounts {
        let acc = &accounts[*name];
        let minor = *currencies.get(&acc.currency).unwrap();
        println!("{} {} {}", name, acc.currency, format_money(&acc.balance, minor));
    }
    println!();

    let mut cur_totals: HashMap<String, (BigDecimal, usize)> = HashMap::new();
    for acc in accounts.values() {
        let minor = *currencies.get(&acc.currency).unwrap();
        let entry = cur_totals
            .entry(acc.currency.clone())
            .or_insert((bd_zero(minor), 0));
        entry.0 = bd_add(&entry.0, &acc.balance);
        entry.1 += 1;
    }

    let mut sorted_currencies: Vec<&String> = cur_totals.keys().collect();
    sorted_currencies.sort();
    for code in &sorted_currencies {
        let (total, count) = &cur_totals[*code];
        let minor = *currencies.get(*code).unwrap();
        println!(
            "total {} {} ({} accounts)",
            code,
            format_money(total, minor),
            count
        );
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXD 256
#define MAXACC 100000
#define MAXCUR 10000
#define MAXLINE 10000
#define MAXTOK 512

typedef struct { int sign, nd, sc; int d[MAXD]; } Dec;

static void bi_norm(int *d, int *nd) {
    while (*nd > 1 && d[*nd - 1] == 0) (*nd)--;
}

static void bi_add(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    int carry = 0, mx = an > bn ? an : bn;
    for (int i = 0; i < mx; i++) {
        int s = (i < an ? a[i] : 0) + (i < bn ? b[i] : 0) + carry;
        rd[i] = s % 10; carry = s / 10;
    }
    if (carry) { rd[mx] = carry; *rnd = mx + 1; }
    else *rnd = mx;
    bi_norm(rd, rnd);
}

static void bi_sub(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    int borrow = 0, mx = an > bn ? an : bn;
    for (int i = 0; i < mx; i++) {
        int diff = (i < an ? a[i] : 0) - (i < bn ? b[i] : 0) - borrow;
        if (diff < 0) { diff += 10; borrow = 1; } else borrow = 0;
        rd[i] = diff;
    }
    *rnd = mx; bi_norm(rd, rnd);
}

static int bi_cmp(const int *a, int an, const int *b, int bn) {
    if (an != bn) return an > bn ? 1 : -1;
    for (int i = an - 1; i >= 0; i--)
        if (a[i] != b[i]) return a[i] > b[i] ? 1 : -1;
    return 0;
}

static void bi_mul(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    memset(rd, 0, (an + bn) * sizeof(int));
    for (int i = 0; i < an; i++) {
        int carry = 0;
        for (int j = 0; j < bn; j++) {
            int p = rd[i+j] + a[i]*b[j] + carry;
            rd[i+j] = p % 10; carry = p / 10;
        }
        if (carry) rd[i+bn] += carry;
    }
    *rnd = an + bn; bi_norm(rd, rnd);
}

static void bi_divmod(int *qd, int *qnd, int *rd, int *rnd,
                      const int *a, int an, const int *b, int bn) {
    int r[MAXD] = {0}; int rlen = 1;
    for (int i = an - 1; i >= 0; i--) {
        int carry = a[i];
        for (int j = 0; j < rlen; j++) {
            int t = r[j]*10 + carry; r[j] = t%10; carry = t/10;
        }
        while (carry) { r[rlen++] = carry%10; carry /= 10; }
        while (rlen > 1 && r[rlen-1] == 0) rlen--;
        int q = 0;
        while (bi_cmp(r, rlen, b, bn) >= 0) {
            int borrow = 0;
            for (int j = 0; j < rlen; j++) {
                int diff = r[j] - (j < bn ? b[j] : 0) - borrow;
                if (diff < 0) { diff += 10; borrow = 1; } else borrow = 0;
                r[j] = diff;
            }
            while (rlen > 1 && r[rlen-1] == 0) rlen--;
            q++;
        }
        qd[i] = q;
    }
    *qnd = an; bi_norm(qd, qnd);
    *rnd = rlen; memcpy(rd, r, rlen * sizeof(int));
}

static void dec_zero(Dec *a) { a->sign=0; a->nd=1; a->sc=0; a->d[0]=0; }
static void dec_copy(Dec *r, const Dec *a) { *r = *a; }
static void dec_norm(Dec *a) { bi_norm(a->d, &a->nd); if (a->nd==1 && a->d[0]==0) a->sign=0; }

static void dec_parse(const char *s, Dec *a) {
    a->sign=1; a->nd=0; a->sc=0;
    int i=0;
    if (s[0]=='-') { a->sign=-1; i=1; }
    else if (s[0]=='+') { i=1; }
    int len=(int)strlen(s), dot=-1;
    for (int j=i;j<len;j++) if (s[j]=='.') { dot=j; break; }
    if (dot>=0) a->sc = len-dot-1;
    int pos=0;
    for (int j=len-1;j>=i;j--) { if (s[j]=='.') continue; a->d[pos++]=s[j]-'0'; }
    a->nd=pos; if (a->nd==0){a->nd=1;a->d[0]=0;}
    dec_norm(a);
}

static void dec_align(Dec *a, Dec *b) {
    if (a->sc < b->sc) {
        int diff=b->sc-a->sc;
        memmove(a->d+diff, a->d, a->nd*sizeof(int));
        memset(a->d, 0, diff*sizeof(int));
        a->nd+=diff; a->sc=b->sc;
    } else if (b->sc < a->sc) {
        int diff=a->sc-b->sc;
        memmove(b->d+diff, b->d, b->nd*sizeof(int));
        memset(b->d, 0, diff*sizeof(int));
        b->nd+=diff; b->sc=a->sc;
    }
}

static void dec_add(Dec *r, const Dec *a, const Dec *b) {
    Dec ta,tb; dec_copy(&ta,a); dec_copy(&tb,b); dec_align(&ta,&tb);
    if (ta.sign==0){dec_copy(r,&tb);return;}
    if (tb.sign==0){dec_copy(r,&ta);return;}
    r->sc=ta.sc;
    if (ta.sign==tb.sign){
        r->sign=ta.sign; bi_add(r->d,&r->nd,ta.d,ta.nd,tb.d,tb.nd);
    } else {
        int c=bi_cmp(ta.d,ta.nd,tb.d,tb.nd);
        if(c==0){r->sign=0;r->nd=1;r->d[0]=0;}
        else if(c>0){r->sign=ta.sign;bi_sub(r->d,&r->nd,ta.d,ta.nd,tb.d,tb.nd);}
        else{r->sign=tb.sign;bi_sub(r->d,&r->nd,tb.d,tb.nd,ta.d,ta.nd);}
    }
    dec_norm(r);
}

static void dec_sub(Dec *r, const Dec *a, const Dec *b) {
    Dec nb=*b; if(nb.sign!=0) nb.sign=-nb.sign;
    dec_add(r,a,&nb);
}

static void dec_mul(Dec *r, const Dec *a, const Dec *b) {
    if(a->sign==0||b->sign==0){dec_zero(r);return;}
    r->sign=a->sign*b->sign; r->sc=a->sc+b->sc;
    bi_mul(r->d,&r->nd,a->d,a->nd,b->d,b->nd);
    dec_norm(r);
}

static int dec_cmp(const Dec *a, const Dec *b) {
    if(a->sign!=b->sign) return a->sign>b->sign?1:-1;
    if(a->sign==0) return 0;
    Dec ta,tb; dec_copy(&ta,a); dec_copy(&tb,b); dec_align(&ta,&tb);
    int c=bi_cmp(ta.d,ta.nd,tb.d,tb.nd);
    return a->sign>0?c:-c;
}

static void dec_round(Dec *a, int ts) {
    if(a->sign==0){a->sc=ts;return;}
    if(a->sc<=ts){
        int diff=ts-a->sc;
        if(diff>0){memmove(a->d+diff,a->d,a->nd*sizeof(int));memset(a->d,0,diff*sizeof(int));a->nd+=diff;}
        a->sc=ts; return;
    }
    int drop=a->sc-ts;
    int cmp_half=0;
    for(int i=drop-1;i>=0;i--){
        int expected=(i==drop-1)?5:0;
        int actual=(i<a->nd)?a->d[i]:0;
        if(actual>expected){cmp_half=1;break;}
        if(actual<expected){cmp_half=-1;break;}
    }
    if(a->nd>drop){memmove(a->d,a->d+drop,(a->nd-drop)*sizeof(int));a->nd-=drop;}
    else{a->nd=1;a->d[0]=0;}
    a->sc=ts;
    if(cmp_half>0||(cmp_half==0&&a->nd>0&&(a->d[0]&1))){
        int carry=1;
        for(int i=0;i<a->nd&&carry;i++){int s=a->d[i]+carry;a->d[i]=s%10;carry=s/10;}
        if(carry){memmove(a->d+1,a->d,a->nd*sizeof(int));a->d[0]=carry;a->nd++;}
    }
    dec_norm(a);
}

static void dec_format(const Dec *a, int minor, char *buf) {
    Dec tmp; dec_copy(&tmp,a); dec_round(&tmp,minor);
    char t[512]; int pos=0;
    if(tmp.sign<0) t[pos++]='-';
    int int_d=tmp.nd-tmp.sc;
    if(int_d<=0){t[pos++]='0';}
    else{
        for(int i=tmp.nd-1;i>=tmp.sc;i--){
            if(i<tmp.nd-1&&(tmp.nd-1-i)%3==0) t[pos++]=',';
            t[pos++]='0'+tmp.d[i];
        }
    }
    if(minor>0){
        t[pos++]='.';
        for(int i=tmp.sc-1;i>=0;i--){
            int dg=(i<tmp.nd)?tmp.d[i]:0;
            t[pos++]='0'+dg;
        }
    }
    t[pos]='\0'; strcpy(buf,t);
}

/* Data structures */
typedef struct { char code[64]; int minor; } Cur;
typedef struct { char name[256]; int ci; Dec bal, lim; } Acc;

static Cur curs[MAXCUR]; static int ncur=0;
static Acc accs[MAXACC]; static int nacc=0;

static int find_cur(const char *c){for(int i=0;i<ncur;i++)if(!strcmp(curs[i].code,c))return i;return -1;}
static int find_acc(const char *n){for(int i=0;i<nacc;i++)if(!strcmp(accs[i].name,n))return i;return -1;}

typedef struct { int line; char reason[512]; } Rej;
static Rej rejects[MAXACC*10]; static int nrej=0;

static void reject(int line, const char *fmt, ...) {
    rejects[nrej].line=line;
    va_list ap; va_start(ap,fmt);
    vsnprintf(rejects[nrej].reason,512,fmt,ap);
    va_end(ap);
    nrej++;
}

int main(int argc, char *argv[]) {
    char path[MAXLINE];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f) return 1;

    char line[MAXLINE];
    int lineno=0;

    while(fgets(line,sizeof(line),f)){
        lineno++;
        int len=(int)strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;

        int first=0;
        while(first<len&&line[first]==' ') first++;
        if(first>=len||line[first]=='#') continue;

        char *toks[MAXTOK]; int ntok=0;
        char *p=line;
        while(*p&&ntok<MAXTOK){
            while(*p==' ')p++;
            if(!*p)break;
            toks[ntok++]=p;
            while(*p&&*p!=' ')p++;
            if(*p)*p++=0;
        }
        if(ntok==0) continue;

        if(!strcmp(toks[0],"currency")){
            int ci=ncur++;
            strcpy(curs[ci].code,toks[1]);
            curs[ci].minor=atoi(toks[2]);
        }
        else if(!strcmp(toks[0],"open")){
            if(find_acc(toks[1])>=0){reject(lineno,"account exists %s",toks[1]);continue;}
            int ci=find_cur(toks[2]);
            int ai=nacc++;
            strcpy(accs[ai].name,toks[1]);
            accs[ai].ci=ci;
            dec_zero(&accs[ai].bal); accs[ai].bal.sc=curs[ci].minor;
            if(ntok>=4){dec_parse(toks[3],&accs[ai].lim);dec_round(&accs[ai].lim,curs[ci].minor);}
            else{dec_zero(&accs[ai].lim);accs[ai].lim.sc=curs[ci].minor;}
        }
        else if(!strcmp(toks[0],"deposit")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec amt; dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[ai].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            dec_add(&accs[ai].bal,&accs[ai].bal,&amt);
        }
        else if(!strcmp(toks[0],"withdraw")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec amt; dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[ai].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[ai].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[ai].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            dec_copy(&accs[ai].bal,&nb);
        }
        else if(!strcmp(toks[0],"transfer")){
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            int ti=find_acc(toks[2]);
            if(ti<0){reject(lineno,"unknown account %s",toks[2]);continue;}
            if(accs[fi].ci!=accs[ti].ci){reject(lineno,"currency mismatch");continue;}
            Dec amt; dec_parse(toks[3],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[fi].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            dec_copy(&accs[fi].bal,&nb);
            dec_add(&accs[ti].bal,&accs[ti].bal,&amt);
        }
        else if(!strcmp(toks[0],"convert")){
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            int ti=find_acc(toks[2]);
            if(ti<0){reject(lineno,"unknown account %s",toks[2]);continue;}
            Dec amt; dec_parse(toks[3],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[fi].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            Dec rate; dec_parse(toks[4],&rate);
            Dec recv; dec_mul(&recv,&amt,&rate); dec_round(&recv,curs[accs[ti].ci].minor);
            dec_copy(&accs[fi].bal,&nb);
            dec_add(&accs[ti].bal,&accs[ti].bal,&recv);
        }
        else if(!strcmp(toks[0],"interest")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec rate; dec_parse(toks[2],&rate);
            Dec gain; dec_mul(&gain,&accs[ai].bal,&rate); dec_round(&gain,curs[accs[ai].ci].minor);
            dec_add(&accs[ai].bal,&accs[ai].bal,&gain);
        }
        else if(!strcmp(toks[0],"split")){
            int rejected=0;
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);rejected=1;}
            int ntargets=ntok-3;
            int targs[MAXTOK]; Dec weights[MAXTOK];
            if(!rejected){
                for(int i=0;i<ntargets;i++){
                    char *colon=strchr(toks[3+i],':');
                    char nm[256]; int nl=colon-toks[3+i];
                    memcpy(nm,toks[3+i],nl); nm[nl]=0;
                    int ti=find_acc(nm);
                    if(ti<0){reject(lineno,"unknown account %s",nm);rejected=1;break;}
                    targs[i]=ti;
                    dec_parse(colon+1,&weights[i]);
                }
            }
            if(!rejected){
                for(int i=0;i<ntargets;i++){
                    if(accs[targs[i]].ci!=accs[fi].ci){reject(lineno,"currency mismatch");rejected=1;break;}
                }
            }
            Dec amt;
            if(!rejected){
                dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
                if(amt.sign<=0){reject(lineno,"non-positive amount");rejected=1;}
            }
            Dec nb;
            if(!rejected){
                dec_sub(&nb,&accs[fi].bal,&amt);
                Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
                if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);rejected=1;}
            }
            if(!rejected){
                Dec A; dec_copy(&A,&amt); A.sc=0;
                Dec W; dec_zero(&W);
                for(int i=0;i<ntargets;i++) dec_add(&W,&W,&weights[i]);
                Dec bases[MAXTOK],rems[MAXTOK];
                Dec sum_b; dec_zero(&sum_b);
                for(int i=0;i<ntargets;i++){
                    Dec prod; dec_mul(&prod,&A,&weights[i]);
                    int qd[MAXD],qnd,rd2[MAXD],rnd;
                    bi_divmod(qd,&qnd,rd2,&rnd,prod.d,prod.nd,W.d,W.nd);
                    bases[i].sign=1;bases[i].nd=qnd;bases[i].sc=0;
                    memcpy(bases[i].d,qd,qnd*sizeof(int)); dec_norm(&bases[i]);
                    rems[i].sign=1;rems[i].nd=rnd;rems[i].sc=0;
                    memcpy(rems[i].d,rd2,rnd*sizeof(int)); dec_norm(&rems[i]);
                    dec_add(&sum_b,&sum_b,&bases[i]);
                }
                Dec leftover; dec_sub(&leftover,&A,&sum_b);
                int lo=0;
                for(int i=leftover.nd-1;i>=0;i--) lo=lo*10+leftover.d[i];
                int order[MAXTOK];
                for(int i=0;i<ntargets;i++) order[i]=i;
                for(int i=1;i<ntargets;i++){
                    int key=order[i],j=i-1;
                    while(j>=0){
                        int c=dec_cmp(&rems[order[j]],&rems[key]);
                        if(c>0||(c==0&&order[j]<key)) break;
                        order[j+1]=order[j]; j--;
                    }
                    order[j+1]=key;
                }
                Dec one; dec_zero(&one); one.sign=1;one.d[0]=1;one.nd=1;one.sc=0;
                for(int i=0;i<lo;i++) dec_add(&bases[order[i]],&bases[order[i]],&one);
                dec_copy(&accs[fi].bal,&nb);
                for(int i=0;i<ntargets;i++){
                    Dec add_a; dec_copy(&add_a,&bases[i]);
                    add_a.sc=curs[accs[fi].ci].minor;
                    dec_add(&accs[targs[i]].bal,&accs[targs[i]].bal,&add_a);
                }
            }
        }
    }
    fclose(f);

    for(int i=0;i<nrej;i++) printf("line %d: REJECT %s\n",rejects[i].line,rejects[i].reason);
    printf("\n");

    int order[MAXACC];
    for(int i=0;i<nacc;i++) order[i]=i;
    for(int i=1;i<nacc;i++){
        int key=order[i],j=i-1;
        while(j>=0&&strcmp(accs[order[j]].name,accs[key].name)>0){order[j+1]=order[j];j--;}
        order[j+1]=key;
    }
    for(int i=0;i<nacc;i++){
        int ai=order[i]; char buf[512];
        dec_format(&accs[ai].bal,curs[accs[ai].ci].minor,buf);
        printf("%s %s %s\n",accs[ai].name,curs[accs[ai].ci].code,buf);
    }
    printf("\n");

    int ccount[MAXCUR]={0}; Dec ctotal[MAXCUR];
    for(int i=0;i<ncur;i++) dec_zero(&ctotal[i]);
    for(int i=0;i<nacc;i++){
        int ci=accs[i].ci; ccount[ci]++;
        dec_add(&ctotal[ci],&ctotal[ci],&accs[i].bal);
    }
    int active[MAXCUR],nact=0;
    for(int i=0;i<ncur;i++) if(ccount[i]>0) active[nact++]=i;
    for(int i=1;i<nact;i++){
        int key=active[i],j=i-1;
        while(j>=0&&strcmp(curs[active[j]].code,curs[key].code)>0){active[j+1]=active[j];j--;}
        active[j+1]=key;
    }
    for(int i=0;i<nact;i++){
        int ci=active[i]; char buf[512];
        dec_format(&ctotal[ci],curs[ci].minor,buf);
        printf("total %s %s (%d accounts)\n",curs[ci].code,buf,ccount[ci]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

#define MAXD 256
#define MAXACC 100000
#define MAXCUR 10000
#define MAXLINE 10000
#define MAXTOK 512

typedef struct { int sign, nd, sc; int d[MAXD]; } Dec;

static void bi_norm(int *d, int *nd) {
    while (*nd > 1 && d[*nd - 1] == 0) (*nd)--;
}

static void bi_add(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    int carry = 0, mx = an > bn ? an : bn;
    for (int i = 0; i < mx; i++) {
        int s = (i < an ? a[i] : 0) + (i < bn ? b[i] : 0) + carry;
        rd[i] = s % 10; carry = s / 10;
    }
    if (carry) { rd[mx] = carry; *rnd = mx + 1; }
    else *rnd = mx;
    bi_norm(rd, rnd);
}

static void bi_sub(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    int borrow = 0, mx = an > bn ? an : bn;
    for (int i = 0; i < mx; i++) {
        int diff = (i < an ? a[i] : 0) - (i < bn ? b[i] : 0) - borrow;
        if (diff < 0) { diff += 10; borrow = 1; } else borrow = 0;
        rd[i] = diff;
    }
    *rnd = mx; bi_norm(rd, rnd);
}

static int bi_cmp(const int *a, int an, const int *b, int bn) {
    if (an != bn) return an > bn ? 1 : -1;
    for (int i = an - 1; i >= 0; i--)
        if (a[i] != b[i]) return a[i] > b[i] ? 1 : -1;
    return 0;
}

static void bi_mul(int *rd, int *rnd, const int *a, int an, const int *b, int bn) {
    memset(rd, 0, (an + bn) * sizeof(int));
    for (int i = 0; i < an; i++) {
        int carry = 0;
        for (int j = 0; j < bn; j++) {
            int p = rd[i+j] + a[i]*b[j] + carry;
            rd[i+j] = p % 10; carry = p / 10;
        }
        if (carry) rd[i+bn] += carry;
    }
    *rnd = an + bn; bi_norm(rd, rnd);
}

static void bi_divmod(int *qd, int *qnd, int *rd, int *rnd,
                      const int *a, int an, const int *b, int bn) {
    int r[MAXD] = {0}; int rlen = 1;
    for (int i = an - 1; i >= 0; i--) {
        int carry = a[i];
        for (int j = 0; j < rlen; j++) {
            int t = r[j]*10 + carry; r[j] = t%10; carry = t/10;
        }
        while (carry) { r[rlen++] = carry%10; carry /= 10; }
        while (rlen > 1 && r[rlen-1] == 0) rlen--;
        int q = 0;
        while (bi_cmp(r, rlen, b, bn) >= 0) {
            int borrow = 0;
            for (int j = 0; j < rlen; j++) {
                int diff = r[j] - (j < bn ? b[j] : 0) - borrow;
                if (diff < 0) { diff += 10; borrow = 1; } else borrow = 0;
                r[j] = diff;
            }
            while (rlen > 1 && r[rlen-1] == 0) rlen--;
            q++;
        }
        qd[i] = q;
    }
    *qnd = an; bi_norm(qd, qnd);
    *rnd = rlen; memcpy(rd, r, rlen * sizeof(int));
}

static void dec_zero(Dec *a) { a->sign=0; a->nd=1; a->sc=0; a->d[0]=0; }
static void dec_copy(Dec *r, const Dec *a) { *r = *a; }
static void dec_norm(Dec *a) { bi_norm(a->d, &a->nd); if (a->nd==1 && a->d[0]==0) a->sign=0; }

static void dec_parse(const char *s, Dec *a) {
    a->sign=1; a->nd=0; a->sc=0;
    int i=0;
    if (s[0]=='-') { a->sign=-1; i=1; }
    else if (s[0]=='+') { i=1; }
    int len=(int)strlen(s), dot=-1;
    for (int j=i;j<len;j++) if (s[j]=='.') { dot=j; break; }
    if (dot>=0) a->sc = len-dot-1;
    int pos=0;
    for (int j=len-1;j>=i;j--) { if (s[j]=='.') continue; a->d[pos++]=s[j]-'0'; }
    a->nd=pos; if (a->nd==0){a->nd=1;a->d[0]=0;}
    dec_norm(a);
}

static void dec_align(Dec *a, Dec *b) {
    if (a->sc < b->sc) {
        int diff=b->sc-a->sc;
        memmove(a->d+diff, a->d, a->nd*sizeof(int));
        memset(a->d, 0, diff*sizeof(int));
        a->nd+=diff; a->sc=b->sc;
    } else if (b->sc < a->sc) {
        int diff=a->sc-b->sc;
        memmove(b->d+diff, b->d, b->nd*sizeof(int));
        memset(b->d, 0, diff*sizeof(int));
        b->nd+=diff; b->sc=a->sc;
    }
}

static void dec_add(Dec *r, const Dec *a, const Dec *b) {
    Dec ta,tb; dec_copy(&ta,a); dec_copy(&tb,b); dec_align(&ta,&tb);
    if (ta.sign==0){dec_copy(r,&tb);return;}
    if (tb.sign==0){dec_copy(r,&ta);return;}
    r->sc=ta.sc;
    if (ta.sign==tb.sign){
        r->sign=ta.sign; bi_add(r->d,&r->nd,ta.d,ta.nd,tb.d,tb.nd);
    } else {
        int c=bi_cmp(ta.d,ta.nd,tb.d,tb.nd);
        if(c==0){r->sign=0;r->nd=1;r->d[0]=0;}
        else if(c>0){r->sign=ta.sign;bi_sub(r->d,&r->nd,ta.d,ta.nd,tb.d,tb.nd);}
        else{r->sign=tb.sign;bi_sub(r->d,&r->nd,tb.d,tb.nd,ta.d,ta.nd);}
    }
    dec_norm(r);
}

static void dec_sub(Dec *r, const Dec *a, const Dec *b) {
    Dec nb=*b; if(nb.sign!=0) nb.sign=-nb.sign;
    dec_add(r,a,&nb);
}

static void dec_mul(Dec *r, const Dec *a, const Dec *b) {
    if(a->sign==0||b->sign==0){dec_zero(r);return;}
    r->sign=a->sign*b->sign; r->sc=a->sc+b->sc;
    bi_mul(r->d,&r->nd,a->d,a->nd,b->d,b->nd);
    dec_norm(r);
}

static int dec_cmp(const Dec *a, const Dec *b) {
    if(a->sign!=b->sign) return a->sign>b->sign?1:-1;
    if(a->sign==0) return 0;
    Dec ta,tb; dec_copy(&ta,a); dec_copy(&tb,b); dec_align(&ta,&tb);
    int c=bi_cmp(ta.d,ta.nd,tb.d,tb.nd);
    return a->sign>0?c:-c;
}

static void dec_round(Dec *a, int ts) {
    if(a->sign==0){a->sc=ts;return;}
    if(a->sc<=ts){
        int diff=ts-a->sc;
        if(diff>0){memmove(a->d+diff,a->d,a->nd*sizeof(int));memset(a->d,0,diff*sizeof(int));a->nd+=diff;}
        a->sc=ts; return;
    }
    int drop=a->sc-ts;
    int cmp_half=0;
    for(int i=drop-1;i>=0;i--){
        int expected=(i==drop-1)?5:0;
        int actual=(i<a->nd)?a->d[i]:0;
        if(actual>expected){cmp_half=1;break;}
        if(actual<expected){cmp_half=-1;break;}
    }
    if(a->nd>drop){memmove(a->d,a->d+drop,(a->nd-drop)*sizeof(int));a->nd-=drop;}
    else{a->nd=1;a->d[0]=0;}
    a->sc=ts;
    if(cmp_half>0||(cmp_half==0&&a->nd>0&&(a->d[0]&1))){
        int carry=1;
        for(int i=0;i<a->nd&&carry;i++){int s=a->d[i]+carry;a->d[i]=s%10;carry=s/10;}
        if(carry){memmove(a->d+1,a->d,a->nd*sizeof(int));a->d[0]=carry;a->nd++;}
    }
    dec_norm(a);
}

static void dec_format(const Dec *a, int minor, char *buf) {
    Dec tmp; dec_copy(&tmp,a); dec_round(&tmp,minor);
    char t[512]; int pos=0;
    if(tmp.sign<0) t[pos++]='-';
    int int_d=tmp.nd-tmp.sc;
    if(int_d<=0){t[pos++]='0';}
    else{
        for(int i=tmp.nd-1;i>=tmp.sc;i--){
            if(i<tmp.nd-1&&(tmp.nd-1-i)%3==0) t[pos++]=',';
            t[pos++]='0'+tmp.d[i];
        }
    }
    if(minor>0){
        t[pos++]='.';
        for(int i=tmp.sc-1;i>=0;i--){
            int dg=(i<tmp.nd)?tmp.d[i]:0;
            t[pos++]='0'+dg;
        }
    }
    t[pos]='\0'; strcpy(buf,t);
}

/* Data structures */
typedef struct { char code[64]; int minor; } Cur;
typedef struct { char name[256]; int ci; Dec bal, lim; } Acc;

static Cur curs[MAXCUR]; static int ncur=0;
static Acc accs[MAXACC]; static int nacc=0;

static int find_cur(const char *c){for(int i=0;i<ncur;i++)if(!strcmp(curs[i].code,c))return i;return -1;}
static int find_acc(const char *n){for(int i=0;i<nacc;i++)if(!strcmp(accs[i].name,n))return i;return -1;}

typedef struct { int line; char reason[512]; } Rej;
static Rej rejects[MAXACC*10]; static int nrej=0;

static void reject(int line, const char *fmt, ...) {
    rejects[nrej].line=line;
    va_list ap; va_start(ap,fmt);
    vsnprintf(rejects[nrej].reason,512,fmt,ap);
    va_end(ap);
    nrej++;
}

int main(int argc, char *argv[]) {
    (void)argc;
    char path[MAXLINE];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f) return 1;

    char line[MAXLINE];
    int lineno=0;

    while(fgets(line,sizeof(line),f)){
        lineno++;
        int len=(int)strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;

        int first=0;
        while(first<len&&line[first]==' ') first++;
        if(first>=len||line[first]=='#') continue;

        char *toks[MAXTOK]; int ntok=0;
        char *p=line;
        while(*p&&ntok<MAXTOK){
            while(*p==' ')p++;
            if(!*p)break;
            toks[ntok++]=p;
            while(*p&&*p!=' ')p++;
            if(*p)*p++=0;
        }
        if(ntok==0) continue;

        if(!strcmp(toks[0],"currency")){
            int ci=ncur++;
            strcpy(curs[ci].code,toks[1]);
            curs[ci].minor=atoi(toks[2]);
        }
        else if(!strcmp(toks[0],"open")){
            if(find_acc(toks[1])>=0){reject(lineno,"account exists %s",toks[1]);continue;}
            int ci=find_cur(toks[2]);
            int ai=nacc++;
            strcpy(accs[ai].name,toks[1]);
            accs[ai].ci=ci;
            dec_zero(&accs[ai].bal); accs[ai].bal.sc=curs[ci].minor;
            if(ntok>=4){dec_parse(toks[3],&accs[ai].lim);dec_round(&accs[ai].lim,curs[ci].minor);}
            else{dec_zero(&accs[ai].lim);accs[ai].lim.sc=curs[ci].minor;}
        }
        else if(!strcmp(toks[0],"deposit")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec amt; dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[ai].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            dec_add(&accs[ai].bal,&accs[ai].bal,&amt);
        }
        else if(!strcmp(toks[0],"withdraw")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec amt; dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[ai].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[ai].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[ai].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            dec_copy(&accs[ai].bal,&nb);
        }
        else if(!strcmp(toks[0],"transfer")){
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            int ti=find_acc(toks[2]);
            if(ti<0){reject(lineno,"unknown account %s",toks[2]);continue;}
            if(accs[fi].ci!=accs[ti].ci){reject(lineno,"currency mismatch");continue;}
            Dec amt; dec_parse(toks[3],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[fi].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            dec_copy(&accs[fi].bal,&nb);
            dec_add(&accs[ti].bal,&accs[ti].bal,&amt);
        }
        else if(!strcmp(toks[0],"convert")){
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            int ti=find_acc(toks[2]);
            if(ti<0){reject(lineno,"unknown account %s",toks[2]);continue;}
            Dec amt; dec_parse(toks[3],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
            if(amt.sign<=0){reject(lineno,"non-positive amount");continue;}
            Dec nb; dec_sub(&nb,&accs[fi].bal,&amt);
            Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
            if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);continue;}
            Dec rate; dec_parse(toks[4],&rate);
            Dec recv; dec_mul(&recv,&amt,&rate); dec_round(&recv,curs[accs[ti].ci].minor);
            dec_copy(&accs[fi].bal,&nb);
            dec_add(&accs[ti].bal,&accs[ti].bal,&recv);
        }
        else if(!strcmp(toks[0],"interest")){
            int ai=find_acc(toks[1]);
            if(ai<0){reject(lineno,"unknown account %s",toks[1]);continue;}
            Dec rate; dec_parse(toks[2],&rate);
            Dec gain; dec_mul(&gain,&accs[ai].bal,&rate); dec_round(&gain,curs[accs[ai].ci].minor);
            dec_add(&accs[ai].bal,&accs[ai].bal,&gain);
        }
        else if(!strcmp(toks[0],"split")){
            int rejected=0;
            int fi=find_acc(toks[1]);
            if(fi<0){reject(lineno,"unknown account %s",toks[1]);rejected=1;}
            int ntargets=ntok-3;
            int targs[MAXTOK]; Dec weights[MAXTOK];
            if(!rejected){
                for(int i=0;i<ntargets;i++){
                    char *colon=strchr(toks[3+i],':');
                    char nm[256]; int nl=(int)(colon-toks[3+i]);
                    memcpy(nm,toks[3+i],nl); nm[nl]=0;
                    int ti=find_acc(nm);
                    if(ti<0){reject(lineno,"unknown account %s",nm);rejected=1;break;}
                    targs[i]=ti;
                    dec_parse(colon+1,&weights[i]);
                }
            }
            if(!rejected){
                for(int i=0;i<ntargets;i++){
                    if(accs[targs[i]].ci!=accs[fi].ci){reject(lineno,"currency mismatch");rejected=1;break;}
                }
            }
            Dec amt;
            if(!rejected){
                dec_parse(toks[2],&amt); dec_round(&amt,curs[accs[fi].ci].minor);
                if(amt.sign<=0){reject(lineno,"non-positive amount");rejected=1;}
            }
            Dec nb;
            if(!rejected){
                dec_sub(&nb,&accs[fi].bal,&amt);
                Dec nl; dec_copy(&nl,&accs[fi].lim); if(nl.sign!=0)nl.sign=-nl.sign;
                if(dec_cmp(&nb,&nl)<0){reject(lineno,"insufficient funds %s",toks[1]);rejected=1;}
            }
            if(!rejected){
                Dec A; dec_copy(&A,&amt); A.sc=0;
                Dec W; dec_zero(&W);
                for(int i=0;i<ntargets;i++) dec_add(&W,&W,&weights[i]);
                Dec bases[MAXTOK],rems[MAXTOK];
                Dec sum_b; dec_zero(&sum_b);
                for(int i=0;i<ntargets;i++){
                    Dec prod; dec_mul(&prod,&A,&weights[i]);
                    int qd[MAXD],qnd,rd2[MAXD],rnd;
                    bi_divmod(qd,&qnd,rd2,&rnd,prod.d,prod.nd,W.d,W.nd);
                    bases[i].sign=1;bases[i].nd=qnd;bases[i].sc=0;
                    memcpy(bases[i].d,qd,qnd*sizeof(int)); dec_norm(&bases[i]);
                    rems[i].sign=1;rems[i].nd=rnd;rems[i].sc=0;
                    memcpy(rems[i].d,rd2,rnd*sizeof(int)); dec_norm(&rems[i]);
                    dec_add(&sum_b,&sum_b,&bases[i]);
                }
                Dec leftover; dec_sub(&leftover,&A,&sum_b);
                int lo=0;
                for(int i=leftover.nd-1;i>=0;i--) lo=lo*10+leftover.d[i];
                int order[MAXTOK];
                for(int i=0;i<ntargets;i++) order[i]=i;
                for(int i=1;i<ntargets;i++){
                    int key=order[i],j=i-1;
                    while(j>=0){
                        int c=dec_cmp(&rems[order[j]],&rems[key]);
                        if(c>0||(c==0&&order[j]<key)) break;
                        order[j+1]=order[j]; j--;
                    }
                    order[j+1]=key;
                }
                Dec one; dec_zero(&one); one.sign=1;one.d[0]=1;one.nd=1;one.sc=0;
                for(int i=0;i<lo;i++) dec_add(&bases[order[i]],&bases[order[i]],&one);
                dec_copy(&accs[fi].bal,&nb);
                for(int i=0;i<ntargets;i++){
                    Dec add_a; dec_copy(&add_a,&bases[i]);
                    add_a.sc=curs[accs[fi].ci].minor;
                    dec_add(&accs[targs[i]].bal,&accs[targs[i]].bal,&add_a);
                }
            }
        }
    }
    fclose(f);

    for(int i=0;i<nrej;i++) printf("line %d: REJECT %s\n",rejects[i].line,rejects[i].reason);
    printf("\n");

    int order[MAXACC];
    for(int i=0;i<nacc;i++) order[i]=i;
    for(int i=1;i<nacc;i++){
        int key=order[i],j=i-1;
        while(j>=0&&strcmp(accs[order[j]].name,accs[key].name)>0){order[j+1]=order[j];j--;}
        order[j+1]=key;
    }
    for(int i=0;i<nacc;i++){
        int ai=order[i]; char buf[512];
        dec_format(&accs[ai].bal,curs[accs[ai].ci].minor,buf);
        printf("%s %s %s\n",accs[ai].name,curs[accs[ai].ci].code,buf);
    }
    printf("\n");

    int ccount[MAXCUR]={0}; Dec ctotal[MAXCUR];
    for(int i=0;i<ncur;i++) dec_zero(&ctotal[i]);
    for(int i=0;i<nacc;i++){
        int ci=accs[i].ci; ccount[ci]++;
        dec_add(&ctotal[ci],&ctotal[ci],&accs[i].bal);
    }
    int active[MAXCUR],nact=0;
    for(int i=0;i<ncur;i++) if(ccount[i]>0) active[nact++]=i;
    for(int i=1;i<nact;i++){
        int key=active[i],j=i-1;
        while(j>=0&&strcmp(curs[active[j]].code,curs[key].code)>0){active[j+1]=active[j];j--;}
        active[j+1]=key;
    }
    for(int i=0;i<nact;i++){
        int ci=active[i]; char buf[512];
        dec_format(&ctotal[ci],curs[ci].minor,buf);
        printf("total %s %s (%d accounts)\n",curs[ci].code,buf,ccount[ci]);
    }
    return 0;
}

import sys
import json
import hmac
import hashlib
import base64
import os


def is_valid_base64url(s):
    if not s:
        return False
    valid_chars = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_')
    for c in s:
        if c not in valid_chars:
            return False
    if len(s) % 4 == 1:
        return False
    return True


def base64url_decode(s):
    padding = 4 - (len(s) % 4)
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)


def validate_token(token, keys, now, leeway, issuer, audience):
    # Rule 1: MALFORMED
    segments = token.split('.')
    if len(segments) != 3:
        return 'MALFORMED'

    for seg in segments:
        if seg == '':
            return 'MALFORMED'
        if not is_valid_base64url(seg):
            return 'MALFORMED'

    # Decode header and payload
    try:
        header_bytes = base64url_decode(segments[0])
        payload_bytes = base64url_decode(segments[1])
    except Exception:
        return 'MALFORMED'

    try:
        header = json.loads(header_bytes.decode('utf-8'))
        payload = json.loads(payload_bytes.decode('utf-8'))
    except Exception:
        return 'MALFORMED'

    if not isinstance(header, dict) or not isinstance(payload, dict):
        return 'MALFORMED'

    # Rule 2: UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
        return 'UNSUPPORTED_ALG'

    # Rule 3: UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys:
        return 'UNKNOWN_KEY'

    key = keys[kid]

    # Rule 4: ALG_MISMATCH
    if key['alg'] != alg:
        return 'ALG_MISMATCH'

    # Rule 5: BAD_SIGNATURE
    signing_input = (segments[0] + '.' + segments[1]).encode('ascii')
    secret = base64url_decode(key['k'])
    hash_func = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}[alg]
    expected_sig = hmac.new(secret, signing_input, hash_func).digest()

    try:
        actual_sig = base64url_decode(segments[2])
    except Exception:
        return 'BAD_SIGNATURE'

    if not hmac.compare_digest(expected_sig, actual_sig):
        return 'BAD_SIGNATURE'

    # Rule 6: EXPIRED
    if 'exp' in payload:
        exp = payload['exp']
        if now >= exp + leeway:
            return 'EXPIRED'

    # Rule 7: NOT_YET_VALID
    if 'nbf' in payload:
        nbf = payload['nbf']
        if now + leeway < nbf:
            return 'NOT_YET_VALID'

    # Rule 8: BAD_ISSUER
    iss = payload.get('iss')
    if not isinstance(iss, str) or iss != issuer:
        return 'BAD_ISSUER'

    # Rule 9: BAD_AUDIENCE
    aud = payload.get('aud')
    if aud is None:
        return 'BAD_AUDIENCE'
    if isinstance(aud, str):
        if aud != audience:
            return 'BAD_AUDIENCE'
    elif isinstance(aud, list):
        if audience not in aud:
            return 'BAD_AUDIENCE'
    else:
        return 'BAD_AUDIENCE'

    return 'VALID'


def main():
    dir_path = sys.argv[1]

    with open(os.path.join(dir_path, 'config.json'), 'r', encoding='utf-8') as f:
        config = json.load(f)

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = {k['kid']: k for k in config['keys']}

    with open(os.path.join(dir_path, 'tokens.txt'), 'r', encoding='utf-8') as f:
        lines = f.read().split('\n')

    valid_count = 0
    invalid_count = 0
    results = []

    token_num = 0
    for line in lines:
        stripped = line.strip(' \t')
        if stripped == '':
            continue
        token_num += 1

        result = validate_token(stripped, keys, now, leeway, issuer, audience)
        if result == 'VALID':
            valid_count += 1
        else:
            invalid_count += 1

        if result == 'VALID':
            segments = stripped.split('.')
            payload = json.loads(base64url_decode(segments[1]))
            sub = payload['sub']
            scope_str = payload.get('scope', '')
            if scope_str:
                scopes = sorted(set(s for s in scope_str.split(' ') if s))
                scope_str_out = ','.join(scopes)
            else:
                scope_str_out = ''
            results.append(f"{token_num}: VALID sub={sub} scope={scope_str_out}")
        else:
            results.append(f"{token_num}: {result}")

    for r in results:
        print(r)
    print()
    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == '__main__':
    main()

import Foundation

// MARK: - JSON Value

enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser

final class JSONParser {
    let bytes: [UInt8]
    var pos: Int

    init(_ s: String) {
        bytes = Array(s.utf8)
        pos = 0
    }

    func parse() -> JSONValue {
        skipWS()
        let v = parseValue()
        return v
    }

    func skipWS() {
        while pos < bytes.count {
            let c = bytes[pos]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D {
                pos += 1
            } else {
                break
            }
        }
    }

    func parseValue() -> JSONValue {
        skipWS()
        guard pos < bytes.count else { fatalError("Unexpected end") }
        let c = bytes[pos]
        switch c {
        case UInt8(ascii: "n"): pos += 4; return .null
        case UInt8(ascii: "t"): pos += 4; return .bool(true)
        case UInt8(ascii: "f"): pos += 5; return .bool(false)
        case UInt8(ascii: "\""): return .string(parseString())
        case UInt8(ascii: "["): return parseArray()
        case UInt8(ascii: "{"): return parseObject()
        default: return parseNumber()
        }
    }

    func parseString() -> String {
        pos += 1 // skip "
        var result: [UInt8] = []
        while pos < bytes.count {
            let c = bytes[pos]
            if c == UInt8(ascii: "\"") {
                pos += 1
                break
            } else if c == UInt8(ascii: "\\") {
                pos += 1
                let e = bytes[pos]
                pos += 1
                switch e {
                case UInt8(ascii: "\""): result.append(0x22)
                case UInt8(ascii: "\\"): result.append(0x5C)
                case UInt8(ascii: "/"): result.append(0x2F)
                case UInt8(ascii: "b"): result.append(0x08)
                case UInt8(ascii: "f"): result.append(0x0C)
                case UInt8(ascii: "n"): result.append(0x0A)
                case UInt8(ascii: "r"): result.append(0x0D)
                case UInt8(ascii: "t"): result.append(0x09)
                case UInt8(ascii: "u"):
                    let cp = parseHex4()
                    if cp >= 0xD800 && cp <= 0xDBFF {
                        // expect \uDC00-\uDFFF
                        pos += 1 // skip backslash
                        pos += 1 // skip 'u'
                        let low = parseHex4()
                        let combined: UInt32 = 0x10000 + (cp - 0xD800) * 0x400 + (low - 0xDC00)
                        appendUTF8(combined, to: &result)
                    } else {
                        appendUTF8(cp, to: &result)
                    }
                default:
                    fatalError("Invalid escape")
                }
            } else {
                result.append(c)
                pos += 1
            }
        }
        return String(decoding: result, as: UTF8.self)
    }

    func parseHex4() -> UInt32 {
        var value: UInt32 = 0
        for _ in 0..<4 {
            let c = bytes[pos]
            pos += 1
            if c >= UInt8(ascii: "0") && c <= UInt8(ascii: "9") {
                value = value * 16 + UInt32(c - UInt8(ascii: "0"))
            } else if c >= UInt8(ascii: "a") && c <= UInt8(ascii: "f") {
                value = value * 16 + UInt32(c - UInt8(ascii: "a") + 10)
            } else if c >= UInt8(ascii: "A") && c <= UInt8(ascii: "F") {
                value = value * 16 + UInt32(c - UInt8(ascii: "A") + 10)
            } else {
                fatalError("Invalid hex digit")
            }
        }
        return value
    }

    func appendUTF8(_ cp: UInt32, to result: inout [UInt8]) {
        if cp < 0x80 {
            result.append(UInt8(cp))
        } else if cp < 0x800 {
            result.append(UInt8(0xC0 | (cp >> 6)))
            result.append(UInt8(0x80 | (cp & 0x3F)))
        } else if cp < 0x10000 {
            result.append(UInt8(0xE0 | (cp >> 12)))
            result.append(UInt8(0x80 | ((cp >> 6) & 0x3F)))
            result.append(UInt8(0x80 | (cp & 0x3F)))
        } else {
            result.append(UInt8(0xF0 | (cp >> 18)))
            result.append(UInt8(0x80 | ((cp >> 12) & 0x3F)))
            result.append(UInt8(0x80 | ((cp >> 6) & 0x3F)))
            result.append(UInt8(0x80 | (cp & 0x3F)))
        }
    }

    func parseNumber() -> JSONValue {
        let start = pos
        if pos < bytes.count && bytes[pos] == UInt8(ascii: "-") { pos += 1 }
        while pos < bytes.count && bytes[pos] >= UInt8(ascii: "0") && bytes[pos] <= UInt8(ascii: "9") { pos += 1 }
        if pos < bytes.count && bytes[pos] == UInt8(ascii: ".") {
            pos += 1
            while pos < bytes.count && bytes[pos] >= UInt8(ascii: "0") && bytes[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        if pos < bytes.count && (bytes[pos] == UInt8(ascii: "e") || bytes[pos] == UInt8(ascii: "E")) {
            pos += 1
            if pos < bytes.count && (bytes[pos] == UInt8(ascii: "+") || bytes[pos] == UInt8(ascii: "-")) { pos += 1 }
            while pos < bytes.count && bytes[pos] >= UInt8(ascii: "0") && bytes[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        let numStr = String(decoding: bytes[start..<pos], as: UTF8.self)
        return .number(Double(numStr)!)
    }

    func parseArray() -> JSONValue {
        pos += 1 // skip [
        var elements: [JSONValue] = []
        skipWS()
        if pos < bytes.count && bytes[pos] == UInt8(ascii: "]") {
            pos += 1
            return .array(elements)
        }
        while true {
            elements.append(parseValue())
            skipWS()
            if bytes[pos] == UInt8(ascii: ",") {
                pos += 1
            } else {
                break
            }
        }
        pos += 1 // skip ]
        return .array(elements)
    }

    func parseObject() -> JSONValue {
        pos += 1 // skip {
        var members: [(String, JSONValue)] = []
        skipWS()
        if pos < bytes.count && bytes[pos] == UInt8(ascii: "}") {
            pos += 1
            return .object(members)
        }
        while true {
            skipWS()
            let key = parseString()
            skipWS()
            pos += 1 // skip :
            let value = parseValue()
            members.append((key, value))
            skipWS()
            if bytes[pos] == UInt8(ascii: ",") {
                pos += 1
            } else {
                break
            }
        }
        pos += 1 // skip }
        return .object(members)
    }
}

// MARK: - Utilities

func objectGet(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    for (k, v) in obj {
        if k == key { return v }
    }
    return nil
}

func objectKeys(_ obj: [(String, JSONValue)]) -> Set<String> {
    var s = Set<String>()
    for (k, _) in obj { s.insert(k) }
    return s
}

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.array(let x), .array(let y)):
        guard x.count == y.count else { return false }
        for i in 0..<x.count {
            if !deepEqual(x[i], y[i]) { return false }
        }
        return true
    case (.object(let x), .object(let y)):
        guard x.count == y.count else { return false }
        for (k, v) in x {
            guard let w = objectGet(y, k) else { return false }
            if !deepEqual(v, w) { return false }
        }
        return true
    default: return false
    }
}

func isIntegerValue(_ v: Double) -> Bool {
    return v == v.rounded(.towardZero)
}

func encodeToken(_ token: String) -> String {
    var result = ""
    for c in token {
        if c == "~" {
            result += "~0"
        } else if c == "/" {
            result += "~1"
        } else {
            result.append(c)
        }
    }
    return result
}

func appendToken(_ loc: String, _ token: String) -> String {
    return loc + "/" + encodeToken(token)
}

func appendIndex(_ loc: String, _ idx: Int) -> String {
    return loc + "/" + String(idx)
}

// MARK: - Validation

struct ValidationError: Hashable {
    let instanceLoc: String
    let schemaLoc: String
}

func typeMatches(_ instance: JSONValue, _ typeName: String) -> Bool {
    switch typeName {
    case "null": return isNull(instance)
    case "boolean": return isBool(instance)
    case "object": return isObject(instance)
    case "array": return isArray(instance)
    case "number": return isNum(instance)
    case "string": return isStr(instance)
    case "integer":
        if case .number(let v) = instance { return isIntegerValue(v) }
        return false
    default: return false
    }
}

func isNull(_ v: JSONValue) -> Bool { if case .null = v { return true }; return false }
func isBool(_ v: JSONValue) -> Bool { if case .bool = v { return true }; return false }
func isObject(_ v: JSONValue) -> Bool { if case .object = v { return true }; return false }
func isArray(_ v: JSONValue) -> Bool { if case .array = v { return true }; return false }
func isNum(_ v: JSONValue) -> Bool { if case .number = v { return true }; return false }
func isStr(_ v: JSONValue) -> Bool { if case .string = v { return true }; return false }

func resolveRef(_ ref: String, rootSchema: JSONValue) -> (JSONValue, String) {
    if ref == "#" {
        return (rootSchema, "#")
    }
    // ref is like "#/$defs/name"
    let path = String(ref.dropFirst()) // "/$defs/name"
    let parts = path.components(separatedBy: "/")
    // parts[0] is "" (from leading /), parts[1] = "$defs", parts[2] = name
    var current = rootSchema
    for i in 1..<parts.count {
        var token = parts[i]
        token = token.replacingOccurrences(of: "~1", with: "/")
        token = token.replacingOccurrences(of: "~0", with: "~")
        if case .object(let members) = current {
            if let next = objectGet(members, token) {
                current = next
            } else {
                return (.bool(true), ref)
            }
        } else {
            return (.bool(true), ref)
        }
    }
    return (current, ref)
}

func validate(instance: JSONValue, schema: JSONValue, instanceLoc: String, schemaLoc: String, rootSchema: JSONValue) -> Set<ValidationError> {
    var errors = Set<ValidationError>()

    switch schema {
    case .bool(true):
        return errors
    case .bool(false):
        errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: schemaLoc))
        return errors
    case .object(let members):
        // type
        if let typeVal = objectGet(members, "type") {
            let typeNames: [String]
            switch typeVal {
            case .string(let s): typeNames = [s]
            case .array(let arr): typeNames = arr.compactMap { if case .string(let s) = $0 { return s } else { return nil } }
            default: typeNames = []
            }
            var matched = false
            for t in typeNames {
                if typeMatches(instance, t) { matched = true; break }
            }
            if !typeNames.isEmpty && !matched {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "type")))
            }
        }

        // enum
        if let enumVal = objectGet(members, "enum"), case .array(let arr) = enumVal {
            var found = false
            for elem in arr {
                if deepEqual(instance, elem) { found = true; break }
            }
            if !found {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "enum")))
            }
        }

        // const
        if let constVal = objectGet(members, "const") {
            if !deepEqual(instance, constVal) {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "const")))
            }
        }

        // Numeric keywords
        if case .number(let num) = instance {
            if let v = objectGet(members, "minimum"), case .number(let minV) = v {
                if num < minV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "minimum")))
                }
            }
            if let v = objectGet(members, "maximum"), case .number(let maxV) = v {
                if num > maxV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "maximum")))
                }
            }
            if let v = objectGet(members, "exclusiveMinimum"), case .number(let minV) = v {
                if num <= minV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "exclusiveMinimum")))
                }
            }
            if let v = objectGet(members, "exclusiveMaximum"), case .number(let maxV) = v {
                if num >= maxV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "exclusiveMaximum")))
                }
            }
        }

        // String keywords
        if case .string(let str) = instance {
            let len = str.unicodeScalars.count
            if let v = objectGet(members, "minLength"), case .number(let minV) = v {
                if Double(len) < minV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "minLength")))
                }
            }
            if let v = objectGet(members, "maxLength"), case .number(let maxV) = v {
                if Double(len) > maxV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "maxLength")))
                }
            }
        }

        // Array keywords
        if case .array(let arr) = instance {
            if let v = objectGet(members, "minItems"), case .number(let minV) = v {
                if Double(arr.count) < minV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "minItems")))
                }
            }
            if let v = objectGet(members, "maxItems"), case .number(let maxV) = v {
                if Double(arr.count) > maxV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "maxItems")))
                }
            }
            if let v = objectGet(members, "uniqueItems"), case .bool(true) = v {
                var hasDup = false
                outer: for i in 0..<arr.count {
                    for j in (i+1)..<arr.count {
                        if deepEqual(arr[i], arr[j]) {
                            hasDup = true
                            break outer
                        }
                    }
                }
                if hasDup {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "uniqueItems")))
                }
            }

            // prefixItems
            if let v = objectGet(members, "prefixItems"), case .array(let schemas) = v {
                let count = min(arr.count, schemas.count)
                for i in 0..<count {
                    let subErrors = validate(instance: arr[i], schema: schemas[i],
                                            instanceLoc: appendIndex(instanceLoc, i),
                                            schemaLoc: appendIndex(appendToken(schemaLoc, "prefixItems"), i),
                                            rootSchema: rootSchema)
                    errors.formUnion(subErrors)
                }
            }

            // items
            if let v = objectGet(members, "items") {
                let prefixLen: Int
                if let pi = objectGet(members, "prefixItems"), case .array(let schemas) = pi {
                    prefixLen = schemas.count
                } else {
                    prefixLen = 0
                }
                if prefixLen < arr.count {
                    for i in prefixLen..<arr.count {
                        let subErrors = validate(instance: arr[i], schema: v,
                                                instanceLoc: appendIndex(instanceLoc, i),
                                                schemaLoc: appendToken(schemaLoc, "items"),
                                                rootSchema: rootSchema)
                        errors.formUnion(subErrors)
                    }
                }
            }
        }

        // Object keywords
        if case .object(let objMembers) = instance {
            if let v = objectGet(members, "minProperties"), case .number(let minV) = v {
                if Double(objMembers.count) < minV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "minProperties")))
                }
            }
            if let v = objectGet(members, "maxProperties"), case .number(let maxV) = v {
                if Double(objMembers.count) > maxV {
                    errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "maxProperties")))
                }
            }

            // required
            if let v = objectGet(members, "required"), case .array(let reqArr) = v {
                let instKeys = objectKeys(objMembers)
                for (j, reqVal) in reqArr.enumerated() {
                    if case .string(let name) = reqVal {
                        if !instKeys.contains(name) {
                            errors.insert(ValidationError(instanceLoc: instanceLoc,
                                                         schemaLoc: appendIndex(appendToken(schemaLoc, "required"), j)))
                        }
                    }
                }
            }

            // properties
            let propKeys: Set<String>
            if let v = objectGet(members, "properties"), case .object(let propObj) = v {
                propKeys = objectKeys(propObj)
                for (name, subSchema) in propObj {
                    if let memberValue = objectGet(objMembers, name) {
                        let subErrors = validate(instance: memberValue, schema: subSchema,
                                                instanceLoc: appendToken(instanceLoc, name),
                                                schemaLoc: appendToken(appendToken(schemaLoc, "properties"), name),
                                                rootSchema: rootSchema)
                        errors.formUnion(subErrors)
                    }
                }
            } else {
                propKeys = []
            }

            // additionalProperties
            if let v = objectGet(members, "additionalProperties") {
                for (name, memberValue) in objMembers {
                    if !propKeys.contains(name) {
                        let subErrors = validate(instance: memberValue, schema: v,
                                                instanceLoc: appendToken(instanceLoc, name),
                                                schemaLoc: appendToken(schemaLoc, "additionalProperties"),
                                                rootSchema: rootSchema)
                        errors.formUnion(subErrors)
                    }
                }
            }
        }

        // allOf
        if let v = objectGet(members, "allOf"), case .array(let schemas) = v {
            for (i, subSchema) in schemas.enumerated() {
                let subErrors = validate(instance: instance, schema: subSchema,
                                        instanceLoc: instanceLoc,
                                        schemaLoc: appendIndex(appendToken(schemaLoc, "allOf"), i),
                                        rootSchema: rootSchema)
                errors.formUnion(subErrors)
            }
        }

        // anyOf
        if let v = objectGet(members, "anyOf"), case .array(let schemas) = v {
            var anyAccepted = false
            for subSchema in schemas {
                let subErrors = validate(instance: instance, schema: subSchema,
                                        instanceLoc: instanceLoc,
                                        schemaLoc: "",
                                        rootSchema: rootSchema)
                if subErrors.isEmpty {
                    anyAccepted = true
                    break
                }
            }
            if !anyAccepted {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "anyOf")))
            }
        }

        // oneOf
        if let v = objectGet(members, "oneOf"), case .array(let schemas) = v {
            var count = 0
            for subSchema in schemas {
                let subErrors = validate(instance: instance, schema: subSchema,
                                        instanceLoc: instanceLoc,
                                        schemaLoc: "",
                                        rootSchema: rootSchema)
                if subErrors.isEmpty {
                    count += 1
                }
            }
            if count != 1 {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "oneOf")))
            }
        }

        // not
        if let v = objectGet(members, "not") {
            let subErrors = validate(instance: instance, schema: v,
                                    instanceLoc: instanceLoc,
                                    schemaLoc: "",
                                    rootSchema: rootSchema)
            if subErrors.isEmpty {
                errors.insert(ValidationError(instanceLoc: instanceLoc, schemaLoc: appendToken(schemaLoc, "not")))
            }
        }

        // if/then/else
        if let ifSchema = objectGet(members, "if") {
            let ifErrors = validate(instance: instance, schema: ifSchema,
                                   instanceLoc: instanceLoc,
                                   schemaLoc: "",
                                   rootSchema: rootSchema)
            if ifErrors.isEmpty {
                if let thenSchema = objectGet(members, "then") {
                    let thenErrors = validate(instance: instance, schema: thenSchema,
                                             instanceLoc: instanceLoc,
                                             schemaLoc: appendToken(schemaLoc, "then"),
                                             rootSchema: rootSchema)
                    errors.formUnion(thenErrors)
                }
            } else {
                if let elseSchema = objectGet(members, "else") {
                    let elseErrors = validate(instance: instance, schema: elseSchema,
                                             instanceLoc: instanceLoc,
                                             schemaLoc: appendToken(schemaLoc, "else"),
                                             rootSchema: rootSchema)
                    errors.formUnion(elseErrors)
                }
            }
        }

        // $ref
        if let v = objectGet(members, "$ref"), case .string(let refStr) = v {
            let (targetSchema, targetLoc) = resolveRef(refStr, rootSchema: rootSchema)
            let refErrors = validate(instance: instance, schema: targetSchema,
                                    instanceLoc: instanceLoc,
                                    schemaLoc: targetLoc,
                                    rootSchema: rootSchema)
            errors.formUnion(refErrors)
        }

    default:
        break
    }

    return errors
}

// MARK: - Main

let dir = CommandLine.arguments[1]
let schemaPath = dir + "/schema.json"
let instancesPath = dir + "/instances.json"

let schemaStr = try! String(contentsOfFile: schemaPath, encoding: .utf8)
let instancesStr = try! String(contentsOfFile: instancesPath, encoding: .utf8)

let schemaParser = JSONParser(schemaStr)
let rootSchema = schemaParser.parse()

let instancesParser = JSONParser(instancesStr)
let instancesVal = instancesParser.parse()

var validCount = 0
var invalidCount = 0

if case .array(let instArr) = instancesVal {
    for (n, inst) in instArr.enumerated() {
        let errors = validate(instance: inst, schema: rootSchema,
                             instanceLoc: "#", schemaLoc: "#", rootSchema: rootSchema)
        if errors.isEmpty {
            print("\(n): valid")
            validCount += 1
        } else {
            print("\(n): invalid (\(errors.count))")
            let sorted = errors.sorted { a, b in
                let aI = Array(a.instanceLoc.utf8)
                let bI = Array(b.instanceLoc.utf8)
                if aI != bI {
                    return aI.lexicographicallyPrecedes(bI)
                }
                let aS = Array(a.schemaLoc.utf8)
                let bS = Array(b.schemaLoc.utf8)
                return aS.lexicographicallyPrecedes(bS)
            }
            for e in sorted {
                print("  \(e.instanceLoc) \(e.schemaLoc)")
            }
            invalidCount += 1
        }
    }
}

print("valid=\(validCount) invalid=\(invalidCount)")

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String configStr = new String(Files.readAllBytes(Paths.get(dir, "config.json")), StandardCharsets.UTF_8);
        String tokensStr = new String(Files.readAllBytes(Paths.get(dir, "tokens.txt")), StandardCharsets.UTF_8);

        Map<String, Object> config = (Map<String, Object>) parseJson(configStr);
        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");

        @SuppressWarnings("unchecked")
        List<Object> keysList = (List<Object>) config.get("keys");
        Map<String, Map<String, Object>> keyMap = new HashMap<>();
        for (Object ko : keysList) {
            @SuppressWarnings("unchecked")
            Map<String, Object> k = (Map<String, Object>) ko;
            keyMap.put((String) k.get("kid"), k);
        }

        String[] lines = tokensStr.split("\n", -1);
        int n = 0;
        int validCount = 0;
        int invalidCount = 0;
        StringBuilder output = new StringBuilder();

        for (String line : lines) {
            String trimmed = trimSpacesTabs(line);
            if (trimmed.isEmpty()) continue;
            n++;

            String result = validateToken(trimmed, keyMap, now, leeway, issuer, audience);
            if (result.startsWith("VALID")) {
                validCount++;
            } else {
                invalidCount++;
            }
            output.append(n).append(": ").append(result).append("\n");
        }

        output.append("\n");
        output.append("valid=").append(validCount).append(" invalid=").append(invalidCount);
        System.out.print(output.toString());
    }

    static String trimSpacesTabs(String s) {
        int start = 0, end = s.length();
        while (start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t')) start++;
        while (end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t')) end--;
        return s.substring(start, end);
    }

    static String validateToken(String token, Map<String, Map<String, Object>> keyMap,
                                double now, double leeway, String issuer, String audience) {
        // Rule 1: MALFORMED
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) return "MALFORMED";
        for (String p : parts) {
            if (p.isEmpty()) return "MALFORMED";
            if (!isValidBase64url(p)) return "MALFORMED";
        }

        byte[] headerBytes, payloadBytes, sigBytes;
        try {
            headerBytes = base64urlDecode(parts[0]);
            payloadBytes = base64urlDecode(parts[1]);
            sigBytes = base64urlDecode(parts[2]);
        } catch (Exception e) {
            return "MALFORMED";
        }

        Object headerObj, payloadObj;
        try {
            headerObj = parseJson(new String(headerBytes, StandardCharsets.UTF_8));
            payloadObj = parseJson(new String(payloadBytes, StandardCharsets.UTF_8));
        } catch (Exception e) {
            return "MALFORMED";
        }

        if (!(headerObj instanceof Map) || !(payloadObj instanceof Map)) return "MALFORMED";

        @SuppressWarnings("unchecked")
        Map<String, Object> header = (Map<String, Object>) headerObj;
        @SuppressWarnings("unchecked")
        Map<String, Object> payload = (Map<String, Object>) payloadObj;

        // Rule 2: UNSUPPORTED_ALG
        Object algObj = header.get("alg");
        if (!(algObj instanceof String)) return "UNSUPPORTED_ALG";
        String alg = (String) algObj;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) return "UNSUPPORTED_ALG";

        // Rule 3: UNKNOWN_KEY
        Object kidObj = header.get("kid");
        if (!(kidObj instanceof String)) return "UNKNOWN_KEY";
        String kid = (String) kidObj;
        Map<String, Object> key = keyMap.get(kid);
        if (key == null) return "UNKNOWN_KEY";

        // Rule 4: ALG_MISMATCH
        String keyAlg = (String) key.get("alg");
        if (!alg.equals(keyAlg)) return "ALG_MISMATCH";

        // Rule 5: BAD_SIGNATURE
        String kStr = (String) key.get("k");
        byte[] secret;
        try {
            secret = base64urlDecode(kStr);
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        String signingInput = parts[0] + "." + parts[1];
        byte[] signingInputBytes = signingInput.getBytes(StandardCharsets.US_ASCII);

        String macAlgo;
        if (alg.equals("HS256")) macAlgo = "HmacSHA256";
        else if (alg.equals("HS384")) macAlgo = "HmacSHA384";
        else macAlgo = "HmacSHA512";

        try {
            Mac mac = Mac.getInstance(macAlgo);
            mac.init(new SecretKeySpec(secret, macAlgo));
            byte[] expectedSig = mac.doFinal(signingInputBytes);
            if (!Arrays.equals(expectedSig, sigBytes)) return "BAD_SIGNATURE";
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        // Rule 6: EXPIRED
        if (payload.containsKey("exp")) {
            double exp = ((Number) payload.get("exp")).doubleValue();
            if (now >= exp + leeway) return "EXPIRED";
        }

        // Rule 7: NOT_YET_VALID
        if (payload.containsKey("nbf")) {
            double nbf = ((Number) payload.get("nbf")).doubleValue();
            if (now + leeway < nbf) return "NOT_YET_VALID";
        }

        // Rule 8: BAD_ISSUER
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !issObj.equals(issuer)) return "BAD_ISSUER";

        // Rule 9: BAD_AUDIENCE
        Object audObj = payload.get("aud");
        if (audObj == null) return "BAD_AUDIENCE";
        if (audObj instanceof String) {
            if (!audObj.equals(audience)) return "BAD_AUDIENCE";
        } else if (audObj instanceof List) {
            @SuppressWarnings("unchecked")
            List<Object> audList = (List<Object>) audObj;
            boolean found = false;
            for (Object o : audList) {
                if (audience.equals(o)) { found = true; break; }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = (String) payload.get("sub");
        String scopeStr = (String) payload.get("scope");
        String scopes = "";
        if (scopeStr != null && !scopeStr.isEmpty()) {
            String[] tokens = scopeStr.split(" ");
            TreeSet<String> set = new TreeSet<>(Main::compareByCodePoint);
            for (String t : tokens) {
                if (!t.isEmpty()) set.add(t);
            }
            scopes = String.join(",", set);
        }
        return "VALID sub=" + sub + " scope=" + scopes;
    }

    static int compareByCodePoint(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }

    static boolean isValidBase64url(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'))
                return false;
        }
        if (s.length() % 4 == 1) return false;
        return true;
    }

    static byte[] base64urlDecode(String s) {
        String standard = s.replace('-', '+').replace('_', '/');
        int mod = standard.length() % 4;
        if (mod == 2) standard += "==";
        else if (mod == 3) standard += "=";
        return Base64.getDecoder().decode(standard);
    }

    // --- JSON Parser ---
    static int pos;
    static String json;

    static Object parseJson(String input) {
        json = input;
        pos = 0;
        skipWs();
        Object val = parseValue();
        skipWs();
        return val;
    }

    static void skipWs() {
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
            else break;
        }
    }

    static Object parseValue() {
        skipWs();
        if (pos >= json.length()) throw new RuntimeException("Unexpected end of JSON");
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't') return parseLiteral("true", Boolean.TRUE);
        if (c == 'f') return parseLiteral("false", Boolean.FALSE);
        if (c == 'n') return parseLiteral("null", null);
        return parseNumber();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++; // skip {
        skipWs();
        if (pos < json.length() && json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            if (json.charAt(pos) != ':') throw new RuntimeException("Expected :");
            pos++;
            skipWs();
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            if (pos >= json.length()) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) == ',') { pos++; continue; }
            if (json.charAt(pos) == '}') { pos++; break; }
            throw new RuntimeException("Expected , or }");
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++; // skip [
        skipWs();
        if (pos < json.length() && json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            skipWs();
            Object val = parseValue();
            list.add(val);
            skipWs();
            if (pos >= json.length()) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) == ',') { pos++; continue; }
            if (json.charAt(pos) == ']') { pos++; break; }
            throw new RuntimeException("Expected , or ]");
        }
        return list;
    }

    static String parseString() {
        if (json.charAt(pos) != '"') throw new RuntimeException("Expected \"");
        pos++;
        StringBuilder sb = new StringBuilder();
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == '"') { pos++; return sb.toString(); }
            if (c == '\\') {
                pos++;
                if (pos >= json.length()) throw new RuntimeException("Unexpected end");
                char esc = json.charAt(pos);
                pos++;
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        String hex = json.substring(pos, pos + 4);
                        pos += 4;
                        int cp = Integer.parseInt(hex, 16);
                        sb.append((char) cp);
                        break;
                    default: throw new RuntimeException("Invalid escape");
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        throw new RuntimeException("Unterminated string");
    }

    static Object parseLiteral(String expected, Object val) {
        if (json.startsWith(expected, pos)) {
            pos += expected.length();
            return val;
        }
        throw new RuntimeException("Invalid literal");
    }

    static Object parseNumber() {
        int start = pos;
        if (pos < json.length() && json.charAt(pos) == '-') pos++;
        while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        if (pos < json.length() && json.charAt(pos) == '.') {
            pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
            pos++;
            if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        return Double.parseDouble(json.substring(start, pos));
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

const dir = process.argv[2];
const config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf-8');

const lines = tokensRaw.split('\n');
const tokens: string[] = [];
for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.length > 0) {
        tokens.push(trimmed);
    }
}

const now: number = config.now;
const leeway: number = config.leeway;
const issuer: string = config.issuer;
const audience: string = config.audience;

const keys = new Map<string, { kid: string; kty: string; alg: string; k: string }>();
for (const key of config.keys) {
    keys.set(key.kid, key);
}

function isValidBase64url(s: string): boolean {
    if (s.length === 0) return true;
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (!((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch === '-' || ch === '_')) {
            return false;
        }
    }
    if (s.length % 4 === 1) return false;
    return true;
}

function base64urlDecode(s: string): Buffer {
    let base64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const pad = (4 - (base64.length % 4)) % 4;
    base64 += '='.repeat(pad);
    return Buffer.from(base64, 'base64');
}

function isJsonObject(value: unknown): boolean {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(obj: any, key: string): boolean {
    return Object.prototype.hasOwnProperty.call(obj, key);
}

function checkToken(token: string): string {
    const parts = token.split('.');

    // Rule 1: MALFORMED
    if (parts.length !== 3) return 'MALFORMED';
    for (const part of parts) {
        if (part.length === 0) return 'MALFORMED';
        if (!isValidBase64url(part)) return 'MALFORMED';
    }

    let header: any;
    let payload: any;
    try {
        const headerJson = base64urlDecode(parts[0]).toString('utf-8');
        header = JSON.parse(headerJson);
    } catch {
        return 'MALFORMED';
    }
    try {
        const payloadJson = base64urlDecode(parts[1]).toString('utf-8');
        payload = JSON.parse(payloadJson);
    } catch {
        return 'MALFORMED';
    }

    if (!isJsonObject(header)) return 'MALFORMED';
    if (!isJsonObject(payload)) return 'MALFORMED';

    // Rule 2: UNSUPPORTED_ALG
    const alg = header.alg;
    if (typeof alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(alg)) {
        return 'UNSUPPORTED_ALG';
    }

    // Rule 3: UNKNOWN_KEY
    const kid = header.kid;
    if (typeof kid !== 'string') return 'UNKNOWN_KEY';
    const key = keys.get(kid);
    if (!key) return 'UNKNOWN_KEY';

    // Rule 4: ALG_MISMATCH
    if (key.alg !== alg) return 'ALG_MISMATCH';

    // Rule 5: BAD_SIGNATURE
    const signingInput = parts[0] + '.' + parts[1];
    const secret = base64urlDecode(key.k);
    const hashAlg = alg === 'HS256' ? 'sha256' : alg === 'HS384' ? 'sha384' : 'sha512';
    const expectedSig = crypto.createHmac(hashAlg, secret).update(signingInput, 'ascii').digest();
    const actualSig = base64urlDecode(parts[2]);

    if (actualSig.length !== expectedSig.length) return 'BAD_SIGNATURE';
    if (!crypto.timingSafeEqual(expectedSig, actualSig)) return 'BAD_SIGNATURE';

    // Rule 6: EXPIRED
    if (hasOwn(payload, 'exp')) {
        if (now >= payload.exp + leeway) return 'EXPIRED';
    }

    // Rule 7: NOT_YET_VALID
    if (hasOwn(payload, 'nbf')) {
        if (now + leeway < payload.nbf) return 'NOT_YET_VALID';
    }

    // Rule 8: BAD_ISSUER
    if (!hasOwn(payload, 'iss') || payload.iss !== issuer) {
        return 'BAD_ISSUER';
    }

    // Rule 9: BAD_AUDIENCE
    if (!hasOwn(payload, 'aud')) return 'BAD_AUDIENCE';
    const aud = payload.aud;
    if (typeof aud === 'string') {
        if (aud !== audience) return 'BAD_AUDIENCE';
    } else if (Array.isArray(aud)) {
        if (!aud.includes(audience)) return 'BAD_AUDIENCE';
    } else {
        return 'BAD_AUDIENCE';
    }

    // VALID
    const sub: string = payload.sub;
    let scopes: string[] = [];
    if (typeof payload.scope === 'string' && payload.scope.length > 0) {
        const scopeParts = payload.scope.split(' ').filter(s => s.length > 0);
        const unique = [...new Set(scopeParts)];
        unique.sort((a, b) => {
            if (a < b) return -1;
            if (a > b) return 1;
            return 0;
        });
        scopes = unique;
    }

    return `VALID sub=${sub} scope=${scopes.join(',')}`;
}

let validCount = 0;
let invalidCount = 0;
const results: string[] = [];

for (let i = 0; i < tokens.length; i++) {
    const result = checkToken(tokens[i]);
    results.push(`${i + 1}: ${result}`);
    if (result.startsWith('VALID')) {
        validCount++;
    } else {
        invalidCount++;
    }
}

console.log(results.join('\n'));
console.log('');
console.log(`valid=${validCount} invalid=${invalidCount}`);

import * as fs from 'fs';
import * as path from 'path';

function encodePointerToken(token: string): string {
    return token.replace(/~/g, '~0').replace(/\//g, '~1');
}

function decodePointerToken(token: string): string {
    return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

function compareByCodePoint(a: string, b: string): number {
    const aPoints = Array.from(a);
    const bPoints = Array.from(b);
    const minLen = Math.min(aPoints.length, bPoints.length);
    for (let i = 0; i < minLen; i++) {
        const cpA = aPoints[i].codePointAt(0)!;
        const cpB = bPoints[i].codePointAt(0)!;
        if (cpA < cpB) return -1;
        if (cpA > cpB) return 1;
    }
    return aPoints.length - bPoints.length;
}

function deepEqual(a: any, b: any): boolean {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
    if (typeof a === 'number' && typeof b === 'number') return a === b;
    if (typeof a === 'string' && typeof b === 'string') return a === b;
    if (typeof a !== typeof b) return false;
    if (Array.isArray(a) && Array.isArray(b)) {
        if (a.length !== b.length) return false;
        for (let i = 0; i < a.length; i++) {
            if (!deepEqual(a[i], b[i])) return false;
        }
        return true;
    }
    if (typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
        const aKeys = Object.keys(a).sort();
        const bKeys = Object.keys(b).sort();
        if (aKeys.length !== bKeys.length) return false;
        for (let i = 0; i < aKeys.length; i++) {
            if (aKeys[i] !== bKeys[i]) return false;
        }
        for (const key of aKeys) {
            if (!deepEqual(a[key], b[key])) return false;
        }
        return true;
    }
    return false;
}

function checkSingleType(instance: any, type: string): boolean {
    switch (type) {
        case 'null': return instance === null;
        case 'boolean': return typeof instance === 'boolean';
        case 'object': return instance !== null && typeof instance === 'object' && !Array.isArray(instance);
        case 'array': return Array.isArray(instance);
        case 'number': return typeof instance === 'number';
        case 'string': return typeof instance === 'string';
        case 'integer': return typeof instance === 'number' && Number.isInteger(instance);
        default: return false;
    }
}

function checkType(instance: any, type: string | string[]): boolean {
    const types = Array.isArray(type) ? type : [type];
    return types.some(t => checkSingleType(instance, t));
}

function resolveRef(ref: string, rootSchema: any): { schema: any; location: string } {
    if (ref === '#') {
        return { schema: rootSchema, location: '#' };
    }
    const prefix = '#/$defs/';
    if (ref.startsWith(prefix)) {
        const encodedName = ref.substring(prefix.length);
        const decodedName = decodePointerToken(encodedName);
        const schema = rootSchema.$defs[decodedName];
        return { schema, location: ref };
    }
    throw new Error(`Unsupported $ref: ${ref}`);
}

function validate(instance: any, schema: any, instanceLoc: string, schemaLoc: string, rootSchema: any): Set<string> {
    const errors = new Set<string>();

    if (schema === true) return errors;
    if (schema === false) {
        errors.add(JSON.stringify([instanceLoc, schemaLoc]));
        return errors;
    }

    // type
    if ('type' in schema) {
        if (!checkType(instance, schema.type)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/type`]));
        }
    }

    // enum
    if ('enum' in schema) {
        if (!schema.enum.some((e: any) => deepEqual(instance, e))) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/enum`]));
        }
    }

    // const
    if ('const' in schema) {
        if (!deepEqual(instance, schema.const)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/const`]));
        }
    }

    // Number keywords
    if (typeof instance === 'number') {
        if ('minimum' in schema && !(instance >= schema.minimum)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/minimum`]));
        }
        if ('maximum' in schema && !(instance <= schema.maximum)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/maximum`]));
        }
        if ('exclusiveMinimum' in schema && !(instance > schema.exclusiveMinimum)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/exclusiveMinimum`]));
        }
        if ('exclusiveMaximum' in schema && !(instance < schema.exclusiveMaximum)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/exclusiveMaximum`]));
        }
    }

    // String keywords
    if (typeof instance === 'string') {
        const len = Array.from(instance).length;
        if ('minLength' in schema && !(len >= schema.minLength)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/minLength`]));
        }
        if ('maxLength' in schema && !(len <= schema.maxLength)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/maxLength`]));
        }
    }

    // Array keywords
    if (Array.isArray(instance)) {
        if ('minItems' in schema && !(instance.length >= schema.minItems)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/minItems`]));
        }
        if ('maxItems' in schema && !(instance.length <= schema.maxItems)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/maxItems`]));
        }
        if (schema.uniqueItems === true) {
            let hasDuplicate = false;
            outer:
            for (let i = 0; i < instance.length; i++) {
                for (let j = i + 1; j < instance.length; j++) {
                    if (deepEqual(instance[i], instance[j])) {
                        hasDuplicate = true;
                        break outer;
                    }
                }
            }
            if (hasDuplicate) {
                errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/uniqueItems`]));
            }
        }

        // prefixItems
        if ('prefixItems' in schema) {
            const prefixItems: any[] = schema.prefixItems;
            for (let i = 0; i < Math.min(instance.length, prefixItems.length); i++) {
                const subErrors = validate(instance[i], prefixItems[i], `${instanceLoc}/${i}`, `${schemaLoc}/prefixItems/${i}`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        }

        // items
        if ('items' in schema) {
            const startIdx = 'prefixItems' in schema ? (schema.prefixItems as any[]).length : 0;
            for (let i = startIdx; i < instance.length; i++) {
                const subErrors = validate(instance[i], schema.items, `${instanceLoc}/${i}`, `${schemaLoc}/items`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        }
    }

    // Object keywords
    if (instance !== null && typeof instance === 'object' && !Array.isArray(instance)) {
        const instanceKeys = Object.keys(instance);
        const instanceKeySet = new Set(instanceKeys);

        // required
        if ('required' in schema) {
            for (let j = 0; j < schema.required.length; j++) {
                if (!instanceKeySet.has(schema.required[j])) {
                    errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/required/${j}`]));
                }
            }
        }

        // properties
        if ('properties' in schema) {
            for (const key of Object.keys(schema.properties)) {
                if (instanceKeySet.has(key)) {
                    const encKey = encodePointerToken(key);
                    const subErrors = validate(instance[key], schema.properties[key], `${instanceLoc}/${encKey}`, `${schemaLoc}/properties/${encKey}`, rootSchema);
                    for (const e of subErrors) errors.add(e);
                }
            }
        }

        // additionalProperties
        if ('additionalProperties' in schema) {
            const knownKeys = new Set('properties' in schema ? Object.keys(schema.properties) : []);
            for (const key of instanceKeys) {
                if (!knownKeys.has(key)) {
                    const encKey = encodePointerToken(key);
                    const subErrors = validate(instance[key], schema.additionalProperties, `${instanceLoc}/${encKey}`, `${schemaLoc}/additionalProperties`, rootSchema);
                    for (const e of subErrors) errors.add(e);
                }
            }
        }

        // minProperties / maxProperties
        if ('minProperties' in schema && !(instanceKeys.length >= schema.minProperties)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/minProperties`]));
        }
        if ('maxProperties' in schema && !(instanceKeys.length <= schema.maxProperties)) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/maxProperties`]));
        }
    }

    // Applicators
    if ('allOf' in schema) {
        for (let i = 0; i < schema.allOf.length; i++) {
            const subErrors = validate(instance, schema.allOf[i], instanceLoc, `${schemaLoc}/allOf/${i}`, rootSchema);
            for (const e of subErrors) errors.add(e);
        }
    }

    if ('anyOf' in schema) {
        const anyValid = schema.anyOf.some((sub: any) => validate(instance, sub, instanceLoc, '#', rootSchema).size === 0);
        if (!anyValid) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/anyOf`]));
        }
    }

    if ('oneOf' in schema) {
        let validCount = 0;
        for (const sub of schema.oneOf) {
            if (validate(instance, sub, instanceLoc, '#', rootSchema).size === 0) {
                validCount++;
            }
        }
        if (validCount !== 1) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/oneOf`]));
        }
    }

    if ('not' in schema) {
        const notErrors = validate(instance, schema.not, instanceLoc, '#', rootSchema);
        if (notErrors.size === 0) {
            errors.add(JSON.stringify([instanceLoc, `${schemaLoc}/not`]));
        }
    }

    if ('if' in schema) {
        const ifErrors = validate(instance, schema.if, instanceLoc, '#', rootSchema);
        if (ifErrors.size === 0) {
            if ('then' in schema) {
                const thenErrors = validate(instance, schema.then, instanceLoc, `${schemaLoc}/then`, rootSchema);
                for (const e of thenErrors) errors.add(e);
            }
        } else {
            if ('else' in schema) {
                const elseErrors = validate(instance, schema.else, instanceLoc, `${schemaLoc}/else`, rootSchema);
                for (const e of elseErrors) errors.add(e);
            }
        }
    }

    if ('$ref' in schema) {
        const { schema: refSchema, location: refLoc } = resolveRef(schema.$ref, rootSchema);
        const refErrors = validate(instance, refSchema, instanceLoc, refLoc, rootSchema);
        for (const e of refErrors) errors.add(e);
    }

    return errors;
}

function main() {
    const dir = process.argv[2];
    const schemaText = fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8');
    const instancesText = fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8');

    const schema = JSON.parse(schemaText);
    const instances = JSON.parse(instancesText);

    let validCount = 0;
    let invalidCount = 0;

    for (let i = 0; i < instances.length; i++) {
        const errors = validate(instances[i], schema, '#', '#', schema);
        if (errors.size === 0) {
            console.log(`${i}: valid`);
            validCount++;
        } else {
            const errorList = [...errors].map(e => JSON.parse(e) as [string, string]);
            errorList.sort((a, b) => {
                const cmp = compareByCodePoint(a[0], b[0]);
                if (cmp !== 0) return cmp;
                return compareByCodePoint(a[1], b[1]);
            });
            console.log(`${i}: invalid (${errorList.length})`);
            for (const [inst, sch] of errorList) {
                console.log(`  ${inst} ${sch}`);
            }
            invalidCount++;
        }
    }

    console.log(`valid=${validCount} invalid=${invalidCount}`);
}

main();

use std::collections::HashSet;
use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> u8 {
        self.input[self.pos]
    }

    fn eat(&mut self, c: u8) {
        assert_eq!(self.input[self.pos], c);
        self.pos += 1;
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        match self.peek() {
            b'n' => { self.eat(b'n'); self.eat(b'u'); self.eat(b'l'); self.eat(b'l'); Value::Null }
            b't' => { self.eat(b't'); self.eat(b'r'); self.eat(b'u'); self.eat(b'e'); Value::Bool(true) }
            b'f' => { self.eat(b'f'); self.eat(b'a'); self.eat(b'l'); self.eat(b's'); self.eat(b'e'); Value::Bool(false) }
            b'"' => Value::Str(self.parse_string()),
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.eat(b'"');
        let mut result = String::new();
        let mut byte_start = self.pos;
        loop {
            let c = self.input[self.pos];
            if c == b'"' {
                result.push_str(std::str::from_utf8(&self.input[byte_start..self.pos]).unwrap());
                self.pos += 1;
                break;
            } else if c == b'\\' {
                result.push_str(std::str::from_utf8(&self.input[byte_start..self.pos]).unwrap());
                self.pos += 1;
                let esc = self.input[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4();
                        if (0xD800..=0xDBFF).contains(&cp) {
                            self.eat(b'\\');
                            self.eat(b'u');
                            let low = self.parse_hex4();
                            let full = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                            result.push(char::from_u32(full).unwrap());
                        } else {
                            result.push(char::from_u32(cp).unwrap());
                        }
                    }
                    _ => unreachable!(),
                }
                byte_start = self.pos;
            } else {
                self.pos += 1;
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.input[self.pos];
            self.pos += 1;
            val = val * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => unreachable!(),
            };
        }
        val
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.input[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        Value::Num(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Value {
        self.eat(b'[');
        self.skip_ws();
        let mut items = Vec::new();
        if self.peek() != b']' {
            loop {
                items.push(self.parse_value());
                self.skip_ws();
                if self.peek() == b',' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        self.eat(b']');
        Value::Arr(items)
    }

    fn parse_object(&mut self) -> Value {
        self.eat(b'{');
        self.skip_ws();
        let mut members = Vec::new();
        if self.peek() != b'}' {
            loop {
                self.skip_ws();
                let key = self.parse_string();
                self.skip_ws();
                self.eat(b':');
                let val = self.parse_value();
                members.push((key, val));
                self.skip_ws();
                if self.peek() == b',' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        self.eat(b'}');
        Value::Obj(members)
    }
}

fn get_member<'a>(obj: &'a Value, name: &str) -> Option<&'a Value> {
    if let Value::Obj(members) = obj {
        members.iter().find(|(k, _)| k == name).map(|(_, v)| v)
    } else {
        None
    }
}

fn get_array<'a>(obj: &'a Value, name: &str) -> Option<&'a Vec<Value>> {
    get_member(obj, name).and_then(|v| if let Value::Arr(a) = v { Some(a) } else { None })
}

fn get_number(obj: &Value, name: &str) -> Option<f64> {
    get_member(obj, name).and_then(|v| if let Value::Num(n) = v { Some(*n) } else { None })
}

fn get_string<'a>(obj: &'a Value, name: &str) -> Option<&'a String> {
    get_member(obj, name).and_then(|v| if let Value::Str(s) = v { Some(s) } else { None })
}

fn get_bool(obj: &Value, name: &str) -> Option<bool> {
    get_member(obj, name).and_then(|v| if let Value::Bool(b) = v { Some(*b) } else { None })
}

fn escape_token(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn child_loc(parent: &str, token: &str) -> String {
    format!("{}/{}", parent, escape_token(token))
}

fn deep_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Arr(x), Value::Arr(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| deep_equal(a, b))
        }
        (Value::Obj(x), Value::Obj(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| {
                y.iter().any(|(k2, v2)| k == k2 && deep_equal(v, v2))
            })
        }
        _ => false,
    }
}

fn is_integer(n: f64) -> bool {
    n.fract() == 0.0
}

fn check_type(instance: &Value, type_name: &str) -> bool {
    match type_name {
        "null" => matches!(instance, Value::Null),
        "boolean" => matches!(instance, Value::Bool(_)),
        "object" => matches!(instance, Value::Obj(_)),
        "array" => matches!(instance, Value::Arr(_)),
        "number" => matches!(instance, Value::Num(_)),
        "string" => matches!(instance, Value::Str(_)),
        "integer" => matches!(instance, Value::Num(n) if is_integer(*n)),
        _ => false,
    }
}

fn resolve_ref<'a>(ref_str: &str, root: &'a Value) -> (&'a Value, String) {
    if ref_str == "#" {
        (root, "#".to_string())
    } else if ref_str.starts_with("#/$defs/") {
        let name_token = &ref_str["#/$defs/".len()..];
        let name = name_token.replace("~1", "/").replace("~0", "~");
        let defs = get_member(root, "$defs").unwrap();
        let schema = get_member(defs, &name).unwrap();
        (schema, ref_str.to_string())
    } else {
        unreachable!("Unexpected $ref: {}", ref_str)
    }
}

fn has_duplicates(arr: &[Value]) -> bool {
    for i in 0..arr.len() {
        for j in i + 1..arr.len() {
            if deep_equal(&arr[i], &arr[j]) {
                return true;
            }
        }
    }
    false
}

fn validate(
    schema: &Value,
    schema_loc: &str,
    instance: &Value,
    instance_loc: &str,
    root: &Value,
    errors: &mut HashSet<(String, String)>,
) {
    match schema {
        Value::Bool(true) => {}
        Value::Bool(false) => {
            errors.insert((instance_loc.to_string(), schema_loc.to_string()));
        }
        Value::Obj(_) => {
            validate_schema_obj(schema, schema_loc, instance, instance_loc, root, errors);
        }
        _ => unreachable!(),
    }
}

fn validate_schema_obj(
    schema: &Value,
    schema_loc: &str,
    instance: &Value,
    instance_loc: &str,
    root: &Value,
    errors: &mut HashSet<(String, String)>,
) {
    // type
    if let Some(type_val) = get_member(schema, "type") {
        let valid = match type_val {
            Value::Str(s) => check_type(instance, s),
            Value::Arr(arr) => arr.iter().any(|v| {
                if let Value::Str(s) = v { check_type(instance, s) } else { false }
            }),
            _ => true,
        };
        if !valid {
            errors.insert((instance_loc.to_string(), format!("{}/type", schema_loc)));
        }
    }

    // enum
    if let Some(enum_val) = get_member(schema, "enum") {
        if let Value::Arr(arr) = enum_val {
            if !arr.iter().any(|e| deep_equal(e, instance)) {
                errors.insert((instance_loc.to_string(), format!("{}/enum", schema_loc)));
            }
        }
    }

    // const
    if let Some(const_val) = get_member(schema, "const") {
        if !deep_equal(const_val, instance) {
            errors.insert((instance_loc.to_string(), format!("{}/const", schema_loc)));
        }
    }

    // Number keywords
    if let Value::Num(n) = instance {
        if let Some(min) = get_number(schema, "minimum") {
            if *n < min {
                errors.insert((instance_loc.to_string(), format!("{}/minimum", schema_loc)));
            }
        }
        if let Some(max) = get_number(schema, "maximum") {
            if *n > max {
                errors.insert((instance_loc.to_string(), format!("{}/maximum", schema_loc)));
            }
        }
        if let Some(exmin) = get_number(schema, "exclusiveMinimum") {
            if *n <= exmin {
                errors.insert((instance_loc.to_string(), format!("{}/exclusiveMinimum", schema_loc)));
            }
        }
        if let Some(exmax) = get_number(schema, "exclusiveMaximum") {
            if *n >= exmax {
                errors.insert((instance_loc.to_string(), format!("{}/exclusiveMaximum", schema_loc)));
            }
        }
    }

    // String keywords
    if let Value::Str(s) = instance {
        let len = s.chars().count();
        if let Some(min_len) = get_number(schema, "minLength") {
            if (len as f64) < min_len {
                errors.insert((instance_loc.to_string(), format!("{}/minLength", schema_loc)));
            }
        }
        if let Some(max_len) = get_number(schema, "maxLength") {
            if (len as f64) > max_len {
                errors.insert((instance_loc.to_string(), format!("{}/maxLength", schema_loc)));
            }
        }
    }

    // Array keywords
    if let Value::Arr(arr) = instance {
        if let Some(min_items) = get_number(schema, "minItems") {
            if (arr.len() as f64) < min_items {
                errors.insert((instance_loc.to_string(), format!("{}/minItems", schema_loc)));
            }
        }
        if let Some(max_items) = get_number(schema, "maxItems") {
            if (arr.len() as f64) > max_items {
                errors.insert((instance_loc.to_string(), format!("{}/maxItems", schema_loc)));
            }
        }
        if get_bool(schema, "uniqueItems") == Some(true) {
            if has_duplicates(arr) {
                errors.insert((instance_loc.to_string(), format!("{}/uniqueItems", schema_loc)));
            }
        }

        // prefixItems
        let prefix_len = if let Some(pi) = get_array(schema, "prefixItems") {
            for (i, sub_schema) in pi.iter().enumerate() {
                if i < arr.len() {
                    let child_inst_loc = child_loc(instance_loc, &i.to_string());
                    let child_schema_loc = format!("{}/prefixItems/{}", schema_loc, i);
                    validate(sub_schema, &child_schema_loc, &arr[i], &child_inst_loc, root, errors);
                }
            }
            pi.len()
        } else {
            0
        };

        // items
        if let Some(items_schema) = get_member(schema, "items") {
            for i in prefix_len..arr.len() {
                let child_inst_loc = child_loc(instance_loc, &i.to_string());
                let child_schema_loc = format!("{}/items", schema_loc);
                validate(items_schema, &child_schema_loc, &arr[i], &child_inst_loc, root, errors);
            }
        }
    }

    // Object keywords
    if let Value::Obj(members) = instance {
        if let Some(min_props) = get_number(schema, "minProperties") {
            if (members.len() as f64) < min_props {
                errors.insert((instance_loc.to_string(), format!("{}/minProperties", schema_loc)));
            }
        }
        if let Some(max_props) = get_number(schema, "maxProperties") {
            if (members.len() as f64) > max_props {
                errors.insert((instance_loc.to_string(), format!("{}/maxProperties", schema_loc)));
            }
        }

        // required
        if let Some(req) = get_array(schema, "required") {
            for (j, req_val) in req.iter().enumerate() {
                if let Value::Str(name) = req_val {
                    if get_member(instance, name).is_none() {
                        errors.insert((
                            instance_loc.to_string(),
                            format!("{}/required/{}", schema_loc, j),
                        ));
                    }
                }
            }
        }

        // properties and additionalProperties
        let props = get_member(schema, "properties");
        let addl = get_member(schema, "additionalProperties");

        for (name, val) in members {
            let child_inst_loc = child_loc(instance_loc, name);
            let in_props = if let Some(Value::Obj(props_members)) = props {
                if let Some((_, prop_schema)) = props_members.iter().find(|(k, _)| k == name) {
                    let child_schema_loc = format!("{}/properties/{}", schema_loc, escape_token(name));
                    validate(prop_schema, &child_schema_loc, val, &child_inst_loc, root, errors);
                    true
                } else {
                    false
                }
            } else {
                false
            };
            if !in_props {
                if let Some(addl_schema) = addl {
                    let child_schema_loc = format!("{}/additionalProperties", schema_loc);
                    validate(addl_schema, &child_schema_loc, val, &child_inst_loc, root, errors);
                }
            }
        }
    }

    // allOf
    if let Some(all_of) = get_array(schema, "allOf") {
        for (i, sub) in all_of.iter().enumerate() {
            let child_schema_loc = format!("{}/allOf/{}", schema_loc, i);
            validate(sub, &child_schema_loc, instance, instance_loc, root, errors);
        }
    }

    // anyOf
    if let Some(any_of) = get_array(schema, "anyOf") {
        let any_valid = any_of.iter().enumerate().any(|(i, sub)| {
            let child_schema_loc = format!("{}/anyOf/{}", schema_loc, i);
            let mut temp_errors = HashSet::new();
            validate(sub, &child_schema_loc, instance, instance_loc, root, &mut temp_errors);
            temp_errors.is_empty()
        });
        if !any_valid {
            errors.insert((instance_loc.to_string(), format!("{}/anyOf", schema_loc)));
        }
    }

    // oneOf
    if let Some(one_of) = get_array(schema, "oneOf") {
        let valid_count = one_of.iter().enumerate().filter(|(i, sub)| {
            let child_schema_loc = format!("{}/oneOf/{}", schema_loc, i);
            let mut temp_errors = HashSet::new();
            validate(sub, &child_schema_loc, instance, instance_loc, root, &mut temp_errors);
            temp_errors.is_empty()
        }).count();
        if valid_count != 1 {
            errors.insert((instance_loc.to_string(), format!("{}/oneOf", schema_loc)));
        }
    }

    // not
    if let Some(not_schema) = get_member(schema, "not") {
        let child_schema_loc = format!("{}/not", schema_loc);
        let mut temp_errors = HashSet::new();
        validate(not_schema, &child_schema_loc, instance, instance_loc, root, &mut temp_errors);
        if temp_errors.is_empty() {
            errors.insert((instance_loc.to_string(), format!("{}/not", schema_loc)));
        }
    }

    // if/then/else
    if let Some(if_schema) = get_member(schema, "if") {
        let child_schema_loc = format!("{}/if", schema_loc);
        let mut temp_errors = HashSet::new();
        validate(if_schema, &child_schema_loc, instance, instance_loc, root, &mut temp_errors);
        let if_valid = temp_errors.is_empty();

        if if_valid {
            if let Some(then_schema) = get_member(schema, "then") {
                let child_schema_loc = format!("{}/then", schema_loc);
                validate(then_schema, &child_schema_loc, instance, instance_loc, root, errors);
            }
        } else {
            if let Some(else_schema) = get_member(schema, "else") {
                let child_schema_loc = format!("{}/else", schema_loc);
                validate(else_schema, &child_schema_loc, instance, instance_loc, root, errors);
            }
        }
    }

    // $ref
    if let Some(ref_val) = get_string(schema, "$ref") {
        let (ref_schema, ref_loc) = resolve_ref(ref_val, root);
        validate(ref_schema, &ref_loc, instance, instance_loc, root, errors);
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let mut parser = Parser::new(&schema_str);
    let root_schema = parser.parse_value();

    let mut parser = Parser::new(&instances_str);
    let instances = parser.parse_value();

    let instances_arr = if let Value::Arr(arr) = &instances { arr } else { unreachable!() };

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for (n, instance) in instances_arr.iter().enumerate() {
        let mut errors: HashSet<(String, String)> = HashSet::new();
        validate(&root_schema, "#", instance, "#", &root_schema, &mut errors);

        if errors.is_empty() {
            println!("{}: valid", n);
            valid_count += 1;
        } else {
            let k = errors.len();
            println!("{}: invalid ({})", n, k);
            let mut sorted: Vec<(String, String)> = errors.into_iter().collect();
            sorted.sort();
            for (inst_loc, schema_loc) in sorted {
                println!("  {} {}", inst_loc, schema_loc);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <ctype.h>

/* ===== JSON Value ===== */
typedef enum { JT_NULL, JT_BOOL, JT_NUM, JT_STR, JT_ARR, JT_OBJ } JType;

typedef struct JVal {
    JType type;
    union {
        bool b;
        double n;
        char *s;
        struct { struct JVal **items; size_t len; } arr;
        struct { char **keys; struct JVal **vals; size_t len; } obj;
    };
} JVal;

/* ===== Parser ===== */
typedef struct { const char *s; size_t pos, len; } P;

static void skip_ws(P *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static JVal *parse_value(P *p);

static JVal *new_val(JType t) {
    JVal *v = calloc(1, sizeof(JVal));
    v->type = t;
    return v;
}

static void utf8_encode(char *buf, unsigned int cp) {
    if (cp < 0x80) { buf[0] = (char)cp; }
    else if (cp < 0x800) {
        buf[0] = (char)(0xC0 | (cp >> 6));
        buf[1] = (char)(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        buf[0] = (char)(0xE0 | (cp >> 12));
        buf[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[2] = (char)(0x80 | (cp & 0x3F));
    } else {
        buf[0] = (char)(0xF0 | (cp >> 18));
        buf[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        buf[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[3] = (char)(0x80 | (cp & 0x3F));
    }
}

static int utf8_len(unsigned int cp) {
    if (cp < 0x80) return 1;
    if (cp < 0x800) return 2;
    if (cp < 0x10000) return 3;
    return 4;
}

static unsigned int parse_hex4(P *p) {
    unsigned int v = 0;
    for (int i = 0; i < 4; i++) {
        char c = p->s[p->pos++];
        if (c >= '0' && c <= '9') v = v * 16 + (c - '0');
        else if (c >= 'a' && c <= 'f') v = v * 16 + (c - 'a' + 10);
        else if (c >= 'A' && c <= 'F') v = v * 16 + (c - 'A' + 10);
    }
    return v;
}

static char *parse_string_raw(P *p) {
    /* p->s[p->pos] == '"' */
    p->pos++; /* skip opening quote */
    size_t cap = 64, len = 0;
    char *buf = malloc(cap);
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == '"') { p->pos++; break; }
        if (c == '\\') {
            p->pos++;
            char e = p->s[p->pos++];
            if (e == '"') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='"'; }
            else if (e == '\\') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\\'; }
            else if (e == '/') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='/'; }
            else if (e == 'b') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\b'; }
            else if (e == 'f') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\f'; }
            else if (e == 'n') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\n'; }
            else if (e == 'r') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\r'; }
            else if (e == 't') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\t'; }
            else if (e == 'u') {
                unsigned int cp = parse_hex4(p);
                if (cp >= 0xD800 && cp <= 0xDBFF) {
                    /* high surrogate, expect low surrogate */
                    if (p->pos + 1 < p->len && p->s[p->pos] == '\\' && p->s[p->pos+1] == 'u') {
                        p->pos += 2;
                        unsigned int lo = parse_hex4(p);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                }
                int ulen = utf8_len(cp);
                if (len + ulen >= cap) { while (len+ulen>=cap) cap*=2; buf=realloc(buf,cap); }
                utf8_encode(buf + len, cp);
                len += ulen;
            }
        } else {
            if (len+1>=cap){cap*=2;buf=realloc(buf,cap);}
            buf[len++] = c;
            p->pos++;
        }
    }
    if (len >= cap) { cap = len+1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static JVal *parse_value(P *p) {
    skip_ws(p);
    char c = p->s[p->pos];
    if (c == '"') {
        JVal *v = new_val(JT_STR);
        v->s = parse_string_raw(p);
        return v;
    }
    if (c == '{') {
        p->pos++;
        size_t cap = 8, len = 0;
        char **keys = malloc(cap * sizeof(char*));
        JVal **vals = malloc(cap * sizeof(JVal*));
        skip_ws(p);
        if (p->s[p->pos] == '}') { p->pos++; }
        else {
            for (;;) {
                skip_ws(p);
                char *key = parse_string_raw(p);
                skip_ws(p);
                p->pos++; /* ':' */
                JVal *val = parse_value(p);
                if (len >= cap) { cap *= 2; keys = realloc(keys, cap*sizeof(char*)); vals = realloc(vals, cap*sizeof(JVal*)); }
                keys[len] = key;
                vals[len] = val;
                len++;
                skip_ws(p);
                if (p->s[p->pos] == ',') { p->pos++; }
                else break;
            }
            skip_ws(p);
            p->pos++; /* '}' */
        }
        JVal *v = new_val(JT_OBJ);
        v->obj.keys = keys; v->obj.vals = vals; v->obj.len = len;
        return v;
    }
    if (c == '[') {
        p->pos++;
        size_t cap = 8, len = 0;
        JVal **items = malloc(cap * sizeof(JVal*));
        skip_ws(p);
        if (p->s[p->pos] == ']') { p->pos++; }
        else {
            for (;;) {
                JVal *val = parse_value(p);
                if (len >= cap) { cap *= 2; items = realloc(items, cap*sizeof(JVal*)); }
                items[len++] = val;
                skip_ws(p);
                if (p->s[p->pos] == ',') { p->pos++; }
                else break;
            }
            skip_ws(p);
            p->pos++; /* ']' */
        }
        JVal *v = new_val(JT_ARR);
        v->arr.items = items; v->arr.len = len;
        return v;
    }
    if (c == 't') { p->pos += 4; JVal *v = new_val(JT_BOOL); v->b = true; return v; }
    if (c == 'f') { p->pos += 5; JVal *v = new_val(JT_BOOL); v->b = false; return v; }
    if (c == 'n') { p->pos += 4; return new_val(JT_NULL); }
    /* number */
    size_t start = p->pos;
    while (p->pos < p->len && (p->s[p->pos]=='-'||p->s[p->pos]=='+'||p->s[p->pos]=='e'||p->s[p->pos]=='E'||
           (p->s[p->pos]>='0'&&p->s[p->pos]<='9')||p->s[p->pos]=='.')) p->pos++;
    char tmp[64];
    size_t nlen = p->pos - start;
    if (nlen >= sizeof(tmp)) nlen = sizeof(tmp)-1;
    memcpy(tmp, p->s + start, nlen);
    tmp[nlen] = '\0';
    JVal *v = new_val(JT_NUM);
    v->n = strtod(tmp, NULL);
    return v;
}

static JVal *parse_json(const char *src, size_t len) {
    P p = {src, 0, len};
    return parse_value(&p);
}

/* ===== Object lookup ===== */
static JVal *obj_get(JVal *obj, const char *key) {
    if (!obj || obj->type != JT_OBJ) return NULL;
    for (size_t i = 0; i < obj->obj.len; i++)
        if (strcmp(obj->obj.keys[i], key) == 0) return obj->obj.vals[i];
    return NULL;
}

static bool obj_has(JVal *obj, const char *key) {
    return obj_get(obj, key) != NULL;
}

/* ===== Deep equality ===== */
static bool deep_eq(JVal *a, JVal *b) {
    if (a->type != b->type) return false;
    switch (a->type) {
        case JT_NULL: return true;
        case JT_BOOL: return a->b == b->b;
        case JT_NUM: return a->n == b->n || (a->n == 0 && b->n == 0);
        case JT_STR: return strcmp(a->s, b->s) == 0;
        case JT_ARR:
            if (a->arr.len != b->arr.len) return false;
            for (size_t i = 0; i < a->arr.len; i++)
                if (!deep_eq(a->arr.items[i], b->arr.items[i])) return false;
            return true;
        case JT_OBJ:
            if (a->obj.len != b->obj.len) return false;
            for (size_t i = 0; i < a->obj.len; i++) {
                JVal *bv = obj_get(b, a->obj.keys[i]);
                if (!bv || !deep_eq(a->obj.vals[i], bv)) return false;
            }
            return true;
    }
    return false;
}

/* ===== Error list ===== */
typedef struct { char *inst_loc; char *schema_loc; } Err;
typedef struct { Err *items; size_t len, cap; } ErrList;

static void errlist_init(ErrList *e) { e->items = NULL; e->len = 0; e->cap = 0; }
static void errlist_add(ErrList *e, const char *il, const char *sl) {
    if (e->len >= e->cap) { e->cap = e->cap ? e->cap*2 : 16; e->items = realloc(e->items, e->cap*sizeof(Err)); }
    e->items[e->len].inst_loc = strdup(il);
    e->items[e->len].schema_loc = strdup(sl);
    e->len++;
}

/* ===== JSON Pointer helpers ===== */
static char *ptr_append(const char *base, const char *token) {
    /* escape ~ -> ~0, / -> ~1 */
    size_t tlen = strlen(token);
    size_t blen = strlen(base);
    size_t cap = blen + tlen*2 + 2;
    char *r = malloc(cap);
    size_t pos = 0;
    memcpy(r+pos, base, blen); pos += blen;
    r[pos++] = '/';
    for (size_t i = 0; i < tlen; i++) {
        if (token[i] == '~') { r[pos++]='~'; r[pos++]='0'; }
        else if (token[i] == '/') { r[pos++]='~'; r[pos++]='1'; }
        else r[pos++] = token[i];
    }
    r[pos] = '\0';
    return r;
}

static char *ptr_append_idx(const char *base, size_t idx) {
    char num[24];
    snprintf(num, sizeof(num), "%zu", idx);
    size_t blen = strlen(base);
    size_t nlen = strlen(num);
    char *r = malloc(blen + nlen + 2);
    memcpy(r, base, blen);
    r[blen] = '/';
    memcpy(r+blen+1, num, nlen+1);
    return r;
}

/* ===== Type checking ===== */
static bool matches_type(JVal *inst, const char *tn) {
    if (strcmp(tn, "null") == 0) return inst->type == JT_NULL;
    if (strcmp(tn, "boolean") == 0) return inst->type == JT_BOOL;
    if (strcmp(tn, "object") == 0) return inst->type == JT_OBJ;
    if (strcmp(tn, "array") == 0) return inst->type == JT_ARR;
    if (strcmp(tn, "number") == 0) return inst->type == JT_NUM;
    if (strcmp(tn, "string") == 0) return inst->type == JT_STR;
    if (strcmp(tn, "integer") == 0) return inst->type == JT_NUM && inst->n == floor(inst->n);
    return false;
}

static bool type_check(JVal *inst, JVal *type_val) {
    if (type_val->type == JT_STR)
        return matches_type(inst, type_val->s);
    if (type_val->type == JT_ARR) {
        for (size_t i = 0; i < type_val->arr.len; i++)
            if (type_val->arr.items[i]->type == JT_STR && matches_type(inst, type_val->arr.items[i]->s))
                return true;
    }
    return false;
}

/* ===== String length in code points ===== */
static size_t str_cp_len(const char *s) {
    size_t count = 0;
    while (*s) {
        unsigned char c = (unsigned char)*s;
        if (c < 0x80) s += 1;
        else if (c < 0xE0) s += 2;
        else if (c < 0xF0) s += 3;
        else s += 4;
        count++;
    }
    return count;
}

/* ===== $ref resolution ===== */
static JVal *resolve_ref(const char *ref, JVal *root, JVal *defs, const char **out_loc) {
    if (strcmp(ref, "#") == 0) {
        *out_loc = "#";
        return root;
    }
    /* must be #/$defs/<name> */
    const char *prefix = "#/$defs/";
    size_t plen = strlen(prefix);
    if (strncmp(ref, prefix, plen) != 0) return NULL;
    const char *token = ref + plen;
    /* decode pointer token: ~1 -> /, ~0 -> ~ */
    size_t tlen = strlen(token);
    char *decoded = malloc(tlen + 1);
    size_t dp = 0;
    for (size_t i = 0; i < tlen; i++) {
        if (token[i] == '~' && i+1 < tlen) {
            if (token[i+1] == '0') { decoded[dp++] = '~'; i++; }
            else if (token[i+1] == '1') { decoded[dp++] = '/'; i++; }
            else decoded[dp++] = token[i];
        } else decoded[dp++] = token[i];
    }
    decoded[dp] = '\0';
    JVal *result = obj_get(defs, decoded);
    free(decoded);
    /* schema location is the ref string itself */
    *out_loc = strdup(ref);
    return result;
}

/* ===== Validation ===== */
static void validate(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                     JVal *root, JVal *defs, ErrList *errs);

static bool schema_accepts(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                           JVal *root, JVal *defs) {
    ErrList tmp = {NULL, 0, 0};
    validate(schema, inst, inst_loc, schema_loc, root, defs, &tmp);
    bool ok = (tmp.len == 0);
    for (size_t i = 0; i < tmp.len; i++) { free(tmp.items[i].inst_loc); free(tmp.items[i].schema_loc); }
    free(tmp.items);
    return ok;
}

static void validate(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                     JVal *root, JVal *defs, ErrList *errs) {
    if (schema->type == JT_BOOL) {
        if (!schema->b) errlist_add(errs, inst_loc, schema_loc);
        return;
    }
    if (schema->type != JT_OBJ) return;

    JVal *kw;

    /* type */
    kw = obj_get(schema, "type");
    if (kw && !type_check(inst, kw)) {
        char *sl = ptr_append(schema_loc, "type");
        errlist_add(errs, inst_loc, sl);
        free(sl);
    }

    /* enum */
    kw = obj_get(schema, "enum");
    if (kw && kw->type == JT_ARR) {
        bool found = false;
        for (size_t i = 0; i < kw->arr.len; i++)
            if (deep_eq(inst, kw->arr.items[i])) { found = true; break; }
        if (!found) {
            char *sl = ptr_append(schema_loc, "enum");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* const */
    kw = obj_get(schema, "const");
    if (kw) {
        if (!deep_eq(inst, kw)) {
            char *sl = ptr_append(schema_loc, "const");
            errlist_add(errs, inst_loc, sl);
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* Numbers */
    if (inst->type == JT_NUM) {
        kw = obj_get(schema, "minimum");
        if (kw && kw->type == JT_NUM && inst->n < kw->n) {
            char *sl = ptr_append(schema_loc, "minimum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maximum");
        if (kw && kw->type == JT_NUM && inst->n > kw->n) {
            char *sl = ptr_append(schema_loc, "maximum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "exclusiveMinimum");
        if (kw && kw->type == JT_NUM && inst->n <= kw->n) {
            char *sl = ptr_append(schema_loc, "exclusiveMinimum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "exclusiveMaximum");
        if (kw && kw->type == JT_NUM && inst->n >= kw->n) {
            char *sl = ptr_append(schema_loc, "exclusiveMaximum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
    }

    /* Strings */
    if (inst->type == JT_STR) {
        size_t slen = str_cp_len(inst->s);
        kw = obj_get(schema, "minLength");
        if (kw && kw->type == JT_NUM && (double)slen < kw->n) {
            char *sl = ptr_append(schema_loc, "minLength");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxLength");
        if (kw && kw->type == JT_NUM && (double)slen > kw->n) {
            char *sl = ptr_append(schema_loc, "maxLength");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
    }

    /* Arrays */
    if (inst->type == JT_ARR) {
        kw = obj_get(schema, "minItems");
        if (kw && kw->type == JT_NUM && (double)inst->arr.len < kw->n) {
            char *sl = ptr_append(schema_loc, "minItems");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxItems");
        if (kw && kw->type == JT_NUM && (double)inst->arr.len > kw->n) {
            char *sl = ptr_append(schema_loc, "maxItems");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "uniqueItems");
        if (kw && kw->type == JT_BOOL && kw->b) {
            bool dup = false;
            for (size_t i = 0; i < inst->arr.len && !dup; i++)
                for (size_t j = i+1; j < inst->arr.len && !dup; j++)
                    if (deep_eq(inst->arr.items[i], inst->arr.items[j])) dup = true;
            if (dup) {
                char *sl = ptr_append(schema_loc, "uniqueItems");
                errlist_add(errs, inst_loc, sl); free(sl);
            }
        }
        /* prefixItems */
        size_t prefix_len = 0;
        kw = obj_get(schema, "prefixItems");
        if (kw && kw->type == JT_ARR) {
            prefix_len = kw->arr.len;
            for (size_t i = 0; i < prefix_len && i < inst->arr.len; i++) {
                char *il = ptr_append_idx(inst_loc, i);
                char *sl = ptr_append_idx(schema_loc, i);
                char *sl2 = ptr_append(sl, "prefixItems");
                free(sl);
                sl = ptr_append_idx(sl2, i);
                free(sl2);
                validate(kw->arr.items[i], inst->arr.items[i], il, sl, root, defs, errs);
                free(il); free(sl);
            }
        }
        /* items */
        kw = obj_get(schema, "items");
        if (kw) {
            for (size_t i = prefix_len; i < inst->arr.len; i++) {
                char *il = ptr_append_idx(inst_loc, i);
                char *sl = ptr_append(schema_loc, "items");
                validate(kw, inst->arr.items[i], il, sl, root, defs, errs);
                free(il); free(sl);
            }
        }
    }

    /* Objects */
    if (inst->type == JT_OBJ) {
        kw = obj_get(schema, "minProperties");
        if (kw && kw->type == JT_NUM && (double)inst->obj.len < kw->n) {
            char *sl = ptr_append(schema_loc, "minProperties");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxProperties");
        if (kw && kw->type == JT_NUM && (double)inst->obj.len > kw->n) {
            char *sl = ptr_append(schema_loc, "maxProperties");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        /* required */
        kw = obj_get(schema, "required");
        if (kw && kw->type == JT_ARR) {
            for (size_t j = 0; j < kw->arr.len; j++) {
                if (kw->arr.items[j]->type == JT_STR && !obj_has(inst, kw->arr.items[j]->s)) {
                    char *sl = ptr_append(schema_loc, "required");
                    char *sl2 = ptr_append_idx(sl, j);
                    free(sl);
                    errlist_add(errs, inst_loc, sl2);
                    free(sl2);
                }
            }
        }
        /* properties */
        JVal *props = obj_get(schema, "properties");
        if (props && props->type == JT_OBJ) {
            for (size_t i = 0; i < inst->obj.len; i++) {
                JVal *sub = obj_get(props, inst->obj.keys[i]);
                if (sub) {
                    char *il = ptr_append(inst_loc, inst->obj.keys[i]);
                    char *sl = ptr_append(schema_loc, "properties");
                    char *sl2 = ptr_append(sl, inst->obj.keys[i]);
                    free(sl);
                    validate(sub, inst->obj.vals[i], il, sl2, root, defs, errs);
                    free(il); free(sl2);
                }
            }
        }
        /* additionalProperties */
        kw = obj_get(schema, "additionalProperties");
        if (kw) {
            for (size_t i = 0; i < inst->obj.len; i++) {
                bool in_props = false;
                if (props && props->type == JT_OBJ) {
                    for (size_t j = 0; j < props->obj.len; j++) {
                        if (strcmp(props->obj.keys[j], inst->obj.keys[i]) == 0) { in_props = true; break; }
                    }
                }
                if (!in_props) {
                    char *il = ptr_append(inst_loc, inst->obj.keys[i]);
                    char *sl = ptr_append(schema_loc, "additionalProperties");
                    validate(kw, inst->obj.vals[i], il, sl, root, defs, errs);
                    free(il); free(sl);
                }
            }
        }
    }

    /* allOf */
    kw = obj_get(schema, "allOf");
    if (kw && kw->type == JT_ARR) {
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "allOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            validate(kw->arr.items[i], inst, inst_loc, sl2, root, defs, errs);
            free(sl2);
        }
    }

    /* anyOf */
    kw = obj_get(schema, "anyOf");
    if (kw && kw->type == JT_ARR) {
        bool any = false;
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "anyOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            if (schema_accepts(kw->arr.items[i], inst, inst_loc, sl2, root, defs)) { any = true; free(sl2); break; }
            free(sl2);
        }
        if (!any) {
            char *sl = ptr_append(schema_loc, "anyOf");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* oneOf */
    kw = obj_get(schema, "oneOf");
    if (kw && kw->type == JT_ARR) {
        int count = 0;
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "oneOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            if (schema_accepts(kw->arr.items[i], inst, inst_loc, sl2, root, defs)) count++;
            free(sl2);
        }
        if (count != 1) {
            char *sl = ptr_append(schema_loc, "oneOf");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* not */
    kw = obj_get(schema, "not");
    if (kw) {
        char *sl = ptr_append(schema_loc, "not");
        if (schema_accepts(kw, inst, inst_loc, sl, root, defs)) {
            errlist_add(errs, inst_loc, sl);
        }
        free(sl);
    }

    /* if/then/else */
    kw = obj_get(schema, "if");
    if (kw) {
        char *sl_if = ptr_append(schema_loc, "if");
        bool if_ok = schema_accepts(kw, inst, inst_loc, sl_if, root, defs);
        free(sl_if);
        if (if_ok) {
            JVal *then_kw = obj_get(schema, "then");
            if (then_kw) {
                char *sl = ptr_append(schema_loc, "then");
                validate(then_kw, inst, inst_loc, sl, root, defs, errs);
                free(sl);
            }
        } else {
            JVal *else_kw = obj_get(schema, "else");
            if (else_kw) {
                char *sl = ptr_append(schema_loc, "else");
                validate(else_kw, inst, inst_loc, sl, root, defs, errs);
                free(sl);
            }
        }
    }

    /* $ref */
    kw = obj_get(schema, "$ref");
    if (kw && kw->type == JT_STR) {
        const char *ref_loc = NULL;
        JVal *target = resolve_ref(kw->s, root, defs, &ref_loc);
        if (target) {
            validate(target, inst, inst_loc, ref_loc, root, defs, errs);
        }
    }
}

/* ===== Sorting and dedup ===== */
static int cmp_err(const void *a, const void *b) {
    const Err *ea = (const Err*)a, *eb = (const Err*)b;
    int c = strcmp(ea->inst_loc, eb->inst_loc);
    if (c) return c;
    return strcmp(ea->schema_loc, eb->schema_loc);
}

/* ===== Main ===== */
static char *read_file(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    *len = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(*len + 1);
    fread(buf, 1, *len, f);
    buf[*len] = '\0';
    fclose(f);
    return buf;
}

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }
    char path[4096];
    snprintf(path, sizeof(path), "%s/schema.json", argv[1]);
    size_t slen;
    char *src = read_file(path, &slen);
    JVal *root = parse_json(src, slen);

    snprintf(path, sizeof(path), "%s/instances.json", argv[1]);
    size_t ilen;
    char *isrc = read_file(path, &ilen);
    JVal *instances = parse_json(isrc, ilen);

    JVal *defs = obj_get(root, "$defs");
    if (!defs || defs->type != JT_OBJ) {
        defs = new_val(JT_OBJ);
        defs->obj.keys = NULL; defs->obj.vals = NULL; defs->obj.len = 0;
    }

    int valid_count = 0, invalid_count = 0;

    for (size_t i = 0; i < instances->arr.len; i++) {
        ErrList errs = {NULL, 0, 0};
        validate(root, instances->arr.items[i], "#", "#", root, defs, &errs);

        if (errs.len == 0) {
            printf("%zu: valid\n", i);
            valid_count++;
        } else {
            /* sort */
            qsort(errs.items, errs.len, sizeof(Err), cmp_err);
            /* dedup */
            size_t out = 1;
            for (size_t j = 1; j < errs.len; j++) {
                if (strcmp(errs.items[j].inst_loc, errs.items[out-1].inst_loc) != 0 ||
                    strcmp(errs.items[j].schema_loc, errs.items[out-1].schema_loc) != 0) {
                    errs.items[out++] = errs.items[j];
                } else {
                    free(errs.items[j].inst_loc);
                    free(errs.items[j].schema_loc);
                }
            }
            errs.len = out;
            printf("%zu: invalid (%zu)\n", i, errs.len);
            for (size_t j = 0; j < errs.len; j++) {
                printf("  %s %s\n", errs.items[j].inst_loc, errs.items[j].schema_loc);
            }
            invalid_count++;
        }
        for (size_t j = 0; j < errs.len; j++) {
            free(errs.items[j].inst_loc);
            free(errs.items[j].schema_loc);
        }
        free(errs.items);
    }

    printf("valid=%d invalid=%d\n", valid_count, invalid_count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <ctype.h>

/* ===== JSON Value ===== */
typedef enum { JT_NULL, JT_BOOL, JT_NUM, JT_STR, JT_ARR, JT_OBJ } JType;

typedef struct JVal {
    JType type;
    union {
        bool b;
        double n;
        char *s;
        struct { struct JVal **items; size_t len; } arr;
        struct { char **keys; struct JVal **vals; size_t len; } obj;
    };
} JVal;

/* ===== Parser ===== */
typedef struct { const char *s; size_t pos, len; } P;

static void skip_ws(P *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static JVal *parse_value(P *p);

static JVal *new_val(JType t) {
    JVal *v = calloc(1, sizeof(JVal));
    v->type = t;
    return v;
}

static void utf8_encode(char *buf, unsigned int cp) {
    if (cp < 0x80) { buf[0] = (char)cp; }
    else if (cp < 0x800) {
        buf[0] = (char)(0xC0 | (cp >> 6));
        buf[1] = (char)(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        buf[0] = (char)(0xE0 | (cp >> 12));
        buf[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[2] = (char)(0x80 | (cp & 0x3F));
    } else {
        buf[0] = (char)(0xF0 | (cp >> 18));
        buf[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        buf[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[3] = (char)(0x80 | (cp & 0x3F));
    }
}

static int utf8_len(unsigned int cp) {
    if (cp < 0x80) return 1;
    if (cp < 0x800) return 2;
    if (cp < 0x10000) return 3;
    return 4;
}

static unsigned int parse_hex4(P *p) {
    unsigned int v = 0;
    for (int i = 0; i < 4; i++) {
        char c = p->s[p->pos++];
        if (c >= '0' && c <= '9') v = v * 16 + (c - '0');
        else if (c >= 'a' && c <= 'f') v = v * 16 + (c - 'a' + 10);
        else if (c >= 'A' && c <= 'F') v = v * 16 + (c - 'A' + 10);
    }
    return v;
}

static char *parse_string_raw(P *p) {
    p->pos++; /* skip opening quote */
    size_t cap = 64, len = 0;
    char *buf = malloc(cap);
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == '"') { p->pos++; break; }
        if (c == '\\') {
            p->pos++;
            char e = p->s[p->pos++];
            if (e == '"') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='"'; }
            else if (e == '\\') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\\'; }
            else if (e == '/') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='/'; }
            else if (e == 'b') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\b'; }
            else if (e == 'f') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\f'; }
            else if (e == 'n') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\n'; }
            else if (e == 'r') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\r'; }
            else if (e == 't') { if (len+1>=cap){cap*=2;buf=realloc(buf,cap);} buf[len++]='\t'; }
            else if (e == 'u') {
                unsigned int cp = parse_hex4(p);
                if (cp >= 0xD800 && cp <= 0xDBFF) {
                    if (p->pos + 1 < p->len && p->s[p->pos] == '\\' && p->s[p->pos+1] == 'u') {
                        p->pos += 2;
                        unsigned int lo = parse_hex4(p);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                }
                int ulen = utf8_len(cp);
                if (len + ulen >= cap) { while (len+ulen>=cap) cap*=2; buf=realloc(buf,cap); }
                utf8_encode(buf + len, cp);
                len += ulen;
            }
        } else {
            if (len+1>=cap){cap*=2;buf=realloc(buf,cap);}
            buf[len++] = c;
            p->pos++;
        }
    }
    if (len >= cap) { cap = len+1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static JVal *parse_value(P *p) {
    skip_ws(p);
    char c = p->s[p->pos];
    if (c == '"') {
        JVal *v = new_val(JT_STR);
        v->s = parse_string_raw(p);
        return v;
    }
    if (c == '{') {
        p->pos++;
        size_t cap = 8, len = 0;
        char **keys = malloc(cap * sizeof(char*));
        JVal **vals = malloc(cap * sizeof(JVal*));
        skip_ws(p);
        if (p->s[p->pos] == '}') { p->pos++; }
        else {
            for (;;) {
                skip_ws(p);
                char *key = parse_string_raw(p);
                skip_ws(p);
                p->pos++; /* ':' */
                JVal *val = parse_value(p);
                if (len >= cap) { cap *= 2; keys = realloc(keys, cap*sizeof(char*)); vals = realloc(vals, cap*sizeof(JVal*)); }
                keys[len] = key;
                vals[len] = val;
                len++;
                skip_ws(p);
                if (p->s[p->pos] == ',') { p->pos++; }
                else break;
            }
            skip_ws(p);
            p->pos++; /* '}' */
        }
        JVal *v = new_val(JT_OBJ);
        v->obj.keys = keys; v->obj.vals = vals; v->obj.len = len;
        return v;
    }
    if (c == '[') {
        p->pos++;
        size_t cap = 8, len = 0;
        JVal **items = malloc(cap * sizeof(JVal*));
        skip_ws(p);
        if (p->s[p->pos] == ']') { p->pos++; }
        else {
            for (;;) {
                JVal *val = parse_value(p);
                if (len >= cap) { cap *= 2; items = realloc(items, cap*sizeof(JVal*)); }
                items[len++] = val;
                skip_ws(p);
                if (p->s[p->pos] == ',') { p->pos++; }
                else break;
            }
            skip_ws(p);
            p->pos++; /* ']' */
        }
        JVal *v = new_val(JT_ARR);
        v->arr.items = items; v->arr.len = len;
        return v;
    }
    if (c == 't') { p->pos += 4; JVal *v = new_val(JT_BOOL); v->b = true; return v; }
    if (c == 'f') { p->pos += 5; JVal *v = new_val(JT_BOOL); v->b = false; return v; }
    if (c == 'n') { p->pos += 4; return new_val(JT_NULL); }
    /* number */
    size_t start = p->pos;
    while (p->pos < p->len && (p->s[p->pos]=='-'||p->s[p->pos]=='+'||p->s[p->pos]=='e'||p->s[p->pos]=='E'||
           (p->s[p->pos]>='0'&&p->s[p->pos]<='9')||p->s[p->pos]=='.')) p->pos++;
    char tmp[64];
    size_t nlen = p->pos - start;
    if (nlen >= sizeof(tmp)) nlen = sizeof(tmp)-1;
    memcpy(tmp, p->s + start, nlen);
    tmp[nlen] = '\0';
    JVal *v = new_val(JT_NUM);
    v->n = strtod(tmp, NULL);
    return v;
}

static JVal *parse_json(const char *src, size_t len) {
    P p = {src, 0, len};
    return parse_value(&p);
}

/* ===== Object lookup ===== */
static JVal *obj_get(JVal *obj, const char *key) {
    if (!obj || obj->type != JT_OBJ) return NULL;
    for (size_t i = 0; i < obj->obj.len; i++)
        if (strcmp(obj->obj.keys[i], key) == 0) return obj->obj.vals[i];
    return NULL;
}

static bool obj_has(JVal *obj, const char *key) {
    return obj_get(obj, key) != NULL;
}

/* ===== Deep equality ===== */
static bool deep_eq(JVal *a, JVal *b) {
    if (a->type != b->type) return false;
    switch (a->type) {
        case JT_NULL: return true;
        case JT_BOOL: return a->b == b->b;
        case JT_NUM: return a->n == b->n || (a->n == 0 && b->n == 0);
        case JT_STR: return strcmp(a->s, b->s) == 0;
        case JT_ARR:
            if (a->arr.len != b->arr.len) return false;
            for (size_t i = 0; i < a->arr.len; i++)
                if (!deep_eq(a->arr.items[i], b->arr.items[i])) return false;
            return true;
        case JT_OBJ:
            if (a->obj.len != b->obj.len) return false;
            for (size_t i = 0; i < a->obj.len; i++) {
                JVal *bv = obj_get(b, a->obj.keys[i]);
                if (!bv || !deep_eq(a->obj.vals[i], bv)) return false;
            }
            return true;
    }
    return false;
}

/* ===== Error list ===== */
typedef struct { char *inst_loc; char *schema_loc; } Err;
typedef struct { Err *items; size_t len, cap; } ErrList;

static void errlist_init(ErrList *e) { e->items = NULL; e->len = 0; e->cap = 0; }
static void errlist_add(ErrList *e, const char *il, const char *sl) {
    if (e->len >= e->cap) { e->cap = e->cap ? e->cap*2 : 16; e->items = realloc(e->items, e->cap*sizeof(Err)); }
    e->items[e->len].inst_loc = strdup(il);
    e->items[e->len].schema_loc = strdup(sl);
    e->len++;
}

/* ===== JSON Pointer helpers ===== */
static char *ptr_append(const char *base, const char *token) {
    size_t tlen = strlen(token);
    size_t blen = strlen(base);
    size_t cap = blen + tlen*2 + 2;
    char *r = malloc(cap);
    size_t pos = 0;
    memcpy(r+pos, base, blen); pos += blen;
    r[pos++] = '/';
    for (size_t i = 0; i < tlen; i++) {
        if (token[i] == '~') { r[pos++]='~'; r[pos++]='0'; }
        else if (token[i] == '/') { r[pos++]='~'; r[pos++]='1'; }
        else r[pos++] = token[i];
    }
    r[pos] = '\0';
    return r;
}

static char *ptr_append_idx(const char *base, size_t idx) {
    char num[24];
    snprintf(num, sizeof(num), "%zu", idx);
    size_t blen = strlen(base);
    size_t nlen = strlen(num);
    char *r = malloc(blen + nlen + 2);
    memcpy(r, base, blen);
    r[blen] = '/';
    memcpy(r+blen+1, num, nlen+1);
    return r;
}

/* ===== Type checking ===== */
static bool matches_type(JVal *inst, const char *tn) {
    if (strcmp(tn, "null") == 0) return inst->type == JT_NULL;
    if (strcmp(tn, "boolean") == 0) return inst->type == JT_BOOL;
    if (strcmp(tn, "object") == 0) return inst->type == JT_OBJ;
    if (strcmp(tn, "array") == 0) return inst->type == JT_ARR;
    if (strcmp(tn, "number") == 0) return inst->type == JT_NUM;
    if (strcmp(tn, "string") == 0) return inst->type == JT_STR;
    if (strcmp(tn, "integer") == 0) return inst->type == JT_NUM && inst->n == floor(inst->n);
    return false;
}

static bool type_check(JVal *inst, JVal *type_val) {
    if (type_val->type == JT_STR)
        return matches_type(inst, type_val->s);
    if (type_val->type == JT_ARR) {
        for (size_t i = 0; i < type_val->arr.len; i++)
            if (type_val->arr.items[i]->type == JT_STR && matches_type(inst, type_val->arr.items[i]->s))
                return true;
    }
    return false;
}

/* ===== String length in code points ===== */
static size_t str_cp_len(const char *s) {
    size_t count = 0;
    while (*s) {
        unsigned char c = (unsigned char)*s;
        if (c < 0x80) s += 1;
        else if (c < 0xE0) s += 2;
        else if (c < 0xF0) s += 3;
        else s += 4;
        count++;
    }
    return count;
}

/* ===== $ref resolution ===== */
static JVal *resolve_ref(const char *ref, JVal *root, JVal *defs, const char **out_loc) {
    if (strcmp(ref, "#") == 0) {
        *out_loc = "#";
        return root;
    }
    const char *prefix = "#/$defs/";
    size_t plen = strlen(prefix);
    if (strncmp(ref, prefix, plen) != 0) return NULL;
    const char *token = ref + plen;
    size_t tlen = strlen(token);
    char *decoded = malloc(tlen + 1);
    size_t dp = 0;
    for (size_t i = 0; i < tlen; i++) {
        if (token[i] == '~' && i+1 < tlen) {
            if (token[i+1] == '0') { decoded[dp++] = '~'; i++; }
            else if (token[i+1] == '1') { decoded[dp++] = '/'; i++; }
            else decoded[dp++] = token[i];
        } else decoded[dp++] = token[i];
    }
    decoded[dp] = '\0';
    JVal *result = obj_get(defs, decoded);
    free(decoded);
    *out_loc = strdup(ref);
    return result;
}

/* ===== Validation ===== */
static void validate(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                     JVal *root, JVal *defs, ErrList *errs);

static bool schema_accepts(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                           JVal *root, JVal *defs) {
    ErrList tmp = {NULL, 0, 0};
    validate(schema, inst, inst_loc, schema_loc, root, defs, &tmp);
    bool ok = (tmp.len == 0);
    for (size_t i = 0; i < tmp.len; i++) { free(tmp.items[i].inst_loc); free(tmp.items[i].schema_loc); }
    free(tmp.items);
    return ok;
}

static void validate(JVal *schema, JVal *inst, const char *inst_loc, const char *schema_loc,
                     JVal *root, JVal *defs, ErrList *errs) {
    if (schema->type == JT_BOOL) {
        if (!schema->b) errlist_add(errs, inst_loc, schema_loc);
        return;
    }
    if (schema->type != JT_OBJ) return;

    JVal *kw;

    /* type */
    kw = obj_get(schema, "type");
    if (kw && !type_check(inst, kw)) {
        char *sl = ptr_append(schema_loc, "type");
        errlist_add(errs, inst_loc, sl);
        free(sl);
    }

    /* enum */
    kw = obj_get(schema, "enum");
    if (kw && kw->type == JT_ARR) {
        bool found = false;
        for (size_t i = 0; i < kw->arr.len; i++)
            if (deep_eq(inst, kw->arr.items[i])) { found = true; break; }
        if (!found) {
            char *sl = ptr_append(schema_loc, "enum");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* const */
    kw = obj_get(schema, "const");
    if (kw) {
        if (!deep_eq(inst, kw)) {
            char *sl = ptr_append(schema_loc, "const");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* Numbers */
    if (inst->type == JT_NUM) {
        kw = obj_get(schema, "minimum");
        if (kw && kw->type == JT_NUM && inst->n < kw->n) {
            char *sl = ptr_append(schema_loc, "minimum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maximum");
        if (kw && kw->type == JT_NUM && inst->n > kw->n) {
            char *sl = ptr_append(schema_loc, "maximum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "exclusiveMinimum");
        if (kw && kw->type == JT_NUM && inst->n <= kw->n) {
            char *sl = ptr_append(schema_loc, "exclusiveMinimum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "exclusiveMaximum");
        if (kw && kw->type == JT_NUM && inst->n >= kw->n) {
            char *sl = ptr_append(schema_loc, "exclusiveMaximum");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
    }

    /* Strings */
    if (inst->type == JT_STR) {
        size_t slen = str_cp_len(inst->s);
        kw = obj_get(schema, "minLength");
        if (kw && kw->type == JT_NUM && (double)slen < kw->n) {
            char *sl = ptr_append(schema_loc, "minLength");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxLength");
        if (kw && kw->type == JT_NUM && (double)slen > kw->n) {
            char *sl = ptr_append(schema_loc, "maxLength");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
    }

    /* Arrays */
    if (inst->type == JT_ARR) {
        kw = obj_get(schema, "minItems");
        if (kw && kw->type == JT_NUM && (double)inst->arr.len < kw->n) {
            char *sl = ptr_append(schema_loc, "minItems");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxItems");
        if (kw && kw->type == JT_NUM && (double)inst->arr.len > kw->n) {
            char *sl = ptr_append(schema_loc, "maxItems");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "uniqueItems");
        if (kw && kw->type == JT_BOOL && kw->b) {
            bool dup = false;
            for (size_t i = 0; i < inst->arr.len && !dup; i++)
                for (size_t j = i+1; j < inst->arr.len && !dup; j++)
                    if (deep_eq(inst->arr.items[i], inst->arr.items[j])) dup = true;
            if (dup) {
                char *sl = ptr_append(schema_loc, "uniqueItems");
                errlist_add(errs, inst_loc, sl); free(sl);
            }
        }
        /* prefixItems */
        size_t prefix_len = 0;
        kw = obj_get(schema, "prefixItems");
        if (kw && kw->type == JT_ARR) {
            prefix_len = kw->arr.len;
            for (size_t i = 0; i < prefix_len && i < inst->arr.len; i++) {
                char *il = ptr_append_idx(inst_loc, i);
                char *sl = ptr_append(schema_loc, "prefixItems");
                char *sl2 = ptr_append_idx(sl, i);
                free(sl);
                validate(kw->arr.items[i], inst->arr.items[i], il, sl2, root, defs, errs);
                free(il); free(sl2);
            }
        }
        /* items */
        kw = obj_get(schema, "items");
        if (kw) {
            for (size_t i = prefix_len; i < inst->arr.len; i++) {
                char *il = ptr_append_idx(inst_loc, i);
                char *sl = ptr_append(schema_loc, "items");
                validate(kw, inst->arr.items[i], il, sl, root, defs, errs);
                free(il); free(sl);
            }
        }
    }

    /* Objects */
    if (inst->type == JT_OBJ) {
        kw = obj_get(schema, "minProperties");
        if (kw && kw->type == JT_NUM && (double)inst->obj.len < kw->n) {
            char *sl = ptr_append(schema_loc, "minProperties");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        kw = obj_get(schema, "maxProperties");
        if (kw && kw->type == JT_NUM && (double)inst->obj.len > kw->n) {
            char *sl = ptr_append(schema_loc, "maxProperties");
            errlist_add(errs, inst_loc, sl); free(sl);
        }
        /* required */
        kw = obj_get(schema, "required");
        if (kw && kw->type == JT_ARR) {
            for (size_t j = 0; j < kw->arr.len; j++) {
                if (kw->arr.items[j]->type == JT_STR && !obj_has(inst, kw->arr.items[j]->s)) {
                    char *sl = ptr_append(schema_loc, "required");
                    char *sl2 = ptr_append_idx(sl, j);
                    free(sl);
                    errlist_add(errs, inst_loc, sl2);
                    free(sl2);
                }
            }
        }
        /* properties */
        JVal *props = obj_get(schema, "properties");
        if (props && props->type == JT_OBJ) {
            for (size_t i = 0; i < inst->obj.len; i++) {
                JVal *sub = obj_get(props, inst->obj.keys[i]);
                if (sub) {
                    char *il = ptr_append(inst_loc, inst->obj.keys[i]);
                    char *sl = ptr_append(schema_loc, "properties");
                    char *sl2 = ptr_append(sl, inst->obj.keys[i]);
                    free(sl);
                    validate(sub, inst->obj.vals[i], il, sl2, root, defs, errs);
                    free(il); free(sl2);
                }
            }
        }
        /* additionalProperties */
        kw = obj_get(schema, "additionalProperties");
        if (kw) {
            for (size_t i = 0; i < inst->obj.len; i++) {
                bool in_props = false;
                if (props && props->type == JT_OBJ) {
                    for (size_t j = 0; j < props->obj.len; j++) {
                        if (strcmp(props->obj.keys[j], inst->obj.keys[i]) == 0) { in_props = true; break; }
                    }
                }
                if (!in_props) {
                    char *il = ptr_append(inst_loc, inst->obj.keys[i]);
                    char *sl = ptr_append(schema_loc, "additionalProperties");
                    validate(kw, inst->obj.vals[i], il, sl, root, defs, errs);
                    free(il); free(sl);
                }
            }
        }
    }

    /* allOf */
    kw = obj_get(schema, "allOf");
    if (kw && kw->type == JT_ARR) {
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "allOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            validate(kw->arr.items[i], inst, inst_loc, sl2, root, defs, errs);
            free(sl2);
        }
    }

    /* anyOf */
    kw = obj_get(schema, "anyOf");
    if (kw && kw->type == JT_ARR) {
        bool any = false;
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "anyOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            if (schema_accepts(kw->arr.items[i], inst, inst_loc, sl2, root, defs)) { any = true; free(sl2); break; }
            free(sl2);
        }
        if (!any) {
            char *sl = ptr_append(schema_loc, "anyOf");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* oneOf */
    kw = obj_get(schema, "oneOf");
    if (kw && kw->type == JT_ARR) {
        int count = 0;
        for (size_t i = 0; i < kw->arr.len; i++) {
            char *sl = ptr_append(schema_loc, "oneOf");
            char *sl2 = ptr_append_idx(sl, i);
            free(sl);
            if (schema_accepts(kw->arr.items[i], inst, inst_loc, sl2, root, defs)) count++;
            free(sl2);
        }
        if (count != 1) {
            char *sl = ptr_append(schema_loc, "oneOf");
            errlist_add(errs, inst_loc, sl);
            free(sl);
        }
    }

    /* not */
    kw = obj_get(schema, "not");
    if (kw) {
        char *sl = ptr_append(schema_loc, "not");
        if (schema_accepts(kw, inst, inst_loc, sl, root, defs)) {
            errlist_add(errs, inst_loc, sl);
        }
        free(sl);
    }

    /* if/then/else */
    kw = obj_get(schema, "if");
    if (kw) {
        char *sl_if = ptr_append(schema_loc, "if");
        bool if_ok = schema_accepts(kw, inst, inst_loc, sl_if, root, defs);
        free(sl_if);
        if (if_ok) {
            JVal *then_kw = obj_get(schema, "then");
            if (then_kw) {
                char *sl = ptr_append(schema_loc, "then");
                validate(then_kw, inst, inst_loc, sl, root, defs, errs);
                free(sl);
            }
        } else {
            JVal *else_kw = obj_get(schema, "else");
            if (else_kw) {
                char *sl = ptr_append(schema_loc, "else");
                validate(else_kw, inst, inst_loc, sl, root, defs, errs);
                free(sl);
            }
        }
    }

    /* $ref */
    kw = obj_get(schema, "$ref");
    if (kw && kw->type == JT_STR) {
        const char *ref_loc = NULL;
        JVal *target = resolve_ref(kw->s, root, defs, &ref_loc);
        if (target) {
            validate(target, inst, inst_loc, ref_loc, root, defs, errs);
        }
    }
}

/* ===== Sorting and dedup ===== */
static int cmp_err(const void *a, const void *b) {
    const Err *ea = (const Err*)a, *eb = (const Err*)b;
    int c = strcmp(ea->inst_loc, eb->inst_loc);
    if (c) return c;
    return strcmp(ea->schema_loc, eb->schema_loc);
}

/* ===== Main ===== */
static char *read_file(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    *len = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(*len + 1);
    fread(buf, 1, *len, f);
    buf[*len] = '\0';
    fclose(f);
    return buf;
}

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }
    char path[4096];
    snprintf(path, sizeof(path), "%s/schema.json", argv[1]);
    size_t slen;
    char *src = read_file(path, &slen);
    JVal *root = parse_json(src, slen);

    snprintf(path, sizeof(path), "%s/instances.json", argv[1]);
    size_t ilen;
    char *isrc = read_file(path, &ilen);
    JVal *instances = parse_json(isrc, ilen);

    JVal *defs = obj_get(root, "$defs");
    if (!defs || defs->type != JT_OBJ) {
        defs = new_val(JT_OBJ);
        defs->obj.keys = NULL; defs->obj.vals = NULL; defs->obj.len = 0;
    }

    int valid_count = 0, invalid_count = 0;

    for (size_t i = 0; i < instances->arr.len; i++) {
        ErrList errs = {NULL, 0, 0};
        validate(root, instances->arr.items[i], "#", "#", root, defs, &errs);

        if (errs.len == 0) {
            printf("%zu: valid\n", i);
            valid_count++;
        } else {
            qsort(errs.items, errs.len, sizeof(Err), cmp_err);
            /* dedup */
            size_t out = 1;
            for (size_t j = 1; j < errs.len; j++) {
                if (strcmp(errs.items[j].inst_loc, errs.items[out-1].inst_loc) != 0 ||
                    strcmp(errs.items[j].schema_loc, errs.items[out-1].schema_loc) != 0) {
                    errs.items[out++] = errs.items[j];
                } else {
                    free(errs.items[j].inst_loc);
                    free(errs.items[j].schema_loc);
                }
            }
            errs.len = out;
            printf("%zu: invalid (%zu)\n", i, errs.len);
            for (size_t j = 0; j < errs.len; j++) {
                printf("  %s %s\n", errs.items[j].inst_loc, errs.items[j].schema_loc);
            }
            invalid_count++;
        }
        for (size_t j = 0; j < errs.len; j++) {
            free(errs.items[j].inst_loc);
            free(errs.items[j].schema_loc);
        }
        free(errs.items);
    }

    printf("valid=%d invalid=%d\n", valid_count, invalid_count);
    return 0;
}

import Foundation
import CommonCrypto

func isValidBase64url(_ s: String) -> Bool {
    if s.isEmpty { return false }
    for scalar in s.unicodeScalars {
        if !((scalar >= "A" && scalar <= "Z") ||
             (scalar >= "a" && scalar <= "z") ||
             (scalar >= "0" && scalar <= "9") ||
             scalar == "-" || scalar == "_") {
            return false
        }
    }
    if s.unicodeScalars.count % 4 == 1 { return false }
    return true
}

func base64urlDecode(_ s: String) -> Data? {
    if s.isEmpty { return nil }
    for scalar in s.unicodeScalars {
        if !((scalar >= "A" && scalar <= "Z") ||
             (scalar >= "a" && scalar <= "z") ||
             (scalar >= "0" && scalar <= "9") ||
             scalar == "-" || scalar == "_") {
            return nil
        }
    }
    let len = s.unicodeScalars.count
    if len % 4 == 1 { return nil }
    var base64 = s.replacingOccurrences(of: "-", with: "+")
                  .replacingOccurrences(of: "_", with: "/")
    let rem = len % 4
    if rem == 2 { base64 += "==" }
    else if rem == 3 { base64 += "=" }
    return Data(base64Encoded: base64)
}

func computeHMAC(alg: String, key: Data, message: Data) -> Data? {
    var ccAlg: CCHmacAlgorithm
    var digestLen: Int
    switch alg {
    case "HS256":
        ccAlg = CCHmacAlgorithm(kCCHmacAlgSHA256)
        digestLen = Int(CC_SHA256_DIGEST_LENGTH)
    case "HS384":
        ccAlg = CCHmacAlgorithm(kCCHmacAlgSHA384)
        digestLen = Int(CC_SHA384_DIGEST_LENGTH)
    case "HS512":
        ccAlg = CCHmacAlgorithm(kCCHmacAlgSHA512)
        digestLen = Int(CC_SHA512_DIGEST_LENGTH)
    default:
        return nil
    }
    var result = [UInt8](repeating: 0, count: digestLen)
    key.withUnsafeBytes { keyPtr in
        message.withUnsafeBytes { msgPtr in
            CCHmac(ccAlg, keyPtr.baseAddress, key.count, msgPtr.baseAddress, message.count, &result)
        }
    }
    return Data(result)
}

func validateToken(_ token: String, keyMap: [String: (kty: String, alg: String, k: String)],
                   now: Double, leeway: Double, issuer: String, audience: String) -> (String, String, String) {
    // Rule 1: MALFORMED
    let segments = token.components(separatedBy: ".")
    guard segments.count == 3 else { return ("MALFORMED", "", "") }
    for seg in segments {
        guard isValidBase64url(seg) else { return ("MALFORMED", "", "") }
    }
    guard let headerData = base64urlDecode(segments[0]),
          let payloadData = base64urlDecode(segments[1]),
          let sigData = base64urlDecode(segments[2]) else {
        return ("MALFORMED", "", "")
    }
    guard let headerObj = try? JSONSerialization.jsonObject(with: headerData),
          let payloadObj = try? JSONSerialization.jsonObject(with: payloadData),
          let header = headerObj as? [String: Any],
          let payload = payloadObj as? [String: Any] else {
        return ("MALFORMED", "", "")
    }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = header["alg"] as? String,
          alg == "HS256" || alg == "HS384" || alg == "HS512" else {
        return ("UNSUPPORTED_ALG", "", "")
    }

    // Rule 3: UNKNOWN_KEY
    guard let kid = header["kid"] as? String,
          let keyEntry = keyMap[kid] else {
        return ("UNKNOWN_KEY", "", "")
    }

    // Rule 4: ALG_MISMATCH
    guard keyEntry.alg == alg else {
        return ("ALG_MISMATCH", "", "")
    }

    // Rule 5: BAD_SIGNATURE
    let signingInput = "\(segments[0]).\(segments[1])"
    guard let signingData = signingInput.data(using: .ascii) else {
        return ("BAD_SIGNATURE", "", "")
    }
    guard let secretData = base64urlDecode(keyEntry.k) else {
        return ("BAD_SIGNATURE", "", "")
    }
    guard let expectedSig = computeHMAC(alg: alg, key: secretData, message: signingData),
          expectedSig == sigData else {
        return ("BAD_SIGNATURE", "", "")
    }

    // Rule 6: EXPIRED
    if let exp = payload["exp"] as? NSNumber {
        let expVal = exp.doubleValue
        if now >= expVal + leeway {
            return ("EXPIRED", "", "")
        }
    }

    // Rule 7: NOT_YET_VALID
    if let nbf = payload["nbf"] as? NSNumber {
        let nbfVal = nbf.doubleValue
        if now + leeway < nbfVal {
            return ("NOT_YET_VALID", "", "")
        }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payload["iss"] as? String, iss == issuer else {
        return ("BAD_ISSUER", "", "")
    }

    // Rule 9: BAD_AUDIENCE
    var audOk = false
    if let aud = payload["aud"] {
        if let audStr = aud as? String {
            audOk = (audStr == audience)
        } else if let audArr = aud as? [Any] {
            audOk = audArr.contains { ($0 as? String) == audience }
        }
    }
    guard audOk else {
        return ("BAD_AUDIENCE", "", "")
    }

    // VALID
    let sub = payload["sub"] as! String
    var scopes = ""
    if let scopeStr = payload["scope"] as? String, !scopeStr.isEmpty {
        let parts = scopeStr.components(separatedBy: " ").filter { !$0.isEmpty }
        let unique = Set(parts)
        scopes = unique.sorted { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
                       .joined(separator: ",")
    }

    return ("VALID", sub, scopes)
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let configPath = "\(dir)/config.json"
let configData = try! Data(contentsOf: URL(fileURLWithPath: configPath))
let config = try! JSONSerialization.jsonObject(with: configData) as! [String: Any]

let now = (config["now"] as! NSNumber).doubleValue
let leeway = (config["leeway"] as! NSNumber).doubleValue
let issuer = config["issuer"] as! String
let audience = config["audience"] as! String
let keysArray = config["keys"] as! [[String: Any]]

var keyMap: [String: (kty: String, alg: String, k: String)] = [:]
for key in keysArray {
    let kid = key["kid"] as! String
    let kty = key["kty"] as! String
    let alg = key["alg"] as! String
    let k = key["k"] as! String
    keyMap[kid] = (kty, alg, k)
}

let tokensPath = "\(dir)/tokens.txt"
let tokensContent = try! String(contentsOfFile: tokensPath, encoding: .utf8)
let lines = tokensContent.components(separatedBy: "\n")

var validCount = 0
var invalidCount = 0
var outputLines: [String] = []
var tokenNumber = 0

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    tokenNumber += 1

    let (result, sub, scopes) = validateToken(trimmed, keyMap: keyMap, now: now, leeway: leeway,
                                              issuer: issuer, audience: audience)
    if result == "VALID" {
        validCount += 1
        outputLines.append("\(tokenNumber): VALID sub=\(sub) scope=\(scopes)")
    } else {
        invalidCount += 1
        outputLines.append("\(tokenNumber): \(result)")
    }
}

for ol in outputLines {
    print(ol)
}
print("")
print("valid=\(validCount) invalid=\(invalidCount)")

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <ctype.h>
#include <CommonCrypto/CommonHMAC.h>

/* ============ JSON Parser ============ */

typedef enum { JSON_NULL, JSON_BOOL, JSON_NUMBER, JSON_STRING, JSON_ARRAY, JSON_OBJECT } json_type_t;

typedef struct json_value {
    json_type_t type;
    union {
        bool bool_val;
        double num_val;
        char *str_val;
        struct { struct json_value **items; size_t count; } array;
        struct { char **keys; struct json_value **values; size_t count; } object;
    };
} json_value_t;

typedef struct {
    const char *s;
    size_t pos;
    size_t len;
} json_parser_t;

static void skip_ws(json_parser_t *p) {
    while (p->pos < p->len && (p->s[p->pos]==' '||p->s[p->pos]=='\t'||p->s[p->pos]=='\n'||p->s[p->pos]=='\r'))
        p->pos++;
}

static json_value_t *parse_value(json_parser_t *p);

static char *parse_string_raw(json_parser_t *p) {
    if (p->pos >= p->len || p->s[p->pos] != '"') return NULL;
    p->pos++;
    size_t start = p->pos;
    /* First pass: find end and check for escapes */
    size_t out_len = 0;
    size_t tmp = p->pos;
    while (tmp < p->len && p->s[tmp] != '"') {
        if (p->s[tmp] == '\\') tmp++;
        tmp++;
        out_len++;
    }
    if (tmp >= p->len) return NULL;
    p->pos = start;

    char *buf = malloc(out_len * 4 + 1);
    size_t bi = 0;

    while (p->pos < p->len && p->s[p->pos] != '"') {
        if (p->s[p->pos] == '\\') {
            p->pos++;
            if (p->pos >= p->len) { free(buf); return NULL; }
            char c = p->s[p->pos++];
            switch (c) {
                case '"': buf[bi++]='"'; break;
                case '\\': buf[bi++]='\\'; break;
                case '/': buf[bi++]='/'; break;
                case 'b': buf[bi++]='\b'; break;
                case 'f': buf[bi++]='\f'; break;
                case 'n': buf[bi++]='\n'; break;
                case 'r': buf[bi++]='\r'; break;
                case 't': buf[bi++]='\t'; break;
                case 'u': {
                    if (p->pos + 4 > p->len) { free(buf); return NULL; }
                    unsigned cp = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = p->s[p->pos++];
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= h - '0';
                        else if (h >= 'a' && h <= 'f') cp |= h - 'a' + 10;
                        else if (h >= 'A' && h <= 'F') cp |= h - 'A' + 10;
                        else { free(buf); return NULL; }
                    }
                    /* Check for surrogate pair */
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (p->pos + 6 <= p->len && p->s[p->pos] == '\\' && p->s[p->pos+1] == 'u') {
                            p->pos += 2;
                            unsigned lo = 0;
                            for (int i = 0; i < 4; i++) {
                                char h = p->s[p->pos++];
                                lo <<= 4;
                                if (h >= '0' && h <= '9') lo |= h - '0';
                                else if (h >= 'a' && h <= 'f') lo |= h - 'a' + 10;
                                else if (h >= 'A' && h <= 'F') lo |= h - 'A' + 10;
                                else { free(buf); return NULL; }
                            }
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        }
                    }
                    /* Encode as UTF-8 */
                    if (cp < 0x80) {
                        buf[bi++] = (char)cp;
                    } else if (cp < 0x800) {
                        buf[bi++] = (char)(0xC0 | (cp >> 6));
                        buf[bi++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        buf[bi++] = (char)(0xE0 | (cp >> 12));
                        buf[bi++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[bi++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        buf[bi++] = (char)(0xF0 | (cp >> 18));
                        buf[bi++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        buf[bi++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[bi++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: free(buf); return NULL;
            }
        } else {
            buf[bi++] = p->s[p->pos++];
        }
    }
    if (p->pos >= p->len || p->s[p->pos] != '"') { free(buf); return NULL; }
    p->pos++; /* skip closing quote */
    buf[bi] = '\0';
    return buf;
}

static json_value_t *parse_string(json_parser_t *p) {
    char *s = parse_string_raw(p);
    if (!s) return NULL;
    json_value_t *v = calloc(1, sizeof(json_value_t));
    v->type = JSON_STRING;
    v->str_val = s;
    return v;
}

static json_value_t *parse_number(json_parser_t *p) {
    size_t start = p->pos;
    if (p->pos < p->len && p->s[p->pos] == '-') p->pos++;
    while (p->pos < p->len && isdigit(p->s[p->pos])) p->pos++;
    if (p->pos < p->len && p->s[p->pos] == '.') {
        p->pos++;
        while (p->pos < p->len && isdigit(p->s[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->s[p->pos] == 'e' || p->s[p->pos] == 'E')) {
        p->pos++;
        if (p->pos < p->len && (p->s[p->pos] == '+' || p->s[p->pos] == '-')) p->pos++;
        while (p->pos < p->len && isdigit(p->s[p->pos])) p->pos++;
    }
    if (p->pos == start) return NULL;
    char *tmp = malloc(p->pos - start + 1);
    memcpy(tmp, p->s + start, p->pos - start);
    tmp[p->pos - start] = '\0';
    double d = strtod(tmp, NULL);
    free(tmp);
    json_value_t *v = calloc(1, sizeof(json_value_t));
    v->type = JSON_NUMBER;
    v->num_val = d;
    return v;
}

static json_value_t *parse_array(json_parser_t *p) {
    p->pos++; /* skip [ */
    skip_ws(p);
    json_value_t *v = calloc(1, sizeof(json_value_t));
    v->type = JSON_ARRAY;
    size_t cap = 8;
    v->array.items = malloc(cap * sizeof(json_value_t*));
    v->array.count = 0;
    if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        json_value_t *item = parse_value(p);
        if (!item) { free(v->array.items); free(v); return NULL; }
        if (v->array.count >= cap) { cap *= 2; v->array.items = realloc(v->array.items, cap * sizeof(json_value_t*)); }
        v->array.items[v->array.count++] = item;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
        free(v->array.items); free(v); return NULL;
    }
}

static json_value_t *parse_object(json_parser_t *p) {
    p->pos++; /* skip { */
    skip_ws(p);
    json_value_t *v = calloc(1, sizeof(json_value_t));
    v->type = JSON_OBJECT;
    size_t cap = 8;
    v->object.keys = malloc(cap * sizeof(char*));
    v->object.values = malloc(cap * sizeof(json_value_t*));
    v->object.count = 0;
    if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        if (!key) { free(v->object.keys); free(v->object.values); free(v); return NULL; }
        skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != ':') { free(key); free(v->object.keys); free(v->object.values); free(v); return NULL; }
        p->pos++;
        skip_ws(p);
        json_value_t *val = parse_value(p);
        if (!val) { free(key); free(v->object.keys); free(v->object.values); free(v); return NULL; }
        if (v->object.count >= cap) {
            cap *= 2;
            v->object.keys = realloc(v->object.keys, cap * sizeof(char*));
            v->object.values = realloc(v->object.values, cap * sizeof(json_value_t*));
        }
        v->object.keys[v->object.count] = key;
        v->object.values[v->object.count] = val;
        v->object.count++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return v; }
        free(v->object.keys); free(v->object.values); free(v); return NULL;
    }
}

static json_value_t *parse_value(json_parser_t *p) {
    skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->s[p->pos];
    if (c == '"') return parse_string(p);
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == 't') {
        if (p->pos + 4 <= p->len && memcmp(p->s + p->pos, "true", 4) == 0) {
            p->pos += 4;
            json_value_t *v = calloc(1, sizeof(json_value_t));
            v->type = JSON_BOOL; v->bool_val = true;
            return v;
        }
        return NULL;
    }
    if (c == 'f') {
        if (p->pos + 5 <= p->len && memcmp(p->s + p->pos, "false", 5) == 0) {
            p->pos += 5;
            json_value_t *v = calloc(1, sizeof(json_value_t));
            v->type = JSON_BOOL; v->bool_val = false;
            return v;
        }
        return NULL;
    }
    if (c == 'n') {
        if (p->pos + 4 <= p->len && memcmp(p->s + p->pos, "null", 4) == 0) {
            p->pos += 4;
            json_value_t *v = calloc(1, sizeof(json_value_t));
            v->type = JSON_NULL;
            return v;
        }
        return NULL;
    }
    if (c == '-' || isdigit(c)) return parse_number(p);
    return NULL;
}

static json_value_t *json_parse(const char *s, size_t len) {
    json_parser_t p = {s, 0, len};
    json_value_t *v = parse_value(&p);
    if (!v) return NULL;
    skip_ws(&p);
    if (p.pos != p.len) { /* trailing garbage */ }
    return v;
}

static json_value_t *json_get(json_value_t *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (size_t i = 0; i < obj->object.count; i++) {
        if (strcmp(obj->object.keys[i], key) == 0)
            return obj->object.values[i];
    }
    return NULL;
}

/* ============ Base64url ============ */

static bool is_base64url_char(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
           (c >= '0' && c <= '9') || c == '-' || c == '_';
}

static bool is_valid_base64url(const char *s, size_t len) {
    if (len % 4 == 1) return false;
    for (size_t i = 0; i < len; i++) {
        if (!is_base64url_char(s[i])) return false;
    }
    return true;
}

static int b64url_decode_char(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}

static unsigned char *b64url_decode(const char *s, size_t len, size_t *out_len) {
    size_t out_cap = (len / 4 + 1) * 3 + 4;
    unsigned char *out = malloc(out_cap);
    size_t oi = 0;
    int buf = 0, bits = 0;
    for (size_t i = 0; i < len; i++) {
        int val = b64url_decode_char(s[i]);
        if (val < 0) { free(out); return NULL; }
        buf = (buf << 6) | val;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out[oi++] = (buf >> bits) & 0xFF;
        }
    }
    *out_len = oi;
    return out;
}

/* ============ HMAC ============ */

static void hmac_sha(const char *alg, const unsigned char *key, size_t key_len,
                     const unsigned char *data, size_t data_len,
                     unsigned char *out, size_t *out_len) {
    CCHmacAlgorithm algo;
    if (strcmp(alg, "HS256") == 0) { algo = kCCHmacAlgSHA256; *out_len = 32; }
    else if (strcmp(alg, "HS384") == 0) { algo = kCCHmacAlgSHA384; *out_len = 48; }
    else { algo = kCCHmacAlgSHA512; *out_len = 64; }
    CCHmac(algo, key, key_len, data, data_len, out);
}

/* ============ Config ============ */

typedef struct {
    char *kid;
    char *kty;
    char *alg;
    char *k; /* base64url encoded */
} config_key_t;

typedef struct {
    double now;
    double leeway;
    char *issuer;
    char *audience;
    config_key_t *keys;
    size_t key_count;
} config_t;

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    *out_len = sz;
    return buf;
}

static config_t parse_config(const char *path) {
    config_t cfg = {0};
    size_t len;
    char *content = read_file(path, &len);
    if (!content) { fprintf(stderr, "Cannot read config\n"); exit(1); }
    json_value_t *root = json_parse(content, len);
    if (!root || root->type != JSON_OBJECT) { fprintf(stderr, "Bad config\n"); exit(1); }

    json_value_t *now_v = json_get(root, "now");
    cfg.now = now_v && now_v->type == JSON_NUMBER ? now_v->num_val : 0;

    json_value_t *leeway_v = json_get(root, "leeway");
    cfg.leeway = leeway_v && leeway_v->type == JSON_NUMBER ? leeway_v->num_val : 0;

    json_value_t *iss_v = json_get(root, "issuer");
    cfg.issuer = (iss_v && iss_v->type == JSON_STRING) ? iss_v->str_val : NULL;

    json_value_t *aud_v = json_get(root, "audience");
    cfg.audience = (aud_v && aud_v->type == JSON_STRING) ? aud_v->str_val : NULL;

    json_value_t *keys_v = json_get(root, "keys");
    if (keys_v && keys_v->type == JSON_ARRAY) {
        cfg.key_count = keys_v->array.count;
        cfg.keys = calloc(cfg.key_count, sizeof(config_key_t));
        for (size_t i = 0; i < cfg.key_count; i++) {
            json_value_t *kv = keys_v->array.items[i];
            if (kv->type != JSON_OBJECT) continue;
            json_value_t *kid_v = json_get(kv, "kid");
            json_value_t *kty_v = json_get(kv, "kty");
            json_value_t *alg_v = json_get(kv, "alg");
            json_value_t *k_v = json_get(kv, "k");
            cfg.keys[i].kid = (kid_v && kid_v->type == JSON_STRING) ? strdup(kid_v->str_val) : NULL;
            cfg.keys[i].kty = (kty_v && kty_v->type == JSON_STRING) ? strdup(kty_v->str_val) : NULL;
            cfg.keys[i].alg = (alg_v && alg_v->type == JSON_STRING) ? strdup(alg_v->str_val) : NULL;
            cfg.keys[i].k = (k_v && k_v->type == JSON_STRING) ? strdup(k_v->str_val) : NULL;
        }
    }
    return cfg;
}

static config_key_t *find_key(config_t *cfg, const char *kid) {
    for (size_t i = 0; i < cfg->key_count; i++) {
        if (cfg->keys[i].kid && strcmp(cfg->keys[i].kid, kid) == 0)
            return &cfg->keys[i];
    }
    return NULL;
}

/* ============ Token Validation ============ */

static char *trim_line(char *line) {
    while (*line == ' ' || *line == '\t') line++;
    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == ' ' || line[len-1] == '\t' || line[len-1] == '\r' || line[len-1] == '\n'))
        len--;
    line[len] = '\0';
    return line;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char**)a, *(const char**)b);
}

typedef struct {
    char *header_seg;
    size_t header_seg_len;
    char *payload_seg;
    size_t payload_seg_len;
    char *sig_seg;
    size_t sig_seg_len;
} token_parts_t;

static bool split_token(const char *token, token_parts_t *parts) {
    const char *d1 = strchr(token, '.');
    if (!d1) return false;
    const char *d2 = strchr(d1 + 1, '.');
    if (!d2) return false;
    if (strchr(d2 + 1, '.')) return false;

    parts->header_seg = (char*)token;
    parts->header_seg_len = d1 - token;
    parts->payload_seg = (char*)(d1 + 1);
    parts->payload_seg_len = d2 - d1 - 1;
    parts->sig_seg = (char*)(d2 + 1);
    parts->sig_seg_len = strlen(d2 + 1);

    if (parts->header_seg_len == 0 || parts->payload_seg_len == 0 || parts->sig_seg_len == 0)
        return false;

    return true;
}

static const char *validate_token(config_t *cfg, const char *token, char *valid_output, size_t valid_output_size) {
    token_parts_t parts;
    if (!split_token(token, &parts))
        return "MALFORMED";

    /* Validate base64url segments */
    if (!is_valid_base64url(parts.header_seg, parts.header_seg_len))
        return "MALFORMED";
    if (!is_valid_base64url(parts.payload_seg, parts.payload_seg_len))
        return "MALFORMED";
    if (!is_valid_base64url(parts.sig_seg, parts.sig_seg_len))
        return "MALFORMED";

    /* Decode header and payload */
    size_t hdr_len, pay_len;
    unsigned char *hdr_bytes = b64url_decode(parts.header_seg, parts.header_seg_len, &hdr_len);
    if (!hdr_bytes) return "MALFORMED";
    unsigned char *pay_bytes = b64url_decode(parts.payload_seg, parts.payload_seg_len, &pay_len);
    if (!pay_bytes) { free(hdr_bytes); return "MALFORMED"; }

    json_value_t *header = json_parse((char*)hdr_bytes, hdr_len);
    json_value_t *payload = json_parse((char*)pay_bytes, pay_len);
    free(hdr_bytes);
    free(pay_bytes);

    if (!header || header->type != JSON_OBJECT) {
        if (header) free(header);
        if (payload) free(payload);
        return "MALFORMED";
    }
    if (!payload || payload->type != JSON_OBJECT) {
        free(header);
        if (payload) free(payload);
        return "MALFORMED";
    }

    /* Rule 2: UNSUPPORTED_ALG */
    json_value_t *alg_v = json_get(header, "alg");
    if (!alg_v || alg_v->type != JSON_STRING) { free(header); free(payload); return "UNSUPPORTED_ALG"; }
    const char *alg = alg_v->str_val;
    if (strcmp(alg, "HS256") != 0 && strcmp(alg, "HS384") != 0 && strcmp(alg, "HS512") != 0) {
        free(header); free(payload); return "UNSUPPORTED_ALG";
    }

    /* Rule 3: UNKNOWN_KEY */
    json_value_t *kid_v = json_get(header, "kid");
    if (!kid_v || kid_v->type != JSON_STRING) { free(header); free(payload); return "UNKNOWN_KEY"; }
    config_key_t *ckey = find_key(cfg, kid_v->str_val);
    if (!ckey) { free(header); free(payload); return "UNKNOWN_KEY"; }

    /* Rule 4: ALG_MISMATCH */
    if (!ckey->alg || strcmp(ckey->alg, alg) != 0) { free(header); free(payload); return "ALG_MISMATCH"; }

    /* Rule 5: BAD_SIGNATURE */
    size_t sig_key_len;
    unsigned char *sig_key = b64url_decode(ckey->k, strlen(ckey->k), &sig_key_len);
    if (!sig_key) { free(header); free(payload); return "BAD_SIGNATURE"; }

    size_t signing_input_len = parts.header_seg_len + 1 + parts.payload_seg_len;
    char *signing_input = malloc(signing_input_len + 1);
    memcpy(signing_input, parts.header_seg, parts.header_seg_len);
    signing_input[parts.header_seg_len] = '.';
    memcpy(signing_input + parts.header_seg_len + 1, parts.payload_seg, parts.payload_seg_len);
    signing_input[signing_input_len] = '\0';

    unsigned char expected_sig[64];
    size_t expected_sig_len;
    hmac_sha(alg, sig_key, sig_key_len, (unsigned char*)signing_input, signing_input_len, expected_sig, &expected_sig_len);
    free(signing_input);
    free(sig_key);

    size_t actual_sig_len;
    unsigned char *actual_sig = b64url_decode(parts.sig_seg, parts.sig_seg_len, &actual_sig_len);
    if (!actual_sig || actual_sig_len != expected_sig_len || memcmp(actual_sig, expected_sig, expected_sig_len) != 0) {
        free(actual_sig);
        free(header); free(payload);
        return "BAD_SIGNATURE";
    }
    free(actual_sig);

    /* Rule 6: EXPIRED */
    json_value_t *exp_v = json_get(payload, "exp");
    if (exp_v && exp_v->type == JSON_NUMBER) {
        if (cfg->now >= exp_v->num_val + cfg->leeway) {
            free(header); free(payload);
            return "EXPIRED";
        }
    }

    /* Rule 7: NOT_YET_VALID */
    json_value_t *nbf_v = json_get(payload, "nbf");
    if (nbf_v && nbf_v->type == JSON_NUMBER) {
        if (cfg->now + cfg->leeway < nbf_v->num_val) {
            free(header); free(payload);
            return "NOT_YET_VALID";
        }
    }

    /* Rule 8: BAD_ISSUER */
    json_value_t *iss_v = json_get(payload, "iss");
    if (!iss_v || iss_v->type != JSON_STRING || strcmp(iss_v->str_val, cfg->issuer) != 0) {
        free(header); free(payload);
        return "BAD_ISSUER";
    }

    /* Rule 9: BAD_AUDIENCE */
    json_value_t *aud_v = json_get(payload, "aud");
    if (!aud_v) { free(header); free(payload); return "BAD_AUDIENCE"; }
    if (aud_v->type == JSON_STRING) {
        if (strcmp(aud_v->str_val, cfg->audience) != 0) { free(header); free(payload); return "BAD_AUDIENCE"; }
    } else if (aud_v->type == JSON_ARRAY) {
        bool found = false;
        for (size_t i = 0; i < aud_v->array.count; i++) {
            json_value_t *item = aud_v->array.items[i];
            if (item->type == JSON_STRING && strcmp(item->str_val, cfg->audience) == 0) {
                found = true; break;
            }
        }
        if (!found) { free(header); free(payload); return "BAD_AUDIENCE"; }
    } else {
        free(header); free(payload);
        return "BAD_AUDIENCE";
    }

    /* VALID - build output */
    json_value_t *sub_v = json_get(payload, "sub");
    const char *sub_str = (sub_v && sub_v->type == JSON_STRING) ? sub_v->str_val : "";

    json_value_t *scope_v = json_get(payload, "scope");
    const char *scope_str = (scope_v && scope_v->type == JSON_STRING) ? scope_v->str_val : "";

    /* Split scope on spaces, deduplicate, sort */
    char *scope_copy = strdup(scope_str);
    char *scopes[1024];
    size_t scope_count = 0;

    if (scope_copy[0] != '\0') {
        char *tok = strtok(scope_copy, " ");
        while (tok && scope_count < 1024) {
            if (tok[0] != '\0') {
                scopes[scope_count++] = strdup(tok);
            }
            tok = strtok(NULL, " ");
        }
    }

    /* Sort */
    qsort(scopes, scope_count, sizeof(char*), cmp_str);

    /* Deduplicate */
    size_t dedup_count = 0;
    for (size_t i = 0; i < scope_count; i++) {
        if (i == 0 || strcmp(scopes[i], scopes[i-1]) != 0) {
            scopes[dedup_count++] = scopes[i];
        }
    }

    /* Join */
    snprintf(valid_output, valid_output_size, "VALID sub=%s scope=", sub_str);
    size_t cur_len = strlen(valid_output);
    for (size_t i = 0; i < dedup_count; i++) {
        if (i > 0 && cur_len < valid_output_size - 1) {
            valid_output[cur_len++] = ',';
            valid_output[cur_len] = '\0';
        }
        size_t sl = strlen(scopes[i]);
        if (cur_len + sl < valid_output_size - 1) {
            memcpy(valid_output + cur_len, scopes[i], sl);
            cur_len += sl;
            valid_output[cur_len] = '\0';
        }
    }

    for (size_t i = 0; i < scope_count; i++) free(scopes[i]);
    free(scope_copy);

    free(header);
    free(payload);
    return NULL; /* means VALID */
}

/* ============ Main ============ */

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }

    char config_path[4096], tokens_path[4096];
    snprintf(config_path, sizeof(config_path), "%s/config.json", argv[1]);
    snprintf(tokens_path, sizeof(tokens_path), "%s/tokens.txt", argv[1]);

    config_t cfg = parse_config(config_path);

    size_t tokens_len;
    char *tokens_content = read_file(tokens_path, &tokens_len);
    if (!tokens_content) { fprintf(stderr, "Cannot read tokens\n"); return 1; }

    int valid_count = 0, invalid_count = 0;
    int line_num = 0;

    char *line = tokens_content;
    while (*line) {
        char *nl = strchr(line, '\n');
        if (nl) *nl = '\0';

        char *trimmed = trim_line(line);
        if (trimmed[0] != '\0') {
            line_num++;
            char valid_buf[65536];
            const char *result = validate_token(&cfg, trimmed, valid_buf, sizeof(valid_buf));
            if (result) {
                printf("%d: %s\n", line_num, result);
                invalid_count++;
            } else {
                printf("%d: %s\n", line_num, valid_buf);
                valid_count++;
            }
        }

        if (nl) line = nl + 1;
        else break;
    }

    printf("\nvalid=%d invalid=%d\n", valid_count, invalid_count);

    free(tokens_content);
    return 0;
}

