def validate_arguments(tool_name, arguments):
    schema = TOOL_SCHEMAS[tool_name]
    properties = schema['properties']
    required = schema['required']

    # Step 2: unknown arguments
    unknown = [k for k in arguments if k not in properties]
    if unknown:
        unknown.sort()
        return f"unknown argument: {unknown[0]}"

    # Step 3: check each property in schema order
    for prop_name in properties:
        if prop_name not in arguments:
            if prop_name in required:
                return f"missing required argument: {prop_name}"
            continue

        val = arguments[prop_name]
        prop_schema = properties[prop_name]
        prop_type = prop_schema['type']

        if prop_type == 'string':
            if not isinstance(val, str):
                return f"argument {prop_name} must be a string"
            if prop_schema.get('minLength', 0) == 1 and len(val) == 0:
                return f"argument {prop_name} must not be empty"
        elif prop_type == 'array':
            if not isinstance(val, list):
                return f"argument {prop_name} must be an array of integers"
            items_type = prop_schema.get('items', {}).get('type')
            if items_type == 'integer':
                for el in val:
                    if not isinstance(el, int) or isinstance(el, bool):
                        return f"argument {prop_name} must be an array of integers"
            if prop_schema.get('minItems', 0) == 1 and len(val) == 0:
                return f"argument {prop_name} must not be empty"

    return None


def execute_tool(tool_name, arguments, store):
    if tool_name == 'kv_set':
        key = arguments['key']
        value = arguments['value']
        if key in store:
            store[key] = value
            return {"content": [{"type": "text", "text": f"updated {key}"}], "isError": False}
        else:
            store[key] = value
            return {"content": [{"type": "text", "text": f"created {key}"}], "isError": False}

    elif tool_name == 'kv_get':
        key = arguments['key']
        if key in store:
            return {"content": [{"type": "text", "text": store[key]}], "isError": False}
        else:
            return {"content": [{"type": "text", "text": f"key not found: {key}"}], "isError": True}

    elif tool_name == 'kv_list':
        prefix = arguments.get('prefix', '')
        keys = sorted([k for k in store if k.startswith(prefix)])
        structured = {"keys": keys, "count": len(keys)}
        return {
            "content": [{"type": "text", "text": json.dumps(structured)}],
            "structuredContent": structured,
            "isError": False,
        }

    elif tool_name == 'sum':
        numbers = arguments['numbers']
        total = sum(numbers)
        structured = {"sum": total, "count": len(numbers)}
        return {
            "content": [{"type": "text", "text": json.dumps(structured)}],
            "structuredContent": structured,
            "isError": False,
        }

    elif tool_name == 'text_stats':
        text = arguments['text']
        w = count_words(text)
        c = len(text)
        b = len(text.encode('utf-8'))
        structured = {"words": w, "codepoints": c, "utf8_bytes": b}
        return {
            "content": [{"type": "text", "text": json.dumps(structured)}],
            "structuredContent": structured,
            "isError": False,
        }


def main():
    initialized = False
    store = {}

    for line in sys.stdin:
        # Strip trailing CR/LF
        line = line.rstrip('\r\n')

        # Skip empty/whitespace-only lines
        if line.strip(' \t\r') == '':
            continue

        # Rule 1: Parse error
        try:
            msg = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}}) + "\n")
            continue

        # Rule 2: Not an object
        if not isinstance(msg, dict):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}) + "\n")
            continue

        # Rule 3: Client response (has result or error, no method)
        if 'method' not in msg and ('result' in msg or 'error' in msg):
            continue

        # Rule 4: Invalid request check
        is_invalid = False
        if msg.get('jsonrpc') != "2.0":
            is_invalid = True
        if 'method' not in msg or not isinstance(msg.get('method'), str):
            is_invalid = True
        if 'id' in msg and not is_valid_id(msg['id']):
            is_invalid = True

        if is_invalid:
            if 'id' in msg and is_valid_id(msg['id']):
                resp_id = msg['id']
            else:
                resp_id = None
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": resp_id, "error": {"code": -32600, "message": "Invalid Request"}}) + "\n")
            continue

        # Rule 5: Notification (no id member)
        if 'id' not in msg:
            continue

        # Rule 6: It's a request
        method = msg['method']
        request_id = msg['id']
        params = msg.get('params')

        # 6a: Method not found
        if method not in VALID_METHODS:
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32601, "message": "Method not found"}}) + "\n")
            continue

        # 6b: params present but not an object
        if 'params' in msg and not isinstance(params, dict):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32602, "message": "Invalid params"}}) + "\n")
            continue

        # 6c: Server not initialized
        if not initialized and method not in ('initialize', 'ping'):
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32002, "message": "Server not initialized"}}) + "\n")
            continue

        # 6d: Dispatch
        if method == 'initialize':
            if initialized:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32600, "message": "Already initialized"}}) + "\n")
                continue
            if params is None or not isinstance(params, dict):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32602, "message": "Invalid params"}}) + "\n")
                continue
            if 'protocolVersion' not in params or not isinstance(params['protocolVersion'], str):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32602, "message": "Invalid params"}}) + "\n")
                continue
            version = params['protocolVersion']
            if version not in SUPPORTED_VERSIONS:
                version = "2025-06-18"
            initialized = True
            result = {
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"},
            }
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}) + "\n")

        elif method == 'ping':
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": {}}) + "\n")

        elif method == 'tools/list':
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": {"tools": TOOLS}}) + "\n")

        elif method == 'tools/call':
            if params is None:
                params = {}
            name = params.get('name')
            if name is None or not isinstance(name, str):
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32602, "message": "Invalid params"}}) + "\n")
                continue
            if name not in TOOL_NAMES:
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "error": {"code": -32602, "message": f"Unknown tool: {name}"}}) + "\n")
                continue

            # Get arguments
            if 'arguments' in params:
                arguments = params['arguments']
                if not isinstance(arguments, dict):
                    result = {"content": [{"type": "text", "text": "arguments must be an object"}], "isError": True}
                    sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}) + "\n")
                    continue
            else:
                arguments = {}

            # Validate arguments
            error_msg = validate_arguments(name, arguments)
            if error_msg is not None:
                result = {"content": [{"type": "text", "text": error_msg}], "isError": True}
                sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}) + "\n")
                continue

            # Execute tool
            result = execute_tool(name, arguments, store)
            sys.stdout.write(json.dumps({"jsonrpc": "2.0", "id": request_id, "result": result}) + "\n")


