use std::env;
use std::fs;

// ============ JSON ============

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let JsonValue::String(s) = self { Some(s) } else { None }
    }
    fn as_f64(&self) -> Option<f64> {
        if let JsonValue::Number(n) = self { Some(*n) } else { None }
    }
    fn as_array(&self) -> Option<&[JsonValue]> {
        if let JsonValue::Array(a) = self { Some(a) } else { None }
    }
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a [u8]) -> Self { JsonParser { input, pos: 0 } }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_ws();
        if self.pos >= self.input.len() { return None; }
        match self.input[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(JsonValue::String),
            b't' => self.parse_lit(b"true", JsonValue::Bool(true)),
            b'f' => self.parse_lit(b"false", JsonValue::Bool(false)),
            b'n' => self.parse_lit(b"null", JsonValue::Null),
            _ => self.parse_number(),
        }
    }

    fn parse_lit(&mut self, lit: &[u8], val: JsonValue) -> Option<JsonValue> {
        if self.input[self.pos..].starts_with(lit) {
            self.pos += lit.len();
            Some(val)
        } else { None }
    }

    fn parse_object(&mut self) -> Option<JsonValue> {
        self.pos += 1;
        self.skip_ws();
        let mut pairs = Vec::new();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return Some(JsonValue::Object(pairs));
        }
        loop {
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b'"' { return None; }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' { return None; }
            self.pos += 1;
            let value = self.parse_value()?;
            pairs.push((key, value));
            self.skip_ws();
            if self.pos >= self.input.len() { return None; }
            match self.input[self.pos] {
                b',' => { self.pos += 1; }
                b'}' => { self.pos += 1; return Some(JsonValue::Object(pairs)); }
                _ => return None,
            }
        }
    }

    fn parse_array(&mut self) -> Option<JsonValue> {
        self.pos += 1;
        self.skip_ws();
        let mut items = Vec::new();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return Some(JsonValue::Array(items));
        }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            if self.pos >= self.input.len() { return None; }
            match self.input[self.pos] {
                b',' => { self.pos += 1; }
                b']' => { self.pos += 1; return Some(JsonValue::Array(items)); }
                _ => return None,
            }
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.input.len() { return None; }
            let c = self.input[self.pos];
            if c == b'"' { self.pos += 1; return Some(result); }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() { return None; }
                let esc = self.input[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{08}'),
                    b'f' => result.push('\u{0C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4()?;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.input.len()
                                && self.input[self.pos] == b'\\'
                                && self.input[self.pos + 1] == b'u'
                            {
                                self.pos += 2;
                                let cp2 = self.parse_hex4()?;
                                if cp2 >= 0xDC00 && cp2 <= 0xDFFF {
                                    let full = 0x10000u32 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                    result.push(char::from_u32(full).unwrap_or('\u{FFFD}'));
                                } else {
                                    result.push('\u{FFFD}');
                                    result.push(char::from_u32(cp2).unwrap_or('\u{FFFD}'));
                                }
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            result.push('\u{FFFD}');
                        } else {
                            result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => return None,
                }
            } else if c < 0x80 {
                result.push(c as char);
                self.pos += 1;
            } else {
                let start = self.pos;
                let len = if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
                if self.pos + len > self.input.len() { return None; }
                let s = std::str::from_utf8(&self.input[start..start + len]).ok()?;
                result.push_str(s);
                self.pos += len;
            }
        }
    }

    fn parse_hex4(&mut self) -> Option<u32> {
        if self.pos + 4 > self.input.len() { return None; }
        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4]).ok()?;
        let val = u32::from_str_radix(hex, 16).ok()?;
        self.pos += 4;
        Some(val)
    }

    fn parse_number(&mut self) -> Option<JsonValue> {
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos == start { return None; }
        let s = std::str::from_utf8(&self.input[start..self.pos]).ok()?;
        let n: f64 = s.parse().ok()?;
        Some(JsonValue::Number(n))
    }
}

fn parse_json(input: &[u8]) -> Option<JsonValue> {
    let mut p = JsonParser::new(input);
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos != p.input.len() { return None; }
    Some(v)
}

// ============ Base64url ============

fn base64url_decode(s: &str) -> Option<Vec<u8>> {
    for c in s.chars() {
        match c {
            'A'..='Z' | 'a'..='z' | '0'..='9' | '-' | '_' => {}
            _ => return None,
        }
    }
    if s.len() % 4 == 1 { return None; }
    let mut result = Vec::new();
    let mut bits: u32 = 0;
    let mut nbits: u32 = 0;
    for c in s.chars() {
        let v: u32 = match c {
            'A'..='Z' => (c as u32) - 65,
            'a'..='z' => (c as u32) - 97 + 26,
            '0'..='9' => (c as u32) - 48 + 52,
            '-' => 62,
            '_' => 63,
            _ => return None,
        };
        bits = (bits << 6) | v;
        nbits += 6;
        if nbits >= 8 {
            nbits -= 8;
            result.push((bits >> nbits) as u8);
            bits &= (1u32 << nbits) - 1;
        }
    }
    Some(result)
}

