    let textStats = JSONValue.object([
        ("name", .string("text_stats")),
        ("title", .string("Text statistics")),
        ("description", .string("Count the words, Unicode code points and UTF-8 bytes of a text.")),
        ("inputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("text", .object([("type", .string("string"))]))
            ])),
            ("required", .array([.string("text")])),
            ("additionalProperties", .bool(false))
        ])),
        ("outputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("words", .object([("type", .string("integer"))])),
                ("codepoints", .object([("type", .string("integer"))])),
                ("utf8_bytes", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("words"), .string("codepoints"), .string("utf8_bytes")]))
        ])),
        ("annotations", .object([
            ("readOnlyHint", .bool(true))
        ]))
    ])
    return .object([
        ("tools", .array([kv_set, kv_get, kv_list, sumTool, textStats]))
    ])
}

// MARK: - Server State
var initialized = false
var kvStore: [String: String] = [:]

// MARK: - Tool Execution
func executeTool(name: String, arguments: JSONValue?) -> (JSONValue, Bool) {
    // arguments is either nil (absent) or a JSONValue
    let args: JSONValue
    if let a = arguments {
        if case .object = a { args = a }
        else { return (makeToolFailure("arguments must be an object"), true) }
    } else {
        args = .object([])
    }

    let toolDef = toolDefs.first(where: { $0.name == name })!

    // Check unknown arguments
    let knownNames = Set(toolDef.props.map { $0.name })
    var unknownNames: [String] = []
    if case .object(let pairs) = args {
        for (k, _) in pairs {
            if !knownNames.contains(k) { unknownNames.append(k) }
        }
    }
    if !unknownNames.isEmpty {
        unknownNames.sort { compareByCodePoint($0, $1) }
        return (makeToolFailure("unknown argument: \(unknownNames[0])"), true)
    }

    // Validate each property in schema order
    for prop in toolDef.props {
        let val = getObj(args, prop.name)
        if val == nil {
            if prop.required {
                return (makeToolFailure("missing required argument: \(prop.name)"), true)
            }
            continue
        }
        let v = val!
        if prop.type == "string" {
            guard case .string = v else {
                return (makeToolFailure("argument \(prop.name) must be a string"), true)
            }
            if let ml = prop.minLength {
                if case .string(let s) = v, s.count < ml {
                    return (makeToolFailure("argument \(prop.name) must not be empty"), true)
                }
            }
        } else if prop.type == "array_int" {
            guard case .array(let elems) = v else {
                return (makeToolFailure("argument \(prop.name) must be an array of integers"), true)
            }
            for e in elems {
                if case .int = e {} else {
                    return (makeToolFailure("argument \(prop.name) must be an array of integers"), true)
                }
            }
            if let mi = prop.minItems {
                if elems.count < mi {
                    return (makeToolFailure("argument \(prop.name) must not be empty"), true)
                }
            }
        }
    }

    // Execute the tool
    switch name {
    case "kv_set":
        let key = getObj(args, "key")!.stringValue!
        let value = getObj(args, "value")!.stringValue!
        let existed = kvStore[key] != nil
        kvStore[key] = value
        let text = existed ? "updated \(key)" : "created \(key)"
        return (makeToolSuccess(text), false)
    case "kv_get":
        let key = getObj(args, "key")!.stringValue!
        if let val = kvStore[key] {
            return (makeToolSuccess(val), false)
        } else {
            return (makeToolFailure("key not found: \(key)"), true)
        }
    case "kv_list":
        let prefixVal = getObj(args, "prefix")
        let prefix = prefixVal?.stringValue ?? ""
        var keys: [String] = []
        for (k, _) in kvStore {
            if prefix.isEmpty || k.hasPrefix(prefix) { keys.append(k) }
        }
        keys.sort { compareByCodePoint($0, $1) }
        let structured = JSONValue.object([
            ("keys", .array(keys.map { .string($0) })),
            ("count", .int(Int64(keys.count)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    case "sum":
        let nums = getObj(args, "numbers")!
        guard case .array(let elems) = nums else { fatalError() }
        var total: Int64 = 0
        for e in elems {
            if case .int(let i) = e { total += i }
        }
        let structured = JSONValue.object([
            ("sum", .int(total)),
            ("count", .int(Int64(elems.count)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    case "text_stats":
        let text = getObj(args, "text")!.stringValue!
        let words = countWords(text)
        let codepoints = text.unicodeScalars.count
        let utf8Bytes = text.utf8.count
        let structured = JSONValue.object([
            ("words", .int(Int64(words))),
            ("codepoints", .int(Int64(codepoints))),
            ("utf8_bytes", .int(Int64(utf8Bytes)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    default:
        fatalError()
    }
}

func compareByCodePoint(_ a: String, _ b: String) -> Bool {
    let as_ = Array(a.unicodeScalars)
    let bs = Array(b.unicodeScalars)
    let n = min(as_.count, bs.count)
    for i in 0..<n {
        if as_[i].value < bs[i].value { return true }
        if as_[i].value > bs[i].value { return false }
    }
    return as_.count < bs.count
}

func countWords(_ text: String) -> Int {
    var count = 0
    var inWord = false
    for sc in text.unicodeScalars {
        if sc.value == 0x20 || sc.value == 0x09 || sc.value == 0x0A || sc.value == 0x0D {
            inWord = false
        } else {
            if !inWord { count += 1; inWord = true }
        }
    }
    return count
}

func makeToolSuccess(_ text: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("isError", .bool(false))
    ])
}

func makeToolSuccessWithStructured(_ structured: JSONValue) -> JSONValue {
    let text = ser(structured)
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("structuredContent", structured),
        ("isError", .bool(false))
    ])
}

func makeToolFailure(_ msg: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(msg))])])),
        ("isError", .bool(true))
    ])
}

// MARK: - Request Processing
func makeError(_ id: JSONValue?, code: Int, message: String) -> String {
    let idVal: JSONValue = id ?? .null
    return ser(.object([
        ("jsonrpc", .string("2.0")),
        ("id", idVal),
        ("error", .object([("code", .int(Int64(code))), ("message", .string(message))]))
    ]))
}

func makeResult(_ id: JSONValue, result: JSONValue) -> String {
    return ser(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("result", result)
    ]))
}

func processLine(_ line: String) -> String? {
    // Try to parse JSON
    var parser = JSONParser(line)
    guard let json = parser.parse() else {
        return makeError(nil, code: -32700, message: "Parse error")
    }

    // Must be an object
    guard case .object = json else {
        return makeError(nil, code: -32600, message: "Invalid Request")
    }

    // Check if it's a response (no method, has result or error)
    let hasMethod = hasKey(json, "method")
    let hasResult = hasKey(json, "result")
    let hasError = hasKey(json, "error")
    if !hasMethod && (hasResult || hasError) {
        return nil // response from client, ignore
    }

    // Check for invalid request
    let jsonrpcVal = getObj(json, "jsonrpc")
    let methodVal = getObj(json, "method")
    let idVal = hasKey(json, "id") ? getObj(json, "id") : nil
    let idPresent = hasKey(json, "id")

    var invalid = false
    if jsonrpcVal?.stringValue != "2.0" { invalid = true }
    if methodVal == nil || methodVal?.stringValue == nil { invalid = true }
    if idPresent && !isValidId(idVal) { invalid = true }

    if invalid {
        let echoId: JSONValue? = (idPresent && isValidId(idVal)) ? idVal : nil
        return makeError(echoId, code: -32600, message: "Invalid Request")
    }

    // Notification: valid object without id
    if !idPresent {
        return nil
    }

    // It's a request
    let id = idVal!
    let method = methodVal!.stringValue!

    // Check params
    let paramsVal = hasKey(json, "params") ? getObj(json, "params") : nil
    if paramsVal != nil {
        if case .object = paramsVal! {} else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
    }

    // Dispatch
    switch method {
    case "initialize":
        if initialized {
            return makeError(id, code: -32600, message: "Already initialized")
        }
        guard let params = paramsVal, case .object = params else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let pv = getObj(params, "protocolVersion")
        guard case .string(let clientVersion)? = pv else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let validVersions: Set<String> = ["2025-06-18", "2025-03-26", "2024-11-05"]
        let responseVersion = validVersions.contains(clientVersion) ? clientVersion : "2025-06-18"
        initialized = true
        let result = JSONValue.object([
            ("protocolVersion", .string(responseVersion)),
            ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
            ("serverInfo", .object([
                ("name", .string("cb2-kv")),
                ("title", .string("CB2 key-value server")),
                ("version", .string("1.4.2"))
            ]))
        ])
        return makeResult(id, result: result)

    case "ping":
        return makeResult(id, result: .object([]))

    case "tools/list":
        return makeResult(id, result: buildToolsList())

    case "tools/call":
        guard let params = paramsVal, case .object = params else {
            // params missing or not object - but we already checked params is object if present
            // If params is missing entirely, name is missing → invalid params
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let nameVal = getObj(params, "name")
        guard case .string(let toolName)? = nameVal else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let knownTools: Set<String> = ["kv_set", "kv_get", "kv_list", "sum", "text_stats"]
        if !knownTools.contains(toolName) {
            return makeError(id, code: -32602, message: "Unknown tool: \(toolName)")
        }
        let argumentsVal = hasKey(params, "arguments") ? getObj(params, "arguments") : nil
        let (result, _) = executeTool(name: toolName, arguments: argumentsVal)
        return makeResult(id, result: result)

    default:
        return makeError(id, code: -32601, message: "Method not found")
    }
}

// MARK: - Main
var outputLines: [String] = []

while let line = readLine() {
    // Strip trailing \r for CRLF handling
    var trimmed = line
    while trimmed.hasSuffix("\r") { trimmed = String(trimmed.dropLast()) }
    // Check if empty or only whitespace/CR
    var skip = true
    for ch in trimmed {
        if ch != " " && ch != "\t" && ch != "\r" { skip = false; break }
    }
    if skip { continue }

    if let response = processLine(trimmed) {
        outputLines.append(response)
    }
}

for line in outputLines {
    print(line)
}
exit(0)

import Foundation

// MARK: - JSON Value
enum JSONValue {
    case null
    case bool(Bool)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])

    var stringValue: String? {
        if case .string(let s) = self { return s }
        return nil
    }
}

// MARK: - JSON Parser
struct JSONParser {
    let input: [UInt8]
    var pos: Int = 0

    init(_ s: String) {
        input = Array(s.utf8)
    }

    mutating func parse() -> JSONValue? {
        skipWS()
        guard let val = parseValue() else { return nil }
        skipWS()
        if pos != input.count { return nil }
        return val
    }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { pos += 1 } else { break }
        }
    }

    mutating func parseValue() -> JSONValue? {
        guard pos < input.count else { return nil }
        let c = input[pos]
        if c == UInt8(ascii: "{") { return parseObject() }
        if c == UInt8(ascii: "[") { return parseArray() }
        if c == UInt8(ascii: "\"") { return parseString() }
        if c == UInt8(ascii: "t") { return matchLit("true") ? .bool(true) : nil }
        if c == UInt8(ascii: "f") { return matchLit("false") ? .bool(false) : nil }
        if c == UInt8(ascii: "n") { return matchLit("null") ? .null : nil }
        if c == UInt8(ascii: "-") || (c >= UInt8(ascii: "0") && c <= UInt8(ascii: "9")) { return parseNumber() }
        return nil
    }

    mutating func matchLit(_ s: String) -> Bool {
        let bytes = Array(s.utf8)
        if pos + bytes.count > input.count { return false }
        for i in 0..<bytes.count { if input[pos+i] != bytes[i] { return false } }
        pos += bytes.count
        return true
    }

    mutating func parseNumber() -> JSONValue? {
        let start = pos
        var isFloat = false
        if pos < input.count && input[pos] == UInt8(ascii: "-") { pos += 1 }
        if pos >= input.count { return nil }
        if input[pos] == UInt8(ascii: "0") {
            pos += 1
        } else if input[pos] >= UInt8(ascii: "1") && input[pos] <= UInt8(ascii: "9") {
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        } else { return nil }
        if pos < input.count && input[pos] == UInt8(ascii: ".") {
            isFloat = true; pos += 1
            if pos >= input.count || input[pos] < UInt8(ascii: "0") || input[pos] > UInt8(ascii: "9") { return nil }
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        if pos < input.count && (input[pos] == UInt8(ascii: "e") || input[pos] == UInt8(ascii: "E")) {
            isFloat = true; pos += 1
            if pos < input.count && (input[pos] == UInt8(ascii: "+") || input[pos] == UInt8(ascii: "-")) { pos += 1 }
            if pos >= input.count || input[pos] < UInt8(ascii: "0") || input[pos] > UInt8(ascii: "9") { return nil }
            while pos < input.count && input[pos] >= UInt8(ascii: "0") && input[pos] <= UInt8(ascii: "9") { pos += 1 }
        }
        let numStr = String(bytes: input[start..<pos], encoding: .utf8)!
        if isFloat {
            return .double(Double(numStr)!)
        } else {
            if let i = Int64(numStr) { return .int(i) }
            return .double(Double(numStr)!)
        }
    }

    mutating func parseString() -> JSONValue? {
        guard let s = parseRawString() else { return nil }
        return .string(s)
    }

    mutating func parseRawString() -> String? {
        guard pos < input.count && input[pos] == UInt8(ascii: "\"") else { return nil }
        pos += 1
        var bytes: [UInt8] = []
        while pos < input.count {
            let c = input[pos]
            if c == UInt8(ascii: "\"") { pos += 1; return String(bytes: bytes, encoding: .utf8) }
            if c == UInt8(ascii: "\\") {
                pos += 1
                if pos >= input.count { return nil }
                let e = input[pos]
                if e == UInt8(ascii: "\"") { bytes.append(0x22); pos += 1 }
                else if e == UInt8(ascii: "\\") { bytes.append(0x5C); pos += 1 }
                else if e == UInt8(ascii: "/") { bytes.append(0x2F); pos += 1 }
                else if e == UInt8(ascii: "b") { bytes.append(0x08); pos += 1 }
                else if e == UInt8(ascii: "f") { bytes.append(0x0C); pos += 1 }
                else if e == UInt8(ascii: "n") { bytes.append(0x0A); pos += 1 }
                else if e == UInt8(ascii: "r") { bytes.append(0x0D); pos += 1 }
                else if e == UInt8(ascii: "t") { bytes.append(0x09); pos += 1 }
                else if e == UInt8(ascii: "u") {
                    pos += 1
                    guard let cp = parseHex4() else { return nil }
                    if cp >= 0xD800 && cp <= 0xDBFF {
                        if pos+1 >= input.count || input[pos] != UInt8(ascii: "\\") || input[pos+1] != UInt8(ascii: "u") { return nil }
                        pos += 2
                        guard let cp2 = parseHex4() else { return nil }
                        if cp2 < 0xDC00 || cp2 > 0xDFFF { return nil }
                        let combined = 0x10000 + (Int(cp - 0xD800) << 10) + Int(cp2 - 0xDC00)
                        guard let sc = Unicode.Scalar(combined) else { return nil }
                        bytes.append(contentsOf: Array(String(sc).utf8))
                    } else if cp >= 0xDC00 && cp <= 0xDFFF {
                        return nil
                    } else {
                        guard let sc = Unicode.Scalar(cp) else { return nil }
                        bytes.append(contentsOf: Array(String(sc).utf8))
                    }
                } else { return nil }
            } else {
                bytes.append(c); pos += 1
            }
        }
        return nil
    }

    mutating func parseHex4() -> UInt32? {
        guard pos + 4 <= input.count else { return nil }
        var val: UInt32 = 0
        for i in 0..<4 {
            let c = input[pos+i]; val <<= 4
            if c >= UInt8(ascii: "0") && c <= UInt8(ascii: "9") { val |= UInt32(c - UInt8(ascii: "0")) }
            else if c >= UInt8(ascii: "a") && c <= UInt8(ascii: "f") { val |= UInt32(c - UInt8(ascii: "a") + 10) }
            else if c >= UInt8(ascii: "A") && c <= UInt8(ascii: "F") { val |= UInt32(c - UInt8(ascii: "A") + 10) }
            else { return nil }
        }
        pos += 4
        return val
    }

    mutating func parseArray() -> JSONValue? {
        pos += 1; var arr: [JSONValue] = []
        skipWS()
        if pos < input.count && input[pos] == UInt8(ascii: "]") { pos += 1; return .array(arr) }
        while true {
            guard let v = parseValue() else { return nil }
            arr.append(v); skipWS()
            if pos >= input.count { return nil }
            if input[pos] == UInt8(ascii: ",") { pos += 1; skipWS() }
            else if input[pos] == UInt8(ascii: "]") { pos += 1; return .array(arr) }
            else { return nil }
        }
    }

    mutating func parseObject() -> JSONValue? {
        pos += 1; var obj: [(String, JSONValue)] = []
        skipWS()
        if pos < input.count && input[pos] == UInt8(ascii: "}") { pos += 1; return .object(obj) }
        while true {
            skipWS()
            guard let key = parseRawString() else { return nil }
            skipWS()
            if pos >= input.count || input[pos] != UInt8(ascii: ":") { return nil }
            pos += 1; skipWS()
            guard let v = parseValue() else { return nil }
            obj.append((key, v)); skipWS()
            if pos >= input.count { return nil }
            if input[pos] == UInt8(ascii: ",") { pos += 1 }
            else if input[pos] == UInt8(ascii: "}") { pos += 1; return .object(obj) }
            else { return nil }
        }
    }
}

// MARK: - JSON Serializer
func escStr(_ s: String) -> String {
    var r = "\""
    for sc in s.unicodeScalars {
        switch sc {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        case "\u{0008}": r += "\\b"
        case "\u{000C}": r += "\\f"
        default:
            if sc.value < 0x20 { r += String(format: "\\u%04x", sc.value) }
            else { r.unicodeScalars.append(sc) }
        }
    }
    r += "\""
    return r
}

func ser(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool(let b): return b ? "true" : "false"
    case .int(let i): return String(i)
    case .double(let d):
        if d == d.rounded() && abs(d) < 1e15 { return String(Int64(d)) }
        return String(d)
    case .string(let s): return escStr(s)
    case .array(let a): return "[" + a.map{ser($0)}.joined(separator: ",") + "]"
    case .object(let pairs):
        return "{" + pairs.map{ escStr($0.0) + ":" + ser($0.1) }.joined(separator: ",") + "}"
    }
}

// MARK: - Helpers
func getObj(_ v: JSONValue, _ key: String) -> JSONValue? {
    if case .object(let pairs) = v {
        for (k, val) in pairs { if k == key { return val } }
    }
    return nil
}

func hasKey(_ v: JSONValue, _ key: String) -> Bool {
    if case .object(let pairs) = v {
        for (k, _) in pairs { if k == key { return true } }
    }
    return false
}

func isValidId(_ v: JSONValue?) -> Bool {
    guard let v = v else { return false }
    switch v {
    case .string: return true
    case .int: return true
    default: return false
    }
}

// MARK: - Tool Definitions
struct ToolProp {
    let name: String
    let type: String // "string" or "array_int"
    let required: Bool
    let minLength: Int?
    let minItems: Int?
}

struct ToolDef {
    let name: String
    let props: [ToolProp]
    let hasOutputSchema: Bool
}

let toolDefs: [ToolDef] = [
    ToolDef(name: "kv_set", props: [
        ToolProp(name: "key", type: "string", required: true, minLength: 1, minItems: nil),
        ToolProp(name: "value", type: "string", required: true, minLength: nil, minItems: nil)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_get", props: [
        ToolProp(name: "key", type: "string", required: true, minLength: 1, minItems: nil)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_list", props: [
        ToolProp(name: "prefix", type: "string", required: false, minLength: nil, minItems: nil)
    ], hasOutputSchema: true),
    ToolDef(name: "sum", props: [
        ToolProp(name: "numbers", type: "array_int", required: true, minLength: nil, minItems: 1)
    ], hasOutputSchema: true),
    ToolDef(name: "text_stats", props: [
        ToolProp(name: "text", type: "string", required: true, minLength: nil, minItems: nil)
    ], hasOutputSchema: true)
]

