        ("inputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("key", .object([("type", .string("string")), ("minLength", .int(1))])),
                ("value", .object([("type", .string("string"))]))
            ])),
            ("required", .array([.string("key"), .string("value")])),
            ("additionalProperties", .bool(false))
        ]))
    ])
    let kv_get = JSONValue.object([
        ("name", .string("kv_get")),
