            ("type", .string("object")),
            ("properties", .object([
                ("key", .object([("type", .string("string")), ("minLength", .int(1))]))
            ])),
            ("required", .array([.string("key")])),
            ("additionalProperties", .bool(false))
        ]))
    ])
    let kv_list = JSONValue.object([
