            ("additionalProperties", .bool(false))
        ])),
        ("outputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("sum", .object([("type", .string("integer"))])),
                ("count", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("sum"), .string("count")]))
        ])),
        ("annotations", .object([
            ("readOnlyHint", .bool(true)),
            ("idempotentHint", .bool(true))
        ]))
    ])
    let textStats = JSONValue.object([
        ("name", .string("text_stats")),
        ("title", .string("Text statistics")),
        ("description", .string("Count the words, Unicode code points and UTF-8 bytes of a text.")),
        ("inputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("text", .object([("type", .string("string"))]))
            ])),
            ("required", .array([.string("text")])),
            ("additionalProperties", .bool(false))
        ])),
        ("outputSchema", .object([
            ("type", .string("object")),
            ("properties", .object([
                ("words", .object([("type", .string("integer"))])),
                ("codepoints", .object([("type", .string("integer"))])),
                ("utf8_bytes", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("words"), .string("codepoints"), .string("utf8_bytes")]))
        ])),
        ("annotations", .object([
            ("readOnlyHint", .bool(true))
        ]))
    ])
    return .object([
        ("tools", .array([kv_set, kv_get, kv_list, sumTool, textStats]))
    ])
}

// MARK: - Server State
var initialized = false
var kvStore: [String: String] = [:]

// MARK: - Tool Execution
func executeTool(name: String, arguments: JSONValue?) -> (JSONValue, Bool) {
    let args: JSONValue
    if let a = arguments {
        if case .object = a { args = a }
        else { return (makeToolFailure("arguments must be an object"), true) }
    } else {
        args = .object([])
    }

    let toolDef = toolDefs.first(where: { $0.name == name })!

    // Check unknown arguments
    let knownNames = Set(toolDef.props.map { $0.name })
    var unknownNames: [String] = []
    if case .object(let pairs) = args {
        for (k, _) in pairs {
            if !knownNames.contains(k) { unknownNames.append(k) }
        }
    }
    if !unknownNames.isEmpty {
        unknownNames.sort { compareByCodePoint($0, $1) }
        return (makeToolFailure("unknown argument: \(unknownNames[0])"), true)
    }

    // Validate each property in schema order
    for prop in toolDef.props {
        let val = getObj(args, prop.name)
        if val == nil {
            if prop.required {
                return (makeToolFailure("missing required argument: \(prop.name)"), true)
            }
            continue
        }
        let v = val!
        if prop.type == "string" {
            guard case .string(let s) = v else {
                return (makeToolFailure("argument \(prop.name) must be a string"), true)
            }
            if let ml = prop.minLength {
                if s.unicodeScalars.count < ml {
                    return (makeToolFailure("argument \(prop.name) must not be empty"), true)
                }
            }
        } else if prop.type == "array_int" {
            guard case .array(let elems) = v else {
                return (makeToolFailure("argument \(prop.name) must be an array of integers"), true)
            }
            for e in elems {
                if case .int = e {} else {
                    return (makeToolFailure("argument \(prop.name) must be an array of integers"), true)
                }
            }
            if let mi = prop.minItems {
                if elems.count < mi {
                    return (makeToolFailure("argument \(prop.name) must not be empty"), true)
                }
            }
        }
    }

    // Execute the tool
    switch name {
    case "kv_set":
        let key = getObj(args, "key")!.stringValue!
        let value = getObj(args, "value")!.stringValue!
        let existed = kvStore[key] != nil
        kvStore[key] = value
        let text = existed ? "updated \(key)" : "created \(key)"
        return (makeToolSuccess(text), false)
    case "kv_get":
        let key = getObj(args, "key")!.stringValue!
        if let val = kvStore[key] {
            return (makeToolSuccess(val), false)
        } else {
            return (makeToolFailure("key not found: \(key)"), true)
        }
    case "kv_list":
        let prefixVal = getObj(args, "prefix")
        let prefix = prefixVal?.stringValue ?? ""
        var keys: [String] = []
        for (k, _) in kvStore {
            if prefix.isEmpty || k.hasPrefix(prefix) { keys.append(k) }
        }
        keys.sort { compareByCodePoint($0, $1) }
        let structured = JSONValue.object([
            ("keys", .array(keys.map { .string($0) })),
            ("count", .int(Int64(keys.count)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    case "sum":
        let nums = getObj(args, "numbers")!
        guard case .array(let elems) = nums else { fatalError() }
        var total: Int64 = 0
        for e in elems {
            if case .int(let i) = e { total += i }
        }
        let structured = JSONValue.object([
            ("sum", .int(total)),
            ("count", .int(Int64(elems.count)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    case "text_stats":
        let text = getObj(args, "text")!.stringValue!
        let words = countWords(text)
        let codepoints = text.unicodeScalars.count
        let utf8Bytes = text.utf8.count
        let structured = JSONValue.object([
            ("words", .int(Int64(words))),
            ("codepoints", .int(Int64(codepoints))),
            ("utf8_bytes", .int(Int64(utf8Bytes)))
        ])
        return (makeToolSuccessWithStructured(structured), false)
    default:
        fatalError()
    }
}

func compareByCodePoint(_ a: String, _ b: String) -> Bool {
    let as_ = Array(a.unicodeScalars)
    let bs = Array(b.unicodeScalars)
    let n = min(as_.count, bs.count)
    for i in 0..<n {
        if as_[i].value < bs[i].value { return true }
        if as_[i].value > bs[i].value { return false }
    }
    return as_.count < bs.count
}

func countWords(_ text: String) -> Int {
    var count = 0
    var inWord = false
    for sc in text.unicodeScalars {
        if sc.value == 0x20 || sc.value == 0x09 || sc.value == 0x0A || sc.value == 0x0D {
            inWord = false
        } else {
            if !inWord { count += 1; inWord = true }
        }
    }
    return count
}

func makeToolSuccess(_ text: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("isError", .bool(false))
    ])
}

func makeToolSuccessWithStructured(_ structured: JSONValue) -> JSONValue {
    let text = ser(structured)
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("structuredContent", structured),
        ("isError", .bool(false))
    ])
}

func makeToolFailure(_ msg: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(msg))])])),
        ("isError", .bool(true))
    ])
}

// MARK: - Request Processing
func makeError(_ id: JSONValue?, code: Int, message: String) -> String {
    let idVal: JSONValue = id ?? .null
    return ser(.object([
        ("jsonrpc", .string("2.0")),
        ("id", idVal),
        ("error", .object([("code", .int(Int64(code))), ("message", .string(message))]))
    ]))
}

func makeResult(_ id: JSONValue, result: JSONValue) -> String {
    return ser(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("result", result)
    ]))
}

func processLine(_ line: String) -> String? {
    // Try to parse JSON
    var parser = JSONParser(line)
    guard let json = parser.parse() else {
        return makeError(nil, code: -32700, message: "Parse error")
    }

    // Must be an object
    guard case .object = json else {
        return makeError(nil, code: -32600, message: "Invalid Request")
    }

    // Check if it's a response (no method, has result or error)
    let hasMethod = hasKey(json, "method")
    let hasResult = hasKey(json, "result")
    let hasError = hasKey(json, "error")
    if !hasMethod && (hasResult || hasError) {
        return nil // response from client, ignore
    }

    // Check for invalid request
    let jsonrpcVal = getObj(json, "jsonrpc")
    let methodVal = getObj(json, "method")
    let idPresent = hasKey(json, "id")
    let idVal = idPresent ? getObj(json, "id") : nil

    var invalid = false
    if jsonrpcVal?.stringValue != "2.0" { invalid = true }
    if methodVal == nil || methodVal?.stringValue == nil { invalid = true }
    if idPresent && !isValidId(idVal) { invalid = true }

    if invalid {
        let echoId: JSONValue? = (idPresent && isValidId(idVal)) ? idVal : nil
        return makeError(echoId, code: -32600, message: "Invalid Request")
    }

    // Notification: valid object without id
    if !idPresent {
        return nil
    }

    // It's a request
    let id = idVal!
    let method = methodVal!.stringValue!

    // a. Check method is valid
    let validMethods: Set<String> = ["initialize", "ping", "tools/list", "tools/call"]
    if !validMethods.contains(method) {
        return makeError(id, code: -32601, message: "Method not found")
    }

    // b. Check params
    let paramsVal = hasKey(json, "params") ? getObj(json, "params") : nil
    if paramsVal != nil {
        if case .object = paramsVal! {} else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
    }

    // c. Check initialized
    if !initialized && method != "initialize" && method != "ping" {
        return makeError(id, code: -32002, message: "Server not initialized")
    }

    // d. Dispatch
    switch method {
    case "initialize":
        if initialized {
            return makeError(id, code: -32600, message: "Already initialized")
        }
        guard let params = paramsVal, case .object = params else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let pv = getObj(params, "protocolVersion")
        guard case .string(let clientVersion)? = pv else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let validVersions: Set<String> = ["2025-06-18", "2025-03-26", "2024-11-05"]
        let responseVersion = validVersions.contains(clientVersion) ? clientVersion : "2025-06-18"
        initialized = true
        let result = JSONValue.object([
            ("protocolVersion", .string(responseVersion)),
            ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
            ("serverInfo", .object([
                ("name", .string("cb2-kv")),
                ("title", .string("CB2 key-value server")),
                ("version", .string("1.4.2"))
            ]))
        ])
        return makeResult(id, result: result)

    case "ping":
        return makeResult(id, result: .object([]))

    case "tools/list":
        return makeResult(id, result: buildToolsList())

    case "tools/call":
        guard let params = paramsVal, case .object = params else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let nameVal = getObj(params, "name")
        guard case .string(let toolName)? = nameVal else {
            return makeError(id, code: -32602, message: "Invalid params")
        }
        let knownTools: Set<String> = ["kv_set", "kv_get", "kv_list", "sum", "text_stats"]
        if !knownTools.contains(toolName) {
            return makeError(id, code: -32602, message: "Unknown tool: \(toolName)")
        }
        let argumentsVal = hasKey(params, "arguments") ? getObj(params, "arguments") : nil
        let (result, _) = executeTool(name: toolName, arguments: argumentsVal)
        return makeResult(id, result: result)

    default:
        return makeError(id, code: -32601, message: "Method not found")
    }
}

// MARK: - Main
var outputLines: [String] = []

while let line = readLine(strippingNewline: true) {
    // Strip trailing \r for CRLF handling
    var trimmed = line
    while trimmed.hasSuffix("\r") { trimmed = String(trimmed.dropLast()) }
    // Check if empty or only whitespace/CR
    var skip = true
    for ch in trimmed {
        if ch != " " && ch != "\t" && ch != "\r" { skip = false; break }
    }
    if skip { continue }

    if let response = processLine(trimmed) {
        outputLines.append(response)
    }
}

for line in outputLines {
    print(line)
}
exit(0)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <math.h>

/* ============ JSON Value ============ */
enum { JT_NULL, JT_BOOL, JT_STRING, JT_NUMBER, JT_ARRAY, JT_OBJECT };

typedef struct jval {
    int type;
    union {
        int bval;
        char *sval;
        struct { double dval; int is_int; char *raw; } nval;
        struct { struct jval **items; size_t len; } arr;
        struct { char **keys; struct jval **vals; size_t len; } obj;
    };
} jval;

static jval *jval_new(int type) {
    jval *v = (jval *)calloc(1, sizeof(jval));
    v->type = type;
    return v;
}

/* ============ JSON Parser ============ */
static const char *skip_ws(const char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return p;
}

static jval *parse_value(const char **pp);

static char *parse_string_raw(const char **pp) {
    const char *p = *pp;
    if (*p != '"') return NULL;
    p++;
    const char *start = p;
    while (*p && *p != '"') {
        if (*p == '\\') p++;
        p++;
    }
    if (*p != '"') return NULL;
    size_t max_len = (size_t)(p - start) + 1;
    char *buf = (char *)malloc(max_len + 1);
    size_t i = 0;
    p = start;
    while (*p != '"') {
        if (*p == '\\') {
            p++;
            char c = *p++;
            switch (c) {
                case '"': buf[i++] = '"'; break;
                case '\\': buf[i++] = '\\'; break;
                case '/': buf[i++] = '/'; break;
                case 'b': buf[i++] = '\b'; break;
                case 'f': buf[i++] = '\f'; break;
                case 'n': buf[i++] = '\n'; break;
                case 'r': buf[i++] = '\r'; break;
                case 't': buf[i++] = '\t'; break;
                case 'u': {
                    unsigned int cp = 0;
                    for (int j = 0; j < 4; j++) {
                        char h = *p++;
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= (unsigned)(h - '0');
                        else if (h >= 'a' && h <= 'f') cp |= (unsigned)(h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') cp |= (unsigned)(h - 'A' + 10);
                        else { free(buf); return NULL; }
                    }
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (*p == '\\' && *(p+1) == 'u') {
                            p += 2;
                            unsigned int lo = 0;
                            for (int j = 0; j < 4; j++) {
                                char h = *p++;
                                lo <<= 4;
                                if (h >= '0' && h <= '9') lo |= (unsigned)(h - '0');
                                else if (h >= 'a' && h <= 'f') lo |= (unsigned)(h - 'a' + 10);
                                else if (h >= 'A' && h <= 'F') lo |= (unsigned)(h - 'A' + 10);
                                else { free(buf); return NULL; }
                            }
                            if (lo >= 0xDC00 && lo <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            }
                        }
                    }
                    if (cp < 0x80) {
                        buf[i++] = (char)cp;
                    } else if (cp < 0x800) {
                        buf[i++] = (char)(0xC0 | (cp >> 6));
                        buf[i++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        buf[i++] = (char)(0xE0 | (cp >> 12));
                        buf[i++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[i++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        buf[i++] = (char)(0xF0 | (cp >> 18));
                        buf[i++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        buf[i++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[i++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: free(buf); return NULL;
            }
        } else {
            buf[i++] = *p++;
        }
    }
    buf[i] = '\0';
    p++;
    *pp = p;
    return buf;
}

static jval *parse_number(const char **pp) {
    const char *p = *pp;
    const char *start = p;
    int is_int = 1;
    if (*p == '-') p++;
    if (*p == '0') { p++; }
    else if (*p >= '1' && *p <= '9') { while (*p >= '0' && *p <= '9') p++; }
    else return NULL;
    if (*p == '.') { is_int = 0; p++; if (!(*p >= '0' && *p <= '9')) return NULL; while (*p >= '0' && *p <= '9') p++; }
    if (*p == 'e' || *p == 'E') {
        is_int = 0; p++;
        if (*p == '+' || *p == '-') p++;
        if (!(*p >= '0' && *p <= '9')) return NULL;
        while (*p >= '0' && *p <= '9') p++;
    }
    jval *v = jval_new(JT_NUMBER);
    size_t len = (size_t)(p - start);
    v->nval.raw = (char *)malloc(len + 1);
    memcpy(v->nval.raw, start, len);
    v->nval.raw[len] = '\0';
    v->nval.dval = strtod(start, NULL);
    v->nval.is_int = is_int;
    *pp = p;
    return v;
}

static jval *parse_array(const char **pp) {
    const char *p = *pp;
    if (*p != '[') return NULL;
    p++;
    p = skip_ws(p);
    jval *v = jval_new(JT_ARRAY);
    size_t cap = 0;
    if (*p == ']') { p++; *pp = p; return v; }
    while (1) {
        p = skip_ws(p);
        jval *item = parse_value(&p);
        if (!item) { free(v); return NULL; }
        if (v->arr.len >= cap) {
            cap = cap ? cap * 2 : 8;
            v->arr.items = (jval **)realloc(v->arr.items, cap * sizeof(jval *));
        }
        v->arr.items[v->arr.len++] = item;
        p = skip_ws(p);
        if (*p == ',') { p++; continue; }
        if (*p == ']') { p++; break; }
        free(v); return NULL;
    }
    *pp = p;
    return v;
}

static jval *parse_object(const char **pp) {
    const char *p = *pp;
    if (*p != '{') return NULL;
    p++;
    p = skip_ws(p);
    jval *v = jval_new(JT_OBJECT);
    size_t cap = 0;
    if (*p == '}') { p++; *pp = p; return v; }
    while (1) {
        p = skip_ws(p);
        if (*p != '"') { free(v); return NULL; }
        char *key = parse_string_raw(&p);
        if (!key) { free(v); return NULL; }
        p = skip_ws(p);
        if (*p != ':') { free(key); free(v); return NULL; }
        p++;
        p = skip_ws(p);
        jval *val = parse_value(&p);
        if (!val) { free(key); free(v); return NULL; }
        if (v->obj.len >= cap) {
            cap = cap ? cap * 2 : 8;
            v->obj.keys = (char **)realloc(v->obj.keys, cap * sizeof(char *));
            v->obj.vals = (jval **)realloc(v->obj.vals, cap * sizeof(jval *));
        }
        v->obj.keys[v->obj.len] = key;
        v->obj.vals[v->obj.len] = val;
        v->obj.len++;
        p = skip_ws(p);
        if (*p == ',') { p++; continue; }
        if (*p == '}') { p++; break; }
        free(v); return NULL;
    }
    *pp = p;
    return v;
}

static jval *parse_value(const char **pp) {
    const char *p = skip_ws(*pp);
    if (*p == '"') {
        char *s = parse_string_raw(&p);
        if (!s) return NULL;
        jval *v = jval_new(JT_STRING);
        v->sval = s;
        *pp = p;
        return v;
    }
    if (*p == '{') return parse_object(pp);
    if (*p == '[') return parse_array(pp);
    if (*p == 't') {
        if (strncmp(p, "true", 4) == 0) {
            jval *v = jval_new(JT_BOOL); v->bval = 1; *pp = p + 4; return v;
        }
        return NULL;
    }
    if (*p == 'f') {
        if (strncmp(p, "false", 5) == 0) {
            jval *v = jval_new(JT_BOOL); v->bval = 0; *pp = p + 5; return v;
        }
        return NULL;
    }
    if (*p == 'n') {
        if (strncmp(p, "null", 4) == 0) {
            jval *v = jval_new(JT_NULL); *pp = p + 4; return v;
        }
        return NULL;
    }
    if (*p == '-' || (*p >= '0' && *p <= '9')) return parse_number(pp);
    return NULL;
}

static jval *parse_json(const char *s) {
    const char *p = s;
    jval *v = parse_value(&p);
    if (!v) return NULL;
    p = skip_ws(p);
    if (*p != '\0') { free(v); return NULL; }
    return v;
}

/* ============ JSON Output ============ */
static void write_json_string(FILE *f, const char *s) {
    fputc('"', f);
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        if (c == '"') fputs("\\\"", f);
        else if (c == '\\') fputs("\\\\", f);
        else if (c == '\n') fputs("\\n", f);
        else if (c == '\r') fputs("\\r", f);
        else if (c == '\t') fputs("\\t", f);
        else if (c < 0x20) fprintf(f, "\\u%04x", c);
        else fputc(c, f);
    }
    fputc('"', f);
}

static void write_id(FILE *f, jval *id) {
    if (!id) { fputs("null", f); return; }
    if (id->type == JT_STRING) {
        write_json_string(f, id->sval);
    } else if (id->type == JT_NUMBER && id->nval.is_int) {
        fprintf(f, "%lld", (long long)id->nval.dval);
    } else {
        fputs("null", f);
    }
}

static void write_json_val(FILE *f, jval *v);

static void write_json_val(FILE *f, jval *v) {
    if (!v) { fputs("null", f); return; }
    switch (v->type) {
        case JT_NULL: fputs("null", f); break;
        case JT_BOOL: fputs(v->bval ? "true" : "false", f); break;
        case JT_STRING: write_json_string(f, v->sval); break;
        case JT_NUMBER:
            if (v->nval.is_int) fprintf(f, "%lld", (long long)v->nval.dval);
            else fputs(v->nval.raw, f);
            break;
        case JT_ARRAY:
            fputc('[', f);
            for (size_t i = 0; i < v->arr.len; i++) {
                if (i) fputc(',', f);
                write_json_val(f, v->arr.items[i]);
            }
            fputc(']', f);
            break;
        case JT_OBJECT:
            fputc('{', f);
            for (size_t i = 0; i < v->obj.len; i++) {
                if (i) fputc(',', f);
                write_json_string(f, v->obj.keys[i]);
                fputc(':', f);
                write_json_val(f, v->obj.vals[i]);
            }
            fputc('}', f);
            break;
    }
}

/* ============ Object helpers ============ */
static int obj_find(jval *obj, const char *key, jval **out) {
    if (!obj || obj->type != JT_OBJECT) return 0;
    for (size_t i = 0; i < obj->obj.len; i++) {
        if (strcmp(obj->obj.keys[i], key) == 0) {
            *out = obj->obj.vals[i];
            return 1;
        }
    }
    return 0;
}

static jval *obj_get(jval *obj, const char *key) {
    jval *v = NULL;
    obj_find(obj, key, &v);
    return v;
}

/* ============ Key-Value Store ============ */
typedef struct { char *key; char *value; } kv_entry;
static kv_entry *kv_store = NULL;
static size_t kv_count = 0, kv_cap = 0;

static kv_entry *kv_find(const char *key) {
    for (size_t i = 0; i < kv_count; i++) {
        if (strcmp(kv_store[i].key, key) == 0) return &kv_store[i];
    }
    return NULL;
}

static void kv_put(const char *key, const char *value) {
    kv_entry *e = kv_find(key);
    if (e) {
        free(e->value);
        e->value = strdup(value);
    } else {
        if (kv_count >= kv_cap) {
            kv_cap = kv_cap ? kv_cap * 2 : 16;
            kv_store = (kv_entry *)realloc(kv_store, kv_cap * sizeof(kv_entry));
        }
        kv_store[kv_count].key = strdup(key);
        kv_store[kv_count].value = strdup(value);
        kv_count++;
    }
}

/* ============ Server State ============ */
static int server_initialized = 0;

/* ============ Tool Schemas ============ */
enum { PT_STRING, PT_ARRAY_INT };

typedef struct {
    const char *name;
    int ptype;
    int required;
    int minLength;
    int minItems;
} prop_def;

typedef struct {
    const char *name;
    prop_def *props;
    int nprops;
    int has_output_schema;
} tool_def;

static prop_def kv_set_props[] = {
    {"key", PT_STRING, 1, 1, 0},
    {"value", PT_STRING, 1, 0, 0}
};
static prop_def kv_get_props[] = {
    {"key", PT_STRING, 1, 1, 0}
};
static prop_def kv_list_props[] = {
    {"prefix", PT_STRING, 0, 0, 0}
};
static prop_def sum_props[] = {
    {"numbers", PT_ARRAY_INT, 1, 0, 1}
};
static prop_def text_stats_props[] = {
    {"text", PT_STRING, 1, 0, 0}
};

static tool_def tools[] = {
    {"kv_set", kv_set_props, 2, 0},
    {"kv_get", kv_get_props, 1, 0},
    {"kv_list", kv_list_props, 1, 1},
    {"sum", sum_props, 1, 1},
    {"text_stats", text_stats_props, 1, 1}
};
#define NTOOLS 5

/* ============ Text Stats Helpers ============ */
static int count_codepoints(const char *s) {
    int count = 0;
    while (*s) {
        unsigned char c = (unsigned char)*s;
        if (c < 0x80) s += 1;
        else if ((c & 0xE0) == 0xC0) s += 2;
        else if ((c & 0xF0) == 0xE0) s += 3;
        else if ((c & 0xF8) == 0xF0) s += 4;
        else s += 1;
        count++;
    }
    return count;
}

static int count_words(const char *s) {
    int count = 0, in_word = 0;
    while (*s) {
        unsigned char c = (unsigned char)*s;
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            in_word = 0;
        } else {
            if (!in_word) { count++; in_word = 1; }
        }
        s++;
    }
    return count;
}

/* ============ Structured Content Serialization ============ */
static void write_structured_kv_list(FILE *f, char **keys, size_t nkeys) {
    fputs("{\"keys\":[", f);
    for (size_t i = 0; i < nkeys; i++) {
        if (i) fputc(',', f);
        write_json_string(f, keys[i]);
    }
    fprintf(f, "],\"count\":%zu}", nkeys);
}

static void write_structured_sum(FILE *f, long long sum, long long count) {
    fprintf(f, "{\"sum\":%lld,\"count\":%lld}", sum, count);
}

static void write_structured_text_stats(FILE *f, int words, int cp, int bytes) {
    fprintf(f, "{\"words\":%d,\"codepoints\":%d,\"utf8_bytes\":%d}", words, cp, bytes);
}

/* ============ Output Helpers ============ */
static void write_tool_result(FILE *f, jval *id, const char *text, int is_error) {
    fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
    write_id(f, id);
    fputs(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":", f);
    write_json_string(f, text);
    fputs("}],\"isError\":", f);
    fputs(is_error ? "true" : "false", f);
    fputs("}}\n", f);
}

static void write_tool_result_structured(FILE *f, jval *id, const char *text_json) {
    /* text_json is the JSON serialization of the structured object */
    fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
    write_id(f, id);
    fputs(",\"result\":{\"content\":[{\"type\":\"text\",\"text\":", f);
    write_json_string(f, text_json);
    fputs("}],\"structuredContent\":", f);
    fputs(text_json, f);
    fputs(",\"isError\":false}}\n", f);
}

static void write_rpc_error(FILE *f, jval *id, int code, const char *msg) {
    fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
    write_id(f, id);
    fputs(",\"error\":{\"code\":", f);
    fprintf(f, "%d", code);
    fputs(",\"message\":", f);
    write_json_string(f, msg);
    fputs("}}\n", f);
}

/* ============ Tools/Call Implementation ============ */
static void handle_tools_call(FILE *f, jval *id, jval *params) {
    jval *name_v = NULL;
    if (!obj_find(params, "name", &name_v) || !name_v || name_v->type != JT_STRING) {
        write_rpc_error(f, id, -32602, "Invalid params");
        return;
    }
    const char *name = name_v->sval;
    int tool_idx = -1;
    for (int i = 0; i < NTOOLS; i++) {
        if (strcmp(tools[i].name, name) == 0) { tool_idx = i; break; }
    }
    if (tool_idx < 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Unknown tool: %s", name);
        write_rpc_error(f, id, -32602, msg);
        return;
    }
    tool_def *td = &tools[tool_idx];

    /* Get arguments */
    jval *args = NULL;
    int has_args = obj_find(params, "arguments", &args);
    if (has_args && (!args || args->type != JT_OBJECT)) {
        write_tool_result(f, id, "arguments must be an object", 1);
        return;
    }

    /* Check unknown arguments */
    if (has_args && args && args->type == JT_OBJECT) {
        const char *smallest = NULL;
        for (size_t i = 0; i < args->obj.len; i++) {
            int found = 0;
            for (int j = 0; j < td->nprops; j++) {
                if (strcmp(args->obj.keys[i], td->props[j].name) == 0) { found = 1; break; }
            }
            if (!found) {
                if (!smallest || strcmp(args->obj.keys[i], smallest) < 0)
                    smallest = args->obj.keys[i];
            }
        }
        if (smallest) {
            char msg[512];
            snprintf(msg, sizeof(msg), "unknown argument: %s", smallest);
            write_tool_result(f, id, msg, 1);
            return;
        }
    }

    /* Validate properties in order */
    for (int j = 0; j < td->nprops; j++) {
        prop_def *pd = &td->props[j];
        jval *val = NULL;
        int present = has_args && args && obj_find(args, pd->name, &val);
        if (!present) {
            if (pd->required) {
                char msg[256];
                snprintf(msg, sizeof(msg), "missing required argument: %s", pd->name);
                write_tool_result(f, id, msg, 1);
                return;
            }
            continue;
        }
        /* Type check */
        if (pd->ptype == PT_STRING) {
            if (val->type != JT_STRING) {
                char msg[256];
                snprintf(msg, sizeof(msg), "argument %s must be a string", pd->name);
                write_tool_result(f, id, msg, 1);
                return;
            }
        } else if (pd->ptype == PT_ARRAY_INT) {
            if (val->type != JT_ARRAY) {
                char msg[256];
                snprintf(msg, sizeof(msg), "argument %s must be an array of integers", pd->name);
                write_tool_result(f, id, msg, 1);
                return;
            }
            for (size_t k = 0; k < val->arr.len; k++) {
                if (val->arr.items[k]->type != JT_NUMBER || !val->arr.items[k]->nval.is_int) {
                    char msg[256];
                    snprintf(msg, sizeof(msg), "argument %s must be an array of integers", pd->name);
                    write_tool_result(f, id, msg, 1);
                    return;
                }
            }
        }
        /* minLength */
        if (pd->minLength && val->type == JT_STRING && strlen(val->sval) < (size_t)pd->minLength) {
            char msg[256];
            snprintf(msg, sizeof(msg), "argument %s must not be empty", pd->name);
            write_tool_result(f, id, msg, 1);
            return;
        }
        /* minItems */
        if (pd->minItems && val->type == JT_ARRAY && val->arr.len < (size_t)pd->minItems) {
            char msg[256];
            snprintf(msg, sizeof(msg), "argument %s must not be empty", pd->name);
            write_tool_result(f, id, msg, 1);
            return;
        }
    }

    /* Execute tool */
    if (tool_idx == 0) { /* kv_set */
        jval *kv = NULL, *vv = NULL;
        obj_find(args, "key", &kv);
        obj_find(args, "value", &vv);
        const char *key = kv->sval;
        const char *value = vv->sval;
        int existed = kv_find(key) != NULL;
        kv_put(key, value);
        char msg[1024];
        snprintf(msg, sizeof(msg), "%s %s", existed ? "updated" : "created", key);
        write_tool_result(f, id, msg, 0);
    } else if (tool_idx == 1) { /* kv_get */
        jval *kv = NULL;
        obj_find(args, "key", &kv);
        const char *key = kv->sval;
        kv_entry *e = kv_find(key);
        if (!e) {
            char msg[1024];
            snprintf(msg, sizeof(msg), "key not found: %s", key);
            write_tool_result(f, id, msg, 1);
        } else {
            write_tool_result(f, id, e->value, 0);
        }
    } else if (tool_idx == 2) { /* kv_list */
        jval *pv = NULL;
        const char *prefix = "";
        if (has_args && args && obj_find(args, "prefix", &pv) && pv && pv->type == JT_STRING)
            prefix = pv->sval;
        size_t plen = strlen(prefix);
        /* Collect matching keys */
        char **keys = NULL;
        size_t nk = 0, kcap = 0;
        for (size_t i = 0; i < kv_count; i++) {
            if (strncmp(kv_store[i].key, prefix, plen) == 0) {
                if (nk >= kcap) { kcap = kcap ? kcap * 2 : 8; keys = (char **)realloc(keys, kcap * sizeof(char *)); }
                keys[nk++] = kv_store[i].key;
            }
        }
        /* Sort by code point (strcmp on UTF-8 preserves code point order) */
        for (size_t i = 0; i < nk; i++) {
            for (size_t j = i + 1; j < nk; j++) {
                if (strcmp(keys[i], keys[j]) > 0) {
                    char *tmp = keys[i]; keys[i] = keys[j]; keys[j] = tmp;
                }
            }
        }
        /* Build structured content JSON */
        char buf[65536];
        int pos = 0;
        pos += snprintf(buf + pos, sizeof(buf) - (size_t)pos, "{\"keys\":[");
        for (size_t i = 0; i < nk; i++) {
            if (i) pos += snprintf(buf + pos, sizeof(buf) - (size_t)pos, ",");
            pos += snprintf(buf + pos, sizeof(buf) - (size_t)pos, "\"");
            /* escape key */
            for (const char *s = keys[i]; *s; s++) {
                unsigned char c = (unsigned char)*s;
                if (c == '"') { buf[pos++] = '\\'; buf[pos++] = '"'; }
                else if (c == '\\') { buf[pos++] = '\\'; buf[pos++] = '\\'; }
                else if (c == '\n') { buf[pos++] = '\\'; buf[pos++] = 'n'; }
                else if (c == '\r') { buf[pos++] = '\\'; buf[pos++] = 'r'; }
                else if (c == '\t') { buf[pos++] = '\\'; buf[pos++] = 't'; }
                else if (c < 0x20) { pos += snprintf(buf + pos, sizeof(buf) - (size_t)pos, "\\u%04x", c); }
                else buf[pos++] = (char)c;
            }
            buf[pos++] = '"';
        }
        pos += snprintf(buf + pos, sizeof(buf) - (size_t)pos, "],\"count\":%zu}", nk);
        buf[pos] = '\0';
        write_tool_result_structured(f, id, buf);
        free(keys);
    } else if (tool_idx == 3) { /* sum */
        jval *nv = NULL;
        obj_find(args, "numbers", &nv);
        long long total = 0;
        long long cnt = (long long)nv->arr.len;
        for (size_t i = 0; i < nv->arr.len; i++) {
            total += (long long)nv->arr.items[i]->nval.dval;
        }
        char buf[256];
        snprintf(buf, sizeof(buf), "{\"sum\":%lld,\"count\":%lld}", total, cnt);
        write_tool_result_structured(f, id, buf);
    } else if (tool_idx == 4) { /* text_stats */
        jval *tv = NULL;
        obj_find(args, "text", &tv);
        const char *text = tv->sval;
        int words = count_words(text);
        int cp = count_codepoints(text);
        int bytes = (int)strlen(text);
        char buf[256];
        snprintf(buf, sizeof(buf), "{\"words\":%d,\"codepoints\":%d,\"utf8_bytes\":%d}", words, cp, bytes);
        write_tool_result_structured(f, id, buf);
    }
}

/* ============ Tools/List ============ */
static void handle_tools_list(FILE *f, jval *id) {
    fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
    write_id(f, id);
    fputs(",\"result\":{\"tools\":[", f);
    /* kv_set */
    fputs("{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}}", f);
    fputs(",", f);
    /* kv_get */
    fputs("{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}}", f);
    fputs(",", f);
    /* kv_list */
    fputs("{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}}", f);
    fputs(",", f);
    /* sum */
    fputs("{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}}", f);
    fputs(",", f);
    /* text_stats */
    fputs("{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}", f);
    fputs("]}}\n", f);
}

/* ============ Initialize ============ */
static void handle_initialize(FILE *f, jval *id, jval *params) {
    if (server_initialized) {
        write_rpc_error(f, id, -32600, "Already initialized");
        return;
    }
    if (!params) {
        write_rpc_error(f, id, -32602, "Invalid params");
        return;
    }
    jval *pv = NULL;
    if (!obj_find(params, "protocolVersion", &pv) || !pv || pv->type != JT_STRING) {
        write_rpc_error(f, id, -32602, "Invalid params");
        return;
    }
    server_initialized = 1;
    const char *ver = pv->sval;
    const char *out_ver = "2025-06-18";
    if (strcmp(ver, "2025-06-18") == 0 || strcmp(ver, "2025-03-26") == 0 || strcmp(ver, "2024-11-05") == 0)
        out_ver = ver;
    fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
    write_id(f, id);
    fputs(",\"result\":{\"protocolVersion\":", f);
    write_json_string(f, out_ver);
    fputs(",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n", f);
}

/* ============ Request Dispatch ============ */
static void handle_request(FILE *f, jval *msg) {
    jval *id = NULL;
    int has_id = obj_find(msg, "id", &id);

    jval *method_v = NULL;
    if (!obj_find(msg, "method", &method_v) || !method_v || method_v->type != JT_STRING) {
        /* Should not reach here (caught earlier), but just in case */
        write_rpc_error(f, NULL, -32600, "Invalid Request");
        return;
    }
    const char *method = method_v->sval;

    jval *params = NULL;
    int has_params = obj_find(msg, "params", &params);
    if (has_params && params && params->type != JT_OBJECT) {
        write_rpc_error(f, id, -32602, "Invalid params");
        return;
    }
    if (!has_params) params = NULL;

    /* Check method */
    if (strcmp(method, "initialize") != 0 &&
        strcmp(method, "ping") != 0 &&
        strcmp(method, "tools/list") != 0 &&
        strcmp(method, "tools/call") != 0) {
        write_rpc_error(f, id, -32601, "Method not found");
        return;
    }

    /* Check initialized */
    if (!server_initialized && strcmp(method, "initialize") != 0 && strcmp(method, "ping") != 0) {
        write_rpc_error(f, id, -32002, "Server not initialized");
        return;
    }

    /* Dispatch */
    if (strcmp(method, "initialize") == 0) {
        handle_initialize(f, id, params);
    } else if (strcmp(method, "ping") == 0) {
        fputs("{\"jsonrpc\":\"2.0\",\"id\":", f);
        write_id(f, id);
        fputs(",\"result\":{}}\n", f);
    } else if (strcmp(method, "tools/list") == 0) {
        handle_tools_list(f, id);
    } else if (strcmp(method, "tools/call") == 0) {
        handle_tools_call(f, id, params);
    }
}

/* ============ Main ============ */
int main(void) {
    char *line = NULL;
    size_t bufsize = 0;
    ssize_t nread;

    while ((nread = getline(&line, &bufsize, stdin)) != -1) {
        /* Strip trailing CR and LF */
        while (nread > 0 && (line[nread-1] == '\n' || line[nread-1] == '\r')) nread--;
        line[nread] = '\0';

        /* Check if line is empty or only whitespace */
        int all_ws = 1;
        for (ssize_t i = 0; i < nread; i++) {
            if (line[i] != ' ' && line[i] != '\t' && line[i] != '\r') { all_ws = 0; break; }
        }
        if (all_ws) continue;

        /* Parse JSON */
        jval *msg = parse_json(line);
        if (!msg) {
            fputs("{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32700,\"message\":\"Parse error\"}}\n", stdout);
            continue;
        }

        /* Rule 2: must be object */
        if (msg->type != JT_OBJECT) {
            fputs("{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n", stdout);
            free(msg);
            continue;
        }

        /* Rule 3: response from client (no method, has result or error) */
        jval *method_v = NULL;
        int has_method = obj_find(msg, "method", &method_v);
        if (!has_method) {
            jval *result_v = NULL, *error_v = NULL;
            if (obj_find(msg, "result", &result_v) || obj_find(msg, "error", &error_v)) {
                free(msg);
                continue; /* ignore response */
            }
        }

        /* Rule 4: invalid request checks */
        {
            jval *jsonrpc_v = NULL;
            int has_jsonrpc = obj_find(msg, "jsonrpc", &jsonrpc_v);
            int jsonrpc_ok = has_jsonrpc && jsonrpc_v && jsonrpc_v->type == JT_STRING && strcmp(jsonrpc_v->sval, "2.0") == 0;

            int method_ok = has_method && method_v && method_v->type == JT_STRING;

            jval *id_v = NULL;
            int has_id = obj_find(msg, "id", &id_v);
            int id_ok = 1; /* if no id member, it's fine (will be notification) */
            if (has_id) {
                if (!id_v) id_ok = 0;
                else if (id_v->type == JT_STRING) id_ok = 1;
                else if (id_v->type == JT_NUMBER && id_v->nval.is_int) id_ok = 1;
                else id_ok = 0;
            }

            if (!jsonrpc_ok || !method_ok || !id_ok) {
                /* Invalid request */
                jval *out_id = NULL;
                if (has_id && id_ok) out_id = id_v;
                fputs("{\"jsonrpc\":\"2.0\",\"id\":", stdout);
                write_id(stdout, out_id);
                fputs(",\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n", stdout);
                free(msg);
                continue;
            }
        }

        /* Rule 5: notification (no id) */
        {
            jval *id_v = NULL;
            int has_id = obj_find(msg, "id", &id_v);
            if (!has_id) {
                free(msg);
                continue;
            }
        }

        /* Rule 6: request */
        handle_request(stdout, msg);
        free(msg);
    }

    free(line);
    return 0;
}

use std::io::{self, BufRead, Write};
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(ref members) = self {
            members.iter().find(|(k, _)| k == key).map(|(_, v)| v)
        } else {
            None
        }
    }
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { input: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b't') => self.parse_lit(b"true", JsonValue::Bool(true)),
            Some(b'f') => self.parse_lit(b"false", JsonValue::Bool(false)),
            Some(b'n') => self.parse_lit(b"null", JsonValue::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err("unexpected".to_string()),
        }
    }

    fn parse_lit(&mut self, expected: &[u8], val: JsonValue) -> Result<JsonValue, String> {
        if self.input[self.pos..].starts_with(expected) {
            self.pos += expected.len();
            Ok(val)
        } else {
            Err("invalid literal".to_string())
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.input.len() {
                return Err("unterminated string".to_string());
            }
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                return Ok(result);
            }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() {
                    return Err("unterminated escape".to_string());
                }
                let e = self.input[self.pos];
                self.pos += 1;
                match e {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4()?;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.input.len()
                                && self.input[self.pos] == b'\\'
                                && self.input[self.pos + 1] == b'u'
                            {
                                self.pos += 2;
                                let cp2 = self.parse_hex4()?;
                                if cp2 >= 0xDC00 && cp2 <= 0xDFFF {
                                    let combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                    result.push(char::from_u32(combined).ok_or("bad surrogate")?);
                                } else {
                                    return Err("bad surrogate pair".to_string());
                                }
                            } else {
                                return Err("unpaired surrogate".to_string());
                            }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            return Err("unpaired low surrogate".to_string());
                        } else {
                            result.push(char::from_u32(cp).ok_or("invalid codepoint")?);
                        }
                    }
                    _ => return Err("invalid escape".to_string()),
                }
            } else if c < 0x20 {
                return Err("control char in string".to_string());
            } else {
                let start = self.pos;
                let len = if c < 0x80 { 1 } else if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
                self.pos += len;
                if self.pos > self.input.len() {
                    return Err("truncated utf8".to_string());
                }
                let s = std::str::from_utf8(&self.input[start..self.pos])
                    .map_err(|_| "invalid utf8".to_string())?;
                result.push_str(s);
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.input.len() {
            return Err("incomplete \\u".to_string());
        }
        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4])
            .map_err(|_| "bad hex".to_string())?;
        self.pos += 4;
        u32::from_str_radix(hex, 16).map_err(|_| "bad hex".to_string())
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        let mut is_int = true;

        if self.peek() == Some(b'-') { self.pos += 1; }

        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        } else {
            return Err("invalid number".to_string());
        }

        if self.peek() == Some(b'.') {
            is_int = false;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("invalid number".to_string());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }

        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_int = false;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("invalid number".to_string());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }

        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "bad number".to_string())?;
        if is_int {
            match s.parse::<i64>() {
                Ok(v) => Ok(JsonValue::Int(v)),
                Err(_) => {
                    let v: f64 = s.parse().map_err(|_| "bad number".to_string())?;
                    Ok(JsonValue::Float(v))
                }
            }
        } else {
            let v: f64 = s.parse().map_err(|_| "bad number".to_string())?;
            Ok(JsonValue::Float(v))
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err("expected key".to_string()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err("expected ':'".to_string()); }
            self.pos += 1;
            let val = self.parse_value()?;
            members.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(members)); }
                _ => return Err("expected , or }".to_string()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err("expected , or ]".to_string()),
            }
        }
    }

    fn parse_complete(&mut self) -> Result<JsonValue, String> {
        let v = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.input.len() {
            return Err("trailing".to_string());
        }
        Ok(v)
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut p = Parser::new(s);
    p.parse_complete()
}

fn ser(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Int(i) => i.to_string(),
        JsonValue::Float(f) => {
            if *f == f.floor() && f.abs() < 1e15 {
                format!("{}", *f as i64)
            } else {
                format!("{}", f)
            }
        }
        JsonValue::Str(s) => ser_str(s),
        JsonValue::Array(items) => {
            let parts: Vec<String> = items.iter().map(ser).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Object(members) => {
            let parts: Vec<String> = members.iter().map(|(k, v)| {
                format!("{}:{}", ser_str(k), ser(v))
            }).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn ser_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                r.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn is_valid_id(v: &JsonValue) -> bool {
    match v {
        JsonValue::Str(_) => true,
        JsonValue::Int(_) => true,
        _ => false,
    }
}

fn obj(pairs: Vec<(&str, JsonValue)>) -> JsonValue {
    JsonValue::Object(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}

fn arr(items: Vec<JsonValue>) -> JsonValue {
    JsonValue::Array(items)
}

fn str_val(s: &str) -> JsonValue {
    JsonValue::Str(s.to_string())
}

fn int_val(i: i64) -> JsonValue {
    JsonValue::Int(i)
}

fn bool_val(b: bool) -> JsonValue {
    JsonValue::Bool(b)
}

fn error_response(id: JsonValue, code: i64, msg: &str) -> String {
    let resp = obj(vec![
        ("jsonrpc", str_val("2.0")),
        ("id", id),
        ("error", obj(vec![
            ("code", int_val(code)),
            ("message", str_val(msg)),
        ])),
    ]);
    ser(&resp)
}

fn result_response(id: JsonValue, result: JsonValue) -> String {
    let resp = obj(vec![
        ("jsonrpc", str_val("2.0")),
        ("id", id),
        ("result", result),
    ]);
    ser(&resp)
}

