struct McpServer {
    initialized: bool,
    store: HashMap<String, String>,
}

impl McpServer {
    fn new() -> Self {
        McpServer { initialized: false, store: HashMap::new() }
    }

    fn handle(&mut self, id: &JsonValue, method: &str, params: Option<&JsonValue>) -> String {
        // Step 6a: method not recognized
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            return error_response(id.clone(), -32601, "Method not found");
        }

        // Step 6b: params present but not an object
        if let Some(p) = params {
            if !matches!(p, JsonValue::Object(_)) {
                return error_response(id.clone(), -32602, "Invalid params");
            }
        }

        // Step 6c: not initialized and method is not initialize or ping
        if !self.initialized && method != "initialize" && method != "ping" {
            return error_response(id.clone(), -32002, "Server not initialized");
        }

        // Step 6d: dispatch
        match method {
            "initialize" => self.handle_initialize(id, params),
            "ping" => result_response(id.clone(), obj(vec![])),
            "tools/list" => result_response(id.clone(), tools_list_result()),
            "tools/call" => self.handle_tools_call(id, params),
            _ => unreachable!(),
        }
    }

    fn handle_initialize(&mut self, id: &JsonValue, params: Option<&JsonValue>) -> String {
        if self.initialized {
            return error_response(id.clone(), -32600, "Already initialized");
        }
        let p = match params {
            Some(JsonValue::Object(_)) => params.unwrap(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        let pv = match p.get("protocolVersion") {
            Some(JsonValue::Str(s)) => s.clone(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        self.initialized = true;
        let version = if pv == "2025-06-18" || pv == "2025-03-26" || pv == "2024-11-05" {
            pv
        } else {
            "2025-06-18".to_string()
        };
        let result = obj(vec![
            ("protocolVersion", str_val(&version)),
            ("capabilities", obj(vec![
                ("tools", obj(vec![("listChanged", bool_val(false))])),
            ])),
            ("serverInfo", obj(vec![
                ("name", str_val("cb2-kv")),
                ("title", str_val("CB2 key-value server")),
                ("version", str_val("1.4.2")),
            ])),
        ]);
        result_response(id.clone(), result)
    }

    fn handle_tools_call(&mut self, id: &JsonValue, params: Option<&JsonValue>) -> String {
        let p = match params {
            Some(JsonValue::Object(_)) => params.unwrap(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        let name = match p.get("name") {
            Some(JsonValue::Str(s)) => s.clone(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };

        let tools = get_tools();
        let tool = match tools.iter().find(|t| t.name == name) {
            Some(t) => t,
            None => return error_response(id.clone(), -32602, &format!("Unknown tool: {}", name)),
        };

        // Validate arguments
        let arguments: Vec<(String, JsonValue)> = match p.get("arguments") {
            None => vec![],
            Some(JsonValue::Object(members)) => members.clone(),
            Some(_) => {
                return result_response(id.clone(), tool_failure("arguments must be an object"));
            }
        };

        // Check unknown arguments
        let valid_names: Vec<&str> = tool.props.iter().map(|p| p.name).collect();
        let mut unknown: Vec<String> = vec![];
        for (k, _) in &arguments {
            if !valid_names.contains(&k.as_str()) {
                unknown.push(k.clone());
            }
        }
        if !unknown.is_empty() {
            unknown.sort();
            return result_response(id.clone(), tool_failure(&format!("unknown argument: {}", unknown[0])));
        }

        // Check each property in schema order
        for prop in &tool.props {
            let arg_val = arguments.iter().find(|(k, _)| k == prop.name).map(|(_, v)| v);
            match arg_val {
                None => {
                    if prop.required {
                        return result_response(id.clone(), tool_failure(&format!("missing required argument: {}", prop.name)));
                    }
                }
                Some(v) => {
                    match prop.ptype {
                        PropType::String => {
                            if !matches!(v, JsonValue::Str(_)) {
                                return result_response(id.clone(), tool_failure(&format!("argument {} must be a string", prop.name)));
                            }
                            if let Some(ml) = prop.min_length {
                                if let JsonValue::Str(s) = v {
                                    if s.is_empty() && ml > 0 {
                                        return result_response(id.clone(), tool_failure(&format!("argument {} must not be empty", prop.name)));
                                    }
                                }
                            }
                        }
                        PropType::ArrayOfIntegers => {
                            match v {
                                JsonValue::Array(items) => {
                                    for item in items {
                                        if !matches!(item, JsonValue::Int(_)) {
                                            return result_response(id.clone(), tool_failure(&format!("argument {} must be an array of integers", prop.name)));
                                        }
                                    }
                                    if let Some(mi) = prop.min_items {
                                        if items.is_empty() && mi > 0 {
                                            return result_response(id.clone(), tool_failure(&format!("argument {} must not be empty", prop.name)));
                                        }
                                    }
                                }
                                _ => {
                                    return result_response(id.clone(), tool_failure(&format!("argument {} must be an array of integers", prop.name)));
                                }
                            }
                        }
                    }
                }
            }
        }

        // Execute tool
        self.execute_tool(id, tool, &arguments)
    }

    fn execute_tool(&mut self, id: &JsonValue, tool: &ToolDef, arguments: &[(String, JsonValue)]) -> String {
        let get_str = |name: &str| -> Option<String> {
            arguments.iter().find(|(k, _)| k == name).and_then(|(_, v)| {
                if let JsonValue::Str(s) = v { Some(s.clone()) } else { None }
            })
        };

        match tool.name {
            "kv_set" => {
                let key = get_str("key").unwrap();
                let value = get_str("value").unwrap();
                let existed = self.store.contains_key(&key);
                self.store.insert(key.clone(), value);
                let text = if existed { format!("updated {}", key) } else { format!("created {}", key) };
                result_response(id.clone(), tool_success(text, None))
            }
            "kv_get" => {
                let key = get_str("key").unwrap();
                match self.store.get(&key) {
                    Some(val) => result_response(id.clone(), tool_success(val.clone(), None)),
                    None => result_response(id.clone(), tool_failure(&format!("key not found: {}", key))),
                }
            }
            "kv_list" => {
                let prefix = get_str("prefix").unwrap_or_default();
                let mut keys: Vec<String> = self.store.keys()
                    .filter(|k| k.starts_with(&prefix))
                    .cloned()
                    .collect();
                keys.sort();
                let count = keys.len() as i64;
                let structured = obj(vec![
                    ("keys", arr(keys.into_iter().map(str_val).collect())),
                    ("count", int_val(count)),
                ]);
                let text = ser(&structured);
                result_response(id.clone(), tool_success(text, Some(structured)))
            }
            "sum" => {
                let numbers: Vec<i64> = arguments.iter().find(|(k, _)| k == "numbers")
                    .and_then(|(_, v)| if let JsonValue::Array(items) = v {
                        Some(items.iter().filter_map(|item| if let JsonValue::Int(i) = item { Some(*i) } else { None }).collect())
                    } else { None })
                    .unwrap_or_default();
                let s: i64 = numbers.iter().sum();
                let count = numbers.len() as i64;
                let structured = obj(vec![
                    ("sum", int_val(s)),
                    ("count", int_val(count)),
                ]);
                let text = ser(&structured);
                result_response(id.clone(), tool_success(text, Some(structured)))
            }
            "text_stats" => {
                let text = get_str("text").unwrap();
                let words = text.split(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r')
                    .filter(|s| !s.is_empty())
                    .count() as i64;
                let codepoints = text.chars().count() as i64;
                let utf8_bytes = text.len() as i64;
                let structured = obj(vec![
                    ("words", int_val(words)),
                    ("codepoints", int_val(codepoints)),
                    ("utf8_bytes", int_val(utf8_bytes)),
                ]);
                let text_json = ser(&structured);
                result_response(id.clone(), tool_success(text_json, Some(structured)))
            }
            _ => unreachable!(),
        }
    }
}

fn tool_success(text: String, structured: Option<JsonValue>) -> JsonValue {
    let mut pairs = vec![
        ("content", arr(vec![
            obj(vec![
                ("type", str_val("text")),
                ("text", str_val(&text)),
            ]),
        ])),
    ];
    if let Some(sc) = structured {
        pairs.push(("structuredContent", sc));
    }
    pairs.push(("isError", bool_val(false)));
    obj(pairs)
}

fn tool_failure(text: &str) -> JsonValue {
    obj(vec![
        ("content", arr(vec![
            obj(vec![
                ("type", str_val("text")),
                ("text", str_val(text)),
            ]),
        ])),
        ("isError", bool_val(true)),
    ])
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut server = McpServer::new();

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        // Check if line is empty or only whitespace/CR
        if line.trim().is_empty() {
            continue;
        }

        // Rule 1: parse JSON
        let parsed = match parse_json(&line) {
            Ok(v) => v,
            Err(_) => {
                let resp = error_response(JsonValue::Null, -32700, "Parse error");
                let _ = writeln!(out, "{}", resp);
                continue;
            }
        };

        // Rule 2: must be object
        let obj_members = match &parsed {
            JsonValue::Object(m) => m,
            _ => {
                let resp = error_response(JsonValue::Null, -32600, "Invalid Request");
                let _ = writeln!(out, "{}", resp);
                continue;
            }
        };

        // Rule 3: response from client (no method, has result or error)
        let has_method = obj_members.iter().any(|(k, _)| k == "method");
        let has_result = obj_members.iter().any(|(k, _)| k == "result");
        let has_error = obj_members.iter().any(|(k, _)| k == "error");
        if !has_method && (has_result || has_error) {
            continue;
        }

        // Rule 4: invalid request check
        let jsonrpc_val = obj_members.iter().find(|(k, _)| k == "jsonrpc").map(|(_, v)| v);
        let method_val = obj_members.iter().find(|(k, _)| k == "method").map(|(_, v)| v);
        let id_member = obj_members.iter().find(|(k, _)| k == "id");

        let jsonrpc_ok = match jsonrpc_val {
            Some(JsonValue::Str(s)) => s == "2.0",
            _ => false,
        };
        let method_ok = match method_val {
            Some(JsonValue::Str(_)) => true,
            _ => false,
        };
        let id_ok = match id_member {
            Some((_, v)) => is_valid_id(v),
            None => true, // no id member is OK for this check
        };

        if !jsonrpc_ok || !method_ok || !id_ok {
            let id = match id_member {
                Some((_, v)) if is_valid_id(v) => v.clone(),
                _ => JsonValue::Null,
            };
            let resp = error_response(id, -32600, "Invalid Request");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        // Rule 5: notification (no id)
        let id = match id_member {
            Some((_, v)) => v.clone(),
            None => continue, // notification, ignore
        };

        // Rule 6: request
        let method = match method_val {
            Some(JsonValue::Str(s)) => s.as_str(),
            _ => unreachable!(),
        };
        let params = obj_members.iter().find(|(k, _)| k == "params").map(|(_, v)| v);

        let resp = server.handle(&id, method, params);
        let _ = writeln!(out, "{}", resp);
    }

    let _ = out.flush();
}

use std::io::{self, BufRead, Write};
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(ref members) = self {
            members.iter().find(|(k, _)| k == key).map(|(_, v)| v)
        } else {
            None
        }
    }
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { input: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b't') => self.parse_lit(b"true", JsonValue::Bool(true)),
            Some(b'f') => self.parse_lit(b"false", JsonValue::Bool(false)),
            Some(b'n') => self.parse_lit(b"null", JsonValue::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err("unexpected".to_string()),
        }
    }

    fn parse_lit(&mut self, expected: &[u8], val: JsonValue) -> Result<JsonValue, String> {
        if self.input[self.pos..].starts_with(expected) {
            self.pos += expected.len();
            Ok(val)
        } else {
            Err("invalid literal".to_string())
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1;
        let mut result = String::new();
        loop {
            if self.pos >= self.input.len() {
                return Err("unterminated string".to_string());
            }
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                return Ok(result);
            }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() {
                    return Err("unterminated escape".to_string());
                }
                let e = self.input[self.pos];
                self.pos += 1;
                match e {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4()?;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.input.len()
                                && self.input[self.pos] == b'\\'
                                && self.input[self.pos + 1] == b'u'
                            {
                                self.pos += 2;
                                let cp2 = self.parse_hex4()?;
                                if cp2 >= 0xDC00 && cp2 <= 0xDFFF {
                                    let combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                    result.push(char::from_u32(combined).ok_or("bad surrogate")?);
                                } else {
                                    return Err("bad surrogate pair".to_string());
                                }
                            } else {
                                return Err("unpaired surrogate".to_string());
                            }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            return Err("unpaired low surrogate".to_string());
                        } else {
                            result.push(char::from_u32(cp).ok_or("invalid codepoint")?);
                        }
                    }
                    _ => return Err("invalid escape".to_string()),
                }
            } else if c < 0x20 {
                return Err("control char in string".to_string());
            } else {
                let start = self.pos;
                let len = if c < 0x80 { 1 } else if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
                self.pos += len;
                if self.pos > self.input.len() {
                    return Err("truncated utf8".to_string());
                }
                let s = std::str::from_utf8(&self.input[start..self.pos])
                    .map_err(|_| "invalid utf8".to_string())?;
                result.push_str(s);
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.input.len() {
            return Err("incomplete \\u".to_string());
        }
        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4])
            .map_err(|_| "bad hex".to_string())?;
        self.pos += 4;
        u32::from_str_radix(hex, 16).map_err(|_| "bad hex".to_string())
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        let mut is_int = true;

        if self.peek() == Some(b'-') { self.pos += 1; }

        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        } else {
            return Err("invalid number".to_string());
        }

        if self.peek() == Some(b'.') {
            is_int = false;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("invalid number".to_string());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }

        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_int = false;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) {
                return Err("invalid number".to_string());
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }

        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "bad number".to_string())?;
        if is_int {
            match s.parse::<i64>() {
                Ok(v) => Ok(JsonValue::Int(v)),
                Err(_) => {
                    let v: f64 = s.parse().map_err(|_| "bad number".to_string())?;
                    Ok(JsonValue::Float(v))
                }
            }
        } else {
            let v: f64 = s.parse().map_err(|_| "bad number".to_string())?;
            Ok(JsonValue::Float(v))
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err("expected key".to_string()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err("expected ':'".to_string()); }
            self.pos += 1;
            let val = self.parse_value()?;
            members.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(members)); }
                _ => return Err("expected , or }".to_string()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err("expected , or ]".to_string()),
            }
        }
    }

    fn parse_complete(&mut self) -> Result<JsonValue, String> {
        let v = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.input.len() {
            return Err("trailing".to_string());
        }
        Ok(v)
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut p = Parser::new(s);
    p.parse_complete()
}

fn ser(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Int(i) => i.to_string(),
        JsonValue::Float(f) => {
            if *f == f.floor() && f.abs() < 1e15 {
                format!("{}", *f as i64)
            } else {
                format!("{}", f)
            }
        }
        JsonValue::Str(s) => ser_str(s),
        JsonValue::Array(items) => {
            let parts: Vec<String> = items.iter().map(ser).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Object(members) => {
            let parts: Vec<String> = members.iter().map(|(k, v)| {
                format!("{}:{}", ser_str(k), ser(v))
            }).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn ser_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                r.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn is_valid_id(v: &JsonValue) -> bool {
    match v {
        JsonValue::Str(_) => true,
        JsonValue::Int(_) => true,
        _ => false,
    }
}

fn obj(pairs: Vec<(&str, JsonValue)>) -> JsonValue {
    JsonValue::Object(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}

fn arr(items: Vec<JsonValue>) -> JsonValue {
    JsonValue::Array(items)
}

fn str_val(s: &str) -> JsonValue {
    JsonValue::Str(s.to_string())
}

fn int_val(i: i64) -> JsonValue {
    JsonValue::Int(i)
}

fn bool_val(b: bool) -> JsonValue {
    JsonValue::Bool(b)
}

fn error_response(id: JsonValue, code: i64, msg: &str) -> String {
    let resp = obj(vec![
        ("jsonrpc", str_val("2.0")),
        ("id", id),
        ("error", obj(vec![
            ("code", int_val(code)),
            ("message", str_val(msg)),
        ])),
    ]);
    ser(&resp)
}

fn result_response(id: JsonValue, result: JsonValue) -> String {
    let resp = obj(vec![
        ("jsonrpc", str_val("2.0")),
        ("id", id),
        ("result", result),
    ]);
    ser(&resp)
}

