struct McpServer {
    initialized: bool,
    store: HashMap<String, String>,
}

impl McpServer {
    fn new() -> Self {
        McpServer { initialized: false, store: HashMap::new() }
    }

    fn handle(&mut self, id: &JsonValue, method: &str, params: Option<&JsonValue>) -> String {
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            return error_response(id.clone(), -32601, "Method not found");
        }

        if let Some(p) = params {
            if !matches!(p, JsonValue::Object(_)) {
                return error_response(id.clone(), -32602, "Invalid params");
            }
        }

        if !self.initialized && method != "initialize" && method != "ping" {
            return error_response(id.clone(), -32002, "Server not initialized");
        }

        match method {
            "initialize" => self.handle_initialize(id, params),
            "ping" => result_response(id.clone(), obj(vec![])),
            "tools/list" => result_response(id.clone(), tools_list_result()),
            "tools/call" => self.handle_tools_call(id, params),
            _ => unreachable!(),
        }
    }

    fn handle_initialize(&mut self, id: &JsonValue, params: Option<&JsonValue>) -> String {
        if self.initialized {
            return error_response(id.clone(), -32600, "Already initialized");
        }
        let p = match params {
            Some(JsonValue::Object(_)) => params.unwrap(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        let pv = match p.get("protocolVersion") {
            Some(JsonValue::Str(s)) => s.clone(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        self.initialized = true;
        let version = if pv == "2025-06-18" || pv == "2025-03-26" || pv == "2024-11-05" {
            pv
        } else {
            "2025-06-18".to_string()
        };
        let result = obj(vec![
            ("protocolVersion", str_val(&version)),
            ("capabilities", obj(vec![
                ("tools", obj(vec![("listChanged", bool_val(false))])),
            ])),
            ("serverInfo", obj(vec![
                ("name", str_val("cb2-kv")),
                ("title", str_val("CB2 key-value server")),
                ("version", str_val("1.4.2")),
            ])),
        ]);
        result_response(id.clone(), result)
    }

    fn handle_tools_call(&mut self, id: &JsonValue, params: Option<&JsonValue>) -> String {
        let p = match params {
            Some(JsonValue::Object(_)) => params.unwrap(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };
        let name = match p.get("name") {
            Some(JsonValue::Str(s)) => s.clone(),
            _ => return error_response(id.clone(), -32602, "Invalid params"),
        };

        let tools = get_tools();
        let tool = match tools.iter().find(|t| t.name == name) {
            Some(t) => t,
            None => return error_response(id.clone(), -32602, &format!("Unknown tool: {}", name)),
        };

        let arguments: Vec<(String, JsonValue)> = match p.get("arguments") {
            None => vec![],
            Some(JsonValue::Object(members)) => members.clone(),
            Some(_) => {
                return result_response(id.clone(), tool_failure("arguments must be an object"));
            }
        };

        let valid_names: Vec<&str> = tool.props.iter().map(|p| p.name).collect();
        let mut unknown: Vec<String> = vec![];
        for (k, _) in &arguments {
            if !valid_names.contains(&k.as_str()) {
                unknown.push(k.clone());
            }
        }
        if !unknown.is_empty() {
            unknown.sort();
            return result_response(id.clone(), tool_failure(&format!("unknown argument: {}", unknown[0])));
        }

        for prop in &tool.props {
            let arg_val = arguments.iter().find(|(k, _)| k == prop.name).map(|(_, v)| v);
            match arg_val {
                None => {
                    if prop.required {
                        return result_response(id.clone(), tool_failure(&format!("missing required argument: {}", prop.name)));
                    }
                }
                Some(v) => {
                    match prop.ptype {
                        PropType::String => {
                            if !matches!(v, JsonValue::Str(_)) {
                                return result_response(id.clone(), tool_failure(&format!("argument {} must be a string", prop.name)));
                            }
                            if let Some(ml) = prop.min_length {
                                if let JsonValue::Str(s) = v {
                                    if s.is_empty() && ml > 0 {
                                        return result_response(id.clone(), tool_failure(&format!("argument {} must not be empty", prop.name)));
                                    }
                                }
                            }
                        }
                        PropType::ArrayOfIntegers => {
                            match v {
                                JsonValue::Array(items) => {
                                    for item in items {
                                        if !matches!(item, JsonValue::Int(_)) {
                                            return result_response(id.clone(), tool_failure(&format!("argument {} must be an array of integers", prop.name)));
                                        }
                                    }
                                    if let Some(mi) = prop.min_items {
                                        if items.is_empty() && mi > 0 {
                                            return result_response(id.clone(), tool_failure(&format!("argument {} must not be empty", prop.name)));
                                        }
                                    }
                                }
                                _ => {
                                    return result_response(id.clone(), tool_failure(&format!("argument {} must be an array of integers", prop.name)));
                                }
                            }
                        }
                    }
                }
            }
        }

        self.execute_tool(id, tool, &arguments)
    }

    fn execute_tool(&mut self, id: &JsonValue, tool: &ToolDef, arguments: &[(String, JsonValue)]) -> String {
        let get_str = |name: &str| -> Option<String> {
            arguments.iter().find(|(k, _)| k == name).and_then(|(_, v)| {
                if let JsonValue::Str(s) = v { Some(s.clone()) } else { None }
            })
        };

        match tool.name {
            "kv_set" => {
                let key = get_str("key").unwrap();
                let value = get_str("value").unwrap();
                let existed = self.store.contains_key(&key);
                self.store.insert(key.clone(), value);
                let text = if existed { format!("updated {}", key) } else { format!("created {}", key) };
                result_response(id.clone(), tool_success(text, None))
            }
            "kv_get" => {
                let key = get_str("key").unwrap();
                match self.store.get(&key) {
                    Some(val) => result_response(id.clone(), tool_success(val.clone(), None)),
                    None => result_response(id.clone(), tool_failure(&format!("key not found: {}", key))),
                }
            }
            "kv_list" => {
                let prefix = get_str("prefix").unwrap_or_default();
                let mut keys: Vec<String> = self.store.keys()
                    .filter(|k| k.starts_with(&prefix))
                    .cloned()
                    .collect();
                keys.sort();
                let count = keys.len() as i64;
                let structured = obj(vec![
                    ("keys", arr(keys.into_iter().map(|s| str_val(&s)).collect())),
                    ("count", int_val(count)),
                ]);
                let text = ser(&structured);
                result_response(id.clone(), tool_success(text, Some(structured)))
            }
            "sum" => {
                let numbers: Vec<i64> = arguments.iter().find(|(k, _)| k == "numbers")
                    .and_then(|(_, v)| if let JsonValue::Array(items) = v {
                        Some(items.iter().filter_map(|item| if let JsonValue::Int(i) = item { Some(*i) } else { None }).collect())
                    } else { None })
                    .unwrap_or_default();
                let s: i64 = numbers.iter().sum();
                let count = numbers.len() as i64;
                let structured = obj(vec![
                    ("sum", int_val(s)),
                    ("count", int_val(count)),
                ]);
                let text = ser(&structured);
                result_response(id.clone(), tool_success(text, Some(structured)))
            }
            "text_stats" => {
                let text = get_str("text").unwrap();
                let words = text.split(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r')
                    .filter(|s| !s.is_empty())
                    .count() as i64;
                let codepoints = text.chars().count() as i64;
                let utf8_bytes = text.len() as i64;
                let structured = obj(vec![
                    ("words", int_val(words)),
                    ("codepoints", int_val(codepoints)),
                    ("utf8_bytes", int_val(utf8_bytes)),
                ]);
                let text_json = ser(&structured);
                result_response(id.clone(), tool_success(text_json, Some(structured)))
            }
            _ => unreachable!(),
        }
    }
}

fn tool_success(text: String, structured: Option<JsonValue>) -> JsonValue {
    let mut pairs = vec![
        ("content", arr(vec![
            obj(vec![
                ("type", str_val("text")),
                ("text", str_val(&text)),
            ]),
        ])),
    ];
    if let Some(sc) = structured {
        pairs.push(("structuredContent", sc));
    }
    pairs.push(("isError", bool_val(false)));
    obj(pairs)
}

fn tool_failure(text: &str) -> JsonValue {
    obj(vec![
        ("content", arr(vec![
            obj(vec![
                ("type", str_val("text")),
                ("text", str_val(text)),
            ]),
        ])),
        ("isError", bool_val(true)),
    ])
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut server = McpServer::new();

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        if line.trim().is_empty() {
            continue;
        }

        let parsed = match parse_json(&line) {
            Ok(v) => v,
            Err(_) => {
                let resp = error_response(JsonValue::Null, -32700, "Parse error");
                let _ = writeln!(out, "{}", resp);
                continue;
            }
        };

        let obj_members = match &parsed {
            JsonValue::Object(m) => m,
            _ => {
                let resp = error_response(JsonValue::Null, -32600, "Invalid Request");
                let _ = writeln!(out, "{}", resp);
                continue;
            }
        };

        let has_method = obj_members.iter().any(|(k, _)| k == "method");
        let has_result = obj_members.iter().any(|(k, _)| k == "result");
        let has_error = obj_members.iter().any(|(k, _)| k == "error");
        if !has_method && (has_result || has_error) {
            continue;
        }

        let jsonrpc_val = obj_members.iter().find(|(k, _)| k == "jsonrpc").map(|(_, v)| v);
        let method_val = obj_members.iter().find(|(k, _)| k == "method").map(|(_, v)| v);
        let id_member = obj_members.iter().find(|(k, _)| k == "id");

        let jsonrpc_ok = match jsonrpc_val {
            Some(JsonValue::Str(s)) => s == "2.0",
            _ => false,
        };
        let method_ok = match method_val {
            Some(JsonValue::Str(_)) => true,
            _ => false,
        };
        let id_ok = match id_member {
            Some((_, v)) => is_valid_id(v),
            None => true,
        };

        if !jsonrpc_ok || !method_ok || !id_ok {
            let id = match id_member {
                Some((_, v)) if is_valid_id(v) => v.clone(),
                _ => JsonValue::Null,
            };
            let resp = error_response(id, -32600, "Invalid Request");
            let _ = writeln!(out, "{}", resp);
            continue;
        }

        let id = match id_member {
            Some((_, v)) => v.clone(),
            None => continue,
        };

        let method = match method_val {
            Some(JsonValue::Str(s)) => s.as_str(),
            _ => unreachable!(),
        };
        let params = obj_members.iter().find(|(k, _)| k == "params").map(|(_, v)| v);

        let resp = server.handle(&id, method, params);
        let _ = writeln!(out, "{}", resp);
    }

    let _ = out.flush();
}

import { readFileSync } from 'fs';

// --- Custom JSON Parser that tracks integer-ness of numbers ---

type ParsedValue =
  | { type: 'string'; value: string }
  | { type: 'number'; value: number; isInteger: boolean }
  | { type: 'boolean'; value: boolean }
  | { type: 'null' }
  | { type: 'object'; value: Map<string, ParsedValue> }
  | { type: 'array'; value: ParsedValue[] };

class JsonParseError extends Error {}

function parseJson(input: string): ParsedValue {
  let pos = 0;

  function skipWs(): void {
    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t' || input[pos] === '\n' || input[pos] === '\r')) {
      pos++;
    }
  }

  function parseValue(): ParsedValue {
    skipWs();
    if (pos >= input.length) throw new JsonParseError('Unexpected end');
    const ch = input[pos];
    if (ch === '"') return parseString();
    if (ch === '{') return parseObject();
    if (ch === '[') return parseArray();
    if (ch === 't') return parseLiteral('true', { type: 'boolean', value: true });
    if (ch === 'f') return parseLiteral('false', { type: 'boolean', value: false });
    if (ch === 'n') return parseLiteral('null', { type: 'null' });
    if (ch === '-' || (ch >= '0' && ch <= '9')) return parseNumber();
    throw new JsonParseError('Unexpected character');
  }

  function parseLiteral(expected: string, result: ParsedValue): ParsedValue {
    if (input.startsWith(expected, pos)) {
      pos += expected.length;
      return result;
    }
    throw new JsonParseError('Invalid literal');
  }

  function parseString(): ParsedValue {
    pos++; // skip "
    let result = '';
    while (pos < input.length) {
      const ch = input[pos];
      if (ch === '"') { pos++; return { type: 'string', value: result }; }
      if (ch === '\\') {
        pos++;
        if (pos >= input.length) throw new JsonParseError('Unexpected end in string');
        const esc = input[pos];
        if (esc === '"') { result += '"'; pos++; }
        else if (esc === '\\') { result += '\\'; pos++; }
        else if (esc === '/') { result += '/'; pos++; }
        else if (esc === 'b') { result += '\b'; pos++; }
        else if (esc === 'f') { result += '\f'; pos++; }
        else if (esc === 'n') { result += '\n'; pos++; }
        else if (esc === 'r') { result += '\r'; pos++; }
        else if (esc === 't') { result += '\t'; pos++; }
        else if (esc === 'u') {
          pos++;
          const hex = input.substring(pos, pos + 4);
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) throw new JsonParseError('Invalid unicode escape');
          const code = parseInt(hex, 16);
          if (code >= 0xD800 && code <= 0xDBFF) {
            if (pos + 6 <= input.length && input[pos + 4] === '\\' && input[pos + 5] === 'u') {
              const hex2 = input.substring(pos + 6, pos + 10);
              if (hex2.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex2)) throw new JsonParseError('Invalid unicode escape');
              const code2 = parseInt(hex2, 16);
              if (code2 >= 0xDC00 && code2 <= 0xDFFF) {
                const fullCode = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00);
                result += String.fromCodePoint(fullCode);
                pos += 10;
              } else {
                result += String.fromCharCode(code);
                pos += 4;
              }
            } else {
              result += String.fromCharCode(code);
              pos += 4;
            }
          } else {
            result += String.fromCharCode(code);
            pos += 4;
          }
        } else {
          throw new JsonParseError('Invalid escape');
        }
      } else if (ch < 0x20) {
        throw new JsonParseError('Control character in string');
      } else {
        result += ch;
        pos++;
      }
    }
    throw new JsonParseError('Unterminated string');
  }

  function parseNumber(): ParsedValue {
    const start = pos;
    if (input[pos] === '-') pos++;
    if (pos >= input.length) throw new JsonParseError('Invalid number');
    if (input[pos] === '0') {
      pos++;
    } else if (input[pos] >= '1' && input[pos] <= '9') {
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    } else {
      throw new JsonParseError('Invalid number');
    }
    let isInteger = true;
    if (pos < input.length && input[pos] === '.') {
      isInteger = false;
      pos++;
      if (pos >= input.length || input[pos] < '0' || input[pos] > '9') throw new JsonParseError('Invalid number');
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    }
    if (pos < input.length && (input[pos] === 'e' || input[pos] === 'E')) {
      isInteger = false;
      pos++;
      if (pos < input.length && (input[pos] === '+' || input[pos] === '-')) pos++;
      if (pos >= input.length || input[pos] < '0' || input[pos] > '9') throw new JsonParseError('Invalid number');
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    }
    return { type: 'number', value: Number(input.substring(start, pos)), isInteger };
  }

  function parseObject(): ParsedValue {
    pos++; // skip {
    skipWs();
    const map = new Map<string, ParsedValue>();
    if (pos < input.length && input[pos] === '}') { pos++; return { type: 'object', value: map }; }
    while (true) {
      skipWs();
      if (pos >= input.length || input[pos] !== '"') throw new JsonParseError('Expected string key');
      const keyResult = parseString();
      const key = (keyResult as { type: 'string'; value: string }).value;
      skipWs();
      if (pos >= input.length || input[pos] !== ':') throw new JsonParseError('Expected :');
      pos++;
      const val = parseValue();
      map.set(key, val);
      skipWs();
      if (pos >= input.length) throw new JsonParseError('Expected , or }');
      if (input[pos] === ',') { pos++; continue; }
      if (input[pos] === '}') { pos++; return { type: 'object', value: map }; }
      throw new JsonParseError('Expected , or }');
    }
  }

  function parseArray(): ParsedValue {
    pos++; // skip [
    skipWs();
    const arr: ParsedValue[] = [];
    if (pos < input.length && input[pos] === ']') { pos++; return { type: 'array', value: arr }; }
    while (true) {
      const val = parseValue();
      arr.push(val);
      skipWs();
      if (pos >= input.length) throw new JsonParseError('Expected , or ]');
      if (input[pos] === ',') { pos++; continue; }
      if (input[pos] === ']') { pos++; return { type: 'array', value: arr }; }
      throw new JsonParseError('Expected , or ]');
    }
  }

  const result = parseValue();
  skipWs();
  if (pos < input.length) throw new JsonParseError('Trailing garbage');
  return result;
}

// --- Helpers ---

function isValidId(v: ParsedValue | undefined): boolean {
  if (v === undefined) return false;
  if (v.type === 'string') return true;
  if (v.type === 'number' && v.isInteger) return true;
  return false;
}

function idToOutput(v: ParsedValue | undefined): any {
  if (v === undefined) return null;
  if (v.type === 'string') return v.value;
  if (v.type === 'number' && v.isInteger) return v.value;
  return null;
}

function compareCodePoints(a: string, b: string): number {
  const aPoints = Array.from(a);
  const bPoints = Array.from(b);
  const minLen = Math.min(aPoints.length, bPoints.length);
  for (let i = 0; i < minLen; i++) {
    const diff = aPoints[i].codePointAt(0)! - bPoints[i].codePointAt(0)!;
    if (diff !== 0) return diff;
  }
  return aPoints.length - bPoints.length;
}

// --- Tool definitions ---

const TOOLS: any[] = [
  {
    name: "kv_set",
    title: "Set a value",
    description: "Store a string value under a key, replacing any previous value.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 },
        value: { type: "string" }
      },
      required: ["key", "value"],
      additionalProperties: false
    }
  },
  {
    name: "kv_get",
    title: "Get a value",
    description: "Return the value stored under a key.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 }
      },
      required: ["key"],
      additionalProperties: false
    }
  },
  {
    name: "kv_list",
    title: "List keys",
    description: "List the stored keys that start with a prefix, sorted by Unicode code point.",
    inputSchema: {
      type: "object",
      properties: {
        prefix: { type: "string" }
      },
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        keys: { type: "array", items: { type: "string" } },
        count: { type: "integer" }
      },
      required: ["keys", "count"]
    }
  },
  {
    name: "sum",
    title: "Sum integers",
    description: "Add up a non-empty list of integers.",
    inputSchema: {
      type: "object",
      properties: {
        numbers: { type: "array", items: { type: "integer" }, minItems: 1 }
      },
      required: ["numbers"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" }
      },
      required: ["sum", "count"]
    },
    annotations: { readOnlyHint: true, idempotentHint: true }
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string" }
      },
      required: ["text"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

// --- Server state ---

let initialized = false;
const store = new Map<string, string>();

// --- Response builders ---

function makeResponse(id: any, result: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result });
}

function makeError(id: any, code: number, message: string): string {
  return JSON.stringify({ jsonrpc: "2.0", id, error: { code, message } });
}

// --- Argument validation ---

function validateArgs(toolIndex: number, args: Map<string, ParsedValue>): string | null {
  const tool = TOOLS[toolIndex];
  const schema = tool.inputSchema;
  const properties: Record<string, any> = schema.properties;
  const required: string[] = schema.required || [];

  // Check unknown arguments
  const propNames = new Set(Object.keys(properties));
  const unknown: string[] = [];
  for (const key of args.keys()) {
    if (!propNames.has(key)) {
      unknown.push(key);
    }
  }
  if (unknown.length > 0) {
    unknown.sort(compareCodePoints);
    return `unknown argument: ${unknown[0]}`;
  }

  // Check each property in schema order
  for (const propName of Object.keys(properties)) {
    const propSchema = properties[propName];
    const val = args.get(propName);

    if (val === undefined) {
      if (required.includes(propName)) {
        return `missing required argument: ${propName}`;
      }
      continue;
    }

    if (propSchema.type === "string") {
      if (val.type !== "string") {
        return `argument ${propName} must be a string`;
      }
      if (propSchema.minLength !== undefined && (val as { type: 'string'; value: string }).value.length < propSchema.minLength) {
        return `argument ${propName} must not be empty`;
      }
    } else if (propSchema.type === "array") {
      if (val.type !== "array") {
        return `argument ${propName} must be an array of integers`;
      }
      const arr = (val as { type: 'array'; value: ParsedValue[] }).value;
      if (propSchema.items && propSchema.items.type === "integer") {
        for (const elem of arr) {
          if (elem.type !== "number" || !elem.isInteger) {
            return `argument ${propName} must be an array of integers`;
          }
        }
      }
      if (propSchema.minItems !== undefined && arr.length < propSchema.minItems) {
        return `argument ${propName} must not be empty`;
      }
    }
  }

  return null;
}

// --- Tool execution ---

function executeTool(name: string, args: Map<string, ParsedValue>): any {
  switch (name) {
    case "kv_set": {
      const key = (args.get("key") as { type: 'string'; value: string }).value;
      const value = (args.get("value") as { type: 'string'; value: string }).value;
      const existed = store.has(key);
      store.set(key, value);
      return { content: [{ type: "text", text: existed ? `updated ${key}` : `created ${key}` }], isError: false };
    }
    case "kv_get": {
      const key = (args.get("key") as { type: 'string'; value: string }).value;
      if (!store.has(key)) {
        return { content: [{ type: "text", text: `key not found: ${key}` }], isError: true };
      }
      return { content: [{ type: "text", text: store.get(key)! }], isError: false };
    }
    case "kv_list": {
      const prefixVal = args.get("prefix");
      const prefix = prefixVal ? (prefixVal as { type: 'string'; value: string }).value : "";
      const keys: string[] = [];
      for (const k of store.keys()) {
        if (k.startsWith(prefix)) keys.push(k);
      }
      keys.sort(compareCodePoints);
      const structuredContent = { keys, count: keys.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    case "sum": {
      const numbersArr = (args.get("numbers") as { type: 'array'; value: ParsedValue[] }).value;
      let total = 0;
      for (const n of numbersArr) {
        total += (n as { type: 'number'; value: number }).value;
      }
      const structuredContent = { sum: total, count: numbersArr.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    case "text_stats": {
      const text = (args.get("text") as { type: 'string'; value: string }).value;
      let words = 0;
      let inWord = false;
      for (const ch of text) {
        if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
          inWord = false;
        } else {
          if (!inWord) {
            words++;
            inWord = true;
          }
        }
      }
      const codepoints = Array.from(text).length;
      const utf8Bytes = Buffer.byteLength(text, 'utf8');
      const structuredContent = { words, codepoints, utf8_bytes: utf8Bytes };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    default:
      throw new Error("Unknown tool: " + name);
  }
}

// --- Main ---

const input = readFileSync(0, 'utf-8');
const lines = input.split('\n');
const outputs: string[] = [];

for (const rawLine of lines) {
  let line = rawLine;
  if (line.endsWith('\r')) {
    line = line.slice(0, -1);
  }

  // Skip blank lines (only spaces, tabs, CR)
  if (line === '' || /^[ \t\r]*$/.test(line)) {
    continue;
  }

  // Rule 1: Parse JSON
  let parsed: ParsedValue;
  try {
    parsed = parseJson(line);
  } catch {
    outputs.push(makeError(null, -32700, "Parse error"));
    continue;
  }

  // Rule 2: Must be an object
  if (parsed.type !== 'object') {
    outputs.push(makeError(null, -32600, "Invalid Request"));
    continue;
  }

  const obj = parsed.value;

  // Rule 3: Client response (no method, has result or error) → ignore
  if (!obj.has('method') && (obj.has('result') || obj.has('error'))) {
    continue;
  }

  // Rule 4: Invalid request check
  const jsonrpc = obj.get('jsonrpc');
  const method = obj.get('method');
  const id = obj.get('id');
  const hasId = obj.has('id');

  const jsonrpcOk = jsonrpc !== undefined && jsonrpc.type === 'string' && (jsonrpc as { type: 'string'; value: string }).value === '2.0';
  const methodOk = method !== undefined && method.type === 'string';
  const idOk = !hasId || isValidId(id);

  if (!jsonrpcOk || !methodOk || !idOk) {
    const outputId = hasId ? idToOutput(id) : null;
    outputs.push(makeError(outputId, -32600, "Invalid Request"));
    continue;
  }

  // Rule 5: Notification (no id) → ignore
  if (!hasId) {
    continue;
  }

  // Rule 6: Request
  const methodStr = (method as { type: 'string'; value: string }).value;
  const outputId = idToOutput(id);

  // 6a: Method not found
  if (!['initialize', 'ping', 'tools/list', 'tools/call'].includes(methodStr)) {
    outputs.push(makeError(outputId, -32601, "Method not found"));
    continue;
  }

  // 6b: params present but not object
  const params = obj.get('params');
  if (params !== undefined && params.type !== 'object') {
    outputs.push(makeError(outputId, -32602, "Invalid params"));
    continue;
  }

  // 6c: Not initialized
  if (!initialized && methodStr !== 'initialize' && methodStr !== 'ping') {
    outputs.push(makeError(outputId, -32002, "Server not initialized"));
    continue;
  }

  // 6d: Dispatch
  const paramsObj = params !== undefined ? (params as { type: 'object'; value: Map<string, ParsedValue> }).value : undefined;

  switch (methodStr) {
    case 'initialize': {
      if (initialized) {
        outputs.push(makeError(outputId, -32600, "Already initialized"));
        break;
      }
      const protocolVersion = paramsObj?.get('protocolVersion');
      if (!protocolVersion || protocolVersion.type !== 'string') {
        outputs.push(makeError(outputId, -32602, "Invalid params"));
        break;
      }
      const pv = (protocolVersion as { type: 'string'; value: string }).value;
      const validVersions = ["2025-06-18", "2025-03-26", "2024-11-05"];
      const responseVersion = validVersions.includes(pv) ? pv : "2025-06-18";
      initialized = true;
      outputs.push(makeResponse(outputId, {
        protocolVersion: responseVersion,
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
      }));
      break;
    }
    case 'ping': {
      outputs.push(makeResponse(outputId, {}));
      break;
    }
    case 'tools/list': {
      outputs.push(makeResponse(outputId, { tools: TOOLS }));
      break;
    }
    case 'tools/call': {
      const nameVal = paramsObj?.get('name');
      if (!nameVal || nameVal.type !== 'string') {
        outputs.push(makeError(outputId, -32602, "Invalid params"));
        break;
      }
      const toolName = (nameVal as { type: 'string'; value: string }).value;
      const toolIndex = TOOLS.findIndex(t => t.name === toolName);
      if (toolIndex === -1) {
        outputs.push(makeError(outputId, -32602, `Unknown tool: ${toolName}`));
        break;
      }

      // Validate arguments
      const argsVal = paramsObj?.get('arguments');
      let args: Map<string, ParsedValue>;
      if (argsVal === undefined) {
        args = new Map();
      } else if (argsVal.type !== 'object') {
        outputs.push(makeResponse(outputId, {
          content: [{ type: "text", text: "arguments must be an object" }],
          isError: true
        }));
        break;
      } else {
        args = (argsVal as { type: 'object'; value: Map<string, ParsedValue> }).value;
      }

      const validationError = validateArgs(toolIndex, args);
      if (validationError) {
        outputs.push(makeResponse(outputId, {
          content: [{ type: "text", text: validationError }],
          isError: true
        }));
        break;
      }

      const result = executeTool(toolName, args);
      outputs.push(makeResponse(outputId, result));
      break;
    }
  }
}

// Write all output
for (const line of outputs) {
  process.stdout.write(line + '\n');
}

process.exit(0);

import { readFileSync } from 'fs';

// --- Custom JSON Parser that tracks integer-ness of numbers ---

type ParsedValue =
  | { type: 'string'; value: string }
  | { type: 'number'; value: number; isInteger: boolean }
  | { type: 'boolean'; value: boolean }
  | { type: 'null' }
  | { type: 'object'; value: Map<string, ParsedValue> }
  | { type: 'array'; value: ParsedValue[] };

class JsonParseError extends Error {}

function parseJson(input: string): ParsedValue {
  let pos = 0;

  function skipWs(): void {
    while (pos < input.length && (input[pos] === ' ' || input[pos] === '\t' || input[pos] === '\n' || input[pos] === '\r')) {
      pos++;
    }
  }

  function parseValue(): ParsedValue {
    skipWs();
    if (pos >= input.length) throw new JsonParseError('Unexpected end');
    const ch = input[pos];
    if (ch === '"') return parseString();
    if (ch === '{') return parseObject();
    if (ch === '[') return parseArray();
    if (ch === 't') return parseLiteral('true', { type: 'boolean', value: true });
    if (ch === 'f') return parseLiteral('false', { type: 'boolean', value: false });
    if (ch === 'n') return parseLiteral('null', { type: 'null' });
    if (ch === '-' || (ch >= '0' && ch <= '9')) return parseNumber();
    throw new JsonParseError('Unexpected character');
  }

  function parseLiteral(expected: string, result: ParsedValue): ParsedValue {
    if (input.startsWith(expected, pos)) {
      pos += expected.length;
      return result;
    }
    throw new JsonParseError('Invalid literal');
  }

  function parseString(): ParsedValue {
    pos++; // skip "
    let result = '';
    while (pos < input.length) {
      const ch = input[pos];
      if (ch === '"') { pos++; return { type: 'string', value: result }; }
      if (ch === '\\') {
        pos++;
        if (pos >= input.length) throw new JsonParseError('Unexpected end in string');
        const esc = input[pos];
        if (esc === '"') { result += '"'; pos++; }
        else if (esc === '\\') { result += '\\'; pos++; }
        else if (esc === '/') { result += '/'; pos++; }
        else if (esc === 'b') { result += '\b'; pos++; }
        else if (esc === 'f') { result += '\f'; pos++; }
        else if (esc === 'n') { result += '\n'; pos++; }
        else if (esc === 'r') { result += '\r'; pos++; }
        else if (esc === 't') { result += '\t'; pos++; }
        else if (esc === 'u') {
          pos++;
          const hex = input.substring(pos, pos + 4);
          if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) throw new JsonParseError('Invalid unicode escape');
          const code = parseInt(hex, 16);
          if (code >= 0xD800 && code <= 0xDBFF) {
            if (pos + 6 <= input.length && input[pos + 4] === '\\' && input[pos + 5] === 'u') {
              const hex2 = input.substring(pos + 6, pos + 10);
              if (hex2.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex2)) throw new JsonParseError('Invalid unicode escape');
              const code2 = parseInt(hex2, 16);
              if (code2 >= 0xDC00 && code2 <= 0xDFFF) {
                const fullCode = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00);
                result += String.fromCodePoint(fullCode);
                pos += 10;
              } else {
                result += String.fromCharCode(code);
                pos += 4;
              }
            } else {
              result += String.fromCharCode(code);
              pos += 4;
            }
          } else {
            result += String.fromCharCode(code);
            pos += 4;
          }
        } else {
          throw new JsonParseError('Invalid escape');
        }
      } else if (ch < 0x20) {
        throw new JsonParseError('Control character in string');
      } else {
        result += ch;
        pos++;
      }
    }
    throw new JsonParseError('Unterminated string');
  }

  function parseNumber(): ParsedValue {
    const start = pos;
    if (input[pos] === '-') pos++;
    if (pos >= input.length) throw new JsonParseError('Invalid number');
    if (input[pos] === '0') {
      pos++;
    } else if (input[pos] >= '1' && input[pos] <= '9') {
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    } else {
      throw new JsonParseError('Invalid number');
    }
    let isInteger = true;
    if (pos < input.length && input[pos] === '.') {
      isInteger = false;
      pos++;
      if (pos >= input.length || input[pos] < '0' || input[pos] > '9') throw new JsonParseError('Invalid number');
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    }
    if (pos < input.length && (input[pos] === 'e' || input[pos] === 'E')) {
      isInteger = false;
      pos++;
      if (pos < input.length && (input[pos] === '+' || input[pos] === '-')) pos++;
      if (pos >= input.length || input[pos] < '0' || input[pos] > '9') throw new JsonParseError('Invalid number');
      while (pos < input.length && input[pos] >= '0' && input[pos] <= '9') pos++;
    }
    return { type: 'number', value: Number(input.substring(start, pos)), isInteger };
  }

  function parseObject(): ParsedValue {
    pos++; // skip {
    skipWs();
    const map = new Map<string, ParsedValue>();
    if (pos < input.length && input[pos] === '}') { pos++; return { type: 'object', value: map }; }
    while (true) {
      skipWs();
      if (pos >= input.length || input[pos] !== '"') throw new JsonParseError('Expected string key');
      const keyResult = parseString();
      const key = (keyResult as { type: 'string'; value: string }).value;
      skipWs();
      if (pos >= input.length || input[pos] !== ':') throw new JsonParseError('Expected :');
      pos++;
      const val = parseValue();
      map.set(key, val);
      skipWs();
      if (pos >= input.length) throw new JsonParseError('Expected , or }');
      if (input[pos] === ',') { pos++; continue; }
      if (input[pos] === '}') { pos++; return { type: 'object', value: map }; }
      throw new JsonParseError('Expected , or }');
    }
  }

  function parseArray(): ParsedValue {
    pos++; // skip [
    skipWs();
    const arr: ParsedValue[] = [];
    if (pos < input.length && input[pos] === ']') { pos++; return { type: 'array', value: arr }; }
    while (true) {
      const val = parseValue();
      arr.push(val);
      skipWs();
      if (pos >= input.length) throw new JsonParseError('Expected , or ]');
      if (input[pos] === ',') { pos++; continue; }
      if (input[pos] === ']') { pos++; return { type: 'array', value: arr }; }
      throw new JsonParseError('Expected , or ]');
    }
  }

  const result = parseValue();
  skipWs();
  if (pos < input.length) throw new JsonParseError('Trailing garbage');
  return result;
}

// --- Helpers ---

function isValidId(v: ParsedValue | undefined): boolean {
  if (v === undefined) return false;
  if (v.type === 'string') return true;
  if (v.type === 'number' && v.isInteger) return true;
  return false;
}

function idToOutput(v: ParsedValue | undefined): any {
  if (v === undefined) return null;
  if (v.type === 'string') return v.value;
  if (v.type === 'number' && v.isInteger) return v.value;
  return null;
}

function compareCodePoints(a: string, b: string): number {
  const aPoints = Array.from(a);
  const bPoints = Array.from(b);
  const minLen = Math.min(aPoints.length, bPoints.length);
  for (let i = 0; i < minLen; i++) {
    const diff = aPoints[i].codePointAt(0)! - bPoints[i].codePointAt(0)!;
    if (diff !== 0) return diff;
  }
  return aPoints.length - bPoints.length;
}

// --- Tool definitions ---

const TOOLS: any[] = [
  {
    name: "kv_set",
    title: "Set a value",
    description: "Store a string value under a key, replacing any previous value.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 },
        value: { type: "string" }
      },
      required: ["key", "value"],
      additionalProperties: false
    }
  },
  {
    name: "kv_get",
    title: "Get a value",
    description: "Return the value stored under a key.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 }
      },
      required: ["key"],
      additionalProperties: false
    }
  },
  {
    name: "kv_list",
    title: "List keys",
    description: "List the stored keys that start with a prefix, sorted by Unicode code point.",
    inputSchema: {
      type: "object",
      properties: {
        prefix: { type: "string" }
      },
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        keys: { type: "array", items: { type: "string" } },
        count: { type: "integer" }
      },
      required: ["keys", "count"]
    }
  },
  {
    name: "sum",
    title: "Sum integers",
    description: "Add up a non-empty list of integers.",
    inputSchema: {
      type: "object",
      properties: {
        numbers: { type: "array", items: { type: "integer" }, minItems: 1 }
      },
      required: ["numbers"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" }
      },
      required: ["sum", "count"]
    },
    annotations: { readOnlyHint: true, idempotentHint: true }
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string" }
      },
      required: ["text"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

// --- Server state ---

let initialized = false;
const store = new Map<string, string>();

// --- Response builders ---

function makeResponse(id: any, result: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result });
}

function makeError(id: any, code: number, message: string): string {
  return JSON.stringify({ jsonrpc: "2.0", id, error: { code, message } });
}

// --- Argument validation ---

function validateArgs(toolIndex: number, args: Map<string, ParsedValue>): string | null {
  const tool = TOOLS[toolIndex];
  const schema = tool.inputSchema;
  const properties: Record<string, any> = schema.properties;
  const required: string[] = schema.required || [];

  // Check unknown arguments
  const propNames = new Set(Object.keys(properties));
  const unknown: string[] = [];
  for (const key of args.keys()) {
    if (!propNames.has(key)) {
      unknown.push(key);
    }
  }
  if (unknown.length > 0) {
    unknown.sort(compareCodePoints);
    return `unknown argument: ${unknown[0]}`;
  }

  // Check each property in schema order
  for (const propName of Object.keys(properties)) {
    const propSchema = properties[propName];
    const val = args.get(propName);

    if (val === undefined) {
      if (required.includes(propName)) {
        return `missing required argument: ${propName}`;
      }
      continue;
    }

    if (propSchema.type === "string") {
      if (val.type !== "string") {
        return `argument ${propName} must be a string`;
      }
      if (propSchema.minLength !== undefined && (val as { type: 'string'; value: string }).value.length < propSchema.minLength) {
        return `argument ${propName} must not be empty`;
      }
    } else if (propSchema.type === "array") {
      if (val.type !== "array") {
        return `argument ${propName} must be an array of integers`;
      }
      const arr = (val as { type: 'array'; value: ParsedValue[] }).value;
      if (propSchema.items && propSchema.items.type === "integer") {
        for (const elem of arr) {
          if (elem.type !== "number" || !elem.isInteger) {
            return `argument ${propName} must be an array of integers`;
          }
        }
      }
      if (propSchema.minItems !== undefined && arr.length < propSchema.minItems) {
        return `argument ${propName} must not be empty`;
      }
    }
  }

  return null;
}

// --- Tool execution ---

function executeTool(name: string, args: Map<string, ParsedValue>): any {
  switch (name) {
    case "kv_set": {
      const key = (args.get("key") as { type: 'string'; value: string }).value;
      const value = (args.get("value") as { type: 'string'; value: string }).value;
      const existed = store.has(key);
      store.set(key, value);
      return { content: [{ type: "text", text: existed ? `updated ${key}` : `created ${key}` }], isError: false };
    }
    case "kv_get": {
      const key = (args.get("key") as { type: 'string'; value: string }).value;
      if (!store.has(key)) {
        return { content: [{ type: "text", text: `key not found: ${key}` }], isError: true };
      }
      return { content: [{ type: "text", text: store.get(key)! }], isError: false };
    }
    case "kv_list": {
      const prefixVal = args.get("prefix");
      const prefix = prefixVal ? (prefixVal as { type: 'string'; value: string }).value : "";
      const keys: string[] = [];
      for (const k of store.keys()) {
        if (k.startsWith(prefix)) keys.push(k);
      }
      keys.sort(compareCodePoints);
      const structuredContent = { keys, count: keys.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    case "sum": {
      const numbersArr = (args.get("numbers") as { type: 'array'; value: ParsedValue[] }).value;
      let total = 0;
      for (const n of numbersArr) {
        total += (n as { type: 'number'; value: number }).value;
      }
      const structuredContent = { sum: total, count: numbersArr.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    case "text_stats": {
      const text = (args.get("text") as { type: 'string'; value: string }).value;
      let words = 0;
      let inWord = false;
      for (const ch of text) {
        if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
          inWord = false;
        } else {
          if (!inWord) {
            words++;
            inWord = true;
          }
        }
      }
      const codepoints = Array.from(text).length;
      const utf8Bytes = Buffer.byteLength(text, 'utf8');
      const structuredContent = { words, codepoints, utf8_bytes: utf8Bytes };
      return {
        content: [{ type: "text", text: JSON.stringify(structuredContent) }],
        structuredContent,
        isError: false
      };
    }
    default:
      throw new Error("Unknown tool: " + name);
  }
}

// --- Main ---

const buf = readFileSync(0);
let input = buf.toString('utf-8');
// Strip UTF-8 BOM if present
if (input.charCodeAt(0) === 0xFEFF) {
  input = input.slice(1);
}

const lines = input.split('\n');
const outputs: string[] = [];

for (const rawLine of lines) {
  let line = rawLine;
  if (line.endsWith('\r')) {
    line = line.slice(0, -1);
  }

  // Skip blank lines (only spaces, tabs, CR)
  if (line === '' || /^[ \t\r]*$/.test(line)) {
    continue;
  }

  // Rule 1: Parse JSON
  let parsed: ParsedValue;
  try {
    parsed = parseJson(line);
  } catch {
    outputs.push(makeError(null, -32700, "Parse error"));
    continue;
  }

  // Rule 2: Must be an object
  if (parsed.type !== 'object') {
    outputs.push(makeError(null, -32600, "Invalid Request"));
    continue;
  }

  const obj = parsed.value;

  // Rule 3: Client response (no method, has result or error) → ignore
  if (!obj.has('method') && (obj.has('result') || obj.has('error'))) {
    continue;
  }

  // Rule 4: Invalid request check
  const jsonrpc = obj.get('jsonrpc');
  const method = obj.get('method');
  const id = obj.get('id');
  const hasId = obj.has('id');

  const jsonrpcOk = jsonrpc !== undefined && jsonrpc.type === 'string' && (jsonrpc as { type: 'string'; value: string }).value === '2.0';
  const methodOk = method !== undefined && method.type === 'string';
  const idOk = !hasId || isValidId(id);

  if (!jsonrpcOk || !methodOk || !idOk) {
    const outputId = hasId ? idToOutput(id) : null;
    outputs.push(makeError(outputId, -32600, "Invalid Request"));
    continue;
  }

  // Rule 5: Notification (no id) → ignore
  if (!hasId) {
    continue;
  }

  // Rule 6: Request
  const methodStr = (method as { type: 'string'; value: string }).value;
  const outputId = idToOutput(id);

  // 6a: Method not found
  if (!['initialize', 'ping', 'tools/list', 'tools/call'].includes(methodStr)) {
    outputs.push(makeError(outputId, -32601, "Method not found"));
    continue;
  }

  // 6b: params present but not object
  const params = obj.get('params');
  if (params !== undefined && params.type !== 'object') {
    outputs.push(makeError(outputId, -32602, "Invalid params"));
    continue;
  }

  // 6c: Not initialized
  if (!initialized && methodStr !== 'initialize' && methodStr !== 'ping') {
    outputs.push(makeError(outputId, -32002, "Server not initialized"));
    continue;
  }

  // 6d: Dispatch
  const paramsObj = params !== undefined ? (params as { type: 'object'; value: Map<string, ParsedValue> }).value : undefined;

  switch (methodStr) {
    case 'initialize': {
      if (initialized) {
        outputs.push(makeError(outputId, -32600, "Already initialized"));
        break;
      }
      const protocolVersion = paramsObj?.get('protocolVersion');
      if (!protocolVersion || protocolVersion.type !== 'string') {
        outputs.push(makeError(outputId, -32602, "Invalid params"));
        break;
      }
      const pv = (protocolVersion as { type: 'string'; value: string }).value;
      const validVersions = ["2025-06-18", "2025-03-26", "2024-11-05"];
      const responseVersion = validVersions.includes(pv) ? pv : "2025-06-18";
      initialized = true;
      outputs.push(makeResponse(outputId, {
        protocolVersion: responseVersion,
        capabilities: { tools: { listChanged: false } },
        serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
      }));
      break;
    }
    case 'ping': {
      outputs.push(makeResponse(outputId, {}));
      break;
    }
    case 'tools/list': {
      outputs.push(makeResponse(outputId, { tools: TOOLS }));
      break;
    }
    case 'tools/call': {
      const nameVal = paramsObj?.get('name');
      if (!nameVal || nameVal.type !== 'string') {
        outputs.push(makeError(outputId, -32602, "Invalid params"));
        break;
      }
      const toolName = (nameVal as { type: 'string'; value: string }).value;
      const toolIndex = TOOLS.findIndex(t => t.name === toolName);
      if (toolIndex === -1) {
        outputs.push(makeError(outputId, -32602, `Unknown tool: ${toolName}`));
        break;
      }

      // Validate arguments
      const argsVal = paramsObj?.get('arguments');
      let args: Map<string, ParsedValue>;
      if (argsVal === undefined) {
        args = new Map();
      } else if (argsVal.type !== 'object') {
        outputs.push(makeResponse(outputId, {
          content: [{ type: "text", text: "arguments must be an object" }],
          isError: true
        }));
        break;
      } else {
        args = (argsVal as { type: 'object'; value: Map<string, ParsedValue> }).value;
      }

      const validationError = validateArgs(toolIndex, args);
      if (validationError) {
        outputs.push(makeResponse(outputId, {
          content: [{ type: "text", text: validationError }],
          isError: true
        }));
        break;
      }

      const result = executeTool(toolName, args);
      outputs.push(makeResponse(outputId, result));
      break;
    }
  }
}

// Write all output
for (const line of outputs) {
  process.stdout.write(line + '\n');
}

process.exit(0);

import Foundation

// MARK: - CRC-32
let crc32Table: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var crc = UInt32(i)
        for _ in 0..<8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320 } else { crc >>= 1 }
        }
        table[i] = crc
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for b in data {
        crc = (crc >> 8) ^ crc32Table[Int((crc ^ UInt32(b)) & 0xFF)]
    }
    return crc ^ 0xFFFFFFFF
}

// MARK: - Utilities
func isHexDigit(_ b: UInt8) -> Bool {
    return (b >= 0x30 && b <= 0x39) || (b >= 0x41 && b <= 0x46) || (b >= 0x61 && b <= 0x66)
}
func hexVal(_ b: UInt8) -> UInt8 {
    if b >= 0x30 && b <= 0x39 { return b - 0x30 }
    if b >= 0x41 && b <= 0x46 { return b - 0x41 + 10 }
    return b - 0x61 + 10
}
func isBase64Char(_ b: UInt8) -> Bool {
    return (b >= 0x41 && b <= 0x5A) || (b >= 0x61 && b <= 0x7A) || (b >= 0x30 && b <= 0x39) || b == 0x2B || b == 0x2F
}
func base64Val(_ b: UInt8) -> UInt8 {
    if b >= 0x41 && b <= 0x5A { return b - 0x41 }
    if b >= 0x61 && b <= 0x7A { return b - 0x61 + 26 }
    if b >= 0x30 && b <= 0x39 { return b - 0x30 + 52 }
    if b == 0x2B { return 62 }
    return 63
}

// MARK: - Base64 Decode
func base64Decode(_ input: [UInt8]) -> [UInt8] {
    var filtered: [UInt8] = []
    for b in input {
        if b == 0x3D { break }
        if isBase64Char(b) { filtered.append(b) }
    }
    var result: [UInt8] = []
    var i = 0
    while i < filtered.count {
        let rem = filtered.count - i
        let cnt = min(4, rem)
        var quad: [UInt8] = [0,0,0,0]
        for j in 0..<cnt { quad[j] = base64Val(filtered[i+j]) }
        if cnt >= 2 { result.append((quad[0] << 2) | (quad[1] >> 4)) }
        if cnt >= 3 { result.append((quad[1] << 4) | (quad[2] >> 2)) }
        if cnt >= 4 { result.append((quad[2] << 6) | quad[3]) }
        i += 4
    }
    return result
}

// MARK: - Quoted-Printable Decode
func decodeQP(_ data: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    // Split into lines
    var lines: [[UInt8]] = []
    var start = 0
    while start < data.count {
        var found = false
        if start + lineBreak.count <= data.count {
            var match = true
            for j in 0..<lineBreak.count {
                if data[start+j] != lineBreak[j] { match = false; break }
            }
            if match {
                lines.append(Array(data[start..<start]))
                // Actually need to find the line break
                lines.removeLast()
                lines.append(Array(data[start..<start]))
                // Let me redo this
                break
            }
        }
        start += 1
    }
    // Redo line splitting properly
    lines = []
    start = 0
    while start < data.count {
        var end = start
        while end < data.count {
            if end + lineBreak.count <= data.count {
                var match = true
                for j in 0..<lineBreak.count {
                    if data[end+j] != lineBreak[j] { match = false; break }
                }
                if match { break }
            }
            end += 1
        }
        lines.append(Array(data[start..<end]))
        if end < data.count {
            start = end + lineBreak.count
        } else {
            break
        }
    }

    // Remove trailing spaces/tabs from each line
    for i in 0..<lines.count {
        while let last = lines[i].last, last == 0x20 || last == 0x09 {
            lines[i].removeLast()
        }
    }

    // Join with soft break resolution
    var joined: [UInt8] = []
    var i = 0
    while i < lines.count {
        var line = lines[i]
        while line.last == 0x3D && i + 1 < lines.count {
            line.removeLast() // remove the '='
            i += 1
            line.append(contentsOf: lines[i])
        }
        joined.append(contentsOf: line)
        if i + 1 < lines.count {
            joined.append(contentsOf: lineBreak)
        }
        i += 1
    }

    // Process =XY sequences
    var output: [UInt8] = []
    var j = 0
    while j < joined.count {
        if joined[j] == 0x3D && j + 2 < joined.count && isHexDigit(joined[j+1]) && isHexDigit(joined[j+2]) {
            output.append(hexVal(joined[j+1]) * 16 + hexVal(joined[j+2]))
            j += 3
        } else {
            output.append(joined[j])
            j += 1
        }
    }
    return output
}

// MARK: - Charset Decode
let win1252: [UInt32] = [
    0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
    0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
    0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
    0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
]

func normalizeCS(_ cs: String) -> String {
    var c = cs.lowercased()
    if let p = c.firstIndex(of: "*") { c = String(c[c.startIndex..<p]) }
    return c
}

func decodeCharset(_ bytes: [UInt8], charset: String) -> String {
    let cs = normalizeCS(charset)
    switch cs {
    case "us-ascii", "utf-8":
        return String(decoding: bytes, as: UTF8.self)
    case "iso-8859-1":
        var s = String.UnicodeScalarView()
        for b in bytes { s.append(UnicodeScalar(UInt32(b))) }
        return String(s)
    case "windows-1252":
        var s = String.UnicodeScalarView()
        for b in bytes {
            if b >= 0x80 && b <= 0x9F { s.append(UnicodeScalar(win1252[Int(b-0x80)])) }
            else { s.append(UnicodeScalar(UInt32(b))) }
        }
        return String(s)
    default:
        return String(decoding: bytes, as: UTF8.self)
    }
}

// MARK: - RFC 2047
func tryParseEW(_ text: String, from start: String.Index) -> (start: String.Index, end: String.Index, charset: String, encoding: Character, encodedText: String)? {
    var pos = text.index(start, offsetBy: 2) // skip "=?"
    var charset = ""
    while pos < text.endIndex && text[pos] != "?" && text[pos] != " " && text[pos] != "\t" {
        charset.append(text[pos]); pos = text.index(after: pos)
    }
    if charset.isEmpty { return nil }
    if pos >= text.endIndex || text[pos] != "?" { return nil }
    pos = text.index(after: pos)
    if pos >= text.endIndex { return nil }
    let enc = text[pos]
    if enc != "B" && enc != "b" && enc != "Q" && enc != "q" { return nil }
    pos = text.index(after: pos)
    if pos >= text.endIndex || text[pos] != "?" { return nil }
    pos = text.index(after: pos)
    var etext = ""
    while pos < text.endIndex && text[pos] != "?" && text[pos] != " " && text[pos] != "\t" {
        etext.append(text[pos]); pos = text.index(after: pos)
    }
    if pos >= text.endIndex || text[pos] != "?" { return nil }
    pos = text.index(after: pos)
    if pos >= text.endIndex || text[pos] != "=" { return nil }
    pos = text.index(after: pos)
    return (start, pos, charset, enc, etext)
}

func qDecodeBytes(_ s: String) -> [UInt8] {
    var result: [UInt8] = []
    var i = s.startIndex
    while i < s.endIndex {
        if s[i] == "_" { result.append(0x20); i = s.index(after: i) }
        else if s[i] == "=" {
            let n1 = s.index(after: i)
            if n1 < s.endIndex {
                let n2 = s.index(after: n1)
                if n2 < s.endIndex {
                    let b1 = s[n1].asciiValue ?? 0
                    let b2 = s[n2].asciiValue ?? 0
                    if isHexDigit(b1) && isHexDigit(b2) {
                        result.append(hexVal(b1)*16+hexVal(b2))
                        i = s.index(after: n2)
                        continue
                    }
                }
            }
            result.append(0x3D); i = s.index(after: i)
        }
        else { result.append(s[i].asciiValue ?? 0); i = s.index(after: i) }
    }
    return result
}

func decodeEWBytes(_ charset: String, encoding: Character, encodedText: String) -> [UInt8] {
    if encoding == "B" || encoding == "b" {
        return base64Decode(Array(encodedText.utf8))
    } else {
        return qDecodeBytes(encodedText)
    }
}

func decodeRFC2047(_ text: String) -> String {
    var words: [(start: String.Index, end: String.Index, charset: String, encoding: Character, encodedText: String)] = []
    var pos = text.startIndex
    while pos < text.endIndex {
        while pos < text.endIndex && text[pos] != "=" { pos = text.index(after: pos) }
        if pos >= text.endIndex { break }
        let next = text.index(after: pos)
        if next >= text.endIndex || text[next] != "?" { pos = text.index(after: pos); continue }
        if let ew = tryParseEW(text, from: pos) {
            words.append(ew)
            pos = ew.end
        } else {
            pos = text.index(after: pos)
        }
    }
    if words.isEmpty { return text }

    var result = ""
    var lastPos = text.startIndex
    var i = 0
    while i < words.count {
        result += String(text[lastPos..<words[i].start])
        let baseCS = normalizeCS(words[i].charset)
        var j = i + 1
        while j < words.count {
            let between = String(text[words[j-1].end..<words[j].start])
            if between.allSatisfy({ $0 == " " || $0 == "\t" }) && normalizeCS(words[j].charset) == baseCS {
                j += 1
            } else { break }
        }
        var bytes: [UInt8] = []
        for k in i..<j {
            bytes.append(contentsOf: decodeEWBytes(words[k].charset, encoding: words[k].encoding, encodedText: words[k].encodedText))
        }
        result += decodeCharset(bytes, charset: words[i].charset)
        lastPos = words[j-1].end
        i = j
    }
    result += String(text[lastPos..<text.endIndex])
    return result
}

// MARK: - RFC 2231
func percentDecode(_ s: String) -> [UInt8] {
    var result: [UInt8] = []
    var i = s.startIndex
    while i < s.endIndex {
        if s[i] == "%" {
            let n1 = s.index(after: i)
            if n1 < s.endIndex {
                let n2 = s.index(after: n1)
                if n2 < s.endIndex {
                    let b1 = s[n1].asciiValue ?? 0
                    let b2 = s[n2].asciiValue ?? 0
                    if isHexDigit(b1) && isHexDigit(b2) {
                        result.append(hexVal(b1)*16+hexVal(b2))
                        i = s.index(after: n2)
                        continue
                    }
                }
            }
            result.append(0x25); i = s.index(after: i)
        } else {
            result.append(contentsOf: Array(String(s[i]).utf8))
            i = s.index(after: i)
        }
    }
    return result
}

func getRFC2231Value(params: [String: String], attr: String) -> String? {
    let a = attr.lowercased()
    // Single segment: a*
    if let val = params[a + "*"] {
        return decodeRFC2231Single(val)
    }
    // Continuation: a*0, a*1, ...
    var segments: [(index: Int, value: String, pct: Bool)] = []
    var idx = 0
    while true {
        let encName = a + "*" + String(idx) + "*"
        let plainName = a + "*" + String(idx)
        if let v = params[encName] { segments.append((idx, v, true)) }
        else if let v = params[plainName] { segments.append((idx, v, false)) }
        else { break }
        idx += 1
    }
    if segments.isEmpty { return nil }
    segments.sort { $0.index < $1.index }

    var allBytes: [UInt8] = []
    var charset = "us-ascii"
    for (si, seg) in segments.enumerated() {
        if seg.pct {
            var v = seg.value
            if si == 0 {
                if let q1 = v.firstIndex(of: "'") {
                    charset = String(v[v.startIndex..<q1])
                    let afterQ1 = v.index(after: q1)
                    if let q2 = v[afterQ1...].firstIndex(of: "'") {
                        v = String(v[v.index(after: q2)...])
                    } else {
                        v = String(v[afterQ1...])
                    }
                }
            }
            allBytes.append(contentsOf: percentDecode(v))
        } else {
            allBytes.append(contentsOf: Array(seg.value.utf8))
        }
    }
    return decodeCharset(allBytes, charset: charset)
}

func decodeRFC2231Single(_ val: String) -> String {
    var v = val
    var charset = "us-ascii"
    if let q1 = v.firstIndex(of: "'") {
        charset = String(v[v.startIndex..<q1])
        let afterQ1 = v.index(after: q1)
        if let q2 = v[afterQ1...].firstIndex(of: "'") {
            v = String(v[v.index(after: q2)...])
        } else {
            v = String(v[afterQ1...])
        }
    }
    let bytes = percentDecode(v)
    return decodeCharset(bytes, charset: charset)
}

// MARK: - MIME Parsing
func findBodyStart(_ data: [UInt8], lineBreak: [UInt8]) -> (headerEnd: Int, bodyStart: Int) {
    if data.count >= lineBreak.count {
        var match = true
        for j in 0..<lineBreak.count { if data[j] != lineBreak[j] { match = false; break } }
        if match { return (0, lineBreak.count) }
    }
    // Find lineBreak + lineBreak
    let dbl = lineBreak + lineBreak
    if dbl.isEmpty { return (data.count, data.count) }
    var i = 0
    while i + dbl.count <= data.count {
        var match = true
        for j in 0..<dbl.count { if data[i+j] != dbl[j] { match = false; break } }
        if match {
            let emptyStart = i + lineBreak.count
            return (emptyStart, emptyStart + lineBreak.count)
        }
        i += 1
    }
    return (data.count, data.count)
}

func unfoldAndSplit(_ data: [UInt8], lineBreak: [UInt8]) -> [[UInt8]] {
    var unfolded: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count {
            var match = true
            for j in 0..<lineBreak.count { if data[i+j] != lineBreak[j] { match = false; break } }
            if match {
                let after = i + lineBreak.count
                if after < data.count && (data[after] == 0x20 || data[after] == 0x09) {
                    i = after
                } else {
                    unfolded.append(contentsOf: lineBreak)
                    i = after
                }
                continue
            }
        }
        unfolded.append(data[i])
        i += 1
    }
    var lines: [[UInt8]] = []
    var start = 0
    while start < unfolded.count {
        var end = start
        while end < unfolded.count {
            if end + lineBreak.count <= unfolded.count {
                var match = true
                for j in 0..<lineBreak.count { if unfolded[end+j] != lineBreak[j] { match = false; break } }
                if match { break }
            }
            end += 1
        }
        lines.append(Array(unfolded[start..<end]))
        if end < unfolded.count { start = end + lineBreak.count } else { break }
    }
    return lines
}

func parseHeaders(_ data: [UInt8], lineBreak: [UInt8]) -> [String: String] {
    let lines = unfoldAndSplit(data, lineBreak: lineBreak)
    var headers: [String: String] = [:]
    for line in lines {
        guard let colonPos = line.firstIndex(of: 0x3A) else { continue }
        let nameBytes = Array(line[0..<colonPos])
        let name = String(bytes: nameBytes, encoding: .ascii)?.lowercased() ?? ""
        if name.isEmpty { continue }
        var vs = colonPos + 1
        while vs < line.count && (line[vs] == 0x20 || line[vs] == 0x09) { vs += 1 }
        var ve = line.count
        while ve > vs && (line[ve-1] == 0x20 || line[ve-1] == 0x09) { ve -= 1 }
        let val = String(bytes: Array(line[vs..<ve]), encoding: .ascii) ?? ""
        headers[name] = val
    }
    return headers
}

struct CTInfo {
    var type: String
    var subtype: String
    var params: [String: String]
}

func parseCT(_ value: String) -> CTInfo {
    var i = value.startIndex
    while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
    var typeStr = ""
    while i < value.endIndex && value[i] != "/" && value[i] != ";" && value[i] != " " && value[i] != "\t" {
        typeStr.append(value[i]); i = value.index(after: i)
    }
    while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
    if i < value.endIndex && value[i] == "/" { i = value.index(after: i) }
    while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
    var subStr = ""
    while i < value.endIndex && value[i] != ";" && value[i] != " " && value[i] != "\t" {
        subStr.append(value[i]); i = value.index(after: i)
    }
    var params: [String: String] = [:]
    while i < value.endIndex {
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        if i >= value.endIndex || value[i] != ";" { break }
        i = value.index(after: i)
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        var attr = ""
        while i < value.endIndex && value[i] != "=" && value[i] != " " && value[i] != "\t" && value[i] != ";" {
            attr.append(value[i]); i = value.index(after: i)
        }
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        if i >= value.endIndex || value[i] != "=" { break }
        i = value.index(after: i)
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        var val = ""
        if i < value.endIndex && value[i] == "\"" {
            i = value.index(after: i)
            while i < value.endIndex && value[i] != "\"" {
                if value[i] == "\\" {
                    i = value.index(after: i)
                    if i < value.endIndex { val.append(value[i]); i = value.index(after: i) }
                } else { val.append(value[i]); i = value.index(after: i) }
            }
            if i < value.endIndex { i = value.index(after: i) }
        } else {
            while i < value.endIndex && value[i] != ";" && value[i] != " " && value[i] != "\t" {
                val.append(value[i]); i = value.index(after: i)
            }
        }
        if !attr.isEmpty { params[attr.lowercased()] = val }
    }
    return CTInfo(type: typeStr.lowercased(), subtype: subStr.lowercased(), params: params)
}

struct CDInfo {
    var type: String
    var params: [String: String]
}

func parseCD(_ value: String) -> CDInfo {
    var i = value.startIndex
    while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
    var dtype = ""
    while i < value.endIndex && value[i] != ";" && value[i] != " " && value[i] != "\t" {
        dtype.append(value[i]); i = value.index(after: i)
    }
    var params: [String: String] = [:]
    while i < value.endIndex {
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        if i >= value.endIndex || value[i] != ";" { break }
        i = value.index(after: i)
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        var attr = ""
        while i < value.endIndex && value[i] != "=" && value[i] != " " && value[i] != "\t" && value[i] != ";" {
            attr.append(value[i]); i = value.index(after: i)
        }
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        if i >= value.endIndex || value[i] != "=" { break }
        i = value.index(after: i)
        while i < value.endIndex && (value[i] == " " || value[i] == "\t") { i = value.index(after: i) }
        var val = ""
        if i < value.endIndex && value[i] == "\"" {
            i = value.index(after: i)
            while i < value.endIndex && value[i] != "\"" {
                if value[i] == "\\" {
                    i = value.index(after: i)
                    if i < value.endIndex { val.append(value[i]); i = value.index(after: i) }
                } else { val.append(value[i]); i = value.index(after: i) }
            }
            if i < value.endIndex { i = value.index(after: i) }
        } else {
            while i < value.endIndex && value[i] != ";" && value[i] != " " && value[i] != "\t" {
                val.append(value[i]); i = value.index(after: i)
            }
        }
        if !attr.isEmpty { params[attr.lowercased()] = val }
    }
    return CDInfo(type: dtype.lowercased(), params: params)
}

struct Entity {
    var headers: [String: String]
    var body: [UInt8]
    var parts: [Entity]
}

func splitMultipart(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [[UInt8]] {
    // Split into lines
    var lines: [(content: [UInt8], hasLB: Bool)] = []
    var start = 0
    while start < body.count {
        var end = start
        while end < body.count {
            if end + lineBreak.count <= body.count {
                var match = true
                for j in 0..<lineBreak.count { if body[end+j] != lineBreak[j] { match = false; break } }
                if match { break }
            }
            end += 1
        }
        let hasLB = end < body.count
        lines.append((Array(body[start..<end]), hasLB))
        if hasLB { start = end + lineBreak.count } else { break }
    }

    let delimPrefix = Array(("--" + boundary).utf8)
    let closePrefix = Array(("--" + boundary + "--").utf8)

    func isDelim(_ content: [UInt8], _ prefix: [UInt8]) -> Bool {
        if content.count < prefix.count { return false }
        for j in 0..<prefix.count { if content[j] != prefix[j] { return false } }
        for j in prefix.count..<content.count {
            if content[j] != 0x20 && content[j] != 0x09 { return false }
        }
        return true
    }

    var delimIndices: [Int] = []
    var closeIdx: Int? = nil
    for (i, (content, _)) in lines.enumerated() {
        if isDelim(content, closePrefix) { closeIdx = i; break }
        if isDelim(content, delimPrefix) { delimIndices.append(i) }
    }

    guard let close = closeIdx, !delimIndices.isEmpty else { return [] }
    let allB = delimIndices + [close]

    var parts: [[UInt8]] = []
    for i in 0..<(allB.count - 1) {
        let s = allB[i] + 1
        let e = allB[i + 1]
        var partData: [UInt8] = []
        for j in s..<e {
            partData.append(contentsOf: lines[j].content)
            if lines[j].hasLB && j < e - 1 {
                partData.append(contentsOf: lineBreak)
            }
        }
        parts.append(partData)
    }
    return parts
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    let (hEnd, bStart) = findBodyStart(data, lineBreak: lineBreak)
    let headerData = Array(data[0..<hEnd])
    let bodyData = Array(data[bStart...])
    let headers = parseHeaders(headerData, lineBreak: lineBreak)

    let ctValue = headers["content-type"]
    var ct: CTInfo
    if let cv = ctValue {
        ct = parseCT(cv)
    } else {
        ct = CTInfo(type: "text", subtype: "plain", params: [:])
    }

    var parts: [Entity] = []
    if ct.type == "multipart" {
        if let boundary = ct.params["boundary"] {
            let partDatas = splitMultipart(bodyData, boundary: boundary, lineBreak: lineBreak)
            parts = partDatas.map { parseEntity($0, lineBreak: lineBreak) }
        }
    }

    return Entity(headers: headers, body: bodyData, parts: parts)
}

// MARK: - Output
func quotedStr(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default:
            if scalar.value < 0x20 || (scalar.value >= 0x7F && scalar.value <= 0x9F) {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

func getEntityName(entity: Entity) -> String? {
    let cdValue = entity.headers["content-disposition"]
    let ctValue = entity.headers["content-type"]

    var cdParams: [String: String] = [:]
    var ctParams: [String: String] = [:]
    if let cv = cdValue { cdParams = parseCD(cv).params }
    if let cv = ctValue { ctParams = parseCT(cv).params }

    // 1. CD filename RFC2231
    if let v = getRFC2231Value(params: cdParams, attr: "filename") { return v }
    // 2. CD filename regular
    if let v = cdParams["filename"] { return decodeRFC2047(v) }
    // 3. CT name RFC2231
    if let v = getRFC2231Value(params: ctParams, attr: "name") { return v }
    // 4. CT name regular
    if let v = ctParams["name"] { return decodeRFC2047(v) }
    return nil
}

func getCT(entity: Entity) -> CTInfo {
    if let cv = entity.headers["content-type"] { return parseCT(cv) }
    return CTInfo(type: "text", subtype: "plain", params: [:])
}

func getCD(entity: Entity) -> CDInfo? {
    if let cv = entity.headers["content-disposition"] { return parseCD(cv) }
    return nil
}

func getCTE(entity: Entity) -> String {
    return (entity.headers["content-transfer-encoding"] ?? "7bit").lowercased()
}

func transferDecode(_ body: [UInt8], cte: String, lineBreak: [UInt8]) -> [UInt8] {
    switch cte {
    case "base64": return base64Decode(body)
    case "quoted-printable": return decodeQP(body, lineBreak: lineBreak)
    default: return body
    }
}

func normalizeLineEnds(_ bytes: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var i = 0
    while i < bytes.count {
        if bytes[i] == 0x0D {
            if i + 1 < bytes.count && bytes[i+1] == 0x0A {
                result.append(0x0A); i += 2
            } else {
                result.append(0x0A); i += 1
            }
        } else {
            result.append(bytes[i]); i += 1
        }
    }
    return result
}

func printEntity(_ entity: Entity, indent: Int, lineBreak: [UInt8], output: inout [String]) {
    let prefix = String(repeating: "  ", count: indent)
    let ct = getCT(entity)
    let cd = getCD(entity)
    let cte = getCTE(entity)

    if ct.type == "multipart" {
        output.append("\(prefix)multipart/\(ct.subtype) parts=\(entity.parts.count)")
        for part in entity.parts {
            printEntity(part, indent: indent + 1, lineBreak: lineBreak, output: &output)
        }
    } else {
        let isText = ct.type == "text" && (cd == nil || cd!.type != "attachment")
        if isText {
            let charset = ct.params["charset"] ?? "us-ascii"
            let decodedBytes = transferDecode(entity.body, cte: cte, lineBreak: lineBreak)
            let normalized = normalizeLineEnds(decodedBytes)
            let text = decodeCharset(normalized, charset: charset)
            let charCount = text.count
            output.append("\(prefix)text/\(ct.subtype) charset=\(charset.lowercased()) cte=\(cte) chars=\(charCount)")
            output.append("\(prefix)  \(quotedStr(text))")
        } else {
            let decodedBytes = transferDecode(entity.body, cte: cte, lineBreak: lineBreak)
            let size = decodedBytes.count
            let crc = crc32(decodedBytes)
            let disp = cd?.type ?? "-"
            let name = getEntityName(entity: entity)
            let nameStr = name != nil ? quotedStr(name!) : "-"
            output.append("\(prefix)\(ct.type)/\(ct.subtype) cte=\(cte) disposition=\(disp) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))")
        }
    }
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let files = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }
let emlFiles = files.filter { $0.hasSuffix(".eml") }.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

var allOutput: [String] = []
for (fi, fname) in emlFiles.enumerated() {
    if fi > 0 { allOutput.append("") }
    let path = dir + "/" + fname
    guard let fileData = fm.contents(atPath: path) else { continue }
    let bytes = [UInt8](fileData)

    // Detect line break
    var lineBreak: [UInt8] = [0x0A]
    for i in 0..<bytes.count {
        if bytes[i] == 0x0D && i + 1 < bytes.count && bytes[i+1] == 0x0A {
            lineBreak = [0x0D, 0x0A]
            break
        }
    }

    allOutput.append("== \(fname)")

    let entity = parseEntity(bytes, lineBreak: lineBreak)

    let fromVal = entity.headers["from"]
    let subjVal = entity.headers["subject"]

    let fromStr = fromVal != nil ? quotedStr(decodeRFC2047(fromVal!)) : "-"
    let subjStr = subjVal != nil ? quotedStr(decodeRFC2047(subjVal!)) : "-"

    allOutput.append("From: \(fromStr)")
    allOutput.append("Subject: \(subjStr)")

    printEntity(entity, indent: 0, lineBreak: lineBreak, output: &allOutput)
}

for line in allOutput {
    print(line)
}

use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let mut files: Vec<String> = fs::read_dir(dir)
        .unwrap()
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().to_string())
        .filter(|n| n.ends_with(".eml"))
        .collect();
    files.sort();
    let mut first = true;
    for fname in &files {
        if !first { println!(); }
        first = false;
        let path = Path::new(dir).join(fname);
        let data = fs::read(&path).unwrap();
        process_message(fname, &data);
    }
}

fn detect_lb(data: &[u8]) -> &'static [u8] {
    for i in 0..data.len() {
        if data[i] == b'\r' && i + 1 < data.len() && data[i + 1] == b'\n' {
            return b"\r\n";
        }
        if data[i] == b'\n' {
            return b"\n";
        }
    }
    b"\n"
}

struct Entity {
    headers: Vec<(String, String)>,
    body: Vec<u8>,
    parts: Vec<Entity>,
}

fn split_into_lines(data: &[u8], lb: &[u8]) -> Vec<&[u8]> {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i + lb.len() <= data.len() {
        if &data[i..i + lb.len()] == lb {
            lines.push(&data[start..i]);
            start = i + lb.len();
            i += lb.len();
        } else {
            i += 1;
        }
    }
    lines.push(&data[start..]);
    lines
}

fn compute_line_starts(data: &[u8], lb: &[u8]) -> Vec<usize> {
    let mut starts = vec![0usize];
    let mut i = 0;
    while i + lb.len() <= data.len() {
        if &data[i..i + lb.len()] == lb {
            starts.push(i + lb.len());
            i += lb.len();
        } else {
            i += 1;
        }
    }
    starts
}

fn unfold_headers(lines: &[&[u8]]) -> Vec<String> {
    let mut result: Vec<String> = Vec::new();
    for line in lines {
        if !line.is_empty() && (line[0] == b' ' || line[0] == b'\t') {
            if let Some(last) = result.last_mut() {
                last.push_str(&String::from_utf8_lossy(line));
            }
        } else {
            result.push(String::from_utf8_lossy(line).into_owned());
        }
    }
    result
}

fn parse_headers(lines: &[String]) -> Vec<(String, String)> {
    let mut headers = Vec::new();
    for line in lines {
        if let Some(colon) = line.find(':') {
            let name = line[..colon].trim().to_lowercase();
            let value = line[colon + 1..].trim_matches(|c| c == ' ' || c == '\t').to_string();
            headers.push((name, value));
        }
    }
    headers
}

fn get_header<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers.iter().find(|(n, _)| n == name).map(|(_, v)| v.as_str())
}

fn parse_params(input: &str) -> Vec<(String, String)> {
    let mut params = Vec::new();
    let mut s = input;
    loop {
        s = s.trim_start_matches(|c| c == ' ' || c == '\t');
        if s.is_empty() { break; }
        let eq_pos = match s.find('=') {
            Some(p) => p,
            None => break,
        };
        let attr = s[..eq_pos].trim_end_matches(|c| c == ' ' || c == '\t').to_lowercase();
        s = &s[eq_pos + 1..];
        s = s.trim_start_matches(|c| c == ' ' || c == '\t');
        let (value, rest) = if s.starts_with('"') {
            parse_quoted_string(s)
        } else {
            let end = s.find(';').unwrap_or(s.len());
            (s[..end].trim_end_matches(|c| c == ' ' || c == '\t').to_string(), &s[end..])
        };
        params.push((attr, value));
        if rest.starts_with(';') {
            s = &rest[1..];
        } else {
            break;
        }
    }
    params
}

fn parse_quoted_string(s: &str) -> (String, &str) {
    let bytes = s.as_bytes();
    let mut result = String::new();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'\\' && i + 1 < bytes.len() {
            result.push(bytes[i + 1] as char);
            i += 2;
        } else if bytes[i] == b'"' {
            i += 1;
            break;
        } else {
            result.push(bytes[i] as char);
            i += 1;
        }
    }
    (result, &s[i..])
}

fn parse_content_type(value: &str) -> (String, String, Vec<(String, String)>) {
    let value = value.trim();
    let (type_sub, params_str) = if let Some(idx) = value.find(';') {
        (&value[..idx], &value[idx + 1..])
    } else {
        (value, "")
    };
    let type_sub = type_sub.trim();
    let (type_, subtype) = if let Some(idx) = type_sub.find('/') {
        (
            type_sub[..idx].trim().to_lowercase(),
            type_sub[idx + 1..].trim().to_lowercase(),
        )
    } else {
        (type_sub.to_lowercase(), String::new())
    };
    let params = parse_params(params_str);
    (type_, subtype, params)
}

fn parse_entity(data: &[u8], lb: &[u8]) -> Entity {
    let lines = split_into_lines(data, lb);
    let starts = compute_line_starts(data, lb);
    let sep_idx = lines.iter().position(|l| l.is_empty());
    let (header_lines, body) = if let Some(idx) = sep_idx {
        let hl: Vec<&[u8]> = lines[..idx].to_vec();
        let body_start = if idx + 1 < starts.len() { starts[idx + 1] } else { data.len() };
        (hl, data[body_start..].to_vec())
    } else {
        (lines.to_vec(), Vec::new())
    };
    let unfolded = unfold_headers(&header_lines);
    let headers = parse_headers(&unfolded);
    let ct_val = get_header(&headers, "content-type").unwrap_or("text/plain");
    let (type_, subtype, ct_params) = parse_content_type(ct_val);
    let is_multipart = type_ == "multipart";
    let parts = if is_multipart {
        let boundary = ct_params.iter()
            .find(|(n, _)| n == "boundary")
            .map(|(_, v)| v.clone())
            .unwrap_or_default();
        parse_multipart_parts(&body, lb, &boundary)
    } else {
        Vec::new()
    };
    Entity { headers, body, parts }
}

fn is_delimiter(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 2 + boundary.len();
    if line.len() < prefix_len { return false; }
    if &line[..2] != b"--" { return false; }
    if &line[2..prefix_len] != boundary { return false; }
    line[prefix_len..].iter().all(|&b| b == b' ' || b == b'\t')
}

fn is_close_delimiter(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 2 + boundary.len() + 2;
    if line.len() < prefix_len { return false; }
    if &line[..2] != b"--" { return false; }
    if &line[2..2 + boundary.len()] != boundary { return false; }
    if &line[2 + boundary.len()..prefix_len] != b"--" { return false; }
    line[prefix_len..].iter().all(|&b| b == b' ' || b == b'\t')
}

fn parse_multipart_parts(body: &[u8], lb: &[u8], boundary: &str) -> Vec<Entity> {
    let lines = split_into_lines(body, lb);
    let starts = compute_line_starts(body, lb);
    let bnd = boundary.as_bytes();
    let mut delim_indices: Vec<usize> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        if is_delimiter(line, bnd) || is_close_delimiter(line, bnd) {
            delim_indices.push(i);
        }
    }
    if delim_indices.len() < 2 {
        return Vec::new();
    }
    let mut parts = Vec::new();
    for i in 0..delim_indices.len() - 1 {
        let di = delim_indices[i];
        let dj = delim_indices[i + 1];
        let part_start = if di + 1 < starts.len() { starts[di + 1] } else { body.len() };
        let part_end = if starts[dj] >= lb.len() { starts[dj] - lb.len() } else { 0 };
        let part_data: &[u8] = if part_end > part_start {
            &body[part_start..part_end]
        } else {
            b""
        };
        parts.push(parse_entity(part_data, lb));
    }
    parts
}

fn transfer_decode(body: &[u8], cte: &str, lb: &[u8]) -> Vec<u8> {
    match cte {
        "base64" => base64_decode(body),
        "quoted-printable" => qp_decode(body, lb),
        _ => body.to_vec(),
    }
}

fn base64_decode(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;
    for &b in data {
        let val = match b {
            b'A'..=b'Z' => (b - b'A') as u32,
            b'a'..=b'z' => (b - b'a' + 26) as u32,
            b'0'..=b'9' => (b - b'0' + 52) as u32,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            _ => continue,
        };
        buf = (buf << 6) | val;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            result.push((buf >> bits) as u8);
        }
    }
    result
}

fn qp_decode(data: &[u8], lb: &[u8]) -> Vec<u8> {
    let lines = split_into_lines(data, lb);
    let mut joined = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let mut end = line.len();
        while end > 0 && (line[end - 1] == b' ' || line[end - 1] == b'\t') {
            end -= 1;
        }
        let stripped = &line[..end];
        if stripped.ends_with(b"=") && i < lines.len() - 1 {
            joined.extend_from_slice(&stripped[..stripped.len() - 1]);
        } else {
            joined.extend_from_slice(stripped);
            if i < lines.len() - 1 {
                joined.extend_from_slice(lb);
            }
        }
    }
    let mut result = Vec::new();
    let mut i = 0;
    while i < joined.len() {
        if joined[i] == b'=' && i + 2 < joined.len() {
            let h1 = hex_val(joined[i + 1]);
            let h2 = hex_val(joined[i + 2]);
            if let (Some(h1), Some(h2)) = (h1, h2) {
                result.push((h1 << 4) | h2);
                i += 3;
            } else {
                result.push(b'=');
                i += 1;
            }
        } else {
            result.push(joined[i]);
            i += 1;
        }
    }
    result
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn decode_charset(data: &[u8], charset: &str) -> String {
    match charset {
        "us-ascii" | "utf-8" => String::from_utf8_lossy(data).into_owned(),
        "iso-8859-1" => data.iter().map(|&b| char::from_u32(b as u32).unwrap()).collect(),
        "windows-1252" => data.iter().map(|&b| windows_1252_char(b)).collect(),
        _ => String::from_utf8_lossy(data).into_owned(),
    }
}

fn windows_1252_char(b: u8) -> char {
    if b < 0x80 || b > 0x9F {
        return char::from_u32(b as u32).unwrap();
    }
    let cp: u32 = match b {
        0x80 => 0x20AC, 0x81 => 0x0081, 0x82 => 0x201A, 0x83 => 0x0192,
        0x84 => 0x201E, 0x85 => 0x2026, 0x86 => 0x2020, 0x87 => 0x2021,
        0x88 => 0x02C6, 0x89 => 0x2030, 0x8A => 0x0160, 0x8B => 0x2039,
        0x8C => 0x0152, 0x8D => 0x008D, 0x8E => 0x017D, 0x8F => 0x008F,
        0x90 => 0x0090, 0x91 => 0x2018, 0x92 => 0x2019, 0x93 => 0x201C,
        0x94 => 0x201D, 0x95 => 0x2022, 0x96 => 0x2013, 0x97 => 0x2014,
        0x98 => 0x02DC, 0x99 => 0x2122, 0x9A => 0x0161, 0x9B => 0x203A,
        0x9C => 0x0153, 0x9D => 0x009D, 0x9E => 0x017E, 0x9F => 0x0178,
        _ => unreachable!(),
    };
    char::from_u32(cp).unwrap()
}

struct EncodedWord {
    start: usize,
    end: usize,
    charset: String,
    encoding: u8,
    encoded_text: Vec<u8>,
}

fn decode_rfc2047(input: &str) -> String {
    let bytes = input.as_bytes();
    let words = find_encoded_words(bytes);
    if words.is_empty() {
        return input.to_string();
    }
    let groups = group_words(&words, bytes);
    let mut result = String::new();
    let mut pos = 0;
    for group in &groups {
        let group_start = words[group[0]].start;
        let group_end = words[group[group.len() - 1]].end;
        result.push_str(&String::from_utf8_lossy(&bytes[pos..group_start]));
        let decoded = decode_group(&words, group);
        result.push_str(&decoded);
        pos = group_end;
    }
    result.push_str(&String::from_utf8_lossy(&bytes[pos..]));
    result
}

fn find_encoded_words(data: &[u8]) -> Vec<EncodedWord> {
    let mut words = Vec::new();
    let mut i = 0;
    while i + 1 < data.len() {
        if data[i] == b'=' && data[i + 1] == b'?' {
            if let Some(w) = try_match_ew(data, i) {
                i = w.end;
                words.push(w);
                continue;
            }
        }
        i += 1;
    }
    words
}

fn try_match_ew(data: &[u8], start: usize) -> Option<EncodedWord> {
    let mut i = start;
    if data[i] != b'=' || data[i + 1] != b'?' { return None; }
    i += 2;
    let cs_start = i;
    while i < data.len() && data[i] != b'?' && data[i] != b' ' && data[i] != b'\t' {
        i += 1;
    }
    if i == cs_start { return None; }
    let charset_raw = &data[cs_start..i];
    if i >= data.len() || data[i] != b'?' { return None; }
    i += 1;
    if i >= data.len() { return None; }
    let enc = data[i];
    if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' { return None; }
    i += 1;
    if i >= data.len() || data[i] != b'?' { return None; }
    i += 1;
    let et_start = i;
    while i < data.len() && data[i] != b'?' && data[i] != b' ' && data[i] != b'\t' {
        i += 1;
    }
    let encoded_text = data[et_start..i].to_vec();
    if i + 1 >= data.len() || data[i] != b'?' || data[i + 1] != b'=' { return None; }
    i += 2;
    let cs_str = String::from_utf8_lossy(charset_raw).to_lowercase();
    let charset = if let Some(pos) = cs_str.find('*') {
        cs_str[..pos].to_string()
    } else {
        cs_str
    };
    Some(EncodedWord {
        start,
        end: i,
        charset,
        encoding: enc.to_ascii_uppercase(),
        encoded_text,
    })
}

fn group_words(words: &[EncodedWord], data: &[u8]) -> Vec<Vec<usize>> {
    let mut groups: Vec<Vec<usize>> = Vec::new();
    for i in 0..words.len() {
        let mut can_group = false;
        if let Some(last_group) = groups.last() {
            let last_idx = *last_group.last().unwrap();
            let prev_end = words[last_idx].end;
            let curr_start = words[i].start;
            let between = &data[prev_end..curr_start];
            if between.iter().all(|&b| b == b' ' || b == b'\t') {
                if words[last_idx].charset == words[i].charset {
                    can_group = true;
                }
            }
        }
        if can_group {
            groups.last_mut().unwrap().push(i);
        } else {
            groups.push(vec![i]);
        }
    }
    groups
}

fn decode_group(words: &[EncodedWord], group: &[usize]) -> String {
    let mut all_bytes = Vec::new();
    for &idx in group {
        let w = &words[idx];
        let bytes = match w.encoding {
            b'B' => base64_decode(&w.encoded_text),
            b'Q' => q_decode_rfc2047(&w.encoded_text),
            _ => Vec::new(),
        };
        all_bytes.extend_from_slice(&bytes);
    }
    decode_charset(&all_bytes, &words[group[0]].charset)
}

fn q_decode_rfc2047(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'_' {
            result.push(b' ');
            i += 1;
        } else if data[i] == b'=' && i + 2 < data.len() {
            let h1 = hex_val(data[i + 1]);
            let h2 = hex_val(data[i + 2]);
            if let (Some(h1), Some(h2)) = (h1, h2) {
                result.push((h1 << 4) | h2);
                i += 3;
            } else {
                result.push(b'=');
                i += 1;
            }
        } else {
            result.push(data[i]);
            i += 1;
        }
    }
    result
}

fn get_filename(entity: &Entity) -> Option<String> {
    let cd_val = get_header(&entity.headers, "content-disposition");
    if let Some(cd) = cd_val {
        let (_, _, cd_params) = parse_content_type(cd);
        if let Some(name) = get_rfc2231_param(&cd_params, "filename") {
            return Some(name);
        }
    }
    let ct_val = get_header(&entity.headers, "content-type");
    if let Some(ct) = ct_val {
        let (_, _, ct_params) = parse_content_type(ct);
        if let Some(name) = get_rfc2231_param(&ct_params, "name") {
            return Some(name);
        }
    }
    None
}

fn get_rfc2231_param(params: &[(String, String)], attr: &str) -> Option<String> {
    let single_key = format!("{}*", attr);
    let has_single = params.iter().any(|(n, _)| n == &single_key);
    let prefix = format!("{}*", attr);
    let mut segments: Vec<(usize, bool, String)> = Vec::new();
    for (name, value) in params {
        if let Some(rest) = name.strip_prefix(&prefix) {
            if rest.is_empty() { continue; }
            if let Some(inner) = rest.strip_suffix('*') {
                if let Ok(idx) = inner.parse::<usize>() {
                    segments.push((idx, true, value.clone()));
                }
            } else if let Ok(idx) = rest.parse::<usize>() {
                segments.push((idx, false, value.clone()));
            }
        }
    }
    if has_single {
        let value = params.iter().find(|(n, _)| n == &single_key).unwrap().1.clone();
        let decoded = percent_decode(&value);
        let (charset, bytes) = extract_charset_prefix(&decoded);
        return Some(decode_charset(&bytes, &charset));
    }
    if !segments.is_empty() {
        segments.sort_by_key(|(idx, _, _)| *idx);
        let mut charset = "us-ascii".to_string();
        let mut all_bytes = Vec::new();
        let mut first_encoded = true;
        for (_, is_encoded, value) in &segments {
            if *is_encoded {
                let decoded = percent_decode(value);
                if first_encoded {
                    let (cs, bytes) = extract_charset_prefix(&decoded);
                    charset = cs;
                    all_bytes.extend_from_slice(&bytes);
                    first_encoded = false;
                } else {
                    all_bytes.extend_from_slice(&decoded);
                }
            } else {
                all_bytes.extend_from_slice(value.as_bytes());
            }
        }
        return Some(decode_charset(&all_bytes, &charset));
    }
    if let Some((_, value)) = params.iter().find(|(n, _)| n == attr) {
        return Some(decode_rfc2047(value));
    }
    None
}

fn extract_charset_prefix(data: &[u8]) -> (String, Vec<u8>) {
    if let Some(q1) = data.iter().position(|&b| b == b'\'') {
        let charset = String::from_utf8_lossy(&data[..q1]).to_lowercase();
        if let Some(q2) = data[q1 + 1..].iter().position(|&b| b == b'\'') {
            let value_start = q1 + 1 + q2 + 1;
            return (charset, data[value_start..].to_vec());
        }
    }
    ("us-ascii".to_string(), data.to_vec())
}

fn percent_decode(s: &str) -> Vec<u8> {
    let bytes = s.as_bytes();
    let mut result = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let h1 = hex_val(bytes[i + 1]);
            let h2 = hex_val(bytes[i + 2]);
            if let (Some(h1), Some(h2)) = (h1, h2) {
                result.push((h1 << 4) | h2);
                i += 3;
            } else {
                result.push(b'%');
                i += 1;
            }
        } else {
            result.push(bytes[i]);
            i += 1;
        }
    }
    result
}

fn quote_string(s: &str) -> String {
    let mut result = String::from("\"");
    for ch in s.chars() {
        match ch {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 || ((c as u32) >= 0x7F && (c as u32) <= 0x9F) => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB8_8320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFF_FFFF
}

fn process_message(fname: &str, data: &[u8]) {
    let lb = detect_lb(data);
    let entity = parse_entity(data, lb);
    println!("== {}", fname);
    let from = get_header(&entity.headers, "from").map(|v| decode_rfc2047(v));
    match from {
        Some(v) => println!("From: {}", quote_string(&v)),
        None => println!("From: -"),
    }
    let subject = get_header(&entity.headers, "subject").map(|v| decode_rfc2047(v));
    match subject {
        Some(v) => println!("Subject: {}", quote_string(&v)),
        None => println!("Subject: -"),
    }
    print_entity(&entity, 0, lb);
}

fn print_entity(entity: &Entity, depth: usize, lb: &[u8]) {
    let indent = "  ".repeat(depth);
    let ct_val = get_header(&entity.headers, "content-type").unwrap_or("text/plain");
    let (type_, subtype, ct_params) = parse_content_type(ct_val);
    let cte_val = get_header(&entity.headers, "content-transfer-encoding")
        .map(|v| v.trim().to_lowercase())
        .unwrap_or_else(|| "7bit".to_string());
    let is_multipart = type_ == "multipart";
    if is_multipart {
        println!("{}multipart/{} parts={}", indent, subtype, entity.parts.len());
        for part in &entity.parts {
            print_entity(part, depth + 1, lb);
        }
    } else {
        let cd_val = get_header(&entity.headers, "content-disposition");
        let cd_type = if let Some(cd) = cd_val {
            let (dt, _, _) = parse_content_type(cd);
            Some(dt)
        } else {
            None
        };
        let is_text = type_ == "text" && cd_type.as_deref().map_or(true, |d| d != "attachment");
        if is_text {
            let charset = ct_params.iter()
                .find(|(n, _)| n == "charset")
                .map(|(_, v)| v.to_lowercase())
                .unwrap_or_else(|| "us-ascii".to_string());
            let decoded_bytes = transfer_decode(&entity.body, &cte_val, lb);
            let mut text = decode_charset(&decoded_bytes, &charset);
            text = text.replace("\r\n", "\n");
            text = text.replace('\r', "\n");
            let chars = text.chars().count();
            println!("{}text/{} charset={} cte={} chars={}", indent, subtype, charset, cte_val, chars);
            println!("{}  {}", indent, quote_string(&text));
        } else {
            let decoded_bytes = transfer_decode(&entity.body, &cte_val, lb);
            let size = decoded_bytes.len();
            let crc = crc32(&decoded_bytes);
            let name = get_filename(entity);
            let disp = cd_type.unwrap_or_else(|| "-".to_string());
            let name_str = match name {
                Some(n) => quote_string(&n),
                None => "-".to_string(),
            };
            println!(
                "{}{}/{} cte={} disposition={} name={} size={} crc32={:08x}",
                indent, type_, subtype, cte_val, disp, name_str, size, crc
            );
        }
    }
}

#!/usr/bin/env python3
import sys
import os
import zlib
import base64
import re


def is_hex(c):
    return c in '0123456789abcdefABCDEF'


def is_hex_byte(b):
    return b in b'0123456789abcdefABCDEF'


def parse_params(i, value):
    params = {}
    n = len(value)
    while i < n:
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        if value[i] != ';':
            break
        i += 1
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        start = i
        while i < n and value[i] not in ' \t=':
            i += 1
        attr = value[start:i].lower()
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n or value[i] != '=':
            continue
        i += 1
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        if value[i] == '"':
            i += 1
            val_chars = []
            while i < n:
                if value[i] == '\\' and i + 1 < n:
                    val_chars.append(value[i + 1])
                    i += 2
                elif value[i] == '"':
                    i += 1
                    break
                else:
                    val_chars.append(value[i])
                    i += 1
            val = ''.join(val_chars)
        else:
            start = i
            while i < n and value[i] not in ' \t;':
                i += 1
            val = value[start:i]
        params[attr] = val
    return params


def parse_content_type(value):
    i = 0
    n = len(value)
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t/;':
        i += 1
    type_part = value[start:i].lower()
    while i < n and value[i] in ' \t':
        i += 1
    if i < n and value[i] == '/':
        i += 1
    else:
        return type_part, '', {}
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t;':
        i += 1
    subtype = value[start:i].lower()
    params = parse_params(i, value)
    return type_part, subtype, params


def parse_content_disposition(value):
    i = 0
    n = len(value)
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t;':
        i += 1
    disp_type = value[start:i].lower()
    params = parse_params(i, value)
    return disp_type, params


def parse_headers(header_bytes, line_break):
    if not header_bytes:
        return []
    lines = header_bytes.split(line_break)
    logical_lines = []
    for line in lines:
        if line and (line[0:1] == b' ' or line[0:1] == b'\t'):
            if logical_lines:
                logical_lines[-1] += line
            else:
                logical_lines.append(line)
        else:
            logical_lines.append(line)
    headers = []
    for line in logical_lines:
        if b':' in line:
            name, value = line.split(b':', 1)
            name = name.decode('ascii').lower()
            value = value.strip(b' \t').decode('ascii')
            headers.append((name, value))
    return headers


def get_header_value(headers, name):
    for n, v in headers:
        if n == name:
            return v
    return None


def get_content_type(headers):
    v = get_header_value(headers, 'content-type')
    if v is not None:
        return parse_content_type(v)
    return ('text', 'plain', {})


def get_cte(headers):
    v = get_header_value(headers, 'content-transfer-encoding')
    if v is not None:
        return v.lower()
    return '7bit'


def get_disposition(headers):
    v = get_header_value(headers, 'content-disposition')
    if v is not None:
        disp_type, _ = parse_content_disposition(v)
        return disp_type
    return None


def get_params(headers, header_name):
    v = get_header_value(headers, header_name)
    if v is None:
        return None
    if header_name == 'content-type':
        _, _, params = parse_content_type(v)
        return params
    elif header_name == 'content-disposition':
        _, params = parse_content_disposition(v)
        return params
    return None


def transfer_decode(body_bytes, cte, line_break):
    if cte in ('7bit', '8bit', 'binary'):
        return body_bytes
    elif cte == 'base64':
        return base64_decode_body(body_bytes)
    elif cte == 'quoted-printable':
        return qp_decode(body_bytes, line_break)
    else:
        return body_bytes


def base64_decode_body(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    filtered = bytearray()
    for b in data:
        if b == ord('='):
            break
        if b in alphabet:
            filtered.append(b)
    filtered = bytes(filtered)
    padding = (4 - len(filtered) % 4) % 4
    filtered += b'=' * padding
    try:
        return base64.b64decode(filtered)
    except Exception:
        return b''


def qp_decode(data, line_break):
    lines = data.split(line_break)
    trimmed = []
    for line in lines:
        while line and line[-1:] in (b' ', b'\t'):
            line = line[:-1]
        trimmed.append(line)
    text = b'\n'.join(trimmed)
    result = bytearray()
    i = 0
    n = len(text)
    while i < n:
        if text[i:i + 1] == b'=':
            if i + 2 < n and is_hex_byte(text[i + 1]) and is_hex_byte(text[i + 2]):
                result.append(int(text[i + 1:i + 3], 16))
                i += 3
            elif i + 1 < n and text[i + 1:i + 2] == b'\n':
                if i + 3 < n and is_hex_byte(text[i + 2]) and is_hex_byte(text[i + 3]):
                    result.append(int(text[i + 2:i + 4], 16))
                    i += 4
                else:
                    i += 2
            else:
                result.append(0x3D)
                i += 1
        else:
            result.append(text[i])
            i += 1
    return bytes(result)


def decode_bytes(data, charset):
    charset = charset.lower()
    if charset == 'us-ascii':
        return data.decode('ascii')
    elif charset == 'utf-8':
        return data.decode('utf-8')
    elif charset == 'iso-8859-1':
        return data.decode('latin-1')
    elif charset == 'windows-1252':
        return data.decode('cp1252')
    else:
        return data.decode('ascii', errors='replace')


def normalize_charset(cs):
    if '*' in cs:
        cs = cs[:cs.index('*')]
    return cs.lower()


def base64_decode_2047(text):
    text = text.rstrip('=')
    padding = (4 - len(text) % 4) % 4
    text += '=' * padding
    try:
        return base64.b64decode(text)
    except Exception:
        return b''


def q_decode_2047(text):
    result = bytearray()
    i = 0
    while i < len(text):
        if text[i] == '_':
            result.append(0x20)
            i += 1
        elif text[i] == '=' and i + 2 < len(text) and is_hex(text[i + 1]) and is_hex(text[i + 2]):
            result.append(int(text[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(text[i]))
            i += 1
    return bytes(result)


def decode_encoded_words(text):
    pattern = re.compile(r'=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=')
    matches = list(pattern.finditer(text))
    if not matches:
        return text
    groups = []
    current_group = [matches[0]]
    for i in range(1, len(matches)):
        prev = current_group[-1]
        curr = matches[i]
        between = text[prev.end():curr.start()]
        if all(c in ' \t' for c in between):
            prev_charset = normalize_charset(prev.group(1))
            curr_charset = normalize_charset(curr.group(1))
            if prev_charset == curr_charset:
                current_group.append(curr)
            else:
                groups.append(current_group)
                current_group = [curr]
        else:
            groups.append(current_group)
            current_group = [curr]
    groups.append(current_group)
    result = []
    pos = 0
    for group in groups:
        result.append(text[pos:group[0].start()])
        charset = normalize_charset(group[0].group(1))
        all_bytes = b''
        for m in group:
            encoding = m.group(2).upper()
            encoded_text = m.group(3)
            if encoding == 'B':
                all_bytes += base64_decode_2047(encoded_text)
            else:
                all_bytes += q_decode_2047(encoded_text)
        decoded = decode_bytes(all_bytes, charset)
        result.append(decoded)
        pos = group[-1].end()
    result.append(text[pos:])
    return ''.join(result)


def percent_decode(text):
    result = bytearray()
    i = 0
    while i < len(text):
        if text[i] == '%' and i + 2 < len(text) and is_hex(text[i + 1]) and is_hex(text[i + 2]):
            result.append(int(text[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(text[i]))
            i += 1
    return bytes(result)


def decode_rfc2231_encoded(value):
    first_quote = value.index("'")
    second_quote = value.index("'", first_quote + 1)
    charset = value[:first_quote]
    percent_part = value[second_quote + 1:]
    raw_bytes = percent_decode(percent_part)
    return decode_bytes(raw_bytes, charset.lower())


def get_rfc2231_param(params, attr):
    single_key = attr + '*'
    if single_key in params:
        return decode_rfc2231_encoded(params[single_key])
    segments = {}
    prefix = attr + '*'
    for key, value in params.items():
        if not key.startswith(prefix):
            continue
        rest = key[len(prefix):]
        if rest == '':
            continue
        if rest.endswith('*'):
            idx_str = rest[:-1]
            encoded = True
        else:
            idx_str = rest
            encoded = False
        try:
            idx = int(idx_str)
        except ValueError:
            continue
        segments[idx] = (value, encoded)
    if not segments:
        return None
    indices = sorted(segments.keys())
    charset = None
    all_bytes = b''
    first_encoded_seen = False
    for idx in indices:
        value, encoded = segments[idx]
        if encoded:
            if not first_encoded_seen:
                first_quote = value.index("'")
                second_quote = value.index("'", first_quote + 1)
                charset = value[:first_quote]
                percent_part = value[second_quote + 1:]
                all_bytes += percent_decode(percent_part)
                first_encoded_seen = True
            else:
                all_bytes += percent_decode(value)
        else:
            all_bytes += value.encode('ascii')
    if charset:
        return decode_bytes(all_bytes, charset.lower())
    else:
        return all_bytes.decode('ascii')


def get_filename(headers):
    cd_params = get_params(headers, 'content-disposition')
    if cd_params is not None:
        name = get_rfc2231_param(cd_params, 'filename')
        if name is not None:
            return name
        if 'filename' in cd_params:
            return decode_encoded_words(cd_params['filename'])
    ct_params = get_params(headers, 'content-type')
    if ct_params is not None:
        name = get_rfc2231_param(ct_params, 'name')
        if name is not None:
            return name
        if 'name' in ct_params:
            return decode_encoded_words(ct_params['name'])
    return None


def is_delimiter(line, delimiter):
    if not line.startswith(delimiter):
        return False
    rest = line[len(delimiter):]
    return all(c in b' \t' for c in rest)


def is_close_delimiter(line, close_delim):
    if not line.startswith(close_delim):
        return False
    rest = line[len(close_delim):]
    return all(c in b' \t' for c in rest)


def parse_multipart(body_bytes, boundary, line_break):
    delimiter = b'--' + boundary
    close_delim = b'--' + boundary + b'--'
    lines = body_bytes.split(line_break)
    first_delim_idx = None
    close_delim_idx = None
    for i, line in enumerate(lines):
        if first_delim_idx is None:
            if is_delimiter(line, delimiter):
                first_delim_idx = i
        else:
            if is_close_delimiter(line, close_delim):
                close_delim_idx = i
                break
    if first_delim_idx is None or close_delim_idx is None:
        return []
    delimiters = [first_delim_idx]
    for i in range(first_delim_idx + 1, close_delim_idx):
        if is_delimiter(lines[i], delimiter):
            delimiters.append(i)
    delimiters.append(close_delim_idx)
    parts = []
    for i in range(len(delimiters) - 1):
        start = delimiters[i] + 1
        end = delimiters[i + 1]
        part_lines = lines[start:end]
        part_data = line_break.join(part_lines)
        parts.append(part_data)
    return parts


def split_entity(data, line_break):
    if data.startswith(line_break):
        return [], data[len(line_break):]
    sep = line_break + line_break
    idx = data.find(sep)
    if idx == -1:
        return parse_headers(data, line_break), b''
    else:
        header_bytes = data[:idx]
        body_bytes = data[idx + len(sep):]
        headers = parse_headers(header_bytes, line_break)
        return headers, body_bytes


def quote_string(text):
    result = ['"']
    for ch in text:
        cp = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append(f'\\u{cp:04x}')
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


def print_entity(headers, body_bytes, line_break, indent):
    type_part, subtype, ct_params = get_content_type(headers)
    cte = get_cte(headers)
    disposition = get_disposition(headers)

    if type_part == 'multipart':
        boundary = ct_params.get('boundary', '')
        boundary_bytes = boundary.encode('ascii')
        parts = parse_multipart(body_bytes, boundary_bytes, line_break)
        print(f"{'  ' * indent}multipart/{subtype} parts={len(parts)}")
        for part_data in parts:
            part_headers, part_body = split_entity(part_data, line_break)
            print_entity(part_headers, part_body, line_break, indent + 1)
    elif type_part == 'text' and disposition != 'attachment':
        charset = ct_params.get('charset', 'us-ascii').lower()
        raw = transfer_decode(body_bytes, cte, line_break)
        decoded_text = decode_bytes(raw, charset)
        decoded_text = decoded_text.replace('\r\n', '\n').replace('\r', '\n')
        print(f"{'  ' * indent}text/{subtype} charset={charset} cte={cte} chars={len(decoded_text)}")
        print(f"{'  ' * (indent + 1)}{quote_string(decoded_text)}")
    else:
        raw = transfer_decode(body_bytes, cte, line_break)
        name = get_filename(headers)
        size = len(raw)
        crc = zlib.crc32(raw) & 0xFFFFFFFF
        disp_str = disposition if disposition else '-'
        name_str = quote_string(name) if name is not None else '-'
        print(f"{'  ' * indent}{type_part}/{subtype} cte={cte} disposition={disp_str} name={name_str} size={size} crc32={crc:08x}")


def main():
    dir_path = sys.argv[1]
    files = sorted([f for f in os.listdir(dir_path) if f.endswith('.eml')])

    first = True
    for fname in files:
        if not first:
            print()
        first = False
        print(f"== {fname}")

        data = open(os.path.join(dir_path, fname), 'rb').read()

        # Detect line ending
        nl_pos = data.find(b'\n')
        if nl_pos > 0 and data[nl_pos - 1:nl_pos] == b'\r':
            line_break = b'\r\n'
        else:
            line_break = b'\n'

        # Split header and body
        sep = line_break + line_break
        idx = data.find(sep)
        if idx == -1:
            header_bytes = data
            body_bytes = b''
        else:
            header_bytes = data[:idx]
            body_bytes = data[idx + len(sep):]

        # Parse headers
        headers = parse_headers(header_bytes, line_break)

        # Print From and Subject
        from_val = get_header_value(headers, 'from')
        subject_val = get_header_value(headers, 'subject')

        if from_val is not None:
            decoded = decode_encoded_words(from_val)
            print(f'From: {quote_string(decoded)}')
        else:
            print('From: -')

        if subject_val is not None:
            decoded = decode_encoded_words(subject_val)
            print(f'Subject: {quote_string(decoded)}')
        else:
            print('Subject: -')

        # Print entity tree
        print_entity(headers, body_bytes, line_break, 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import sys
import os
import zlib
import base64
import re


# Windows-1252 mapping for bytes 0x80-0x9F
_WINDOWS_1252_HIGH = {
    0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192,
    0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021,
    0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
    0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D, 0x8F: 0x008F,
    0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
    0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A,
    0x9C: 0x0153, 0x9D: 0x009D, 0x9E: 0x017E, 0x9F: 0x0178,
}


def is_hex(c):
    return c in '0123456789abcdefABCDEF'


def is_hex_byte(b):
    return b in b'0123456789abcdefABCDEF'


def parse_params(i, value):
    params = {}
    n = len(value)
    while i < n:
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        if value[i] != ';':
            break
        i += 1
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        start = i
        while i < n and value[i] not in ' \t=':
            i += 1
        attr = value[start:i].lower()
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n or value[i] != '=':
            continue
        i += 1
        while i < n and value[i] in ' \t':
            i += 1
        if i >= n:
            break
        if value[i] == '"':
            i += 1
            val_chars = []
            while i < n:
                if value[i] == '\\' and i + 1 < n:
                    val_chars.append(value[i + 1])
                    i += 2
                elif value[i] == '"':
                    i += 1
                    break
                else:
                    val_chars.append(value[i])
                    i += 1
            val = ''.join(val_chars)
        else:
            start = i
            while i < n and value[i] not in ' \t;':
                i += 1
            val = value[start:i]
        params[attr] = val
    return params


def parse_content_type(value):
    i = 0
    n = len(value)
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t/;':
        i += 1
    type_part = value[start:i].lower()
    while i < n and value[i] in ' \t':
        i += 1
    if i < n and value[i] == '/':
        i += 1
    else:
        return type_part, '', {}
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t;':
        i += 1
    subtype = value[start:i].lower()
    params = parse_params(i, value)
    return type_part, subtype, params


def parse_content_disposition(value):
    i = 0
    n = len(value)
    while i < n and value[i] in ' \t':
        i += 1
    start = i
    while i < n and value[i] not in ' \t;':
        i += 1
    disp_type = value[start:i].lower()
    params = parse_params(i, value)
    return disp_type, params


def parse_headers(header_bytes, line_break):
    if not header_bytes:
        return []
    lines = header_bytes.split(line_break)
    logical_lines = []
    for line in lines:
        if line and (line[0:1] == b' ' or line[0:1] == b'\t'):
            if logical_lines:
                logical_lines[-1] += line
            else:
                logical_lines.append(line)
        else:
            logical_lines.append(line)
    headers = []
    for line in logical_lines:
        if b':' in line:
            name, value = line.split(b':', 1)
            name = name.decode('ascii').lower()
            value = value.strip(b' \t').decode('ascii')
            headers.append((name, value))
    return headers


def get_header_value(headers, name):
    for n, v in headers:
        if n == name:
            return v
    return None


def get_content_type(headers):
    v = get_header_value(headers, 'content-type')
    if v is not None:
        return parse_content_type(v)
    return ('text', 'plain', {})


def get_cte(headers):
    v = get_header_value(headers, 'content-transfer-encoding')
    if v is not None:
        return v.lower()
    return '7bit'


def get_disposition(headers):
    v = get_header_value(headers, 'content-disposition')
    if v is not None:
        disp_type, _ = parse_content_disposition(v)
        return disp_type
    return None


def get_params(headers, header_name):
    v = get_header_value(headers, header_name)
    if v is None:
        return None
    if header_name == 'content-type':
        _, _, params = parse_content_type(v)
        return params
    elif header_name == 'content-disposition':
        _, params = parse_content_disposition(v)
        return params
    return None


def transfer_decode(body_bytes, cte, line_break):
    if cte in ('7bit', '8bit', 'binary'):
        return body_bytes
    elif cte == 'base64':
        return base64_decode_body(body_bytes)
    elif cte == 'quoted-printable':
        return qp_decode(body_bytes, line_break)
    else:
        return body_bytes


def base64_decode_body(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    filtered = bytearray()
    for b in data:
        if b == ord('='):
            break
        if b in alphabet:
            filtered.append(b)
    filtered = bytes(filtered)
    padding = (4 - len(filtered) % 4) % 4
    filtered += b'=' * padding
    try:
        return base64.b64decode(filtered)
    except Exception:
        return b''


def qp_decode(data, line_break):
    lines = data.split(line_break)
    # Step 1: remove trailing spaces/tabs from each line
    trimmed = []
    for line in lines:
        while line and line[-1:] in (b' ', b'\t'):
            line = line[:-1]
        trimmed.append(line)

    # Step 2: join soft line breaks
    # A line ending with `=` is a soft break UNLESS next line starts with two hex digits
    joined = []
    i = 0
    while i < len(trimmed):
        if i + 1 < len(trimmed) and trimmed[i].endswith(b'='):
            next_line = trimmed[i + 1]
            if len(next_line) >= 2 and is_hex_byte(next_line[0]) and is_hex_byte(next_line[1]):
                # Would split =XY, not a soft break
                joined.append(trimmed[i])
                i += 1
            else:
                # Soft break: remove = and join with next line
                joined.append(trimmed[i][:-1] + next_line)
                i += 2
        else:
            joined.append(trimmed[i])
            i += 1

    # Steps 3-5: process joined text
    text = b'\n'.join(joined)
    result = bytearray()
    i = 0
    n = len(text)
    while i < n:
        if text[i:i+1] == b'=':
            if i + 2 < n and is_hex_byte(text[i+1]) and is_hex_byte(text[i+2]):
                result.append(int(text[i+1:i+3], 16))
                i += 3
            else:
                result.append(0x3D)
                i += 1
        else:
            result.append(text[i])
            i += 1
    return bytes(result)


def decode_bytes(data, charset):
    charset = charset.lower()
    if charset == 'us-ascii':
        return data.decode('ascii')
    elif charset == 'utf-8':
        return data.decode('utf-8')
    elif charset == 'iso-8859-1':
        return data.decode('latin-1')
    elif charset == 'windows-1252':
        return decode_windows1252(data)
    else:
        return data.decode('ascii', errors='replace')


def decode_windows1252(data):
    result = []
    for b in data:
        if b < 0x80 or b >= 0xA0:
            result.append(chr(b))
        else:
            # 0x80-0x9F: use windows-1252 mapping
            cp = _WINDOWS_1252_HIGH.get(b, b)
            result.append(chr(cp))
    return ''.join(result)


def normalize_charset(cs):
    if '*' in cs:
        cs = cs[:cs.index('*')]
    return cs.lower()


def base64_decode_2047(text):
    text = text.rstrip('=')
    padding = (4 - len(text) % 4) % 4
    text += '=' * padding
    try:
        return base64.b64decode(text)
    except Exception:
        return b''


def q_decode_2047(text):
    result = bytearray()
    i = 0
    while i < len(text):
        if text[i] == '_':
            result.append(0x20)
            i += 1
        elif text[i] == '=' and i + 2 < len(text) and is_hex(text[i + 1]) and is_hex(text[i + 2]):
            result.append(int(text[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(text[i]))
            i += 1
    return bytes(result)


def decode_encoded_words(text):
    pattern = re.compile(r'=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=')
    matches = list(pattern.finditer(text))
    if not matches:
        return text
    groups = []
    current_group = [matches[0]]
    for i in range(1, len(matches)):
        prev = current_group[-1]
        curr = matches[i]
        between = text[prev.end():curr.start()]
        if all(c in ' \t' for c in between):
            prev_charset = normalize_charset(prev.group(1))
            curr_charset = normalize_charset(curr.group(1))
            if prev_charset == curr_charset:
                current_group.append(curr)
            else:
                groups.append(current_group)
                current_group = [curr]
        else:
            groups.append(current_group)
            current_group = [curr]
    groups.append(current_group)
    result = []
    pos = 0
    for group in groups:
        result.append(text[pos:group[0].start()])
        charset = normalize_charset(group[0].group(1))
        all_bytes = b''
        for m in group:
            encoding = m.group(2).upper()
            encoded_text = m.group(3)
            if encoding == 'B':
                all_bytes += base64_decode_2047(encoded_text)
            else:
                all_bytes += q_decode_2047(encoded_text)
        decoded = decode_bytes(all_bytes, charset)
        result.append(decoded)
        pos = group[-1].end()
    result.append(text[pos:])
    return ''.join(result)


def percent_decode(text):
    result = bytearray()
    i = 0
    while i < len(text):
        if text[i] == '%' and i + 2 < len(text) and is_hex(text[i + 1]) and is_hex(text[i + 2]):
            result.append(int(text[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(text[i]))
            i += 1
    return bytes(result)


def decode_rfc2231_encoded(value):
    try:
        first_quote = value.index("'")
        second_quote = value.index("'", first_quote + 1)
    except ValueError:
        return None
    charset = value[:first_quote]
    percent_part = value[second_quote + 1:]
    raw_bytes = percent_decode(percent_part)
    return decode_bytes(raw_bytes, charset.lower())


def get_rfc2231_param(params, attr):
    single_key = attr + '*'
    if single_key in params:
        result = decode_rfc2231_encoded(params[single_key])
        if result is not None:
            return result
    segments = {}
    prefix = attr + '*'
    for key, value in params.items():
        if not key.startswith(prefix):
            continue
        rest = key[len(prefix):]
        if rest == '':
            continue
        if rest.endswith('*'):
            idx_str = rest[:-1]
            encoded = True
        else:
            idx_str = rest
            encoded = False
        try:
            idx = int(idx_str)
        except ValueError:
            continue
        segments[idx] = (value, encoded)
    if not segments:
        return None
    indices = sorted(segments.keys())
    charset = None
    all_bytes = b''
    first_encoded_seen = False
    for idx in indices:
        value, encoded = segments[idx]
        if encoded:
            if not first_encoded_seen:
                try:
                    first_quote = value.index("'")
                    second_quote = value.index("'", first_quote + 1)
                    charset = value[:first_quote]
                    percent_part = value[second_quote + 1:]
                    all_bytes += percent_decode(percent_part)
                    first_encoded_seen = True
                except ValueError:
                    all_bytes += percent_decode(value)
                    first_encoded_seen = True
            else:
                all_bytes += percent_decode(value)
        else:
            all_bytes += value.encode('ascii')
    if charset:
        return decode_bytes(all_bytes, charset.lower())
    else:
        return all_bytes.decode('ascii')


def get_filename(headers):
    cd_params = get_params(headers, 'content-disposition')
    if cd_params is not None:
        name = get_rfc2231_param(cd_params, 'filename')
        if name is not None:
            return name
        if 'filename' in cd_params:
            return decode_encoded_words(cd_params['filename'])
    ct_params = get_params(headers, 'content-type')
    if ct_params is not None:
        name = get_rfc2231_param(ct_params, 'name')
        if name is not None:
            return name
        if 'name' in ct_params:
            return decode_encoded_words(ct_params['name'])
    return None


def is_delimiter(line, delimiter):
    if not line.startswith(delimiter):
        return False
    rest = line[len(delimiter):]
    return all(c in b' \t' for c in rest)


def is_close_delimiter(line, close_delim):
    if not line.startswith(close_delim):
        return False
    rest = line[len(close_delim):]
    return all(c in b' \t' for c in rest)


def parse_multipart(body_bytes, boundary, line_break):
    delimiter = b'--' + boundary
    close_delim = b'--' + boundary + b'--'
    lines = body_bytes.split(line_break)
    first_delim_idx = None
    close_delim_idx = None
    for i, line in enumerate(lines):
        if first_delim_idx is None:
            if is_delimiter(line, delimiter):
                first_delim_idx = i
        else:
            if is_close_delimiter(line, close_delim):
                close_delim_idx = i
                break
    if first_delim_idx is None or close_delim_idx is None:
        return []
    delimiters = [first_delim_idx]
    for i in range(first_delim_idx + 1, close_delim_idx):
        if is_delimiter(lines[i], delimiter):
            delimiters.append(i)
    delimiters.append(close_delim_idx)
    parts = []
    for i in range(len(delimiters) - 1):
        start = delimiters[i] + 1
        end = delimiters[i + 1]
        part_lines = lines[start:end]
        part_data = line_break.join(part_lines)
        parts.append(part_data)
    return parts


def split_entity(data, line_break):
    if data.startswith(line_break):
        return [], data[len(line_break):]
    sep = line_break + line_break
    idx = data.find(sep)
    if idx == -1:
        return parse_headers(data, line_break), b''
    else:
        header_bytes = data[:idx]
        body_bytes = data[idx + len(sep):]
        headers = parse_headers(header_bytes, line_break)
        return headers, body_bytes


def quote_string(text):
    result = ['"']
    for ch in text:
        cp = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append(f'\\u{cp:04x}')
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


def print_entity(headers, body_bytes, line_break, indent):
    type_part, subtype, ct_params = get_content_type(headers)
    cte = get_cte(headers)
    disposition = get_disposition(headers)

    if type_part == 'multipart':
        boundary = ct_params.get('boundary', '')
        boundary_bytes = boundary.encode('ascii')
        parts = parse_multipart(body_bytes, boundary_bytes, line_break)
        print(f"{'  ' * indent}multipart/{subtype} parts={len(parts)}")
        for part_data in parts:
            part_headers, part_body = split_entity(part_data, line_break)
            print_entity(part_headers, part_body, line_break, indent + 1)
    elif type_part == 'text' and disposition != 'attachment':
        charset = ct_params.get('charset', 'us-ascii').lower()
        raw = transfer_decode(body_bytes, cte, line_break)
        decoded_text = decode_bytes(raw, charset)
        decoded_text = decoded_text.replace('\r\n', '\n').replace('\r', '\n')
        print(f"{'  ' * indent}text/{subtype} charset={charset} cte={cte} chars={len(decoded_text)}")
        print(f"{'  ' * (indent + 1)}{quote_string(decoded_text)}")
    else:
        raw = transfer_decode(body_bytes, cte, line_break)
        name = get_filename(headers)
        size = len(raw)
        crc = zlib.crc32(raw) & 0xFFFFFFFF
        disp_str = disposition if disposition else '-'
        name_str = quote_string(name) if name is not None else '-'
        print(f"{'  ' * indent}{type_part}/{subtype} cte={cte} disposition={disp_str} name={name_str} size={size} crc32={crc:08x}")


def main():
    dir_path = sys.argv[1]
    files = sorted([f for f in os.listdir(dir_path) if f.endswith('.eml')])

    first = True
    for fname in files:
        if not first:
            print()
        first = False
        print(f"== {fname}")

        data = open(os.path.join(dir_path, fname), 'rb').read()

        # Detect line ending
        nl_pos = data.find(b'\n')
        if nl_pos > 0 and data[nl_pos - 1:nl_pos] == b'\r':
            line_break = b'\r\n'
        else:
            line_break = b'\n'

        # Split header and body
        sep = line_break + line_break
        idx = data.find(sep)
        if idx == -1:
            header_bytes = data
            body_bytes = b''
        else:
            header_bytes = data[:idx]
            body_bytes = data[idx + len(sep):]

        # Parse headers
        headers = parse_headers(header_bytes, line_break)

        # Print From and Subject
        from_val = get_header_value(headers, 'from')
        subject_val = get_header_value(headers, 'subject')

        if from_val is not None:
            decoded = decode_encoded_words(from_val)
            print(f'From: {quote_string(decoded)}')
        else:
            print('From: -')

        if subject_val is not None:
            decoded = decode_encoded_words(subject_val)
            print(f'Subject: {quote_string(decoded)}')
        else:
            print('Subject: -')

        # Print entity tree
        print_entity(headers, body_bytes, line_break, 0)


if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.file.*;
import java.nio.charset.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.CRC32;

public class Main {
    static String lineEnd;
    static int lineEndLen;

    static final int[] WIN1252 = {
        0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
        0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
        0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
        0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
    };

    static final Pattern EW = Pattern.compile("=\\?([^?\\t ]+)\\?([BbQq])\\?([^?\\t ]*)\\?=");

    static class Entity {
        List<String[]> headers = new ArrayList<>();
        byte[] body = new byte[0];
        String type = "text", subtype = "plain";
        Map<String, String> ctParams = new LinkedHashMap<>();
        String cte = "7bit";
        String dispType = null;
        Map<String, String> cdParams = new LinkedHashMap<>();
        List<Entity> parts = null;
    }

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        File[] files = dir.toFile().listFiles((d, n) -> n.endsWith(".eml"));
        if (files == null) return;
        Arrays.sort(files, (a, b) -> {
            byte[] an = a.getName().getBytes("US-ASCII");
            byte[] bn = b.getName().getBytes("US-ASCII");
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++)
                if ((an[i] & 0xFF) != (bn[i] & 0xFF)) return (an[i] & 0xFF) - (bn[i] & 0xFF);
            return an.length - bn.length;
        });
        boolean first = true;
        for (File f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        if (hasCRLF(data)) { lineEnd = "\r\n"; lineEndLen = 2; }
        else { lineEnd = "\n"; lineEndLen = 1; }

        System.out.println("== " + f.getName());
        Entity msg = parseEntity(data, 0, data.length);
        String from = getHeader(msg, "from");
        String subj = getHeader(msg, "subject");
        System.out.println("From: " + (from != null ? quoted(decodeEncodedWords(from)) : "-"));
        System.out.println("Subject: " + (subj != null ? quoted(decodeEncodedWords(subj)) : "-"));
        printTree(msg, 0);
    }

    static boolean hasCRLF(byte[] d) {
        for (int i = 0; i + 1 < d.length; i++) if (d[i] == '\r' && d[i+1] == '\n') return true;
        return false;
    }

    static boolean mle(byte[] d, int p) {
        if (lineEndLen == 2) return p + 1 < d.length && d[p] == '\r' && d[p+1] == '\n';
        return p < d.length && d[p] == '\n';
    }

    static int findLE(byte[] d, int p) {
        for (int i = p; i < d.length; i++) {
            if (lineEndLen == 2) { if (i+1 < d.length && d[i]=='\r' && d[i+1]=='\n') return i; }
            else { if (d[i]=='\n') return i; }
        }
        return -1;
    }

    static Entity parseEntity(byte[] data, int start, int end) {
        Entity e = new Entity();
        int bodyStart, headerEnd;
        if (start + lineEndLen <= end && mle(data, start)) {
            headerEnd = start; bodyStart = start + lineEndLen;
        } else {
            int pos = -1;
            for (int i = start; i + 2*lineEndLen <= end; i++) {
                if (mle(data, i) && mle(data, i + lineEndLen)) { pos = i; break; }
            }
            if (pos >= 0) { headerEnd = pos; bodyStart = pos + 2*lineEndLen; }
            else { headerEnd = end; bodyStart = end; }
        }
        parseHeaders(data, start, headerEnd, e);
        e.body = Arrays.copyOfRange(data, bodyStart, end);
        parseContentType(e);
        parseCTE(e);
        parseContentDisposition(e);
        if (e.type.equals("multipart")) {
            String b = e.ctParams.get("boundary");
            if (b != null) e.parts = parseMultipart(e.body, b);
        }
        return e;
    }

    static void parseHeaders(byte[] data, int start, int end, Entity e) {
        List<String> lines = splitLines(data, start, end);
        List<String> unfolded = new ArrayList<>();
        for (String line : lines) {
            if (line.isEmpty()) continue;
            if (!line.isEmpty() && (line.charAt(0)==' '||line.charAt(0)=='\t') && !unfolded.isEmpty()) {
                unfolded.set(unfolded.size()-1, unfolded.get(unfolded.size()-1)+line);
            } else unfolded.add(line);
        }
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String val = trimST(line.substring(colon+1));
            e.headers.add(new String[]{name, val});
        }
    }

    static List<String> splitLines(byte[] data, int start, int end) {
        List<String> lines = new ArrayList<>();
        int pos = start;
        while (pos < end) {
            int le = findLE(data, pos);
            int ce = (le < 0) ? end : le;
            lines.add(new String(data, pos, ce - pos, StandardCharsets.ISO_8859_1));
            if (le < 0) break;
            pos = le + lineEndLen;
        }
        return lines;
    }

    static String trimST(String s) {
        int a=0,b=s.length();
        while(a<b&&(s.charAt(a)==' '||s.charAt(a)=='\t'))a++;
        while(b>a&&(s.charAt(b-1)==' '||s.charAt(b-1)=='\t'))b--;
        return s.substring(a,b);
    }

    static String getHeader(Entity e, String name) {
        name = name.toLowerCase();
        for (String[] h : e.headers) if (h[0].equals(name)) return h[1];
        return null;
    }

    static void parseContentType(Entity e) {
        String v = getHeader(e, "content-type");
        if (v == null) { e.type="text"; e.subtype="plain"; return; }
        int[] p = parseTypeSub(v, 0);
        e.type = p[0]>=0 ? v.substring(p[0],p[1]).trim().toLowerCase() : "text";
        e.subtype = p[2]>=0 ? v.substring(p[2],p[3]).trim().toLowerCase() : "plain";
        parseParams(v, p[3], e.ctParams);
    }

    static int[] parseTypeSub(String s, int start) {
        int i=start;
        while(i<s.length()&&(s.charAt(i)==' '||s.charAt(i)=='\t'))i++;
        int ts=i; while(i<s.length()&&s.charAt(i)!='/'&&s.charAt(i)!=';')i++;
        int te=i;
        if(i<s.length()&&s.charAt(i)=='/'){i++;while(i<s.length()&&(s.charAt(i)==' '||s.charAt(i)=='\t'))i++;}
        int ss=i; while(i<s.length()&&s.charAt(i)!=';')i++;
        int se=i;
        return new int[]{ts,te,ss,se};
    }

    static void parseParams(String s, int pos, Map<String,String> params) {
        while (pos < s.length()) {
            pos = skipST(s,pos);
            if (pos>=s.length()) break;
            if (s.charAt(pos)!=';') { pos++; continue; }
            pos++; pos = skipST(s,pos);
            if (pos>=s.length()) break;
            int ns=pos; while(pos<s.length()&&s.charAt(pos)!='='&&s.charAt(pos)!=' '&&s.charAt(pos)!='\t')pos++;
            String name = s.substring(ns,pos).toLowerCase();
            pos = skipST(s,pos);
            if (pos>=s.length()||s.charAt(pos)!='=') continue;
            pos++; pos = skipST(s,pos);
            if (pos>=s.length()) continue;
            String val;
            if (s.charAt(pos)=='"') {
                pos++; StringBuilder sb=new StringBuilder();
                while(pos<s.length()&&s.charAt(pos)!='"'){
                    if(s.charAt(pos)=='\\'&&pos+1<s.length()){sb.append(s.charAt(pos+1));pos+=2;}
                    else{sb.append(s.charAt(pos));pos++;}
                }
                if(pos<s.length())pos++;
                val=sb.toString();
            } else {
                int vs=pos; while(pos<s.length()&&s.charAt(pos)!=';'&&s.charAt(pos)!=' '&&s.charAt(pos)!='\t')pos++;
                val=s.substring(vs,pos);
            }
            params.put(name, val);
        }
    }

    static int skipST(String s, int p) { while(p<s.length()&&(s.charAt(p)==' '||s.charAt(p)=='\t'))p++; return p; }

    static void parseCTE(Entity e) {
        String v = getHeader(e, "content-transfer-encoding");
        if (v != null) e.cte = v.trim().toLowerCase();
    }

    static void parseContentDisposition(Entity e) {
        String v = getHeader(e, "content-disposition");
        if (v == null) return;
        int semi = v.indexOf(';');
        String dtype = (semi>=0 ? v.substring(0,semi) : v).trim().toLowerCase();
        if (dtype.equals("inline")||dtype.equals("attachment")) e.dispType = dtype;
        if (semi>=0) parseParams(v, semi+1, e.cdParams);
    }

    static List<byte[]> parseMultipart(byte[] body, String boundary) {
        List<byte[]> parts = new ArrayList<>();
        List<int[]> delims = new ArrayList<>();
        int pos = 0;
        while (pos <= body.length) {
            int le = findLE(body, pos);
            int ce = (le<0)?body.length:le;
            String line = new String(body, pos, ce-pos, StandardCharsets.ISO_8859_1);
            if (isCloseDelim(line, boundary)) {
                delims.add(new int[]{pos, (le<0)?body.length:le+lineEndLen});
                break;
            } else if (isDelim(line, boundary)) {
                delims.add(new int[]{pos, (le<0)?body.length:le+lineEndLen});
            }
            if (le<0) break;
            pos = le+lineEndLen;
        }
        if (delims.isEmpty()) return parts;
        for (int i=0;i<delims.size()-1;i++){
            int ps=delims.get(i)[1], pe=delims.get(i+1)[0];
            if(pe-ps>=lineEndLen&&mle(body,pe-lineEndLen)) pe-=lineEndLen;
            parts.add(Arrays.copyOfRange(body,ps,pe));
        }
        return parts;
    }

    static boolean isDelim(String line, String b) {
        String d="--"+b;
        if(!line.startsWith(d))return false;
        String r=line.substring(d.length());
        for(int i=0;i<r.length();i++)if(r.charAt(i)!=' '&&r.charAt(i)!='\t')return false;
        return true;
    }
    static boolean isCloseDelim(String line, String b) {
        String d="--"+b+"--";
        if(!line.startsWith(d))return false;
        String r=line.substring(d.length());
        for(int i=0;i<r.length();i++)if(r.charAt(i)!=' '&&r.charAt(i)!='\t')return false;
        return true;
    }

    static byte[] decodeTE(byte[] body, String cte) {
        if(cte.equals("base64")) return decodeB64(body);
        if(cte.equals("quoted-printable")) return decodeQP(body);
        return body;
    }

    static byte[] decodeB64(byte[] data) {
        StringBuilder sb=new StringBuilder();
        for(byte b:data){char c=(char)(b&0xFF);if(c=='=')break;
            if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/')sb.append(c);}
        String s=sb.toString();
        while(s.length()%4!=0)s+="=";
        try{return Base64.getDecoder().decode(s);}catch(Exception ex){return new byte[0];}
    }

    static byte[] decodeQP(byte[] data) {
        List<String> lines=splitLines(data,0,data.length);
        for(int i=0;i<lines.size();i++) lines.set(i, trimTrailingST(lines.get(i)));
        StringBuilder joined=new StringBuilder();
        for(int i=0;i<lines.size();i++){
            String ln=lines.get(i);
            if(ln.endsWith("=")&&i<lines.size()-1){
                String next=lines.get(i+1);
                if(next.length()>=2&&isHex(next.charAt(0))&&isHex(next.charAt(1))){
                    joined.append(ln); joined.append(lineEnd);
                } else {
                    joined.append(ln,0,ln.length()-1);
                }
            } else {
                joined.append(ln);
                if(i<lines.size()-1) joined.append(lineEnd);
            }
        }
        String text=joined.toString();
        ByteArrayOutputStream out=new ByteArrayOutputStream();
        int i=0;
        while(i<text.length()){
            if(text.charAt(i)=='='&&i+2<text.length()&&isHex(text.charAt(i+1))&&isHex(text.charAt(i+2))){
                out.write(Integer.parseInt(text.substring(i+1,i+3),16));i+=3;
            } else if(text.charAt(i)=='='){out.write('=');i++;}
            else{out.write(text.charAt(i)&0xFF);i++;}
        }
        return out.toByteArray();
    }

    static String trimTrailingST(String s){
        int b=s.length();
        while(b>0&&(s.charAt(b-1)==' '||s.charAt(b-1)=='\t'))b--;
        return s.substring(0,b);
    }

    static boolean isHex(char c){return (c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}

    static String decodeCharset(byte[] bytes, String cs) {
        switch(cs.toLowerCase()){
            case "us-ascii": case "ascii": return new String(bytes,StandardCharsets.US_ASCII);
            case "utf-8": return new String(bytes,StandardCharsets.UTF_8);
            case "iso-8859-1": case "latin-1": case "latin1": return new String(bytes,StandardCharsets.ISO_8859_1);
            case "windows-1252": return decodeWin1252(bytes);
            default: return new String(bytes,StandardCharsets.ISO_8859_1);
        }
    }

    static String decodeWin1252(byte[] bytes){
        char[] r=new char[bytes.length];
        for(int i=0;i<bytes.length;i++){
            int b=bytes[i]&0xFF;
            if(b>=0x80&&b<=0x9F) r[i]=(char)WIN1252[b-0x80];
            else r[i]=(char)b;
        }
        return new String(r);
    }

    static String decodeEncodedWords(String text) {
        List<int[]> positions=new ArrayList<>();
        List<String> charsets=new ArrayList<>();
        List<byte[]> byteLists=new ArrayList<>();
        Matcher m=EW.matcher(text);
        while(m.find()){
            String cs=m.group(1), enc=m.group(2), et=m.group(3);
            byte[] bytes=decodeWordBytes(enc,et);
            positions.add(new int[]{m.start(),m.end()});
            charsets.add(cs);
            byteLists.add(bytes);
        }
        if(positions.isEmpty()) return text;
        List<List<Integer>> runs=new ArrayList<>();
        int i=0;
        while(i<positions.size()){
            List<Integer> run=new ArrayList<>();
            run.add(i); i++;
            while(i<positions.size()){
                int prevEnd=positions.get(i-1)[1];
                int currStart=positions.get(i)[0];
                String between=text.substring(prevEnd,currStart);
                if(!onlyST(between)) break;
                if(!sameCS(charsets.get(i-1),charsets.get(i))) break;
                run.add(i); i++;
            }
            runs.add(run);
        }
        StringBuilder result=new StringBuilder();
        int pos=0;
        for(List<Integer> run:runs){
            result.append(text,pos,positions.get(run.get(0))[0]);
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            for(int idx:run){byte[] b=byteLists.get(idx);baos.write(b,0,b.length);}
            String cs=stripLang(charsets.get(run.get(0)));
            result.append(decodeCharset(baos.toByteArray(),cs));
            pos=positions.get(run.get(run.size()-1))[1];
        }
        result.append(text,pos,text.length());
        return result.toString();
    }

    static byte[] decodeWordBytes(String enc, String et){
        if(enc.equalsIgnoreCase("B")){
            StringBuilder sb=new StringBuilder();
            for(int i=0;i<et.length();i++){char c=et.charAt(i);if(c=='=')break;
                if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/')sb.append(c);}
            String s=sb.toString();
            while(s.length()%4!=0)s+="=";
            try{return Base64.getDecoder().decode(s);}catch(Exception ex){return new byte[0];}
        } else {
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            for(int i=0;i<et.length();i++){
                char c=et.charAt(i);
                if(c=='_')baos.write(0x20);
                else if(c=='='&&i+2<et.length()&&isHex(et.charAt(i+1))&&isHex(et.charAt(i+2))){
                    baos.write(Integer.parseInt(et.substring(i+1,i+3),16));i+=2;
                } else baos.write(c&0xFF);
            }
            return baos.toByteArray();
        }
    }

    static boolean onlyST(String s){for(int i=0;i<s.length();i++)if(s.charAt(i)!=' '&&s.charAt(i)!='\t')return false;return true;}
    static boolean sameCS(String a,String b){return stripLang(a).equalsIgnoreCase(stripLang(b));}
    static String stripLang(String cs){int s=cs.indexOf('*');return s>=0?cs.substring(0,s):cs;}

    static String getFileName(Entity e) {
        String r=getRFC2231(e.cdParams,"filename");
        if(r!=null)return r;
        r=e.cdParams.get("filename");
        if(r!=null)return decodeEncodedWords(r);
        r=getRFC2231(e.ctParams,"name");
        if(r!=null)return r;
        r=e.ctParams.get("name");
        if(r!=null)return decodeEncodedWords(r);
        return null;
    }

    static String getRFC2231(Map<String,String> params, String attr) {
        boolean hasSingle=params.containsKey(attr+"*");
        boolean hasCont=false; int maxI=-1;
        for(int i=0;i<=200;i++){
            if(params.containsKey(attr+"*"+i)||params.containsKey(attr+"*"+i+"*")){hasCont=true;maxI=i;}
        }
        if(!hasSingle&&!hasCont)return null;
        TreeMap<Integer,String[]> segs=new TreeMap<>();
        if(hasSingle) segs.put(0,new String[]{params.get(attr+"*"),"true"});
        for(int i=0;i<=maxI;i++){
            if(params.containsKey(attr+"*"+i+"*")) segs.put(i,new String[]{params.get(attr+"*"+i+"*"),"true"});
            else if(params.containsKey(attr+"*"+i)) segs.put(i,new String[]{params.get(attr+"*"+i),"false"});
        }
        if(segs.isEmpty())return null;
        boolean hasPE=false;
        for(String[] s:segs.values())if(s[1].equals("true")){hasPE=true;break;}
        String cs="us-ascii";
        if(hasPE){String[] s0=segs.get(0);if(s0!=null&&s0[1].equals("true")){
            String v=s0[0];int q=v.indexOf('\'');if(q>=0)cs=v.substring(0,q);
        }}
        ByteArrayOutputStream baos=new ByteArrayOutputStream();
        for(Map.Entry<Integer,String[]> ent:segs.entrySet()){
            String val=ent.getValue()[0]; boolean pe=ent.getValue()[1].equals("true");
            if(pe){
                if(ent.getKey()==0&&hasPE){
                    int q1=val.indexOf('\'');
                    if(q1>=0){int q2=val.indexOf('\'',q1+1);if(q2>=0)val=val.substring(q2+1);}
                }
                for(int i=0;i<val.length();i++){
                    if(val.charAt(i)=='%'&&i+2<val.length()&&isHex(val.charAt(i+1))&&isHex(val.charAt(i+2))){
                        baos.write(Integer.parseInt(val.substring(i+1,i+3),16));i+=2;
                    } else baos.write(val.charAt(i)&0xFF);
                }
            } else {
                for(int i=0;i<val.length();i++) baos.write(val.charAt(i)&0xFF);
            }
        }
        return decodeCharset(baos.toByteArray(),cs);
    }

    static void printTree(Entity e, int indent) {
        String prefix="  ".repeat(indent);
        if(e.type.equals("multipart")){
            System.out.println(prefix+"multipart/"+e.subtype+" parts="+(e.parts!=null?e.parts.size():0));
            if(e.parts!=null)for(Entity p:e.parts)printTree(p,indent+1);
        } else if(e.type.equals("text")&&!"attachment".equals(e.dispType)){
            byte[] decoded=decodeTE(e.body,e.cte);
            String cs=e.ctParams.getOrDefault("charset","us-ascii").toLowerCase();
            String text=decodeCharset(decoded,cs);
            text=text.replace("\r\n","\n").replace("\r","\n");
            int chars=text.codePointCount(0,text.length());
            System.out.println(prefix+"text/"+e.subtype+" charset="+cs+" cte="+e.cte+" chars="+chars);
            System.out.println("  ".repeat(indent+1)+quoted(text));
        } else {
            byte[] decoded=decodeTE(e.body,e.cte);
            String name=getFileName(e);
            String nameStr=name!=null?quoted(name):"-";
            CRC32 crc=new CRC32();crc.update(decoded);
            String disp=e.dispType!=null?e.dispType:"-";
            System.out.println(prefix+e.type+"/"+e.subtype+" cte="+e.cte+" disposition="+disp+" name="+nameStr+" size="+decoded.length+" crc32="+String.format("%08x",crc.getValue()));
        }
    }

    static String quoted(String text){
        StringBuilder sb=new StringBuilder("\"");
        for(int i=0;i<text.length();){
            int cp=text.codePointAt(i);
            if(cp=='\\')sb.append("\\\\");
            else if(cp=='"')sb.append("\\\"");
            else if(cp=='\n')sb.append("\\n");
            else if(cp=='\t')sb.append("\\t");
            else if(cp<0x20||(cp>=0x7F&&cp<=0x9F))sb.append(String.format("\\u%04x",cp));
            else sb.appendCodePoint(cp);
            i+=Character.charCount(cp);
        }
        sb.append("\"");
        return sb.toString();
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.CRC32;

public class Main {
    static String lineEnd;
    static int lineEndLen;

    static final int[] WIN1252 = {
        0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
        0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
        0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
        0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
    };

    static final Pattern EW = Pattern.compile("=\\?([^?\\t ]+)\\?([BbQq])\\?([^?\\t ]*)\\?=");

    static class Entity {
        List<String[]> headers = new ArrayList<>();
        byte[] body = new byte[0];
        String type = "text", subtype = "plain";
        Map<String, String> ctParams = new LinkedHashMap<>();
        String cte = "7bit";
        String dispType = null;
        Map<String, String> cdParams = new LinkedHashMap<>();
        List<Entity> parts = null;
    }

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        File[] files = dir.toFile().listFiles((d, n) -> n.endsWith(".eml"));
        if (files == null) return;
        Arrays.sort(files, (a, b) -> {
            byte[] an = a.getName().getBytes("US-ASCII");
            byte[] bn = b.getName().getBytes("US-ASCII");
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++)
                if ((an[i] & 0xFF) != (bn[i] & 0xFF)) return (an[i] & 0xFF) - (bn[i] & 0xFF);
            return an.length - bn.length;
        });
        boolean first = true;
        for (File f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        if (hasCRLF(data)) { lineEnd = "\r\n"; lineEndLen = 2; }
        else { lineEnd = "\n"; lineEndLen = 1; }

        System.out.println("== " + f.getName());
        Entity msg = parseEntity(data, 0, data.length);
        String from = getHeader(msg, "from");
        String subj = getHeader(msg, "subject");
        System.out.println("From: " + (from != null ? quoted(decodeEncodedWords(from)) : "-"));
        System.out.println("Subject: " + (subj != null ? quoted(decodeEncodedWords(subj)) : "-"));
        printTree(msg, 0);
    }

    static boolean hasCRLF(byte[] d) {
        for (int i = 0; i + 1 < d.length; i++) if (d[i] == '\r' && d[i+1] == '\n') return true;
        return false;
    }

    static boolean mle(byte[] d, int p) {
        if (lineEndLen == 2) return p + 1 < d.length && d[p] == '\r' && d[p+1] == '\n';
        return p < d.length && d[p] == '\n';
    }

    static int findLE(byte[] d, int p, int end) {
        for (int i = p; i < end; i++) {
            if (lineEndLen == 2) { if (i+1 < end && d[i]=='\r' && d[i+1]=='\n') return i; }
            else { if (d[i]=='\n') return i; }
        }
        return -1;
    }

    static Entity parseEntity(byte[] data, int start, int end) {
        Entity e = new Entity();
        int bodyStart, headerEnd;
        if (start + lineEndLen <= end && mle(data, start)) {
            headerEnd = start; bodyStart = start + lineEndLen;
        } else {
            int pos = -1;
            for (int i = start; i + 2*lineEndLen <= end; i++) {
                if (mle(data, i) && mle(data, i + lineEndLen)) { pos = i; break; }
            }
            if (pos >= 0) { headerEnd = pos; bodyStart = pos + 2*lineEndLen; }
            else { headerEnd = end; bodyStart = end; }
        }
        parseHeaders(data, start, headerEnd, e);
        e.body = Arrays.copyOfRange(data, bodyStart, end);
        parseContentType(e);
        parseCTE(e);
        parseContentDisposition(e);
        if (e.type.equals("multipart")) {
            String b = e.ctParams.get("boundary");
            if (b != null) e.parts = parseMultipart(e.body, b);
        }
        return e;
    }

    static void parseHeaders(byte[] data, int start, int end, Entity e) {
        List<String> lines = splitLines(data, start, end);
        List<String> unfolded = new ArrayList<>();
        for (String line : lines) {
            if (line.isEmpty()) continue;
            if (!line.isEmpty() && (line.charAt(0)==' '||line.charAt(0)=='\t') && !unfolded.isEmpty()) {
                unfolded.set(unfolded.size()-1, unfolded.get(unfolded.size()-1)+line);
            } else unfolded.add(line);
        }
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String val = trimST(line.substring(colon+1));
            e.headers.add(new String[]{name, val});
        }
    }

    static List<String> splitLines(byte[] data, int start, int end) {
        List<String> lines = new ArrayList<>();
        int pos = start;
        while (pos < end) {
            int le = findLE(data, pos, end);
            int ce = (le < 0) ? end : le;
            lines.add(new String(data, pos, ce - pos, StandardCharsets.ISO_8859_1));
            if (le < 0) break;
            pos = le + lineEndLen;
        }
        return lines;
    }

    static String trimST(String s) {
        int a=0,b=s.length();
        while(a<b&&(s.charAt(a)==' '||s.charAt(a)=='\t'))a++;
        while(b>a&&(s.charAt(b-1)==' '||s.charAt(b-1)=='\t'))b--;
        return s.substring(a,b);
    }

    static String getHeader(Entity e, String name) {
        name = name.toLowerCase();
        for (String[] h : e.headers) if (h[0].equals(name)) return h[1];
        return null;
    }

    static void parseContentType(Entity e) {
        String v = getHeader(e, "content-type");
        if (v == null) { e.type="text"; e.subtype="plain"; return; }
        int[] p = parseTypeSub(v, 0);
        e.type = v.substring(p[0],p[1]).trim().toLowerCase();
        e.subtype = v.substring(p[2],p[3]).trim().toLowerCase();
        if (e.type.isEmpty()) e.type = "text";
        if (e.subtype.isEmpty()) e.subtype = "plain";
        parseParams(v, p[3], e.ctParams);
    }

    static int[] parseTypeSub(String s, int start) {
        int i=start;
        while(i<s.length()&&(s.charAt(i)==' '||s.charAt(i)=='\t'))i++;
        int ts=i; while(i<s.length()&&s.charAt(i)!='/'&&s.charAt(i)!=';')i++;
        int te=i;
        if(i<s.length()&&s.charAt(i)=='/'){i++;while(i<s.length()&&(s.charAt(i)==' '||s.charAt(i)=='\t'))i++;}
        int ss=i; while(i<s.length()&&s.charAt(i)!=';')i++;
        int se=i;
        return new int[]{ts,te,ss,se};
    }

    static void parseParams(String s, int pos, Map<String,String> params) {
        while (pos < s.length()) {
            pos = skipST(s,pos);
            if (pos>=s.length()) break;
            if (s.charAt(pos)!=';') { pos++; continue; }
            pos++; pos = skipST(s,pos);
            if (pos>=s.length()) break;
            int ns=pos; while(pos<s.length()&&s.charAt(pos)!='='&&s.charAt(pos)!=' '&&s.charAt(pos)!='\t')pos++;
            String name = s.substring(ns,pos).toLowerCase();
            pos = skipST(s,pos);
            if (pos>=s.length()||s.charAt(pos)!='=') continue;
            pos++; pos = skipST(s,pos);
            if (pos>=s.length()) continue;
            String val;
            if (s.charAt(pos)=='"') {
                pos++; StringBuilder sb=new StringBuilder();
                while(pos<s.length()&&s.charAt(pos)!='"'){
                    if(s.charAt(pos)=='\\'&&pos+1<s.length()){sb.append(s.charAt(pos+1));pos+=2;}
                    else{sb.append(s.charAt(pos));pos++;}
                }
                if(pos<s.length())pos++;
                val=sb.toString();
            } else {
                int vs=pos; while(pos<s.length()&&s.charAt(pos)!=';'&&s.charAt(pos)!=' '&&s.charAt(pos)!='\t')pos++;
                val=s.substring(vs,pos);
            }
            params.put(name, val);
        }
    }

    static int skipST(String s, int p) { while(p<s.length()&&(s.charAt(p)==' '||s.charAt(p)=='\t'))p++; return p; }

    static void parseCTE(Entity e) {
        String v = getHeader(e, "content-transfer-encoding");
        if (v != null) e.cte = v.trim().toLowerCase();
    }

    static void parseContentDisposition(Entity e) {
        String v = getHeader(e, "content-disposition");
        if (v == null) return;
        int semi = v.indexOf(';');
        String dtype = (semi>=0 ? v.substring(0,semi) : v).trim().toLowerCase();
        if (dtype.equals("inline")||dtype.equals("attachment")) e.dispType = dtype;
        if (semi>=0) parseParams(v, semi+1, e.cdParams);
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        List<int[]> delims = new ArrayList<>();
        int pos = 0;
        while (pos <= body.length) {
            int le = findLE(body, pos, body.length);
            int ce = (le<0)?body.length:le;
            String line = new String(body, pos, ce-pos, StandardCharsets.ISO_8859_1);
            if (isCloseDelim(line, boundary)) {
                delims.add(new int[]{pos, (le<0)?body.length:le+lineEndLen});
                break;
            } else if (isDelim(line, boundary)) {
                delims.add(new int[]{pos, (le<0)?body.length:le+lineEndLen});
            }
            if (le<0) break;
            pos = le+lineEndLen;
        }
        if (delims.isEmpty()) return parts;
        for (int i=0;i<delims.size()-1;i++){
            int ps=delims.get(i)[1], pe=delims.get(i+1)[0];
            if(pe-ps>=lineEndLen&&mle(body,pe-lineEndLen)) pe-=lineEndLen;
            byte[] partData = Arrays.copyOfRange(body, ps, pe);
            parts.add(parseEntity(partData, 0, partData.length));
        }
        return parts;
    }

    static boolean isDelim(String line, String b) {
        String d="--"+b;
        if(!line.startsWith(d))return false;
        String r=line.substring(d.length());
        for(int i=0;i<r.length();i++)if(r.charAt(i)!=' '&&r.charAt(i)!='\t')return false;
        return true;
    }
    static boolean isCloseDelim(String line, String b) {
        String d="--"+b+"--";
        if(!line.startsWith(d))return false;
        String r=line.substring(d.length());
        for(int i=0;i<r.length();i++)if(r.charAt(i)!=' '&&r.charAt(i)!='\t')return false;
        return true;
    }

    static byte[] decodeTE(byte[] body, String cte) {
        if(cte.equals("base64")) return decodeB64(body);
        if(cte.equals("quoted-printable")) return decodeQP(body);
        return body;
    }

    static byte[] decodeB64(byte[] data) {
        StringBuilder sb=new StringBuilder();
        for(byte b:data){char c=(char)(b&0xFF);if(c=='=')break;
            if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/')sb.append(c);}
        String s=sb.toString();
        while(s.length()%4!=0)s+="=";
        try{return Base64.getDecoder().decode(s);}catch(Exception ex){return new byte[0];}
    }

    static byte[] decodeQP(byte[] data) {
        List<String> lines=splitLines(data,0,data.length);
        for(int i=0;i<lines.size();i++) lines.set(i, trimTrailingST(lines.get(i)));
        StringBuilder joined=new StringBuilder();
        for(int i=0;i<lines.size();i++){
            String ln=lines.get(i);
            if(ln.endsWith("=")&&i<lines.size()-1){
                joined.append(ln,0,ln.length()-1);
            } else {
                joined.append(ln);
                if(i<lines.size()-1) joined.append(lineEnd);
            }
        }
        String text=joined.toString();
        ByteArrayOutputStream out=new ByteArrayOutputStream();
        int i=0;
        while(i<text.length()){
            if(text.charAt(i)=='='&&i+2<text.length()&&isHex(text.charAt(i+1))&&isHex(text.charAt(i+2))){
                out.write(Integer.parseInt(text.substring(i+1,i+3),16));i+=3;
            } else if(text.charAt(i)=='='){out.write('=');i++;}
            else{out.write(text.charAt(i)&0xFF);i++;}
        }
        return out.toByteArray();
    }

    static String trimTrailingST(String s){
        int b=s.length();
        while(b>0&&(s.charAt(b-1)==' '||s.charAt(b-1)=='\t'))b--;
        return s.substring(0,b);
    }

    static boolean isHex(char c){return (c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}

    static String decodeCharset(byte[] bytes, String cs) {
        switch(cs.toLowerCase()){
            case "us-ascii": case "ascii": return new String(bytes,StandardCharsets.US_ASCII);
            case "utf-8": return new String(bytes,StandardCharsets.UTF_8);
            case "iso-8859-1": case "latin-1": case "latin1": return new String(bytes,StandardCharsets.ISO_8859_1);
            case "windows-1252": return decodeWin1252(bytes);
            default: return new String(bytes,StandardCharsets.ISO_8859_1);
        }
    }

    static String decodeWin1252(byte[] bytes){
        char[] r=new char[bytes.length];
        for(int i=0;i<bytes.length;i++){
            int b=bytes[i]&0xFF;
            if(b>=0x80&&b<=0x9F) r[i]=(char)WIN1252[b-0x80];
            else r[i]=(char)b;
        }
        return new String(r);
    }

    static String decodeEncodedWords(String text) {
        List<int[]> positions=new ArrayList<>();
        List<String> charsets=new ArrayList<>();
        List<byte[]> byteLists=new ArrayList<>();
        Matcher m=EW.matcher(text);
        while(m.find()){
            String cs=m.group(1), enc=m.group(2), et=m.group(3);
            byte[] bytes=decodeWordBytes(enc,et);
            positions.add(new int[]{m.start(),m.end()});
            charsets.add(cs);
            byteLists.add(bytes);
        }
        if(positions.isEmpty()) return text;
        List<List<Integer>> runs=new ArrayList<>();
        int i=0;
        while(i<positions.size()){
            List<Integer> run=new ArrayList<>();
            run.add(i); i++;
            while(i<positions.size()){
                int prevEnd=positions.get(i-1)[1];
                int currStart=positions.get(i)[0];
                String between=text.substring(prevEnd,currStart);
                if(!onlyST(between)) break;
                if(!sameCS(charsets.get(i-1),charsets.get(i))) break;
                run.add(i); i++;
            }
            runs.add(run);
        }
        StringBuilder result=new StringBuilder();
        int pos=0;
        for(List<Integer> run:runs){
            result.append(text,pos,positions.get(run.get(0))[0]);
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            for(int idx:run){byte[] b=byteLists.get(idx);baos.write(b,0,b.length);}
            String cs=stripLang(charsets.get(run.get(0)));
            result.append(decodeCharset(baos.toByteArray(),cs));
            pos=positions.get(run.get(run.size()-1))[1];
        }
        result.append(text,pos,text.length());
        return result.toString();
    }

    static byte[] decodeWordBytes(String enc, String et){
        if(enc.equalsIgnoreCase("B")){
            StringBuilder sb=new StringBuilder();
            for(int i=0;i<et.length();i++){char c=et.charAt(i);if(c=='=')break;
                if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/')sb.append(c);}
            String s=sb.toString();
            while(s.length()%4!=0)s+="=";
            try{return Base64.getDecoder().decode(s);}catch(Exception ex){return new byte[0];}
        } else {
            ByteArrayOutputStream baos=new ByteArrayOutputStream();
            for(int i=0;i<et.length();i++){
                char c=et.charAt(i);
                if(c=='_')baos.write(0x20);
                else if(c=='='&&i+2<et.length()&&isHex(et.charAt(i+1))&&isHex(et.charAt(i+2))){
                    baos.write(Integer.parseInt(et.substring(i+1,i+3),16));i+=2;
                } else baos.write(c&0xFF);
            }
            return baos.toByteArray();
        }
    }

    static boolean onlyST(String s){for(int i=0;i<s.length();i++)if(s.charAt(i)!=' '&&s.charAt(i)!='\t')return false;return true;}
    static boolean sameCS(String a,String b){return stripLang(a).equalsIgnoreCase(stripLang(b));}
    static String stripLang(String cs){int s=cs.indexOf('*');return s>=0?cs.substring(0,s):cs;}

    static String getFileName(Entity e) {
        String r=getRFC2231(e.cdParams,"filename");
        if(r!=null)return r;
        r=e.cdParams.get("filename");
        if(r!=null)return decodeEncodedWords(r);
        r=getRFC2231(e.ctParams,"name");
        if(r!=null)return r;
        r=e.ctParams.get("name");
        if(r!=null)return decodeEncodedWords(r);
        return null;
    }

    static String getRFC2231(Map<String,String> params, String attr) {
        boolean hasSingle=params.containsKey(attr+"*");
        boolean hasCont=false; int maxI=-1;
        for(int i=0;i<=1000;i++){
            if(params.containsKey(attr+"*"+i)||params.containsKey(attr+"*"+i+"*")){hasCont=true;maxI=i;}
        }
        if(!hasSingle&&!hasCont)return null;
        TreeMap<Integer,String[]> segs=new TreeMap<>();
        if(hasSingle) segs.put(0,new String[]{params.get(attr+"*"),"true"});
        for(int i=0;i<=maxI;i++){
            if(params.containsKey(attr+"*"+i+"*")) segs.put(i,new String[]{params.get(attr+"*"+i+"*"),"true"});
            else if(params.containsKey(attr+"*"+i)) segs.put(i,new String[]{params.get(attr+"*"+i),"false"});
        }
        if(segs.isEmpty())return null;
        boolean hasPE=false;
        for(String[] s:segs.values())if(s[1].equals("true")){hasPE=true;break;}
        String cs="us-ascii";
        if(hasPE){String[] s0=segs.get(0);if(s0!=null&&s0[1].equals("true")){
            String v=s0[0];int q=v.indexOf('\'');if(q>=0)cs=v.substring(0,q);
        }}
        ByteArrayOutputStream baos=new ByteArrayOutputStream();
        for(Map.Entry<Integer,String[]> ent:segs.entrySet()){
            String val=ent.getValue()[0]; boolean pe=ent.getValue()[1].equals("true");
            if(pe){
                if(ent.getKey()==0&&hasPE){
                    int q1=val.indexOf('\'');
                    if(q1>=0){int q2=val.indexOf('\'',q1+1);if(q2>=0)val=val.substring(q2+1);}
                }
                for(int i=0;i<val.length();i++){
                    if(val.charAt(i)=='%'&&i+2<val.length()&&isHex(val.charAt(i+1))&&isHex(val.charAt(i+2))){
                        baos.write(Integer.parseInt(val.substring(i+1,i+3),16));i+=2;
                    } else baos.write(val.charAt(i)&0xFF);
                }
            } else {
                for(int i=0;i<val.length();i++) baos.write(val.charAt(i)&0xFF);
            }
        }
        return decodeCharset(baos.toByteArray(),cs);
    }

    static void printTree(Entity e, int indent) {
        String prefix="  ".repeat(indent);
        if(e.type.equals("multipart")){
            System.out.println(prefix+"multipart/"+e.subtype+" parts="+(e.parts!=null?e.parts.size():0));
            if(e.parts!=null)for(Entity p:e.parts)printTree(p,indent+1);
        } else if(e.type.equals("text")&&!"attachment".equals(e.dispType)){
            byte[] decoded=decodeTE(e.body,e.cte);
            String cs=e.ctParams.getOrDefault("charset","us-ascii").toLowerCase();
            String text=decodeCharset(decoded,cs);
            text=text.replace("\r\n","\n").replace("\r","\n");
            int chars=text.codePointCount(0,text.length());
            System.out.println(prefix+"text/"+e.subtype+" charset="+cs+" cte="+e.cte+" chars="+chars);
            System.out.println("  ".repeat(indent+1)+quoted(text));
        } else {
            byte[] decoded=decodeTE(e.body,e.cte);
            String name=getFileName(e);
            String nameStr=name!=null?quoted(name):"-";
            CRC32 crc=new CRC32();crc.update(decoded);
            String disp=e.dispType!=null?e.dispType:"-";
            System.out.println(prefix+e.type+"/"+e.subtype+" cte="+e.cte+" disposition="+disp+" name="+nameStr+" size="+decoded.length+" crc32="+String.format("%08x",crc.getValue()));
        }
    }

    static String quoted(String text){
        StringBuilder sb=new StringBuilder("\"");
        for(int i=0;i<text.length();){
            int cp=text.codePointAt(i);
            if(cp=='\\')sb.append("\\\\");
            else if(cp=='"')sb.append("\\\"");
            else if(cp=='\n')sb.append("\\n");
            else if(cp=='\t')sb.append("\\t");
            else if(cp<0x20||(cp>=0x7F&&cp<=0x9F))sb.append(String.format("\\u%04x",cp));
            else sb.appendCodePoint(cp);
            i+=Character.charCount(cp);
        }
        sb.append("\"");
        return sb.toString();
    }
}

import * as fs from 'fs';
import * as path from 'path';

// CRC-32 (zlib/PNG)
function crc32(data: Buffer): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
            else crc >>>= 1;
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

const CP1252_HIGH: number[] = [
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
    0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
    0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
    0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
];

function normalizeCharset(cs: string): string {
    return cs.toLowerCase().replace(/[^a-z0-9]/g, '');
}

function decodeBytesToText(bytes: Buffer, charset: string): string {
    const nc = normalizeCharset(charset);
    if (nc === 'utf8') return bytes.toString('utf-8');
    if (nc === 'usascii' || nc === 'iso88591' || nc === 'latin1') return bytes.toString('latin1');
    if (nc === 'windows1252' || nc === 'cp1252') {
        let s = '';
        for (let i = 0; i < bytes.length; i++) {
            const b = bytes[i];
            if (b >= 0x80 && b <= 0x9F) s += String.fromCodePoint(CP1252_HIGH[b - 0x80]);
            else s += String.fromCharCode(b);
        }
        return s;
    }
    return bytes.toString('latin1');
}

function hexVal(c: string): number {
    if (c >= '0' && c <= '9') return c.charCodeAt(0) - 0x30;
    if (c >= 'a' && c <= 'f') return c.charCodeAt(0) - 0x61 + 10;
    if (c >= 'A' && c <= 'F') return c.charCodeAt(0) - 0x41 + 10;
    return -1;
}

function matchesAt(data: Buffer, pos: number, pattern: Buffer): boolean {
    if (pos + pattern.length > data.length) return false;
    for (let i = 0; i < pattern.length; i++) {
        if (data[pos + i] !== pattern[i]) return false;
    }
    return true;
}

const B64ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64LOOKUP = new Int8Array(256).fill(-1);
for (let i = 0; i < B64ALPHA.length; i++) B64LOOKUP[B64ALPHA.charCodeAt(i)] = i;

function decodeBase64Bytes(data: Buffer): Buffer {
    const vals: number[] = [];
    for (let i = 0; i < data.length; i++) {
        const b = data[i];
        if (b === 0x3D) break;
        const v = B64LOOKUP[b];
        if (v >= 0) vals.push(v);
    }
    const result: number[] = [];
    for (let i = 0; i < vals.length; i += 4) {
        const g = vals.slice(i, Math.min(i + 4, vals.length));
        if (g.length >= 2) result.push((g[0] << 2) | (g[1] >> 4));
        if (g.length >= 3) result.push(((g[1] & 0xF) << 4) | (g[2] >> 2));
        if (g.length >= 4) result.push(((g[2] & 0x3) << 6) | g[3]);
    }
    return Buffer.from(result);
}

function decodeBase64Str(s: string): number[] {
    const vals: number[] = [];
    for (let i = 0; i < s.length; i++) {
        const b = s.charCodeAt(i);
        if (b === 0x3D) break;
        const v = B64LOOKUP[b];
        if (v >= 0) vals.push(v);
    }
    const result: number[] = [];
    for (let i = 0; i < vals.length; i += 4) {
        const g = vals.slice(i, Math.min(i + 4, vals.length));
        if (g.length >= 2) result.push((g[0] << 2) | (g[1] >> 4));
        if (g.length >= 3) result.push(((g[1] & 0xF) << 4) | (g[2] >> 2));
        if (g.length >= 4) result.push(((g[2] & 0x3) << 6) | g[3]);
    }
    return result;
}

function decodeQStr(s: string): number[] {
    const result: number[] = [];
    let i = 0;
    while (i < s.length) {
        if (s[i] === '_') { result.push(0x20); i++; }
        else if (s[i] === '=' && i + 2 < s.length) {
            const h1 = hexVal(s[i + 1]);
            const h2 = hexVal(s[i + 2]);
            if (h1 >= 0 && h2 >= 0) { result.push(h1 * 16 + h2); i += 3; }
            else { result.push(0x3D); i++; }
        } else { result.push(s.charCodeAt(i)); i++; }
    }
    return result;
}

function processQPBytes(data: Buffer, start: number, end: number, result: number[]): void {
    let i = start;
    while (i < end) {
        if (data[i] === 0x3D && i + 2 < end) {
            const h1 = hexVal(String.fromCharCode(data[i + 1]));
            const h2 = hexVal(String.fromCharCode(data[i + 2]));
            if (h1 >= 0 && h2 >= 0) { result.push(h1 * 16 + h2); i += 3; continue; }
        }
        result.push(data[i]);
        i++;
    }
}

function decodeQP(data: Buffer, lineEnding: string): Buffer {
    const le = Buffer.from(lineEnding);
    const result: number[] = [];
    let pos = 0;
    while (pos <= data.length) {
        let lineEnd = pos;
        while (lineEnd < data.length) {
            if (matchesAt(data, lineEnd, le)) break;
            lineEnd++;
        }
        let contentEnd = lineEnd;
        while (contentEnd > pos && (data[contentEnd - 1] === 0x20 || data[contentEnd - 1] === 0x09)) {
            contentEnd--;
        }
        let isSoft = false;
        if (contentEnd > pos && data[contentEnd - 1] === 0x3D) {
            isSoft = true;
            contentEnd--;
        }
        processQPBytes(data, pos, contentEnd, result);
        if (!isSoft && lineEnd < data.length) {
            for (let k = 0; k < le.length; k++) result.push(le[k]);
        }
        if (lineEnd >= data.length) break;
        pos = lineEnd + le.length;
    }
    return Buffer.from(result);
}

function decodeTransferEncoding(data: Buffer, encoding: string, lineEnding: string): Buffer {
    const enc = encoding.toLowerCase();
    if (enc === 'base64') return decodeBase64Bytes(data);
    if (enc === 'quoted-printable') return decodeQP(data, lineEnding);
    return data;
}

interface EW {
    start: number;
    end: number;
    charset: string;
    encoding: string;
    text: string;
}

function decodeRFC2047(input: string): string {
    const ewRegex = /=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=/g;
    const words: EW[] = [];
    let m: RegExpExecArray | null;
    while ((m = ewRegex.exec(input)) !== null) {
        let cs = m[1].toLowerCase();
        const si = cs.indexOf('*');
        if (si >= 0) cs = cs.substring(0, si);
        words.push({ start: m.index, end: m.index + m[0].length, charset: cs, encoding: m[2].toUpperCase(), text: m[3] });
    }
    if (words.length === 0) return input;

    const adjacent: boolean[] = [];
    for (let i = 0; i < words.length - 1; i++) {
        const between = input.substring(words[i].end, words[i + 1].start);
        adjacent.push(/^[ \t]*$/.test(between));
    }

    let output = '';
    let pos = 0;
    let i = 0;
    while (i < words.length) {
        if (i === 0 || !adjacent[i - 1]) {
            output += input.substring(pos, words[i].start);
        }
        const charset = words[i].charset;
        const groupStart = i;
        i++;
        while (i < words.length && adjacent[i - 1] && words[i].charset === charset) {
            i++;
        }
        const bytes: number[] = [];
        for (let j = groupStart; j < i; j++) {
            if (words[j].encoding === 'B') bytes.push(...decodeBase64Str(words[j].text));
            else bytes.push(...decodeQStr(words[j].text));
        }
        output += decodeBytesToText(Buffer.from(bytes), charset);
