        while(i<len){
            uint32_t c;
            if(data[i]<0x80){c=data[i];i+=1;}
            else if((data[i]&0xE0)==0xC0){c=(data[i]&0x1F)<<6|(data[i+1]&0x3F);i+=2;}
            else if((data[i]&0xF0)==0xE0){c=(data[i]&0x0F)<<12|(data[i+1]&0x3F)<<6|(data[i+2]&0x3F);i+=3;}
            else{c=(data[i]&0x07)<<18|(data[i+1]&0x3F)<<12|(data[i+2]&0x3F)<<6|(data[i+3]&0x3F);i+=4;}
            cp[n++]=c;
        }
    }else if(ci_cmp(cs,"iso-8859-1")==0){
        for(size_t i=0;i<len;i++)cp[n++]=data[i];
    }else if(ci_cmp(cs,"windows-1252")==0){
        for(size_t i=0;i<len;i++){
            if(data[i]>=0x80&&data[i]<=0x9F)cp[n++]=cp1252[data[i]-0x80];
            else cp[n++]=data[i];
        }
    }else{
        for(size_t i=0;i<len;i++)cp[n++]=data[i];
    }
    *outlen=n;return cp;
}

/* ===== UTF-8 encode ===== */
static void utf8_enc(uint32_t cp,Buf*out){
    if(cp<0x80)buf_addc(out,(char)cp);
    else if(cp<0x800){buf_addc(out,(char)(0xC0|(cp>>6)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
    else if(cp<0x10000){buf_addc(out,(char)(0xE0|(cp>>12)));buf_addc(out,(char)(0x80|((cp>>6)&0x3F)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
    else{buf_addc(out,(char)(0xF0|(cp>>18)));buf_addc(out,(char)(0x80|((cp>>12)&0x3F)));buf_addc(out,(char)(0x80|((cp>>6)&0x3F)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
}

/* ===== RFC 2047 encoded-words ===== */
typedef struct{int start,end;char charset[512];unsigned char*bytes;size_t nbytes;}EW;
static int try_match_ew(const char*t,int len,int pos,int*endp,char*charset,int*encp,const char**etp,size_t*etlenp){
    if(pos+1>=len||t[pos]!='='||t[pos+1]!='?')return 0;
    int p=pos+2;
    int cs_s=p;
    while(p<len&&t[p]!='?'&&t[p]!=' '&&t[p]!='\t')p++;
    if(p==cs_s)return 0;
    if(p>=len||t[p]!='?')return 0;
    int cs_len=p-cs_s;
    p++;
    if(p>=len)return 0;
    int enc=t[p];
    if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q')return 0;
    p++;
    if(p>=len||t[p]!='?')return 0;
    p++;
    int et_s=p;
    while(p<len&&t[p]!='?'&&t[p]!=' '&&t[p]!='\t')p++;
    if(p+1>=len||t[p]!='?'||t[p+1]!='=')return 0;
    memcpy(charset,t+cs_s,cs_len);charset[cs_len]=0;
    *encp=enc;*etp=t+et_s;*etlenp=p-et_s;*endp=p+2;
    return 1;
}
static void strip_lang(char*cs){char*star=strchr(cs,'*');if(star)*star=0;}
static unsigned char*ew_decode_bytes(const char*et,size_t etlen,int enc,size_t*outlen){
    if(enc=='B'||enc=='b')return b64_decode((const unsigned char*)et,etlen,outlen);
    unsigned char*r=malloc(etlen+1);size_t n=0;
    for(size_t i=0;i<etlen;){
        if(et[i]=='='&&i+2<etlen&&is_hex(et[i+1])&&is_hex(et[i+2])){r[n++]=(unsigned char)(hex_val(et[i+1])*16+hex_val(et[i+2]));i+=3;}
        else if(et[i]=='_'){r[n++]=0x20;i++;}
        else{r[n++]=(unsigned char)et[i];i++;}
    }
    *outlen=n;return r;
}
static char*decode_rfc2047(const char*text){
    int len=strlen(text);
    EW words[256];int nw=0;
    int pos=0;
    while(pos<len){
        int found=-1;
        for(int i=pos;i<len-1;i++){
            int end;char cs[512];int enc;const char*et;size_t etl;
            if(try_match_ew(text,len,i,&end,cs,&enc,&et,&etl)){found=i;break;}
        }
        if(found<0)break;
        int end;char cs[512];int enc;const char*et;size_t etl;
        try_match_ew(text,len,found,&end,cs,&enc,&et,&etl);
        size_t nbytes;unsigned char*bytes=ew_decode_bytes(et,etl,enc,&nbytes);
        if(nw<256){words[nw].start=found;words[nw].end=end;strcpy(words[nw].charset,cs);words[nw].bytes=bytes;words[nw].nbytes=nbytes;nw++;}
        pos=end;
    }
    Buf out;buf_init(&out);
    int prev_end=0,i=0;
    while(i<nw){
        int gap_start=prev_end,gap_end=words[i].start;
        if(i>0){
            int adj=1;for(int k=gap_start;k<gap_end;k++){if(text[k]!=' '&&text[k]!='\t'){adj=0;break;}}
            if(!adj)buf_add(&out,text+gap_start,gap_end-gap_start);
        }else{
            buf_add(&out,text+gap_start,gap_end-gap_start);
        }
        char gcs[512];strcpy(gcs,words[i].charset);strip_lang(gcs);
        Buf gbuf;buf_init(&gbuf);
        buf_add(&gbuf,words[i].bytes,words[i].nbytes);
        int j=i+1;
        while(j<nw){
            int g2s=words[j-1].end,g2e=words[j].start;
            int adj2=1;for(int k=g2s;k<g2e;k++){if(text[k]!=' '&&text[k]!='\t'){adj2=0;break;}}
            if(!adj2)break;
            char cs2[512];strcpy(cs2,words[j].charset);strip_lang(cs2);
            if(ci_cmp(gcs,cs2)!=0)break;
            buf_add(&gbuf,words[j].bytes,words[j].nbytes);
            j++;
        }
        size_t cplen;uint32_t*cps=charset_decode((unsigned char*)gbuf.d,gbuf.len,gcs,&cplen);
        for(size_t k=0;k<cplen;k++)utf8_enc(cps[k],&out);
        free(cps);free(gbuf.d);
        prev_end=words[j-1].end;
        i=j;
    }
    if(prev_end<len)buf_add(&out,text+prev_end,len-prev_end);
    for(int k=0;k<nw;k++)free(words[k].bytes);
    return buf_str(&out);
}

/* ===== Headers ===== */
typedef struct{char*name;char*value;}Header;
static const char*find_header(Header*h,int n,const char*name){
    for(int i=0;i<n;i++)if(ci_cmp(h[i].name,name)==0)return h[i].value;
    return NULL;
}

/* ===== Parameters ===== */
typedef struct{char name[512];char*value;}Param;
static void parse_params(const char*s,Param*params,int*nparams){
    *nparams=0;
    while(*s){
        while(*s==' '||*s=='\t')s++;
        if(!*s)break;
        if(*s==';'){s++;continue;}
        char nm[512];int ni=0;
        while(*s&&*s!='='&&*s!=' '&&*s!='\t'&&*s!=';'){if(ni<511)nm[ni++]=*s;s++;}
        nm[ni]=0;
        while(*s==' '||*s=='\t')s++;
        if(*s!='='){continue;}
        s++;
        while(*s==' '||*s=='\t')s++;
        char*val;
        if(*s=='"'){
            s++;Buf vb;buf_init(&vb);
            while(*s&&*s!='"'){if(*s=='\\'&&s[1]){s++;buf_addc(&vb,*s);s++;}else{buf_addc(&vb,*s);s++;}}
            if(*s=='"')s++;
            buf_addc(&vb,0);val=vb.d;
        }else{
            Buf vb;buf_init(&vb);
            while(*s&&*s!=';'&&*s!=' '&&*s!='\t'){buf_addc(&vb,*s);s++;}
            buf_addc(&vb,0);val=vb.d;
        }
        if(*nparams<64){
            for(int k=0;k<ni;k++)params[*nparams].name[k]=tolower((unsigned char)nm[k]);
            params[*nparams].name[ni]=0;
            params[*nparams].value=val;
            (*nparams)++;
        }
    }
}

/* ===== RFC 2231 ===== */
static void percent_dec(const char*s,Buf*out){
    while(*s){
        if(*s=='%'&&is_hex(s[1])&&is_hex(s[2])){buf_addc(out,(char)(hex_val(s[1])*16+hex_val(s[2])));s+=3;}
        else{buf_addc(out,*s);s++;}
    }
}
static char*decode_rfc2231(Param*params,int np,const char*attr){
    char prefix[512];snprintf(prefix,sizeof(prefix),"%s*",attr);
    int has_2231=0;
    for(int i=0;i<np;i++){
        if(ci_cmp(params[i].name,prefix)==0||strlen(params[i].name)>strlen(prefix)&&ci_cmp(params[i].name,prefix)==0){
            // check if name starts with attr*
            if(strncasecmp(params[i].name,prefix,strlen(prefix))==0||ci_cmp(params[i].name,prefix)==0){has_2231=1;break;}
        }
        // Also check attr*N and attr*N*
        size_t alen=strlen(attr);
        if(strlen(params[i].name)>alen&&params[i].name[alen]=='*'){
            has_2231=1;break;
        }
    }
    if(!has_2231)return NULL;
    // Collect segments
    struct{int idx;int pct;char*val;}segs[64];int ns=0;
    char charset[512]="us-ascii";
    for(int i=0;i<np;i++){
        size_t alen=strlen(attr);
        if(strlen(params[i].name)<=alen)continue;
        if(params[i].name[alen]!='*')continue;
        const char*rest=params[i].name+alen+1;
        // rest is either "" (single form attr*), or "N" (literal), or "N*" (percent-encoded)
        if(*rest==0){
            // Single form: attr*=charset'lang'value
            // percent-encoded
            const char*v=params[i].value;
            const char*q1=strchr(v,'\'');
            if(q1){
                size_t cl=q1-v;if(cl>511)cl=511;
                memcpy(charset,v,cl);charset[cl]=0;
                const char*q2=strchr(q1+1,'\'');
                if(q2){v=q2+1;}else{v=q1+1;}
            }
            Buf pb;buf_init(&pb);percent_dec(v,&pb);
            if(ns<64){segs[ns].idx=0;segs[ns].pct=1;segs[ns].val=pb.d;ns++;}
        }else{
            // Continuation
            int idx=atoi(rest);
            int pct=0;
            const char*end=rest;while(*end&&*end>='0'&&*end<='9')end++;
            if(*end=='*')pct=1;
            if(pct){
                const char*v=params[i].value;
                if(idx==0){
                    const char*q1=strchr(v,'\'');
                    if(q1){
                        size_t cl=q1-v;if(cl>511)cl=511;
                        memcpy(charset,v,cl);charset[cl]=0;
                        const char*q2=strchr(q1+1,'\'');
                        if(q2){v=q2+1;}else{v=q1+1;}
                    }
                }
                Buf pb;buf_init(&pb);percent_dec(v,&pb);
                if(ns<64){segs[ns].idx=idx;segs[ns].pct=1;segs[ns].val=pb.d;ns++;}
            }else{
                if(ns<64){segs[ns].idx=idx;segs[ns].pct=0;segs[ns].val=xstrdup(params[i].value);ns++;}
            }
        }
    }
    if(ns==0)return NULL;
    // Sort by idx
    for(int i=0;i<ns-1;i++)for(int j=i+1;j<ns;j++){if(segs[j].idx<segs[i].idx){typeof(segs[0])t=segs[i];segs[i]=segs[j];segs[j]=t;}}
    // Concatenate
    Buf all;buf_init(&all);
    for(int i=0;i<ns;i++)buf_add(&all,segs[i].val,strlen(segs[i].val));
    // Decode charset
    size_t cplen;uint32_t*cps=charset_decode((unsigned char*)all.d,all.len,charset,&cplen);
    Buf out;buf_init(&out);
    for(size_t k=0;k<cplen;k++)utf8_enc(cps[k],&out);
    free(cps);free(all.d);
    for(int i=0;i<ns;i++)free(segs[i].val);
    return buf_str(&out);
}

/* ===== Entity ===== */
typedef struct Entity{
    Header*headers;int nheaders;
    unsigned char*body;size_t body_len;
    struct Entity**children;int nchildren;
    int is_multipart;
}Entity;

static Entity*parse_entity(const unsigned char*data,size_t len,int crlf);

static int find_sep(const unsigned char*data,size_t len,int crlf,size_t*hdr_end,size_t*body_start){
    size_t pos=0,lb=crlf?2:1;
    while(pos<=len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        if(le==pos){
            *hdr_end=pos;
            *body_start=(le<len)?le+lb:len;
            return 1;
        }
        if(le>=len)break;
        pos=le+lb;
    }
    *hdr_end=len;*body_start=len;return 0;
}

static void parse_hdrs(const unsigned char*data,size_t len,int crlf,Header**hp,int*nhp){
    Header*hs=NULL;int nh=0,cap=0;
    size_t pos=0,lb=crlf?2:1;
    while(pos<len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        // Check if next line is continuation (starts with space/tab)
        size_t next=pos+((le<len)?lb:0);
        // Unfold: collect this line and continuations
        Buf line;buf_init(&line);
        buf_add(&line,data+pos,le-pos);
        while(next<len){
            if(data[next]==' '||data[next]=='\t'){
                // continuation
                buf_addc(&line,data[next]); // keep the space/tab
                size_t le2=next+1;
                while(le2<len){if(crlf){if(data[le2]=='\r'&&le2+1<len&&data[le2+1]=='\n')break;}else{if(data[le2]=='\n')break;}le2++;}
                buf_add(&line,data+next+1,le2-next-1);
                next=le2+((le2<len)?lb:0);
            }else break;
        }
        buf_addc(&line,0);
        // Parse Name: value
        char*ln=line.d;
        char*colon=strchr(ln,':');
        if(colon){
            size_t nlen=colon-ln;
            char*name=xstrndup(ln,nlen);
            // trim name trailing spaces
            while(nlen>0&&(name[nlen-1]==' '||name[nlen-1]=='\t')){name[--nlen]=0;}
            const char*val=colon+1;
            while(*val==' '||*val=='\t')val++;
            size_t vlen=strlen(val);
            while(vlen>0&&(val[vlen-1]==' '||val[vlen-1]=='\t'))vlen--;
            char*v=xstrndup(val,vlen);
            if(nh>=cap){cap=cap?cap*2:8;hs=realloc(hs,cap*sizeof(Header));}
            hs[nh].name=name;hs[nh].value=v;nh++;
        }
        free(line.d);
        if(le>=len)break;
        pos=le+lb;
    }
    *hp=hs;*nhp=nh;
}

typedef struct{char type[256],subtype[256];Param params[64];int nparams;}CT;
static void parse_ct(const char*v,CT*ct){
    memset(ct,0,sizeof(*ct));
    const char*slash=strchr(v,'/');
    if(!slash){strcpy(ct->type,"text");strcpy(ct->subtype,"plain");return;}
    size_t tl=slash-v;while(tl>0&&(v[tl-1]==' '||v[tl-1]=='\t'))tl--;
    for(size_t i=0;i<tl&&i<255;i++)ct->type[i]=tolower((unsigned char)v[i]);ct->type[tl]=0;
    const char*sp=slash+1;while(*sp==' '||*sp=='\t')sp++;
    const char*semi=strchr(sp,';');
    size_t sl=semi?(size_t)(semi-sp):strlen(sp);
    while(sl>0&&(sp[sl-1]==' '||sp[sl-1]=='\t'))sl--;
    for(size_t i=0;i<sl&&i<255;i++)ct->subtype[i]=tolower((unsigned char)sp[i]);ct->subtype[sl]=0;
    if(semi)parse_params(semi+1,ct->params,&ct->nparams);
}
typedef struct{char disp[256];Param params[64];int nparams;}CD;
static void parse_cd(const char*v,CD*cd){
    memset(cd,0,sizeof(*cd));
    const char*semi=strchr(v,';');
    size_t dl=semi?(size_t)(semi-v):strlen(v);
    while(dl>0&&(v[dl-1]==' '||v[dl-1]=='\t'))dl--;
    while(dl>0&&(v[0]==' '||v[0]=='\t')){v++;dl--;}
    for(size_t i=0;i<dl&&i<255;i++)cd->disp[i]=tolower((unsigned char)v[i]);cd->disp[dl]=0;
    if(semi)parse_params(semi+1,cd->params,&cd->nparams);
}
static const char*param_get(Param*p,int n,const char*name){
    for(int i=0;i<n;i++)if(ci_cmp(p[i].name,name)==0)return p[i].value;
    return NULL;
}

/* ===== Delimiter finding ===== */
typedef struct{size_t ls,le,fe;int close;}Delim;
static int find_delims(const unsigned char*data,size_t len,const char*bnd,int crlf,Delim**outp,int*noutp){
    size_t lb=crlf?2:1,bl=strlen(bnd);
    int cap=16,n=0;Delim*arr=malloc(cap*sizeof(Delim));
    size_t pos=0;
    while(pos<=len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        int isd=0,isc=0;
        if(le-pos>=2+bl&&data[pos]=='-'&&data[pos+1]=='-'&&memcmp(data+pos+2,bnd,bl)==0){
            size_t ab=pos+2+bl;
            if(ab+2<=le&&data[ab]=='-'&&data[ab+1]=='-'){
                int ok=1;for(size_t k=ab+2;k<le;k++)if(data[k]!=' '&&data[k]!='\t'){ok=0;break;}
                if(ok){isd=1;isc=1;}
            }
            if(!isd){
                int ok=1;for(size_t k=ab;k<le;k++)if(data[k]!=' '&&data[k]!='\t'){ok=0;break;}
                if(ok){isd=1;isc=0;}
            }
        }
        if(isd){
            if(n>=cap){cap*=2;arr=realloc(arr,cap*sizeof(Delim));}
            arr[n].ls=pos;arr[n].le=le;arr[n].fe=(le<len)?le+lb:len;arr[n].close=isc;n++;
        }
        if(le>=len)break;
        pos=le+lb;
    }
    *outp=arr;*noutp=n;return n;
}

static Entity*parse_entity(const unsigned char*data,size_t len,int crlf){
    Entity*e=calloc(1,sizeof(Entity));
    size_t hdr_end,body_start;
    find_sep(data,len,crlf,&hdr_end,&body_start);
    parse_hdrs(data,hdr_end,crlf,&e->headers,&e->nheaders);
    const char*ctv=find_header(e->headers,e->nheaders,"content-type");
    CT ct;
    if(ctv)parse_ct(ctv,&ct);
    else{strcpy(ct.type,"text");strcpy(ct.subtype,"plain");ct.nparams=0;}
    if(strcmp(ct.type,"multipart")==0){
        e->is_multipart=1;
        const char*bnd=param_get(ct.params,ct.nparams,"boundary");
        if(!bnd)bnd="";
        const unsigned char*body=data+body_start;
        size_t blen=len-body_start;
        Delim*dels=NULL;int nd=0;
        if(strlen(bnd)>0)find_delims(body,blen,bnd,crlf,&dels,&nd);
        int fr=-1,cl=-1;
        for(int i=0;i<nd;i++){if(!dels[i].close&&fr<0)fr=i;if(dels[i].close&&fr>=0&&cl<0)cl=i;}
        if(fr>=0){
            int end_idx=(cl>=0)?cl:nd;
            int np=end_idx-fr;
            if(np<0)np=0;
            e->children=calloc(np,sizeof(Entity*));
            e->nchildren=np;
            for(int i=0;i<np;i++){
                size_t cs=dels[fr+i].fe;
                size_t ce;
                if(fr+i+1<nd)ce=dels[fr+i+1].ls;
                else ce=blen;
                // strip trailing line break
                if(ce>cs){
                    if(crlf&&ce>=cs+2&&body[ce-2]=='\r'&&body[ce-1]=='\n')ce-=2;
                    else if(!crlf&&body[ce-1]=='\n')ce-=1;
                }
                e->children[i]=parse_entity(body+cs,ce-cs,crlf);
            }
        }
        free(dels);
    }else{
        e->body=(unsigned char*)data+body_start;
        e->body_len=len-body_start;
    }
    return e;
}

/* ===== Output ===== */
static void print_quoted(Buf*out,const uint32_t*cps,size_t n){
    buf_addc(out,'"');
    for(size_t i=0;i<n;i++){
        uint32_t c=cps[i];
        if(c=='\\'){buf_addstr(out,"\\\\");}
        else if(c=='"'){buf_addstr(out,"\\\"");}
        else if(c=='\n'){buf_addstr(out,"\\n");}
        else if(c=='\t'){buf_addstr(out,"\\t");}
        else if(c<0x20||(c>=0x7F&&c<=0x9F)){
            char tmp[8];sprintf(tmp,"\\u%04x",c);buf_addstr(out,tmp);
        }else{
            utf8_enc(c,out);
        }
    }
    buf_addc(out,'"');
}

static void print_entity(Entity*e,int depth){
    const char*ctv=find_header(e->headers,e->nheaders,"content-type");
    CT ct;
    if(ctv)parse_ct(ctv,&ct);
    else{strcpy(ct.type,"text");strcpy(ct.subtype,"plain");ct.nparams=0;}
    const char*cdv=find_header(e->headers,e->nheaders,"content-disposition");
    CD cd;
    if(cdv)parse_cd(cdv,&cd);
    else{cd.disp[0]=0;cd.nparams=0;}
    const char*ctev=find_header(e->headers,e->nheaders,"content-transfer-encoding");
    char cte[64]="7bit";
    if(ctev){for(size_t i=0;i<strlen(ctev)&&i<63;i++)cte[i]=tolower((unsigned char)ctev[i]);cte[strlen(ctev)]=0;}

    for(int i=0;i<depth*2;i++)putchar(' ');

    if(e->is_multipart){
        printf("multipart/%s parts=%d\n",ct.subtype,e->nchildren);
        for(int i=0;i<e->nchildren;i++)print_entity(e->children[i],depth+1);
    }else{
        int is_text=(strcmp(ct.type,"text")==0&&strcmp(cd.disp,"attachment")!=0);
        if(is_text){
            const char*cs=param_get(ct.params,ct.nparams,"charset");
            char charset[256]="us-ascii";
            if(cs){for(size_t i=0;i<strlen(cs)&&i<255;i++)charset[i]=tolower((unsigned char)cs[i]);charset[strlen(cs)]=0;}
            // Decode body
            unsigned char*dec=NULL;size_t dlen=0;
            if(strcmp(cte,"base64")==0)dec=b64_decode(e->body,e->body_len,&dlen);
            else if(strcmp(cte,"quoted-printable")==0)dec=qp_decode(e->body,e->body_len,0,&dlen); // crlf detection done at file level
            else{dec=malloc(e->body_len);memcpy(dec,e->body,e->body_len);dlen=e->body_len;}
            size_t cplen;uint32_t*cps=charset_decode(dec,dlen,charset,&cplen);
            // Replace CRLF and lone CR with LF
            size_t n2=0;
            for(size_t i=0;i<cplen;i++){
                if(cps[i]==0x0D){
                    if(i+1<cplen&&cps[i+1]==0x0A){cps[n2++]=0x0A;i++;}
                    else cps[n2++]=0x0A;
                }else cps[n2++]=cps[i];
            }
            printf("text/%s charset=%s cte=%s chars=%zu\n",ct.subtype,charset,cte,n2);
            for(int i=0;i<(depth+1)*2;i++)putchar(' ');
            Buf qb;buf_init(&qb);
            print_quoted(&qb,cps,n2);
            printf("%s\n",qb.d);
            free(qb.d);free(cps);free(dec);
        }else{
            // Non-text or attachment
            unsigned char*dec=NULL;size_t dlen=0;
            if(strcmp(cte,"base64")==0)dec=b64_decode(e->body,e->body_len,&dlen);
            else if(strcmp(cte,"quoted-printable")==0)dec=qp_decode(e->body,e->body_len,0,&dlen);
            else{dec=malloc(e->body_len);memcpy(dec,e->body,e->body_len);dlen=e->body_len;}
            uint32_t c=crc32(dec,dlen);
            // Get name
            char*name=NULL;
            // RFC 2231 filename from CD
            name=decode_rfc2231(cd.params,cd.nparams,"filename");
            if(!name){const char*f=param_get(cd.params,cd.nparams,"filename");if(f)name=decode_rfc2047(f);}
            if(!name)name=decode_rfc2231(ct.params,ct.nparams,"name");
            if(!name){const char*nm=param_get(ct.params,ct.nparams,"name");if(nm)name=decode_rfc2047(nm);}
            printf("%s/%s cte=%s disposition=%s name=",ct.type,ct.subtype,cte,cd.disp[0]?cd.disp:"-");
            if(name){
                // Decode as code points for quoted string
                size_t cplen;uint32_t*cps=charset_decode((unsigned char*)name,strlen(name),"utf-8",&cplen);
                Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
                printf("%s",qb.d);free(qb.d);free(cps);
                free(name);
            }else printf("-");
            printf(" size=%zu crc32=%08x\n",dlen,c);
            free(dec);
        }
    }
}

/* ===== Main ===== */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char*argv[]){
    crc32_init();
    if(argc<2)return 1;
    DIR*dir=opendir(argv[1]);
    if(!dir)return 1;
    char*files[4096];int nf=0;
    struct dirent*ent;
    while((ent=readdir(dir))){
        size_t l=strlen(ent->d_name);
        if(l>4&&strcmp(ent->d_name+l-4,".eml")==0)files[nf++]=xstrdup(ent->d_name);
    }
    closedir(dir);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)printf("\n");
        printf("== %s\n",files[fi]);
        char path[4096];snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
        unsigned char*data=malloc(sz+1);
        fread(data,1,sz,f);fclose(f);
        // Detect line ending
        int crlf=0;
        for(long i=0;i<sz-1;i++){if(data[i]=='\r'&&data[i+1]=='\n'){crlf=1;break;}if(data[i]=='\n')break;}
        Entity*msg=parse_entity(data,sz,crlf);
        // Print From and Subject
        const char*fromv=find_header(msg->headers,msg->nheaders,"from");
        const char*subjv=find_header(msg->headers,msg->nheaders,"subject");
        printf("From: ");
        if(fromv){
            char*dec=decode_rfc2047(fromv);
            size_t cplen;uint32_t*cps=charset_decode((unsigned char*)dec,strlen(dec),"utf-8",&cplen);
            Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
            printf("%s\n",qb.d);free(qb.d);free(cps);free(dec);
        }else printf("-\n");
        printf("Subject: ");
        if(subjv){
            char*dec=decode_rfc2047(subjv);
            size_t cplen;uint32_t*cps=charset_decode((unsigned char*)dec,strlen(dec),"utf-8",&cplen);
            Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
            printf("%s\n",qb.d);free(qb.d);free(cps);free(dec);
        }else printf("-\n");
        print_entity(msg,0);
        free(data);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <sys/stat.h>
#include <stdint.h>
#include <stdarg.h>

/* ===== CRC-32 ===== */
static uint32_t crc32_tab[256];
static void crc32_init(void){
    for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?(0xEDB88320^(c>>1)):(c>>1);crc32_tab[i]=c;}
}
static uint32_t crc32(const unsigned char*d,size_t n){
    uint32_t c=0xFFFFFFFF;for(size_t i=0;i<n;i++)c=crc32_tab[(c^d[i])&0xFF]^(c>>8);return c^0xFFFFFFFF;
}

/* ===== Utility ===== */
static int is_hex(char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}
static int hex_val(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;return c-'A'+10;}
static int is_b64(char c){return(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/';}
static int b64_val(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;return 63;}
static char *xstrdup(const char*s){char*r=malloc(strlen(s)+1);strcpy(r,s);return r;}
static char *xstrndup(const char*s,size_t n){char*r=malloc(n+1);memcpy(r,s,n);r[n]=0;return r;}
static int ci_cmp(const char*a,const char*b){while(*a&&*b){if(tolower((unsigned char)*a)!=tolower((unsigned char)*b))return tolower((unsigned char)*a)-tolower((unsigned char)*b);a++;b++;}return tolower((unsigned char)*a)-tolower((unsigned char)*b);}

/* ===== Dynamic buffer ===== */
typedef struct{char*d;size_t len,cap;}Buf;
static void buf_init(Buf*b){b->d=NULL;b->len=0;b->cap=0;}
static void buf_res(Buf*b,size_t n){if(b->len+n>b->cap){b->cap=(b->len+n)*2+64;b->d=realloc(b->d,b->cap);}}
static void buf_add(Buf*b,const void*d,size_t n){buf_res(b,n);memcpy(b->d+b->len,d,n);b->len+=n;}
static void buf_addc(Buf*b,char c){buf_res(b,1);b->d[b->len++]=c;}
static void buf_addstr(Buf*b,const char*s){buf_add(b,s,strlen(s));}
static char *buf_str(Buf*b){buf_res(b,1);b->d[b->len]=0;return b->d;}

/* ===== Base64 decode ===== */
static unsigned char*b64_decode(const unsigned char*in,size_t inlen,size_t*outlen){
    unsigned char*ch=malloc(inlen+1);size_t nc=0;
    for(size_t i=0;i<inlen;i++){if(in[i]=='=')break;if(is_b64((char)in[i]))ch[nc++]=in[i];}
    unsigned char*out=malloc(nc/4*3+4);size_t ol=0;
    for(size_t i=0;i+3<nc;i+=4){
        uint32_t v=((uint32_t)b64_val((char)ch[i])<<18)|((uint32_t)b64_val((char)ch[i+1])<<12)|((uint32_t)b64_val((char)ch[i+2])<<6)|b64_val((char)ch[i+3]);
        out[ol++]=(v>>16)&0xFF;out[ol++]=(v>>8)&0xFF;out[ol++]=v&0xFF;
    }
    size_t rem=nc%4;
    if(rem==2){uint32_t v=((uint32_t)b64_val((char)ch[nc-2])<<18)|((uint32_t)b64_val((char)ch[nc-1])<<12);out[ol++]=(v>>16)&0xFF;}
    else if(rem==3){uint32_t v=((uint32_t)b64_val((char)ch[nc-3])<<18)|((uint32_t)b64_val((char)ch[nc-2])<<12)|((uint32_t)b64_val((char)ch[nc-1])<<6);out[ol++]=(v>>16)&0xFF;out[ol++]=(v>>8)&0xFF;}
    free(ch);*outlen=ol;return out;
}

/* ===== Quoted-printable decode ===== */
static unsigned char*qp_decode(const unsigned char*in,size_t inlen,int crlf,size_t*outlen){
    Buf tmp;buf_init(&tmp);
    size_t pos=0,lb=crlf?2:1;
    while(pos<=inlen){
        size_t le=pos;
        while(le<inlen){if(crlf){if(in[le]=='\r'&&le+1<inlen&&in[le+1]=='\n')break;}else{if(in[le]=='\n')break;}le++;}
        size_t ce=le;
        while(ce>pos&&(in[ce-1]==' '||in[ce-1]=='\t'))ce--;
        if(ce>pos&&in[ce-1]=='='){
            buf_add(&tmp,in+pos,ce-pos-1);
        }else{
            buf_add(&tmp,in+pos,ce-pos);
            if(le<inlen){if(crlf){buf_addc(&tmp,'\r');buf_addc(&tmp,'\n');}else buf_addc(&tmp,'\n');}
        }
        if(le>=inlen)break;
        pos=le+lb;
    }
    unsigned char*res=malloc(tmp.len+1);size_t rl=0;
    for(size_t i=0;i<tmp.len;){
        if(tmp.d[i]=='='&&i+2<tmp.len&&is_hex(tmp.d[i+1])&&is_hex(tmp.d[i+2])){
            res[rl++]=(unsigned char)(hex_val(tmp.d[i+1])*16+hex_val(tmp.d[i+2]));i+=3;
        }else{res[rl++]=(unsigned char)tmp.d[i];i++;}
    }
    free(tmp.d);*outlen=rl;return res;
}

/* ===== Charset decode ===== */
static const uint32_t cp1252[32]={
    0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
    0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
    0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
    0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
};
static uint32_t*charset_decode(const unsigned char*data,size_t len,const char*cs,size_t*outlen){
    uint32_t*cp=malloc((len+1)*sizeof(uint32_t));size_t n=0;
    if(ci_cmp(cs,"utf-8")==0){
        size_t i=0;
        while(i<len){
            uint32_t c;
            if(data[i]<0x80){c=data[i];i+=1;}
            else if((data[i]&0xE0)==0xC0){c=(data[i]&0x1F)<<6|(data[i+1]&0x3F);i+=2;}
            else if((data[i]&0xF0)==0xE0){c=(data[i]&0x0F)<<12|(data[i+1]&0x3F)<<6|(data[i+2]&0x3F);i+=3;}
            else{c=(data[i]&0x07)<<18|(data[i+1]&0x3F)<<12|(data[i+2]&0x3F)<<6|(data[i+3]&0x3F);i+=4;}
            cp[n++]=c;
        }
    }else if(ci_cmp(cs,"iso-8859-1")==0){
        for(size_t i=0;i<len;i++)cp[n++]=data[i];
    }else if(ci_cmp(cs,"windows-1252")==0){
        for(size_t i=0;i<len;i++){
            if(data[i]>=0x80&&data[i]<=0x9F)cp[n++]=cp1252[data[i]-0x80];
            else cp[n++]=data[i];
        }
    }else{
        for(size_t i=0;i<len;i++)cp[n++]=data[i];
    }
    *outlen=n;return cp;
}

/* ===== UTF-8 encode ===== */
static void utf8_enc(uint32_t cp,Buf*out){
    if(cp<0x80)buf_addc(out,(char)cp);
    else if(cp<0x800){buf_addc(out,(char)(0xC0|(cp>>6)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
    else if(cp<0x10000){buf_addc(out,(char)(0xE0|(cp>>12)));buf_addc(out,(char)(0x80|((cp>>6)&0x3F)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
    else{buf_addc(out,(char)(0xF0|(cp>>18)));buf_addc(out,(char)(0x80|((cp>>12)&0x3F)));buf_addc(out,(char)(0x80|((cp>>6)&0x3F)));buf_addc(out,(char)(0x80|(cp&0x3F)));}
}

/* ===== RFC 2047 encoded-words ===== */
typedef struct{int start,end;char charset[512];unsigned char*bytes;size_t nbytes;}EW;
static int try_match_ew(const char*t,int len,int pos,int*endp,char*charset,int*encp,const char**etp,size_t*etlenp){
    if(pos+1>=len||t[pos]!='='||t[pos+1]!='?')return 0;
    int p=pos+2;
    int cs_s=p;
    while(p<len&&t[p]!='?'&&t[p]!=' '&&t[p]!='\t')p++;
    if(p==cs_s)return 0;
    if(p>=len||t[p]!='?')return 0;
    int cs_len=p-cs_s;
    p++;
    if(p>=len)return 0;
    int enc=t[p];
    if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q')return 0;
    p++;
    if(p>=len||t[p]!='?')return 0;
    p++;
    int et_s=p;
    while(p<len&&t[p]!='?'&&t[p]!=' '&&t[p]!='\t')p++;
    if(p+1>=len||t[p]!='?'||t[p+1]!='=')return 0;
    memcpy(charset,t+cs_s,cs_len);charset[cs_len]=0;
    *encp=enc;*etp=t+et_s;*etlenp=(size_t)(p-et_s);*endp=p+2;
    return 1;
}
static void strip_lang(char*cs){char*star=strchr(cs,'*');if(star)*star=0;}
static unsigned char*ew_decode_bytes(const char*et,size_t etlen,int enc,size_t*outlen){
    if(enc=='B'||enc=='b')return b64_decode((const unsigned char*)et,etlen,outlen);
    unsigned char*r=malloc(etlen+1);size_t n=0;
    for(size_t i=0;i<etlen;){
        if(et[i]=='='&&i+2<etlen&&is_hex(et[i+1])&&is_hex(et[i+2])){r[n++]=(unsigned char)(hex_val(et[i+1])*16+hex_val(et[i+2]));i+=3;}
        else if(et[i]=='_'){r[n++]=0x20;i++;}
        else{r[n++]=(unsigned char)et[i];i++;}
    }
    *outlen=n;return r;
}
static char*decode_rfc2047(const char*text){
    int len=(int)strlen(text);
    EW words[256];int nw=0;
    int pos=0;
    while(pos<len){
        int found=-1;
        for(int i=pos;i<len-1;i++){
            int end;char cs[512];int enc;const char*et;size_t etl;
            if(try_match_ew(text,len,i,&end,cs,&enc,&et,&etl)){found=i;break;}
        }
        if(found<0)break;
        int end;char cs[512];int enc;const char*et;size_t etl;
        try_match_ew(text,len,found,&end,cs,&enc,&et,&etl);
        size_t nbytes;unsigned char*bytes=ew_decode_bytes(et,etl,enc,&nbytes);
        if(nw<256){words[nw].start=found;words[nw].end=end;strcpy(words[nw].charset,cs);words[nw].bytes=bytes;words[nw].nbytes=nbytes;nw++;}
        pos=end;
    }
    Buf out;buf_init(&out);
    int prev_end=0,i=0;
    while(i<nw){
        int gap_start=prev_end,gap_end=words[i].start;
        if(i>0){
            int adj=1;for(int k=gap_start;k<gap_end;k++){if(text[k]!=' '&&text[k]!='\t'){adj=0;break;}}
            if(!adj)buf_add(&out,text+gap_start,gap_end-gap_start);
        }else{
            buf_add(&out,text+gap_start,gap_end-gap_start);
        }
        char gcs[512];strcpy(gcs,words[i].charset);strip_lang(gcs);
        Buf gbuf;buf_init(&gbuf);
        buf_add(&gbuf,words[i].bytes,words[i].nbytes);
        int j=i+1;
        while(j<nw){
            int g2s=words[j-1].end,g2e=words[j].start;
            int adj2=1;for(int k=g2s;k<g2e;k++){if(text[k]!=' '&&text[k]!='\t'){adj2=0;break;}}
            if(!adj2)break;
            char cs2[512];strcpy(cs2,words[j].charset);strip_lang(cs2);
            if(ci_cmp(gcs,cs2)!=0)break;
            buf_add(&gbuf,words[j].bytes,words[j].nbytes);
            j++;
        }
        size_t cplen;uint32_t*cps=charset_decode((unsigned char*)gbuf.d,gbuf.len,gcs,&cplen);
        for(size_t k=0;k<cplen;k++)utf8_enc(cps[k],&out);
        free(cps);free(gbuf.d);
        prev_end=words[j-1].end;
        i=j;
    }
    if(prev_end<len)buf_add(&out,text+prev_end,len-prev_end);
    for(int k=0;k<nw;k++)free(words[k].bytes);
    return buf_str(&out);
}

/* ===== Headers ===== */
typedef struct{char*name;char*value;}Header;
static const char*find_header(Header*h,int n,const char*name){
    for(int i=0;i<n;i++)if(ci_cmp(h[i].name,name)==0)return h[i].value;
    return NULL;
}

/* ===== Parameters ===== */
typedef struct{char name[512];char*value;}Param;
static void parse_params(const char*s,Param*params,int*nparams){
    *nparams=0;
    while(*s){
        while(*s==' '||*s=='\t')s++;
        if(!*s)break;
        if(*s==';'){s++;continue;}
        char nm[512];int ni=0;
        while(*s&&*s!='='&&*s!=' '&&*s!='\t'&&*s!=';'){if(ni<511)nm[ni++]=*s;s++;}
        nm[ni]=0;
        while(*s==' '||*s=='\t')s++;
        if(*s!='='){continue;}
        s++;
        while(*s==' '||*s=='\t')s++;
        char*val;
        if(*s=='"'){
            s++;Buf vb;buf_init(&vb);
            while(*s&&*s!='"'){if(*s=='\\'&&s[1]){s++;buf_addc(&vb,*s);s++;}else{buf_addc(&vb,*s);s++;}}
            if(*s=='"')s++;
            buf_addc(&vb,0);val=vb.d;
        }else{
            Buf vb;buf_init(&vb);
            while(*s&&*s!=';'&&*s!=' '&&*s!='\t'){buf_addc(&vb,*s);s++;}
            buf_addc(&vb,0);val=vb.d;
        }
        if(*nparams<64){
            for(int k=0;k<ni;k++)params[*nparams].name[k]=tolower((unsigned char)nm[k]);
            params[*nparams].name[ni]=0;
            params[*nparams].value=val;
            (*nparams)++;
        }
    }
}

/* ===== RFC 2231 ===== */
static void percent_dec(const char*s,Buf*out){
    while(*s){
        if(*s=='%'&&s[1]&&s[2]&&is_hex(s[1])&&is_hex(s[2])){buf_addc(out,(char)(hex_val(s[1])*16+hex_val(s[2])));s+=3;}
        else{buf_addc(out,*s);s++;}
    }
}
static char*decode_rfc2231(Param*params,int np,const char*attr){
    size_t alen=strlen(attr);
    int has_2231=0;
    for(int i=0;i<np;i++){
        if(strlen(params[i].name)>alen&&params[i].name[alen]=='*'){
            has_2231=1;break;
        }
    }
    if(!has_2231)return NULL;
    struct{int idx;int pct;char*val;}segs[64];int ns=0;
    char charset[512]="us-ascii";
    for(int i=0;i<np;i++){
        if(strlen(params[i].name)<=alen)continue;
        if(params[i].name[alen]!='*')continue;
        const char*rest=params[i].name+alen+1;
        if(*rest==0){
            /* Single form: attr*=charset'lang'value (percent-encoded) */
            const char*v=params[i].value;
            const char*q1=strchr(v,'\'');
            if(q1){
                size_t cl=(size_t)(q1-v);if(cl>511)cl=511;
                memcpy(charset,v,cl);charset[cl]=0;
                const char*q2=strchr(q1+1,'\'');
                if(q2)v=q2+1;else v=q1+1;
            }
            Buf pb;buf_init(&pb);percent_dec(v,&pb);
            if(ns<64){segs[ns].idx=0;segs[ns].pct=1;segs[ns].val=pb.d;ns++;}
        }else{
            /* Continuation: attr*N or attr*N* */
            int idx=0;const char*p=rest;
            while(*p>='0'&&*p<='9'){idx=idx*10+(*p-'0');p++;}
            int pct=(*p=='*')?1:0;
            if(pct){
                const char*v=params[i].value;
                if(idx==0){
                    const char*q1=strchr(v,'\'');
                    if(q1){
                        size_t cl=(size_t)(q1-v);if(cl>511)cl=511;
                        memcpy(charset,v,cl);charset[cl]=0;
                        const char*q2=strchr(q1+1,'\'');
                        if(q2)v=q2+1;else v=q1+1;
                    }
                }
                Buf pb;buf_init(&pb);percent_dec(v,&pb);
                if(ns<64){segs[ns].idx=idx;segs[ns].pct=1;segs[ns].val=pb.d;ns++;}
            }else{
                if(ns<64){segs[ns].idx=idx;segs[ns].pct=0;segs[ns].val=xstrdup(params[i].value);ns++;}
            }
        }
    }
    if(ns==0)return NULL;
    /* Sort by idx (insertion sort) */
    for(int i=1;i<ns;i++){
        struct{int idx;int pct;char*val;}tmp=segs[i];
        int j=i-1;
        while(j>=0&&segs[j].idx>tmp.idx){segs[j+1]=segs[j];j--;}
        segs[j+1]=tmp;
    }
    Buf all;buf_init(&all);
    for(int i=0;i<ns;i++)buf_add(&all,segs[i].val,strlen(segs[i].val));
    size_t cplen;uint32_t*cps=charset_decode((unsigned char*)all.d,all.len,charset,&cplen);
    Buf out;buf_init(&out);
    for(size_t k=0;k<cplen;k++)utf8_enc(cps[k],&out);
    free(cps);free(all.d);
    for(int i=0;i<ns;i++)free(segs[i].val);
    return buf_str(&out);
}

/* ===== Entity ===== */
typedef struct Entity{
    Header*headers;int nheaders;
    unsigned char*body;size_t body_len;
    struct Entity**children;int nchildren;
    int is_multipart;
    int crlf;
}Entity;

static Entity*parse_entity(const unsigned char*data,size_t len,int crlf);

static int find_sep(const unsigned char*data,size_t len,int crlf,size_t*hdr_end,size_t*body_start){
    size_t pos=0,lb=crlf?2:1;
    while(pos<=len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        if(le==pos){
            *hdr_end=pos;
            *body_start=(le<len)?le+lb:len;
            return 1;
        }
        if(le>=len)break;
        pos=le+lb;
    }
    *hdr_end=len;*body_start=len;return 0;
}

static void parse_hdrs(const unsigned char*data,size_t len,int crlf,Header**hp,int*nhp){
    Header*hs=NULL;int nh=0,cap=0;
    size_t pos=0,lb=crlf?2:1;
    while(pos<len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        size_t next=pos+((le<len)?lb:0);
        Buf line;buf_init(&line);
        buf_add(&line,data+pos,le-pos);
        while(next<len){
            if(data[next]==' '||data[next]=='\t'){
                buf_addc(&line,data[next]);
                size_t le2=next+1;
                while(le2<len){if(crlf){if(data[le2]=='\r'&&le2+1<len&&data[le2+1]=='\n')break;}else{if(data[le2]=='\n')break;}le2++;}
                buf_add(&line,data+next+1,le2-next-1);
                next=le2+((le2<len)?lb:0);
            }else break;
        }
        buf_addc(&line,0);
        char*ln=line.d;
        char*colon=strchr(ln,':');
        if(colon){
            size_t nlen=(size_t)(colon-ln);
            char*name=xstrndup(ln,nlen);
            while(nlen>0&&(name[nlen-1]==' '||name[nlen-1]=='\t')){name[--nlen]=0;}
            const char*val=colon+1;
            while(*val==' '||*val=='\t')val++;
            size_t vlen=strlen(val);
            while(vlen>0&&(val[vlen-1]==' '||val[vlen-1]=='\t'))vlen--;
            char*v=xstrndup(val,vlen);
            if(nh>=cap){cap=cap?cap*2:8;hs=realloc(hs,cap*sizeof(Header));}
            hs[nh].name=name;hs[nh].value=v;nh++;
        }
        free(line.d);
        if(le>=len)break;
        pos=le+lb;
    }
    *hp=hs;*nhp=nh;
}

typedef struct{char type[256],subtype[256];Param params[64];int nparams;}CT;
static void parse_ct(const char*v,CT*ct){
    memset(ct,0,sizeof(*ct));
    const char*slash=strchr(v,'/');
    if(!slash){strcpy(ct->type,"text");strcpy(ct->subtype,"plain");return;}
    size_t tl=(size_t)(slash-v);while(tl>0&&(v[tl-1]==' '||v[tl-1]=='\t'))tl--;
    for(size_t i=0;i<tl&&i<255;i++)ct->type[i]=tolower((unsigned char)v[i]);ct->type[tl]=0;
    const char*sp=slash+1;while(*sp==' '||*sp=='\t')sp++;
    const char*semi=strchr(sp,';');
    size_t sl=semi?(size_t)(semi-sp):strlen(sp);
    while(sl>0&&(sp[sl-1]==' '||sp[sl-1]=='\t'))sl--;
    for(size_t i=0;i<sl&&i<255;i++)ct->subtype[i]=tolower((unsigned char)sp[i]);ct->subtype[sl]=0;
    if(semi)parse_params(semi+1,ct->params,&ct->nparams);
}
typedef struct{char disp[256];Param params[64];int nparams;}CD;
static void parse_cd(const char*v,CD*cd){
    memset(cd,0,sizeof(*cd));
    const char*semi=strchr(v,';');
    size_t dl=semi?(size_t)(semi-v):strlen(v);
    while(dl>0&&(v[dl-1]==' '||v[dl-1]=='\t'))dl--;
    while(dl>0&&(v[0]==' '||v[0]=='\t')){v++;dl--;}
    for(size_t i=0;i<dl&&i<255;i++)cd->disp[i]=tolower((unsigned char)v[i]);cd->disp[dl]=0;
    if(semi)parse_params(semi+1,cd->params,&cd->nparams);
}
static const char*param_get(Param*p,int n,const char*name){
    for(int i=0;i<n;i++)if(ci_cmp(p[i].name,name)==0)return p[i].value;
    return NULL;
}

/* ===== Delimiter finding ===== */
typedef struct{size_t ls,le,fe;int close;}Delim;
static int find_delims(const unsigned char*data,size_t len,const char*bnd,int crlf,Delim**outp,int*noutp){
    size_t lb=crlf?2:1,bl=strlen(bnd);
    int cap=16,n=0;Delim*arr=malloc(cap*sizeof(Delim));
    size_t pos=0;
    while(pos<=len){
        size_t le=pos;
        while(le<len){if(crlf){if(data[le]=='\r'&&le+1<len&&data[le+1]=='\n')break;}else{if(data[le]=='\n')break;}le++;}
        int isd=0,isc=0;
        if(le-pos>=2+bl&&data[pos]=='-'&&data[pos+1]=='-'&&memcmp(data+pos+2,bnd,bl)==0){
            size_t ab=pos+2+bl;
            if(ab+2<=le&&data[ab]=='-'&&data[ab+1]=='-'){
                int ok=1;for(size_t k=ab+2;k<le;k++)if(data[k]!=' '&&data[k]!='\t'){ok=0;break;}
                if(ok){isd=1;isc=1;}
            }
            if(!isd){
                int ok=1;for(size_t k=ab;k<le;k++)if(data[k]!=' '&&data[k]!='\t'){ok=0;break;}
                if(ok){isd=1;isc=0;}
            }
        }
        if(isd){
            if(n>=cap){cap*=2;arr=realloc(arr,cap*sizeof(Delim));}
            arr[n].ls=pos;arr[n].le=le;arr[n].fe=(le<len)?le+lb:len;arr[n].close=isc;n++;
        }
        if(le>=len)break;
        pos=le+lb;
    }
    *outp=arr;*noutp=n;return n;
}

static Entity*parse_entity(const unsigned char*data,size_t len,int crlf){
    Entity*e=calloc(1,sizeof(Entity));
    e->crlf=crlf;
    size_t hdr_end,body_start;
    find_sep(data,len,crlf,&hdr_end,&body_start);
    parse_hdrs(data,hdr_end,crlf,&e->headers,&e->nheaders);
    const char*ctv=find_header(e->headers,e->nheaders,"content-type");
    CT ct;
    if(ctv)parse_ct(ctv,&ct);
    else{strcpy(ct.type,"text");strcpy(ct.subtype,"plain");ct.nparams=0;}
    if(strcmp(ct.type,"multipart")==0){
        e->is_multipart=1;
        const char*bnd=param_get(ct.params,ct.nparams,"boundary");
        if(!bnd)bnd="";
        const unsigned char*body=data+body_start;
        size_t blen=len-body_start;
        Delim*dels=NULL;int nd=0;
        if(strlen(bnd)>0)find_delims(body,blen,bnd,crlf,&dels,&nd);
        int fr=-1,cl=-1;
        for(int i=0;i<nd;i++){if(!dels[i].close&&fr<0)fr=i;if(dels[i].close&&fr>=0&&cl<0)cl=i;}
        if(fr>=0){
            int end_idx=(cl>=0)?cl:nd;
            int np=end_idx-fr;
            if(np<0)np=0;
            e->children=calloc(np,sizeof(Entity*));
            e->nchildren=np;
            for(int i=0;i<np;i++){
                size_t cs=dels[fr+i].fe;
                size_t ce;
                if(fr+i+1<nd)ce=dels[fr+i+1].ls;
                else ce=blen;
                if(ce>cs){
                    if(crlf&&ce>=cs+2&&body[ce-2]=='\r'&&body[ce-1]=='\n')ce-=2;
                    else if(!crlf&&body[ce-1]=='\n')ce-=1;
                }
                e->children[i]=parse_entity(body+cs,ce-cs,crlf);
            }
        }
        free(dels);
    }else{
        e->body=(unsigned char*)data+body_start;
        e->body_len=len-body_start;
    }
    return e;
}

/* ===== Output ===== */
static void print_quoted(Buf*out,const uint32_t*cps,size_t n){
    buf_addc(out,'"');
    for(size_t i=0;i<n;i++){
        uint32_t c=cps[i];
        if(c=='\\'){buf_addstr(out,"\\\\");}
        else if(c=='"'){buf_addstr(out,"\\\"");}
        else if(c=='\n'){buf_addstr(out,"\\n");}
        else if(c=='\t'){buf_addstr(out,"\\t");}
        else if(c<0x20||(c>=0x7F&&c<=0x9F)){
            char tmp[8];sprintf(tmp,"\\u%04x",c);buf_addstr(out,tmp);
        }else{
            utf8_enc(c,out);
        }
    }
    buf_addc(out,'"');
}

static void print_entity(Entity*e,int depth){
    const char*ctv=find_header(e->headers,e->nheaders,"content-type");
    CT ct;
    if(ctv)parse_ct(ctv,&ct);
    else{strcpy(ct.type,"text");strcpy(ct.subtype,"plain");ct.nparams=0;}
    const char*cdv=find_header(e->headers,e->nheaders,"content-disposition");
    CD cd;
    if(cdv)parse_cd(cdv,&cd);
    else{cd.disp[0]=0;cd.nparams=0;}
    const char*ctev=find_header(e->headers,e->nheaders,"content-transfer-encoding");
    char cte[64]="7bit";
    if(ctev){size_t l=strlen(ctev);for(size_t i=0;i<l&&i<63;i++)cte[i]=tolower((unsigned char)ctev[i]);cte[l<64?l:63]=0;}

    for(int i=0;i<depth*2;i++)putchar(' ');

    if(e->is_multipart){
        printf("multipart/%s parts=%d\n",ct.subtype,e->nchildren);
        for(int i=0;i<e->nchildren;i++)print_entity(e->children[i],depth+1);
    }else{
        int is_text=(strcmp(ct.type,"text")==0&&strcmp(cd.disp,"attachment")!=0);
        if(is_text){
            const char*cs=param_get(ct.params,ct.nparams,"charset");
            char charset[256]="us-ascii";
            if(cs){size_t l=strlen(cs);for(size_t i=0;i<l&&i<255;i++)charset[i]=tolower((unsigned char)cs[i]);charset[l<256?l:255]=0;}
            unsigned char*dec=NULL;size_t dlen=0;
            if(strcmp(cte,"base64")==0)dec=b64_decode(e->body,e->body_len,&dlen);
            else if(strcmp(cte,"quoted-printable")==0)dec=qp_decode(e->body,e->body_len,e->crlf,&dlen);
            else{dec=malloc(e->body_len?e->body_len:1);memcpy(dec,e->body,e->body_len);dlen=e->body_len;}
            size_t cplen;uint32_t*cps=charset_decode(dec,dlen,charset,&cplen);
            size_t n2=0;
            for(size_t i=0;i<cplen;i++){
                if(cps[i]==0x0D){
                    if(i+1<cplen&&cps[i+1]==0x0A){cps[n2++]=0x0A;i++;}
                    else cps[n2++]=0x0A;
                }else cps[n2++]=cps[i];
            }
            printf("text/%s charset=%s cte=%s chars=%zu\n",ct.subtype,charset,cte,n2);
            for(int i=0;i<(depth+1)*2;i++)putchar(' ');
            Buf qb;buf_init(&qb);
            print_quoted(&qb,cps,n2);
            printf("%s\n",qb.d);
            free(qb.d);free(cps);free(dec);
        }else{
            unsigned char*dec=NULL;size_t dlen=0;
            if(strcmp(cte,"base64")==0)dec=b64_decode(e->body,e->body_len,&dlen);
            else if(strcmp(cte,"quoted-printable")==0)dec=qp_decode(e->body,e->body_len,e->crlf,&dlen);
            else{dec=malloc(e->body_len?e->body_len:1);memcpy(dec,e->body,e->body_len);dlen=e->body_len;}
            uint32_t c=crc32(dec,dlen);
            char*name=NULL;
            name=decode_rfc2231(cd.params,cd.nparams,"filename");
            if(!name){const char*f=param_get(cd.params,cd.nparams,"filename");if(f)name=decode_rfc2047(f);}
            if(!name)name=decode_rfc2231(ct.params,ct.nparams,"name");
            if(!name){const char*nm=param_get(ct.params,ct.nparams,"name");if(nm)name=decode_rfc2047(nm);}
            printf("%s/%s cte=%s disposition=%s name=",ct.type,ct.subtype,cte,cd.disp[0]?cd.disp:"-");
            if(name){
                size_t cplen;uint32_t*cps=charset_decode((unsigned char*)name,strlen(name),"utf-8",&cplen);
                Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
                printf("%s",qb.d);free(qb.d);free(cps);
                free(name);
            }else printf("-");
            printf(" size=%zu crc32=%08x\n",dlen,c);
            free(dec);
        }
    }
}

/* ===== Main ===== */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char*argv[]){
    crc32_init();
    if(argc<2)return 1;
    DIR*dir=opendir(argv[1]);
    if(!dir)return 1;
    char*files[4096];int nf=0;
    struct dirent*ent;
    while((ent=readdir(dir))){
        size_t l=strlen(ent->d_name);
        if(l>4&&strcmp(ent->d_name+l-4,".eml")==0)files[nf++]=xstrdup(ent->d_name);
    }
    closedir(dir);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)printf("\n");
        printf("== %s\n",files[fi]);
        char path[4096];snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
        unsigned char*data=malloc(sz+1);
        if(sz>0)fread(data,1,sz,f);
        fclose(f);
        int crlf=0;
        for(long i=0;i<sz-1;i++){if(data[i]=='\r'&&data[i+1]=='\n'){crlf=1;break;}if(data[i]=='\n')break;}
        Entity*msg=parse_entity(data,sz,crlf);
        const char*fromv=find_header(msg->headers,msg->nheaders,"from");
        const char*subjv=find_header(msg->headers,msg->nheaders,"subject");
        printf("From: ");
        if(fromv){
            char*dec=decode_rfc2047(fromv);
            size_t cplen;uint32_t*cps=charset_decode((unsigned char*)dec,strlen(dec),"utf-8",&cplen);
            Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
            printf("%s\n",qb.d);free(qb.d);free(cps);free(dec);
        }else printf("-\n");
        printf("Subject: ");
        if(subjv){
            char*dec=decode_rfc2047(subjv);
            size_t cplen;uint32_t*cps=charset_decode((unsigned char*)dec,strlen(dec),"utf-8",&cplen);
            Buf qb;buf_init(&qb);print_quoted(&qb,cps,cplen);
            printf("%s\n",qb.d);free(qb.d);free(cps);free(dec);
        }else printf("-\n");
        print_entity(msg,0);
        free(data);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) {
        crc = (crc >>> 1) ^ 0xEDB88320;
      } else {
        crc = crc >>> 1;
      }
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function splitLines(content: string): string[] {
  if (content === '') return [];
  const parts = content.split('\n');
  const lines: string[] = [];
  for (let i = 0; i < parts.length - 1; i++) {
    lines.push(parts[i] + '\n');
  }
  if (parts[parts.length - 1] !== '') {
    lines.push(parts[parts.length - 1]);
  }
  return lines;
}

interface Hunk {
  a: number;
  b: number;
  c: number;
  d: number;
  oldLines: string[];
  newLines: string[];
  malformed: boolean;
}

interface Section {
  filePath: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
}

function parseDiff(diffContent: string): Section[] {
  const lines = diffContent.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const sections: Section[] = [];
  let i = 0;

  while (i < lines.length) {
    if (!lines[i].startsWith('diff --git ')) {
      i++;
      continue;
    }

    const match = lines[i].match(/^diff --git a\/(.+) b\/(.+)$/);
    if (!match) {
      i++;
      continue;
    }
    const filePath = match[1];
    i++;

    let kind: 'create' | 'delete' | 'modify' = 'modify';

    while (i < lines.length) {
      const hline = lines[i];
      if (hline.startsWith('diff --git ') || hline.startsWith('@@ ')) break;
      if (hline.startsWith('new file mode ')) {
        kind = 'create';
        i++;
      } else if (hline.startsWith('deleted file mode ')) {
        kind = 'delete';
        i++;
      } else if (
        hline.startsWith('index ') ||
        hline.startsWith('--- ') ||
        hline.startsWith('+++ ')
      ) {
        i++;
      } else {
        break;
      }
    }

    const hunks: Hunk[] = [];
    while (i < lines.length) {
      if (!lines[i].startsWith('@@ ')) break;

      const hunkMatch = lines[i].match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
      if (!hunkMatch) {
        i++;
        continue;
      }

      const a = parseInt(hunkMatch[1]);
      const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2]) : 1;
      const c = parseInt(hunkMatch[3]);
      const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4]) : 1;
      i++;

      const oldLines: string[] = [];
      const newLines: string[] = [];
      let lastMarker = '';

      while (i < lines.length) {
        const bline = lines[i];
        if (bline.startsWith('@@ ') || bline.startsWith('diff --git ')) break;

        if (bline.startsWith('\\')) {
          if (lastMarker === ' ') {
            if (oldLines.length > 0)
              oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
            if (newLines.length > 0)
              newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
          } else if (lastMarker === '-') {
            if (oldLines.length > 0)
              oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
          } else if (lastMarker === '+') {
            if (newLines.length > 0)
              newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
          }
          i++;
          continue;
        }

        const marker = bline[0];
        const content = bline.substring(1);

        if (marker === ' ') {
          oldLines.push(content + '\n');
          newLines.push(content + '\n');
        } else if (marker === '-') {
          oldLines.push(content + '\n');
        } else if (marker === '+') {
          newLines.push(content + '\n');
        }

        lastMarker = marker;
        i++;
      }

      const malformed = oldLines.length !== b || newLines.length !== d;
      hunks.push({ a, b, c, d, oldLines, newLines, malformed });
    }

    sections.push({ filePath, kind, hunks });
  }

  return sections;
}

function main() {
  const dir = process.argv[2];
  const diffPath = path.join(dir, 'changes.diff');
  const treeDir = path.join(dir, 'tree');

  const diffContent = fs.readFileSync(diffPath, 'latin1');
  const sections = parseDiff(diffContent);

  sections.sort((a, b) => {
    if (a.filePath < b.filePath) return -1;
    if (a.filePath > b.filePath) return 1;
    return 0;
  });

  const output: string[] = [];

  for (const section of sections) {
    const { filePath, kind, hunks } = section;

    output.push(`${filePath}: ${kind}`);

    const fullPath = path.join(treeDir, filePath);
    let fileExists = false;
    let content: string = '';

    try {
      content = fs.readFileSync(fullPath, 'latin1');
      fileExists = true;
    } catch {
      fileExists = false;
    }

    if (kind === 'create') {
      if (fileExists) {
        output.push('  error: already exists');
        continue;
      }
      content = '';
    } else {
      if (!fileExists) {
        output.push('  error: not found');
        continue;
      }
    }

    let lines = splitLines(content);
    let delta = 0;
    let allApplied = true;

    for (let hi = 0; hi < hunks.length; hi++) {
      const hunk = hunks[hi];
      const hunkNum = hi + 1;

      if (hunk.malformed) {
        output.push(`  hunk ${hunkNum}: malformed`);
        allApplied = false;
        continue;
      }

      const P = hunk.a + delta;

      if (hunk.b === 0) {
        if (P >= 0 && P <= lines.length) {
          lines = [...lines.slice(0, P), ...hunk.newLines, ...lines.slice(P)];
          output.push(`  hunk ${hunkNum}: applied at ${P} (offset 0)`);
          delta += hunk.d;
        } else {
          output.push(`  hunk ${hunkNum}: rejected`);
          allApplied = false;
        }
      } else {
        const b = hunk.b;
        const maxP = lines.length - b + 1;

        let found = false;
        let foundP = -1;

        if (maxP >= 1) {
          for (let k = 0; ; k++) {
            const candidates: number[] = [];
            if (k === 0) {
              candidates.push(P);
            } else {
              candidates.push(P - k);
              candidates.push(P + k);
            }

            for (const p of candidates) {
              if (p >= 1 && p <= maxP) {
                let matches = true;
                for (let j = 0; j < b; j++) {
                  if (lines[p - 1 + j] !== hunk.oldLines[j]) {
                    matches = false;
                    break;
                  }
                }
                if (matches) {
                  found = true;
                  foundP = p;
                  break;
                }
              }
            }

            if (found) break;
            if (P - k < 1 && P + k > maxP) break;
          }
        }

        if (found) {
          const offset = foundP - P;
          lines = [
            ...lines.slice(0, foundP - 1),
            ...hunk.newLines,
            ...lines.slice(foundP - 1 + b),
          ];
          const offsetStr = offset > 0 ? `+${offset}` : `${offset}`;
          output.push(`  hunk ${hunkNum}: applied at ${foundP} (offset ${offsetStr})`);
          delta += hunk.d - hunk.b;
        } else {
          output.push(`  hunk ${hunkNum}: rejected`);
          allApplied = false;
        }
      }
    }

    if (kind === 'delete' && allApplied && lines.length === 0) {
      output.push('  result: deleted');
    } else {
      const finalContent = lines.join('');
      const buf = Buffer.from(finalContent, 'latin1');
      const crc = crc32(buf);
      output.push(
        `  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`
      );
    }
  }

  if (output.length > 0) {
    console.log(output.join('\n'));
  }
}

