            try execBlock(fn.body, callScope)
        } catch ControlFlow.returnVal(let v) {
            return v
        }
        return .nilVal
    }

    func callBuiltin(_ name: String, _ args: [TernValue], _ callLine: Int) throws -> TernValue {
