    case kw_true, kw_false, kw_nil
    case op_eq, op_ne, op_le, op_ge, op_lt, op_gt, op_assign
    case op_add, op_sub, op_mul, op_div, op_mod
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon
    case eof
}

struct Token {
    let type: TokType
    let text: String
    let line: Int
    let intVal: Int
}

// MARK: - Lexer

class Lexer {
    let chars: [UInt8]
    var pos = 0
    var line = 1

    init(_ source: String) {
        self.chars = Array(source.utf8)
    }

    func tokenize() -> [Token] {
        var tokens: [Token] = []
        while pos < chars.count {
            let c = chars[pos]
            if c == 32 || c == 9 || c == 13 {
                pos += 1
            } else if c == 10 {
                line += 1
                pos += 1
            } else if c == 35 {
                while pos < chars.count && chars[pos] != 10 { pos += 1 }
            } else if c >= 48 && c <= 57 {
                tokens.append(readInt())
            } else if c == 34 {
                tokens.append(readString())
            } else if (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 {
                tokens.append(readIdent())
            } else {
                tokens.append(readOp())
            }
        }
        tokens.append(Token(type: .eof, text: "", line: line, intVal: 0))
        return tokens
    }

    func readInt() -> Token {
        let start = pos
        var val = 0
        while pos < chars.count && chars[pos] >= 48 && chars[pos] <= 57 {
            val = val &* 10 &+ Int(chars[pos] - 48)
            pos += 1
        }
        let text = String(bytes: chars[start..<pos], encoding: .ascii)!
        return Token(type: .int, text: text, line: line, intVal: val)
