        let t = peek()
        switch t.type {
        case .kw_let:
            advance()
            let name = advance().text
            expect(.op_assign)
            let val = parseExpr()
            expect(.semicolon)
            return .letStmt(name, val, t.line)
        case .kw_fn:
            advance()
            let name = advance().text
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            expect(.lbrace)
            let body = parseBlock()
            expect(.rbrace)
            return .fnDecl(name, params, body, t.line)
        case .kw_if:
            return parseIfStmt()
        case .kw_while:
            advance()
            let cond = parseExpr()
            expect(.lbrace)
            let body = parseBlock()
            expect(.rbrace)
            return .whileStmt(cond, body, t.line)
        case .kw_for:
            advance()
            let varName = advance().text
            expect(.kw_in)
            let iterable = parseExpr()
            expect(.lbrace)
            let body = parseBlock()
            expect(.rbrace)
            return .forStmt(varName, iterable, body, t.line)
        case .kw_return:
            advance()
            if peek().type == .semicolon {
                advance()
                return .returnStmt(nil, t.line)
            } else {
                let val = parseExpr()
                expect(.semicolon)
                return .returnStmt(val, t.line)
            }
        case .kw_break:
            advance()
            expect(.semicolon)
            return .breakStmt(t.line)
        case .kw_continue:
            advance()
            expect(.semicolon)
            return .continueStmt(t.line)
        case .ident where tokens[pos + 1].type == .op_assign:
            advance()
            advance()
            let val = parseExpr()
            expect(.semicolon)
            return .assignStmt(t.text, val, t.line)
        default:
            let expr = parseExpr()
            if peek().type == .op_assign {
                advance()
                let val = parseExpr()
                expect(.semicolon)
                if case .index(let obj, let idx, let bline) = expr {
                    return .indexAssign(obj, idx, val, bline)
                }
                return .exprStmt(expr, t.line)
            }
            expect(.semicolon)
            return .exprStmt(expr, t.line)
        }
    }

    func parseIfStmt() -> Stmt {
        let t = advance()
        let cond = parseExpr()
        expect(.lbrace)
        let body = parseBlock()
        expect(.rbrace)
        var elseClause: ElseClause? = nil
        if peek().type == .kw_else {
            advance()
            if peek().type == .kw_if {
                elseClause = .ifStmt(parseIfStmt())
            } else {
                expect(.lbrace)
                let elseBody = parseBlock()
                expect(.rbrace)
                elseClause = .block(elseBody)
            }
        }
        return .ifStmt(cond, body, elseClause, t.line)
    }

    func parseParams() -> [String] {
        var params: [String] = []
        if peek().type != .rparen {
            params.append(advance().text)
            while peek().type == .comma {
                advance()
                params.append(advance().text)
            }
        }
        return params
    }

    func parseBlock() -> [Stmt] {
        var stmts: [Stmt] = []
        while peek().type != .rbrace && peek().type != .eof {
            stmts.append(parseStmt())
        }
        return stmts
    }

    func parseExpr() -> Expr { return parseOr() }

    func parseOr() -> Expr {
        var left = parseAnd()
        while peek().type == .kw_or {
            let t = advance()
            let right = parseAnd()
            left = .binOp(.or, left, right, t.line)
        }
        return left
    }

    func parseAnd() -> Expr {
        var left = parseNot()
        while peek().type == .kw_and {
            let t = advance()
            let right = parseNot()
            left = .binOp(.and, left, right, t.line)
        }
        return left
    }

    func parseNot() -> Expr {
        if peek().type == .kw_not {
            let t = advance()
            let operand = parseNot()
            return .notOp(operand, t.line)
        }
        return parseComparison()
    }

    func parseComparison() -> Expr {
        var left = parseAdd()
        while true {
            let t = peek()
            let op: BinOpType
            switch t.type {
            case .op_eq: op = .eq
            case .op_ne: op = .ne
            case .op_lt: op = .lt
            case .op_le: op = .le
            case .op_gt: op = .gt
            case .op_ge: op = .ge
            default: return left
            }
            advance()
            let right = parseAdd()
            left = .binOp(op, left, right, t.line)
        }
    }

    func parseAdd() -> Expr {
        var left = parseMul()
        while true {
            let t = peek()
            let op: BinOpType
            switch t.type {
            case .op_add: op = .add
            case .op_sub: op = .sub
            default: return left
            }
            advance()
            let right = parseMul()
            left = .binOp(op, left, right, t.line)
        }
    }

    func parseMul() -> Expr {
        var left = parseUnary()
        while true {
            let t = peek()
            let op: BinOpType
            switch t.type {
            case .op_mul: op = .mul
            case .op_div: op = .div
            case .op_mod: op = .mod
            default: return left
            }
            advance()
            let right = parseUnary()
            left = .binOp(op, left, right, t.line)
        }
    }

    func parseUnary() -> Expr {
        if peek().type == .op_sub {
            let t = advance()
            let operand = parseUnary()
            return .neg(operand, t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var expr = parsePrimary()
        while true {
            if peek().type == .lparen {
                let t = advance()
                var args: [Expr] = []
                if peek().type != .rparen {
                    args.append(parseExpr())
                    while peek().type == .comma {
                        advance()
                        args.append(parseExpr())
                    }
                }
                expect(.rparen)
                expr = .call(expr, args, t.line)
            } else if peek().type == .lbracket {
                let t = advance()
                let idx = parseExpr()
                expect(.rbracket)
                expr = .index(expr, idx, t.line)
            } else {
                break
            }
        }
        return expr
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.type {
        case .int: advance(); return .intLit(t.intVal, t.line)
        case .str: advance(); return .strLit(t.text, t.line)
        case .kw_true: advance(); return .boolLit(true, t.line)
        case .kw_false: advance(); return .boolLit(false, t.line)
        case .kw_nil: advance(); return .nilLit(t.line)
        case .ident: advance(); return .ident(t.text, t.line)
        case .lparen:
            advance()
            let expr = parseExpr()
            expect(.rparen)
            return expr
        case .lbracket:
            advance()
            var elements: [Expr] = []
            if peek().type != .rbracket {
                elements.append(parseExpr())
                while peek().type == .comma {
                    advance()
                    elements.append(parseExpr())
                }
            }
            expect(.rbracket)
            return .listLit(elements, t.line)
        case .kw_fn:
            advance()
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            expect(.lbrace)
            let body = parseBlock()
            expect(.rbrace)
            return .fnExpr(params, body, t.line)
        default:
            advance()
            return .nilLit(t.line)
        }
    }
}

// MARK: - Values

class TernList {
    var elements: [TernValue]
    init(_ elements: [TernValue] = []) { self.elements = elements }
}

class TernFunction {
    let params: [String]
    let body: [Stmt]
    let capturedScope: Scope
    let builtinName: String?
    init(params: [String], body: [Stmt], capturedScope: Scope, builtinName: String? = nil) {
        self.params = params
        self.body = body
        self.capturedScope = capturedScope
        self.builtinName = builtinName
    }
}

enum TernValue {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(TernList)
    case function(TernFunction)
    case nilVal
}

class Scope {
    var vars: [String: TernValue] = [:]
    let parent: Scope?
    init(parent: Scope?) { self.parent = parent }

    func lookup(_ name: String) -> TernValue? {
        var s: Scope? = self
        while let sc = s {
            if let v = sc.vars[name] { return v }
            s = sc.parent
        }
        return nil
    }

    func assign(_ name: String, _ value: TernValue) -> Bool {
        var s: Scope? = self
        while let sc = s {
            if sc.vars[name] != nil {
                sc.vars[name] = value
                return true
            }
            s = sc.parent
        }
        return false
    }
}

// MARK: - Interpreter

enum ControlFlow: Error {
    case breakLoop
    case continueLoop
    case returnVal(TernValue)
}

struct TernError: Error {
    let message: String
    let line: Int
    init(_ message: String, line: Int) {
        self.message = message
        self.line = line
    }
}

class Interpreter {
    let globalScope: Scope

    init() {
        let builtinScope = Scope(parent: nil)
        let bnames = ["print","str","type","len","push","pop","range","slice"]
        for name in bnames {
            builtinScope.vars[name] = .function(TernFunction(params: [], body: [], capturedScope: builtinScope, builtinName: name))
        }
        globalScope = Scope(parent: builtinScope)
    }

    func typeName(_ v: TernValue) -> String {
        switch v {
        case .int: return "int"
        case .bool: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .function: return "function"
        case .nilVal: return "nil"
        }
    }

    func isTruthy(_ v: TernValue) -> Bool {
        switch v {
        case .int(let n): return n != 0
        case .bool(let b): return b
        case .string(let s): return !s.isEmpty
        case .list(let l): return !l.elements.isEmpty
        case .function: return true
        case .nilVal: return false
        }
    }

    func display(_ v: TernValue, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
        switch v {
        case .int(let n): return String(n)
        case .bool(let b): return b ? "true" : "false"
        case .string(let s):
            if inList {
                var r = "\""
                for c in s.unicodeScalars {
                    switch c {
                    case "\\": r += "\\\\"
                    case "\"": r += "\\\""
                    case "\n": r += "\\n"
                    case "\t": r += "\\t"
                    default: r.unicodeScalars.append(c)
                    }
                }
                r += "\""
                return r
            }
            return s
        case .list(let l):
            if seen.contains(ObjectIdentifier(l)) { return "[...]" }
            seen.insert(ObjectIdentifier(l))
            let parts = l.elements.map { display($0, inList: true, seen: &seen) }
            seen.remove(ObjectIdentifier(l))
            return "[" + parts.joined(separator: ", ") + "]"
        case .function: return "<fn>"
        case .nilVal: return "nil"
        }
    }

    func valueEquals(_ a: TernValue, _ b: TernValue) -> Bool {
        switch (a, b) {
        case (.int(let x), .int(let y)): return x == y
        case (.bool(let x), .bool(let y)): return x == y
        case (.string(let x), .string(let y)): return x == y
        case (.nilVal, .nilVal): return true
        case (.list(let x), .list(let y)):
            if x.elements.count != y.elements.count { return false }
            for i in 0..<x.elements.count {
                if !valueEquals(x.elements[i], y.elements[i]) { return false }
            }
            return true
        case (.function(let x), .function(let y)): return x === y
        default: return false
        }
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execBlock(stmts, globalScope)
        } catch let err as TernError {
            print("error at line \(err.line): \(err.message)")
        } catch {
            // shouldn't happen
        }
    }

    func execBlock(_ stmts: [Stmt], _ scope: Scope) throws {
        for stmt in stmts {
            try exec(stmt, scope)
        }
    }

    func exec(_ stmt: Stmt, _ scope: Scope) throws {
        switch stmt {
        case .letStmt(let name, let val, _):
            let v = try eval(val, scope)
            scope.vars[name] = v
        case .fnDecl(let name, let params, let body, _):
            let fn = TernFunction(params: params, body: body, capturedScope: scope)
            scope.vars[name] = .function(fn)
        case .ifStmt(let cond, let body, let elseClause, _):
            let cv = try eval(cond, scope)
            if isTruthy(cv) {
                let innerScope = Scope(parent: scope)
                try execBlock(body, innerScope)
            } else if let ec = elseClause {
                switch ec {
                case .block(let stmts):
                    let innerScope = Scope(parent: scope)
                    try execBlock(stmts, innerScope)
                case .ifStmt(let ifStmt):
                    try exec(ifStmt, scope)
                }
            }
        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try eval(cond, scope)
                if !isTruthy(cv) { break }
                let innerScope = Scope(parent: scope)
                do {
                    try execBlock(body, innerScope)
                } catch ControlFlow.breakLoop {
                    break
                } catch ControlFlow.continueLoop {
                    continue
                }
            }
        case .forStmt(let varName, let iterable, let body, let line):
            let listVal = try eval(iterable, scope)
            guard case .list(let list) = listVal else {
                throw TernError("cannot iterate \(typeName(listVal))", line: line)
            }
            var i = 0
            while i < list.elements.count {
                let innerScope = Scope(parent: scope)
                innerScope.vars[varName] = list.elements[i]
                do {
                    try execBlock(body, innerScope)
                } catch ControlFlow.breakLoop {
                    break
                } catch ControlFlow.continueLoop {
                    // fall through to i += 1
                }
                i += 1
            }
        case .returnStmt(let val, _):
            if let v = val {
                let result = try eval(v, scope)
                throw ControlFlow.returnVal(result)
            } else {
                throw ControlFlow.returnVal(.nilVal)
            }
        case .breakStmt:
            throw ControlFlow.breakLoop
        case .continueStmt:
            throw ControlFlow.continueLoop
        case .assignStmt(let name, let val, let line):
            let v = try eval(val, scope)
            if !scope.assign(name, v) {
                throw TernError("undefined variable \(name)", line: line)
            }
        case .indexAssign(let obj, let idx, let val, let bracketLine):
            let objVal = try eval(obj, scope)
            let idxVal = try eval(idx, scope)
            let v = try eval(val, scope)
            guard case .list(let list) = objVal else {
                throw TernError("cannot assign into \(typeName(objVal))", line: bracketLine)
            }
            guard case .int(let i) = idxVal else {
                throw TernError("cannot index list with \(typeName(idxVal))", line: bracketLine)
            }
            if i < 0 || i >= list.elements.count {
                throw TernError("index \(i) out of range for length \(list.elements.count)", line: bracketLine)
            }
            list.elements[i] = v
        case .exprStmt(let expr, _):
            _ = try eval(expr, scope)
        }
    }

    func eval(_ expr: Expr, _ scope: Scope) throws -> TernValue {
        switch expr {
        case .intLit(let v, _): return .int(v)
        case .strLit(let s, _): return .string(s)
        case .boolLit(let b, _): return .bool(b)
        case .nilLit: return .nilVal
        case .ident(let name, let line):
            if let v = scope.lookup(name) { return v }
            throw TernError("undefined variable \(name)", line: line)
        case .binOp(let op, let left, let right, let line):
            return try evalBinOp(op, left, right, line, scope)
        case .neg(let operand, let line):
            let v = try eval(operand, scope)
            guard case .int(let n) = v else {
                throw TernError("cannot apply - to \(typeName(v))", line: line)
            }
            if n == Int.min {
                throw TernError("integer overflow", line: line)
            }
            return .int(-n)
        case .notOp(let operand, _):
            let v = try eval(operand, scope)
            return .bool(!isTruthy(v))
        case .call(let callee, let args, let callLine):
            let calleeVal = try eval(callee, scope)
            var argVals: [TernValue] = []
            for arg in args {
                argVals.append(try eval(arg, scope))
            }
            return try callFunction(calleeVal, argVals, callLine)
        case .index(let obj, let idx, let bracketLine):
            let objVal = try eval(obj, scope)
            let idxVal = try eval(idx, scope)
            switch objVal {
            case .list(let list):
                guard case .int(let i) = idxVal else {
                    throw TernError("cannot index list with \(typeName(idxVal))", line: bracketLine)
                }
                if i < 0 || i >= list.elements.count {
                    throw TernError("index \(i) out of range for length \(list.elements.count)", line: bracketLine)
                }
                return list.elements[i]
            case .string(let s):
                guard case .int(let i) = idxVal else {
                    throw TernError("cannot index string with \(typeName(idxVal))", line: bracketLine)
                }
                let chars = Array(s.unicodeScalars)
                if i < 0 || i >= chars.count {
                    throw TernError("index \(i) out of range for length \(chars.count)", line: bracketLine)
                }
                return .string(String(chars[i]))
            default:
                throw TernError("cannot index \(typeName(objVal)) with \(typeName(idxVal))", line: bracketLine)
            }
        case .listLit(let elements, _):
            var vals: [TernValue] = []
            vals.reserveCapacity(elements.count)
            for e in elements {
                vals.append(try eval(e, scope))
            }
            return .list(TernList(vals))
        case .fnExpr(let params, let body, _):
            return .function(TernFunction(params: params, body: body, capturedScope: scope))
        }
    }

    func evalBinOp(_ op: BinOpType, _ left: Expr, _ right: Expr, _ line: Int, _ scope: Scope) throws -> TernValue {
        switch op {
        case .and:
            let lv = try eval(left, scope)
            if !isTruthy(lv) { return lv }
            return try eval(right, scope)
        case .or:
            let lv = try eval(left, scope)
            if isTruthy(lv) { return lv }
            return try eval(right, scope)
        default:
            let lv = try eval(left, scope)
            let rv = try eval(right, scope)
            return try applyBinOp(op, lv, rv, line)
        }
    }

    func applyBinOp(_ op: BinOpType, _ a: TernValue, _ b: TernValue, _ line: Int) throws -> TernValue {
        switch op {
        case .add:
            if case .int(let x) = a, case .int(let y) = b {
                let (result, overflow) = x.addingReportingOverflow(y)
                if overflow { throw TernError("integer overflow", line: line) }
                return .int(result)
            }
            if case .string(let x) = a, case .string(let y) = b {
                return .string(x + y)
            }
            if case .list(let x) = a, case .list(let y) = b {
                return .list(TernList(x.elements + y.elements))
            }
            throw TernError("cannot apply + to \(typeName(a)) and \(typeName(b))", line: line)
        case .sub:
            if case .int(let x) = a, case .int(let y) = b {
                let (result, overflow) = x.subtractingReportingOverflow(y)
                if overflow { throw TernError("integer overflow", line: line) }
                return .int(result)
            }
            throw TernError("cannot apply - to \(typeName(a)) and \(typeName(b))", line: line)
        case .mul:
            if case .int(let x) = a, case .int(let y) = b {
                let (result, overflow) = x.multipliedReportingOverflow(by: y)
                if overflow { throw TernError("integer overflow", line: line) }
                return .int(result)
            }
            throw TernError("cannot apply * to \(typeName(a)) and \(typeName(b))", line: line)
        case .div:
            if case .int(let x) = a, case .int(let y) = b {
                if y == 0 { throw TernError("division by zero", line: line) }
                if x == Int.min && y == -1 { throw TernError("integer overflow", line: line) }
                return .int(x / y)
            }
            throw TernError("cannot apply / to \(typeName(a)) and \(typeName(b))", line: line)
        case .mod:
            if case .int(let x) = a, case .int(let y) = b {
                if y == 0 { throw TernError("division by zero", line: line) }
                if y == -1 { return .int(0) }
                return .int(x % y)
            }
            throw TernError("cannot apply % to \(typeName(a)) and \(typeName(b))", line: line)
        case .eq:
            return .bool(valueEquals(a, b))
        case .ne:
            return .bool(!valueEquals(a, b))
        case .lt:
            if case .int(let x) = a, case .int(let y) = b { return .bool(x < y) }
            if case .string(let x) = a, case .string(let y) = b { return .bool(Array(x.utf8).lexicographicallyPrecedes(Array(y.utf8))) }
            throw TernError("cannot apply < to \(typeName(a)) and \(typeName(b))", line: line)
        case .le:
            if case .int(let x) = a, case .int(let y) = b { return .bool(x <= y) }
            if case .string(let x) = a, case .string(let y) = b { return .bool(!Array(y.utf8).lexicographicallyPrecedes(Array(x.utf8))) }
            throw TernError("cannot apply <= to \(typeName(a)) and \(typeName(b))", line: line)
        case .gt:
            if case .int(let x) = a, case .int(let y) = b { return .bool(x > y) }
            if case .string(let x) = a, case .string(let y) = b { return .bool(Array(y.utf8).lexicographicallyPrecedes(Array(x.utf8))) }
            throw TernError("cannot apply > to \(typeName(a)) and \(typeName(b))", line: line)
        case .ge:
            if case .int(let x) = a, case .int(let y) = b { return .bool(x >= y) }
            if case .string(let x) = a, case .string(let y) = b { return .bool(!Array(x.utf8).lexicographicallyPrecedes(Array(y.utf8))) }
            throw TernError("cannot apply >= to \(typeName(a)) and \(typeName(b))", line: line)
        case .and, .or:
            fatalError("and/or should not reach applyBinOp")
        }
    }

    func callFunction(_ callee: TernValue, _ args: [TernValue], _ callLine: Int) throws -> TernValue {
        guard case .function(let fn) = callee else {
            throw TernError("cannot call \(typeName(callee))", line: callLine)
        }
        if let name = fn.builtinName {
            return try callBuiltin(name, args, callLine)
        }
        if args.count != fn.params.count {
            throw TernError("expected \(fn.params.count) arguments, got \(args.count)", line: callLine)
        }
        let callScope = Scope(parent: fn.capturedScope)
        for (i, param) in fn.params.enumerated() {
            callScope.vars[param] = args[i]
        }
        do {
            try execBlock(fn.body, callScope)
        } catch ControlFlow.returnVal(let v) {
            return v
        }
        return .nilVal
    }

    func callBuiltin(_ name: String, _ args: [TernValue], _ callLine: Int) throws -> TernValue {
        switch name {
        case "print":
            var parts: [String] = []
            for arg in args {
                var seen = Set<ObjectIdentifier>()
                parts.append(display(arg, inList: false, seen: &seen))
            }
            print(parts.joined(separator: " "))
            return .nilVal
        case "str":
            if args.count != 1 { throw TernError("expected 1 arguments, got \(args.count)", line: callLine) }
            var seen = Set<ObjectIdentifier>()
            return .string(display(args[0], inList: false, seen: &seen))
        case "type":
            if args.count != 1 { throw TernError("expected 1 arguments, got \(args.count)", line: callLine) }
            return .string(typeName(args[0]))
        case "len":
            if args.count != 1 { throw TernError("expected 1 arguments, got \(args.count)", line: callLine) }
            switch args[0] {
            case .string(let s): return .int(s.unicodeScalars.count)
            case .list(let l): return .int(l.elements.count)
            default: throw TernError("bad argument to len", line: callLine)
            }
        case "push":
            if args.count != 2 { throw TernError("expected 2 arguments, got \(args.count)", line: callLine) }
            guard case .list(let l) = args[0] else { throw TernError("bad argument to push", line: callLine) }
            l.elements.append(args[1])
            return .nilVal
        case "pop":
            if args.count != 1 { throw TernError("expected 1 arguments, got \(args.count)", line: callLine) }
            guard case .list(let l) = args[0] else { throw TernError("bad argument to pop", line: callLine) }
            if l.elements.isEmpty { throw TernError("bad argument to pop", line: callLine) }
            return l.elements.removeLast()
        case "range":
            if args.count != 2 { throw TernError("expected 2 arguments, got \(args.count)", line: callLine) }
            guard case .int(let a) = args[0], case .int(let b) = args[1] else {
                throw TernError("bad argument to range", line: callLine)
            }
            if b <= a { return .list(TernList()) }
            var elems: [TernValue] = []
            elems.reserveCapacity(b - a)
            var i = a
            while i < b {
                elems.append(.int(i))
                i += 1
            }
            return .list(TernList(elems))
        case "slice":
            if args.count != 3 { throw TernError("expected 3 arguments, got \(args.count)", line: callLine) }
            guard case .int(let a) = args[1], case .int(let b) = args[2] else {
                throw TernError("bad argument to slice", line: callLine)
            }
            switch args[0] {
            case .string(let s):
                let chars = Array(s.unicodeScalars)
                if a < 0 || b > chars.count || a > b { throw TernError("bad argument to slice", line: callLine) }
                return .string(String(chars[a..<b]))
            case .list(let l):
                if a < 0 || b > l.elements.count || a > b { throw TernError("bad argument to slice", line: callLine) }
                return .list(TernList(Array(l.elements[a..<b])))
            default:
                throw TernError("bad argument to slice", line: callLine)
            }
        default:
            throw TernError("bad argument to \(name)", line: callLine)
        }
    }
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else {
    exit(1)
}
let dir = args[1]
let path = dir + "/program.tern"
guard let content = try? String(contentsOfFile: path, encoding: .utf8) else {
    exit(1)
}
let lexer = Lexer(content)
let tokens = lexer.tokenize()
let parser = Parser(tokens)
let program = parser.parseProgram()
let interpreter = Interpreter()
interpreter.run(program)

import * as fs from 'fs';
import * as path from 'path';

// ==================== LEXER ====================

interface Token {
  type: 'INT' | 'STRING' | 'IDENT' | 'KEYWORD' | 'OP' | 'EOF';
  value: string;
  line: number;
}

const KEYWORDS = new Set([
  'let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return', 'break', 'continue',
  'and', 'or', 'not', 'true', 'false', 'nil'
]);

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;
  let line = 1;
  const len = source.length;

  while (pos < len) {
    const ch = source[pos];
    if (ch === '\n') { line++; pos++; continue; }
    if (ch === ' ' || ch === '\t' || ch === '\r') { pos++; continue; }
    if (ch === '#') { while (pos < len && source[pos] !== '\n') pos++; continue; }

    if (ch >= '0' && ch <= '9') {
      const start = pos;
      while (pos < len && source[pos] >= '0' && source[pos] <= '9') pos++;
      tokens.push({ type: 'INT', value: source.slice(start, pos), line });
      continue;
    }

    if (ch === '"') {
      pos++;
      let str = '';
      while (pos < len && source[pos] !== '"') {
        if (source[pos] === '\\') {
          pos++;
          const esc = source[pos];
          if (esc === 'n') str += '\n';
          else if (esc === 't') str += '\t';
          else if (esc === '"') str += '"';
          else if (esc === '\\') str += '\\';
          else str += esc;
          pos++;
        } else { str += source[pos]; pos++; }
      }
      pos++;
      tokens.push({ type: 'STRING', value: str, line });
      continue;
    }

    if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_') {
      const start = pos;
      while (pos < len) {
        const c = source[pos];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c === '_') pos++;
        else break;
      }
      const word = source.slice(start, pos);
      tokens.push({ type: KEYWORDS.has(word) ? 'KEYWORD' : 'IDENT', value: word, line });
      continue;
    }

    if (pos + 1 < len) {
      const two = source[pos] + source[pos + 1];
      if (two === '==' || two === '!=' || two === '<=' || two === '>=') {
        tokens.push({ type: 'OP', value: two, line });
        pos += 2;
        continue;
      }
    }

    if ('<>=+-*/%()[]{},;'.includes(ch)) {
      tokens.push({ type: 'OP', value: ch, line });
      pos++;
      continue;
    }
    pos++;
  }

  tokens.push({ type: 'EOF', value: '', line });
  return tokens;
}

// ==================== AST ====================

type TernValue = bigint | boolean | string | TernList | TernFunction | TernBuiltin | null;
type TernList = TernValue[];

interface TernFunction {
  kind: 'user';
  params: string[];
  body: Stmt[];
  capturedScope: Scope;
}

interface TernBuiltin {
  kind: 'builtin';
  name: string;
  arity: number;
  fn: (args: TernValue[], interp: Interpreter, line: number) => TernValue;
}

interface Scope {
  vars: Map<string, TernValue>;
  parent: Scope | null;
}

type Expr =
  | { kind: 'int'; value: bigint; line: number }
  | { kind: 'string'; value: string; line: number }
  | { kind: 'bool'; value: boolean; line: number }
  | { kind: 'nil'; line: number }
  | { kind: 'ident'; name: string; line: number }
  | { kind: 'list'; elements: Expr[]; line: number }
  | { kind: 'fn'; params: string[]; body: Stmt[]; line: number }
  | { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'unary'; op: string; operand: Expr; line: number }
  | { kind: 'call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'index'; object: Expr; index: Expr; line: number }
  | { kind: 'and'; left: Expr; right: Expr; line: number }
  | { kind: 'or'; left: Expr; right: Expr; line: number };

interface IfStmt {
  kind: 'if';
  condition: Expr;
  thenBody: Stmt[];
  elseIf: IfStmt | null;
  elseBody: Stmt[] | null;
  line: number;
}

type Stmt =
  | IfStmt
  | { kind: 'let'; name: string; value: Expr; line: number }
  | { kind: 'fnDecl'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'while'; condition: Expr; body: Stmt[]; line: number }
  | { kind: 'for'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'return'; value: Expr | null; line: number }
  | { kind: 'break'; line: number }
  | { kind: 'continue'; line: number }
  | { kind: 'assign'; name: string; value: Expr; line: number }
  | { kind: 'indexAssign'; object: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'exprStmt'; expr: Expr; line: number };

// ==================== PARSER ====================

class Parser {
  private tokens: Token[];
  private pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  private peek(): Token { return this.tokens[this.pos]; }
  private peekAt(n: number): Token { return this.tokens[this.pos + n]; }
  private advance(): Token { return this.tokens[this.pos++]; }

  private expect(type: string, value?: string): Token {
    const tok = this.advance();
    if (tok.type !== type || (value !== undefined && tok.value !== value)) {
      throw new Error(`Expected ${type}${value ? ' ' + value : ''} but got ${tok.type} ${tok.value} at line ${tok.line}`);
    }
    return tok;
  }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type !== 'EOF') stmts.push(this.parseStmt());
    return stmts;
  }

  private parseBlock(): Stmt[] {
    this.expect('OP', '{');
    const stmts: Stmt[] = [];
    while (!(this.peek().type === 'OP' && this.peek().value === '}')) stmts.push(this.parseStmt());
    this.expect('OP', '}');
    return stmts;
  }

  private parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type === 'OP' && this.peek().value === ')') return params;
    params.push(this.expect('IDENT').value);
    while (this.peek().type === 'OP' && this.peek().value === ',') {
      this.advance();
      params.push(this.expect('IDENT').value);
    }
    return params;
  }

  private parseStmt(): Stmt {
    const tok = this.peek();

    if (tok.type === 'KEYWORD') {
      switch (tok.value) {
        case 'let': return this.parseLet();
        case 'fn':
          if (this.peekAt(1).type === 'IDENT') return this.parseFnDecl();
          break;
        case 'if': return this.parseIf();
        case 'while': return this.parseWhile();
        case 'for': return this.parseFor();
        case 'return': return this.parseReturn();
        case 'break': this.advance(); this.expect('OP', ';'); return { kind: 'break', line: tok.line };
        case 'continue': this.advance(); this.expect('OP', ';'); return { kind: 'continue', line: tok.line };
      }
    }

    if (tok.type === 'IDENT') {
      const next = this.peekAt(1);
      if (next.type === 'OP' && next.value === '=') {
        this.advance(); this.advance();
        const value = this.parseExpr();
        this.expect('OP', ';');
        return { kind: 'assign', name: tok.value, value, line: tok.line };
      }
    }

    const expr = this.parseExpr();
    if (this.peek().type === 'OP' && this.peek().value === '=') {
      this.advance();
      const value = this.parseExpr();
      this.expect('OP', ';');
      if (expr.kind === 'index') {
        return { kind: 'indexAssign', object: expr.object, index: expr.index, value, line: expr.line };
      }
      throw new Error('Invalid assignment target');
    }
    this.expect('OP', ';');
    return { kind: 'exprStmt', expr, line: tok.line };
  }

  private parseLet(): Stmt {
    const tok = this.advance();
    const name = this.expect('IDENT').value;
    this.expect('OP', '=');
    const value = this.parseExpr();
    this.expect('OP', ';');
    return { kind: 'let', name, value, line: tok.line };
  }

  private parseFnDecl(): Stmt {
    const tok = this.advance();
    const name = this.expect('IDENT').value;
    this.expect('OP', '(');
    const params = this.parseParams();
    this.expect('OP', ')');
    const body = this.parseBlock();
    return { kind: 'fnDecl', name, params, body, line: tok.line };
  }

  private parseIf(): IfStmt {
    const tok = this.advance();
    const condition = this.parseExpr();
    const thenBody = this.parseBlock();
    let elseIf: IfStmt | null = null;
    let elseBody: Stmt[] | null = null;
    if (this.peek().type === 'KEYWORD' && this.peek().value === 'else') {
      this.advance();
      if (this.peek().type === 'KEYWORD' && this.peek().value === 'if') {
        elseIf = this.parseIf();
      } else {
        elseBody = this.parseBlock();
      }
    }
    return { kind: 'if', condition, thenBody, elseIf, elseBody, line: tok.line };
  }

  private parseWhile(): Stmt {
    const tok = this.advance();
    const condition = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'while', condition, body, line: tok.line };
  }

  private parseFor(): Stmt {
    const tok = this.advance();
    const varName = this.expect('IDENT').value;
    this.expect('KEYWORD', 'in');
    const iterable = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'for', varName, iterable, body, line: tok.line };
  }

  private parseReturn(): Stmt {
    const tok = this.advance();
    let value: Expr | null = null;
    if (!(this.peek().type === 'OP' && this.peek().value === ';')) value = this.parseExpr();
    this.expect('OP', ';');
    return { kind: 'return', value, line: tok.line };
  }

  private parseExpr(): Expr { return this.parseOr(); }

  private parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek().type === 'KEYWORD' && this.peek().value === 'or') {
      const tok = this.advance();
      left = { kind: 'or', left, right: this.parseAnd(), line: tok.line };
    }
    return left;
  }

  private parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek().type === 'KEYWORD' && this.peek().value === 'and') {
      const tok = this.advance();
      left = { kind: 'and', left, right: this.parseNot(), line: tok.line };
    }
    return left;
  }

  private parseNot(): Expr {
    if (this.peek().type === 'KEYWORD' && this.peek().value === 'not') {
      const tok = this.advance();
      return { kind: 'unary', op: 'not', operand: this.parseNot(), line: tok.line };
    }
    return this.parseComparison();
  }

  private parseComparison(): Expr {
    let left = this.parseAdditive();
    while (this.peek().type === 'OP' && ['==', '!=', '<', '<=', '>', '>='].includes(this.peek().value)) {
      const tok = this.advance();
      left = { kind: 'binary', op: tok.value, left, right: this.parseAdditive(), line: tok.line };
    }
    return left;
  }

  private parseAdditive(): Expr {
    let left = this.parseMultiplicative();
    while (this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const tok = this.advance();
      left = { kind: 'binary', op: tok.value, left, right: this.parseMultiplicative(), line: tok.line };
    }
    return left;
  }

  private parseMultiplicative(): Expr {
    let left = this.parseUnary();
    while (this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/' || this.peek().value === '%')) {
      const tok = this.advance();
      left = { kind: 'binary', op: tok.value, left, right: this.parseUnary(), line: tok.line };
    }
    return left;
  }

  private parseUnary(): Expr {
    if (this.peek().type === 'OP' && this.peek().value === '-') {
      const tok = this.advance();
      return { kind: 'unary', op: '-', operand: this.parseUnary(), line: tok.line };
    }
    return this.parsePostfix();
  }

  private parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.peek().type === 'OP' && this.peek().value === '(') {
        const tok = this.advance();
        const args: Expr[] = [];
        if (!(this.peek().type === 'OP' && this.peek().value === ')')) {
          args.push(this.parseExpr());
          while (this.peek().type === 'OP' && this.peek().value === ',') {
            this.advance();
            args.push(this.parseExpr());
          }
        }
        this.expect('OP', ')');
        expr = { kind: 'call', callee: expr, args, line: tok.line };
      } else if (this.peek().type === 'OP' && this.peek().value === '[') {
        const tok = this.advance();
        const index = this.parseExpr();
        this.expect('OP', ']');
        expr = { kind: 'index', object: expr, index, line: tok.line };
      } else break;
    }
    return expr;
  }

  private parsePrimary(): Expr {
    const tok = this.peek();
    if (tok.type === 'INT') { this.advance(); return { kind: 'int', value: BigInt(tok.value), line: tok.line }; }
    if (tok.type === 'STRING') { this.advance(); return { kind: 'string', value: tok.value, line: tok.line }; }
    if (tok.type === 'KEYWORD') {
      if (tok.value === 'true') { this.advance(); return { kind: 'bool', value: true, line: tok.line }; }
      if (tok.value === 'false') { this.advance(); return { kind: 'bool', value: false, line: tok.line }; }
      if (tok.value === 'nil') { this.advance(); return { kind: 'nil', line: tok.line }; }
      if (tok.value === 'fn') {
        this.advance();
        this.expect('OP', '(');
        const params = this.parseParams();
        this.expect('OP', ')');
        const body = this.parseBlock();
        return { kind: 'fn', params, body, line: tok.line };
      }
    }
    if (tok.type === 'IDENT') { this.advance(); return { kind: 'ident', name: tok.value, line: tok.line }; }
    if (tok.type === 'OP' && tok.value === '(') {
      this.advance();
      const expr = this.parseExpr();
      this.expect('OP', ')');
      return expr;
    }
    if (tok.type === 'OP' && tok.value === '[') {
      this.advance();
      const elements: Expr[] = [];
      if (!(this.peek().type === 'OP' && this.peek().value === ']')) {
        elements.push(this.parseExpr());
        while (this.peek().type === 'OP' && this.peek().value === ',') {
          this.advance();
          elements.push(this.parseExpr());
        }
      }
      this.expect('OP', ']');
      return { kind: 'list', elements, line: tok.line };
    }
    throw new Error(`Unexpected token: ${tok.type} ${tok.value} at line ${tok.line}`);
  }
}

// ==================== INTERPRETER ====================

class TernError extends Error {
  constructor(public line: number, message: string) { super(message); }
}

class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { constructor(public value: TernValue) {} }

const INT_MIN = -(1n << 63n);
const INT_MAX = (1n << 63n) - 1n;

class Interpreter {
  private globalScope: Scope;

  constructor() {
    const builtinScope: Scope = { vars: new Map(), parent: null };
    this.globalScope = { vars: new Map(), parent: builtinScope };
    this.setupBuiltins(builtinScope);
  }

  private setupBuiltins(scope: Scope) {
    const b = scope.vars;

    b.set('print', { kind: 'builtin', name: 'print', arity: -1,
      fn: (args, interp, _line) => {
        const parts: string[] = [];
        for (const a of args) parts.push(interp.display(a, false, new Set()));
        process.stdout.write(parts.join(' ') + '\n');
        return null;
      }
    });

    b.set('str', { kind: 'builtin', name: 'str', arity: 1,
      fn: (args, interp, _line) => interp.display(args[0], false, new Set())
    });

    b.set('type', { kind: 'builtin', name: 'type', arity: 1,
      fn: (args, interp, _line) => interp.typeName(args[0])
    });

    b.set('len', { kind: 'builtin', name: 'len', arity: 1,
      fn: (args, _interp, line) => {
        const v = args[0];
        if (typeof v === 'string') return BigInt(v.length);
        if (Array.isArray(v)) return BigInt(v.length);
        throw new TernError(line, 'bad argument to len');
      }
    });

    b.set('push', { kind: 'builtin', name: 'push', arity: 2,
      fn: (args, _interp, line) => {
        if (!Array.isArray(args[0])) throw new TernError(line, 'bad argument to push');
        (args[0] as TernList).push(args[1]);
        return null;
      }
    });

    b.set('pop', { kind: 'builtin', name: 'pop', arity: 1,
      fn: (args, _interp, line) => {
        if (!Array.isArray(args[0])) throw new TernError(line, 'bad argument to pop');
        const list = args[0] as TernList;
        if (list.length === 0) throw new TernError(line, 'bad argument to pop');
        return list.pop()!;
      }
    });

    b.set('range', { kind: 'builtin', name: 'range', arity: 2,
      fn: (args, _interp, line) => {
        if (typeof args[0] !== 'bigint' || typeof args[1] !== 'bigint')
          throw new TernError(line, 'bad argument to range');
        const a = args[0] as bigint, b = args[1] as bigint;
        const result: TernList = [];
        for (let i = a; i < b; i++) result.push(i);
        return result;
      }
    });

    b.set('slice', { kind: 'builtin', name: 'slice', arity: 3,
      fn: (args, _interp, line) => {
        const x = args[0], a = args[1], b = args[2];
        if (typeof a !== 'bigint' || typeof b !== 'bigint')
          throw new TernError(line, 'bad argument to slice');
        const ai = Number(a), bi = Number(b);
        if (typeof x === 'string') {
          if (ai < 0 || bi > x.length || ai > bi) throw new TernError(line, 'bad argument to slice');
          return x.slice(ai, bi);
        }
        if (Array.isArray(x)) {
          if (ai < 0 || bi > x.length || ai > bi) throw new TernError(line, 'bad argument to slice');
          return (x as TernList).slice(ai, bi);
        }
        throw new TernError(line, 'bad argument to slice');
      }
    });
  }

  typeName(v: TernValue): string {
    if (v === null) return 'nil';
    if (typeof v === 'bigint') return 'int';
    if (typeof v === 'boolean') return 'bool';
    if (typeof v === 'string') return 'string';
    if (Array.isArray(v)) return 'list';
    return 'function';
  }

  truthiness(v: TernValue): boolean {
    if (v === null) return false;
    if (typeof v === 'boolean') return v;
    if (typeof v === 'bigint') return v !== 0n;
    if (typeof v === 'string') return v.length > 0;
    if (Array.isArray(v)) return v.length > 0;
    return true;
  }

  display(v: TernValue, inList: boolean, seen: Set<TernList>): string {
    if (v === null) return 'nil';
    if (typeof v === 'bigint') return v.toString();
    if (typeof v === 'boolean') return v ? 'true' : 'false';
    if (typeof v === 'string') {
      if (!inList) return v;
      let r = '"';
      for (let i = 0; i < v.length; i++) {
        const ch = v[i];
        if (ch === '\\') r += '\\\\';
        else if (ch === '"') r += '\\"';
        else if (ch === '\n') r += '\\n';
        else if (ch === '\t') r += '\\t';
        else r += ch;
      }
      return r + '"';
    }
    if (Array.isArray(v)) {
      if (seen.has(v)) return '[...]';
      seen.add(v);
      const parts: string[] = [];
      for (const e of v) parts.push(this.display(e, true, seen));
      seen.delete(v);
      return '[' + parts.join(', ') + ']';
    }
    return '<fn>';
  }

  private checkIntRange(v: bigint, line: number): bigint {
    if (v < INT_MIN || v > INT_MAX) throw new TernError(line, 'integer overflow');
    return v;
  }

  private lookup(name: string, scope: Scope, line: number): TernValue {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) return s.vars.get(name)!;
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  private assignVar(name: string, value: TernValue, scope: Scope, line: number): void {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) { s.vars.set(name, value); return; }
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  run(stmts: Stmt[]): void {
    this.execBlock(stmts, this.globalScope);
  }

  private execBlock(stmts: Stmt[], scope: Scope): void {
    for (const stmt of stmts) this.execStmt(stmt, scope);
  }

  private execStmt(stmt: Stmt, scope: Scope): void {
    switch (stmt.kind) {
      case 'let': {
        const value = this.eval(stmt.value, scope);
        scope.vars.set(stmt.name, value);
        break;
      }
      case 'fnDecl': {
        const fn: TernFunction = { kind: 'user', params: stmt.params, body: stmt.body, capturedScope: scope };
        scope.vars.set(stmt.name, fn);
        break;
      }
      case 'if': {
        if (this.truthiness(this.eval(stmt.condition, scope))) {
          const bs: Scope = { vars: new Map(), parent: scope };
          this.execBlock(stmt.thenBody, bs);
        } else if (stmt.elseIf) {
          this.execStmt(stmt.elseIf, scope);
        } else if (stmt.elseBody) {
          const bs: Scope = { vars: new Map(), parent: scope };
          this.execBlock(stmt.elseBody, bs);
        }
        break;
      }
      case 'while': {
        while (this.truthiness(this.eval(stmt.condition, scope))) {
          const bs: Scope = { vars: new Map(), parent: scope };
          try { this.execBlock(stmt.body, bs); }
          catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { /* fall through */ }
            else throw e;
          }
        }
        break;
      }
      case 'for': {
        const list = this.eval(stmt.iterable, scope);
        if (!Array.isArray(list)) throw new TernError(stmt.line, `cannot iterate ${this.typeName(list)}`);
        const arr = list as TernList;
        let i = 0;
        while (i < arr.length) {
          const is: Scope = { vars: new Map(), parent: scope };
          is.vars.set(stmt.varName, arr[i]);
          try { this.execBlock(stmt.body, is); }
          catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { /* fall through */ }
            else throw e;
          }
          i++;
        }
        break;
      }
      case 'return': {
        const value = stmt.value ? this.eval(stmt.value, scope) : null;
        throw new ReturnSignal(value);
      }
      case 'break': throw new BreakSignal();
      case 'continue': throw new ContinueSignal();
      case 'assign': {
        const value = this.eval(stmt.value, scope);
        this.assignVar(stmt.name, value, scope, stmt.line);
        break;
      }
      case 'indexAssign': {
        const obj = this.eval(stmt.object, scope);
        const idx = this.eval(stmt.index, scope);
        const val = this.eval(stmt.value, scope);
        if (!Array.isArray(obj)) throw new TernError(stmt.line, `cannot assign into ${this.typeName(obj)}`);
        if (typeof idx !== 'bigint') throw new TernError(stmt.line, `cannot index list with ${this.typeName(idx)}`);
        const i = Number(idx);
        const len = (obj as TernList).length;
        if (i < 0 || i >= len) throw new TernError(stmt.line, `index ${idx} out of range for length ${len}`);
        (obj as TernList)[i] = val;
        break;
      }
      case 'exprStmt': {
        this.eval(stmt.expr, scope);
        break;
      }
    }
  }

  eval(expr: Expr, scope: Scope): TernValue {
    switch (expr.kind) {
      case 'int': return expr.value;
      case 'string': return expr.value;
      case 'bool': return expr.value;
      case 'nil': return null;
      case 'ident': return this.lookup(expr.name, scope, expr.line);
      case 'list': {
        const result: TernList = [];
        for (const e of expr.elements) result.push(this.eval(e, scope));
        return result;
      }
      case 'fn': return { kind: 'user', params: expr.params, body: expr.body, capturedScope: scope };
      case 'and': {
        const left = this.eval(expr.left, scope);
        if (!this.truthiness(left)) return left;
        return this.eval(expr.right, scope);
      }
      case 'or': {
        const left = this.eval(expr.left, scope);
        if (this.truthiness(left)) return left;
        return this.eval(expr.right, scope);
      }
      case 'unary': return this.evalUnary(expr, scope);
      case 'binary': return this.evalBinary(expr, scope);
      case 'call': return this.evalCall(expr, scope);
      case 'index': return this.evalIndex(expr, scope);
    }
  }

  private evalUnary(expr: { kind: 'unary'; op: string; operand: Expr; line: number }, scope: Scope): TernValue {
    if (expr.op === 'not') {
      return !this.truthiness(this.eval(expr.operand, scope));
    }
    const val = this.eval(expr.operand, scope);
    if (typeof val !== 'bigint') throw new TernError(expr.line, `cannot apply - to ${this.typeName(val)}`);
    return this.checkIntRange(-val, expr.line);
  }

  private evalBinary(expr: { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }, scope: Scope): TernValue {
    const left = this.eval(expr.left, scope);
    const right = this.eval(expr.right, scope);
    const op = expr.op;

    switch (op) {
      case '+': {
        if (typeof left === 'bigint' && typeof right === 'bigint') return this.checkIntRange(left + right, expr.line);
        if (typeof left === 'string' && typeof right === 'string') return left + right;
        if (Array.isArray(left) && Array.isArray(right)) return [...(left as TernList), ...(right as TernList)];
        throw new TernError(expr.line, `cannot apply + to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      case '-': {
        if (typeof left === 'bigint' && typeof right === 'bigint') return this.checkIntRange(left - right, expr.line);
        throw new TernError(expr.line, `cannot apply - to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      case '*': {
        if (typeof left === 'bigint' && typeof right === 'bigint') return this.checkIntRange(left * right, expr.line);
        throw new TernError(expr.line, `cannot apply * to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      case '/': {
        if (typeof left === 'bigint' && typeof right === 'bigint') {
          if (right === 0n) throw new TernError(expr.line, 'division by zero');
          return this.checkIntRange(left / right, expr.line);
        }
        throw new TernError(expr.line, `cannot apply / to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      case '%': {
        if (typeof left === 'bigint' && typeof right === 'bigint') {
          if (right === 0n) throw new TernError(expr.line, 'division by zero');
          return left - (left / right) * right;
        }
        throw new TernError(expr.line, `cannot apply % to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      case '==': return this.valuesEqual(left, right);
      case '!=': return !this.valuesEqual(left, right);
      case '<': case '<=': case '>': case '>=': {
        if (typeof left === 'bigint' && typeof right === 'bigint') {
          if (op === '<') return left < right;
          if (op === '<=') return left <= right;
          if (op === '>') return left > right;
          return left >= right;
        }
        if (typeof left === 'string' && typeof right === 'string') {
          if (op === '<') return left < right;
          if (op === '<=') return left <= right;
          if (op === '>') return left > right;
          return left >= right;
        }
        throw new TernError(expr.line, `cannot apply ${op} to ${this.typeName(left)} and ${this.typeName(right)}`);
      }
      default:
        throw new TernError(expr.line, `unknown operator ${op}`);
    }
  }

  private valuesEqual(a: TernValue, b: TernValue): boolean {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    const ta = this.typeName(a), tb = this.typeName(b);
    if (ta !== tb) return false;
    if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
    if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
    if (typeof a === 'string' && typeof b === 'string') return a === b;
    if (Array.isArray(a) && Array.isArray(b)) {
      const la = a as TernList, lb = b as TernList;
      if (la.length !== lb.length) return false;
      for (let i = 0; i < la.length; i++) {
        if (!this.valuesEqual(la[i], lb[i])) return false;
      }
      return true;
    }
    return a === b;
  }

  private evalCall(expr: { kind: 'call'; callee: Expr; args: Expr[]; line: number }, scope: Scope): TernValue {
    const callee = this.eval(expr.callee, scope);
    const args: TernValue[] = [];
    for (const a of expr.args) args.push(this.eval(a, scope));

    if (callee === null || typeof callee === 'bigint' || typeof callee === 'boolean' || typeof callee === 'string' || Array.isArray(callee)) {
      throw new TernError(expr.line, `cannot call ${this.typeName(callee)}`);
    }

    if (callee.kind === 'builtin') {
      if (callee.arity >= 0 && args.length !== callee.arity) {
        throw new TernError(expr.line, `expected ${callee.arity} arguments, got ${args.length}`);
      }
      return callee.fn(args, this, expr.line);
    }

    const fn = callee as TernFunction;
    if (args.length !== fn.params.length) {
      throw new TernError(expr.line, `expected ${fn.params.length} arguments, got ${args.length}`);
    }

    const fnScope: Scope = { vars: new Map(), parent: fn.capturedScope };
    for (let i = 0; i < fn.params.length; i++) {
      fnScope.vars.set(fn.params[i], args[i]);
    }

    try {
      this.execBlock(fn.body, fnScope);
    } catch (e) {
      if (e instanceof ReturnSignal) return e.value;
      throw e;
    }
    return null;
  }

  private evalIndex(expr: { kind: 'index'; object: Expr; index: Expr; line: number }, scope: Scope): TernValue {
    const obj = this.eval(expr.object, scope);
    const idx = this.eval(expr.index, scope);

    if (!Array.isArray(obj) && typeof obj !== 'string') {
      throw new TernError(expr.line, `cannot index ${this.typeName(obj)} with ${this.typeName(idx)}`);
    }
    if (typeof idx !== 'bigint') {
      throw new TernError(expr.line, `cannot index ${this.typeName(obj)} with ${this.typeName(idx)}`);
    }

    const i = Number(idx);
    const len = Array.isArray(obj) ? (obj as TernList).length : (obj as string).length;
    if (i < 0 || i >= len) {
      throw new TernError(expr.line, `index ${idx} out of range for length ${len}`);
    }

    if (Array.isArray(obj)) return (obj as TernList)[i];
    return (obj as string)[i];
  }
}

// ==================== MAIN ====================

const dir = process.argv[2];
const source = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = tokenize(source);
const parser = new Parser(tokens);
const ast = parser.parseProgram();
const interp = new Interpreter();

try {
  interp.run(ast);
} catch (e) {
  if (e instanceof TernError) {
    process.stdout.write(`error at line ${e.line}: ${e.message}\n`);
  } else {
    throw e;
  }
}

use std::collections::HashMap;
use std::cell::RefCell;
use std::rc::Rc;
use std::env;
use std::fs;
use std::io::{self, Write};

// ==================== TOKENS ====================

#[derive(Debug, Clone, PartialEq)]
enum TokKind {
    IntLit(i64),
    StrLit(String),
    Ident(String),
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Neq, Lt, Le, Gt, Ge, Assign,
    Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace, Comma, Semicolon,
    EOF,
}

#[derive(Debug, Clone)]
struct Tok {
    kind: TokKind,
    line: usize,
}

fn tokenize(src: &str) -> Vec<Tok> {
    let mut tokens = Vec::new();
    let bytes = src.as_bytes();
    let mut pos = 0usize;
    let mut line = 1usize;
    while pos < bytes.len() {
        let ch = bytes[pos];
        if ch == b'\n' { line += 1; pos += 1; continue; }
        if ch == b' ' || ch == b'\t' || ch == b'\r' { pos += 1; continue; }
        if ch == b'#' {
            while pos < bytes.len() && bytes[pos] != b'\n' { pos += 1; }
            continue;
        }
        if ch == b'"' {
            pos += 1;
            let mut s = String::new();
            while pos < bytes.len() && bytes[pos] != b'"' {
                if bytes[pos] == b'\\' {
                    pos += 1;
                    match bytes[pos] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        c => s.push(c as char),
                    }
                } else {
                    s.push(bytes[pos] as char);
                }
                pos += 1;
            }
            pos += 1;
            tokens.push(Tok { kind: TokKind::StrLit(s), line });
            continue;
        }
        if ch.is_ascii_digit() {
            let start = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_digit() { pos += 1; }
            let val: i64 = src[start..pos].parse().unwrap();
            tokens.push(Tok { kind: TokKind::IntLit(val), line });
            continue;
        }
        if ch.is_ascii_alphabetic() || ch == b'_' {
            let start = pos;
            while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
            let word = &src[start..pos];
            let kind = match word {
                "let" => TokKind::Let, "fn" => TokKind::Fn, "if" => TokKind::If,
                "else" => TokKind::Else, "while" => TokKind::While, "for" => TokKind::For,
                "in" => TokKind::In, "return" => TokKind::Return, "break" => TokKind::Break,
                "continue" => TokKind::Continue, "and" => TokKind::And, "or" => TokKind::Or,
                "not" => TokKind::Not, "true" => TokKind::True, "false" => TokKind::False,
                "nil" => TokKind::Nil,
                _ => TokKind::Ident(word.to_string()),
            };
            tokens.push(Tok { kind, line });
            continue;
        }
        let (kind, len) = match ch {
            b'=' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Eq, 2),
            b'!' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Neq, 2),
            b'<' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Le, 2),
            b'>' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Ge, 2),
            b'<' => (TokKind::Lt, 1),
            b'>' => (TokKind::Gt, 1),
            b'=' => (TokKind::Assign, 1),
            b'+' => (TokKind::Plus, 1),
            b'-' => (TokKind::Minus, 1),
            b'*' => (TokKind::Star, 1),
            b'/' => (TokKind::Slash, 1),
            b'%' => (TokKind::Percent, 1),
            b'(' => (TokKind::LParen, 1),
            b')' => (TokKind::RParen, 1),
            b'[' => (TokKind::LBracket, 1),
            b']' => (TokKind::RBracket, 1),
            b'{' => (TokKind::LBrace, 1),
            b'}' => (TokKind::RBrace, 1),
            b',' => (TokKind::Comma, 1),
            b';' => (TokKind::Semicolon, 1),
            _ => { pos += 1; continue; }
        };
        tokens.push(Tok { kind, line });
        pos += len;
    }
    tokens.push(Tok { kind: TokKind::EOF, line });
    tokens
}

// ==================== AST ====================

#[derive(Debug, Clone, PartialEq)]
enum BinOp { Add, Sub, Mul, Div, Mod, Eq, Neq, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64),
    StrLit(String),
    BoolLit(bool),
    NilLit,
    Ident(String, usize),
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr>, line: usize },
    UnaryNot { expr: Box<Expr> },
    UnaryNeg { expr: Box<Expr>, line: usize },
    Call { callee: Box<Expr>, args: Vec<Expr>, line: usize },
    Index { obj: Box<Expr>, idx: Box<Expr>, line: usize },
    ListLit(Vec<Expr>),
    FnLit { params: Vec<String>, body: Vec<Stmt> },
}

#[derive(Debug, Clone)]
enum Stmt {
    Let { name: String, expr: Expr },
    FnDecl { name: String, params: Vec<String>, body: Vec<Stmt> },
    If { cond: Expr, then_body: Vec<Stmt>, else_body: Option<Vec<Stmt>> },
    While { cond: Expr, body: Vec<Stmt> },
    For { var: String, iter: Expr, body: Vec<Stmt>, line: usize },
    Return { expr: Option<Expr> },
    Break,
    Continue,
    Assign { name: String, expr: Expr, line: usize },
    IndexAssign { obj: Expr, idx: Expr, val: Expr, line: usize },
    ExprStmt { expr: Expr },
}

// ==================== PARSER ====================

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn new(toks: Vec<Tok>) -> Self { Parser { toks, pos: 0 } }
    fn peek(&self) -> &Tok { &self.toks[self.pos] }
    fn peek_kind(&self) -> &TokKind { &self.toks[self.pos].kind }
    fn peek_line(&self) -> usize { self.toks[self.pos].line }
    fn advance(&mut self) -> Tok { let t = self.toks[self.pos].clone(); self.pos += 1; t }
    fn expect(&mut self, k: TokKind) -> Tok {
        let t = self.advance();
        assert_eq!(t.kind, k, "expected {:?} got {:?} at line {}", k, t.kind, t.line);
        t
    }
    fn at(&self, k: &TokKind) -> bool { self.peek_kind() == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while !self.at(&TokKind::EOF) {
            stmts.push(self.parse_stmt());
        }
        stmts
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(TokKind::LBrace);
        let mut stmts = Vec::new();
        while !self.at(&TokKind::RBrace) {
            stmts.push(self.parse_stmt());
        }
        self.expect(TokKind::RBrace);
        stmts
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut params = Vec::new();
        if !self.at(&TokKind::RParen) {
            loop {
                let t = self.expect(TokKind::Ident(String::new()));
                if let TokKind::Ident(name) = t.kind { params.push(name); }
                if !self.at(&TokKind::Comma) { break; }
                self.advance();
            }
        }
        params
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek_kind().clone() {
            TokKind::Let => {
                self.advance();
                let name = self.expect_ident();
                self.expect(TokKind::Assign);
                let expr = self.parse_expr();
                self.expect(TokKind::Semicolon);
                Stmt::Let { name, expr }
            }
            TokKind::Fn => {
                self.advance();
                let name = self.expect_ident();
                self.expect(TokKind::LParen);
                let params = self.parse_params();
                self.expect(TokKind::RParen);
                let body = self.parse_block();
                Stmt::FnDecl { name, params, body }
            }
            TokKind::If => {
                self.advance();
                let cond = self.parse_expr();
                let then_body = self.parse_block();
                let else_body = if self.at(&TokKind::Else) {
                    self.advance();
                    if self.at(&TokKind::If) {
                        Some(vec![self.parse_stmt()])
                    } else {
                        Some(self.parse_block())
                    }
                } else { None };
                Stmt::If { cond, then_body, else_body }
            }
            TokKind::While => {
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While { cond, body }
            }
            TokKind::For => {
                let for_line = self.peek_line();
                self.advance();
                let var = self.expect_ident();
                self.expect(TokKind::In);
                let iter = self.parse_expr();
                let body = self.parse_block();
                Stmt::For { var, iter, body, line: for_line }
            }
            TokKind::Return => {
                self.advance();
                let expr = if self.at(&TokKind::Semicolon) { None } else { Some(self.parse_expr()) };
                self.expect(TokKind::Semicolon);
                Stmt::Return { expr }
            }
            TokKind::Break => { self.advance(); self.expect(TokKind::Semicolon); Stmt::Break }
            TokKind::Continue => { self.advance(); self.expect(TokKind::Semicolon); Stmt::Continue }
            TokKind::Ident(_) => {
                // Check if it's an assignment
                if self.pos + 1 < self.toks.len() && self.toks[self.pos + 1].kind == TokKind::Assign {
                    let t = self.advance();
                    let name = match t.kind { TokKind::Ident(n) => n, _ => unreachable!() };
                    let line = t.line;
                    self.expect(TokKind::Assign);
                    let expr = self.parse_expr();
                    self.expect(TokKind::Semicolon);
                    return Stmt::Assign { name, expr, line };
                }
                // Parse expression and check for index assignment
                let expr = self.parse_expr();
                if self.at(&TokKind::Assign) {
                    if let Expr::Index { obj, idx, line } = expr {
                        self.advance();
                        let val = self.parse_expr();
                        self.expect(TokKind::Semicolon);
                        return Stmt::IndexAssign { obj: *obj, idx: *idx, val, line };
                    }
                }
                self.expect(TokKind::Semicolon);
                Stmt::ExprStmt { expr }
            }
            _ => {
                let expr = self.parse_expr();
                self.expect(TokKind::Semicolon);
                Stmt::ExprStmt { expr }
            }
        }
    }

    fn expect_ident(&mut self) -> String {
        let t = self.advance();
        match t.kind { TokKind::Ident(n) => n, _ => panic!("expected ident, got {:?}", t.kind) }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        while self.at(&TokKind::Or) {
            let line = self.peek_line();
            self.advance();
            let right = self.parse_and();
            left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        while self.at(&TokKind::And) {
            let line = self.peek_line();
            self.advance();
            let right = self.parse_not();
            left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(&TokKind::Not) {
            self.advance();
            let expr = self.parse_not();
            Expr::UnaryNot { expr: Box::new(expr) }
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            let op = match self.peek_kind() {
                TokKind::Eq => BinOp::Eq,
                TokKind::Neq => BinOp::Neq,
                TokKind::Lt => BinOp::Lt,
                TokKind::Le => BinOp::Le,
                TokKind::Gt => BinOp::Gt,
                TokKind::Ge => BinOp::Ge,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_add();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            let op = match self.peek_kind() {
                TokKind::Plus => BinOp::Add,
                TokKind::Minus => BinOp::Sub,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_mul();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_unary();
        loop {
            let op = match self.peek_kind() {
                TokKind::Star => BinOp::Mul,
                TokKind::Slash => BinOp::Div,
                TokKind::Percent => BinOp::Mod,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_unary();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_unary(&mut self) -> Expr {
        if self.at(&TokKind::Minus) {
            let line = self.peek_line();
            self.advance();
            let expr = self.parse_unary();
            Expr::UnaryNeg { expr: Box::new(expr), line }
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut expr = self.parse_primary();
        loop {
            if self.at(&TokKind::LParen) {
                let line = self.peek_line();
                self.advance();
                let mut args = Vec::new();
                if !self.at(&TokKind::RParen) {
                    loop {
                        args.push(self.parse_expr());
                        if !self.at(&TokKind::Comma) { break; }
                        self.advance();
                    }
                }
                self.expect(TokKind::RParen);
                expr = Expr::Call { callee: Box::new(expr), args, line };
            } else if self.at(&TokKind::LBracket) {
                let line = self.peek_line();
                self.advance();
                let idx = self.parse_expr();
                self.expect(TokKind::RBracket);
                expr = Expr::Index { obj: Box::new(expr), idx: Box::new(idx), line };
            } else {
                break;
            }
        }
        expr
    }

    fn parse_primary(&mut self) -> Expr {
        match self.peek_kind().clone() {
            TokKind::IntLit(v) => { self.advance(); Expr::IntLit(v) }
            TokKind::StrLit(s) => { self.advance(); Expr::StrLit(s) }
            TokKind::True => { self.advance(); Expr::BoolLit(true) }
            TokKind::False => { self.advance(); Expr::BoolLit(false) }
            TokKind::Nil => { self.advance(); Expr::NilLit }
            TokKind::Ident(name) => {
                let line = self.peek_line();
                self.advance();
                Expr::Ident(name, line)
            }
            TokKind::LParen => {
                self.advance();
                let expr = self.parse_expr();
                self.expect(TokKind::RParen);
                expr
            }
            TokKind::LBracket => {
                self.advance();
                let mut elems = Vec::new();
                if !self.at(&TokKind::RBracket) {
                    loop {
                        elems.push(self.parse_expr());
                        if !self.at(&TokKind::Comma) { break; }
                        self.advance();
                    }
                }
                self.expect(TokKind::RBracket);
                Expr::ListLit(elems)
            }
            TokKind::Fn => {
                self.advance();
                self.expect(TokKind::LParen);
                let params = self.parse_params();
                self.expect(TokKind::RParen);
                let body = self.parse_block();
                Expr::FnLit { params, body }
            }
            _ => panic!("unexpected token in primary: {:?}", self.peek_kind()),
        }
    }
}

// ==================== VALUES ====================

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Rc<FnDef>),
    Nil,
}

struct FnDef {
    params: Vec<String>,
    body: Vec<Stmt>,
    captured_scope: Rc<RefCell<Scope>>,
    builtin: Option<String>,
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    fn new(parent: Option<Rc<RefCell<Scope>>>) -> Self {
        Scope { vars: HashMap::new(), parent }
    }
    fn get(&self, name: &str) -> Option<&Value> {
        if let Some(v) = self.vars.get(name) { return Some(v); }
        if let Some(ref p) = self.parent { return p.borrow().get(name); }
        None
    }
    fn set(&mut self, name: &str, val: Value) -> bool {
        if self.vars.contains_key(name) { self.vars.insert(name.to_string(), val); return true; }
        if let Some(ref p) = self.parent { return p.borrow_mut().set(name, val); }
        false
    }
}

enum ControlFlow { Normal, Break, Continue, Return(Value) }

struct RuntimeError { line: usize, message: String }
type Result<T> = std::result::Result<T, RuntimeError>;

// ==================== INTERPRETER ====================

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int",
        Value::Bool(_) => "bool",
        Value::Str(_) => "string",
        Value::List(_) => "list",
        Value::Function(_) => "function",
        Value::Nil => "nil",
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Int(i) => *i != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Function(_) => true,
        Value::Nil => false,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::List(x), Value::List(y)) => {
            let xa = x.borrow();
            let ya = y.borrow();
            if xa.len() != ya.len() { return false; }
            for (i, j) in xa.iter().zip(ya.iter()) {
                if !values_equal(i, j) { return false; }
            }
            true
        }
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

fn display(v: &Value, in_list: bool, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(i) => i.to_string(),
        Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Value::Nil => "nil".to_string(),
        Value::Str(s) => {
            if in_list {
                let mut r = String::from("\"");
                for ch in s.chars() {
                    match ch {
                        '\\' => r.push_str("\\\\"),
                        '"' => r.push_str("\\\""),
                        '\n' => r.push_str("\\n"),
                        '\t' => r.push_str("\\t"),
                        _ => r.push(ch),
                    }
                }
                r.push('"');
                r
            } else {
                s.to_string()
            }
        }
        Value::Function(_) => "<fn>".to_string(),
        Value::List(l) => {
            let ptr = Rc::as_ptr(l) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let items: Vec<String> = l.borrow().iter().map(|e| display(e, true, seen)).collect();
            seen.pop();
            format!("[{}]", items.join(", "))
        }
    }
}

fn display_top(v: &Value) -> String {
    display(v, false, &mut Vec::new())
}

fn err(line: usize, message: String) -> RuntimeError {
    RuntimeError { line, message }
}

struct Interpreter {
    global_scope: Rc<RefCell<Scope>>,
    stdout: String,
}

impl Interpreter {
    fn new() -> Self {
        let global = Rc::new(RefCell::new(Scope::new(None)));
        Interpreter { global_scope: global, stdout: String::new() }
    }

    fn setup_builtins(&mut self) {
        let builtin_names = ["print", "str", "type", "len", "push", "pop", "range", "slice"];
        for name in &builtin_names {
            let fn_def = Rc::new(FnDef {
                params: vec![],
                body: vec![],
                captured_scope: Rc::clone(&self.global_scope),
                builtin: Some(name.to_string()),
            });
            self.global_scope.borrow_mut().vars.insert(name.to_string(), Value::Function(fn_def));
        }
    }

    fn run(&mut self, stmts: &[Stmt]) {
        match self.exec_block(stmts, &self.global_scope) {
            Ok(_) => {}
            Err(e) => {
                self.stdout.push_str(&format!("error at line {}: {}\n", e.line, e.message));
            }
        }
    }

    fn exec_block(&self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        for stmt in stmts {
            let cf = self.exec_stmt(stmt, scope)?;
            if !matches!(cf, ControlFlow::Normal) { return Ok(cf); }
        }
        Ok(ControlFlow::Normal)
    }

    fn exec_block_new_scope(&self, stmts: &[Stmt], parent: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        let scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(parent)))));
        self.exec_block(stmts, &scope)
    }

    fn exec_stmt(&self, stmt: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        match stmt {
            Stmt::Let { name, expr } => {
                let val = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), val);
                Ok(ControlFlow::Normal)
            }
            Stmt::FnDecl { name, params, body } => {
                let fn_def = Rc::new(FnDef {
                    params: params.clone(),
                    body: body.clone(),
                    captured_scope: Rc::clone(scope),
                    builtin: None,
                });
                scope.borrow_mut().vars.insert(name.clone(), Value::Function(fn_def));
                Ok(ControlFlow::Normal)
            }
            Stmt::If { cond, then_body, else_body } => {
                let c = self.eval(cond, scope)?;
                if is_truthy(&c) {
                    self.exec_block_new_scope(then_body, scope)
                } else if let Some(eb) = else_body {
                    self.exec_block_new_scope(eb, scope)
                } else {
                    Ok(ControlFlow::Normal)
                }
            }
            Stmt::While { cond, body } => {
                loop {
                    let c = self.eval(cond, scope)?;
                    if !is_truthy(&c) { break; }
                    match self.exec_block_new_scope(body, scope)? {
                        ControlFlow::Break => break,
                        ControlFlow::Continue => continue,
                        ControlFlow::Return(v) => return Ok(ControlFlow::Return(v)),
                        ControlFlow::Normal => {}
                    }
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::For { var, iter, body, line } => {
                let list_val = self.eval(iter, scope)?;
                let list = match &list_val {
                    Value::List(l) => Rc::clone(l),
                    _ => return Err(err(*line, format!("cannot iterate {}", type_name(&list_val)))),
                };
                let mut i = 0usize;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let iter_scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(scope)))));
                    iter_scope.borrow_mut().vars.insert(var.clone(), elem);
                    match self.exec_block(body, &iter_scope)? {
                        ControlFlow::Break => break,
                        ControlFlow::Continue => {}
                        ControlFlow::Return(v) => return Ok(ControlFlow::Return(v)),
                        ControlFlow::Normal => {}
                    }
                    i += 1;
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::Return { expr } => {
                let val = match expr {
                    Some(e) => self.eval(e, scope)?,
                    None => Value::Nil,
                };
                Ok(ControlFlow::Return(val))
            }
            Stmt::Break => Ok(ControlFlow::Break),
            Stmt::Continue => Ok(ControlFlow::Continue),
            Stmt::Assign { name, expr, line } => {
                let val = self.eval(expr, scope)?;
                if !scope.borrow_mut().set(name, val.clone()) {
                    return Err(err(*line, format!("undefined variable {}", name)));
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::IndexAssign { obj, idx, val, line } => {
                let obj_val = self.eval(obj, scope)?;
                let idx_val = self.eval(idx, scope)?;
                let val_val = self.eval(val, scope)?;
                match &obj_val {
                    Value::List(l) => {
                        match &idx_val {
                            Value::Int(i) => {
                                let i = *i;
                                let len = l.borrow().len() as i64;
                                if i < 0 || i >= len {
                                    return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                                }
                                l.borrow_mut()[i as usize] = val_val;
                            }
                            _ => return Err(err(*line, format!("cannot index list with {}", type_name(&idx_val)))),
                        }
                    }
                    _ => return Err(err(*line, format!("cannot assign into {}", type_name(&obj_val)))),
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::ExprStmt { expr } => {
                self.eval(expr, scope)?;
                Ok(ControlFlow::Normal)
            }
        }
    }

    fn eval(&self, expr: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value> {
        match expr {
            Expr::IntLit(v) => Ok(Value::Int(*v)),
            Expr::StrLit(s) => Ok(Value::Str(Rc::new(s.clone()))),
            Expr::BoolLit(b) => Ok(Value::Bool(*b)),
            Expr::NilLit => Ok(Value::Nil),
            Expr::Ident(name, line) => {
                match scope.borrow().get(name) {
                    Some(v) => Ok(v.clone()),
                    None => Err(err(*line, format!("undefined variable {}", name))),
                }
            }
            Expr::Binary { op, left, right, line } => {
                match op {
                    BinOp::And => {
                        let l = self.eval(left, scope)?;
                        if !is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    BinOp::Or => {
                        let l = self.eval(left, scope)?;
                        if is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    _ => {
                        let l = self.eval(left, scope)?;
                        let r = self.eval(right, scope)?;
                        self.eval_binary(op, l, r, *line)
                    }
                }
            }
            Expr::UnaryNot { expr } => {
                let v = self.eval(expr, scope)?;
                Ok(Value::Bool(!is_truthy(&v)))
            }
            Expr::UnaryNeg { expr, line } => {
                let v = self.eval(expr, scope)?;
                match v {
                    Value::Int(i) => {
                        match i.checked_neg() {
                            Some(n) => Ok(Value::Int(n)),
                            None => Err(err(*line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(*line, format!("cannot apply - to {}", type_name(&v)))),
                }
            }
            Expr::Call { callee, args, line } => {
                let callee_val = self.eval(callee, scope)?;
                let mut arg_vals = Vec::with_capacity(args.len());
                for a in args {
                    arg_vals.push(self.eval(a, scope)?);
                }
                self.call(&callee_val, arg_vals, *line)
            }
            Expr::Index { obj, idx, line } => {
                let obj_val = self.eval(obj, scope)?;
                let idx_val = self.eval(idx, scope)?;
                match (&obj_val, &idx_val) {
                    (Value::List(l), Value::Int(i)) => {
                        let i = *i;
                        let len = l.borrow().len() as i64;
                        if i < 0 || i >= len {
                            return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                        }
                        Ok(l.borrow()[i as usize].clone())
                    }
                    (Value::Str(s), Value::Int(i)) => {
                        let i = *i;
                        let len = s.len() as i64;
                        if i < 0 || i >= len {
                            return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                        }
                        Ok(Value::Str(Rc::new(s[i as usize..i as usize + 1].to_string())))
                    }
                    _ => {
                        Err(err(*line, format!("cannot index {} with {}", type_name(&obj_val), type_name(&idx_val))))
                    }
                }
            }
            Expr::ListLit(elems) => {
                let mut vals = Vec::with_capacity(elems.len());
                for e in elems {
                    vals.push(self.eval(e, scope)?);
                }
                Ok(Value::List(Rc::new(RefCell::new(vals))))
            }
            Expr::FnLit { params, body } => {
                let fn_def = Rc::new(FnDef {
                    params: params.clone(),
                    body: body.clone(),
                    captured_scope: Rc::clone(scope),
                    builtin: None,
                });
                Ok(Value::Function(fn_def))
            }
        }
    }

    fn eval_binary(&self, op: &BinOp, l: Value, r: Value, line: usize) -> Result<Value> {
        match op {
            BinOp::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_add(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(Rc::new(format!("{}{}", a, b)))),
                    (Value::List(a), Value::List(b)) => {
                        let mut new_list = a.borrow().clone();
                        new_list.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => Err(err(line, format!("cannot apply + to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Sub => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_sub(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(line, format!("cannot apply - to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Mul => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_mul(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(line, format!("cannot apply * to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Div => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 {
                            return Err(err(line, "division by zero".to_string()));
                        }
                        if *a == i64::MIN && *b == -1 {
                            return Err(err(line, "integer overflow".to_string()));
                        }
                        Ok(Value::Int(a / b))
                    }
                    _ => Err(err(line, format!("cannot apply / to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Mod => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 {
                            return Err(err(line, "division by zero".to_string()));
                        }
                        if *b == -1 {
                            return Ok(Value::Int(0));
                        }
                        Ok(Value::Int(a % b))
                    }
                    _ => Err(err(line, format!("cannot apply % to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Eq => Ok(Value::Bool(values_equal(&l, &r))),
            BinOp::Neq => Ok(Value::Bool(!values_equal(&l, &r))),
            BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let res = match op {
                            BinOp::Lt => a < b,
                            BinOp::Le => a <= b,
                            BinOp::Gt => a > b,
                            BinOp::Ge => a >= b,
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op {
                            BinOp::Lt => a.as_str() < b.as_str(),
                            BinOp::Le => a.as_str() <= b.as_str(),
                            BinOp::Gt => a.as_str() > b.as_str(),
                            BinOp::Ge => a.as_str() >= b.as_str(),
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    _ => Err(err(line, format!("cannot apply {} to {} and {}",
                        match op { BinOp::Lt => "<", BinOp::Le => "<=", BinOp::Gt => ">", BinOp::Ge => ">=", _ => unreachable!() },
                        type_name(&l), type_name(&r)))),
                }
            }
            _ => unreachable!(),
        }
    }

    fn call(&self, callee: &Value, args: Vec<Value>, line: usize) -> Result<Value> {
        match callee {
            Value::Function(f) => {
                if let Some(ref bname) = f.builtin {
                    return self.call_builtin(bname, args, line);
                }
                if args.len() != f.params.len() {
                    return Err(err(line, format!("expected {} arguments, got {}", f.params.len(), args.len())));
                }
                let call_scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(&f.captured_scope)))));
                for (p, a) in f.params.iter().zip(args) {
                    call_scope.borrow_mut().vars.insert(p.clone(), a);
                }
                match self.exec_block(&f.body, &call_scope) {
                    Ok(ControlFlow::Return(v)) => Ok(v),
                    Ok(_) => Ok(Value::Nil),
                    Err(e) => Err(e),
                }
            }
            _ => Err(err(line, format!("cannot call {}", type_name(callee)))),
        }
    }

    fn call_builtin(&self, name: &str, args: Vec<Value>, line: usize) -> Result<Value> {
        let bad_arg = || Err(err(line, format!("bad argument to {}", name)));
        match name {
            "print" => {
                let parts: Vec<String> = args.iter().map(|v| display_top(v)).collect();
                self.stdout.push_str(&parts.join(" "));
                self.stdout.push('\n');
                Ok(Value::Nil)
            }
            "str" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                Ok(Value::Str(Rc::new(display_top(&args[0]))))
            }
            "type" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                Ok(Value::Str(Rc::new(type_name(&args[0]).to_string())))
            }
            "len" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => bad_arg(),
                }
            }
            "push" => {
                if args.len() != 2 { return Err(err(line, format!("expected 2 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => bad_arg(),
                }
            }
            "pop" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::List(l) => {
                        if l.borrow().is_empty() { return bad_arg(); }
                        Ok(l.borrow_mut().pop().unwrap())
                    }
                    _ => bad_arg(),
                }
            }
            "range" => {
                if args.len() != 2 { return Err(err(line, format!("expected 2 arguments, got {}", args.len()))); }
                let (a, b) = match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return bad_arg(),
                };
                let mut list = Vec::new();
                let mut i = a;
                while i < b {
                    list.push(Value::Int(i));
                    i += 1;
                }
                Ok(Value::List(Rc::new(RefCell::new(list))))
            }
            "slice" => {
                if args.len() != 3 { return Err(err(line, format!("expected 3 arguments, got {}", args.len()))); }
                let (a, b) = match (&args[1], &args[2]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return bad_arg(),
                };
                match &args[0] {
                    Value::Str(s) => {
                        let len = s.len() as i64;
                        if a < 0 || b > len || a > b { return bad_arg(); }
                        Ok(Value::Str(Rc::new(s[a as usize..b as usize].to_string())))
                    }
                    Value::List(l) => {
                        let len = l.borrow().len() as i64;
                        if a < 0 || b > len || a > b { return bad_arg(); }
                        let new_list: Vec<Value> = l.borrow()[a as usize..b as usize].to_vec();
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => bad_arg(),
                }
            }
            _ => unreachable!(),
        }
    }
}

// ==================== MAIN ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = fs::read_to_string(path).unwrap();
    let toks = tokenize(&src);
    let mut parser = Parser::new(toks);
    let program = parser.parse_program();
    let mut interp = Interpreter::new();
    interp.setup_builtins();
    interp.run(&program);
    let mut out = io::stdout();
    out.write_all(interp.stdout.as_bytes()).unwrap();
    out.flush().unwrap();
}

use std::collections::HashMap;
use std::cell::RefCell;
use std::rc::Rc;
use std::env;
use std::fs;
use std::io::{self, Write};

// ==================== TOKENS ====================

#[derive(Debug, Clone, PartialEq)]
enum TokKind {
    IntLit(i64),
    StrLit(String),
    Ident(String),
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Neq, Lt, Le, Gt, Ge, Assign,
    Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace, Comma, Semicolon,
    EOF,
}

#[derive(Debug, Clone)]
struct Tok {
    kind: TokKind,
    line: usize,
}

fn tokenize(src: &str) -> Vec<Tok> {
    let mut tokens = Vec::new();
    let bytes = src.as_bytes();
    let mut pos = 0usize;
    let mut line = 1usize;
    while pos < bytes.len() {
        let ch = bytes[pos];
        if ch == b'\n' { line += 1; pos += 1; continue; }
        if ch == b' ' || ch == b'\t' || ch == b'\r' { pos += 1; continue; }
        if ch == b'#' {
            while pos < bytes.len() && bytes[pos] != b'\n' { pos += 1; }
            continue;
        }
        if ch == b'"' {
            pos += 1;
            let mut s = String::new();
            while pos < bytes.len() && bytes[pos] != b'"' {
                if bytes[pos] == b'\\' {
                    pos += 1;
                    match bytes[pos] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        c => s.push(c as char),
                    }
                } else {
                    s.push(bytes[pos] as char);
                }
                pos += 1;
            }
            pos += 1;
            tokens.push(Tok { kind: TokKind::StrLit(s), line });
            continue;
        }
        if ch.is_ascii_digit() {
            let start = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_digit() { pos += 1; }
            let val: i64 = src[start..pos].parse().unwrap();
            tokens.push(Tok { kind: TokKind::IntLit(val), line });
            continue;
        }
        if ch.is_ascii_alphabetic() || ch == b'_' {
            let start = pos;
            while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
            let word = &src[start..pos];
            let kind = match word {
                "let" => TokKind::Let, "fn" => TokKind::Fn, "if" => TokKind::If,
                "else" => TokKind::Else, "while" => TokKind::While, "for" => TokKind::For,
                "in" => TokKind::In, "return" => TokKind::Return, "break" => TokKind::Break,
                "continue" => TokKind::Continue, "and" => TokKind::And, "or" => TokKind::Or,
                "not" => TokKind::Not, "true" => TokKind::True, "false" => TokKind::False,
                "nil" => TokKind::Nil,
                _ => TokKind::Ident(word.to_string()),
            };
            tokens.push(Tok { kind, line });
            continue;
        }
        let (kind, len) = match ch {
            b'=' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Eq, 2),
            b'!' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Neq, 2),
            b'<' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Le, 2),
            b'>' if pos + 1 < bytes.len() && bytes[pos + 1] == b'=' => (TokKind::Ge, 2),
            b'<' => (TokKind::Lt, 1),
            b'>' => (TokKind::Gt, 1),
            b'=' => (TokKind::Assign, 1),
            b'+' => (TokKind::Plus, 1),
            b'-' => (TokKind::Minus, 1),
            b'*' => (TokKind::Star, 1),
            b'/' => (TokKind::Slash, 1),
            b'%' => (TokKind::Percent, 1),
            b'(' => (TokKind::LParen, 1),
            b')' => (TokKind::RParen, 1),
            b'[' => (TokKind::LBracket, 1),
            b']' => (TokKind::RBracket, 1),
            b'{' => (TokKind::LBrace, 1),
            b'}' => (TokKind::RBrace, 1),
            b',' => (TokKind::Comma, 1),
            b';' => (TokKind::Semicolon, 1),
            _ => { pos += 1; continue; }
        };
        tokens.push(Tok { kind, line });
        pos += len;
    }
    tokens.push(Tok { kind: TokKind::EOF, line });
    tokens
}

// ==================== AST ====================

#[derive(Debug, Clone, PartialEq)]
enum BinOp { Add, Sub, Mul, Div, Mod, Eq, Neq, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64),
    StrLit(String),
    BoolLit(bool),
    NilLit,
    Ident(String, usize),
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr>, line: usize },
    UnaryNot { expr: Box<Expr> },
    UnaryNeg { expr: Box<Expr>, line: usize },
    Call { callee: Box<Expr>, args: Vec<Expr>, line: usize },
    Index { obj: Box<Expr>, idx: Box<Expr>, line: usize },
    ListLit(Vec<Expr>),
    FnLit { params: Vec<String>, body: Vec<Stmt> },
}

#[derive(Debug, Clone)]
enum Stmt {
    Let { name: String, expr: Expr },
    FnDecl { name: String, params: Vec<String>, body: Vec<Stmt> },
    If { cond: Expr, then_body: Vec<Stmt>, else_body: Option<Vec<Stmt>> },
    While { cond: Expr, body: Vec<Stmt> },
    For { var: String, iter: Expr, body: Vec<Stmt>, line: usize },
    Return { expr: Option<Expr> },
    Break,
    Continue,
    Assign { name: String, expr: Expr, line: usize },
    IndexAssign { obj: Expr, idx: Expr, val: Expr, line: usize },
    ExprStmt { expr: Expr },
}

// ==================== PARSER ====================

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn new(toks: Vec<Tok>) -> Self { Parser { toks, pos: 0 } }
    fn peek(&self) -> &Tok { &self.toks[self.pos] }
    fn peek_kind(&self) -> &TokKind { &self.toks[self.pos].kind }
    fn peek_line(&self) -> usize { self.toks[self.pos].line }
    fn advance(&mut self) -> Tok { let t = self.toks[self.pos].clone(); self.pos += 1; t }
    fn expect(&mut self, k: TokKind) -> Tok {
        let t = self.advance();
        assert_eq!(t.kind, k, "expected {:?} got {:?} at line {}", k, t.kind, t.line);
        t
    }
    fn at(&self, k: &TokKind) -> bool { self.peek_kind() == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while !self.at(&TokKind::EOF) {
            stmts.push(self.parse_stmt());
        }
        stmts
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(TokKind::LBrace);
        let mut stmts = Vec::new();
        while !self.at(&TokKind::RBrace) {
            stmts.push(self.parse_stmt());
        }
        self.expect(TokKind::RBrace);
        stmts
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut params = Vec::new();
        if !self.at(&TokKind::RParen) {
            loop {
                let t = self.advance();
                if let TokKind::Ident(name) = t.kind { params.push(name); }
                else { panic!("expected ident"); }
                if !self.at(&TokKind::Comma) { break; }
                self.advance();
            }
        }
        params
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek_kind().clone() {
            TokKind::Let => {
                self.advance();
                let name = self.expect_ident();
                self.expect(TokKind::Assign);
                let expr = self.parse_expr();
                self.expect(TokKind::Semicolon);
                Stmt::Let { name, expr }
            }
            TokKind::Fn => {
                self.advance();
                let name = self.expect_ident();
                self.expect(TokKind::LParen);
                let params = self.parse_params();
                self.expect(TokKind::RParen);
                let body = self.parse_block();
                Stmt::FnDecl { name, params, body }
            }
            TokKind::If => {
                self.advance();
                let cond = self.parse_expr();
                let then_body = self.parse_block();
                let else_body = if self.at(&TokKind::Else) {
                    self.advance();
                    if self.at(&TokKind::If) {
                        Some(vec![self.parse_stmt()])
                    } else {
                        Some(self.parse_block())
                    }
                } else { None };
                Stmt::If { cond, then_body, else_body }
            }
            TokKind::While => {
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While { cond, body }
            }
            TokKind::For => {
                let for_line = self.peek_line();
                self.advance();
                let var = self.expect_ident();
                self.expect(TokKind::In);
                let iter = self.parse_expr();
                let body = self.parse_block();
                Stmt::For { var, iter, body, line: for_line }
            }
            TokKind::Return => {
                self.advance();
                let expr = if self.at(&TokKind::Semicolon) { None } else { Some(self.parse_expr()) };
                self.expect(TokKind::Semicolon);
                Stmt::Return { expr }
            }
            TokKind::Break => { self.advance(); self.expect(TokKind::Semicolon); Stmt::Break }
            TokKind::Continue => { self.advance(); self.expect(TokKind::Semicolon); Stmt::Continue }
            TokKind::Ident(_) => {
                // Check if it's a simple assignment: IDENT = expr ;
                if self.pos + 1 < self.toks.len() && self.toks[self.pos + 1].kind == TokKind::Assign {
                    let t = self.advance();
                    let name = match t.kind { TokKind::Ident(n) => n, _ => unreachable!() };
                    let line = t.line;
                    self.expect(TokKind::Assign);
                    let expr = self.parse_expr();
                    self.expect(TokKind::Semicolon);
                    return Stmt::Assign { name, expr, line };
                }
                // Parse expression and check for index assignment
                let expr = self.parse_expr();
                if self.at(&TokKind::Assign) {
                    if let Expr::Index { obj, idx, line } = expr {
                        self.advance();
                        let val = self.parse_expr();
                        self.expect(TokKind::Semicolon);
                        return Stmt::IndexAssign { obj: *obj, idx: *idx, val, line };
                    }
                }
                self.expect(TokKind::Semicolon);
                Stmt::ExprStmt { expr }
            }
            _ => {
                let expr = self.parse_expr();
                self.expect(TokKind::Semicolon);
                Stmt::ExprStmt { expr }
            }
        }
    }

    fn expect_ident(&mut self) -> String {
        let t = self.advance();
        match t.kind { TokKind::Ident(n) => n, _ => panic!("expected ident, got {:?}", t.kind) }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        while self.at(&TokKind::Or) {
            let line = self.peek_line();
            self.advance();
            let right = self.parse_and();
            left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        while self.at(&TokKind::And) {
            let line = self.peek_line();
            self.advance();
            let right = self.parse_not();
            left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(&TokKind::Not) {
            self.advance();
            let expr = self.parse_not();
            Expr::UnaryNot { expr: Box::new(expr) }
        } else {
            self.parse_cmp()
        }
    }

    fn parse_cmp(&mut self) -> Expr {
        let mut left = self.parse_add();
        loop {
            let op = match self.peek_kind() {
                TokKind::Eq => BinOp::Eq,
                TokKind::Neq => BinOp::Neq,
                TokKind::Lt => BinOp::Lt,
                TokKind::Le => BinOp::Le,
                TokKind::Gt => BinOp::Gt,
                TokKind::Ge => BinOp::Ge,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_add();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_add(&mut self) -> Expr {
        let mut left = self.parse_mul();
        loop {
            let op = match self.peek_kind() {
                TokKind::Plus => BinOp::Add,
                TokKind::Minus => BinOp::Sub,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_mul();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_mul(&mut self) -> Expr {
        let mut left = self.parse_unary();
        loop {
            let op = match self.peek_kind() {
                TokKind::Star => BinOp::Mul,
                TokKind::Slash => BinOp::Div,
                TokKind::Percent => BinOp::Mod,
                _ => break,
            };
            let line = self.peek_line();
            self.advance();
            let right = self.parse_unary();
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), line };
        }
        left
    }

    fn parse_unary(&mut self) -> Expr {
        if self.at(&TokKind::Minus) {
            let line = self.peek_line();
            self.advance();
            let expr = self.parse_unary();
            Expr::UnaryNeg { expr: Box::new(expr), line }
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut expr = self.parse_primary();
        loop {
            if self.at(&TokKind::LParen) {
                let line = self.peek_line();
                self.advance();
                let mut args = Vec::new();
                if !self.at(&TokKind::RParen) {
                    loop {
                        args.push(self.parse_expr());
                        if !self.at(&TokKind::Comma) { break; }
                        self.advance();
                    }
                }
                self.expect(TokKind::RParen);
                expr = Expr::Call { callee: Box::new(expr), args, line };
            } else if self.at(&TokKind::LBracket) {
                let line = self.peek_line();
                self.advance();
                let idx = self.parse_expr();
                self.expect(TokKind::RBracket);
                expr = Expr::Index { obj: Box::new(expr), idx: Box::new(idx), line };
            } else {
                break;
            }
        }
        expr
    }

    fn parse_primary(&mut self) -> Expr {
        match self.peek_kind().clone() {
            TokKind::IntLit(v) => { self.advance(); Expr::IntLit(v) }
            TokKind::StrLit(s) => { self.advance(); Expr::StrLit(s) }
            TokKind::True => { self.advance(); Expr::BoolLit(true) }
            TokKind::False => { self.advance(); Expr::BoolLit(false) }
            TokKind::Nil => { self.advance(); Expr::NilLit }
            TokKind::Ident(name) => {
                let line = self.peek_line();
                self.advance();
                Expr::Ident(name, line)
            }
            TokKind::LParen => {
                self.advance();
                let expr = self.parse_expr();
                self.expect(TokKind::RParen);
                expr
            }
            TokKind::LBracket => {
                self.advance();
                let mut elems = Vec::new();
                if !self.at(&TokKind::RBracket) {
                    loop {
                        elems.push(self.parse_expr());
                        if !self.at(&TokKind::Comma) { break; }
                        self.advance();
                    }
                }
                self.expect(TokKind::RBracket);
                Expr::ListLit(elems)
            }
            TokKind::Fn => {
                self.advance();
                self.expect(TokKind::LParen);
                let params = self.parse_params();
                self.expect(TokKind::RParen);
                let body = self.parse_block();
                Expr::FnLit { params, body }
            }
            _ => panic!("unexpected token in primary: {:?}", self.peek_kind()),
        }
    }
}

// ==================== VALUES ====================

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Value>>>),
    Function(Rc<FnDef>),
    Nil,
}

struct FnDef {
    params: Vec<String>,
    body: Vec<Stmt>,
    captured_scope: Rc<RefCell<Scope>>,
    builtin: Option<String>,
}

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    fn new(parent: Option<Rc<RefCell<Scope>>>) -> Self {
        Scope { vars: HashMap::new(), parent }
    }
    fn get(&self, name: &str) -> Option<Value> {
        if let Some(v) = self.vars.get(name) { return Some(v.clone()); }
        if let Some(ref p) = self.parent { return p.borrow().get(name); }
        None
    }
    fn set(&mut self, name: &str, val: Value) -> bool {
        if self.vars.contains_key(name) { self.vars.insert(name.to_string(), val); return true; }
        if let Some(ref p) = self.parent { return p.borrow_mut().set(name, val); }
        false
    }
}

enum ControlFlow { Normal, Break, Continue, Return(Value) }

struct RuntimeError { line: usize, message: String }
type Result<T> = std::result::Result<T, RuntimeError>;

// ==================== INTERPRETER ====================

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int",
        Value::Bool(_) => "bool",
        Value::Str(_) => "string",
        Value::List(_) => "list",
        Value::Function(_) => "function",
        Value::Nil => "nil",
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Int(i) => *i != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Function(_) => true,
        Value::Nil => false,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::List(x), Value::List(y)) => {
            let xa = x.borrow();
            let ya = y.borrow();
            if xa.len() != ya.len() { return false; }
            for (i, j) in xa.iter().zip(ya.iter()) {
                if !values_equal(i, j) { return false; }
            }
            true
        }
        (Value::Function(x), Value::Function(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

fn display(v: &Value, in_list: bool, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(i) => i.to_string(),
        Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Value::Nil => "nil".to_string(),
        Value::Str(s) => {
            if in_list {
                let mut r = String::from("\"");
                for ch in s.chars() {
                    match ch {
                        '\\' => r.push_str("\\\\"),
                        '"' => r.push_str("\\\""),
                        '\n' => r.push_str("\\n"),
                        '\t' => r.push_str("\\t"),
                        _ => r.push(ch),
                    }
                }
                r.push('"');
                r
            } else {
                s.to_string()
            }
        }
        Value::Function(_) => "<fn>".to_string(),
        Value::List(l) => {
            let ptr = Rc::as_ptr(l) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let items: Vec<String> = l.borrow().iter().map(|e| display(e, true, seen)).collect();
            seen.pop();
            format!("[{}]", items.join(", "))
        }
    }
}

fn display_top(v: &Value) -> String {
    display(v, false, &mut Vec::new())
}

fn err(line: usize, message: String) -> RuntimeError {
    RuntimeError { line, message }
}

struct Interpreter {
    global_scope: Rc<RefCell<Scope>>,
    stdout: RefCell<String>,
}

impl Interpreter {
    fn new() -> Self {
        let global = Rc::new(RefCell::new(Scope::new(None)));
        Interpreter { global_scope: global, stdout: RefCell::new(String::new()) }
    }

    fn setup_builtins(&mut self) {
        let builtin_names = ["print", "str", "type", "len", "push", "pop", "range", "slice"];
        for name in &builtin_names {
            let fn_def = Rc::new(FnDef {
                params: vec![],
                body: vec![],
                captured_scope: Rc::clone(&self.global_scope),
                builtin: Some(name.to_string()),
            });
            self.global_scope.borrow_mut().vars.insert(name.to_string(), Value::Function(fn_def));
        }
    }

    fn run(&mut self, stmts: &[Stmt]) {
        match self.exec_block(stmts, &self.global_scope) {
            Ok(_) => {}
            Err(e) => {
                self.stdout.borrow_mut().push_str(&format!("error at line {}: {}\n", e.line, e.message));
            }
        }
    }

    fn exec_block(&self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        for stmt in stmts {
            let cf = self.exec_stmt(stmt, scope)?;
            if !matches!(cf, ControlFlow::Normal) { return Ok(cf); }
        }
        Ok(ControlFlow::Normal)
    }

    fn exec_block_new_scope(&self, stmts: &[Stmt], parent: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        let scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(parent)))));
        self.exec_block(stmts, &scope)
    }

    fn exec_stmt(&self, stmt: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<ControlFlow> {
        match stmt {
            Stmt::Let { name, expr } => {
                let val = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), val);
                Ok(ControlFlow::Normal)
            }
            Stmt::FnDecl { name, params, body } => {
                let fn_def = Rc::new(FnDef {
                    params: params.clone(),
                    body: body.clone(),
                    captured_scope: Rc::clone(scope),
                    builtin: None,
                });
                scope.borrow_mut().vars.insert(name.clone(), Value::Function(fn_def));
                Ok(ControlFlow::Normal)
            }
            Stmt::If { cond, then_body, else_body } => {
                let c = self.eval(cond, scope)?;
                if is_truthy(&c) {
                    self.exec_block_new_scope(then_body, scope)
                } else if let Some(eb) = else_body {
                    self.exec_block_new_scope(eb, scope)
                } else {
                    Ok(ControlFlow::Normal)
                }
            }
            Stmt::While { cond, body } => {
                loop {
                    let c = self.eval(cond, scope)?;
                    if !is_truthy(&c) { break; }
                    match self.exec_block_new_scope(body, scope)? {
                        ControlFlow::Break => break,
                        ControlFlow::Continue => continue,
                        ControlFlow::Return(v) => return Ok(ControlFlow::Return(v)),
                        ControlFlow::Normal => {}
                    }
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::For { var, iter, body, line } => {
                let list_val = self.eval(iter, scope)?;
                let list = match &list_val {
                    Value::List(l) => Rc::clone(l),
                    _ => return Err(err(*line, format!("cannot iterate {}", type_name(&list_val)))),
                };
                let mut i = 0usize;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let iter_scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(scope)))));
                    iter_scope.borrow_mut().vars.insert(var.clone(), elem);
                    match self.exec_block(body, &iter_scope)? {
                        ControlFlow::Break => break,
                        ControlFlow::Continue => {}
                        ControlFlow::Return(v) => return Ok(ControlFlow::Return(v)),
                        ControlFlow::Normal => {}
                    }
                    i += 1;
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::Return { expr } => {
                let val = match expr {
                    Some(e) => self.eval(e, scope)?,
                    None => Value::Nil,
                };
                Ok(ControlFlow::Return(val))
            }
            Stmt::Break => Ok(ControlFlow::Break),
            Stmt::Continue => Ok(ControlFlow::Continue),
            Stmt::Assign { name, expr, line } => {
                let val = self.eval(expr, scope)?;
                if !scope.borrow_mut().set(name, val.clone()) {
                    return Err(err(*line, format!("undefined variable {}", name)));
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::IndexAssign { obj, idx, val, line } => {
                let obj_val = self.eval(obj, scope)?;
                let idx_val = self.eval(idx, scope)?;
                let val_val = self.eval(val, scope)?;
                match &obj_val {
                    Value::List(l) => {
                        match &idx_val {
                            Value::Int(i) => {
                                let i = *i;
                                let len = l.borrow().len() as i64;
                                if i < 0 || i >= len {
                                    return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                                }
                                l.borrow_mut()[i as usize] = val_val;
                            }
                            _ => return Err(err(*line, format!("cannot index list with {}", type_name(&idx_val)))),
                        }
                    }
                    _ => return Err(err(*line, format!("cannot assign into {}", type_name(&obj_val)))),
                }
                Ok(ControlFlow::Normal)
            }
            Stmt::ExprStmt { expr } => {
                self.eval(expr, scope)?;
                Ok(ControlFlow::Normal)
            }
        }
    }

    fn eval(&self, expr: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value> {
        match expr {
            Expr::IntLit(v) => Ok(Value::Int(*v)),
            Expr::StrLit(s) => Ok(Value::Str(Rc::new(s.clone()))),
            Expr::BoolLit(b) => Ok(Value::Bool(*b)),
            Expr::NilLit => Ok(Value::Nil),
            Expr::Ident(name, line) => {
                match scope.borrow().get(name) {
                    Some(v) => Ok(v),
                    None => Err(err(*line, format!("undefined variable {}", name))),
                }
            }
            Expr::Binary { op, left, right, line } => {
                match op {
                    BinOp::And => {
                        let l = self.eval(left, scope)?;
                        if !is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    BinOp::Or => {
                        let l = self.eval(left, scope)?;
                        if is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    _ => {
                        let l = self.eval(left, scope)?;
                        let r = self.eval(right, scope)?;
                        self.eval_binary(op, l, r, *line)
                    }
                }
            }
            Expr::UnaryNot { expr } => {
                let v = self.eval(expr, scope)?;
                Ok(Value::Bool(!is_truthy(&v)))
            }
            Expr::UnaryNeg { expr, line } => {
                let v = self.eval(expr, scope)?;
                match v {
                    Value::Int(i) => {
                        match i.checked_neg() {
                            Some(n) => Ok(Value::Int(n)),
                            None => Err(err(*line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(*line, format!("cannot apply - to {}", type_name(&v)))),
                }
            }
            Expr::Call { callee, args, line } => {
                let callee_val = self.eval(callee, scope)?;
                let mut arg_vals = Vec::with_capacity(args.len());
                for a in args {
                    arg_vals.push(self.eval(a, scope)?);
                }
                self.call(&callee_val, arg_vals, *line)
            }
            Expr::Index { obj, idx, line } => {
                let obj_val = self.eval(obj, scope)?;
                let idx_val = self.eval(idx, scope)?;
                match (&obj_val, &idx_val) {
                    (Value::List(l), Value::Int(i)) => {
                        let i = *i;
                        let len = l.borrow().len() as i64;
                        if i < 0 || i >= len {
                            return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                        }
                        Ok(l.borrow()[i as usize].clone())
                    }
                    (Value::Str(s), Value::Int(i)) => {
                        let i = *i;
                        let len = s.len() as i64;
                        if i < 0 || i >= len {
                            return Err(err(*line, format!("index {} out of range for length {}", i, len)));
                        }
                        Ok(Value::Str(Rc::new(s[i as usize..i as usize + 1].to_string())))
                    }
                    _ => {
                        Err(err(*line, format!("cannot index {} with {}", type_name(&obj_val), type_name(&idx_val))))
                    }
                }
            }
            Expr::ListLit(elems) => {
                let mut vals = Vec::with_capacity(elems.len());
                for e in elems {
                    vals.push(self.eval(e, scope)?);
                }
                Ok(Value::List(Rc::new(RefCell::new(vals))))
            }
            Expr::FnLit { params, body } => {
                let fn_def = Rc::new(FnDef {
                    params: params.clone(),
                    body: body.clone(),
                    captured_scope: Rc::clone(scope),
                    builtin: None,
                });
                Ok(Value::Function(fn_def))
            }
        }
    }

    fn eval_binary(&self, op: &BinOp, l: Value, r: Value, line: usize) -> Result<Value> {
        match op {
            BinOp::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_add(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(Rc::new(format!("{}{}", a, b)))),
                    (Value::List(a), Value::List(b)) => {
                        let mut new_list = a.borrow().clone();
                        new_list.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => Err(err(line, format!("cannot apply + to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Sub => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_sub(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(line, format!("cannot apply - to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Mul => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        match a.checked_mul(*b) {
                            Some(v) => Ok(Value::Int(v)),
                            None => Err(err(line, "integer overflow".to_string())),
                        }
                    }
                    _ => Err(err(line, format!("cannot apply * to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Div => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 {
                            return Err(err(line, "division by zero".to_string()));
                        }
                        if *a == i64::MIN && *b == -1 {
                            return Err(err(line, "integer overflow".to_string()));
                        }
                        Ok(Value::Int(a / b))
                    }
                    _ => Err(err(line, format!("cannot apply / to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Mod => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 {
                            return Err(err(line, "division by zero".to_string()));
                        }
                        if *b == -1 {
                            return Ok(Value::Int(0));
                        }
                        Ok(Value::Int(a % b))
                    }
                    _ => Err(err(line, format!("cannot apply % to {} and {}", type_name(&l), type_name(&r)))),
                }
            }
            BinOp::Eq => Ok(Value::Bool(values_equal(&l, &r))),
            BinOp::Neq => Ok(Value::Bool(!values_equal(&l, &r))),
            BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let res = match op {
                            BinOp::Lt => a < b,
                            BinOp::Le => a <= b,
                            BinOp::Gt => a > b,
                            BinOp::Ge => a >= b,
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op {
                            BinOp::Lt => a.as_str() < b.as_str(),
                            BinOp::Le => a.as_str() <= b.as_str(),
                            BinOp::Gt => a.as_str() > b.as_str(),
                            BinOp::Ge => a.as_str() >= b.as_str(),
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    _ => Err(err(line, format!("cannot apply {} to {} and {}",
                        match op { BinOp::Lt => "<", BinOp::Le => "<=", BinOp::Gt => ">", BinOp::Ge => ">=", _ => unreachable!() },
                        type_name(&l), type_name(&r)))),
                }
            }
            _ => unreachable!(),
        }
    }

    fn call(&self, callee: &Value, args: Vec<Value>, line: usize) -> Result<Value> {
        match callee {
            Value::Function(f) => {
                if let Some(ref bname) = f.builtin {
                    return self.call_builtin(bname, args, line);
                }
                if args.len() != f.params.len() {
                    return Err(err(line, format!("expected {} arguments, got {}", f.params.len(), args.len())));
                }
                let call_scope = Rc::new(RefCell::new(Scope::new(Some(Rc::clone(&f.captured_scope)))));
                for (p, a) in f.params.iter().zip(args) {
                    call_scope.borrow_mut().vars.insert(p.clone(), a);
                }
                match self.exec_block(&f.body, &call_scope) {
                    Ok(ControlFlow::Return(v)) => Ok(v),
                    Ok(_) => Ok(Value::Nil),
                    Err(e) => Err(e),
                }
            }
            _ => Err(err(line, format!("cannot call {}", type_name(callee)))),
        }
    }

    fn call_builtin(&self, name: &str, args: Vec<Value>, line: usize) -> Result<Value> {
        let bad_arg = || Err(err(line, format!("bad argument to {}", name)));
        match name {
            "print" => {
                let parts: Vec<String> = args.iter().map(|v| display_top(v)).collect();
                self.stdout.borrow_mut().push_str(&parts.join(" "));
                self.stdout.borrow_mut().push('\n');
                Ok(Value::Nil)
            }
            "str" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                Ok(Value::Str(Rc::new(display_top(&args[0]))))
            }
            "type" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                Ok(Value::Str(Rc::new(type_name(&args[0]).to_string())))
            }
            "len" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => bad_arg(),
                }
            }
            "push" => {
                if args.len() != 2 { return Err(err(line, format!("expected 2 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => bad_arg(),
                }
            }
            "pop" => {
                if args.len() != 1 { return Err(err(line, format!("expected 1 arguments, got {}", args.len()))); }
                match &args[0] {
                    Value::List(l) => {
                        if l.borrow().is_empty() { return bad_arg(); }
                        Ok(l.borrow_mut().pop().unwrap())
                    }
                    _ => bad_arg(),
                }
            }
            "range" => {
                if args.len() != 2 { return Err(err(line, format!("expected 2 arguments, got {}", args.len()))); }
                let (a, b) = match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return bad_arg(),
                };
                let mut list = Vec::new();
                let mut i = a;
                while i < b {
                    list.push(Value::Int(i));
                    i += 1;
                }
                Ok(Value::List(Rc::new(RefCell::new(list))))
            }
            "slice" => {
                if args.len() != 3 { return Err(err(line, format!("expected 3 arguments, got {}", args.len()))); }
                let (a, b) = match (&args[1], &args[2]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return bad_arg(),
                };
                match &args[0] {
                    Value::Str(s) => {
                        let len = s.len() as i64;
                        if a < 0 || b > len || a > b { return bad_arg(); }
                        Ok(Value::Str(Rc::new(s[a as usize..b as usize].to_string())))
                    }
                    Value::List(l) => {
                        let len = l.borrow().len() as i64;
                        if a < 0 || b > len || a > b { return bad_arg(); }
                        let new_list: Vec<Value> = l.borrow()[a as usize..b as usize].to_vec();
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => bad_arg(),
                }
            }
            _ => unreachable!(),
        }
    }
}

