int main(int argc,char **argv){
    if(argc<2)return 1;
    char dir[4096];strncpy(dir,argv[1],4095);dir[4095]=0;
    char path[4200];
    snprintf(path,sizeof(path),"%s/schema.proto",dir);
    FILE *f=fopen(path,"rb");
    if(!f)return 1;
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    g_src=malloc(fsz+1);fread(g_src,1,fsz,f);fclose(f);
    g_src[fsz]=0;g_len=fsz;g_pos=0;
    parse_proto();
    resolve_types();
    snprintf(path,sizeof(path),"%s/messages.bin",dir);
    f=fopen(path,"rb");
    if(!f)return 1;
    fseek(f,0,SEEK_END);long bsz=ftell(f);fseek(f,0,SEEK_SET);
    uint8_t *bdata=malloc(bsz?bsz:1);
    fread(bdata,1,bsz,f);fclose(f);
    int bpos=0;
    MsgDef *root=&g_msgs[g_root];
    while(bpos<bsz){
        uint64_t rlen=read_varint(bdata,&bpos,bsz);
        if(bpos+(int)rlen>bsz)break;
        DecodedMsg *m=new_msg();
        decode_msg(bdata,bpos,bpos+(int)rlen,m,root);
        bpos+=(int)rlen;
        Buf out;buf_init(&out);
        print_msg_json(&out,m,root);
        fwrite(out.d,1,out.len,stdout);
        putchar('\n');
        free(out.d);
    }
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

// ============ Types ============

interface FieldDef {
  name: string;
  number: number;
  type: string;
  label: 'singular' | 'repeated' | 'optional';
  isMap: boolean;
  mapKeyType?: string;
  mapValueType?: string;
  oneofName?: string;
}

interface MessageDef {
  name: string;
  fields: Map<number, FieldDef>;
  oneofs: Map<string, number[]>;
}

interface EnumDef {
  name: string;
  values: Map<number, string>;
}

interface Schema {
  messages: Map<string, MessageDef>;
  enums: Map<string, EnumDef>;
  rootMessage: string;
}

class DecodedMessage {
  values = new Map<number, any>();
  present = new Set<number>();
  oneofState = new Map<string, number>();
}

// ============ Tokenizer ============

interface Token { type: string; value: string; }

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    if (input[i] === ' ' || input[i] === '\t' || input[i] === '\r' || input[i] === '\n') { i++; continue; }
    if (input[i] === '/' && input[i + 1] === '/') {
      i += 2;
      while (i < input.length && input[i] !== '\n') i++;
      continue;
    }
    if (input[i] === '/' && input[i + 1] === '*') {
      i += 2;
      while (i < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
      i += 2;
      continue;
    }
    if (input[i] === '"') {
      let s = '"'; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { s += input[i] + (input[i + 1] || ''); i += 2; }
        else { s += input[i]; i++; }
      }
      s += '"'; i++;
      tokens.push({ type: 'string', value: s });
      continue;
    }
    if (/[a-zA-Z_]/.test(input[i])) {
      let s = '';
      while (i < input.length && /[a-zA-Z0-9_.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'ident', value: s });
      continue;
    }
    if (/[0-9]/.test(input[i]) || (input[i] === '-' && i + 1 < input.length && /[0-9]/.test(input[i + 1]))) {
      let s = '';
      if (input[i] === '-') { s += '-'; i++; }
      while (i < input.length && /[0-9a-fA-FxX.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'number', value: s });
      continue;
    }
    tokens.push({ type: 'punct', value: input[i] });
    i++;
  }
  return tokens;
}

// ============ Proto Parser ============

class ProtoParser {
  private tokens: Token[];
  private pos: number = 0;
  private schema: Schema;
  private rootSet = false;

  constructor(input: string) {
    this.tokens = tokenize(input);
    this.schema = { messages: new Map(), enums: new Map(), rootMessage: '' };
  }

  private peek(): Token | null { return this.pos < this.tokens.length ? this.tokens[this.pos] : null; }
  private next(): Token { return this.tokens[this.pos++]; }
  private expect(v: string): void { const t = this.next(); if (t.value !== v) throw new Error(`Expected '${v}', got '${t.value}' at pos ${this.pos - 1}`); }
  private match(v: string): boolean { if (this.peek()?.value === v) { this.pos++; return true; } return false; }

  parse(): Schema {
    while (this.pos < this.tokens.length) {
      const t = this.peek();
      if (!t) break;
      if (t.value === 'syntax') this.parseSyntax();
      else if (t.value === 'package') this.parsePackage();
      else if (t.value === 'option') this.parseOption();
      else if (t.value === 'message') this.parseMessage();
      else if (t.value === 'enum') this.parseEnum();
      else this.pos++;
    }
    return this.schema;
  }

  private parseSyntax(): void { this.expect('syntax'); this.expect('='); this.next(); this.match(';'); }
  private parsePackage(): void { this.expect('package'); this.next(); this.match(';'); }
  private parseOption(): void { this.expect('option'); while (this.pos < this.tokens.length && this.peek()?.value !== ';') this.pos++; this.match(';'); }

  private parseMessage(): void {
    this.expect('message');
    const name = this.next().value;
    if (!this.rootSet) { this.schema.rootMessage = name; this.rootSet = true; }
    this.expect('{');
    const msgDef: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'message') { this.parseMessage(); continue; }
      if (t.value === 'enum') { this.parseEnum(); continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      if (t.value === 'reserved') { this.parseReserved(); continue; }
      if (t.value === 'oneof') { this.parseOneof(msgDef); continue; }
      this.parseField(msgDef);
    }
    this.schema.messages.set(name, msgDef);
  }

  private parseReserved(): void {
    this.expect('reserved');
    while (this.pos < this.tokens.length && this.peek()?.value !== ';') this.pos++;
    this.match(';');
  }

  private parseOneof(msgDef: MessageDef): void {
    this.expect('oneof');
    const name = this.next().value;
    this.expect('{');
    const fieldNums: number[] = [];
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      const type = this.next().value;
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type, label: 'singular', isMap: false, oneofName: name });
      fieldNums.push(fieldNum);
    }
    msgDef.oneofs.set(name, fieldNums);
  }

  private parseField(msgDef: MessageDef): void {
    let label: 'singular' | 'repeated' | 'optional' = 'singular';
    const t = this.peek();
    if (t?.value === 'repeated') { label = 'repeated'; this.pos++; }
    else if (t?.value === 'optional') { label = 'optional'; this.pos++; }

    if (this.peek()?.value === 'map') {
      this.pos++;
      this.expect('<');
      const keyType = this.next().value;
      this.expect(',');
      const valueType = this.next().value;
      this.expect('>');
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type: '', label: 'repeated', isMap: true, mapKeyType: keyType, mapValueType: valueType });
    } else {
      const type = this.next().value;
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type, label, isMap: false });
    }
  }

  private parseFieldOptions(): void {
    if (this.peek()?.value === '[') {
      this.pos++;
      let depth = 1;
      while (this.pos < this.tokens.length && depth > 0) {
        const t = this.next();
        if (t.value === '[') depth++;
        else if (t.value === ']') depth--;
      }
    }
  }

  private parseEnum(): void {
    this.expect('enum');
    const name = this.next().value;
    this.expect('{');
    const enumDef: EnumDef = { name, values: new Map() };
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      if (t.value === 'reserved') { this.parseReserved(); continue; }
      const valueName = this.next().value;
      this.expect('=');
      const valueNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      enumDef.values.set(valueNum, valueName);
    }
    this.schema.enums.set(name, enumDef);
  }
}

// ============ Binary Reader ============

class BinaryReader {
  private buf: Buffer;
  private pos: number;
  private end: number;

  constructor(buf: Buffer, start?: number, end?: number) {
    this.buf = buf;
    this.pos = start ?? 0;
    this.end = end ?? buf.length;
  }

  atEnd(): boolean { return this.pos >= this.end; }

  readVarint(): bigint {
    let result = 0n;
    let shift = 0n;
    for (let i = 0; i < 10; i++) {
      const byte = this.buf[this.pos++];
      result |= BigInt(byte & 0x7F) << shift;
      if ((byte & 0x80) === 0) break;
      shift += 7n;
    }
    return result;
  }

  readFixed32(): number { const v = this.buf.readUInt32LE(this.pos); this.pos += 4; return v; }
  readSFixed32(): number { const v = this.buf.readInt32LE(this.pos); this.pos += 4; return v; }
  readFixed64(): bigint { const v = this.buf.readBigUInt64LE(this.pos); this.pos += 8; return v; }
  readSFixed64(): bigint { const v = this.buf.readBigInt64LE(this.pos); this.pos += 8; return v; }

  readBytes(): Buffer {
    const len = Number(this.readVarint());
    const r = this.buf.subarray(this.pos, this.pos + len);
    this.pos += len;
    return r;
  }

  skipField(wireType: number, fieldNum: number): void {
    switch (wireType) {
      case 0: this.readVarint(); break;
      case 1: this.pos += 8; break;
      case 2: { const len = Number(this.readVarint()); this.pos += len; break; }
      case 5: this.pos += 4; break;
      case 3: {
        while (!this.atEnd()) {
          const key = this.readVarint();
          const fn = Number(key >> 3n);
          const wt = Number(key & 7n);
          if (wt === 4 && fn === fieldNum) break;
          this.skipField(wt, fn);
        }
        break;
      }
      case 4: break;
      default: throw new Error(`Unknown wire type ${wireType}`);
    }
  }
}

// ============ Scalar Reading ============

function varintToInt32(v: bigint): number {
  const low = Number(v & 0xFFFFFFFFn);
  return low >= 0x80000000 ? low - 0x100000000 : low;
}

function varintToInt64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  return v >= 0x8000000000000000n ? v - 0x10000000000000000n : v;
}

function zigzag32(v: bigint): number {
  const n = Number(v & 0xFFFFFFFFn);
  return (n >>> 1) ^ (-(n & 1));
}

function zigzag64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  return (v >> 1n) ^ -(v & 1n);
}

function readScalarValue(reader: BinaryReader, type: string, schema: Schema): any {
  switch (type) {
    case 'int32': return varintToInt32(reader.readVarint());
    case 'int64': return varintToInt64(reader.readVarint());
    case 'uint32': return Number(reader.readVarint() & 0xFFFFFFFFn);
    case 'uint64': return reader.readVarint() & 0xFFFFFFFFFFFFFFFFn;
    case 'sint32': return zigzag32(reader.readVarint());
    case 'sint64': return zigzag64(reader.readVarint());
    case 'bool': return reader.readVarint() !== 0n;
    case 'string': return reader.readBytes().toString('utf8');
    case 'bytes': return reader.readBytes();
    case 'fixed32': return reader.readFixed32();
    case 'fixed64': return reader.readFixed64();
    case 'sfixed32': return reader.readSFixed32();
    case 'sfixed64': return reader.readSFixed64();
    default:
      if (schema.enums.has(type)) return varintToInt32(reader.readVarint());
      throw new Error(`Unknown scalar type: ${type}`);
  }
}

function isPackable(type: string, schema: Schema): boolean {
  if (type === 'string' || type === 'bytes') return false;
  if (schema.messages.has(type)) return false;
  return true;
}

// ============ Message Decoding ============

function decodeMessage(reader: BinaryReader, msgDef: MessageDef, schema: Schema): DecodedMessage {
  const msg = new DecodedMessage();
  while (!reader.atEnd()) {
    const key = reader.readVarint();
    const fieldNum = Number(key >> 3n);
    const wireType = Number(key & 7n);
    const fieldDef = msgDef.fields.get(fieldNum);
    if (!fieldDef) { reader.skipField(wireType, fieldNum); continue; }

    if (fieldDef.isMap) {
      const entryBytes = reader.readBytes();
      const entryReader = new BinaryReader(entryBytes);
      const [k, v] = decodeMapEntry(entryReader, fieldDef, schema);
      let map = msg.values.get(fieldNum) as Map<any, any> | undefined;
      if (!map) { map = new Map(); msg.values.set(fieldNum, map); }
      map.set(k, v);
      msg.present.add(fieldNum);
    } else if (fieldDef.label === 'repeated') {
      let arr = msg.values.get(fieldNum) as any[] | undefined;
      if (!arr) { arr = []; msg.values.set(fieldNum, arr); }
      if (isPackable(fieldDef.type, schema) && wireType === 2) {
        const payload = reader.readBytes();
        const pr = new BinaryReader(payload);
        while (!pr.atEnd()) { arr.push(readScalarValue(pr, fieldDef.type, schema)); }
      } else {
        arr.push(readScalarValue(reader, fieldDef.type, schema));
      }
      msg.present.add(fieldNum);
    } else if (schema.messages.has(fieldDef.type)) {
      const subBytes = reader.readBytes();
      const subReader = new BinaryReader(subBytes);
      const subDef = schema.messages.get(fieldDef.type)!;
      const subMsg = decodeMessage(subReader, subDef, schema);
      if (fieldDef.oneofName) {
        const cur = msg.oneofState.get(fieldDef.oneofName);
        if (cur !== undefined && cur !== fieldNum) { msg.values.delete(cur); msg.present.delete(cur); }
        msg.oneofState.set(fieldDef.oneofName, fieldNum);
      }
      if (msg.present.has(fieldNum)) {
        mergeMessages(msg.values.get(fieldNum) as DecodedMessage, subMsg, subDef, schema);
      } else {
        msg.values.set(fieldNum, subMsg);
        msg.present.add(fieldNum);
      }
    } else {
      const value = readScalarValue(reader, fieldDef.type, schema);
      if (fieldDef.oneofName) {
        const cur = msg.oneofState.get(fieldDef.oneofName);
        if (cur !== undefined && cur !== fieldNum) { msg.values.delete(cur); msg.present.delete(cur); }
        msg.oneofState.set(fieldDef.oneofName, fieldNum);
      }
      msg.values.set(fieldNum, value);
      msg.present.add(fieldNum);
    }
  }
  return msg;
}

function decodeMapEntry(reader: BinaryReader, fieldDef: FieldDef, schema: Schema): [any, any] {
  let key: any;
  let value: any;
  const kt = fieldDef.mapKeyType!;
  const vt = fieldDef.mapValueType!;

  if (kt === 'string') key = ''; else key = 0;
  if (vt === 'string') value = '';
  else if (vt === 'bytes') value = Buffer.alloc(0);
  else if (schema.messages.has(vt)) value = new DecodedMessage();
  else if (schema.enums.has(vt)) value = 0;
  else if (vt === 'bool') value = false;
  else if (vt === 'int64' || vt === 'uint64' || vt === 'sint64' || vt === 'fixed64' || vt === 'sfixed64') value = 0n;
  else value = 0;

  while (!reader.atEnd()) {
    const k = reader.readVarint();
    const fn = Number(k >> 3n);
    const wt = Number(k & 7n);
    if (fn === 1) {
      key = readScalarValue(reader, kt, schema);
    } else if (fn === 2) {
      if (schema.messages.has(vt)) {
        const subBytes = reader.readBytes();
        const subReader = new BinaryReader(subBytes);
        value = decodeMessage(subReader, schema.messages.get(vt)!, schema);
      } else {
        value = readScalarValue(reader, vt, schema);
      }
    } else {
      reader.skipField(wt, fn);
    }
  }
  return [key, value];
}

function mergeMessages(target: DecodedMessage, source: DecodedMessage, msgDef: MessageDef, schema: Schema): void {
  for (const [oneofName, fieldNum] of source.oneofState) {
    const cur = target.oneofState.get(oneofName);
    if (cur !== undefined && cur !== fieldNum) { target.values.delete(cur); target.present.delete(cur); }
    target.oneofState.set(oneofName, fieldNum);
  }
  for (const [fieldNum, sv] of source.values) {
    const fd = msgDef.fields.get(fieldNum);
    if (!fd) continue;
    if (fd.isMap) {
      let map = target.values.get(fieldNum) as Map<any, any> | undefined;
      if (!map) { map = new Map(); target.values.set(fieldNum, map); }
      for (const [k, v] of sv as Map<any, any>) map.set(k, v);
      target.present.add(fieldNum);
    } else if (fd.label === 'repeated') {
      let arr = target.values.get(fieldNum) as any[] | undefined;
      if (!arr) { arr = []; target.values.set(fieldNum, arr); }
      for (const item of sv as any[]) arr.push(item);
      target.present.add(fieldNum);
    } else if (schema.messages.has(fd.type)) {
      if (target.present.has(fieldNum)) {
        mergeMessages(target.values.get(fieldNum) as DecodedMessage, sv as DecodedMessage, schema.messages.get(fd.type)!, schema);
      } else {
        target.values.set(fieldNum, sv);
        target.present.add(fieldNum);
      }
    } else {
      target.values.set(fieldNum, sv);
      target.present.add(fieldNum);
    }
  }
}

// ============ JSON Output ============

function toCamelCase(name: string): string {
  let result = '';
  let upperNext = false;
  for (const ch of name) {
    if (ch === '_') { upperNext = true; }
    else {
      if (upperNext && ch >= 'a' && ch <= 'z') result += ch.toUpperCase();
      else result += ch;
      upperNext = false;
    }
  }
  return result;
}

function escapeJson(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === '"') r += '\\"';
    else if (ch === '\\') r += '\\\\';
    else if (code === 8) r += '\\b';
    else if (code === 9) r += '\\t';
    else if (code === 10) r += '\\n';
    else if (code === 12) r += '\\f';
    else if (code === 13) r += '\\r';
    else if (code < 32) r += '\\u' + code.toString(16).padStart(4, '0');
    else r += ch;
  }
  return r + '"';
}

function isDefaultScalar(value: any, type: string, schema: Schema): boolean {
  switch (type) {
    case 'int32': case 'uint32': case 'sint32': case 'fixed32': case 'sfixed32': return value === 0;
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return value === 0n;
    case 'bool': return value === false;
    case 'string': return value === '';
    case 'bytes': return (value as Buffer).length === 0;
    default:
      if (schema.enums.has(type)) return value === 0;
      return false;
  }
}

function is64BitType(type: string): boolean {
  return type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64';
}

function valueToJson(value: any, type: string, schema: Schema): string {
  if (schema.messages.has(type)) {
    return messageToJson(value as DecodedMessage, schema.messages.get(type)!, schema);
  }
  switch (type) {
    case 'int32': case 'uint32': case 'sint32': case 'fixed32': case 'sfixed32': return String(value);
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return `"${(value as bigint).toString()}"`;
    case 'bool': return value ? 'true' : 'false';
    case 'string': return escapeJson(value as string);
    case 'bytes': return `"${(value as Buffer).toString('base64')}"`;
    default:
      if (schema.enums.has(type)) {
        const enumDef = schema.enums.get(type)!;
        const name = enumDef.values.get(value as number);
        if (name !== undefined) return `"${name}"`;
        return String(value);
      }
      throw new Error(`Unknown type for JSON: ${type}`);
  }
}

function mapToJson(map: Map<any, any>, fieldDef: FieldDef, schema: Schema): string {
  const entries: { keyStr: string; json: string; sortKey: any }[] = [];
  const kt = fieldDef.mapKeyType!;
  const vt = fieldDef.mapValueType!;

  for (const [k, v] of map) {
    const keyStr = kt === 'int32' ? String(k) : String(k);
    const jsonKey = escapeJson(keyStr);
    const jsonVal = valueToJson(v, vt, schema);
    entries.push({ keyStr, json: `${jsonKey}:${jsonVal}`, sortKey: kt === 'int32' ? (k as number) : Buffer.from(keyStr, 'utf8') });
  }

  if (kt === 'int32') {
    entries.sort((a, b) => (a.sortKey as number) - (b.sortKey as number));
  } else {
    entries.sort((a, b) => (a.sortKey as Buffer).compare(b.sortKey as Buffer));
  }

  return '{' + entries.map(e => e.json).join(',') + '}';
}

function messageToJson(msg: DecodedMessage, msgDef: MessageDef, schema: Schema): string {
  const parts: string[] = [];
  const sortedFields = [...msgDef.fields.values()].sort((a, b) => a.number - b.number);

  for (const fd of sortedFields) {
    if (!msg.present.has(fd.number)) continue;
    const value = msg.values.get(fd.number);

    if (fd.isMap) {
      if (!(value instanceof Map) || (value as Map<any, any>).size === 0) continue;
    } else if (fd.label === 'repeated') {
      if (!Array.isArray(value) || (value as any[]).length === 0) continue;
    } else if (schema.messages.has(fd.type)) {
      // always print if present
    } else if (fd.oneofName || fd.label === 'optional') {
      // always print if present
    } else {
      if (isDefaultScalar(value, fd.type, schema)) continue;
    }

    const jsonName = escapeJson(toCamelCase(fd.name));
    let jsonVal: string;
    if (fd.isMap) {
      jsonVal = mapToJson(value as Map<any, any>, fd, schema);
    } else if (fd.label === 'repeated') {
      const arr = value as any[];
      jsonVal = '[' + arr.map(el => valueToJson(el, fd.type, schema)).join(',') + ']';
    } else {
      jsonVal = valueToJson(value, fd.type, schema);
    }
    parts.push(`${jsonName}:${jsonVal}`);
  }
  return '{' + parts.join(',') + '}';
}

// ============ Main ============

function main(): void {
  const dir = process.argv[2];
  const protoContent = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf8');
  const binContent = fs.readFileSync(path.join(dir, 'messages.bin'));

  const parser = new ProtoParser(protoContent);
  const schema = parser.parse();

  const rootDef = schema.messages.get(schema.rootMessage)!;

  let pos = 0;
  const lines: string[] = [];

  while (pos < binContent.length) {
    // Read varint length
    let len = 0;
    let shift = 0;
    for (let i = 0; i < 10 && pos < binContent.length; i++) {
      const byte = binContent[pos++];
      len |= (byte & 0x7F) << shift;
      if ((byte & 0x80) === 0) break;
      shift += 7;
    }
    const msgBytes = binContent.subarray(pos, pos + len);
    pos += len;

    const reader = new BinaryReader(msgBytes);
    const decoded = decodeMessage(reader, rootDef, schema);
    lines.push(messageToJson(decoded, rootDef, schema));
  }

  process.stdout.write(lines.join('\n') + (lines.length > 0 ? '\n' : ''));
}

main();

import * as fs from 'fs';
import * as path from 'path';

// ============ Types ============

interface FieldDef {
  name: string;
  number: number;
  type: string;
  label: 'singular' | 'repeated' | 'optional';
  isMap: boolean;
  mapKeyType?: string;
  mapValueType?: string;
  oneofName?: string;
}

interface MessageDef {
  name: string;
  fields: Map<number, FieldDef>;
  oneofs: Map<string, number[]>;
}

interface EnumDef {
  name: string;
  values: Map<number, string>;
}

interface Schema {
  messages: Map<string, MessageDef>;
  enums: Map<string, EnumDef>;
  rootMessage: string;
}

class DecodedMessage {
  values = new Map<number, any>();
  present = new Set<number>();
  oneofState = new Map<string, number>();
}

// ============ Tokenizer ============

interface Token { type: string; value: string; }

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    if (input[i] === ' ' || input[i] === '\t' || input[i] === '\r' || input[i] === '\n') { i++; continue; }
    if (input[i] === '/' && input[i + 1] === '/') {
      i += 2;
      while (i < input.length && input[i] !== '\n') i++;
      continue;
    }
    if (input[i] === '/' && input[i + 1] === '*') {
      i += 2;
      while (i < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
      i += 2;
      continue;
    }
    if (input[i] === '"') {
      let s = '"'; i++;
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') { s += input[i] + (input[i + 1] || ''); i += 2; }
        else { s += input[i]; i++; }
      }
      s += '"'; i++;
      tokens.push({ type: 'string', value: s });
      continue;
    }
    if (/[a-zA-Z_]/.test(input[i])) {
      let s = '';
      while (i < input.length && /[a-zA-Z0-9_.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'ident', value: s });
      continue;
    }
    if (/[0-9]/.test(input[i]) || (input[i] === '-' && i + 1 < input.length && /[0-9]/.test(input[i + 1]))) {
      let s = '';
      if (input[i] === '-') { s += '-'; i++; }
      while (i < input.length && /[0-9a-fA-FxX.]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'number', value: s });
      continue;
    }
    tokens.push({ type: 'punct', value: input[i] });
    i++;
  }
  return tokens;
}

// ============ Proto Parser ============

class ProtoParser {
  private tokens: Token[];
  private pos: number = 0;
  private schema: Schema;
  private rootSet = false;

  constructor(input: string) {
    this.tokens = tokenize(input);
    this.schema = { messages: new Map(), enums: new Map(), rootMessage: '' };
  }

  private peek(): Token | null { return this.pos < this.tokens.length ? this.tokens[this.pos] : null; }
  private next(): Token { return this.tokens[this.pos++]; }
  private expect(v: string): void { const t = this.next(); if (t.value !== v) throw new Error(`Expected '${v}', got '${t.value}' at pos ${this.pos - 1}`); }
  private match(v: string): boolean { if (this.peek()?.value === v) { this.pos++; return true; } return false; }

  parse(): Schema {
    while (this.pos < this.tokens.length) {
      const t = this.peek();
      if (!t) break;
      if (t.value === 'syntax') this.parseSyntax();
      else if (t.value === 'package') this.parsePackage();
      else if (t.value === 'option') this.parseOption();
      else if (t.value === 'message') this.parseMessage();
      else if (t.value === 'enum') this.parseEnum();
      else this.pos++;
    }
    return this.schema;
  }

  private parseSyntax(): void { this.expect('syntax'); this.expect('='); this.next(); this.match(';'); }
  private parsePackage(): void { this.expect('package'); this.next(); this.match(';'); }
  private parseOption(): void { this.expect('option'); while (this.pos < this.tokens.length && this.peek()?.value !== ';') this.pos++; this.match(';'); }

  private parseMessage(): void {
    this.expect('message');
    const name = this.next().value;
    if (!this.rootSet) { this.schema.rootMessage = name; this.rootSet = true; }
    this.expect('{');
    const msgDef: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'message') { this.parseMessage(); continue; }
      if (t.value === 'enum') { this.parseEnum(); continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      if (t.value === 'reserved') { this.parseReserved(); continue; }
      if (t.value === 'oneof') { this.parseOneof(msgDef); continue; }
      this.parseField(msgDef);
    }
    this.schema.messages.set(name, msgDef);
  }

  private parseReserved(): void {
    this.expect('reserved');
    while (this.pos < this.tokens.length && this.peek()?.value !== ';') this.pos++;
    this.match(';');
  }

  private parseOneof(msgDef: MessageDef): void {
    this.expect('oneof');
    const name = this.next().value;
    this.expect('{');
    const fieldNums: number[] = [];
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      const type = this.next().value;
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type, label: 'singular', isMap: false, oneofName: name });
      fieldNums.push(fieldNum);
    }
    msgDef.oneofs.set(name, fieldNums);
  }

  private parseField(msgDef: MessageDef): void {
    let label: 'singular' | 'repeated' | 'optional' = 'singular';
    const t = this.peek();
    if (t?.value === 'repeated') { label = 'repeated'; this.pos++; }
    else if (t?.value === 'optional') { label = 'optional'; this.pos++; }

    if (this.peek()?.value === 'map') {
      this.pos++;
      this.expect('<');
      const keyType = this.next().value;
      this.expect(',');
      const valueType = this.next().value;
      this.expect('>');
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type: '', label: 'repeated', isMap: true, mapKeyType: keyType, mapValueType: valueType });
    } else {
      const type = this.next().value;
      const fieldName = this.next().value;
      this.expect('=');
      const fieldNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      msgDef.fields.set(fieldNum, { name: fieldName, number: fieldNum, type, label, isMap: false });
    }
  }

  private parseFieldOptions(): void {
    if (this.peek()?.value === '[') {
      this.pos++;
      let depth = 1;
      while (this.pos < this.tokens.length && depth > 0) {
        const t = this.next();
        if (t.value === '[') depth++;
        else if (t.value === ']') depth--;
      }
    }
  }

  private parseEnum(): void {
    this.expect('enum');
    const name = this.next().value;
    this.expect('{');
    const enumDef: EnumDef = { name, values: new Map() };
    while (true) {
      const t = this.peek();
      if (!t) break;
      if (t.value === '}') { this.pos++; break; }
      if (t.value === ';') { this.pos++; continue; }
      if (t.value === 'option') { this.parseOption(); continue; }
      if (t.value === 'reserved') { this.parseReserved(); continue; }
      const valueName = this.next().value;
      this.expect('=');
      const valueNum = parseInt(this.next().value);
      this.parseFieldOptions();
      this.match(';');
      enumDef.values.set(valueNum, valueName);
    }
    this.schema.enums.set(name, enumDef);
  }
}

// ============ Binary Reader ============

class BinaryReader {
  private buf: Buffer;
  private pos: number;
  private end: number;

  constructor(buf: Buffer, start?: number, end?: number) {
    this.buf = buf;
    this.pos = start ?? 0;
    this.end = end ?? buf.length;
  }

  atEnd(): boolean { return this.pos >= this.end; }

  readVarint(): bigint {
    let result = 0n;
    let shift = 0n;
    for (let i = 0; i < 10; i++) {
      const byte = this.buf[this.pos++];
      result |= BigInt(byte & 0x7F) << shift;
      if ((byte & 0x80) === 0) break;
      shift += 7n;
    }
    return result;
  }

  readFixed32(): number { const v = this.buf.readUInt32LE(this.pos); this.pos += 4; return v; }
  readSFixed32(): number { const v = this.buf.readInt32LE(this.pos); this.pos += 4; return v; }
  readFixed64(): bigint { const v = this.buf.readBigUInt64LE(this.pos); this.pos += 8; return v; }
  readSFixed64(): bigint { const v = this.buf.readBigInt64LE(this.pos); this.pos += 8; return v; }

  readBytes(): Buffer {
    const len = Number(this.readVarint());
    const r = this.buf.subarray(this.pos, this.pos + len);
    this.pos += len;
    return r;
  }

  skipField(wireType: number, fieldNum: number): void {
    switch (wireType) {
      case 0: this.readVarint(); break;
      case 1: this.pos += 8; break;
      case 2: { const len = Number(this.readVarint()); this.pos += len; break; }
      case 5: this.pos += 4; break;
      case 3: {
        while (!this.atEnd()) {
          const key = this.readVarint();
          const fn = Number(key >> 3n);
          const wt = Number(key & 7n);
          if (wt === 4 && fn === fieldNum) break;
          this.skipField(wt, fn);
        }
        break;
      }
      case 4: break;
      default: throw new Error(`Unknown wire type ${wireType}`);
    }
  }
}

// ============ Scalar Reading ============

function varintToInt32(v: bigint): number {
  const low = Number(v & 0xFFFFFFFFn);
  return low >= 0x80000000 ? low - 0x100000000 : low;
}

function varintToInt64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  return v >= 0x8000000000000000n ? v - 0x10000000000000000n : v;
}

function zigzag32(v: bigint): number {
  const n = Number(v & 0xFFFFFFFFn);
  return (n >>> 1) ^ (-(n & 1));
}

function zigzag64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  return (v >> 1n) ^ -(v & 1n);
}

function readScalarValue(reader: BinaryReader, type: string, schema: Schema): any {
  switch (type) {
    case 'int32': return varintToInt32(reader.readVarint());
    case 'int64': return varintToInt64(reader.readVarint());
    case 'uint32': return Number(reader.readVarint() & 0xFFFFFFFFn);
    case 'uint64': return reader.readVarint() & 0xFFFFFFFFFFFFFFFFn;
    case 'sint32': return zigzag32(reader.readVarint());
    case 'sint64': return zigzag64(reader.readVarint());
    case 'bool': return reader.readVarint() !== 0n;
    case 'string': return reader.readBytes().toString('utf8');
    case 'bytes': return reader.readBytes();
    case 'fixed32': return reader.readFixed32();
    case 'fixed64': return reader.readFixed64();
    case 'sfixed32': return reader.readSFixed32();
    case 'sfixed64': return reader.readSFixed64();
    default:
      if (schema.enums.has(type)) return varintToInt32(reader.readVarint());
      throw new Error(`Unknown scalar type: ${type}`);
  }
}

function isPackable(type: string, schema: Schema): boolean {
  if (type === 'string' || type === 'bytes') return false;
  if (schema.messages.has(type)) return false;
  return true;
}

// ============ Message Decoding ============

function decodeMessage(reader: BinaryReader, msgDef: MessageDef, schema: Schema): DecodedMessage {
  const msg = new DecodedMessage();
  while (!reader.atEnd()) {
    const key = reader.readVarint();
    const fieldNum = Number(key >> 3n);
    const wireType = Number(key & 7n);
    const fieldDef = msgDef.fields.get(fieldNum);
    if (!fieldDef) { reader.skipField(wireType, fieldNum); continue; }

    if (fieldDef.isMap) {
      const entryBytes = reader.readBytes();
      const entryReader = new BinaryReader(entryBytes);
      const [k, v] = decodeMapEntry(entryReader, fieldDef, schema);
      let map = msg.values.get(fieldNum) as Map<any, any> | undefined;
      if (!map) { map = new Map(); msg.values.set(fieldNum, map); }
      map.set(k, v);
      msg.present.add(fieldNum);
    } else if (fieldDef.label === 'repeated') {
      let arr = msg.values.get(fieldNum) as any[] | undefined;
      if (!arr) { arr = []; msg.values.set(fieldNum, arr); }
      if (isPackable(fieldDef.type, schema) && wireType === 2) {
        const payload = reader.readBytes();
        const pr = new BinaryReader(payload);
        while (!pr.atEnd()) { arr.push(readScalarValue(pr, fieldDef.type, schema)); }
      } else if (schema.messages.has(fieldDef.type)) {
        const subBytes = reader.readBytes();
        const subReader = new BinaryReader(subBytes);
        const subDef = schema.messages.get(fieldDef.type)!;
        arr.push(decodeMessage(subReader, subDef, schema));
      } else {
        arr.push(readScalarValue(reader, fieldDef.type, schema));
      }
      msg.present.add(fieldNum);
    } else if (schema.messages.has(fieldDef.type)) {
      const subBytes = reader.readBytes();
      const subReader = new BinaryReader(subBytes);
      const subDef = schema.messages.get(fieldDef.type)!;
      const subMsg = decodeMessage(subReader, subDef, schema);
      if (fieldDef.oneofName) {
        const cur = msg.oneofState.get(fieldDef.oneofName);
        if (cur !== undefined && cur !== fieldNum) { msg.values.delete(cur); msg.present.delete(cur); }
        msg.oneofState.set(fieldDef.oneofName, fieldNum);
      }
      if (msg.present.has(fieldNum)) {
        mergeMessages(msg.values.get(fieldNum) as DecodedMessage, subMsg, subDef, schema);
      } else {
        msg.values.set(fieldNum, subMsg);
        msg.present.add(fieldNum);
      }
    } else {
      const value = readScalarValue(reader, fieldDef.type, schema);
      if (fieldDef.oneofName) {
        const cur = msg.oneofState.get(fieldDef.oneofName);
        if (cur !== undefined && cur !== fieldNum) { msg.values.delete(cur); msg.present.delete(cur); }
        msg.oneofState.set(fieldDef.oneofName, fieldNum);
      }
      msg.values.set(fieldNum, value);
      msg.present.add(fieldNum);
    }
  }
  return msg;
}

function decodeMapEntry(reader: BinaryReader, fieldDef: FieldDef, schema: Schema): [any, any] {
  let key: any;
  let value: any;
  const kt = fieldDef.mapKeyType!;
  const vt = fieldDef.mapValueType!;

  if (kt === 'string') key = ''; else key = 0;
  if (vt === 'string') value = '';
  else if (vt === 'bytes') value = Buffer.alloc(0);
  else if (schema.messages.has(vt)) value = new DecodedMessage();
  else if (schema.enums.has(vt)) value = 0;
  else if (vt === 'bool') value = false;
  else if (vt === 'int64' || vt === 'uint64' || vt === 'sint64' || vt === 'fixed64' || vt === 'sfixed64') value = 0n;
  else value = 0;

  while (!reader.atEnd()) {
    const k = reader.readVarint();
    const fn = Number(k >> 3n);
    const wt = Number(k & 7n);
    if (fn === 1) {
      key = readScalarValue(reader, kt, schema);
    } else if (fn === 2) {
      if (schema.messages.has(vt)) {
        const subBytes = reader.readBytes();
        const subReader = new BinaryReader(subBytes);
        value = decodeMessage(subReader, schema.messages.get(vt)!, schema);
      } else {
        value = readScalarValue(reader, vt, schema);
      }
    } else {
      reader.skipField(wt, fn);
    }
  }
  return [key, value];
}

function mergeMessages(target: DecodedMessage, source: DecodedMessage, msgDef: MessageDef, schema: Schema): void {
  for (const [oneofName, fieldNum] of source.oneofState) {
    const cur = target.oneofState.get(oneofName);
    if (cur !== undefined && cur !== fieldNum) { target.values.delete(cur); target.present.delete(cur); }
    target.oneofState.set(oneofName, fieldNum);
  }
  for (const [fieldNum, sv] of source.values) {
    const fd = msgDef.fields.get(fieldNum);
    if (!fd) continue;
    if (fd.isMap) {
      let map = target.values.get(fieldNum) as Map<any, any> | undefined;
      if (!map) { map = new Map(); target.values.set(fieldNum, map); }
      for (const [k, v] of sv as Map<any, any>) map.set(k, v);
      target.present.add(fieldNum);
    } else if (fd.label === 'repeated') {
      let arr = target.values.get(fieldNum) as any[] | undefined;
      if (!arr) { arr = []; target.values.set(fieldNum, arr); }
      for (const item of sv as any[]) arr.push(item);
      target.present.add(fieldNum);
    } else if (schema.messages.has(fd.type)) {
      if (target.present.has(fieldNum)) {
        mergeMessages(target.values.get(fieldNum) as DecodedMessage, sv as DecodedMessage, schema.messages.get(fd.type)!, schema);
      } else {
        target.values.set(fieldNum, sv);
        target.present.add(fieldNum);
      }
    } else {
      target.values.set(fieldNum, sv);
      target.present.add(fieldNum);
    }
  }
}

// ============ JSON Output ============

function toCamelCase(name: string): string {
  let result = '';
  let upperNext = false;
  for (const ch of name) {
    if (ch === '_') { upperNext = true; }
    else {
      if (upperNext && ch >= 'a' && ch <= 'z') result += ch.toUpperCase();
      else result += ch;
      upperNext = false;
    }
  }
  return result;
}

function escapeJson(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (ch === '"') r += '\\"';
    else if (ch === '\\') r += '\\\\';
    else if (code === 8) r += '\\b';
    else if (code === 9) r += '\\t';
    else if (code === 10) r += '\\n';
    else if (code === 12) r += '\\f';
    else if (code === 13) r += '\\r';
    else if (code < 32) r += '\\u' + code.toString(16).padStart(4, '0');
    else r += ch;
  }
  return r + '"';
}

function isDefaultScalar(value: any, type: string, schema: Schema): boolean {
  switch (type) {
    case 'int32': case 'uint32': case 'sint32': case 'fixed32': case 'sfixed32': return value === 0;
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return value === 0n;
    case 'bool': return value === false;
    case 'string': return value === '';
    case 'bytes': return (value as Buffer).length === 0;
    default:
      if (schema.enums.has(type)) return value === 0;
      return false;
  }
}

function is64BitType(type: string): boolean {
  return type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64';
}

function valueToJson(value: any, type: string, schema: Schema): string {
  if (schema.messages.has(type)) {
    return messageToJson(value as DecodedMessage, schema.messages.get(type)!, schema);
  }
  switch (type) {
    case 'int32': case 'uint32': case 'sint32': case 'fixed32': case 'sfixed32': return String(value);
    case 'int64': case 'uint64': case 'sint64': case 'fixed64': case 'sfixed64': return `"${(value as bigint).toString()}"`;
    case 'bool': return value ? 'true' : 'false';
    case 'string': return escapeJson(value as string);
    case 'bytes': return `"${(value as Buffer).toString('base64')}"`;
    default:
      if (schema.enums.has(type)) {
        const enumDef = schema.enums.get(type)!;
        const name = enumDef.values.get(value as number);
        if (name !== undefined) return `"${name}"`;
        return String(value);
      }
      throw new Error(`Unknown type for JSON: ${type}`);
  }
}

function mapToJson(map: Map<any, any>, fieldDef: FieldDef, schema: Schema): string {
  const entries: { keyStr: string; json: string; sortKey: any }[] = [];
  const kt = fieldDef.mapKeyType!;
  const vt = fieldDef.mapValueType!;

  for (const [k, v] of map) {
    const keyStr = kt === 'int32' ? String(k) : String(k);
    const jsonKey = escapeJson(keyStr);
    const jsonVal = valueToJson(v, vt, schema);
    entries.push({ keyStr, json: `${jsonKey}:${jsonVal}`, sortKey: kt === 'int32' ? (k as number) : Buffer.from(keyStr, 'utf8') });
  }

  if (kt === 'int32') {
    entries.sort((a, b) => (a.sortKey as number) - (b.sortKey as number));
  } else {
    entries.sort((a, b) => (a.sortKey as Buffer).compare(b.sortKey as Buffer));
  }

  return '{' + entries.map(e => e.json).join(',') + '}';
}

function messageToJson(msg: DecodedMessage, msgDef: MessageDef, schema: Schema): string {
  const parts: string[] = [];
  const sortedFields = [...msgDef.fields.values()].sort((a, b) => a.number - b.number);

  for (const fd of sortedFields) {
    if (!msg.present.has(fd.number)) continue;
    const value = msg.values.get(fd.number);

    if (fd.isMap) {
      if (!(value instanceof Map) || (value as Map<any, any>).size === 0) continue;
    } else if (fd.label === 'repeated') {
      if (!Array.isArray(value) || (value as any[]).length === 0) continue;
    } else if (schema.messages.has(fd.type)) {
      // always print if present
    } else if (fd.oneofName || fd.label === 'optional') {
      // always print if present
    } else {
      if (isDefaultScalar(value, fd.type, schema)) continue;
    }

    const jsonName = escapeJson(toCamelCase(fd.name));
    let jsonVal: string;
    if (fd.isMap) {
      jsonVal = mapToJson(value as Map<any, any>, fd, schema);
    } else if (fd.label === 'repeated') {
      const arr = value as any[];
      jsonVal = '[' + arr.map(el => valueToJson(el, fd.type, schema)).join(',') + ']';
    } else {
      jsonVal = valueToJson(value, fd.type, schema);
    }
    parts.push(`${jsonName}:${jsonVal}`);
  }
  return '{' + parts.join(',') + '}';
}

// ============ Main ============

function main(): void {
  const dir = process.argv[2];
  const protoContent = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf8');
  const binContent = fs.readFileSync(path.join(dir, 'messages.bin'));

  const parser = new ProtoParser(protoContent);
  const schema = parser.parse();

  const rootDef = schema.messages.get(schema.rootMessage)!;

  let pos = 0;
  const lines: string[] = [];

  while (pos < binContent.length) {
    let len = 0;
    let shift = 0;
    for (let i = 0; i < 10 && pos < binContent.length; i++) {
      const byte = binContent[pos++];
      len |= (byte & 0x7F) << shift;
      if ((byte & 0x80) === 0) break;
      shift += 7;
    }
    const msgBytes = binContent.subarray(pos, pos + len);
    pos += len;

    const reader = new BinaryReader(msgBytes);
    const decoded = decodeMessage(reader, rootDef, schema);
    lines.push(messageToJson(decoded, rootDef, schema));
  }

  process.stdout.write(lines.join('\n') + (lines.length > 0 ? '\n' : ''));
}

main();

import Foundation

// MARK: - Schema Types

enum ScalarKind: String {
    case int32, int64, uint32, uint64, sint32, sint64
    case bool, string, bytes
    case fixed32, fixed64, sfixed32, sfixed64
}

enum FieldTypeDef {
    case scalar(ScalarKind)
    case message(String)
    case enumType(String)
    case map(key: ScalarKind, value: FieldTypeDef)
}

struct FieldDef {
    let name: String
    let number: Int
    let type: FieldTypeDef
    let isRepeated: Bool
    let isOptional: Bool
    let oneofName: String?
}

struct MessageDef {
    let name: String
    var fields: [FieldDef] = []
}

struct EnumDef {
    let name: String
    var values: [(name: String, number: Int32)] = []
    var byNumber: [Int32: String] = [:]
}

struct Schema {
    var messages: [String: MessageDef] = [:]
    var enums: [String: EnumDef] = [:]
    var rootMessage: String = ""
}

// MARK: - Lexer

enum TokType { case ident, num, str, lbrace, rbrace, lbracket, rbracket, langle, rangle, comma, semicolon, equals, dot, eof }

struct Tok { let type: TokType; let value: String }

func tokenize(_ input: String) -> [Tok] {
    var toks: [Tok] = []
    let chars = Array(input)
    var i = 0
    let n = chars.count
    while i < n {
        let c = chars[i]
        if c == " " || c == "\t" || c == "\n" || c == "\r" || c == "\r\n" {
            i += 1
        } else if c == "/" && i + 1 < n && chars[i+1] == "/" {
            i += 2
            while i < n && chars[i] != "\n" { i += 1 }
        } else if c == "/" && i + 1 < n && chars[i+1] == "*" {
            i += 2
            while i + 1 < n && !(chars[i] == "*" && chars[i+1] == "/") { i += 1 }
            if i + 1 < n { i += 2 }
        } else if c == "{" { toks.append(Tok(type: .lbrace, value: "{")); i += 1 }
        else if c == "}" { toks.append(Tok(type: .rbrace, value: "}")); i += 1 }
        else if c == "[" { toks.append(Tok(type: .lbracket, value: "[")); i += 1 }
        else if c == "]" { toks.append(Tok(type: .rbracket, value: "]")); i += 1 }
        else if c == "<" { toks.append(Tok(type: .langle, value: "<")); i += 1 }
        else if c == ">" { toks.append(Tok(type: .rangle, value: ">")); i += 1 }
        else if c == "," { toks.append(Tok(type: .comma, value: ",")); i += 1 }
        else if c == ";" { toks.append(Tok(type: .semicolon, value: ";")); i += 1 }
        else if c == "=" { toks.append(Tok(type: .equals, value: "=")); i += 1 }
        else if c == "." { toks.append(Tok(type: .dot, value: ".")); i += 1 }
        else if c == "\"" {
            i += 1
            var s = ""
            while i < n && chars[i] != "\"" { s.append(chars[i]); i += 1 }
            if i < n { i += 1 }
            toks.append(Tok(type: .str, value: s))
        } else if c.isLetter || c == "_" {
            var s = ""
            while i < n && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_" || chars[i] == ".") {
                s.append(chars[i]); i += 1
            }
            toks.append(Tok(type: .ident, value: s))
        } else if c.isNumber || c == "-" || c == "+" {
            var s = ""
            if c == "-" || c == "+" { s.append(c); i += 1 }
            while i < n && (chars[i].isNumber || chars[i] == "." || chars[i] == "e" || chars[i] == "E" || chars[i] == "+" || chars[i] == "-") {
                if (chars[i] == "+" || chars[i] == "-") && s.last != "e" && s.last != "E" { break }
                s.append(chars[i]); i += 1
            }
            toks.append(Tok(type: .num, value: s))
        } else if c == ":" { toks.append(Tok(type: .equals, value: ":")); i += 1 }
        else { i += 1 }
    }
    toks.append(Tok(type: .eof, value: ""))
    return toks
}

// MARK: - Parser

class ProtoParser {
    let toks: [Tok]
    var pos = 0
    var schema = Schema()
    var rootFound = false

    init(_ toks: [Tok]) { self.toks = toks }

    func peek() -> Tok { toks[pos] }
    func advance() -> Tok { let t = toks[pos]; pos += 1; return t }
    func expect(_ t: TokType) { _ = advance() }
    func skipTo(_ t: TokType) { while peek().type != t && peek().type != .eof { advance() } }
    func skipOptions() {
        if peek().type == .lbracket {
            advance() // [
            while peek().type != .rbracket && peek().type != .eof { advance() }
            if peek().type == .rbracket { advance() }
        }
    }

    func parse() {
        while peek().type != .eof {
            parseTopLevel()
        }
    }

    func parseTopLevel() {
        let t = peek()
        if t.type == .ident {
            switch t.value {
            case "syntax":
                advance(); advance(); advance(); advance() // syntax = "proto3" ;
            case "package":
                advance(); skipTo(.semicolon); advance()
            case "option":
                advance(); skipTo(.semicolon); advance()
            case "message":
                parseMessage(topLevel: true)
            case "enum":
                parseEnum()
            default:
                advance()
            }
        } else {
            advance()
        }
    }

    func parseMessage(topLevel: Bool) {
        advance() // message
        let name = advance().value // name
        if topLevel && !rootFound {
            schema.rootMessage = name
            rootFound = true
        }
        expect(.lbrace)
        var msgDef = MessageDef(name: name)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                switch t.value {
                case "message":
                    parseMessage(topLevel: false)
                case "enum":
                    parseEnum()
                case "oneof":
                    parseOneof(into: &msgDef)
                case "reserved":
                    advance(); skipTo(.semicolon); advance()
                case "option":
                    advance(); skipTo(.semicolon); advance()
                case "map":
                    parseField(into: &msgDef, inOneof: nil)
                default:
                    parseField(into: &msgDef, inOneof: nil)
                }
            } else {
                advance()
            }
        }
        if peek().type == .rbrace { advance() }
        schema.messages[name] = msgDef
    }

    func parseOneof(into msgDef: inout MessageDef) {
        advance() // oneof
        let oneofName = advance().value
        expect(.lbrace)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                switch t.value {
                case "option":
                    advance(); skipTo(.semicolon); advance()
                default:
                    parseField(into: &msgDef, inOneof: oneofName)
                }
            } else {
                advance()
            }
        }
        if peek().type == .rbrace { advance() }
    }

    func parseField(into msgDef: inout MessageDef, inOneof: String?) {
        var isRepeated = false
        var isOptional = false

        if peek().type == .ident {
            if peek().value == "repeated" { isRepeated = true; advance() }
            else if peek().value == "optional" && inOneof == nil { isOptional = true; advance() }
        }

        var fieldType: FieldTypeDef
        if peek().type == .ident && peek().value == "map" && pos + 1 < toks.count && toks[pos+1].type == .langle {
            advance() // map
            expect(.langle)
            let keyName = advance().value
            let keyKind: ScalarKind = keyName == "int32" ? .int32 : .string
            expect(.comma)
            let valTypeName = advance().value
            let valType = resolveTypeName(valTypeName)
            expect(.rangle)
            fieldType = .map(key: keyKind, value: valType)
        } else {
            let typeName = advance().value
            fieldType = resolveTypeName(typeName)
        }

        let fieldName = advance().value // field name
        // expect =
        if peek().type == .equals { advance() }
        let numStr = advance().value
        let fieldNumber = Int(numStr) ?? 0

        skipOptions()

        if peek().type == .semicolon { advance() }

        let fd = FieldDef(name: fieldName, number: fieldNumber, type: fieldType,
                         isRepeated: isRepeated, isOptional: isOptional, oneofName: inOneof)
        msgDef.fields.append(fd)
    }

    func resolveTypeName(_ name: String) -> FieldTypeDef {
        if let _ = ScalarKind(rawValue: name) {
            return .scalar(ScalarKind(rawValue: name)!)
        }
        if schema.enums[name] != nil {
            return .enumType(name)
        }
        // Could be a message (possibly not yet declared)
        return .message(name)
    }

    func parseEnum() {
        advance() // enum
        let name = advance().value
        expect(.lbrace)
        var enumDef = EnumDef(name: name)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                if t.value == "option" || t.value == "reserved" {
                    advance(); skipTo(.semicolon); advance()
                } else {
                    let valName = advance().value
                    if peek().type == .equals { advance() }
                    var neg = false
                    if peek().type == .num && peek().value.hasPrefix("-") { neg = true; advance() }
                    else if peek().type == .num { advance() }
                    else if peek().type == .ident && (peek().value == "-" || peek().value == "+") {
                        if peek().value == "-" { neg = true }
                        advance()
                        if peek().type == .num { advance() }
                    }
                    let numStr = toks[pos-1].value
                    let numVal = Int32(numStr) ?? 0
                    let finalVal = neg ? -abs(numVal) : numVal
                    skipOptions()
                    if peek().type == .semicolon { advance() }
                    enumDef.values.append((name: valName, number: finalVal))
                    enumDef.byNumber[finalVal] = valName
                }
            } else {
                advance()
            }
        }
        if peek().type == .rbrace { advance() }
        schema.enums[name] = enumDef
    }
}

// MARK: - Decoded Values

indirect enum Val {
    case int(Int64)
    case uint(UInt64)
    case bool(Bool)
    case str(String)
    case bytes([UInt8])
    case msg(DecodedMsg)
    case enumVal(Int32)
}

struct MapEntry {
    let key: MapKey
    let value: Val
}

enum MapKey: Hashable {
    case str(String)
    case int(Int32)
}

struct FieldData {
    var occurred = false
    var singular: Val? = nil
    var repeated: [Val] = []
    var mapEntries: [MapEntry] = []
}

struct DecodedMsg {
    var fields: [Int: FieldData] = [:]
    var oneofSet: [String: Int] = [:]
}

// MARK: - Decoder

class Decoder {
    let data: [UInt8]
    var pos = 0
    let schema: Schema

    init(_ data: [UInt8], schema: Schema) {
        self.data = data
        self.schema = schema
    }

    func readVarint() -> UInt64 {
        var result: UInt64 = 0
        var shift: UInt64 = 0
        for _ in 0..<10 {
            if pos >= data.count { break }
            let b = data[pos]; pos += 1
            result |= UInt64(b & 0x7F) << shift
            if b & 0x80 == 0 { break }
            shift += 7
        }
        return result
    }

    func readFixed32() -> UInt32 {
        var v: UInt32 = 0
        for i in 0..<4 {
            if pos < data.count { v |= UInt32(data[pos]) << (8 * UInt32(i)) }
            pos += 1
        }
        return v
    }

    func readFixed64() -> UInt64 {
        var v: UInt64 = 0
        for i in 0..<8 {
            if pos < data.count { v |= UInt64(data[pos]) << (8 * UInt64(i)) }
            pos += 1
        }
        return v
    }

    func readBytes() -> [UInt8] {
        let len = Int(readVarint())
        let end = min(pos + len, data.count)
        let result = Array(data[pos..<end])
        pos = end
        return result
    }

    func skipValue(wireType: Int, fieldNumber: Int) {
        switch wireType {
        case 0: _ = readVarint()
        case 1: pos += 8
        case 2: let len = Int(readVarint()); pos = min(pos + len, data.count)
        case 5: pos += 4
        case 3:
            while pos < data.count {
                let key = readVarint()
                let wt = Int(key & 7)
                let fn = Int(key >> 3)
                if wt == 4 && fn == fieldNumber { break }
                skipValue(wireType: wt, fieldNumber: fn)
            }
        case 4: break
        default: break
        }
    }

    func decodeMessage(msgName: String) -> DecodedMsg {
        guard let msgDef = schema.messages[msgName] else { return DecodedMsg() }
        return decodeMessage(msgDef)
    }

    func decodeMessage(_ msgDef: MessageDef) -> DecodedMsg {
        var msg = DecodedMsg()
        while pos < data.count {
            let key = readVarint()
            let fieldNumber = Int(key >> 3)
            let wireType = Int(key & 7)

            guard let fieldDef = msgDef.fields.first(where: { $0.number == fieldNumber }) else {
                skipValue(wireType: wireType, fieldNumber: fieldNumber)
                continue
            }

            handleField(fieldDef, wireType: wireType, into: &msg, msgDef: msgDef)
        }
        return msg
    }

    func isPackedType(_ type: FieldTypeDef) -> Bool {
        switch type {
        case .scalar(let k):
            switch k {
            case .string, .bytes: return false
            default: return true
            }
        case .enumType: return true
        default: return false
        }
    }

    func isMessageOrEnum(_ type: FieldTypeDef) -> Bool {
        switch type {
        case .message, .enumType: return true
        default: return false
        }
    }

    func handleField(_ fd: FieldDef, wireType: Int, into msg: inout DecodedMsg, msgDef: MessageDef) {
        let baseType: FieldTypeDef
        switch fd.type {
        case .map(_, let v): baseType = v
        default: baseType = fd.type
        }

        if fd.isRepeated {
            if isPackedType(baseType) && wireType == 2 {
                let packedData = readBytes()
                let sub = Decoder(packedData, schema: schema)
                while sub.pos < packedData.count {
                    if let v = sub.decodeSingleValue(baseType, wireType: packedWireType(baseType)) {
                        msg.fields[fd.number, default: FieldData()].repeated.append(v)
                        msg.fields[fd.number]!.occurred = true
                    } else { break }
                }
            } else {
                if let v = decodeSingleValue(baseType, wireType: wireType) {
                    msg.fields[fd.number, default: FieldData()].repeated.append(v)
                    msg.fields[fd.number]!.occurred = true
                }
            }
        } else if case .map(let keyKind, let valType) = fd.type {
            if wireType == 2 {
                let entryBytes = readBytes()
                let entryDecoder = Decoder(entryBytes, schema: schema)
                var keyValue: Val = keyKind == .string ? .str("") : .int(0)
                var valValue: Val = defaultVal(valType)
                let entryMsg = entryDecoder.decodeMapEntry(keyKind: keyKind, valType: valType)
                if let kv = entryMsg.0 { keyValue = kv }
                if let vv = entryMsg.1 { valValue = vv }
                let mk: MapKey = keyKind == .string ? (keyValue == .str("") ? .str("") : (case .str(let s) = keyValue ? .str(s) : .str(""))) : (case .int(let i) = keyValue ? .int(i) : .int(0))
                // Fix: properly extract map key
                let mapKey: MapKey
                if keyKind == .string {
                    if case .str(let s) = keyValue { mapKey = .str(s) } else { mapKey = .str("") }
                } else {
                    if case .int(let i) = keyValue { mapKey = .int(i) }
                    else if case .uint(let u) = keyValue { mapKey = .int(Int32(truncatingBitPattern: u)) }
                    else { mapKey = .int(0) }
                }
                var entries = msg.fields[fd.number, default: FieldData()].mapEntries
                if let idx = entries.firstIndex(where: { $0.key == mapKey }) {
                    entries[idx] = MapEntry(key: mapKey, value: valValue)
                } else {
                    entries.append(MapEntry(key: mapKey, value: valValue))
                }
                msg.fields[fd.number] = FieldData(occurred: true, mapEntries: entries)
            }
        } else {
            // Singular
            if let v = decodeSingleValue(fd.type, wireType: wireType) {
                if let oneofName = fd.oneofName {
                    // Clear other members of same oneof
                    for other in msgDef.fields where other.oneofName == oneofName && other.number != fd.number {
                        msg.fields[other.number] = nil
                    }
                    if msg.oneofSet[oneofName] == fd.number, case .message(let mn) = fd.type {
                        // Merge with existing
                        if case .msg(let existing) = msg.fields[fd.number]?.singular, case .msg(let newMsg) = v {
                            var merged = existing
                            mergeMsg(into: &merged, from: newMsg, msgName: mn)
                            msg.fields[fd.number] = FieldData(occurred: true, singular: .msg(merged))
                        } else {
                            msg.fields[fd.number] = FieldData(occurred: true, singular: v)
                        }
                    } else {
                        msg.fields[fd.number] = FieldData(occurred: true, singular: v)
                    }
                    msg.oneofSet[oneofName] = fd.number
                } else if case .message(let mn) = fd.type {
                    if msg.fields[fd.number]?.occurred == true, case .msg(let existing) = msg.fields[fd.number]!.singular, case .msg(let newMsg) = v {
                        var merged = existing
                        mergeMsg(into: &merged, from: newMsg, msgName: mn)
                        msg.fields[fd.number] = FieldData(occurred: true, singular: .msg(merged))
                    } else {
                        msg.fields[fd.number] = FieldData(occurred: true, singular: v)
                    }
                } else {
                    msg.fields[fd.number] = FieldData(occurred: true, singular: v)
                }
            }
        }
    }

    func packedWireType(_ type: FieldTypeDef) -> Int {
        switch type {
        case .scalar(let k):
            switch k {
            case .fixed32, .sfixed32: return 5
            case .fixed64, .sfixed64: return 1
            default: return 0
            }
        case .enumType: return 0
        default: return 0
        }
    }

    func decodeSingleValue(_ type: FieldTypeDef, wireType: Int) -> Val? {
        switch type {
        case .scalar(let k):
            return decodeScalar(k, wireType: wireType)
        case .message(let mn):
            if wireType == 2 {
                let bytes = readBytes()
                let sub = Decoder(bytes, schema: schema)
                return .msg(sub.decodeMessage(msgName: mn))
            }
            return nil
        case .enumType(let en):
            if wireType == 0 {
                let v = readVarint()
                return .enumVal(Int32(truncatingBitPattern: UInt32(truncatingBitPattern: v)))
            }
            return nil
        case .map:
            return nil
        }
    }

    func decodeScalar(_ k: ScalarKind, wireType: Int) -> Val? {
        switch k {
        case .int32:
            if wireType == 0 { let v = readVarint(); return .int(Int64(Int32(truncatingBitPattern: UInt32(truncatingBitPattern: v)))) }
        case .int64:
            if wireType == 0 { let v = readVarint(); return .int(Int64(bitPattern: v)) }
        case .uint32:
            if wireType == 0 { let v = readVarint(); return .uint(UInt64(UInt32(truncatingBitPattern: v))) }
        case .uint64:
            if wireType == 0 { let v = readVarint(); return .uint(v) }
        case .sint32:
            if wireType == 0 { let v = readVarint(); return .int(Int64(zigzag32(v))) }
        case .sint64:
            if wireType == 0 { let v = readVarint(); return .int(zigzag64(v)) }
        case .bool:
            if wireType == 0 { let v = readVarint(); return .bool(v != 0) }
        case .string:
            if wireType == 2 { let b = readBytes(); return .str(String(decoding: b, as: UTF8.self)) }
        case .bytes:
            if wireType == 2 { let b = readBytes(); return .bytes(b) }
        case .fixed32:
            if wireType == 5 { let v = readFixed32(); return .uint(UInt64(v)) }
        case .fixed64:
            if wireType == 1 { let v = readFixed64(); return .uint(v) }
        case .sfixed32:
            if wireType == 5 { let v = readFixed32(); return .int(Int64(Int32(bitPattern: v))) }
        case .sfixed64:
            if wireType == 1 { let v = readFixed64(); return .int(Int64(bitPattern: v)) }
        }
        // Wrong wire type - skip
        skipValue(wireType: wireType, fieldNumber: 0)
        return nil
    }

    func decodeMapEntry(keyKind: ScalarKind, valType: FieldTypeDef) -> (Val?, Val?) {
        var keyValue: Val? = nil
        var valValue: Val? = nil
        while pos < data.count {
            let key = readVarint()
            let fn = Int(key >> 3)
            let wt = Int(key & 7)
            if fn == 1 {
                if keyKind == .string {
                    if wt == 2 { let b = readBytes(); keyValue = .str(String(decoding: b, as: UTF8.self)) }
                } else {
                    if wt == 0 { let v = readVarint(); keyValue = .int(Int32(truncatingBitPattern: UInt32(truncatingBitPattern: v))) }
                }
            } else if fn == 2 {
                valValue = decodeSingleValue(valType, wireType: wt)
            } else {
                skipValue(wireType: wt, fieldNumber: fn)
            }
        }
        return (keyValue, valValue)
    }

    func mergeMsg(into target: inout DecodedMsg, from source: DecodedMsg, msgName: String) {
        guard let msgDef = schema.messages[msgName] else { return }
        for (fn, srcData) in source.fields {
            guard srcData.occurred else { continue }
            guard let fd = msgDef.fields.first(where: { $0.number == fn }) else { continue }

            if let oneofName = fd.oneofName {
                for other in msgDef.fields where other.oneofName == oneofName && other.number != fn {
                    target.fields[other.number] = nil
                }
                target.oneofSet[oneofName] = fn
            }

            if fd.isRepeated {
                target.fields[fn, default: FieldData()].repeated.append(contentsOf: srcData.repeated)
                target.fields[fn]!.occurred = true
            } else if case .map = fd.type {
                var entries = target.fields[fn, default: FieldData()].mapEntries
                for entry in srcData.mapEntries {
                    if let idx = entries.firstIndex(where: { $0.key == entry.key }) {
                        entries[idx] = entry
                    } else {
                        entries.append(entry)
                    }
                }
                target.fields[fn] = FieldData(occurred: true, mapEntries: entries)
            } else if case .message(let mn) = fd.type {
                if target.fields[fn]?.occurred == true, case .msg(let existing) = target.fields[fn]!.singular, case .msg(let newM) = srcData.singular {
                    var merged = existing
                    mergeMsg(into: &merged, from: newM, msgName: mn)
                    target.fields[fn] = FieldData(occurred: true, singular: .msg(merged))
                } else {
                    target.fields[fn] = srcData
                }
            } else {
                target.fields[fn] = srcData
            }
        }
        for (k, v) in source.oneofSet {
            target.oneofSet[k] = v
        }
    }
}

func zigzag32(_ n: UInt64) -> Int32 {
    let v = UInt32(truncatingBitPattern: n)
    return Int32(bitPattern: (v >> 1) ^ (UInt32(bitPattern: Int32(bitPattern: v << 31 >> 31))))
}

func zigzag64(_ n: UInt64) -> Int64 {
    return Int64(bitPattern: (n >> 1) ^ UInt64(bitPattern: Int64(bitPattern: n << 63 >> 63)))
}

func defaultVal(_ type: FieldTypeDef) -> Val {
    switch type {
    case .scalar(let k):
        switch k {
        case .string: return .str("")
        case .bytes: return .bytes([])
        case .bool: return .bool(false)
        default: return .int(0)
        }
    case .message: return .msg(DecodedMsg())
    case .enumType: return .enumVal(0)
    case .map: return .bytes([]) // shouldn't happen
    }
}

// MARK: - JSON Output

func toLowerCamelCase(_ name: String) -> String {
    var result = ""
    var i = name.startIndex
    while i < name.endIndex {
        if name[i] == "_" {
            let next = name.index(after: i)
            if next < name.endIndex {
                let c = name[next]
                if c >= "a" && c <= "z" {
                    result.append(Character(c.uppercased()))
                } else {
                    result.append(c)
                }
                i = name.index(after: next)
            } else {
                i = next
            }
        } else {
            result.append(name[i])
            i = name.index(after: i)
        }
    }
    return result
}

func escapeJSONString(_ s: String) -> String {
    var result = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        switch v {
        case 0x08: result += "\\b"
        case 0x09: result += "\\t"
        case 0x0A: result += "\\n"
        case 0x0C: result += "\\f"
        case 0x0D: result += "\\r"
        case 0x22: result += "\\\""
        case 0x5C: result += "\\\\"
        default:
            if v < 0x20 {
                result += String(format: "\\u%04x", v)
            } else {
                result.unicodeScalars.append(scalar)
            }
        }
    }
    result += "\""
    return result
}

func base64Encode(_ data: [UInt8]) -> String {
    return Data(data).base64EncodedString()
}

func isDefault(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i == 0
    case .uint(let u): return u == 0
    case .bool(let b): return !b
    case .str(let s): return s.isEmpty
    case .bytes(let b): return b.isEmpty
    case .enumVal(let e): return e == 0
    case .msg: return false
    }
}

func valToJSON(_ v: Val, type: FieldTypeDef, schema: Schema) -> String {
    switch (v, type) {
    case (.int(let i), _):
        if isInt64Type(type) {
            return "\"\(i)\""
        } else {
            return "\(i)"
        }
    case (.uint(let u), _):
        if isUInt64Type(type) {
            return "\"\(u)\""
        } else {
            return "\(u)"
        }
    case (.bool(let b), _):
        return b ? "true" : "false"
    case (.str(let s), _):
        return escapeJSONString(s)
    case (.bytes(let b), _):
        return "\"" + base64Encode(b) + "\""
    case (.msg(let m), .message(let mn)):
        return msgToJSON(m, msgName: mn, schema: schema)
    case (.enumVal(let e), .enumType(let en)):
        if let enumDef = schema.enums[en], let name = enumDef.byNumber[e] {
            return "\"\(name)\""
        } else {
            return "\(e)"
        }
    default:
        return "null"
    }
}

func isInt64Type(_ type: FieldTypeDef) -> Bool {
    switch type {
    case .scalar(let k):
        switch k {
        case .int64, .sint64, .sfixed64: return true
        default: return false
        }
    default: return false
    }
}

func isUInt64Type(_ type: FieldTypeDef) -> Bool {
    switch type {
    case .scalar(let k):
        switch k {
        case .uint64, .fixed64: return true
        default: return false
        }
    default: return false
    }
}

func msgToJSON(_ msg: DecodedMsg, msgName: String, schema: Schema) -> String {
    guard let msgDef = schema.messages[msgName] else { return "{}" }
    var parts: [String] = []
    let sortedFields = msgDef.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        guard let fd_data = msg.fields[fd.number], fd_data.occurred else { continue }

        if fd.isRepeated {
            if fd_data.repeated.isEmpty { continue }
            let baseType: FieldTypeDef
            switch fd.type {
            case .map(_, let v): baseType = v
            default: baseType = fd.type
            }
            let arr = fd_data.repeated.map { valToJSON($0, type: baseType, schema: schema) }
            parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):[\(arr.joined(separator: ","))]")
        } else if case .map(let keyKind, let valType) = fd.type {
            if fd_data.mapEntries.isEmpty { continue }
            let sorted: [MapEntry]
            if keyKind == .int32 {
                sorted = fd_data.mapEntries.sorted { a, b in
                    let ai: Int32, bi: Int32
                    if case .int(let x) = a.key { ai = x } else { ai = 0 }
                    if case .int(let x) = b.key { bi = x } else { bi = 0 }
                    return ai < bi
                }
            } else {
                sorted = fd_data.mapEntries.sorted { a, b in
                    let as_: String, bs: String
                    if case .str(let x) = a.key { as_ = x } else { as_ = "" }
                    if case .str(let x) = b.key { bs = x } else { bs = "" }
                    return as_.utf8.lexicographicallyPrecedes(bs.utf8)
                }
            }
            let mapParts = sorted.map { entry -> String in
                let keyStr: String
                switch entry.key {
                case .str(let s): keyStr = s
                case .int(let i): keyStr = "\(i)"
                }
                return "\(escapeJSONString(keyStr)):\(valToJSON(entry.value, type: valType, schema: schema))"
            }
            parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):{\(mapParts.joined(separator: ","))}")
        } else {
            // Singular
            guard let val = fd_data.singular else { continue }

            if case .message = fd.type {
                // Always print if occurred
                parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
            } else {
                // Scalar or enum
                if fd.oneofName != nil {
                    // Print if it's the set member
                    if let on = fd.oneofName, msg.oneofSet[on] == fd.number {
                        parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                    }
                } else if fd.isOptional {
                    parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                } else {
                    // Print only if not default
                    if !isDefault(val) {
                        parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                    }
                }
            }
        }
    }

    return "{\(parts.joined(separator: ","))}"
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]

let protoPath = dir + "/schema.proto"
let binPath = dir + "/messages.bin"

guard let protoContent = try? String(contentsOfFile: protoPath, encoding: .utf8) else { exit(0) }
guard let binData = try? Data(contentsOf: URL(fileURLWithPath: binPath)) else { exit(0) }

let toks = tokenize(protoContent)
let parser = ProtoParser(toks)
parser.parse()
let schema = parser.schema

let binBytes = [UInt8](binData)
var outputLines: [String] = []
var bpos = 0

while bpos < binBytes.count {
    // Read varint length
    var len: UInt64 = 0
    var shift: UInt64 = 0
    var varintOk = false
    for _ in 0..<10 {
        if bpos >= binBytes.count { break }
        let b = binBytes[bpos]; bpos += 1
        len |= UInt64(b & 0x7F) << shift
        if b & 0x80 == 0 { varintOk = true; break }
        shift += 7
    }
    if !varintOk { break }
    let msgLen = Int(len)
    let msgEnd = min(bpos + msgLen, binBytes.count)
    let msgBytes = Array(binBytes[bpos..<msgEnd])
    bpos = msgEnd

    let decoder = Decoder(msgBytes, schema: schema)
    let decoded = decoder.decodeMessage(msgName: schema.rootMessage)
    let json = msgToJSON(decoded, msgName: schema.rootMessage, schema: schema)
    outputLines.append(json)
}

print(outputLines.joined(separator: "\n"))
exit(0)

