    while i < n {
        let c = chars[i]
        if c == " " || c == "\t" || c == "\n" || c == "\r" {
            i += 1
        } else if c == "/" && i + 1 < n && chars[i+1] == "/" {
            i += 2
            while i < n && chars[i] != "\n" { i += 1 }
        } else if c == "/" && i + 1 < n && chars[i+1] == "*" {
            i += 2
            while i + 1 < n && !(chars[i] == "*" && chars[i+1] == "/") { i += 1 }
            if i + 1 < n { i += 2 }
        } else if c == "{" { toks.append(Tok(type: .lbrace, value: "{")); i += 1 }
        else if c == "}" { toks.append(Tok(type: .rbrace, value: "}")); i += 1 }
        else if c == "[" { toks.append(Tok(type: .lbracket, value: "[")); i += 1 }
        else if c == "]" { toks.append(Tok(type: .rbracket, value: "]")); i += 1 }
        else if c == "<" { toks.append(Tok(type: .langle, value: "<")); i += 1 }
        else if c == ">" { toks.append(Tok(type: .rangle, value: ">")); i += 1 }
        else if c == "," { toks.append(Tok(type: .comma, value: ",")); i += 1 }
        else if c == ";" { toks.append(Tok(type: .semicolon, value: ";")); i += 1 }
        else if c == "=" { toks.append(Tok(type: .equals, value: "=")); i += 1 }
        else if c == "." { toks.append(Tok(type: .dot, value: ".")); i += 1 }
        else if c == ":" { toks.append(Tok(type: .equals, value: ":")); i += 1 }
        else if c == "\"" {
            i += 1
            var s = ""
            while i < n && chars[i] != "\"" { s.append(chars[i]); i += 1 }
            if i < n { i += 1 }
            toks.append(Tok(type: .str, value: s))
        } else if c.isLetter || c == "_" {
            var s = ""
            while i < n && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_" || chars[i] == ".") {
                s.append(chars[i]); i += 1
            }
            toks.append(Tok(type: .ident, value: s))
        } else if c.isNumber || c == "-" || c == "+" {
            var s = ""
            if c == "-" || c == "+" { s.append(c); i += 1 }
            while i < n && (chars[i].isNumber || chars[i] == "." || chars[i] == "e" || chars[i] == "E") {
                s.append(chars[i]); i += 1
            }
            if i < n && (chars[i] == "+" || chars[i] == "-") && (s.last == "e" || s.last == "E") {
                s.append(chars[i]); i += 1
                while i < n && chars[i].isNumber { s.append(chars[i]); i += 1 }
            }
            toks.append(Tok(type: .num, value: s))
        } else { i += 1 }
    }
    toks.append(Tok(type: .eof, value: ""))
    return toks
