// MARK: - Parser

class ProtoParser {
    let toks: [Tok]
    var pos = 0
    var schema = Schema()
    var rootFound = false

    init(_ toks: [Tok]) { self.toks = toks }

    func peek() -> Tok { toks[pos] }
    func advance() -> Tok { let t = toks[pos]; pos += 1; return t }
    func expect(_ t: TokType) { _ = advance() }
    func skipTo(_ t: TokType) { while peek().type != t && peek().type != .eof { advance() } }
    func skipOptions() {
        if peek().type == .lbracket {
            advance()
            while peek().type != .rbracket && peek().type != .eof { advance() }
            if peek().type == .rbracket { advance() }
        }
    }

    func parse() {
        while peek().type != .eof {
            parseTopLevel()
        }
    }

    func parseTopLevel() {
        let t = peek()
        if t.type == .ident {
            switch t.value {
            case "syntax":
                advance(); advance(); advance(); advance()
            case "package":
                advance(); skipTo(.semicolon); advance()
            case "option":
                advance(); skipTo(.semicolon); advance()
            case "message":
                parseMessage(topLevel: true)
            case "enum":
                parseEnum()
            default:
                advance()
            }
        } else {
            advance()
        }
    }

    func parseMessage(topLevel: Bool) {
        advance() // message
        let name = advance().value
        if topLevel && !rootFound {
            schema.rootMessage = name
            rootFound = true
        }
        expect(.lbrace)
        var msgDef = MessageDef(name: name)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                switch t.value {
                case "message":
                    parseMessage(topLevel: false)
                case "enum":
                    parseEnum()
                case "oneof":
                    parseOneof(into: &msgDef)
                case "reserved":
                    advance(); skipTo(.semicolon); advance()
                case "option":
                    advance(); skipTo(.semicolon); advance()
                default:
                    parseField(into: &msgDef, inOneof: nil)
                }
            } else {
                advance()
            }
        }
        if peek().type == .rbrace { advance() }
        schema.messages[name] = msgDef
    }

    func parseOneof(into msgDef: inout MessageDef) {
        advance() // oneof
        let oneofName = advance().value
        expect(.lbrace)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                switch t.value {
                case "option":
                    advance(); skipTo(.semicolon); advance()
                default:
                    parseField(into: &msgDef, inOneof: oneofName)
                }
            } else {
                advance()
            }
        }
        if peek().type == .rbrace { advance() }
    }

    func parseField(into msgDef: inout MessageDef, inOneof: String?) {
        var isRepeated = false
        var isOptional = false

        if peek().type == .ident {
            if peek().value == "repeated" { isRepeated = true; advance() }
            else if peek().value == "optional" && inOneof == nil { isOptional = true; advance() }
        }

        var fieldType: FieldTypeDef
        if peek().type == .ident && peek().value == "map" && pos + 1 < toks.count && toks[pos+1].type == .langle {
            advance() // map
            expect(.langle)
            let keyName = advance().value
            let keyKind: ScalarKind = keyName == "int32" ? .int32 : .string
            expect(.comma)
            let valTypeName = advance().value
            let valType = resolveTypeName(valTypeName)
            expect(.rangle)
            fieldType = .map(key: keyKind, value: valType)
        } else {
            let typeName = advance().value
            fieldType = resolveTypeName(typeName)
        }

