        if peek().type == .equals { advance() }
        let numStr = advance().value
        let fieldNumber = Int(numStr) ?? 0

        skipOptions()

        if peek().type == .semicolon { advance() }

        let fd = FieldDef(name: fieldName, number: fieldNumber, type: fieldType,
                         isRepeated: isRepeated, isOptional: isOptional, oneofName: inOneof)
        msgDef.fields.append(fd)
    }

    func resolveTypeName(_ name: String) -> FieldTypeDef {
        if let k = ScalarKind(rawValue: name) {
            return .scalar(k)
        }
        if schema.enums[name] != nil {
            return .enumType(name)
        }
        return .message(name)
    }

    func parseEnum() {
        advance() // enum
        let name = advance().value
        expect(.lbrace)
        var enumDef = EnumDef(name: name)
        while peek().type != .rbrace && peek().type != .eof {
            let t = peek()
            if t.type == .ident {
                if t.value == "option" || t.value == "reserved" {
                    advance(); skipTo(.semicolon); advance()
                } else {
                    let valName = advance().value
                    if peek().type == .equals { advance() }
                    var neg = false
                    if peek().type == .num && peek().value.hasPrefix("-") {
                        neg = true; advance()
                    } else if peek().type == .num {
