                if target.fields[fn]?.occurred == true, case .msg(let existing) = target.fields[fn]!.singular, case .msg(let newM) = srcData.singular {
                    var merged = existing
                    mergeMsg(into: &merged, from: newM, msgName: mn)
                    target.fields[fn] = FieldData(occurred: true, singular: .msg(merged))
                } else {
                    target.fields[fn] = srcData
                }
            } else {
                target.fields[fn] = srcData
            }
        }
        for (k, v) in source.oneofSet {
            target.oneofSet[k] = v
        }
    }
}

func zigzag32(_ n: UInt64) -> Int32 {
    let v = UInt32(truncatingIfNeeded: n)
    return Int32(bitPattern: (v >> 1) ^ (0 &- (v & 1)))
}

func zigzag64(_ n: UInt64) -> Int64 {
    return Int64(bitPattern: (n >> 1) ^ (0 &- (n & 1)))
}

// MARK: - JSON Output

func toLowerCamelCase(_ name: String) -> String {
    var result = ""
    var i = name.startIndex
    while i < name.endIndex {
        if name[i] == "_" {
            let next = name.index(after: i)
            if next < name.endIndex {
                let c = name[next]
                if c >= "a" && c <= "z" {
                    result.append(Character(c.uppercased()))
                } else {
                    result.append(c)
                }
                i = name.index(after: next)
            } else {
                i = next
            }
        } else {
            result.append(name[i])
            i = name.index(after: i)
        }
    }
    return result
}

func escapeJSONString(_ s: String) -> String {
    var result = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        switch v {
        case 0x08: result += "\\b"
        case 0x09: result += "\\t"
        case 0x0A: result += "\\n"
        case 0x0C: result += "\\f"
        case 0x0D: result += "\\r"
        case 0x22: result += "\\\""
        case 0x5C: result += "\\\\"
        default:
            if v < 0x20 {
                result += String(format: "\\u%04x", v)
            } else {
                result.unicodeScalars.append(scalar)
            }
        }
    }
    result += "\""
    return result
}

func base64Encode(_ data: [UInt8]) -> String {
    return Data(data).base64EncodedString()
}

func isDefault(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i == 0
    case .uint(let u): return u == 0
    case .bool(let b): return !b
    case .str(let s): return s.isEmpty
    case .bytes(let b): return b.isEmpty
    case .enumVal(let e): return e == 0
    case .msg: return false
    }
}

func isInt64Type(_ type: FieldTypeDef) -> Bool {
    switch type {
    case .scalar(let k):
        switch k {
        case .int64, .sint64, .sfixed64: return true
        default: return false
        }
    default: return false
    }
}

func isUInt64Type(_ type: FieldTypeDef) -> Bool {
    switch type {
    case .scalar(let k):
        switch k {
        case .uint64, .fixed64: return true
        default: return false
        }
    default: return false
    }
}

func valToJSON(_ v: Val, type: FieldTypeDef, schema: Schema) -> String {
    switch (v, type) {
    case (.int(let i), _):
        if isInt64Type(type) {
            return "\"\(i)\""
        } else {
            return "\(i)"
        }
    case (.uint(let u), _):
        if isUInt64Type(type) {
            return "\"\(u)\""
        } else {
            return "\(u)"
        }
    case (.bool(let b), _):
        return b ? "true" : "false"
    case (.str(let s), _):
        return escapeJSONString(s)
    case (.bytes(let b), _):
        return "\"" + base64Encode(b) + "\""
    case (.msg(let m), .message(let mn)):
        return msgToJSON(m, msgName: mn, schema: schema)
    case (.enumVal(let e), .enumType(let en)):
        if let enumDef = schema.enums[en], let name = enumDef.byNumber[e] {
            return "\"\(name)\""
        } else {
            return "\(e)"
        }
    default:
        return "null"
    }
}

func msgToJSON(_ msg: DecodedMsg, msgName: String, schema: Schema) -> String {
    guard let msgDef = schema.messages[msgName] else { return "{}" }
    var parts: [String] = []
    let sortedFields = msgDef.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        guard let fd_data = msg.fields[fd.number], fd_data.occurred else { continue }

        if fd.isRepeated {
            if fd_data.repeated.isEmpty { continue }
            let baseType: FieldTypeDef
            switch fd.type {
            case .map(_, let v): baseType = v
            default: baseType = fd.type
            }
            let arr = fd_data.repeated.map { valToJSON($0, type: baseType, schema: schema) }
            parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):[\(arr.joined(separator: ","))]")
        } else if case .map(let keyKind, let valType) = fd.type {
            if fd_data.mapEntries.isEmpty { continue }
            let sorted: [MapEntry]
            if keyKind == .int32 {
                sorted = fd_data.mapEntries.sorted { a, b in
                    let ai: Int32, bi: Int32
                    if case .int(let x) = a.key { ai = x } else { ai = 0 }
                    if case .int(let x) = b.key { bi = x } else { bi = 0 }
                    return ai < bi
                }
            } else {
                sorted = fd_data.mapEntries.sorted { a, b in
                    let as_: String, bs: String
                    if case .str(let x) = a.key { as_ = x } else { as_ = "" }
                    if case .str(let x) = b.key { bs = x } else { bs = "" }
                    return as_.utf8.lexicographicallyPrecedes(bs.utf8)
                }
            }
            let mapParts = sorted.map { entry -> String in
                let keyStr: String
                switch entry.key {
                case .str(let s): keyStr = s
                case .int(let i): keyStr = "\(i)"
                }
                return "\(escapeJSONString(keyStr)):\(valToJSON(entry.value, type: valType, schema: schema))"
            }
            parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):{\(mapParts.joined(separator: ","))}")
        } else {
            guard let val = fd_data.singular else { continue }

            if case .message = fd.type {
                parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
            } else {
                if fd.oneofName != nil {
                    if let on = fd.oneofName, msg.oneofSet[on] == fd.number {
                        parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                    }
                } else if fd.isOptional {
                    parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                } else {
                    if !isDefault(val) {
                        parts.append("\(escapeJSONString(toLowerCamelCase(fd.name))):\(valToJSON(val, type: fd.type, schema: schema))")
                    }
                }
            }
        }
    }

    return "{\(parts.joined(separator: ","))}"
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]

let protoPath = dir + "/schema.proto"
let binPath = dir + "/messages.bin"

guard let protoContent = try? String(contentsOfFile: protoPath, encoding: .utf8) else { exit(0) }
guard let binData = try? Data(contentsOf: URL(fileURLWithPath: binPath)) else { exit(0) }

let toks = tokenize(protoContent)
let parser = ProtoParser(toks)
parser.parse()
let schema = parser.schema

let binBytes = [UInt8](binData)
var outputLines: [String] = []
var bpos = 0

while bpos < binBytes.count {
    var len: UInt64 = 0
    var shift: UInt64 = 0
    var varintOk = false
    for _ in 0..<10 {
        if bpos >= binBytes.count { break }
        let b = binBytes[bpos]; bpos += 1
        len |= UInt64(b & 0x7F) << shift
        if b & 0x80 == 0 { varintOk = true; break }
        shift += 7
    }
    if !varintOk { break }
    let msgLen = Int(len)
    let msgEnd = min(bpos + msgLen, binBytes.count)
    let msgBytes = Array(binBytes[bpos..<msgEnd])
    bpos = msgEnd

    let decoder = Decoder(msgBytes, schema: schema)
    let decoded = decoder.decodeMessage(msgName: schema.rootMessage)
    let json = msgToJSON(decoded, msgName: schema.rootMessage, schema: schema)
    outputLines.append(json)
}

print(outputLines.joined(separator: "\n"))
exit(0)

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

const args = process.argv.slice(2);
const dataDir = args[0];
const baseUrl = args[1];

const clientPath = path.join(dataDir, 'client.json');
const client = JSON.parse(fs.readFileSync(clientPath, 'utf-8'));
const { client_id, client_secret, scope, page_size } = client;

function formUrlEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf-8');
  let result = '';
  for (const byte of bytes) {
    if (
      (byte >= 0x41 && byte <= 0x5A) ||
      (byte >= 0x61 && byte <= 0x7A) ||
      (byte >= 0x30 && byte <= 0x39) ||
      byte === 0x2D || byte === 0x2E || byte === 0x5F || byte === 0x2A
    ) {
      result += String.fromCharCode(byte);
    } else if (byte === 0x20) {
      result += '+';
    } else {
      result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function buildBasicAuth(id: string, secret: string): string {
  const encoded = formUrlEncode(id) + ':' + formUrlEncode(secret);
  const b64 = Buffer.from(encoded, 'ascii').toString('base64');
  return `Basic ${b64}`;
}

function httpRequest(
  method: string,
  url: string,
  headers: Record<string, string>,
  body?: string
): Promise<{ status: number; headers: http.IncomingHttpHeaders; body: string }> {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const reqHeaders: Record<string, string> = {
      Host: urlObj.host,
      ...headers,
    };
    if (body !== undefined) {
      reqHeaders['Content-Length'] = String(Buffer.byteLength(body, 'utf-8'));
    }
    const options: http.RequestOptions = {
      hostname: urlObj.hostname,
      port: urlObj.port || 80,
      path: urlObj.pathname + urlObj.search,
      method,
      headers: reqHeaders,
    };
    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode!,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
    });
    req.on('error', reject);
    if (body !== undefined) {
      req.write(body);
    }
    req.end();
  });
}

function parseAmount(s: string): bigint {
  let negative = false;
  let i = 0;
  if (s[0] === '-') {
    negative = true;
    i = 1;
  }
  let intPart = '';
  while (i < s.length && s[i] !== '.') {
    intPart += s[i];
    i++;
  }
  let fracPart = '';
  if (i < s.length && s[i] === '.') {
    i++;
    while (i < s.length) {
      fracPart += s[i];
      i++;
    }
  }
  while (fracPart.length < 2) fracPart += '0';
  fracPart = fracPart.substring(0, 2);
  const total = BigInt(intPart) * 100n + BigInt(fracPart);
  return negative ? -total : total;
}

function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / 100n;
  const fracPart = abs % 100n;
  const fracStr = fracPart.toString().padStart(2, '0');
  return (negative ? '-' : '') + intPart.toString() + '.' + fracStr;
}

function compareByCodePoints(a: string, b: string): number {
  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');
  const len = Math.min(bufA.length, bufB.length);
  for (let i = 0; i < len; i++) {
    if (bufA[i] !== bufB[i]) return bufA[i] - bufB[i];
  }
  return bufA.length - bufB.length;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function main() {
  const basicAuth = buildBasicAuth(client_id, client_secret);

  let totalOrders = 0;
  let pages = 0;
  let retries = 0;
  let reauths = 0;

  const totals = new Map<string, bigint>();
  const statusCounts = new Map<string, number>();

  async function getToken(): Promise<string> {
    const body = `grant_type=client_credentials&scope=${formUrlEncode(scope)}`;
    const resp = await httpRequest('POST', `${baseUrl}/oauth/token`, {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': basicAuth,
    }, body);
    if (resp.status !== 200) {
      console.log(`ERROR ${resp.status} ${resp.body}`);
      process.exit(0);
    }
    return JSON.parse(resp.body).access_token;
  }

  let accessToken = await getToken();
  let isFirstWithToken = true;

  let cursor: string | null = null;
  let hasCursor = false;

  while (true) {
    let url = `${baseUrl}/orders?limit=${page_size}`;
    if (hasCursor) {
      url += `&cursor=${encodeURIComponent(cursor!)}`;
    }

    const resp = await httpRequest('GET', url, {
      'Authorization': `Bearer ${accessToken}`,
    });

    if (resp.status === 429) {
      retries++;
      const retryAfter = parseInt(resp.headers['retry-after'] as string, 10);
      await sleep(retryAfter * 1000);
      isFirstWithToken = false;
      continue;
    }

    if (resp.status === 503) {
      retries++;
      await sleep(500);
      isFirstWithToken = false;
      continue;
    }

    if (resp.status === 401) {
      if (isFirstWithToken) {
        console.log(`ERROR 401 ${resp.body}`);
        process.exit(0);
      }
      reauths++;
      accessToken = await getToken();
      isFirstWithToken = true;
      continue;
    }

    if (resp.status !== 200) {
      console.log(`ERROR ${resp.status} ${resp.body}`);
      process.exit(0);
    }

    isFirstWithToken = false;
    pages++;

    const pageData = JSON.parse(resp.body);
    const data: any[] = pageData.data;
    const nextCursor = pageData.next_cursor;

    for (const order of data) {
      totalOrders++;
      const status: string = order.status;
      statusCounts.set(status, (statusCounts.get(status) || 0) + 1);

      if (status !== 'cancelled') {
        const name: string = order.customer.name;
        const currency: string = order.currency;
        const amount = parseAmount(order.amount);
        const key = name + '\0' + currency;
        totals.set(key, (totals.get(key) || 0n) + amount);
      }
    }

    if (nextCursor === null) {
      break;
    }

    cursor = nextCursor;
    hasCursor = true;
  }

  const totalEntries: { name: string; currency: string; amount: bigint }[] = [];
  for (const [key, amount] of totals) {
    const sep = key.indexOf('\0');
    const name = key.substring(0, sep);
    const currency = key.substring(sep + 1);
    totalEntries.push({ name, currency, amount });
  }
  totalEntries.sort((a, b) => {
    const cmp = compareByCodePoints(a.name, b.name);
    if (cmp !== 0) return cmp;
    return compareByCodePoints(a.currency, b.currency);
  });

  for (const entry of totalEntries) {
    console.log(`total ${entry.currency} ${formatCents(entry.amount)} ${entry.name}`);
  }

  const statusEntries = [...statusCounts.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  });

  for (const [status, count] of statusEntries) {
    console.log(`status ${status} ${count}`);
  }

  console.log(`orders ${totalOrders} pages ${pages} retries ${retries} reauth ${reauths}`);
}

main();

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};

// ===== Schema Types =====

#[derive(Clone, Debug, PartialEq)]
enum ScalarType {
    Int32, Int64, UInt32, UInt64, SInt32, SInt64,
    Bool, Str, Bytes, Fixed32, Fixed64, SFixed32, SFixed64,
}

#[derive(Clone, Debug)]
enum FieldType {
    Scalar(ScalarType),
    Named(String),
    Map { key_type: ScalarType, value_type: Box<FieldType> },
}

#[derive(Clone, Debug, PartialEq)]
enum Label { Singular, Optional, Repeated, Map }

#[derive(Clone, Debug)]
struct FieldDef {
    name: String,
    number: u32,
    field_type: FieldType,
    label: Label,
    oneof: Option<String>,
}

#[derive(Clone, Debug)]
struct MessageDef {
    name: String,
    fields: Vec<FieldDef>,
    oneofs: HashMap<String, Vec<u32>>,
}

#[derive(Clone, Debug)]
struct EnumDef {
    name: String,
    values: Vec<(i32, String)>,
}

struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_type: String,
}

// ===== Decoded Values =====

#[derive(Clone, Debug)]
enum DecodedValue {
    Int32(i32),
    Int64(i64),
    UInt32(u32),
    UInt64(u64),
    SInt32(i32),
    SInt64(i64),
    Bool(bool),
    Str(String),
    Bytes(Vec<u8>),
    Fixed32(u32),
    Fixed64(u64),
    SFixed32(i32),
    SFixed64(i64),
    Enum(i32),
    Message(DecodedMessage),
}

#[derive(Clone, Debug)]
enum FieldState {
    Singular { occurred: bool, value: Option<DecodedValue> },
    Repeated { values: Vec<DecodedValue> },
    Map { entries: Vec<(DecodedValue, DecodedValue)> },
}

#[derive(Clone, Debug)]
struct DecodedMessage {
    fields: HashMap<u32, FieldState>,
    active_oneofs: HashMap<String, u32>,
}

// ===== Parser =====

struct Parser {
    chars: Vec<char>,
    pos: usize,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_type: Option<String>,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
            messages: HashMap::new(),
            enums: HashMap::new(),
            root_type: None,
        }
    }

    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' {
                if self.chars[self.pos + 1] == '/' {
                    self.pos += 2;
                    while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                        self.pos += 1;
                    }
                } else if self.chars[self.pos + 1] == '*' {
                    self.pos += 2;
                    while self.pos + 1 < self.chars.len() {
                        if self.chars[self.pos] == '*' && self.chars[self.pos + 1] == '/' {
                            self.pos += 2;
                            break;
                        }
                        self.pos += 1;
                    }
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }

    fn peek_word(&mut self) -> Option<String> {
        self.skip_ws();
        if self.pos < self.chars.len() && (self.chars[self.pos].is_alphabetic() || self.chars[self.pos] == '_') {
            let start = self.pos;
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
                self.pos += 1;
            }
            Some(self.chars[start..self.pos].iter().collect())
        } else {
            None
        }
    }

    fn peek_char(&mut self) -> Option<char> {
        self.skip_ws();
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn expect_word(&mut self) -> String {
        self.skip_ws();
        let start = self.pos;
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
            self.pos += 1;
        }
        self.chars[start..self.pos].iter().collect()
    }

    fn expect_char(&mut self, c: char) {
        self.skip_ws();
        assert_eq!(self.chars[self.pos], c, "expected '{}' at pos {}", c, self.pos);
        self.pos += 1;
    }

    fn expect_int(&mut self) -> i64 {
        self.skip_ws();
        let mut neg = false;
        if self.pos < self.chars.len() && self.chars[self.pos] == '-' {
            neg = true;
            self.pos += 1;
        }
        let start = self.pos;
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        let n: i64 = s.parse().unwrap();
        if neg { -n } else { n }
    }

    fn expect_string(&mut self) -> String {
        self.skip_ws();
        assert_eq!(self.chars[self.pos], '"');
        self.pos += 1;
        let start = self.pos;
        while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
            self.pos += 1;
        }
        let s = self.chars[start..self.pos].iter().collect();
        self.pos += 1;
        s
    }

    fn skip_value(&mut self) {
        self.skip_ws();
        if self.chars[self.pos] == '"' {
            self.expect_string();
        } else if self.chars[self.pos] == '-' || self.chars[self.pos].is_ascii_digit() {
            self.expect_int();
        } else if self.chars[self.pos] == '{' {
            // skip brace-delimited value
            self.pos += 1;
            let mut depth = 1;
            while depth > 0 && self.pos < self.chars.len() {
                if self.chars[self.pos] == '{' { depth += 1; }
                else if self.chars[self.pos] == '}' { depth -= 1; }
                self.pos += 1;
            }
        } else {
            self.expect_word();
        }
    }

    fn skip_option_stmt(&mut self) {
        // already consumed "option"
        // skip name (possibly dotted)
        self.skip_ws();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.' || self.chars[self.pos] == '(' || self.chars[self.pos] == ')') {
            self.pos += 1;
        }
        self.expect_char('=');
        self.skip_value();
        self.expect_char(';');
    }

    fn skip_field_options(&mut self) {
        // skip [name = value, ...]
        self.expect_char('[');
        loop {
            self.skip_ws();
            if self.chars[self.pos] == ']' {
                self.pos += 1;
                break;
            }
            // name
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.' || self.chars[self.pos] == '(' || self.chars[self.pos] == ')') {
                self.pos += 1;
            }
            self.expect_char('=');
            self.skip_value();
            self.skip_ws();
            if self.chars[self.pos] == ',' {
                self.pos += 1;
            }
        }
    }

    fn parse_file(&mut self) {
        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            let word = self.peek_word();
            match word.as_deref() {
                Some("syntax") => {
                    self.expect_word();
                    self.expect_char('=');
                    self.expect_string();
                    self.expect_char(';');
                }
                Some("package") => {
                    self.expect_word();
                    self.skip_ws();
                    while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.') {
                        self.pos += 1;
                    }
                    self.expect_char(';');
                }
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("message") => {
                    self.expect_word();
                    let name = self.expect_word();
                    if self.root_type.is_none() {
                        self.root_type = Some(name.clone());
                    }
                    self.parse_message(&name);
                }
                Some("enum") => {
                    self.expect_word();
                    let name = self.expect_word();
                    self.parse_enum(&name);
                }
                _ => {
                    // skip unknown
                    if self.pos < self.chars.len() {
                        self.pos += 1;
                    }
                }
            }
        }
    }

    fn parse_message(&mut self, name: &str) {
        self.expect_char('{');
        let mut fields: Vec<FieldDef> = Vec::new();
        let mut oneofs: HashMap<String, Vec<u32>> = HashMap::new();

        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            if self.chars[self.pos] == '}' {
                self.pos += 1;
                break;
            }
            let word = self.peek_word();
            match word.as_deref() {
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("message") => {
                    self.expect_word();
                    let nested_name = self.expect_word();
                    self.parse_message(&nested_name);
                }
                Some("enum") => {
                    self.expect_word();
                    let nested_name = self.expect_word();
                    self.parse_enum(&nested_name);
                }
                Some("oneof") => {
                    self.expect_word();
                    let oneof_name = self.expect_word();
                    self.expect_char('{');
                    let mut oneof_fields = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.chars[self.pos] == '}' {
                            self.pos += 1;
                            break;
                        }
                        let f = self.parse_field(Some(oneof_name.clone()));
                        oneof_fields.push(f.number);
                        fields.push(f);
                    }
                    oneofs.insert(oneof_name, oneof_fields);
                }
                Some("reserved") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        if self.chars[self.pos] == '"' {
                            self.pos += 1;
                            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                                self.pos += 1;
                            }
                            self.pos += 1;
                        } else {
                            self.pos += 1;
                        }
                    }
                    self.pos += 1; // skip ';'
                }
                Some("extensions") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        self.pos += 1;
                    }
                    self.pos += 1;
                }
                _ => {
                    let f = self.parse_field(None);
                    fields.push(f);
                }
            }
        }

        self.messages.insert(name.to_string(), MessageDef {
            name: name.to_string(),
            fields,
            oneofs,
        });
    }

    fn parse_field(&mut self, oneof_name: Option<String>) -> FieldDef {
        self.skip_ws();
        let word = self.peek_word().unwrap();

        if word == "map" {
            self.expect_word();
            self.expect_char('<');
            let key_type_str = self.expect_word();
            self.expect_char(',');
            let value_type_str = self.expect_word();
            self.expect_char('>');
            let name = self.expect_word();
            self.expect_char('=');
            let number = self.expect_int() as u32;
            if self.peek_char() == Some('[') {
                self.skip_field_options();
            }
            self.expect_char(';');
            let key_type = parse_scalar_type(&key_type_str);
            let value_type = FieldType::Named(value_type_str);
            return FieldDef {
                name, number,
                field_type: FieldType::Map { key_type, value_type: Box::new(value_type) },
                label: Label::Map,
                oneof: oneof_name,
            };
        }

        let label = match word.as_str() {
            "repeated" => { self.expect_word(); Label::Repeated }
            "optional" => { self.expect_word(); Label::Optional }
            _ => Label::Singular,
        };

        let type_str = self.expect_word();
        let name = self.expect_word();
        self.expect_char('=');
        let number = self.expect_int() as u32;
        if self.peek_char() == Some('[') {
            self.skip_field_options();
        }
        self.expect_char(';');

        let field_type = if let Some(st) = try_parse_scalar_type(&type_str) {
            FieldType::Scalar(st)
        } else {
            FieldType::Named(type_str)
        };

        FieldDef { name, number, field_type, label, oneof: oneof_name }
    }

    fn parse_enum(&mut self, name: &str) {
        self.expect_char('{');
        let mut values: Vec<(i32, String)> = Vec::new();

        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            if self.chars[self.pos] == '}' {
                self.pos += 1;
                break;
            }
            let word = self.peek_word();
            match word.as_deref() {
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("reserved") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        if self.chars[self.pos] == '"' {
                            self.pos += 1;
                            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                                self.pos += 1;
                            }
                            self.pos += 1;
                        } else {
                            self.pos += 1;
                        }
                    }
                    self.pos += 1;
                }
                _ => {
                    let value_name = self.expect_word();
                    self.expect_char('=');
                    let value_num = self.expect_int() as i32;
                    if self.peek_char() == Some('[') {
                        self.skip_field_options();
                    }
                    self.expect_char(';');
                    values.push((value_num, value_name));
                }
            }
        }

        self.enums.insert(name.to_string(), EnumDef { name: name.to_string(), values });
    }
}

fn try_parse_scalar_type(s: &str) -> Option<ScalarType> {
    match s {
        "int32" => Some(ScalarType::Int32),
        "int64" => Some(ScalarType::Int64),
        "uint32" => Some(ScalarType::UInt32),
        "uint64" => Some(ScalarType::UInt64),
        "sint32" => Some(ScalarType::SInt32),
        "sint64" => Some(ScalarType::SInt64),
        "bool" => Some(ScalarType::Bool),
        "string" => Some(ScalarType::Str),
        "bytes" => Some(ScalarType::Bytes),
        "fixed32" => Some(ScalarType::Fixed32),
        "fixed64" => Some(ScalarType::Fixed64),
        "sfixed32" => Some(ScalarType::SFixed32),
        "sfixed64" => Some(ScalarType::SFixed64),
        _ => None,
    }
}

fn parse_scalar_type(s: &str) -> ScalarType {
    try_parse_scalar_type(s).unwrap_or_else(|| panic!("unknown scalar type: {}", s))
}

// ===== Decoder =====

fn read_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        let byte = data[*pos];
        *pos += 1;
        if shift < 64 {
            result |= ((byte & 0x7F) as u64) << shift;
        }
        if byte & 0x80 == 0 { break; }
        shift += 7;
    }
    result
}

fn zigzag32(n: u32) -> i32 {
    ((n >> 1) as i32) ^ (0u32.wrapping_sub(n & 1) as i32)
}

fn zigzag64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ (0u64.wrapping_sub(n & 1) as i64)
}

fn is_packed_type(ft: &FieldType) -> bool {
    match ft {
        FieldType::Scalar(st) => matches!(st,
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool |
            ScalarType::Fixed32 | ScalarType::Fixed64 | ScalarType::SFixed32 | ScalarType::SFixed64
        ),
        FieldType::Named(_) => false, // enum could be packed, handled separately
        FieldType::Map { .. } => false,
    }
}

fn is_enum_type(ft: &FieldType, schema: &Schema) -> bool {
    match ft {
        FieldType::Named(name) => schema.enums.contains_key(name),
        _ => false,
    }
}

fn is_message_type(ft: &FieldType, schema: &Schema) -> bool {
    match ft {
        FieldType::Named(name) => schema.messages.contains_key(name),
        _ => false,
    }
}

fn get_named_type(ft: &FieldType) -> &str {
    match ft {
        FieldType::Named(name) => name,
        _ => unreachable!(),
    }
}

fn decode_scalar_from_varint(ft: &FieldType, raw: u64) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Int32) => DecodedValue::Int32(raw as u32 as i32),
        FieldType::Scalar(ScalarType::Int64) => DecodedValue::Int64(raw as i64),
        FieldType::Scalar(ScalarType::UInt32) => DecodedValue::UInt32(raw as u32),
        FieldType::Scalar(ScalarType::UInt64) => DecodedValue::UInt64(raw),
        FieldType::Scalar(ScalarType::SInt32) => DecodedValue::SInt32(zigzag32(raw as u32)),
        FieldType::Scalar(ScalarType::SInt64) => DecodedValue::SInt64(zigzag64(raw)),
        FieldType::Scalar(ScalarType::Bool) => DecodedValue::Bool(raw != 0),
        FieldType::Named(_) => DecodedValue::Enum(raw as u32 as i32), // enum
        _ => unreachable!(),
    }
}

fn decode_scalar_from_fixed32(ft: &FieldType, raw: u32) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Fixed32) => DecodedValue::Fixed32(raw),
        FieldType::Scalar(ScalarType::SFixed32) => DecodedValue::SFixed32(raw as i32),
        _ => unreachable!(),
    }
}

fn decode_scalar_from_fixed64(ft: &FieldType, raw: u64) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Fixed64) => DecodedValue::Fixed64(raw),
        FieldType::Scalar(ScalarType::SFixed64) => DecodedValue::SFixed64(raw as i64),
        _ => unreachable!(),
    }
}

fn decode_value_for_type(data: &[u8], pos: &mut usize, ft: &FieldType, wire_type: u8, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool => {
                let raw = read_varint(data, pos);
                decode_scalar_from_varint(ft, raw)
            }
            ScalarType::Str => {
                let len = read_varint(data, pos) as usize;
                let bytes = &data[*pos..*pos + len];
                *pos += len;
                DecodedValue::Str(String::from_utf8_lossy(bytes).into_owned())
            }
            ScalarType::Bytes => {
                let len = read_varint(data, pos) as usize;
                let bytes = data[*pos..*pos + len].to_vec();
                *pos += len;
                DecodedValue::Bytes(bytes)
            }
            ScalarType::Fixed32 | ScalarType::SFixed32 => {
                let raw = u32::from_le_bytes([data[*pos], data[*pos+1], data[*pos+2], data[*pos+3]]);
                *pos += 4;
                decode_scalar_from_fixed32(ft, raw)
            }
            ScalarType::Fixed64 | ScalarType::SFixed64 => {
                let raw = u64::from_le_bytes([
                    data[*pos], data[*pos+1], data[*pos+2], data[*pos+3],
                    data[*pos+4], data[*pos+5], data[*pos+6], data[*pos+7],
                ]);
                *pos += 8;
                decode_scalar_from_fixed64(ft, raw)
            }
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                let raw = read_varint(data, pos);
                DecodedValue::Enum(raw as u32 as i32)
            } else {
                // message
                let len = read_varint(data, pos) as usize;
                let sub_data = &data[*pos..*pos + len];
                *pos += len;
                DecodedValue::Message(decode_message_bytes(sub_data, name, schema))
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn skip_field(data: &[u8], pos: &mut usize, wire_type: u8, field_number: u32) {
    match wire_type {
        0 => { read_varint(data, pos); }
        1 => { *pos += 8; }
        2 => { let len = read_varint(data, pos) as usize; *pos += len; }
        5 => { *pos += 4; }
        3 => {
            // group start
            loop {
                let key = read_varint(data, pos);
                let fn2 = (key >> 3) as u32;
                let wt2 = (key & 7) as u8;
                if wt2 == 4 && fn2 == field_number { break; }
                skip_field(data, pos, wt2, fn2);
            }
        }
        4 => { /* shouldn't reach here normally */ }
        _ => {}
    }
}

fn decode_message_bytes(data: &[u8], msg_name: &str, schema: &Schema) -> DecodedMessage {
    let msg_def = &schema.messages[msg_name];
    let field_map: HashMap<u32, &FieldDef> = msg_def.fields.iter().map(|f| (f.number, f)).collect();

    let mut result = DecodedMessage {
        fields: HashMap::new(),
        active_oneofs: HashMap::new(),
    };

    let mut pos = 0;
    while pos < data.len() {
        let key = read_varint(data, &mut pos);
        let field_number = (key >> 3) as u32;
        let wire_type = (key & 7) as u8;

        if let Some(&field_def) = field_map.get(&field_number) {
            decode_field(data, &mut pos, field_def, wire_type, &mut result, schema);
        } else {
            skip_field(data, &mut pos, wire_type, field_number);
        }
    }

    result
}

fn decode_field(data: &[u8], pos: &mut usize, field_def: &FieldDef, wire_type: u8,
                result: &mut DecodedMessage, schema: &Schema) {
    match field_def.label {
        Label::Singular | Label::Optional => {
            // Check if in oneof
            if let Some(ref oneof_name) = field_def.oneof {
                let current_active = result.active_oneofs.get(oneof_name).copied();
                if current_active != Some(field_def.number) {
                    // Clear previous member
                    if let Some(prev) = current_active {
                        result.fields.remove(&prev);
                    }
                    result.active_oneofs.insert(oneof_name.clone(), field_def.number);
                    // Start fresh
                    let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                } else {
                    // Same member, merge if message
                    if is_message_type(&field_def.field_type, schema) {
                        let new_val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                        if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = result.fields.get_mut(&field_def.number) {
                            if let DecodedValue::Message(new_msg) = new_val {
                                merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                            }
                        }
                    } else {
                        let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                        result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                    }
                }
            } else {
                // Not in oneof
                if is_message_type(&field_def.field_type, schema) {
                    let new_val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = result.fields.get_mut(&field_def.number) {
                        if let DecodedValue::Message(new_msg) = new_val {
                            merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                        }
                    } else {
                        result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(new_val) });
                    }
                } else {
                    let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                }
            }
        }
        Label::Repeated => {
            // Check for packed encoding
            let is_packed = wire_type == 2 && (is_packed_type(&field_def.field_type) || is_enum_type(&field_def.field_type, schema));
            if is_packed {
                let len = read_varint(data, pos) as usize;
                let end = *pos + len;
                let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    while *pos < end {
                        let val = decode_packed_element(data, pos, &field_def.field_type, schema);
                        values.push(val);
                    }
                }
            } else {
                let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    values.push(val);
                }
            }
        }
        Label::Map => {
            // Decode map entry
            let (key_type, value_type) = match &field_def.field_type {
                FieldType::Map { key_type, value_type } => (key_type.clone(), (**value_type).clone()),
                _ => unreachable!(),
            };
            let len = read_varint(data, pos) as usize;
            let end = *pos + len;

            let mut key_val: Option<DecodedValue> = None;
            let mut val_val: Option<DecodedValue> = None;

            while *pos < end {
                let k = read_varint(data, pos);
                let fn2 = (k >> 3) as u32;
                let wt2 = (k & 7) as u8;
                match fn2 {
                    1 => { key_val = Some(decode_value_for_type(data, pos, &FieldType::Scalar(key_type.clone()), wt2, schema)); }
                    2 => { val_val = Some(decode_value_for_type(data, pos, &value_type, wt2, schema)); }
                    _ => { skip_field(data, pos, wt2, fn2); }
                }
            }

            let default_key = match key_type {
                ScalarType::Str => DecodedValue::Str(String::new()),
                ScalarType::Int32 => DecodedValue::Int32(0),
                _ => unreachable!(),
            };
            let default_value = default_value_for_type(&value_type, schema);

            let kv = key_val.unwrap_or(default_key);
            let vv = val_val.unwrap_or(default_value);

            let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Map { entries: Vec::new() });
            if let FieldState::Map { entries } = entry {
                // Replace if key exists, else append
                let mut found = false;
                for e in entries.iter_mut() {
                    if decoded_values_equal(&e.0, &kv) {
                        e.1 = vv.clone();
                        found = true;
                        break;
                    }
                }
                if !found {
                    entries.push((kv, vv));
                }
            }
        }
    }
}

fn decode_packed_element(data: &[u8], pos: &mut usize, ft: &FieldType, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool => {
                let raw = read_varint(data, pos);
                decode_scalar_from_varint(ft, raw)
            }
            ScalarType::Fixed32 | ScalarType::SFixed32 => {
                let raw = u32::from_le_bytes([data[*pos], data[*pos+1], data[*pos+2], data[*pos+3]]);
                *pos += 4;
                decode_scalar_from_fixed32(ft, raw)
            }
            ScalarType::Fixed64 | ScalarType::SFixed64 => {
                let raw = u64::from_le_bytes([
                    data[*pos], data[*pos+1], data[*pos+2], data[*pos+3],
                    data[*pos+4], data[*pos+5], data[*pos+6], data[*pos+7],
                ]);
                *pos += 8;
                decode_scalar_from_fixed64(ft, raw)
            }
            _ => unreachable!(),
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                let raw = read_varint(data, pos);
                DecodedValue::Enum(raw as u32 as i32)
            } else {
                unreachable!()
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn default_value_for_type(ft: &FieldType, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 => DecodedValue::Int32(0),
            ScalarType::Int64 => DecodedValue::Int64(0),
            ScalarType::UInt32 => DecodedValue::UInt32(0),
            ScalarType::UInt64 => DecodedValue::UInt64(0),
            ScalarType::SInt32 => DecodedValue::SInt32(0),
            ScalarType::SInt64 => DecodedValue::SInt64(0),
            ScalarType::Bool => DecodedValue::Bool(false),
            ScalarType::Str => DecodedValue::Str(String::new()),
            ScalarType::Bytes => DecodedValue::Bytes(Vec::new()),
            ScalarType::Fixed32 => DecodedValue::Fixed32(0),
            ScalarType::Fixed64 => DecodedValue::Fixed64(0),
            ScalarType::SFixed32 => DecodedValue::SFixed32(0),
            ScalarType::SFixed64 => DecodedValue::SFixed64(0),
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                DecodedValue::Enum(0)
            } else {
                DecodedValue::Message(DecodedMessage { fields: HashMap::new(), active_oneofs: HashMap::new() })
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn decoded_values_equal(a: &DecodedValue, b: &DecodedValue) -> bool {
    match (a, b) {
        (DecodedValue::Str(x), DecodedValue::Str(y)) => x == y,
        (DecodedValue::Int32(x), DecodedValue::Int32(y)) => x == y,
        _ => false,
    }
}

fn merge_messages(target: &mut DecodedMessage, source: DecodedMessage, msg_name: &str, schema: &Schema) {
    let msg_def = &schema.messages[msg_name];
    let field_map: HashMap<u32, &FieldDef> = msg_def.fields.iter().map(|f| (f.number, f)).collect();

    for (field_num, source_state) in source.fields {
        let field_def = match field_map.get(&field_num) {
            Some(f) => *f,
            None => continue,
        };

        // Handle oneof clearing
        if let Some(ref oneof_name) = field_def.oneof {
            if let Some(&current_active) = target.active_oneofs.get(oneof_name) {
                if current_active != field_num {
                    target.fields.remove(&current_active);
                }
            }
            target.active_oneofs.insert(oneof_name.clone(), field_num);
        }

        match (&field_def.label, source_state) {
            (Label::Singular | Label::Optional, FieldState::Singular { value: Some(sv), .. }) => {
                if is_message_type(&field_def.field_type, schema) {
                    let mut merged = false;
                    if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = target.fields.get_mut(&field_num) {
                        if let DecodedValue::Message(new_msg) = sv {
                            merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                            merged = true;
                        }
                    }
                    if !merged {
                        target.fields.insert(field_num, FieldState::Singular { occurred: true, value: Some(sv) });
                    }
                } else {
                    target.fields.insert(field_num, FieldState::Singular { occurred: true, value: Some(sv) });
                }
            }
            (Label::Repeated, FieldState::Repeated { values: new_vals }) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    values.extend(new_vals);
                }
            }
            (Label::Map, FieldState::Map { entries: new_entries }) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Map { entries: Vec::new() });
                if let FieldState::Map { entries } = entry {
                    for (k, v) in new_entries {
                        let mut found = false;
                        for e in entries.iter_mut() {
                            if decoded_values_equal(&e.0, &k) {
                                e.1 = v.clone();
                                found = true;
                                break;
                            }
                        }
                        if !found {
                            entries.push((k, v));
                        }
                    }
                }
            }
            _ => {}
        }
    }
}

// ===== JSON Output =====

fn to_lower_camel_case(name: &str) -> String {
    let mut result = String::new();
    let mut chars = name.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '_' {
            if let Some(&next) = chars.peek() {
                if next.is_ascii_lowercase() {
                    result.push(next.to_ascii_uppercase());
                    chars.next();
                }
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn json_escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{0009}' => result.push_str("\\t"),
            '\u{000A}' => result.push_str("\\n"),
            '\u{000C}' => result.push_str("\\f"),
            '\u{000D}' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

fn is_default_value(val: &DecodedValue) -> bool {
    match val {
        DecodedValue::Int32(v) => *v == 0,
        DecodedValue::Int64(v) => *v == 0,
        DecodedValue::UInt32(v) => *v == 0,
        DecodedValue::UInt64(v) => *v == 0,
        DecodedValue::SInt32(v) => *v == 0,
        DecodedValue::SInt64(v) => *v == 0,
        DecodedValue::Bool(v) => !*v,
        DecodedValue::Str(v) => v.is_empty(),
        DecodedValue::Bytes(v) => v.is_empty(),
        DecodedValue::Fixed32(v) => *v == 0,
        DecodedValue::Fixed64(v) => *v == 0,
        DecodedValue::SFixed32(v) => *v == 0,
        DecodedValue::SFixed64(v) => *v == 0,
        DecodedValue::Enum(v) => *v == 0,
        DecodedValue::Message(_) => false, // messages are always printed if occurred
    }
}

fn value_to_json(val: &DecodedValue, schema: &Schema) -> String {
    match val {
        DecodedValue::Int32(v) => format!("{}", v),
        DecodedValue::Int64(v) => format!("\"{}\"", v),
        DecodedValue::UInt32(v) => format!("{}", v),
        DecodedValue::UInt64(v) => format!("\"{}\"", v),
        DecodedValue::SInt32(v) => format!("{}", v),
        DecodedValue::SInt64(v) => format!("\"{}\"", v),
        DecodedValue::Bool(v) => if *v { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(v) => format!("\"{}\"", json_escape(v)),
        DecodedValue::Bytes(v) => format!("\"{}\"", base64_encode(v)),
        DecodedValue::Fixed32(v) => format!("{}", v),
        DecodedValue::Fixed64(v) => format!("\"{}\"", v),
        DecodedValue::SFixed32(v) => format!("{}", v),
        DecodedValue::SFixed64(v) => format!("\"{}\"", v),
        DecodedValue::Enum(v) => {
            // This shouldn't be called directly without enum name context
            format!("{}", v)
        }
        DecodedValue::Message(m) => {
            // This shouldn't be called directly without message name context
            format!("{}", message_to_json(m, "", schema))
        }
    }
}

fn value_to_json_with_type(val: &DecodedValue, ft: &FieldType, schema: &Schema) -> String {
    match val {
        DecodedValue::Int32(v) => format!("{}", v),
        DecodedValue::Int64(v) => format!("\"{}\"", v),
        DecodedValue::UInt32(v) => format!("{}", v),
        DecodedValue::UInt64(v) => format!("\"{}\"", v),
        DecodedValue::SInt32(v) => format!("{}", v),
        DecodedValue::SInt64(v) => format!("\"{}\"", v),
        DecodedValue::Bool(v) => if *v { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(v) => format!("\"{}\"", json_escape(v)),
        DecodedValue::Bytes(v) => format!("\"{}\"", base64_encode(v)),
        DecodedValue::Fixed32(v) => format!("{}", v),
        DecodedValue::Fixed64(v) => format!("\"{}\"", v),
        DecodedValue::SFixed32(v) => format!("{}", v),
        DecodedValue::SFixed64(v) => format!("\"{}\"", v),
        DecodedValue::Enum(v) => {
            if let FieldType::Named(name) = ft {
                if let Some(enum_def) = schema.enums.get(name) {
                    for (num, val_name) in &enum_def.values {
                        if *num == *v {
                            return format!("\"{}\"", json_escape(val_name));
                        }
                    }
                }
            }
            format!("{}", v)
        }
        DecodedValue::Message(m) => {
            if let FieldType::Named(name) = ft {
                message_to_json(m, name, schema)
            } else {
                "{}".to_string()
            }
        }
    }
}

fn message_to_json(msg: &DecodedMessage, msg_name: &str, schema: &Schema) -> String {
    let msg_def = match schema.messages.get(msg_name) {
        Some(d) => d,
        None => return "{}".to_string(),
    };

    let mut sorted_fields: Vec<&FieldDef> = msg_def.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    let mut parts: Vec<String> = Vec::new();

    for field_def in sorted_fields {
        let state = match msg.fields.get(&field_def.number) {
            Some(s) => s,
            None => continue,
        };

        let should_print = match (&field_def.label, state) {
            (Label::Singular, FieldState::Singular { occurred, value }) => {
                if !*occurred { continue; }
                // Check if in oneof
                if field_def.oneof.is_some() {
                    // Print if it's the active member
                    if let Some(ref oneof_name) = field_def.oneof {
                        msg.active_oneofs.get(oneof_name) == Some(&field_def.number)
                    } else {
                        false
                    }
                } else {
                    // Not optional, not in oneof: omit if default
                    if let Some(val) = value {
                        !is_default_value(val)
                    } else {
                        false
                    }
                }
            }
            (Label::Optional, FieldState::Singular { occurred, .. }) => {
                *occurred
            }
            (Label::Repeated, FieldState::Repeated { values }) => {
                !values.is_empty()
            }
            (Label::Map, FieldState::Map { entries }) => {
                !entries.is_empty()
            }
            _ => false,
        };

        if !should_print { continue; }

        let json_name = to_lower_camel_case(&field_def.name);

        let json_value = match state {
            FieldState::Singular { value: Some(val), .. } => {
                value_to_json_with_type(val, &field_def.field_type, schema)
            }
            FieldState::Singular { value: None, .. } => continue,
            FieldState::Repeated { values } => {
                let items: Vec<String> = values.iter()
                    .map(|v| value_to_json_with_type(v, &field_def.field_type, schema))
                    .collect();
                format!("[{}]", items.join(","))
            }
            FieldState::Map { entries } => {
                // Deduplicate by key (last wins) - already done during decode
                // Sort by key
                let (key_type, value_type) = match &field_def.field_type {
                    FieldType::Map { key_type, value_type } => (key_type.clone(), (**value_type).clone()),
                    _ => unreachable!(),
                };

                let mut sorted_entries: Vec<&(DecodedValue, DecodedValue)> = entries.iter().collect();
                match key_type {
                    ScalarType::Str => {
                        sorted_entries.sort_by(|a, b| {
                            let ka = match &a.0 { DecodedValue::Str(s) => s.as_str(), _ => "" };
                            let kb = match &b.0 { DecodedValue::Str(s) => s.as_str(), _ => "" };
                            ka.cmp(kb)
                        });
                    }
                    ScalarType::Int32 => {
                        sorted_entries.sort_by(|a, b| {
                            let ka = match &a.0 { DecodedValue::Int32(v) => *v, _ => 0 };
                            let kb = match &b.0 { DecodedValue::Int32(v) => *v, _ => 0 };
                            ka.cmp(&kb)
                        });
                    }
                    _ => {}
                }

                let items: Vec<String> = sorted_entries.iter().map(|(k, v)| {
                    let key_str = match k {
                        DecodedValue::Str(s) => json_escape(s),
                        DecodedValue::Int32(n) => format!("{}", n),
                        _ => String::new(),
                    };
                    let val_str = value_to_json_with_type(v, &value_type, schema);
                    format!("\"{}\":{}", key_str, val_str)
                }).collect();
                format!("{{{}}}", items.join(","))
            }
        };

        parts.push(format!("\"{}\":{}", json_name, json_value));
    }

    format!("{{{}}}", parts.join(","))
}

// ===== Main =====

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_path = format!("{}/schema.proto", dir);
    let messages_path = format!("{}/messages.bin", dir);

    let schema_str = fs::read_to_string(&schema_path).unwrap();
    let messages_data = fs::read(&messages_path).unwrap();

    // Parse schema
    let mut parser = Parser::new(&schema_str);
    parser.parse_file();

    let schema = Schema {
        messages: parser.messages,
        enums: parser.enums,
        root_type: parser.root_type.unwrap_or_default(),
    };

    // Read records
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let mut pos = 0;
    while pos < messages_data.len() {
        let len = read_varint(&messages_data, &mut pos) as usize;
        let record_data = &messages_data[pos..pos + len];
        pos += len;

        let decoded = decode_message_bytes(record_data, &schema.root_type, &schema);
        let json = message_to_json(&decoded, &schema.root_type, &schema);
        writeln!(out, "{}", json).unwrap();
    }

    out.flush().unwrap();
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};

// ===== Schema Types =====

#[derive(Clone, Debug, PartialEq)]
enum ScalarType {
    Int32, Int64, UInt32, UInt64, SInt32, SInt64,
    Bool, Str, Bytes, Fixed32, Fixed64, SFixed32, SFixed64,
}

#[derive(Clone, Debug)]
enum FieldType {
    Scalar(ScalarType),
    Named(String),
    Map { key_type: ScalarType, value_type: Box<FieldType> },
}

#[derive(Clone, Debug, PartialEq)]
enum Label { Singular, Optional, Repeated, Map }

#[derive(Clone, Debug)]
struct FieldDef {
    name: String,
    number: u32,
    field_type: FieldType,
    label: Label,
    oneof: Option<String>,
}

#[derive(Clone, Debug)]
struct MessageDef {
    name: String,
    fields: Vec<FieldDef>,
    oneofs: HashMap<String, Vec<u32>>,
}

#[derive(Clone, Debug)]
struct EnumDef {
    name: String,
    values: Vec<(i32, String)>,
}

struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_type: String,
}

// ===== Decoded Values =====

#[derive(Clone, Debug)]
enum DecodedValue {
    Int32(i32),
    Int64(i64),
    UInt32(u32),
    UInt64(u64),
    SInt32(i32),
    SInt64(i64),
    Bool(bool),
    Str(String),
    Bytes(Vec<u8>),
    Fixed32(u32),
    Fixed64(u64),
    SFixed32(i32),
    SFixed64(i64),
    Enum(i32),
    Message(DecodedMessage),
}

#[derive(Clone, Debug)]
enum FieldState {
    Singular { occurred: bool, value: Option<DecodedValue> },
    Repeated { values: Vec<DecodedValue> },
    Map { entries: Vec<(DecodedValue, DecodedValue)> },
}

#[derive(Clone, Debug)]
struct DecodedMessage {
    fields: HashMap<u32, FieldState>,
    active_oneofs: HashMap<String, u32>,
}

// ===== Parser =====

struct Parser {
    chars: Vec<char>,
    pos: usize,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_type: Option<String>,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
            messages: HashMap::new(),
            enums: HashMap::new(),
            root_type: None,
        }
    }

    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' {
                if self.chars[self.pos + 1] == '/' {
                    self.pos += 2;
                    while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                        self.pos += 1;
                    }
                } else if self.chars[self.pos + 1] == '*' {
                    self.pos += 2;
                    while self.pos + 1 < self.chars.len() {
                        if self.chars[self.pos] == '*' && self.chars[self.pos + 1] == '/' {
                            self.pos += 2;
                            break;
                        }
                        self.pos += 1;
                    }
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }

    fn peek_word(&mut self) -> Option<String> {
        self.skip_ws();
        if self.pos < self.chars.len() && (self.chars[self.pos].is_alphabetic() || self.chars[self.pos] == '_') {
            let start = self.pos;
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
                self.pos += 1;
            }
            Some(self.chars[start..self.pos].iter().collect())
        } else {
            None
        }
    }

    fn peek_char(&mut self) -> Option<char> {
        self.skip_ws();
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn expect_word(&mut self) -> String {
        self.skip_ws();
        let start = self.pos;
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
            self.pos += 1;
        }
        self.chars[start..self.pos].iter().collect()
    }

    fn expect_char(&mut self, c: char) {
        self.skip_ws();
        assert_eq!(self.chars[self.pos], c, "expected '{}' at pos {}", c, self.pos);
        self.pos += 1;
    }

    fn expect_int(&mut self) -> i64 {
        self.skip_ws();
        let mut neg = false;
        if self.pos < self.chars.len() && self.chars[self.pos] == '-' {
            neg = true;
            self.pos += 1;
        }
        let start = self.pos;
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        let n: i64 = s.parse().unwrap();
        if neg { -n } else { n }
    }

    fn expect_string(&mut self) -> String {
        self.skip_ws();
        assert_eq!(self.chars[self.pos], '"');
        self.pos += 1;
        let start = self.pos;
        while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
            self.pos += 1;
        }
        let s = self.chars[start..self.pos].iter().collect();
        self.pos += 1;
        s
    }

    fn skip_value(&mut self) {
        self.skip_ws();
        if self.chars[self.pos] == '"' {
            self.expect_string();
        } else if self.chars[self.pos] == '-' || self.chars[self.pos].is_ascii_digit() {
            self.expect_int();
        } else if self.chars[self.pos] == '{' {
            self.pos += 1;
            let mut depth = 1;
            while depth > 0 && self.pos < self.chars.len() {
                if self.chars[self.pos] == '{' { depth += 1; }
                else if self.chars[self.pos] == '}' { depth -= 1; }
                self.pos += 1;
            }
        } else {
            self.expect_word();
        }
    }

    fn skip_option_stmt(&mut self) {
        self.skip_ws();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.' || self.chars[self.pos] == '(' || self.chars[self.pos] == ')') {
            self.pos += 1;
        }
        self.expect_char('=');
        self.skip_value();
        self.expect_char(';');
    }

    fn skip_field_options(&mut self) {
        self.expect_char('[');
        loop {
            self.skip_ws();
            if self.chars[self.pos] == ']' {
                self.pos += 1;
                break;
            }
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.' || self.chars[self.pos] == '(' || self.chars[self.pos] == ')') {
                self.pos += 1;
            }
            self.expect_char('=');
            self.skip_value();
            self.skip_ws();
            if self.chars[self.pos] == ',' {
                self.pos += 1;
            }
        }
    }

    fn parse_file(&mut self) {
        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            let word = self.peek_word();
            match word.as_deref() {
                Some("syntax") => {
                    self.expect_word();
                    self.expect_char('=');
                    self.expect_string();
                    self.expect_char(';');
                }
                Some("package") => {
                    self.expect_word();
                    self.skip_ws();
                    while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.') {
                        self.pos += 1;
                    }
                    self.expect_char(';');
                }
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("message") => {
                    self.expect_word();
                    let name = self.expect_word();
                    if self.root_type.is_none() {
                        self.root_type = Some(name.clone());
                    }
                    self.parse_message(&name);
                }
                Some("enum") => {
                    self.expect_word();
                    let name = self.expect_word();
                    self.parse_enum(&name);
                }
                _ => {
                    if self.pos < self.chars.len() {
                        self.pos += 1;
                    }
                }
            }
        }
    }

    fn parse_message(&mut self, name: &str) {
        self.expect_char('{');
        let mut fields: Vec<FieldDef> = Vec::new();
        let mut oneofs: HashMap<String, Vec<u32>> = HashMap::new();

        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            if self.chars[self.pos] == '}' {
                self.pos += 1;
                break;
            }
            let word = self.peek_word();
            match word.as_deref() {
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("message") => {
                    self.expect_word();
                    let nested_name = self.expect_word();
                    self.parse_message(&nested_name);
                }
                Some("enum") => {
                    self.expect_word();
                    let nested_name = self.expect_word();
                    self.parse_enum(&nested_name);
                }
                Some("oneof") => {
                    self.expect_word();
                    let oneof_name = self.expect_word();
                    self.expect_char('{');
                    let mut oneof_fields = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.chars[self.pos] == '}' {
                            self.pos += 1;
                            break;
                        }
                        let f = self.parse_field(Some(oneof_name.clone()));
                        oneof_fields.push(f.number);
                        fields.push(f);
                    }
                    oneofs.insert(oneof_name, oneof_fields);
                }
                Some("reserved") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        if self.chars[self.pos] == '"' {
                            self.pos += 1;
                            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                                self.pos += 1;
                            }
                            self.pos += 1;
                        } else {
                            self.pos += 1;
                        }
                    }
                    self.pos += 1;
                }
                Some("extensions") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        self.pos += 1;
                    }
                    self.pos += 1;
                }
                _ => {
                    let f = self.parse_field(None);
                    fields.push(f);
                }
            }
        }

        self.messages.insert(name.to_string(), MessageDef {
            name: name.to_string(),
            fields,
            oneofs,
        });
    }

    fn parse_field(&mut self, oneof_name: Option<String>) -> FieldDef {
        self.skip_ws();
        let word = self.peek_word().unwrap();

        if word == "map" {
            self.expect_word();
            self.expect_char('<');
            let key_type_str = self.expect_word();
            self.expect_char(',');
            let value_type_str = self.expect_word();
            self.expect_char('>');
            let name = self.expect_word();
            self.expect_char('=');
            let number = self.expect_int() as u32;
            if self.peek_char() == Some('[') {
                self.skip_field_options();
            }
            self.expect_char(';');
            let key_type = parse_scalar_type(&key_type_str);
            let value_type = FieldType::Named(value_type_str);
            return FieldDef {
                name, number,
                field_type: FieldType::Map { key_type, value_type: Box::new(value_type) },
                label: Label::Map,
                oneof: oneof_name,
            };
        }

        let label = match word.as_str() {
            "repeated" => { self.expect_word(); Label::Repeated }
            "optional" => { self.expect_word(); Label::Optional }
            _ => Label::Singular,
        };

        let type_str = self.expect_word();
        let name = self.expect_word();
        self.expect_char('=');
        let number = self.expect_int() as u32;
        if self.peek_char() == Some('[') {
            self.skip_field_options();
        }
        self.expect_char(';');

        let field_type = if let Some(st) = try_parse_scalar_type(&type_str) {
            FieldType::Scalar(st)
        } else {
            FieldType::Named(type_str)
        };

        FieldDef { name, number, field_type, label, oneof: oneof_name }
    }

    fn parse_enum(&mut self, name: &str) {
        self.expect_char('{');
        let mut values: Vec<(i32, String)> = Vec::new();

        loop {
            self.skip_ws();
            if self.pos >= self.chars.len() { break; }
            if self.chars[self.pos] == '}' {
                self.pos += 1;
                break;
            }
            let word = self.peek_word();
            match word.as_deref() {
                Some("option") => {
                    self.expect_word();
                    self.skip_option_stmt();
                }
                Some("reserved") => {
                    self.expect_word();
                    while self.pos < self.chars.len() && self.chars[self.pos] != ';' {
                        if self.chars[self.pos] == '"' {
                            self.pos += 1;
                            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                                self.pos += 1;
                            }
                            self.pos += 1;
                        } else {
                            self.pos += 1;
                        }
                    }
                    self.pos += 1;
                }
                _ => {
                    let value_name = self.expect_word();
                    self.expect_char('=');
                    let value_num = self.expect_int() as i32;
                    if self.peek_char() == Some('[') {
                        self.skip_field_options();
                    }
                    self.expect_char(';');
                    values.push((value_num, value_name));
                }
            }
        }

        self.enums.insert(name.to_string(), EnumDef { name: name.to_string(), values });
    }
}

fn try_parse_scalar_type(s: &str) -> Option<ScalarType> {
    match s {
        "int32" => Some(ScalarType::Int32),
        "int64" => Some(ScalarType::Int64),
        "uint32" => Some(ScalarType::UInt32),
        "uint64" => Some(ScalarType::UInt64),
        "sint32" => Some(ScalarType::SInt32),
        "sint64" => Some(ScalarType::SInt64),
        "bool" => Some(ScalarType::Bool),
        "string" => Some(ScalarType::Str),
        "bytes" => Some(ScalarType::Bytes),
        "fixed32" => Some(ScalarType::Fixed32),
        "fixed64" => Some(ScalarType::Fixed64),
        "sfixed32" => Some(ScalarType::SFixed32),
        "sfixed64" => Some(ScalarType::SFixed64),
        _ => None,
    }
}

fn parse_scalar_type(s: &str) -> ScalarType {
    try_parse_scalar_type(s).unwrap_or_else(|| panic!("unknown scalar type: {}", s))
}

// ===== Decoder =====

fn read_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        let byte = data[*pos];
        *pos += 1;
        if shift < 64 {
            result |= ((byte & 0x7F) as u64) << shift;
        }
        if byte & 0x80 == 0 { break; }
        shift += 7;
    }
    result
}

fn zigzag32(n: u32) -> i32 {
    ((n >> 1) as i32) ^ (0u32.wrapping_sub(n & 1) as i32)
}

fn zigzag64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ (0u64.wrapping_sub(n & 1) as i64)
}

fn is_packed_type(ft: &FieldType) -> bool {
    match ft {
        FieldType::Scalar(st) => matches!(st,
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool |
            ScalarType::Fixed32 | ScalarType::Fixed64 | ScalarType::SFixed32 | ScalarType::SFixed64
        ),
        FieldType::Named(_) => false,
        FieldType::Map { .. } => false,
    }
}

fn is_enum_type(ft: &FieldType, schema: &Schema) -> bool {
    match ft {
        FieldType::Named(name) => schema.enums.contains_key(name),
        _ => false,
    }
}

fn is_message_type(ft: &FieldType, schema: &Schema) -> bool {
    match ft {
        FieldType::Named(name) => schema.messages.contains_key(name),
        _ => false,
    }
}

fn get_named_type(ft: &FieldType) -> &str {
    match ft {
        FieldType::Named(name) => name,
        _ => unreachable!(),
    }
}

fn decode_scalar_from_varint(ft: &FieldType, raw: u64) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Int32) => DecodedValue::Int32(raw as u32 as i32),
        FieldType::Scalar(ScalarType::Int64) => DecodedValue::Int64(raw as i64),
        FieldType::Scalar(ScalarType::UInt32) => DecodedValue::UInt32(raw as u32),
        FieldType::Scalar(ScalarType::UInt64) => DecodedValue::UInt64(raw),
        FieldType::Scalar(ScalarType::SInt32) => DecodedValue::SInt32(zigzag32(raw as u32)),
        FieldType::Scalar(ScalarType::SInt64) => DecodedValue::SInt64(zigzag64(raw)),
        FieldType::Scalar(ScalarType::Bool) => DecodedValue::Bool(raw != 0),
        FieldType::Named(_) => DecodedValue::Enum(raw as u32 as i32),
        _ => unreachable!(),
    }
}

fn decode_scalar_from_fixed32(ft: &FieldType, raw: u32) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Fixed32) => DecodedValue::Fixed32(raw),
        FieldType::Scalar(ScalarType::SFixed32) => DecodedValue::SFixed32(raw as i32),
        _ => unreachable!(),
    }
}

fn decode_scalar_from_fixed64(ft: &FieldType, raw: u64) -> DecodedValue {
    match ft {
        FieldType::Scalar(ScalarType::Fixed64) => DecodedValue::Fixed64(raw),
        FieldType::Scalar(ScalarType::SFixed64) => DecodedValue::SFixed64(raw as i64),
        _ => unreachable!(),
    }
}

fn decode_value_for_type(data: &[u8], pos: &mut usize, ft: &FieldType, wire_type: u8, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool => {
                let raw = read_varint(data, pos);
                decode_scalar_from_varint(ft, raw)
            }
            ScalarType::Str => {
                let len = read_varint(data, pos) as usize;
                let bytes = &data[*pos..*pos + len];
                *pos += len;
                DecodedValue::Str(String::from_utf8_lossy(bytes).into_owned())
            }
            ScalarType::Bytes => {
                let len = read_varint(data, pos) as usize;
                let bytes = data[*pos..*pos + len].to_vec();
                *pos += len;
                DecodedValue::Bytes(bytes)
            }
            ScalarType::Fixed32 | ScalarType::SFixed32 => {
                let raw = u32::from_le_bytes([data[*pos], data[*pos+1], data[*pos+2], data[*pos+3]]);
                *pos += 4;
                decode_scalar_from_fixed32(ft, raw)
            }
            ScalarType::Fixed64 | ScalarType::SFixed64 => {
                let raw = u64::from_le_bytes([
                    data[*pos], data[*pos+1], data[*pos+2], data[*pos+3],
                    data[*pos+4], data[*pos+5], data[*pos+6], data[*pos+7],
                ]);
                *pos += 8;
                decode_scalar_from_fixed64(ft, raw)
            }
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                let raw = read_varint(data, pos);
                DecodedValue::Enum(raw as u32 as i32)
            } else {
                let len = read_varint(data, pos) as usize;
                let sub_data = &data[*pos..*pos + len];
                *pos += len;
                DecodedValue::Message(decode_message_bytes(sub_data, name, schema))
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn skip_field(data: &[u8], pos: &mut usize, wire_type: u8, field_number: u32) {
    match wire_type {
        0 => { read_varint(data, pos); }
        1 => { *pos += 8; }
        2 => { let len = read_varint(data, pos) as usize; *pos += len; }
        5 => { *pos += 4; }
        3 => {
            loop {
                let key = read_varint(data, pos);
                let fn2 = (key >> 3) as u32;
                let wt2 = (key & 7) as u8;
                if wt2 == 4 && fn2 == field_number { break; }
                skip_field(data, pos, wt2, fn2);
            }
        }
        4 => {}
        _ => {}
    }
}

fn decode_message_bytes(data: &[u8], msg_name: &str, schema: &Schema) -> DecodedMessage {
    let msg_def = &schema.messages[msg_name];
    let field_map: HashMap<u32, &FieldDef> = msg_def.fields.iter().map(|f| (f.number, f)).collect();

    let mut result = DecodedMessage {
        fields: HashMap::new(),
        active_oneofs: HashMap::new(),
    };

    let mut pos = 0;
    while pos < data.len() {
        let key = read_varint(data, &mut pos);
        let field_number = (key >> 3) as u32;
        let wire_type = (key & 7) as u8;

        if let Some(&field_def) = field_map.get(&field_number) {
            decode_field(data, &mut pos, field_def, wire_type, &mut result, schema);
        } else {
            skip_field(data, &mut pos, wire_type, field_number);
        }
    }

    result
}

fn decode_field(data: &[u8], pos: &mut usize, field_def: &FieldDef, wire_type: u8,
                result: &mut DecodedMessage, schema: &Schema) {
    match field_def.label {
        Label::Singular | Label::Optional => {
            if let Some(ref oneof_name) = field_def.oneof {
                let current_active = result.active_oneofs.get(oneof_name).copied();
                if current_active != Some(field_def.number) {
                    if let Some(prev) = current_active {
                        result.fields.remove(&prev);
                    }
                    result.active_oneofs.insert(oneof_name.clone(), field_def.number);
                    let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                } else {
                    if is_message_type(&field_def.field_type, schema) {
                        let new_val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                        if let DecodedValue::Message(new_msg) = new_val {
                            if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = result.fields.get_mut(&field_def.number) {
                                merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                            } else {
                                result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(DecodedValue::Message(new_msg)) });
                            }
                        }
                    } else {
                        let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                        result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                    }
                }
            } else {
                if is_message_type(&field_def.field_type, schema) {
                    let new_val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    if let DecodedValue::Message(new_msg) = new_val {
                        if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = result.fields.get_mut(&field_def.number) {
                            merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                        } else {
                            result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(DecodedValue::Message(new_msg)) });
                        }
                    }
                } else {
                    let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                    result.fields.insert(field_def.number, FieldState::Singular { occurred: true, value: Some(val) });
                }
            }
        }
        Label::Repeated => {
            let is_packed = wire_type == 2 && (is_packed_type(&field_def.field_type) || is_enum_type(&field_def.field_type, schema));
            if is_packed {
                let len = read_varint(data, pos) as usize;
                let end = *pos + len;
                let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    while *pos < end {
                        let val = decode_packed_element(data, pos, &field_def.field_type, schema);
                        values.push(val);
                    }
                }
            } else {
                let val = decode_value_for_type(data, pos, &field_def.field_type, wire_type, schema);
                let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    values.push(val);
                }
            }
        }
        Label::Map => {
            let (key_type, value_type) = match &field_def.field_type {
                FieldType::Map { key_type, value_type } => (key_type.clone(), (**value_type).clone()),
                _ => unreachable!(),
            };
            let len = read_varint(data, pos) as usize;
            let end = *pos + len;

            let mut key_val: Option<DecodedValue> = None;
            let mut val_val: Option<DecodedValue> = None;

            while *pos < end {
                let k = read_varint(data, pos);
                let fn2 = (k >> 3) as u32;
                let wt2 = (k & 7) as u8;
                match fn2 {
                    1 => { key_val = Some(decode_value_for_type(data, pos, &FieldType::Scalar(key_type.clone()), wt2, schema)); }
                    2 => { val_val = Some(decode_value_for_type(data, pos, &value_type, wt2, schema)); }
                    _ => { skip_field(data, pos, wt2, fn2); }
                }
            }

            let default_key = match key_type {
                ScalarType::Str => DecodedValue::Str(String::new()),
                ScalarType::Int32 => DecodedValue::Int32(0),
                _ => unreachable!(),
            };
            let default_value = default_value_for_type(&value_type, schema);

            let kv = key_val.unwrap_or(default_key);
            let vv = val_val.unwrap_or(default_value);

            let entry = result.fields.entry(field_def.number).or_insert_with(|| FieldState::Map { entries: Vec::new() });
            if let FieldState::Map { entries } = entry {
                let mut found = false;
                for e in entries.iter_mut() {
                    if decoded_values_equal(&e.0, &kv) {
                        e.1 = vv.clone();
                        found = true;
                        break;
                    }
                }
                if !found {
                    entries.push((kv, vv));
                }
            }
        }
    }
}

fn decode_packed_element(data: &[u8], pos: &mut usize, ft: &FieldType, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::UInt32 | ScalarType::UInt64 |
            ScalarType::SInt32 | ScalarType::SInt64 | ScalarType::Bool => {
                let raw = read_varint(data, pos);
                decode_scalar_from_varint(ft, raw)
            }
            ScalarType::Fixed32 | ScalarType::SFixed32 => {
                let raw = u32::from_le_bytes([data[*pos], data[*pos+1], data[*pos+2], data[*pos+3]]);
                *pos += 4;
                decode_scalar_from_fixed32(ft, raw)
            }
            ScalarType::Fixed64 | ScalarType::SFixed64 => {
                let raw = u64::from_le_bytes([
                    data[*pos], data[*pos+1], data[*pos+2], data[*pos+3],
                    data[*pos+4], data[*pos+5], data[*pos+6], data[*pos+7],
                ]);
                *pos += 8;
                decode_scalar_from_fixed64(ft, raw)
            }
            _ => unreachable!(),
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                let raw = read_varint(data, pos);
                DecodedValue::Enum(raw as u32 as i32)
            } else {
                unreachable!()
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn default_value_for_type(ft: &FieldType, schema: &Schema) -> DecodedValue {
    match ft {
        FieldType::Scalar(st) => match st {
            ScalarType::Int32 => DecodedValue::Int32(0),
            ScalarType::Int64 => DecodedValue::Int64(0),
            ScalarType::UInt32 => DecodedValue::UInt32(0),
            ScalarType::UInt64 => DecodedValue::UInt64(0),
            ScalarType::SInt32 => DecodedValue::SInt32(0),
            ScalarType::SInt64 => DecodedValue::SInt64(0),
            ScalarType::Bool => DecodedValue::Bool(false),
            ScalarType::Str => DecodedValue::Str(String::new()),
            ScalarType::Bytes => DecodedValue::Bytes(Vec::new()),
            ScalarType::Fixed32 => DecodedValue::Fixed32(0),
            ScalarType::Fixed64 => DecodedValue::Fixed64(0),
            ScalarType::SFixed32 => DecodedValue::SFixed32(0),
            ScalarType::SFixed64 => DecodedValue::SFixed64(0),
        },
        FieldType::Named(name) => {
            if schema.enums.contains_key(name) {
                DecodedValue::Enum(0)
            } else {
                DecodedValue::Message(DecodedMessage { fields: HashMap::new(), active_oneofs: HashMap::new() })
            }
        }
        FieldType::Map { .. } => unreachable!(),
    }
}

fn decoded_values_equal(a: &DecodedValue, b: &DecodedValue) -> bool {
    match (a, b) {
        (DecodedValue::Str(x), DecodedValue::Str(y)) => x == y,
        (DecodedValue::Int32(x), DecodedValue::Int32(y)) => x == y,
        _ => false,
    }
}

fn merge_messages(target: &mut DecodedMessage, source: DecodedMessage, msg_name: &str, schema: &Schema) {
    let msg_def = &schema.messages[msg_name];
    let field_map: HashMap<u32, &FieldDef> = msg_def.fields.iter().map(|f| (f.number, f)).collect();

    for (field_num, source_state) in source.fields {
        let field_def = match field_map.get(&field_num) {
            Some(f) => *f,
            None => continue,
        };

        if let Some(ref oneof_name) = field_def.oneof {
            if let Some(&current_active) = target.active_oneofs.get(oneof_name) {
                if current_active != field_num {
                    target.fields.remove(&current_active);
                }
            }
            target.active_oneofs.insert(oneof_name.clone(), field_num);
        }

        match (&field_def.label, source_state) {
            (Label::Singular | Label::Optional, FieldState::Singular { value: Some(sv), .. }) => {
                if is_message_type(&field_def.field_type, schema) {
                    if let DecodedValue::Message(new_msg) = sv {
                        let mut merged = false;
                        if let Some(FieldState::Singular { value: Some(DecodedValue::Message(ref mut existing)), .. }) = target.fields.get_mut(&field_num) {
                            merge_messages(existing, new_msg, get_named_type(&field_def.field_type), schema);
                            merged = true;
                        }
                        if !merged {
                            target.fields.insert(field_num, FieldState::Singular { occurred: true, value: Some(DecodedValue::Message(new_msg)) });
                        }
                    } else {
                        target.fields.insert(field_num, FieldState::Singular { occurred: true, value: Some(sv) });
                    }
                } else {
                    target.fields.insert(field_num, FieldState::Singular { occurred: true, value: Some(sv) });
                }
            }
            (Label::Repeated, FieldState::Repeated { values: new_vals }) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Repeated { values: Vec::new() });
                if let FieldState::Repeated { values } = entry {
                    values.extend(new_vals);
                }
            }
            (Label::Map, FieldState::Map { entries: new_entries }) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Map { entries: Vec::new() });
                if let FieldState::Map { entries } = entry {
                    for (k, v) in new_entries {
                        let mut found = false;
                        for e in entries.iter_mut() {
                            if decoded_values_equal(&e.0, &k) {
                                e.1 = v.clone();
                                found = true;
                                break;
                            }
                        }
                        if !found {
                            entries.push((k, v));
                        }
                    }
                }
            }
            _ => {}
        }
    }
}

// ===== JSON Output =====

fn to_lower_camel_case(name: &str) -> String {
    let mut result = String::new();
    let mut chars = name.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '_' {
            if let Some(&next) = chars.peek() {
                if next.is_ascii_lowercase() {
                    result.push(next.to_ascii_uppercase());
                    chars.next();
                }
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn json_escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{0009}' => result.push_str("\\t"),
            '\u{000A}' => result.push_str("\\n"),
            '\u{000C}' => result.push_str("\\f"),
            '\u{000D}' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

fn is_default_value(val: &DecodedValue) -> bool {
    match val {
        DecodedValue::Int32(v) => *v == 0,
        DecodedValue::Int64(v) => *v == 0,
        DecodedValue::UInt32(v) => *v == 0,
        DecodedValue::UInt64(v) => *v == 0,
        DecodedValue::SInt32(v) => *v == 0,
        DecodedValue::SInt64(v) => *v == 0,
        DecodedValue::Bool(v) => !*v,
        DecodedValue::Str(v) => v.is_empty(),
        DecodedValue::Bytes(v) => v.is_empty(),
        DecodedValue::Fixed32(v) => *v == 0,
        DecodedValue::Fixed64(v) => *v == 0,
        DecodedValue::SFixed32(v) => *v == 0,
        DecodedValue::SFixed64(v) => *v == 0,
        DecodedValue::Enum(v) => *v == 0,
        DecodedValue::Message(_) => false,
    }
}

fn value_to_json_with_type(val: &DecodedValue, ft: &FieldType, schema: &Schema) -> String {
    match val {
        DecodedValue::Int32(v) => format!("{}", v),
        DecodedValue::Int64(v) => format!("\"{}\"", v),
        DecodedValue::UInt32(v) => format!("{}", v),
        DecodedValue::UInt64(v) => format!("\"{}\"", v),
        DecodedValue::SInt32(v) => format!("{}", v),
        DecodedValue::SInt64(v) => format!("\"{}\"", v),
        DecodedValue::Bool(v) => if *v { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(v) => format!("\"{}\"", json_escape(v)),
        DecodedValue::Bytes(v) => format!("\"{}\"", base64_encode(v)),
        DecodedValue::Fixed32(v) => format!("{}", v),
        DecodedValue::Fixed64(v) => format!("\"{}\"", v),
        DecodedValue::SFixed32(v) => format!("{}", v),
        DecodedValue::SFixed64(v) => format!("\"{}\"", v),
        DecodedValue::Enum(v) => {
            if let FieldType::Named(name) = ft {
                if let Some(enum_def) = schema.enums.get(name) {
                    for (num, val_name) in &enum_def.values {
                        if *num == *v {
                            return format!("\"{}\"", json_escape(val_name));
                        }
                    }
                }
            }
            format!("{}", v)
        }
        DecodedValue::Message(m) => {
            if let FieldType::Named(name) = ft {
                message_to_json(m, name, schema)
            } else {
                "{}".to_string()
            }
        }
    }
}

fn message_to_json(msg: &DecodedMessage, msg_name: &str, schema: &Schema) -> String {
    let msg_def = match schema.messages.get(msg_name) {
        Some(d) => d,
        None => return "{}".to_string(),
    };

    let mut sorted_fields: Vec<&FieldDef> = msg_def.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    let mut parts: Vec<String> = Vec::new();

    for field_def in sorted_fields {
        let state = match msg.fields.get(&field_def.number) {
            Some(s) => s,
            None => continue,
        };

        let should_print = match (&field_def.label, state) {
            (Label::Singular, FieldState::Singular { occurred, value }) => {
                if !*occurred { continue; }
                if field_def.oneof.is_some() {
                    if let Some(ref oneof_name) = field_def.oneof {
                        msg.active_oneofs.get(oneof_name) == Some(&field_def.number)
                    } else {
                        false
                    }
                } else {
                    if let Some(val) = value {
                        !is_default_value(val)
                    } else {
                        false
                    }
                }
            }
            (Label::Optional, FieldState::Singular { occurred, .. }) => {
                *occurred
            }
            (Label::Repeated, FieldState::Repeated { values }) => {
                !values.is_empty()
            }
            (Label::Map, FieldState::Map { entries }) => {
                !entries.is_empty()
            }
            _ => false,
        };

        if !should_print { continue; }

        let json_name = to_lower_camel_case(&field_def.name);

        let json_value = match state {
            FieldState::Singular { value: Some(val), .. } => {
                value_to_json_with_type(val, &field_def.field_type, schema)
            }
            FieldState::Singular { value: None, .. } => continue,
            FieldState::Repeated { values } => {
                let items: Vec<String> = values.iter()
                    .map(|v| value_to_json_with_type(v, &field_def.field_type, schema))
                    .collect();
                format!("[{}]", items.join(","))
            }
            FieldState::Map { entries } => {
                let (key_type, value_type) = match &field_def.field_type {
                    FieldType::Map { key_type, value_type } => (key_type.clone(), (**value_type).clone()),
                    _ => unreachable!(),
                };

                let mut sorted_entries: Vec<&(DecodedValue, DecodedValue)> = entries.iter().collect();
                match key_type {
                    ScalarType::Str => {
                        sorted_entries.sort_by(|a, b| {
                            let ka = match &a.0 { DecodedValue::Str(s) => s.as_str(), _ => "" };
                            let kb = match &b.0 { DecodedValue::Str(s) => s.as_str(), _ => "" };
                            ka.cmp(kb)
                        });
                    }
                    ScalarType::Int32 => {
                        sorted_entries.sort_by(|a, b| {
                            let ka = match &a.0 { DecodedValue::Int32(v) => *v, _ => 0 };
                            let kb = match &b.0 { DecodedValue::Int32(v) => *v, _ => 0 };
                            ka.cmp(&kb)
                        });
                    }
                    _ => {}
                }

                let items: Vec<String> = sorted_entries.iter().map(|(k, v)| {
                    let key_str = match k {
                        DecodedValue::Str(s) => json_escape(s),
                        DecodedValue::Int32(n) => format!("{}", n),
                        _ => String::new(),
                    };
                    let val_str = value_to_json_with_type(v, &value_type, schema);
                    format!("\"{}\":{}", key_str, val_str)
                }).collect();
                format!("{{{}}}", items.join(","))
            }
        };

        parts.push(format!("\"{}\":{}", json_name, json_value));
    }

    format!("{{{}}}", parts.join(","))
}

// ===== Main =====

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_path = format!("{}/schema.proto", dir);
    let messages_path = format!("{}/messages.bin", dir);

    let schema_str = fs::read_to_string(&schema_path).unwrap();
    let messages_data = fs::read(&messages_path).unwrap();

    let mut parser = Parser::new(&schema_str);
    parser.parse_file();

    let schema = Schema {
        messages: parser.messages,
        enums: parser.enums,
        root_type: parser.root_type.unwrap_or_default(),
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let mut pos = 0;
    while pos < messages_data.len() {
        let len = read_varint(&messages_data, &mut pos) as usize;
        let record_data = &messages_data[pos..pos + len];
        pos += len;

        let decoded = decode_message_bytes(record_data, &schema.root_type, &schema);
        let json = message_to_json(&decoded, &schema.root_type, &schema);
        writeln!(out, "{}", json).unwrap();
    }

    out.flush().unwrap();
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ==================== JSON Parser ====================
    static class JsonParser {
        final String input;
        int pos;

        JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        Object parse() {
            skipWs();
            char c = peek();
            if (c == '{') return parseObj();
            if (c == '[') return parseArr();
            if (c == '"') return parseStr();
            if (c == 't' || c == 'f') return parseBool();
            if (c == 'n') { expect("null"); return null; }
            return parseNum();
        }

        Map<String, Object> parseObj() {
            Map<String, Object> m = new LinkedHashMap<>();
            expect('{');
            skipWs();
            if (peek() == '}') { pos++; return m; }
            while (true) {
                skipWs();
                String key = parseStr();
                skipWs();
                expect(':');
                skipWs();
                m.put(key, parse());
                skipWs();
                if (peek() == '}') { pos++; return m; }
                expect(',');
            }
        }

        List<Object> parseArr() {
            List<Object> list = new ArrayList<>();
            expect('[');
            skipWs();
            if (peek() == ']') { pos++; return list; }
            while (true) {
                skipWs();
                list.add(parse());
                skipWs();
                if (peek() == ']') { pos++; return list; }
                expect(',');
            }
        }

        String parseStr() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = input.charAt(pos++);
                if (c == '"') return sb.toString();
                if (c == '\\') {
                    char e = input.charAt(pos++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(input.substring(pos, pos + 4), 16);
                            pos += 4;
                            if (Character.isHighSurrogate((char) hi) && pos + 1 < input.length()
                                    && input.charAt(pos) == '\\' && input.charAt(pos + 1) == 'u') {
                                pos += 2;
                                int lo = Integer.parseInt(input.substring(pos, pos + 4), 16);
                                pos += 4;
                                sb.appendCodePoint(Character.toCodePoint((char) hi, (char) lo));
                            } else {
                                sb.appendCodePoint(hi);
                            }
                            break;
                        }
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c);
                }
            }
        }

        String parseNum() {
            int start = pos;
            if (peek() == '-') pos++;
            while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            if (pos < input.length() && input.charAt(pos) == '.') {
                pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            return input.substring(start, pos);
        }

        Boolean parseBool() {
            if (input.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
            if (input.startsWith("false", pos)) { pos += 5; return Boolean.FALSE; }
            throw new RuntimeException("bad bool");
        }

        void skipWs() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        char peek() { return input.charAt(pos); }

        void expect(char c) {
            if (input.charAt(pos) != c) throw new RuntimeException("Expected '" + c + "' at pos " + pos);
            pos++;
        }

        void expect(String s) {
            if (!input.startsWith(s, pos)) throw new RuntimeException("Expected '" + s + "' at pos " + pos);
            pos += s.length();
        }
    }

    // ==================== HTTP ====================
    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
    }

    static HttpResponse doRequest(String host, int port, String method, String path,
                                  Map<String, String> extraHeaders, String body) throws Exception {
        Socket sock = new Socket();
        sock.connect(new InetSocketAddress(host, port), 15000);
        sock.setSoTimeout(30000);
        OutputStream os = sock.getOutputStream();
        InputStream is = sock.getInputStream();

        StringBuilder req = new StringBuilder();
        req.append(method).append(' ').append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host);
        if (port != 80) req.append(':').append(port);
        req.append("\r\n");
        if (extraHeaders != null) {
            for (Map.Entry<String, String> e : extraHeaders.entrySet()) {
                req.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");
            }
        }
        if (body != null) {
            byte[] bb = body.getBytes(StandardCharsets.UTF_8);
            req.append("Content-Length: ").append(bb.length).append("\r\n");
        }
        req.append("\r\n");
        os.write(req.toString().getBytes(StandardCharsets.UTF_8));
        if (body != null) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }
        os.flush();

        HttpResponse resp = new HttpResponse();
        resp.headers = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);

        String statusLine = readLine(is);
        if (statusLine == null) { sock.close(); throw new IOException("EOF reading status"); }
        String[] parts = statusLine.split(" ", 3);
        resp.status = Integer.parseInt(parts[1]);

        String line;
        while ((line = readLine(is)) != null && !line.isEmpty()) {
            int ci = line.indexOf(':');
            if (ci >= 0) {
                resp.headers.put(line.substring(0, ci).trim(), line.substring(ci + 1).trim());
            }
        }

        String te = resp.headers.get("transfer-encoding");
        String cl = resp.headers.get("content-length");

        if (te != null && te.toLowerCase().contains("chunked")) {
            resp.body = readChunked(is);
        } else if (cl != null) {
            int len = Integer.parseInt(cl.trim());
            byte[] buf = new byte[len];
            int off = 0;
            while (off < len) {
                int r = is.read(buf, off, len - off);
                if (r < 0) break;
                off += r;
            }
            resp.body = new String(buf, 0, off, StandardCharsets.UTF_8);
        } else {
            resp.body = "";
        }

        sock.close();
        return resp;
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') break;
            sb.append((char) c);
        }
        if (c == -1 && sb.length() == 0) return null;
        if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '\r') {
            sb.setLength(sb.length() - 1);
        }
        return sb.toString();
    }

    static String readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String sizeLine = readLine(in);
            if (sizeLine == null) break;
            int semi = sizeLine.indexOf(';');
            String hex = (semi >= 0 ? sizeLine.substring(0, semi) : sizeLine).trim();
            int sz = Integer.parseInt(hex, 16);
            if (sz == 0) {
                // consume trailer headers until blank line
                while (true) {
                    String t = readLine(in);
                    if (t == null || t.isEmpty()) break;
                }
                break;
            }
            byte[] buf = new byte[sz];
            int off = 0;
            while (off < sz) {
                int r = in.read(buf, off, sz - off);
                if (r < 0) break;
                off += r;
            }
            baos.write(buf, 0, off);
            readLine(in); // consume trailing CRLF
        }
        return baos.toString("UTF-8");
    }

    // ==================== Encoding helpers ====================
    static String formUrlEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append('%');
                sb.append(Character.toUpperCase(Character.forDigit((c >> 4) & 0xF, 16)));
                sb.append(Character.toUpperCase(Character.forDigit(c & 0xF, 16)));
            }
        }
        return sb.toString();
    }

    static String percentEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append('%');
                sb.append(Character.toUpperCase(Character.forDigit((c >> 4) & 0xF, 16)));
                sb.append(Character.toUpperCase(Character.forDigit(c & 0xF, 16)));
            }
        }
        return sb.toString();
    }

    // ==================== Amount helpers ====================
    static long parseAmountToCents(String amount) {
        boolean neg = false;
        int i = 0;
        if (amount.charAt(0) == '-') { neg = true; i = 1; }
        long intPart = 0;
        while (i < amount.length() && amount.charAt(i) != '.') {
            intPart = intPart * 10 + (amount.charAt(i) - '0');
            i++;
        }
        long cents = intPart * 100;
        if (i < amount.length() && amount.charAt(i) == '.') {
            i++;
            long frac = 0;
            int digits = 0;
            while (i < amount.length() && digits < 2) {
                frac = frac * 10 + (amount.charAt(i) - '0');
                i++;
                digits++;
            }
            if (digits == 1) frac *= 10;
            cents += frac;
        }
        return neg ? -cents : cents;
    }

    static String formatCents(long cents) {
        if (cents == 0) return "0.00";
        boolean neg = cents < 0;
        long abs = Math.abs(cents);
        long dollars = abs / 100;
        long rem = abs % 100;
        return (neg ? "-" : "") + dollars + "." + (rem < 10 ? "0" : "") + rem;
    }

    // ==================== Code-point comparison ====================
    static int cmpCodePoints(String a, String b) {
        int lenA = a.codePointCount(0, a.length());
        int lenB = b.codePointCount(0, b.length());
        int iA = 0, iB = 0;
        int minLen = Math.min(lenA, lenB);
        for (int i = 0; i < minLen; i++) {
            int cpA = a.codePointAt(iA);
            int cpB = b.codePointAt(iB);
            if (cpA != cpB) return cpA - cpB;
            iA += Character.charCount(cpA);
            iB += Character.charCount(cpB);
        }
        return Integer.compare(lenA, lenB);
    }

    // ==================== Token acquisition ====================
    static String getToken(String host, int port, String basePath,
                           String clientId, String clientSecret, String scope,
                           PrintStream out) throws Exception {
        String encId = formUrlEncode(clientId);
        String encSecret = formUrlEncode(clientSecret);
        String credentials = encId + ":" + encSecret;
        String b64 = Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));

        String body = "grant_type=client_credentials&scope=" + formUrlEncode(scope);

        Map<String, String> hdrs = new LinkedHashMap<>();
        hdrs.put("Content-Type", "application/x-www-form-urlencoded");
        hdrs.put("Authorization", "Basic " + b64);

        String path = basePath + "/oauth/token";
        HttpResponse resp = doRequest(host, port, "POST", path, hdrs, body);

        if (resp.status != 200) {
            out.println("ERROR " + resp.status + " " + resp.body);
            out.flush();
            return null;
        }

        Map<String, Object> obj = (Map<String, Object>) new JsonParser(resp.body).parse();
        return (String) obj.get("access_token");
    }

    // ==================== Main ====================
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        PrintStream out = new PrintStream(new FileOutputStream(FileDescriptor.out), true, "UTF-8");

        String dataDir = args[0];
        String baseUrl = args[1];

        // Read client.json
        String clientJson = new String(
                Files.readAllBytes(Paths.get(dataDir, "client.json")), StandardCharsets.UTF_8);
        Map<String, Object> client = (Map<String, Object>) new JsonParser(clientJson).parse();
        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = Integer.parseInt((String) client.get("page_size"));

        // Parse base URL
        URL url = new URL(baseUrl);
        String host = url.getHost();
        int port = url.getPort();
        if (port == -1) port = 80;
        String basePath = url.getPath();
        if (basePath.endsWith("/")) basePath = basePath.substring(0, basePath.length() - 1);

        // Step 1: get token
        String accessToken = getToken(host, port, basePath, clientId, clientSecret, scope, out);
        if (accessToken == null) return;
        int reauthCount = 0;

        // Step 2: fetch pages
        int pages = 0;
        int retries = 0;
        List<Map<String, Object>> allOrders = new ArrayList<>();
        String cursor = null;
        boolean firstPage = true;
        boolean firstOrdersRequest = true;

        while (true) {
            String path = basePath + "/orders?limit=" + pageSize;
            if (!firstPage) {
                path += "&cursor=" + percentEncode(cursor);
            }

            Map<String, String> hdrs = new LinkedHashMap<>();
            hdrs.put("Authorization", "Bearer " + accessToken);

            boolean wasFirst = firstOrdersRequest;
            firstOrdersRequest = false;

            HttpResponse resp = doRequest(host, port, "GET", path, hdrs, null);

            if (resp.status == 429) {
                retries++;
                String ra = resp.headers.get("retry-after");
                int secs = Integer.parseInt(ra.trim());
                Thread.sleep(secs * 1000L);
                continue;
            }
            if (resp.status == 503) {
                retries++;
                Thread.sleep(500);
                continue;
            }
            if (resp.status == 401) {
                if (wasFirst) {
                    out.println("ERROR 401 " + resp.body);
                    out.flush();
                    return;
                }
                accessToken = getToken(host, port, basePath, clientId, clientSecret, scope, out);
                if (accessToken == null) return;
                reauthCount++;
                firstOrdersRequest = true;
                continue;
            }
            if (resp.status != 200) {
                out.println("ERROR " + resp.status + " " + resp.body);
                out.flush();
                return;
            }

            // 200 OK
            pages++;
            Map<String, Object> obj = (Map<String, Object>) new JsonParser(resp.body).parse();
            List<Object> data = (List<Object>) obj.get("data");
            if (data != null) {
                for (Object o : data) {
                    allOrders.add((Map<String, Object>) o);
                }
            }
            Object nc = obj.get("next_cursor");
            if (nc == null) break;
            cursor = (String) nc;
            firstPage = false;
        }

        // ==================== Aggregate ====================
        // totals: name -> currency -> cents
        TreeMap<String, TreeMap<String, Long>> totals = new TreeMap<>(Main::cmpCodePoints);
        TreeMap<String, Integer> statusCounts = new TreeMap<>();

        for (Map<String, Object> order : allOrders) {
            String status = (String) order.get("status");
            statusCounts.merge(status, 1, Integer::sum);

            if (!"cancelled".equals(status)) {
                Map<String, Object> cust = (Map<String, Object>) order.get("customer");
                String name = (String) cust.get("name");
                String currency = (String) order.get("currency");
                String amtStr = (String) order.get("amount");
                long cents = parseAmountToCents(amtStr);

                totals.computeIfAbsent(name, k -> new TreeMap<>()).merge(currency, cents, Long::sum);
            }
        }

        // ==================== Output ====================
        for (Map.Entry<String, TreeMap<String, Long>> nameEntry : totals.entrySet()) {
            String name = nameEntry.getKey();
            for (Map.Entry<String, Long> currEntry : nameEntry.getValue().entrySet()) {
                out.println("total " + currEntry.getKey() + " " + formatCents(currEntry.getValue()) + " " + name);
            }
        }
        for (Map.Entry<String, Integer> se : statusCounts.entrySet()) {
            out.println("status " + se.getKey() + " " + se.getValue());
        }
        out.println("orders " + allOrders.size() + " pages " + pages + " retries " + retries + " reauth " + reauthCount);
        out.flush();
    }
}

