import Foundation

let allPrintable: Set<Character> = {
    var s = Set<Character>()
    for i in 0x20...0x7E {
        s.insert(Character(Unicode.Scalar(i)!))
    }
    return s
}()

let wordChars: Set<Character> = {
    var s = Set<Character>()
    for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_" {
        s.insert(c)
