let digitChars: Set<Character> = Set("0123456789")
let spaceChars: Set<Character> = Set(" ")

indirect enum AST {
    case literal(Character)
    case any
    case anchorStart
    case anchorEnd
    case classMatch(Set<Character>)
    case group(Int?, AST)
    case concat([AST])
    case alt([AST])
    case quant(Int, Int?, Bool, AST)
}

class RegexParser {
    let chars: [Character]
    var pos = 0
    var groupCount = 0

    init(_ pattern: String) {
        self.chars = Array(pattern)
    }

    func peek() -> Character? {
        return pos < chars.count ? chars[pos] : nil
    }

    func consume() -> Character {
        let c = chars[pos]
        pos += 1
        return c
    }

    func parse() -> AST {
        return parseAlt()
    }

    func parseAlt() -> AST {
        var branches: [AST] = [parseBranch()]
        while peek() == "|" {
            consume()
            branches.append(parseBranch())
        }
        if branches.count == 1 { return branches[0] }
        return .alt(branches)
    }

    func parseBranch() -> AST {
        var pieces: [AST] = []
        while let c = peek(), c != "|" && c != ")" {
            pieces.append(parsePiece())
        }
        if pieces.isEmpty { return .concat([]) }
        if pieces.count == 1 { return pieces[0] }
        return .concat(pieces)
    }

    func parsePiece() -> AST {
        let atom = parseAtom()
        if case .anchorStart = atom { return atom }
        if case .anchorEnd = atom { return atom }

        if let c = peek() {
            if c == "*" || c == "+" || c == "?" {
                return parseSimpleQuantifier(atom)
            } else if c == "{" {
                let savedPos = pos
                if let quant = tryParseCounted() {
                    return quant(atom)
                } else {
                    pos = savedPos
                }
            }
        }
        return atom
    }

    func parseSimpleQuantifier(_ atom: AST) -> AST {
        let c = consume()
        var lazy = false
        if peek() == "?" {
            consume()
            lazy = true
        }
        switch c {
        case "*": return .quant(0, nil, lazy, atom)
        case "+": return .quant(1, nil, lazy, atom)
        case "?": return .quant(0, 1, lazy, atom)
        default: fatalError()
        }
    }

    func tryParseCounted() -> ((AST) -> AST)? {
        let start = pos
        consume() // '{'
        guard let m = parseNumber() else { pos = start; return nil }
        if peek() == "}" {
            consume()
            var lazy = false
            if peek() == "?" { consume(); lazy = true }
            return { atom in .quant(m, m, lazy, atom) }
        }
        guard peek() == "," else { pos = start; return nil }
        consume() // ','
        if peek() == "}" {
            consume()
            var lazy = false
            if peek() == "?" { consume(); lazy = true }
            return { atom in .quant(m, nil, lazy, atom) }
        }
        guard let n = parseNumber() else { pos = start; return nil }
        guard peek() == "}" else { pos = start; return nil }
        consume() // '}'
        var lazy = false
        if peek() == "?" { consume(); lazy = true }
        return { atom in .quant(m, n, lazy, atom) }
    }

    func parseNumber() -> Int? {
        var num = ""
        while let c = peek(), c.isNumber {
            num.append(consume())
        }
        if num.isEmpty { return nil }
        return Int(num)
    }

    func parseAtom() -> AST {
        let c = consume()
        switch c {
        case "(":
            if peek() == "?" && pos + 1 < chars.count && chars[pos + 1] == ":" {
                consume(); consume()
                let body = parseAlt()
                _ = consume() // ')'
                return .group(nil, body)
            } else {
                groupCount += 1
                let idx = groupCount
                let body = parseAlt()
                _ = consume() // ')'
                return .group(idx, body)
            }
        case ".":
            return .any
        case "^":
            return .anchorStart
        case "$":
            return .anchorEnd
        case "[":
            return parseClass()
        case "\\":
            return parseEscape()
        default:
            return .literal(c)
        }
    }

    func parseEscape() -> AST {
        let c = consume()
        switch c {
        case "d": return .classMatch(digitChars)
        case "D": return .classMatch(allPrintable.subtracting(digitChars))
        case "w": return .classMatch(wordChars)
        case "W": return .classMatch(allPrintable.subtracting(wordChars))
        case "s": return .classMatch(spaceChars)
        case "S": return .classMatch(allPrintable.subtracting(spaceChars))
        default: return .literal(c)
        }
    }

    func parseClass() -> AST {
        var negated = false
        if peek() == "^" {
            consume()
            negated = true
        }
        var charSet: Set<Character> = []

        while peek() != "]" {
            guard let c = peek() else { fatalError("unterminated class") }
            if c == "\\" {
                consume()
                let ec = consume()
                switch ec {
                case "d": charSet.formUnion(digitChars)
                case "D": charSet.formUnion(allPrintable.subtracting(digitChars))
                case "w": charSet.formUnion(wordChars)
                case "W": charSet.formUnion(allPrintable.subtracting(wordChars))
                case "s": charSet.formUnion(spaceChars)
                case "S": charSet.formUnion(allPrintable.subtracting(spaceChars))
                default: charSet.insert(ec)
                }
            } else {
                consume()
                if peek() == "-" && pos + 1 < chars.count && chars[pos + 1] != "]" {
                    consume() // '-'
                    let end: Character
                    if peek() == "\\" {
                        consume()
                        end = consume()
                    } else {
                        end = consume()
                    }
                    let lo = c.unicodeScalars.first!.value
                    let hi = end.unicodeScalars.first!.value
                    if lo <= hi {
                        for v in lo...hi {
                            if let sc = Unicode.Scalar(v) {
                                charSet.insert(Character(sc))
                            }
                        }
                    }
                } else {
                    charSet.insert(c)
                }
            }
        }
        consume() // ']'

        if negated {
            return .classMatch(allPrintable.subtracting(charSet))
        } else {
            return .classMatch(charSet)
        }
    }
}

enum Inst {
    case char(Character)
    case classMatch(Set<Character>)
    case any
    case split(Int, Int)
    case save(Int)
    case match
    case anchorStart
    case anchorEnd
}

func compile(_ ast: AST, into prog: inout [Inst]) {
    switch ast {
    case .literal(let c):
        prog.append(.char(c))
    case .any:
        prog.append(.any)
    case .classMatch(let s):
        prog.append(.classMatch(s))
    case .anchorStart:
        prog.append(.anchorStart)
    case .anchorEnd:
        prog.append(.anchorEnd)
    case .group(let idx, let body):
        if let idx = idx {
            prog.append(.save(2 * idx))
        }
        compile(body, into: &prog)
        if let idx = idx {
            prog.append(.save(2 * idx + 1))
        }
    case .concat(let pieces):
        for p in pieces {
            compile(p, into: &prog)
        }
    case .alt(let branches):
        compileAlt(branches, into: &prog)
    case .quant(let min, let max, let lazy, let body):
        compileQuant(min, max, lazy, body, into: &prog)
    }
}

func compileAlt(_ branches: [AST], into prog: inout [Inst]) {
    if branches.count == 1 {
        compile(branches[0], into: &prog)
        return
    }
    let splitIdx = prog.count
    prog.append(.split(0, 0))
    let branch0Start = prog.count
    compile(branches[0], into: &prog)
    let jumpIdx = prog.count
    prog.append(.split(0, 0))
    let restStart = prog.count
    compileAlt(Array(branches[1...]), into: &prog)
    let afterAlt = prog.count
    prog[splitIdx] = .split(branch0Start, restStart)
    prog[jumpIdx] = .split(afterAlt, afterAlt)
}

func compileQuant(_ min: Int, _ max: Int?, _ lazy: Bool, _ body: AST, into prog: inout [Inst]) {
    if let max = max {
        for _ in 0..<min {
            compile(body, into: &prog)
        }
        for _ in 0..<(max - min) {
            if lazy {
                let splitIdx = prog.count
                prog.append(.split(0, 0))
                let bodyStart = prog.count
                compile(body, into: &prog)
                let after = prog.count
                prog[splitIdx] = .split(after, bodyStart)
            } else {
                let splitIdx = prog.count
                prog.append(.split(0, 0))
                let bodyStart = prog.count
                compile(body, into: &prog)
                let after = prog.count
                prog[splitIdx] = .split(bodyStart, after)
            }
        }
    } else {
        if min == 0 {
            let splitIdx = prog.count
            prog.append(.split(0, 0))
            let bodyStart = prog.count
            compile(body, into: &prog)
            let jumpIdx = prog.count
            prog.append(.split(0, 0))
            let after = prog.count
            if lazy {
                prog[splitIdx] = .split(after, bodyStart)
            } else {
                prog[splitIdx] = .split(bodyStart, after)
            }
            prog[jumpIdx] = .split(splitIdx, splitIdx)
        } else {
            for _ in 0..<(min - 1) {
                compile(body, into: &prog)
            }
            let bodyStart = prog.count
            compile(body, into: &prog)
            let splitIdx = prog.count
            prog.append(.split(0, 0))
            let after = prog.count
            if lazy {
                prog[splitIdx] = .split(after, bodyStart)
            } else {
                prog[splitIdx] = .split(bodyStart, after)
            }
        }
    }
}

func findMatch(prog: [Inst], subject: [Character], numGroups: Int) -> (Int, Int, [Int?])? {
    let n = subject.count
    let m = prog.count
    if m == 0 {
        return (0, 0, Array(repeating: nil, count: numGroups))
    }

    var failed = Set<Int>()

    for start in 0...n {
        var onStack = Set<Int>()
        var cycleHit = false
        var endPos = -1

        func backtrack(_ pc: Int, _ pos: Int, _ captures: inout [Int]) -> Bool {
            let key = pc * (n + 1) + pos
            if failed.contains(key) { return false }
            if onStack.contains(key) {
                cycleHit = true
                return false
            }
            onStack.insert(key)
            let savedCycleHit = cycleHit
            cycleHit = false

            let result = backtrackInner(pc, pos, &captures)

            onStack.remove(key)
            let localCycle = cycleHit
            cycleHit = savedCycleHit || localCycle

            if !result && !localCycle {
                failed.insert(key)
            }
            return result
        }

        func backtrackInner(_ pc: Int, _ pos: Int, _ captures: inout [Int]) -> Bool {
            if pc >= m { return false }
            switch prog[pc] {
            case .match:
                endPos = pos
                return true
            case .char(let c):
                if pos < n && subject[pos] == c {
                    return backtrack(pc + 1, pos + 1, &captures)
                }
                return false
            case .classMatch(let s):
                if pos < n && s.contains(subject[pos]) {
                    return backtrack(pc + 1, pos + 1, &captures)
                }
                return false
            case .any:
                if pos < n {
                    return backtrack(pc + 1, pos + 1, &captures)
                }
                return false
            case .split(let x, let y):
                var cap1 = captures
                if backtrack(x, pos, &cap1) {
                    captures = cap1
                    return true
                }
                var cap2 = captures
                if backtrack(y, pos, &cap2) {
                    captures = cap2
                    return true
                }
                return false
            case .save(let idx):
                let old = captures[idx]
                captures[idx] = pos
                if backtrack(pc + 1, pos, &captures) {
                    return true
                }
                captures[idx] = old
                return false
            case .anchorStart:
                if pos == 0 {
                    return backtrack(pc + 1, pos, &captures)
                }
                return false
            case .anchorEnd:
                if pos == n {
                    return backtrack(pc + 1, pos, &captures)
                }
                return false
            }
        }

        var captures = Array(repeating: -1, count: 2 * numGroups)
        if backtrack(0, start, &captures) {
            var result: [Int?] = []
            for g in 0..<numGroups {
                let s = captures[2 * g]
                let e = captures[2 * g + 1]
                if s == -1 || e == -1 {
                    result.append(nil)
                } else {
                    result.append((s, e))
                }
            }
            return (start, endPos, result)
        }
    }
    return nil
}

