fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let cs = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let cj = pj(&cs);
    let cid = js(&cj, "client_id").unwrap();
    let csec = js(&cj, "client_secret").unwrap();
    let scope = js(&cj, "scope").unwrap();
    let psz = jn(&cj, "page_size").unwrap() as i64;

    let (host, port, pp) = purl(base_url);

    let mut tok = get_tok(&host, port, &pp, &cid, &csec, &scope);

    let mut orders: Vec<JsonValue> = Vec::new();
    let mut cursor: Option<String> = None;
    let mut pages: u64 = 0;
    let mut retries: u64 = 0;
    let mut reauth: u64 = 0;
    let mut tok_used = false;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}?limit={}&cursor={}", pp, psz, penc(c))
        } else {
            format!("{}?limit={}", pp, psz)
        };

        loop {
            let ah = format!("Bearer {}", tok);
            let hdrs = vec![("Authorization".to_string(), ah)];
            let resp = http("GET", &host, port, &path, &hdrs, None);

            match resp.status {
                200 => {
                    pages += 1;
                    let bs = String::from_utf8(resp.body).unwrap();
                    let j = pj(&bs);
                    if let Some(data) = ja(&j, "data") {
                        for item in data { orders.push(item.clone()); }
                    }
                    cursor = jos(&j, "next_cursor");
                    tok_used = true;
                    break;
                }
                429 => {
                    retries += 1;
                    let ra: u64 = gh(&resp, "retry-after").trim().parse().unwrap_or(1);
                    sleep(Duration::from_secs(ra));
                }
                503 => {
                    retries += 1;
                }
                401 => {
                    if !tok_used {
                        let bs = String::from_utf8_lossy(&resp.body).to_string();
                        println!("ERROR {} {}", resp.status, bs);
                        return;
                    }
                    tok = get_tok(&host, port, &pp, &cid, &csec, &scope);
                    reauth += 1;
                    tok_used = false;
                }
                _ => {
                    let bs = String::from_utf8_lossy(&resp.body).to_string();
                    println!("ERROR {} {}", resp.status, bs);
                    return;
                }
            }
        }
        if cursor.is_none() { break; }
    }

    let mut totals: HashMap<(String,String), i64> = HashMap::new();
    let mut scounts: HashMap<String, u64> = HashMap::new();

    for o in &orders {
        let st = js(o, "status").unwrap_or_default();
        *scounts.entry(st.clone()).or_insert(0) += 1;
        if st != "cancelled" {
            let nm = jg(o, "customer").and_then(|c| js(c, "name")).unwrap_or_default();
            let cur = js(o, "currency").unwrap_or_default();
            let amt = pamt(&js(o, "amount").unwrap_or_else(|| "0".to_string()));
            *totals.entry((nm, cur)).or_insert(0) += amt;
        }
    }

    let mut tl: Vec<(String,String,i64)> = totals.into_iter().map(|((n,c),v)| (n,c,v)).collect();
    tl.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    for (n,c,v) in &tl { println!("total {} {} {}", c, fmtc(*v), n); }

    let mut sl: Vec<(String,u64)> = scounts.into_iter().collect();
    sl.sort_by(|a,b| a.0.cmp(&b.0));
    for (s,c) in &sl { println!("status {} {}", s, c); }

    println!("orders {} pages {} retries {} reauth {}", orders.len(), pages, retries, reauth);
}

use std::io::{Read, Write, BufRead, BufReader};
use std::net::TcpStream;
use std::collections::HashMap;
use std::thread::sleep;
use std::time::Duration;
use std::env;
use std::fs;

// ==================== JSON Parser ====================

#[derive(Clone)]
enum JsonValue {
    Object(Vec<(String, JsonValue)>),
    Array(Vec<JsonValue>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

struct JP<'a> { d: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(d: &'a [u8]) -> Self { JP { d, p: 0 } }
    fn ws(&mut self) { while self.p < self.d.len() && matches!(self.d[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn pk(&self) -> Option<u8> { if self.p < self.d.len() { Some(self.d[self.p]) } else { None } }

    fn parse(&mut self) -> JsonValue {
        self.ws();
        match self.pk() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => JsonValue::Str(self.string()),
            Some(b't') => { self.p += 4; JsonValue::Bool(true) }
            Some(b'f') => { self.p += 5; JsonValue::Bool(false) }
            Some(b'n') => { self.p += 4; JsonValue::Null }
            _ => self.num(),
        }
    }

    fn obj(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut f = Vec::new();
        if self.pk() == Some(b'}') { self.p += 1; return JsonValue::Object(f); }
        loop {
            self.ws(); let k = self.string(); self.ws(); self.p += 1; self.ws();
            let v = self.parse(); f.push((k, v)); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Object(f)
    }

    fn arr(&mut self) -> JsonValue {
        self.p += 1; self.ws();
        let mut a = Vec::new();
        if self.pk() == Some(b']') { self.p += 1; return JsonValue::Array(a); }
        loop {
            self.ws(); a.push(self.parse()); self.ws();
            if self.pk() == Some(b',') { self.p += 1; } else { break; }
        }
        self.ws(); self.p += 1; JsonValue::Array(a)
    }

    fn string(&mut self) -> String {
        self.p += 1;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            let c = self.d[self.p];
            if c == b'"' { self.p += 1; break; }
            if c == b'\\' {
                self.p += 1;
                let c2 = self.d[self.p];
                match c2 {
                    b'"' => { buf.push(b'"'); self.p += 1; }
                    b'\\' => { buf.push(b'\\'); self.p += 1; }
                    b'/' => { buf.push(b'/'); self.p += 1; }
                    b'b' => { buf.push(8); self.p += 1; }
                    b'f' => { buf.push(12); self.p += 1; }
                    b'n' => { buf.push(b'\n'); self.p += 1; }
                    b'r' => { buf.push(b'\r'); self.p += 1; }
                    b't' => { buf.push(b'\t'); self.p += 1; }
                    b'u' => {
                        self.p += 1;
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            utf8(&mut buf, code);
                        } else {
                            utf8(&mut buf, cp);
                        }
                    }
                    _ => { buf.push(c2); self.p += 1; }
                }
            } else { buf.push(c); self.p += 1; }
        }
        String::from_utf8(buf).unwrap()
    }

    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.d[self.p];
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => 0,
            };
            self.p += 1;
        }
        v
    }

    fn num(&mut self) -> JsonValue {
        let s = self.p;
        if self.d[self.p] == b'-' { self.p += 1; }
        while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.d.len() && self.d[self.p] == b'.' {
            self.p += 1;
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        if self.p < self.d.len() && (self.d[self.p] == b'e' || self.d[self.p] == b'E') {
            self.p += 1;
            if self.d[self.p] == b'+' || self.d[self.p] == b'-' { self.p += 1; }
            while self.p < self.d.len() && self.d[self.p].is_ascii_digit() { self.p += 1; }
        }
        JsonValue::Num(std::str::from_utf8(&self.d[s..self.p]).unwrap().parse::<f64>().unwrap())
    }
}

fn utf8(buf: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 { buf.push(cp as u8); }
    else if cp < 0x800 { buf.push(0xC0|(cp>>6) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else if cp < 0x10000 { buf.push(0xE0|(cp>>12) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
    else { buf.push(0xF0|(cp>>18) as u8); buf.push(0x80|((cp>>12)&0x3F) as u8); buf.push(0x80|((cp>>6)&0x3F) as u8); buf.push(0x80|(cp&0x3F) as u8); }
}

fn pj(s: &str) -> JsonValue { JP::new(s.as_bytes()).parse() }

fn jg<'a>(v: &'a JsonValue, k: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(f) = v { for (key, val) in f { if key == k { return Some(val); } } }
    None
}
fn js(v: &JsonValue, k: &str) -> Option<String> {
    jg(v, k).and_then(|x| if let JsonValue::Str(s) = x { Some(s.clone()) } else { None })
}
fn jn(v: &JsonValue, k: &str) -> Option<f64> {
    jg(v, k).and_then(|x| if let JsonValue::Num(n) = x { Some(*n) } else { None })
}
fn ja<'a>(v: &'a JsonValue, k: &str) -> Option<&'a Vec<JsonValue>> {
    jg(v, k).and_then(|x| if let JsonValue::Array(a) = x { Some(a) } else { None })
}
fn jos(v: &JsonValue, k: &str) -> Option<String> {
    match jg(v, k) { Some(JsonValue::Str(s)) => Some(s.clone()), _ => None }
}

// ==================== Base64 ====================

fn b64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut o = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i+1 < data.len() { data[i+1] as u32 } else { 0 };
        let b2 = if i+2 < data.len() { data[i+2] as u32 } else { 0 };
        let n = (b0<<16)|(b1<<8)|b2;
        o.push(T[(n>>18) as usize] as char);
        o.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() { o.push(T[((n>>6)&63) as usize] as char); } else { o.push('='); }
        if i+2 < data.len() { o.push(T[(n&63) as usize] as char); } else { o.push('='); }
        i += 3;
    }
    o
}

// ==================== URL encoding ====================

fn fenc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'*' => o.push(b as char),
            b' ' => o.push('+'),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

fn penc(s: &str) -> String {
    let mut o = String::new();
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z'|b'a'..=b'z'|b'0'..=b'9'|b'-'|b'.'|b'_'|b'~' => o.push(b as char),
            _ => o.push_str(&format!("%{:02X}", b)),
        }
    }
    o
}

// ==================== HTTP ====================

struct Resp { status: u16, headers: Vec<(String,String)>, body: Vec<u8> }

fn purl(url: &str) -> (String, u16, String) {
    let r = url.strip_prefix("http://").unwrap_or(url);
    let sl = r.find('/').unwrap_or(r.len());
    let hp = &r[..sl];
    let path = if sl < r.len() { &r[sl..] } else { "/" };
    let (h, p) = match hp.rfind(':') {
        Some(i) => (hp[..i].to_string(), hp[i+1..].parse::<u16>().unwrap_or(80)),
        None => (hp.to_string(), 80),
    };
    (h, p, path.to_string())
}

fn rline(r: &mut BufReader<TcpStream>) -> String {
    let mut l = String::new();
    r.read_line(&mut l).unwrap();
    if l.ends_with('\n') { l.pop(); }
    if l.ends_with('\r') { l.pop(); }
    l
}

fn http(method: &str, host: &str, port: u16, path: &str, hdrs: &[(String,String)], body: Option<&[u8]>) -> Resp {
    let mut s = TcpStream::connect((host, port)).unwrap();
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host);
    for (k, v) in hdrs { req.push_str(&format!("{}: {}\r\n", k, v)); }
    if let Some(b) = body { req.push_str(&format!("Content-Length: {}\r\n", b.len())); }
    req.push_str("Connection: close\r\n\r\n");
    s.write_all(req.as_bytes()).unwrap();
    if let Some(b) = body { s.write_all(b).unwrap(); }
    s.flush().unwrap();

    let mut r = BufReader::new(s);
    let sl = rline(&mut r);
    let status: u16 = sl.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    loop {
        let l = rline(&mut r);
        if l.is_empty() { break; }
        if let Some(c) = l.find(':') {
            headers.push((l[..c].trim().to_lowercase(), l[c+1..].trim().to_string()));
        }
    }

    let mut chunked = false;
    let mut clen: Option<usize> = None;
    for (k, v) in &headers {
        if k == "transfer-encoding" && v.to_lowercase().contains("chunked") { chunked = true; }
        if k == "content-length" { clen = v.trim().parse().ok(); }
    }

    let body_bytes = if chunked {
        let mut bd = Vec::new();
        loop {
            let szl = rline(&mut r);
            let hx = szl.split(';').next().unwrap_or("").trim();
            if hx.is_empty() { break; }
            let sz = usize::from_str_radix(hx, 16).unwrap();
            if sz == 0 {
                loop { let t = rline(&mut r); if t.is_empty() { break; } }
                break;
            }
            let mut ch = vec![0u8; sz];
            r.read_exact(&mut ch).unwrap();
            bd.extend_from_slice(&ch);
            rline(&mut r);
        }
        bd
    } else if let Some(len) = clen {
        let mut bd = vec![0u8; len];
        r.read_exact(&mut bd).unwrap();
        bd
    } else {
        let mut bd = Vec::new();
        r.read_to_end(&mut bd).unwrap();
        bd
    };

    Resp { status, headers, body: body_bytes }
}

fn gh(r: &Resp, n: &str) -> String {
    for (k, v) in &r.headers { if k == n { return v.clone(); } }
    String::new()
}

