    @SuppressWarnings("unchecked")
    static List<Block> processSSE(List<SSEEvent> events) {
        Map<Integer, Block> blockMap = new TreeMap<>();
        for (SSEEvent ev : events) {
            if (ev.data == null || ev.data.isEmpty()) continue;
            Map<String, Object> obj;
            try { obj = (Map<String, Object>) parseJson(ev.data); } catch (Exception e) { continue; }
            String type = ev.event;
            if (type == null) type = (String) obj.get("type");
            if (type == null) continue;

            if ("content_block_start".equals(type)) {
                int idx = ((Number) obj.get("index")).intValue();
                Map<String, Object> cb = (Map<String, Object>) obj.get("content_block");
                Block b = new Block();
                b.type = (String) cb.get("type");
                if ("tool_use".equals(b.type)) {
                    b.id = (String) cb.get("id");
                    b.name = (String) cb.get("name");
                }
                blockMap.put(idx, b);
            } else if ("content_block_delta".equals(type)) {
                int idx = ((Number) obj.get("index")).intValue();
                Map<String, Object> delta = (Map<String, Object>) obj.get("delta");
                if (delta == null) continue;
                Block b = blockMap.get(idx);
                if (b == null) continue;
                String dt = (String) delta.get("type");
                if ("thinking_delta".equals(dt)) {
                    b.thinking.append((String) delta.get("thinking"));
                } else if ("signature_delta".equals(dt)) {
                    b.signature.append((String) delta.get("signature"));
                } else if ("text_delta".equals(dt)) {
                    b.text.append((String) delta.get("text"));
                } else if ("input_json_delta".equals(dt)) {
                    b.rawInput.append((String) delta.get("partial_json"));
                }
            }
        }
        return new ArrayList<>(blockMap.values());
    }

    static byte[] readFile(String path) throws IOException {
        File f = new File(path);
        byte[] buf = new byte[(int) f.length()];
        try (FileInputStream fis = new FileInputStream(f)) {
            int off = 0;
            while (off < buf.length) {
                int r = fis.read(buf, off, buf.length - off);
                if (r < 0) break;
                off += r;
            }
        }
        return buf;
    }
}

