def walk_btree(data, page_num, page_size, reserved_bytes, usable_size):
    header_offset = 100 if page_num == 1 else 0
    page_start = (page_num - 1) * page_size
    page = data[page_start:page_start + page_size]

    page_type = page[header_offset]
    num_cells = struct.unpack('>H', page[header_offset + 3:header_offset + 5])[0]

    if page_type == 13:  # Leaf table page
        for i in range(num_cells):
            cell_ptr = struct.unpack('>H', page[header_offset + 8 + i * 2:header_offset + 10 + i * 2])[0]

            pos = cell_ptr
            payload_size, pos = read_varint(page, pos)
            rowid, pos = read_varint(page, pos)

            X = usable_size - 35
            if payload_size <= X:
                payload = page[pos:pos + payload_size]
            else:
                K = X + ((payload_size - X) % (usable_size - 4)) % (usable_size - 4)
                if K <= X:
                    local_size = K
                else:
                    local_size = X
                payload = page[pos:pos + local_size]
                pos += local_size
                overflow_page = struct.unpack('>I', page[pos:pos + 4])[0]
                remaining = payload_size - local_size
                while overflow_page != 0 and remaining > 0:
                    op_start = (overflow_page - 1) * page_size
                    opage = data[op_start:op_start + page_size]
                    next_overflow = struct.unpack('>I', opage[0:4])[0]
                    chunk_size = min(remaining, usable_size - 4)
                    payload += opage[4:4 + chunk_size]
                    remaining -= chunk_size
                    overflow_page = next_overflow

            yield (rowid, payload)

