import sys
import struct
import zlib
import re
from decimal import Decimal


def read_varint(data, offset):
    result = 0
    for i in range(9):
        byte = data[offset + i]
        if i < 8:
            result = (result << 7) | (byte & 0x7F)
            if byte < 0x80:
                return result, offset + i + 1
        else:
            result = (result << 8) | byte
            if result >= (1 << 63):
                result -= (1 << 64)
            return result, offset + i + 1
    raise ValueError("varint too long")


def get_serial_type_size(st):
    if st <= 9:
        return [0, 1, 2, 3, 4, 6, 8, 8, 0, 0][st]
    elif st <= 11:
        return 0
    elif st % 2 == 0:
        return (st - 12) // 2
    else:
        return (st - 13) // 2


def parse_record(payload, num_columns):
    if len(payload) == 0:
        return [('NULL', None)] * num_columns

    header_size, offset = read_varint(payload, 0)

    serial_types = []
    while offset < header_size:
        st, offset = read_varint(payload, offset)
        serial_types.append(st)

    values = []
    data_offset = header_size
    for st in serial_types:
        size = get_serial_type_size(st)
        raw = payload[data_offset:data_offset + size]
        data_offset += size

        if st == 0:
            values.append(('NULL', None))
        elif 1 <= st <= 6:
            if st == 1:
                val = struct.unpack('>b', raw)[0]
            elif st == 2:
                val = struct.unpack('>h', raw)[0]
            elif st == 3:
                val = int.from_bytes(raw, 'big', signed=True)
            elif st == 4:
                val = struct.unpack('>i', raw)[0]
            elif st == 5:
                val = int.from_bytes(raw, 'big', signed=True)
            elif st == 6:
                val = struct.unpack('>q', raw)[0]
            values.append(('INTEGER', val))
        elif st == 7:
            val = struct.unpack('>d', raw)[0]
            values.append(('REAL', val))
        elif st == 8:
            values.append(('INTEGER', 0))
        elif st == 9:
            values.append(('INTEGER', 1))
        elif st >= 12 and st % 2 == 0:
            values.append(('BLOB', raw))
        elif st >= 13 and st % 2 == 1:
            values.append(('TEXT', raw))
        else:
            values.append(('NULL', None))

    while len(values) < num_columns:
        values.append(('NULL', None))

    return values[:num_columns]


def walk_btree(data, page_num, page_size, reserved_bytes, usable_size):
    header_offset = 100 if page_num == 1 else 0
    page_start = (page_num - 1) * page_size
    page = data[page_start:page_start + page_size]

    page_type = page[header_offset]
    num_cells = struct.unpack('>H', page[header_offset + 3:header_offset + 5])[0]

    if page_type == 13:  # Leaf table page
        for i in range(num_cells):
            cell_ptr = struct.unpack('>H', page[header_offset + 8 + i * 2:header_offset + 10 + i * 2])[0]

            pos = cell_ptr
            payload_size, pos = read_varint(page, pos)
            rowid, pos = read_varint(page, pos)

            X = usable_size - 35
            if payload_size <= X:
                payload = page[pos:pos + payload_size]
            else:
                K = X + ((payload_size - X) % (usable_size - 4))
                if K <= X:
                    K = X
                local_size = K
                payload = page[pos:pos + local_size]
                pos += local_size
                overflow_page = struct.unpack('>I', page[pos:pos + 4])[0]
                remaining = payload_size - local_size
                while overflow_page != 0 and remaining > 0:
                    op_start = (overflow_page - 1) * page_size
                    if op_start < 0 or op_start + 4 > len(data):
                        break
                    opage = data[op_start:op_start + page_size]
                    next_overflow = struct.unpack('>I', opage[0:4])[0]
                    chunk_size = min(remaining, usable_size - 4)
                    payload += opage[4:4 + chunk_size]
                    remaining -= chunk_size
                    overflow_page = next_overflow

            yield (rowid, payload)

    elif page_type == 5:  # Interior table page
        for i in range(num_cells):
            cell_ptr = struct.unpack('>H', page[header_offset + 12 + i * 2:header_offset + 14 + i * 2])[0]
            left_child = struct.unpack('>I', page[cell_ptr:cell_ptr + 4])[0]
            yield from walk_btree(data, left_child, page_size, reserved_bytes, usable_size)

        right_most = struct.unpack('>I', page[header_offset + 8:header_offset + 12])[0]
        yield from walk_btree(data, right_most, page_size, reserved_bytes, usable_size)


def parse_create_table(sql):
    text = sql.strip()
    i = 0

    # Skip CREATE
    while i < len(text) and text[i].isspace():
        i += 1
    while i < len(text) and text[i].isalpha():
        i += 1
    # Skip TABLE
    while i < len(text) and text[i].isspace():
        i += 1
    while i < len(text) and text[i].isalpha():
        i += 1
    while i < len(text) and text[i].isspace():
        i += 1

    # Parse table name
    if i < len(text) and text[i] == '"':
        i += 1
        while i < len(text) and text[i] != '"':
            i += 1
        i += 1
    else:
        while i < len(text) and (text[i].isalnum() or text[i] == '_'):
            i += 1

    while i < len(text) and text[i].isspace():
        i += 1

    # Find matching parentheses
    assert text[i] == '('
    i += 1
    depth = 1
    start = i
    while i < len(text) and depth > 0:
        if text[i] == '(':
            depth += 1
        elif text[i] == ')':
            depth -= 1
        i += 1
    defs_text = text[start:i - 1]

    # Split by commas at depth 0
    defs = []
    current = []
    depth = 0
    for ch in defs_text:
        if ch == '(':
            depth += 1
            current.append(ch)
        elif ch == ')':
            depth -= 1
            current.append(ch)
        elif ch == ',' and depth == 0:
            defs.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if current:
        defs.append(''.join(current))

    columns = []
    for def_text in defs:
        col_name, is_alias = parse_column_def(def_text)
        columns.append((col_name, is_alias))

    return columns


def parse_column_def(def_text):
    text = def_text.strip()
    i = 0

    while i < len(text) and text[i].isspace():
        i += 1

    # Extract column name
    if i < len(text) and text[i] == '"':
        i += 1
        start = i
        while i < len(text) and text[i] != '"':
            i += 1
        col_name = text[start:i]
        i += 1
    else:
        start = i
        while i < len(text) and (text[i].isalnum() or text[i] == '_'):
            i += 1
        col_name = text[start:i]

    # Extract type (first identifier after column name)
    while i < len(text) and text[i].isspace():
        i += 1
    type_start = i
    while i < len(text) and (text[i].isalnum() or text[i] == '_'):
        i += 1
    type_name = text[type_start:i]

    # Check for INTEGER PRIMARY KEY
    upper_text = text.upper()
    has_pk = re.search(r'\bPRIMARY\s+KEY\b', upper_text) is not None
    is_alias = (type_name.upper() == 'INTEGER' and has_pk)

    return col_name, is_alias


def format_real(value):
    if value == 0:
        return '0.0'
    d = Decimal(value)
    sign = '-' if d < 0 else ''
    d = abs(d)
    sign_t, digits, exponent = d.as_tuple()
    digit_str = ''.join(str(d) for d in digits)

    if exponent >= 0:
        int_part = digit_str + '0' * exponent
        frac_part = '0'
    else:
        int_len = len(digit_str) + exponent
        if int_len > 0:
            int_part = digit_str[:int_len]
            frac_part = digit_str[int_len:]
        else:
            int_part = '0'
            frac_part = '0' * (-int_len) + digit_str
        frac_part = frac_part.rstrip('0')
        if not frac_part:
            frac_part = '0'

    return sign + int_part + '.' + frac_part


def escape_text(raw_bytes):
    s = raw_bytes.decode('utf-8')
    result = []
    for ch in s:
        cp = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20 or cp == 0x7F:
            result.append(f'\\x{cp:02X}')
        else:
            result.append(ch)
    return '"' + ''.join(result) + '"'


def format_value(val_type, val):
    if val_type == 'NULL':
        return 'NULL'
    elif val_type == 'INTEGER':
        return str(val)
    elif val_type == 'REAL':
        return format_real(val)
    elif val_type == 'TEXT':
        if len(val) <= 100:
            return escape_text(val)
        else:
            crc = zlib.crc32(val) & 0xFFFFFFFF
            return f'<TEXT len={len(val)} crc32={crc:08x}>'
    elif val_type == 'BLOB':
        if len(val) <= 100:
            return "X'" + val.hex().upper() + "'"
        else:
            crc = zlib.crc32(val) & 0xFFFFFFFF
            return f'<BLOB len={len(val)} crc32={crc:08x}>'
    return 'NULL'


