    static String escText(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        int i = 0;
        while (i < bytes.length) {
            int c = bytes[i] & 0xFF;
            if (c < 0x80) {
                if (c == '\\') sb.append("\\\\");
                else if (c == '"') sb.append("\\\"");
                else if (c == '\n') sb.append("\\n");
                else if (c == '\r') sb.append("\\r");
                else if (c == '\t') sb.append("\\t");
                else if (c < 0x20 || c == 0x7F) {
                    sb.append(String.format("\\x%02X", c));
                } else {
                    sb.append((char) c);
                }
                i++;
            } else {
                int seqLen = 1;
                if ((c & 0xE0) == 0xC0) seqLen = 2;
                else if ((c & 0xF0) == 0xE0) seqLen = 3;
                else if ((c & 0xF8) == 0xF0) seqLen = 4;
                if (i + seqLen > bytes.length) seqLen = bytes.length - i;
                String s = new String(bytes, i, seqLen, StandardCharsets.UTF_8);
                sb.append(s);
                i += seqLen;
            }
        }
        sb.append('"');
        return sb.toString();
    }

    static String escBlob(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        sb.append("X'");
        for (byte b : bytes) sb.append(String.format("%02X", b & 0xFF));
        sb.append("'");
        return sb.toString();
    }

    static String crc32Hex(byte[] bytes) {
        CRC32 crc = new CRC32();
        crc.update(bytes);
        return String.format("%08x", crc.getValue());
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
