/* ==================== String Buffer ==================== */
typedef struct { char *d; size_t len, cap; } sb;

static void sb_init(sb *s) { s->d = NULL; s->len = 0; s->cap = 0; }
static void sb_ensure(sb *s, size_t n) {
    if (s->len + n + 1 > s->cap) {
        s->cap = (s->len + n + 1) * 2;
        if (s->cap < 64) s->cap = 64;
        s->d = realloc(s->d, s->cap);
        if (!s->d) abort();
    }
}
static void sb_append(sb *s, const char *d, size_t n) {
    sb_ensure(s, n);
    memcpy(s->d + s->len, d, n);
    s->len += n;
    s->d[s->len] = 0;
}
static void sb_appendc(sb *s, char c) { sb_append(s, &c, 1); }
static void sb_appendf(sb *s, const char *fmt, ...) {
    char buf[256];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n < (int)sizeof(buf)) { sb_append(s, buf, n); return; }
    char *big = malloc(n + 1);
    va_start(ap, fmt);
    vsnprintf(big, n + 1, fmt, ap);
    va_end(ap);
    sb_append(s, big, n);
    free(big);
}
static void sb_free(sb *s) { free(s->d); s->d = NULL; s->len = s->cap = 0; }

/* ==================== JSON ==================== */
typedef enum { JV_NULL, JV_BOOL, JV_NUM, JV_STR, JV_ARR, JV_OBJ } jtype;
typedef struct jval {
    jtype type;
    union {
        int b;
        char *num;
        char *s;
        struct { struct jval **items; int count, cap; } arr;
        struct { char **keys; struct jval **vals; int count, cap; } obj;
    };
} jval;

static void *xmalloc(size_t n) { void *p = malloc(n); if (!p) abort(); return p; }
static char *xstrdup(const char *s) { char *p = strdup(s); if (!p) abort(); return p; }

static jval *jval_new(jtype t) {
    jval *v = xmalloc(sizeof(jval));
    memset(v, 0, sizeof(jval));
    v->type = t;
    return v;
}

static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static void utf8_encode(uint32_t cp, sb *out) {
    if (cp < 0x80) { sb_appendc(out, (char)cp); }
    else if (cp < 0x800) {
        sb_appendc(out, (char)(0xC0 | (cp >> 6)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    } else if (cp < 0x10000) {
        sb_appendc(out, (char)(0xE0 | (cp >> 12)));
        sb_appendc(out, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    } else {
        sb_appendc(out, (char)(0xF0 | (cp >> 18)));
        sb_appendc(out, (char)(0x80 | ((cp >> 12) & 0x3F)));
        sb_appendc(out, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    }
}

static int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static const char *parse_json_str(const char *s, sb *out) {
    if (*s != '"') return NULL;
    s++;
    while (*s && *s != '"') {
        if (*s == '\\') {
            s++;
            switch (*s) {
                case '"': sb_appendc(out, '"'); s++; break;
                case '\\': sb_appendc(out, '\\'); s++; break;
                case '/': sb_appendc(out, '/'); s++; break;
                case 'b': sb_appendc(out, '\b'); s++; break;
                case 'f': sb_appendc(out, '\f'); s++; break;
                case 'n': sb_appendc(out, '\n'); s++; break;
                case 'r': sb_appendc(out, '\r'); s++; break;
                case 't': sb_appendc(out, '\t'); s++; break;
                case 'u': {
                    s++;
                    int h = 0;
                    for (int i = 0; i < 4; i++) { int v = hex_val(*s); if (v < 0) return NULL; h = h * 16 + v; s++; }
                    uint32_t cp = (uint32_t)h;
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (*s == '\\' && s[1] == 'u') {
                            s += 2;
                            int l = 0;
                            for (int i = 0; i < 4; i++) { int v = hex_val(*s); if (v < 0) return NULL; l = l * 16 + v; s++; }
                            if (l >= 0xDC00 && l <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (l - 0xDC00);
                            } else {
                                utf8_encode(cp, out);
                                cp = (uint32_t)l;
                            }
                        } else {
                            cp = 0xFFFD;
                        }
                    }
                    utf8_encode(cp, out);
                    break;
                }
                default: return NULL;
            }
        } else {
            sb_appendc(out, *s);
            s++;
        }
    }
    if (*s != '"') return NULL;
    s++;
    return s;
}

static const char *parse_json(const char *s, jval **out);

static const char *parse_json_obj(const char *s, jval **out) {
    jval *v = jval_new(JV_OBJ);
    s++; /* skip { */
    s = skip_ws(s);
    if (*s == '}') { s++; *out = v; return s; }
    while (1) {
        s = skip_ws(s);
        sb key = {0};
        s = parse_json_str(s, &key);
        if (!s) { free(key.d); return NULL; }
        s = skip_ws(s);
        if (*s != ':') { free(key.d); return NULL; }
        s++;
        s = skip_ws(s);
        jval *val = NULL;
        s = parse_json(s, &val);
        if (!s) { free(key.d); return NULL; }
        if (v->count >= v->cap) {
            v->cap = v->cap ? v->cap * 2 : 4;
            v->obj.keys = realloc(v->obj.keys, v->cap * sizeof(char*));
            v->obj.vals = realloc(v->obj.vals, v->cap * sizeof(jval*));
        }
        v->obj.keys[v->count] = key.d;
        v->obj.vals[v->count] = val;
        v->count++;
        s = skip_ws(s);
        if (*s == ',') { s++; continue; }
        if (*s == '}') { s++; break; }
        return NULL;
    }
    *out = v;
    return s;
}

static const char *parse_json_arr(const char *s, jval **out) {
    jval *v = jval_new(JV_ARR);
    s++; /* skip [ */
    s = skip_ws(s);
    if (*s == ']') { s++; *out = v; return s; }
    while (1) {
        s = skip_ws(s);
        jval *item = NULL;
        s = parse_json(s, &item);
        if (!s) return NULL;
        if (v->count >= v->cap) {
            v->cap = v->cap ? v->cap * 2 : 4;
            v->arr.items = realloc(v->arr.items, v->cap * sizeof(jval*));
        }
        v->arr.items[v->count++] = item;
        s = skip_ws(s);
        if (*s == ',') { s++; continue; }
        if (*s == ']') { s++; break; }
        return NULL;
    }
    *out = v;
    return s;
}

static const char *parse_json(const char *s, jval **out) {
    s = skip_ws(s);
    if (!*s) return NULL;
    if (*s == '"') {
        sb tmp = {0};
        s = parse_json_str(s, &tmp);
        if (!s) { free(tmp.d); return NULL; }
        jval *v = jval_new(JV_STR);
        v->s = tmp.d;
        *out = v;
        return s;
    }
    if (*s == '{') return parse_json_obj(s, out);
    if (*s == '[') return parse_json_arr(s, out);
    if (!strncmp(s, "true", 4)) { jval *v = jval_new(JV_BOOL); v->b = 1; *out = v; return s + 4; }
    if (!strncmp(s, "false", 5)) { jval *v = jval_new(JV_BOOL); v->b = 0; *out = v; return s + 5; }
    if (!strncmp(s, "null", 4)) { jval *v = jval_new(JV_NULL); *out = v; return s + 4; }
    /* number */
    const char *start = s;
    if (*s == '-') s++;
    while (isdigit((unsigned char)*s)) s++;
    if (*s == '.') { s++; while (isdigit((unsigned char)*s)) s++; }
    if (*s == 'e' || *s == 'E') { s++; if (*s == '+' || *s == '-') s++; while (isdigit((unsigned char)*s)) s++; }
    if (s == start) return NULL;
    jval *v = jval_new(JV_NUM);
    size_t nlen = s - start;
    v->num = xmalloc(nlen + 1);
    memcpy(v->num, start, nlen);
    v->num[nlen] = 0;
    *out = v;
    return s;
}

static jval *jobj_get(jval *obj, const char *key) {
    if (!obj || obj->type != JV_OBJ) return NULL;
    for (int i = 0; i < obj->count; i++)
        if (!strcmp(obj->obj.keys[i], key)) return obj->obj.vals[i];
    return NULL;
}

static const char *jstr(jval *v) { return (v && v->type == JV_STR) ? v->s : NULL; }
static int jnum_int(jval *v) { return (v && v->type == JV_NUM) ? atoi(v->num) : 0; }

/* JSON serializer */
static void jser_str(sb *out, const char *s) {
    sb_appendc(out, '"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') { sb_append(out, "\\\"", 2); }
        else if (c == '\\') { sb_append(out, "\\\\", 2); }
        else if (c < 0x20) { sb_appendf(out, "\\u%04x", c); }
        else { sb_appendc(out, (char)c); }
    }
    sb_appendc(out, '"');
}

static void jser_val(sb *out, jval *v) {
    if (!v) { sb_append(out, "null", 4); return; }
    switch (v->type) {
        case JV_NULL: sb_append(out, "null", 4); break;
        case JV_BOOL: sb_append(out, v->b ? "true" : "false", v->b ? 4 : 5); break;
        case JV_NUM: sb_append(out, v->num, strlen(v->num)); break;
        case JV_STR: jser_str(out, v->s); break;
        case JV_ARR:
            sb_appendc(out, '[');
            for (int i = 0; i < v->count; i++) {
                if (i) sb_appendc(out, ',');
                jser_val(out, v->arr.items[i]);
            }
            sb_appendc(out, ']');
            break;
        case JV_OBJ:
            sb_appendc(out, '{');
            for (int i = 0; i < v->count; i++) {
                if (i) sb_appendc(out, ',');
                jser_str(out, v->obj.keys[i]);
                sb_appendc(out, ':');
                jser_val(out, v->obj.vals[i]);
            }
            sb_appendc(out, '}');
            break;
    }
}

/* ==================== Output Escaping ==================== */
static void print_escaped(const char *s) {
    if (!s) return;
    for (const char *p = s; *p; p++) {
        switch (*p) {
            case '\\': fputs("\\\\", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default: putchar(*p); break;
        }
    }
}

/* ==================== UTF-8 Utilities ==================== */
static int utf8_decode(const char *s, uint32_t *cp) {
    unsigned char c0 = (unsigned char)s[0];
    if (c0 < 0x80) { *cp = c0; return 1; }
    if ((c0 & 0xE0) == 0xC0) {
        *cp = ((uint32_t)(c0 & 0x1F) << 6) | (s[1] & 0x3F);
        return 2;
    }
    if ((c0 & 0xF0) == 0xE0) {
        *cp = ((uint32_t)(c0 & 0x0F) << 12) | ((uint32_t)(s[1] & 0x3F) << 6) | (s[2] & 0x3F);
        return 3;
    }
    if ((c0 & 0xF8) == 0xF0) {
        *cp = ((uint32_t)(c0 & 0x07) << 18) | ((uint32_t)(s[1] & 0x3F) << 12) |
              ((uint32_t)(s[2] & 0x3F) << 6) | (s[3] & 0x3F);
        return 4;
    }
    *cp = 0xFFFD;
    return 1;
}

static int utf8_count(const char *s) {
    int count = 0;
    while (*s) { uint32_t cp; s += utf8_decode(s, &cp); count++; }
    return count;
}

static int utf16_count(const char *s) {
    int count = 0;
    while (*s) {
        uint32_t cp;
        s += utf8_decode(s, &cp);
        count += (cp > 0xFFFF) ? 2 : 1;
    }
    return count;
}

static char *utf8_reverse(const char *s) {
    /* Decode to code points */
    int cap = 64, count = 0;
    uint32_t *cps = xmalloc(cap * sizeof(uint32_t));
    while (*s) {
        uint32_t cp;
        s += utf8_decode(s, &cp);
        if (count >= cap) { cap *= 2; cps = realloc(cps, cap * sizeof(uint32_t)); }
        cps[count++] = cp;
    }
    /* Reverse */
    for (int i = 0; i < count / 2; i++) {
        uint32_t tmp = cps[i];
        cps[i] = cps[count - 1 - i];
        cps[count - 1 - i] = tmp;
    }
    /* Encode back */
    sb out = {0};
    for (int i = 0; i < count; i++) utf8_encode(cps[i], &out);
    free(cps);
    return out.d ? out.d : xstrdup("");
}

/* ==================== HTTP ==================== */
static int http_connect(const char *host, int port) {
    struct addrinfo hints = {0}, *res;
    char portstr[16];
    snprintf(portstr, sizeof(portstr), "%d", port);
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int rc = getaddrinfo(host, portstr, &hints, &res);
    if (rc) return -1;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) { close(fd); freeaddrinfo(res); return -1; }
    freeaddrinfo(res);
    return fd;
}

static void send_all(int fd, const char *data, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, data + sent, len - sent, 0);
        if (n <= 0) return;
        sent += n;
    }
}

static void read_all(int fd, sb *buf) {
    char tmp[8192];
    ssize_t n;
    while ((n = recv(fd, tmp, sizeof(tmp), 0)) > 0) {
        sb_append(buf, tmp, n);
    }
}

/* Parse chunked transfer encoding */
static char *decode_chunked(const char *data, size_t len, size_t *out_len) {
    sb out = {0};
    size_t pos = 0;
    while (pos < len) {
        /* Read hex size */
        size_t size = 0;
        while (pos < len && data[pos] != '\r' && data[pos] != '\n') {
            int h = hex_val(data[pos]);
            if (h < 0) { pos++; continue; }
            size = size * 16 + h;
            pos++;
        }
        /* Skip CRLF or LF */
        while (pos < len && (data[pos] == '\r' || data[pos] == '\n')) pos++;
        if (size == 0) break;
        /* Read data */
        if (pos + size <= len) {
            sb_append(&out, data + pos, size);
            pos += size;
        } else {
            sb_append(&out, data + pos, len - pos);
            pos = len;
        }
        /* Skip trailing CRLF */
        while (pos < len && (data[pos] == '\r' || data[pos] == '\n')) pos++;
    }
    *out_len = out.len;
    return out.d ? out.d : xstrdup("");
}

/* ==================== SSE Parser ==================== */
typedef struct {
    char *event_name;
    sb data;
} sse_event;

typedef void (*sse_handler)(const char *event, const char *data, void *ctx);

static void parse_sse(const char *buf, size_t len, sse_handler handler, void *ctx) {
    sb event_name = {0};
    sb data_buf = {0};
    int have_data = 0;
    size_t pos = 0;

    while (pos <= len) {
        /* Read a line */
        size_t line_start = pos;
        while (pos < len && buf[pos] != '\n') pos++;
        size_t line_end = pos;
        if (pos < len) pos++; /* skip \n */
        /* Strip trailing \r */
        if (line_end > line_start && buf[line_end - 1] == '\r') line_end--;
        size_t line_len = line_end - line_start;

        if (line_len == 0) {
            /* Blank line: dispatch event */
            if (have_data || event_name.len > 0) {
                handler(event_name.d ? event_name.d : "", data_buf.d ? data_buf.d : "", ctx);
            }
            free(event_name.d); sb_init(&event_name);
            free(data_buf.d); sb_init(&data_buf);
            have_data = 0;
        } else if (buf[line_start] == ':') {
            /* Comment, ignore */
        } else if (line_len >= 6 && !strncmp(buf + line_start, "event:", 6)) {
            const char *v = buf + line_start + 6;
            size_t vl = line_len - 6;
            if (vl > 0 && *v == ' ') { v++; vl--; }
            free(event_name.d); sb_init(&event_name);
            sb_append(&event_name, v, vl);
        } else if (line_len >= 5 && !strncmp(buf + line_start, "data:", 5)) {
            const char *v = buf + line_start + 5;
            size_t vl = line_len - 5;
            if (vl > 0 && *v == ' ') { v++; vl--; }
            if (have_data) sb_appendc(&data_buf, '\n');
            sb_append(&data_buf, v, vl);
            have_data = 1;
        }
    }
    /* Final dispatch if needed */
    if (have_data || event_name.len > 0) {
        handler(event_name.d ? event_name.d : "", data_buf.d ? data_buf.d : "", ctx);
    }
    free(event_name.d);
    free(data_buf.d);
}

/* ==================== Content Blocks ==================== */
typedef struct {
    int index;
    char *type;
    char *thinking;
    char *signature;
    char *text;
    char *id;
    char *name;
    char *partial_json;
} cblock;

typedef struct {
    cblock *blocks;
    int count, cap;
    char *stop_reason;
    int input_tokens, output_tokens, cache_read_tokens;
} reply_state;

static cblock *get_block(reply_state *st, int idx) {
    for (int i = 0; i < st->count; i++)
        if (st->blocks[i].index == idx) return &st->blocks[i];
    if (st->count >= st->cap) {
        st->cap = st->cap ? st->cap * 2 : 8;
        st->blocks = realloc(st->blocks, st->cap * sizeof(cblock));
    }
    cblock *b = &st->blocks[st->count++];
    memset(b, 0, sizeof(cblock));
    b->index = idx;
    return b;
}

static void append_str(char **dst, const char *src, size_t n) {
    if (!src || n == 0) return;
    size_t old = *dst ? strlen(*dst) : 0;
    *dst = realloc(*dst, old + n + 1);
    memcpy(*dst + old, src, n);
    (*dst)[old + n] = 0;
}

static void sse_handler(const char *event, const char *data, void *ctx) {
    reply_state *st = (reply_state *)ctx;
    if (!event[0] || !data[0]) return;
    if (!strcmp(event, "ping")) return;

    jval *ev = NULL;
    const char *end = parse_json(data, &ev);
    if (!end || !ev) return;

    if (!strcmp(event, "message_start")) {
        jval *msg = jobj_get(ev, "message");
        jval *usage = msg ? jobj_get(msg, "usage") : NULL;
        if (usage) {
            jval *it = jobj_get(usage, "input_tokens");
            if (it && it->type == JV_NUM) st->input_tokens += atoi(it->num);
            jval *cr = jobj_get(usage, "cache_read_input_tokens");
            if (cr && cr->type == JV_NUM) st->cache_read_tokens += atoi(cr->num);
        }
    } else if (!strcmp(event, "content_block_start")) {
        jval *idxv = jobj_get(ev, "index");
        int idx = idxv ? atoi(idxv->num) : 0;
        cblock *b = get_block(st, idx);
        jval *cb = jobj_get(ev, "content_block");
        if (cb) {
            const char *t = jstr(jobj_get(cb, "type"));
            if (t) b->type = xstrdup(t);
            if (!strcmp(t, "tool_use")) {
                const char *id = jstr(jobj_get(cb, "id"));
                const char *nm = jstr(jobj_get(cb, "name"));
                if (id) b->id = xstrdup(id);
                if (nm) b->name = xstrdup(nm);
            }
        }
    } else if (!strcmp(event, "content_block_delta")) {
        jval *idxv = jobj_get(ev, "index");
        int idx = idxv ? atoi(idxv->num) : 0;
        cblock *b = get_block(st, idx);
        jval *delta = jobj_get(ev, "delta");
        if (!delta) { jval_free(ev); return; }
        const char *dtype = jstr(jobj_get(delta, "type"));
        if (!dtype) { jval_free(ev); return; }
        if (!strcmp(dtype, "thinking_delta")) {
            const char *t = jstr(jobj_get(delta, "thinking"));
            if (t) append_str(&b->thinking, t, strlen(t));
        } else if (!strcmp(dtype, "signature_delta")) {
            const char *t = jstr(jobj_get(delta, "signature"));
            if (t) append_str(&b->signature, t, strlen(t));
        } else if (!strcmp(dtype, "text_delta")) {
            const char *t = jstr(jobj_get(delta, "text"));
            if (t) append_str(&b->text, t, strlen(t));
        } else if (!strcmp(dtype, "input_json_delta")) {
            const char *t = jstr(jobj_get(delta, "partial_json"));
            if (t) append_str(&b->partial_json, t, strlen(t));
        }
    } else if (!strcmp(event, "message_delta")) {
        jval *delta = jobj_get(ev, "delta");
        if (delta) {
            const char *sr = jstr(jobj_get(delta, "stop_reason"));
            if (sr) st->stop_reason = xstrdup(sr);
        }
        jval *usage = jobj_get(ev, "usage");
        if (usage) {
            jval *ot = jobj_get(usage, "output_tokens");
            if (ot && ot->type == JV_NUM) st->output_tokens += atoi(ot->num);
        }
    }

    jval_free(ev);
}

static void jval_free(jval *v) {
    if (!v) return;
    switch (v->type) {
        case JV_STR: free(v->s); break;
        case JV_NUM: free(v->num); break;
        case JV_ARR:
            for (int i = 0; i < v->count; i++) jval_free(v->arr.items[i]);
            free(v->arr.items);
            break;
        case JV_OBJ:
            for (int i = 0; i < v->count; i++) { free(v->obj.keys[i]); jval_free(v->obj.vals[i]); }
            free(v->obj.keys); free(v->obj.vals);
            break;
        default: break;
    }
    free(v);
}

/* ==================== Tools ==================== */
static char *exec_tool(const char *name, jval *input, int *is_error) {
    *is_error = 0;
    if (strcmp(name, "measure") != 0 && strcmp(name, "reverse") != 0) {
        *is_error = 1;
        char buf[256];
        snprintf(buf, sizeof(buf), "unknown tool: %s", name);
        return xstrdup(buf);
    }
    if (strcmp(name, "measure") == 0) {
        const char *text = jstr(jobj_get(input, "text"));
        const char *unit = jstr(jobj_get(input, "unit"));
        if (!text) text = "";
        if (!unit) unit = "";
        if (!strcmp(unit, "code_points")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%d", utf8_count(text));
            return xstrdup(buf);
        } else if (!strcmp(unit, "utf8_bytes")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%zu", strlen(text));
            return xstrdup(buf);
        } else if (!strcmp(unit, "utf16_units")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%d", utf16_count(text));
            return xstrdup(buf);
        } else {
            *is_error = 1;
            char buf[256];
            snprintf(buf, sizeof(buf), "unsupported unit: %s", unit);
            return xstrdup(buf);
        }
    }
    /* reverse */
    const char *text = jstr(jobj_get(input, "text"));
    if (!text) text = "";
    return utf8_reverse(text);
}

/* ==================== Print Blocks ==================== */
static void print_blocks(reply_state *st) {
    for (int i = 0; i < st->count; i++) {
        cblock *b = &st->blocks[i];
        if (!b->type) continue;
        if (!strcmp(b->type, "thinking")) {
            printf("thinking ");
            print_escaped(b->thinking ? b->thinking : "");
            printf("\n");
            printf("signature ");
            print_escaped(b->signature ? b->signature : "");
            printf("\n");
        } else if (!strcmp(b->type, "text")) {
            printf("text ");
            print_escaped(b->text ? b->text : "");
            printf("\n");
        } else if (!strcmp(b->type, "tool_use")) {
            printf("tool_use ");
            print_escaped(b->id ? b->id : "");
            putchar(' ');
            print_escaped(b->name ? b->name : "");
            putchar(' ');
            print_escaped(b->partial_json ? b->partial_json : "");
            printf("\n");
        }
    }
}

/* ==================== Build Request Body ==================== */
static void build_request_body(sb *body, const char *model, int max_tokens,
                               int thinking_budget, jval *system, jval *tools, jval *messages) {
    sb_appendc(body, '{');
    sb_append(body, "\"model\":", 8); jser_str(body, model); sb_appendc(body, ',');
    sb_append(body, "\"max_tokens\":", 13); sb_appendf(body, "%d", max_tokens); sb_appendc(body, ',');
    sb_append(body, "\"stream\":true,", 14);
    sb_append(body, "\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":", 43);
    sb_appendf(body, "%d", thinking_budget); sb_append(body, "},", 2);
    sb_append(body, "\"system\":", 9); jser_val(body, system); sb_appendc(body, ',');
    sb_append(body, "\"tools\":", 8); jser_val(body, tools); sb_appendc(body, ',');
    sb_append(body, "\"messages\":", 11); jser_val(body, messages);
    sb_appendc(body, '}');
}

/* ==================== Parse URL ==================== */
static void parse_url(const char *url, char *host, size_t hsz, int *port, char *path, size_t psz) {
    const char *p = url;
    if (!strncmp(p, "http://", 7)) p += 7;
    else if (!strncmp(p, "https://", 8)) p += 8;
    /* host:port */
    const char *slash = strchr(p, '/');
    const char *colon = NULL;
    const char *end = slash ? slash : p + strlen(p);
    for (const char *q = p; q < end; q++) if (*q == ':') { colon = q; break; }
    if (colon) {
        size_t hlen = colon - p;
        if (hlen >= hsz) hlen = hsz - 1;
        memcpy(host, p, hlen);
        host[hlen] = 0;
        *port = atoi(colon + 1);
    } else {
        size_t hlen = end - p;
        if (hlen >= hsz) hlen = hsz - 1;
        memcpy(host, p, hlen);
        host[hlen] = 0;
        *port = 80;
    }
    if (slash) {
        strncpy(path, slash, psz - 1);
        path[psz - 1] = 0;
    } else {
        path[0] = '/';
        path[1] = 0;
    }
}

/* ==================== Make Request ==================== */
static int make_request(const char *host, int port, const char *path,
                        const char *api_key, const char *body, size_t body_len,
                        sb *resp_body, int *status, jval **err_json) {
    int fd = http_connect(host, port);
    if (fd < 0) return -1;

    sb req = {0};
    sb_appendf(&req, "POST %s HTTP/1.1\r\n", path);
    sb_appendf(&req, "Host: %s:%d\r\n", host, port);
    sb_appendf(&req, "Content-Length: %zu\r\n", body_len);
    sb_appendf(&req, "x-api-key: %s\r\n", api_key);
    sb_append(&req, "anthropic-version: 2023-06-01\r\n", 31);
    sb_append(&req, "content-type: application/json\r\n", 30);
    sb_append(&req, "\r\n", 2);
    sb_append(&req, body, body_len);

    send_all(fd, req.d, req.len);
    free(req.d);

    /* Read response */
    sb resp = {0};
    read_all(fd, &resp);
    close(fd);

    /* Parse status line */
    const char *r = resp.d;
    size_t rlen = resp.len;
    if (rlen < 12) { free(resp.d); return -1; }
    if (strncmp(r, "HTTP/1.1 ", 9) && strncmp(r, "HTTP/1.0 ", 9)) { free(resp.d); return -1; }
    *status = atoi(r + 9);

    /* Find end of headers */
    const char *hdr_end = NULL;
    for (size_t i = 0; i + 3 < rlen; i++) {
        if (r[i] == '\r' && r[i+1] == '\n' && r[i+2] == '\r' && r[i+3] == '\n') {
            hdr_end = r + i + 4;
            break;
        }
    }
    if (!hdr_end) { free(resp.d); return -1; }

    /* Parse headers for content-length and transfer-encoding */
    size_t hdr_len = hdr_end - r;
    int is_chunked = 0;
    size_t content_length = 0;
    /* Simple header parsing */
    {
        char *hdrs = xmalloc(hdr_len + 1);
        memcpy(hdrs, r, hdr_len);
        hdrs[hdr_len] = 0;
        char *line = strtok(hdrs, "\r\n");
        while (line) {
            if (!strncasecmp(line, "transfer-encoding:", 18)) {
                if (strstr(line, "chunked")) is_chunked = 1;
            } else if (!strncasecmp(line, "content-length:", 15)) {
                content_length = strtoul(line + 15, NULL, 10);
            }
            line = strtok(NULL, "\r\n");
        }
        free(hdrs);
    }

    const char *body_start = hdr_end;
    size_t body_avail = rlen - (body_start - r);

    if (is_chunked) {
        size_t out_len;
        resp_body->d = decode_chunked(body_start, body_avail, &out_len);
        resp_body->len = out_len;
        resp_body->cap = out_len + 1;
    } else {
        /* Read content-length bytes */
        if (body_avail < content_length) content_length = body_avail;
        resp_body->d = xmalloc(content_length + 1);
        memcpy(resp_body->d, body_start, content_length);
        resp_body->d[content_length] = 0;
        resp_body->len = content_length;
        resp_body->cap = content_length + 1;
    }

    free(resp.d);

    if (*status != 200 && err_json) {
        jval *ev = NULL;
        parse_json(resp_body->d, &ev);
        *err_json = ev;
    }
    return 0;
}

/* ==================== Main ==================== */
int main(int argc, char **argv) {
    if (argc < 3) return 1;
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    /* Read request.json */
    char cfg_path[4096];
    snprintf(cfg_path, sizeof(cfg_path), "%s/request.json", data_dir);
    FILE *f = fopen(cfg_path, "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long fsz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *cfg_raw = xmalloc(fsz + 1);
    fread(cfg_raw, 1, fsz, f);
    cfg_raw[fsz] = 0;
    fclose(f);

    jval *cfg = NULL;
    parse_json(cfg_raw, &cfg);
    free(cfg_raw);
    if (!cfg) return 1;

    const char *api_key = jstr(jobj_get(cfg, "api_key"));
    const char *model = jstr(jobj_get(cfg, "model"));
    int max_tokens = jnum_int(jobj_get(cfg, "max_tokens"));
    int thinking_budget = jnum_int(jobj_get(cfg, "thinking_budget"));
    jval *system = jobj_get(cfg, "system");
    const char *prompt = jstr(jobj_get(cfg, "prompt"));
    jval *tools = jobj_get(cfg, "tools");

    /* Parse URL */
    char host[256] = {0}, path[1024] = {0};
    int port = 80;
    parse_url(base_url, host, sizeof(host), &port, path, sizeof(path));
    /* Append /v1/messages */
    size_t plen = strlen(path);
    snprintf(path + plen, sizeof(path) - plen, "/v1/messages");

    int total_input = 0, total_output = 0, total_cache = 0;

    /* ===== Request 1 ===== */
    /* Build messages: [{"role":"user","content":<prompt>}] */
    jval *msg1 = jval_new(JV_ARR);
    msg1->cap = 1;
    msg1->arr.items = xmalloc(sizeof(jval*));
    jval *user_msg = jval_new(JV_OBJ);
    user_msg->cap = 2;
    user_msg->obj.keys = xmalloc(2 * sizeof(char*));
    user_msg->obj.vals = xmalloc(2 * sizeof(jval*));
    user_msg->obj.keys[0] = xstrdup("role");
    jval *rv = jval_new(JV_STR); rv->s = xstrdup("user");
    user_msg->obj.vals[0] = rv;
    user_msg->obj.keys[1] = xstrdup("content");
    jval *cv = jval_new(JV_STR); cv->s = xstrdup(prompt ? prompt : "");
    user_msg->obj.vals[1] = cv;
    user_msg->count = 2;
    msg1->arr.items[0] = user_msg;
    msg1->count = 1;

    sb body1 = {0};
    build_request_body(&body1, model, max_tokens, thinking_budget, system, tools, msg1);

    sb resp1 = {0};
    int status1 = 0;
    jval *err1 = NULL;
    if (make_request(host, port, path, api_key, body1.d, body1.len, &resp1, &status1, &err1) < 0) {
        printf("ERROR 0: connection failed\n");
        return 0;
    }
    free(body1.d);

    if (status1 != 200) {
        const char *etype = "", *emsg = "";
        if (err1) {
            jval *e = jobj_get(err1, "error");
            if (e) { etype = jstr(jobj_get(e, "type")) ? : ""; emsg = jstr(jobj_get(e, "message")) ? : ""; }
        }
        printf("ERROR %d %s: %s\n", status1, etype, emsg);
        return 0;
    }

    /* Parse SSE from resp1 */
    reply_state st1 = {0};
    parse_sse(resp1.d, resp1.len, sse_handler, &st1);
    free(resp1.d);

    total_input += st1.input_tokens;
    total_output += st1.output_tokens;
    total_cache += st1.cache_read_tokens;

    /* Print request 1 */
    printf("request 1\n");
    print_blocks(&st1);
    printf("stop_reason %s\n", st1.stop_reason ? st1.stop_reason : "");

    /* Execute tools */
    /* Collect tool_use blocks */
    typedef struct { char *id; char *result; int is_error; } tool_result;
    tool_result *results = NULL;
    int nresults = 0;

    for (int i = 0; i < st1.count; i++) {
        cblock *b = &st1.blocks[i];
        if (!b->type || strcmp(b->type, "tool_use") != 0) continue;
        /* Parse input */
        jval *input = NULL;
        const char *pj = b->partial_json ? b->partial_json : "{}";
        parse_json(pj, &input);
        if (!input) { input = jval_new(JV_OBJ); }

        int is_err = 0;
        char *res = exec_tool(b->name ? b->name : "", input, &is_err);
        jval_free(input);

        results = realloc(results, (nresults + 1) * sizeof(tool_result));
        results[nresults].id = xstrdup(b->id ? b->id : "");
        results[nresults].result = res;
        results[nresults].is_error = is_err;
        nresults++;
    }

    /* Print results */
    for (int i = 0; i < nresults; i++) {
        if (results[i].is_error)
            printf("error ");
        else
            printf("result ");
        print_escaped(results[i].id);
        putchar(' ');
        print_escaped(results[i].result);
        printf("\n");
    }

    /* ===== Request 2 ===== */
    /* Build messages array: [user_msg, assistant_msg, tool_result_msg] */
    jval *msgs2 = jval_new(JV_ARR);
    msgs2->cap = 3;
    msgs2->arr.items = xmalloc(3 * sizeof(jval*));

    /* Rebuild user message */
    jval *um = jval_new(JV_OBJ);
    um->cap = 2;
    um->obj.keys = xmalloc(2 * sizeof(char*));
    um->obj.vals = xmalloc(2 * sizeof(jval*));
    um->obj.keys[0] = xstrdup("role");
    jval *ur = jval_new(JV_STR); ur->s = xstrdup("user");
    um->obj.vals[0] = ur;
    um->obj.keys[1] = xstrdup("content");
    jval *uc = jval_new(JV_STR); uc->s = xstrdup(prompt ? prompt : "");
    um->obj.vals[1] = uc;
    um->count = 2;
    msgs2->arr.items[0] = um;

    /* Assistant message */
    jval *am = jval_new(JV_OBJ);
    am->cap = 2;
    am->obj.keys = xmalloc(2 * sizeof(char*));
    am->obj.vals = xmalloc(2 * sizeof(jval*));
    am->obj.keys[0] = xstrdup("role");
    jval *ar = jval_new(JV_STR); ar->s = xstrdup("assistant");
    am->obj.vals[0] = ar;
    am->obj.keys[1] = xstrdup("content");
    jval *ac = jval_new(JV_ARR);
    ac->cap = st1.count;
    ac->arr.items = xmalloc(st1.count * sizeof(jval*));
    int ai = 0;
    for (int i = 0; i < st1.count; i++) {
        cblock *b = &st1.blocks[i];
        if (!b->type) continue;
        if (!strcmp(b->type, "thinking")) {
            jval *blk = jval_new(JV_OBJ);
            blk->cap = 3;
            blk->obj.keys = xmalloc(3 * sizeof(char*));
            blk->obj.vals = xmalloc(3 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("thinking");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("thinking");
            jval *thv = jval_new(JV_STR); thv->s = xstrdup(b->thinking ? b->thinking : "");
            blk->obj.vals[1] = thv;
            blk->obj.keys[2] = xstrdup("signature");
            jval *sv = jval_new(JV_STR); sv->s = xstrdup(b->signature ? b->signature : "");
            blk->obj.vals[2] = sv;
            blk->count = 3;
            ac->arr.items[ai++] = blk;
        } else if (!strcmp(b->type, "text")) {
            jval *blk = jval_new(JV_OBJ);
            blk->cap = 2;
            blk->obj.keys = xmalloc(2 * sizeof(char*));
            blk->obj.vals = xmalloc(2 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("text");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("text");
            jval *txv = jval_new(JV_STR); txv->s = xstrdup(b->text ? b->text : "");
            blk->obj.vals[1] = txv;
            blk->count = 2;
            ac->arr.items[ai++] = blk;
        } else if (!strcmp(b->type, "tool_use")) {
            jval *blk = jval_new(JV_OBJ);
            blk->cap = 4;
            blk->obj.keys = xmalloc(4 * sizeof(char*));
            blk->obj.vals = xmalloc(4 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("tool_use");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("id");
            jval *idv = jval_new(JV_STR); idv->s = xstrdup(b->id ? b->id : "");
            blk->obj.vals[1] = idv;
            blk->obj.keys[2] = xstrdup("name");
            jval *nv = jval_new(JV_STR); nv->s = xstrdup(b->name ? b->name : "");
            blk->obj.vals[2] = nv;
            blk->obj.keys[3] = xstrdup("input");
            jval *inp = NULL;
            const char *pj = b->partial_json ? b->partial_json : "{}";
            parse_json(pj, &inp);
            if (!inp) inp = jval_new(JV_OBJ);
            blk->obj.vals[3] = inp;
            blk->count = 4;
            ac->arr.items[ai++] = blk;
        }
    }
    ac->count = ai;
    am->obj.vals[1] = ac;
    am->count = 2;
    msgs2->arr.items[1] = am;

    /* Tool result message */
    jval *trm = jval_new(JV_OBJ);
    trm->cap = 2;
    trm->obj.keys = xmalloc(2 * sizeof(char*));
    trm->obj.vals = xmalloc(2 * sizeof(jval*));
    trm->obj.keys[0] = xstrdup("role");
    jval *trr = jval_new(JV_STR); trr->s = xstrdup("user");
    trm->obj.vals[0] = trr;
    trm->obj.keys[1] = xstrdup("content");
    jval *trc = jval_new(JV_ARR);
    trc->cap = nresults;
    trc->arr.items = xmalloc((nresults > 0 ? nresults : 1) * sizeof(jval*));
    for (int i = 0; i < nresults; i++) {
        jval *blk = jval_new(JV_OBJ);
        blk->cap = 4;
        blk->obj.keys = xmalloc(4 * sizeof(char*));
        blk->obj.vals = xmalloc(4 * sizeof(jval*));
        blk->obj.keys[0] = xstrdup("type");
        jval *tv = jval_new(JV_STR); tv->s = xstrdup("tool_result");
        blk->obj.vals[0] = tv;
        blk->obj.keys[1] = xstrdup("tool_use_id");
        jval *idv = jval_new(JV_STR); idv->s = xstrdup(results[i].id);
        blk->obj.vals[1] = idv;
        blk->obj.keys[2] = xstrdup("content");
        jval *cv2 = jval_new(JV_STR); cv2->s = xstrdup(results[i].result);
        blk->obj.vals[2] = cv2;
        blk->count = 3;
        if (results[i].is_error) {
            blk->obj.keys[3] = xstrdup("is_error");
            jval *ie = jval_new(JV_BOOL); ie->b = 1;
            blk->obj.vals[3] = ie;
            blk->count = 4;
        }
        trc->arr.items[i] = blk;
    }
    trc->count = nresults;
    trm->obj.vals[1] = trc;
    trm->count = 2;
    msgs2->arr.items[2] = trm;
    msgs2->count = 3;

    sb body2 = {0};
    build_request_body(&body2, model, max_tokens, thinking_budget, system, tools, msgs2);

    printf("request 2\n");

    sb resp2 = {0};
    int status2 = 0;
    jval *err2 = NULL;
    if (make_request(host, port, path, api_key, body2.d, body2.len, &resp2, &status2, &err2) < 0) {
        printf("ERROR 0: connection failed\n");
        return 0;
    }
    free(body2.d);

    if (status2 != 200) {
        const char *etype = "", *emsg = "";
        if (err2) {
            jval *e = jobj_get(err2, "error");
            if (e) { etype = jstr(jobj_get(e, "type")) ? : ""; emsg = jstr(jobj_get(e, "message")) ? : ""; }
        }
        printf("ERROR %d %s: %s\n", status2, etype, emsg);
        return 0;
    }

    /* Parse SSE from resp2 */
    reply_state st2 = {0};
    parse_sse(resp2.d, resp2.len, sse_handler, &st2);
    free(resp2.d);

    total_input += st2.input_tokens;
    total_output += st2.output_tokens;
    total_cache += st2.cache_read_tokens;

    print_blocks(&st2);
    printf("stop_reason %s\n", st2.stop_reason ? st2.stop_reason : "");

    printf("usage input=%d output=%d cache_read=%d\n", total_input, total_output, total_cache);

    /* Cleanup (not strictly necessary but good practice) */
    jval_free(cfg);
    return 0;
}

