/* ==================== String Buffer ==================== */
typedef struct { char *d; size_t len, cap; } sb;

static void sb_init(sb *s) { s->d = NULL; s->len = 0; s->cap = 0; }
static void sb_ensure(sb *s, size_t n) {
    if (s->len + n + 1 > s->cap) {
        s->cap = (s->len + n + 1) * 2;
        if (s->cap < 64) s->cap = 64;
        s->d = realloc(s->d, s->cap);
        if (!s->d) abort();
    }
}
static void sb_append(sb *s, const char *d, size_t n) {
    sb_ensure(s, n);
    memcpy(s->d + s->len, d, n);
    s->len += n;
    s->d[s->len] = 0;
}
static void sb_appendc(sb *s, char c) { sb_append(s, &c, 1); }
static void sb_appendf(sb *s, const char *fmt, ...) {
    char buf[256];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n < (int)sizeof(buf)) { sb_append(s, buf, n); return; }
    char *big = malloc(n + 1);
    va_start(ap, fmt);
    vsnprintf(big, n + 1, fmt, ap);
    va_end(ap);
    sb_append(s, big, n);
    free(big);
}
static void sb_free(sb *s) { free(s->d); s->d = NULL; s->len = s->cap = 0; }

/* ==================== JSON ==================== */
typedef enum { JV_NULL, JV_BOOL, JV_NUM, JV_STR, JV_ARR, JV_OBJ } jtype;
typedef struct jval {
    jtype type;
    union {
        int b;
        char *num;
        char *s;
        struct { struct jval **items; int count, cap; } arr;
        struct { char **keys; struct jval **vals; int count, cap; } obj;
    };
} jval;

static void *xmalloc(size_t n) { void *p = malloc(n); if (!p) abort(); return p; }
static char *xstrdup(const char *s) { char *p = strdup(s); if (!p) abort(); return p; }

static jval *jval_new(jtype t) {
    jval *v = xmalloc(sizeof(jval));
    memset(v, 0, sizeof(jval));
    v->type = t;
    return v;
}

static void jval_free(jval *v) {
    if (!v) return;
    switch (v->type) {
        case JV_STR: free(v->s); break;
        case JV_NUM: free(v->num); break;
        case JV_ARR:
            for (int i = 0; i < v->arr.count; i++) jval_free(v->arr.items[i]);
            free(v->arr.items);
            break;
        case JV_OBJ:
            for (int i = 0; i < v->obj.count; i++) { free(v->obj.keys[i]); jval_free(v->obj.vals[i]); }
            free(v->obj.keys); free(v->obj.vals);
            break;
        default: break;
    }
    free(v);
}

static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static void utf8_encode(uint32_t cp, sb *out) {
    if (cp < 0x80) { sb_appendc(out, (char)cp); }
    else if (cp < 0x800) {
        sb_appendc(out, (char)(0xC0 | (cp >> 6)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    } else if (cp < 0x10000) {
        sb_appendc(out, (char)(0xE0 | (cp >> 12)));
        sb_appendc(out, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    } else {
        sb_appendc(out, (char)(0xF0 | (cp >> 18)));
        sb_appendc(out, (char)(0x80 | ((cp >> 12) & 0x3F)));
        sb_appendc(out, (char)(0x80 | ((cp >> 6) & 0x3F)));
        sb_appendc(out, (char)(0x80 | (cp & 0x3F)));
    }
}

static int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static const char *parse_json_str(const char *s, sb *out) {
    if (*s != '"') return NULL;
    s++;
    while (*s && *s != '"') {
        if (*s == '\\') {
            s++;
            switch (*s) {
                case '"': sb_appendc(out, '"'); s++; break;
                case '\\': sb_appendc(out, '\\'); s++; break;
                case '/': sb_appendc(out, '/'); s++; break;
                case 'b': sb_appendc(out, '\b'); s++; break;
                case 'f': sb_appendc(out, '\f'); s++; break;
                case 'n': sb_appendc(out, '\n'); s++; break;
                case 'r': sb_appendc(out, '\r'); s++; break;
                case 't': sb_appendc(out, '\t'); s++; break;
                case 'u': {
                    s++;
                    int h = 0;
                    for (int i = 0; i < 4; i++) { int v = hex_val(*s); if (v < 0) return NULL; h = h * 16 + v; s++; }
                    uint32_t cp = (uint32_t)h;
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (*s == '\\' && s[1] == 'u') {
                            s += 2;
                            int l = 0;
                            for (int i = 0; i < 4; i++) { int v = hex_val(*s); if (v < 0) return NULL; l = l * 16 + v; s++; }
                            if (l >= 0xDC00 && l <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (l - 0xDC00);
                            } else {
                                utf8_encode(cp, out);
                                cp = (uint32_t)l;
                            }
                        } else {
                            cp = 0xFFFD;
                        }
                    }
                    utf8_encode(cp, out);
                    break;
                }
                default: return NULL;
            }
        } else {
            sb_appendc(out, *s);
            s++;
        }
    }
    if (*s != '"') return NULL;
    s++;
    return s;
}

static const char *parse_json(const char *s, jval **out);

static const char *parse_json_obj(const char *s, jval **out) {
    jval *v = jval_new(JV_OBJ);
    s++; /* skip { */
    s = skip_ws(s);
    if (*s == '}') { s++; *out = v; return s; }
    while (1) {
        s = skip_ws(s);
        sb key = {0};
        s = parse_json_str(s, &key);
        if (!s) { free(key.d); return NULL; }
        s = skip_ws(s);
        if (*s != ':') { free(key.d); return NULL; }
        s++;
        s = skip_ws(s);
        jval *val = NULL;
        s = parse_json(s, &val);
        if (!s) { free(key.d); return NULL; }
        if (v->obj.count >= v->obj.cap) {
            v->obj.cap = v->obj.cap ? v->obj.cap * 2 : 4;
            v->obj.keys = realloc(v->obj.keys, v->obj.cap * sizeof(char*));
            v->obj.vals = realloc(v->obj.vals, v->obj.cap * sizeof(jval*));
        }
        v->obj.keys[v->obj.count] = key.d;
        v->obj.vals[v->obj.count] = val;
        v->obj.count++;
        s = skip_ws(s);
        if (*s == ',') { s++; continue; }
        if (*s == '}') { s++; break; }
        return NULL;
    }
    *out = v;
    return s;
}

static const char *parse_json_arr(const char *s, jval **out) {
    jval *v = jval_new(JV_ARR);
    s++; /* skip [ */
    s = skip_ws(s);
    if (*s == ']') { s++; *out = v; return s; }
    while (1) {
        s = skip_ws(s);
        jval *item = NULL;
        s = parse_json(s, &item);
        if (!s) return NULL;
        if (v->arr.count >= v->arr.cap) {
            v->arr.cap = v->arr.cap ? v->arr.cap * 2 : 4;
            v->arr.items = realloc(v->arr.items, v->arr.cap * sizeof(jval*));
        }
        v->arr.items[v->arr.count++] = item;
        s = skip_ws(s);
        if (*s == ',') { s++; continue; }
        if (*s == ']') { s++; break; }
        return NULL;
    }
    *out = v;
    return s;
}

static const char *parse_json(const char *s, jval **out) {
    s = skip_ws(s);
    if (!*s) return NULL;
    if (*s == '"') {
        sb tmp = {0};
        s = parse_json_str(s, &tmp);
        if (!s) { free(tmp.d); return NULL; }
        jval *v = jval_new(JV_STR);
        v->s = tmp.d;
        *out = v;
        return s;
    }
    if (*s == '{') return parse_json_obj(s, out);
    if (*s == '[') return parse_json_arr(s, out);
    if (!strncmp(s, "true", 4)) { jval *v = jval_new(JV_BOOL); v->b = 1; *out = v; return s + 4; }
    if (!strncmp(s, "false", 5)) { jval *v = jval_new(JV_BOOL); v->b = 0; *out = v; return s + 5; }
    if (!strncmp(s, "null", 4)) { jval *v = jval_new(JV_NULL); *out = v; return s + 4; }
    /* number */
    const char *start = s;
    if (*s == '-') s++;
    while (isdigit((unsigned char)*s)) s++;
    if (*s == '.') { s++; while (isdigit((unsigned char)*s)) s++; }
    if (*s == 'e' || *s == 'E') { s++; if (*s == '+' || *s == '-') s++; while (isdigit((unsigned char)*s)) s++; }
    if (s == start) return NULL;
    jval *v = jval_new(JV_NUM);
    size_t nlen = s - start;
    v->num = xmalloc(nlen + 1);
    memcpy(v->num, start, nlen);
    v->num[nlen] = 0;
    *out = v;
    return s;
}

static jval *jobj_get(jval *obj, const char *key) {
    if (!obj || obj->type != JV_OBJ) return NULL;
    for (int i = 0; i < obj->obj.count; i++)
        if (!strcmp(obj->obj.keys[i], key)) return obj->obj.vals[i];
    return NULL;
}

static const char *jstr(jval *v) { return (v && v->type == JV_STR) ? v->s : NULL; }
static int jnum_int(jval *v) { return (v && v->type == JV_NUM) ? atoi(v->num) : 0; }

/* JSON serializer */
static void jser_str(sb *out, const char *s) {
    sb_appendc(out, '"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') { sb_append(out, "\\\"", 2); }
        else if (c == '\\') { sb_append(out, "\\\\", 2); }
        else if (c < 0x20) { sb_appendf(out, "\\u%04x", c); }
        else { sb_appendc(out, (char)c); }
    }
    sb_appendc(out, '"');
}

static void jser_val(sb *out, jval *v) {
    if (!v) { sb_append(out, "null", 4); return; }
    switch (v->type) {
        case JV_NULL: sb_append(out, "null", 4); break;
        case JV_BOOL: sb_append(out, v->b ? "true" : "false", v->b ? 4 : 5); break;
        case JV_NUM: sb_append(out, v->num, strlen(v->num)); break;
        case JV_STR: jser_str(out, v->s); break;
        case JV_ARR:
            sb_appendc(out, '[');
            for (int i = 0; i < v->arr.count; i++) {
                if (i) sb_appendc(out, ',');
                jser_val(out, v->arr.items[i]);
            }
            sb_appendc(out, ']');
            break;
        case JV_OBJ:
            sb_appendc(out, '{');
            for (int i = 0; i < v->obj.count; i++) {
                if (i) sb_appendc(out, ',');
                jser_str(out, v->obj.keys[i]);
                sb_appendc(out, ':');
                jser_val(out, v->obj.vals[i]);
            }
            sb_appendc(out, '}');
            break;
    }
}

/* ==================== Output Escaping ==================== */
static void print_escaped(const char *s) {
    if (!s) return;
    for (const char *p = s; *p; p++) {
        switch (*p) {
            case '\\': fputs("\\\\", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default: putchar(*p); break;
        }
    }
}

/* ==================== UTF-8 Utilities ==================== */
static int utf8_decode(const char *s, uint32_t *cp) {
    unsigned char c0 = (unsigned char)s[0];
    if (c0 < 0x80) { *cp = c0; return 1; }
    if ((c0 & 0xE0) == 0xC0) {
        *cp = ((uint32_t)(c0 & 0x1F) << 6) | (s[1] & 0x3F);
        return 2;
    }
    if ((c0 & 0xF0) == 0xE0) {
        *cp = ((uint32_t)(c0 & 0x0F) << 12) | ((uint32_t)(s[1] & 0x3F) << 6) | (s[2] & 0x3F);
        return 3;
    }
    if ((c0 & 0xF8) == 0xF0) {
        *cp = ((uint32_t)(c0 & 0x07) << 18) | ((uint32_t)(s[1] & 0x3F) << 12) |
              ((uint32_t)(s[2] & 0x3F) << 6) | (s[3] & 0x3F);
        return 4;
    }
    *cp = 0xFFFD;
    return 1;
}

static int utf8_count(const char *s) {
    int count = 0;
    while (*s) { uint32_t cp; s += utf8_decode(s, &cp); count++; }
    return count;
}

static int utf16_count(const char *s) {
    int count = 0;
    while (*s) {
        uint32_t cp;
        s += utf8_decode(s, &cp);
        count += (cp > 0xFFFF) ? 2 : 1;
    }
    return count;
}

static char *utf8_reverse(const char *s) {
    int cap = 64, count = 0;
    uint32_t *cps = xmalloc(cap * sizeof(uint32_t));
    while (*s) {
        uint32_t cp;
        s += utf8_decode(s, &cp);
        if (count >= cap) { cap *= 2; cps = realloc(cps, cap * sizeof(uint32_t)); }
        cps[count++] = cp;
    }
    for (int i = 0; i < count / 2; i++) {
        uint32_t tmp = cps[i];
        cps[i] = cps[count - 1 - i];
        cps[count - 1 - i] = tmp;
    }
    sb out = {0};
    for (int i = 0; i < count; i++) utf8_encode(cps[i], &out);
    free(cps);
    return out.d ? out.d : xstrdup("");
}

/* ==================== HTTP ==================== */
static int http_connect(const char *host, int port) {
    struct addrinfo hints = {0}, *res;
    char portstr[16];
    snprintf(portstr, sizeof(portstr), "%d", port);
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    int rc = getaddrinfo(host, portstr, &hints, &res);
    if (rc) return -1;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) { close(fd); freeaddrinfo(res); return -1; }
    freeaddrinfo(res);
    return fd;
}

static void send_all(int fd, const char *data, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, data + sent, len - sent, 0);
        if (n <= 0) return;
        sent += n;
    }
}

static void read_all(int fd, sb *buf) {
    char tmp[8192];
    ssize_t n;
    while ((n = recv(fd, tmp, sizeof(tmp), 0)) > 0) {
        sb_append(buf, tmp, n);
    }
}

/* Parse chunked transfer encoding */
static char *decode_chunked(const char *data, size_t len, size_t *out_len) {
    sb out = {0};
    size_t pos = 0;
    while (pos < len) {
        /* Read hex size */
        size_t size = 0;
        while (pos < len && data[pos] != '\r' && data[pos] != '\n') {
            int h = hex_val(data[pos]);
            if (h < 0) { pos++; continue; }
            size = size * 16 + h;
            pos++;
        }
        /* Skip CRLF or LF */
        while (pos < len && (data[pos] == '\r' || data[pos] == '\n')) pos++;
        if (size == 0) break;
        /* Read data */
        if (pos + size <= len) {
            sb_append(&out, data + pos, size);
            pos += size;
        } else {
            sb_append(&out, data + pos, len - pos);
            pos = len;
        }
        /* Skip trailing CRLF */
        while (pos < len && (data[pos] == '\r' || data[pos] == '\n')) pos++;
    }
    *out_len = out.len;
    return out.d ? out.d : xstrdup("");
}

/* ==================== SSE Parser ==================== */
typedef void (*sse_handler)(const char *event, const char *data, void *ctx);

static void parse_sse(const char *buf, size_t len, sse_handler handler, void *ctx) {
    sb event_name = {0};
    sb data_buf = {0};
    int have_data = 0;
    size_t pos = 0;

    while (pos <= len) {
        /* Read a line */
        size_t line_start = pos;
        while (pos < len && buf[pos] != '\n') pos++;
        size_t line_end = pos;
        if (pos < len) pos++; /* skip \n */
        /* Strip trailing \r */
        if (line_end > line_start && buf[line_end - 1] == '\r') line_end--;
        size_t line_len = line_end - line_start;

        if (line_len == 0) {
            /* Blank line: dispatch event */
            if (have_data || event_name.len > 0) {
                handler(event_name.d ? event_name.d : "", data_buf.d ? data_buf.d : "", ctx);
            }
            free(event_name.d); sb_init(&event_name);
            free(data_buf.d); sb_init(&data_buf);
            have_data = 0;
        } else if (buf[line_start] == ':') {
            /* Comment, ignore */
        } else if (line_len >= 6 && !strncmp(buf + line_start, "event:", 6)) {
            const char *v = buf + line_start + 6;
            size_t vl = line_len - 6;
            if (vl > 0 && *v == ' ') { v++; vl--; }
            free(event_name.d); sb_init(&event_name);
            sb_append(&event_name, v, vl);
        } else if (line_len >= 5 && !strncmp(buf + line_start, "data:", 5)) {
            const char *v = buf + line_start + 5;
            size_t vl = line_len - 5;
            if (vl > 0 && *v == ' ') { v++; vl--; }
            if (have_data) sb_appendc(&data_buf, '\n');
            sb_append(&data_buf, v, vl);
            have_data = 1;
        }
    }
    /* Final dispatch if needed */
    if (have_data || event_name.len > 0) {
        handler(event_name.d ? event_name.d : "", data_buf.d ? data_buf.d : "", ctx);
    }
    free(event_name.d);
    free(data_buf.d);
}

/* ==================== Content Blocks ==================== */
typedef struct {
    int index;
    char *type;
    char *thinking;
    char *signature;
    char *text;
    char *id;
    char *name;
    char *partial_json;
} cblock;

typedef struct {
    cblock *blocks;
    int count, cap;
    char *stop_reason;
    int input_tokens, output_tokens, cache_read_tokens;
} reply_state;

static cblock *get_block(reply_state *st, int idx) {
    for (int i = 0; i < st->count; i++)
        if (st->blocks[i].index == idx) return &st->blocks[i];
    if (st->count >= st->cap) {
        st->cap = st->cap ? st->cap * 2 : 8;
        st->blocks = realloc(st->blocks, st->cap * sizeof(cblock));
    }
    cblock *b = &st->blocks[st->count++];
    memset(b, 0, sizeof(cblock));
    b->index = idx;
    return b;
}

static void append_str(char **dst, const char *src, size_t n) {
    if (!src || n == 0) return;
    size_t old = *dst ? strlen(*dst) : 0;
    *dst = realloc(*dst, old + n + 1);
    memcpy(*dst + old, src, n);
    (*dst)[old + n] = 0;
}

static void sse_handler(const char *event, const char *data, void *ctx) {
    reply_state *st = (reply_state *)ctx;
    if (!event[0] || !data[0]) return;
    if (!strcmp(event, "ping")) return;

    jval *ev = NULL;
    const char *end = parse_json(data, &ev);
    if (!end || !ev) return;

    if (!strcmp(event, "message_start")) {
        jval *msg = jobj_get(ev, "message");
        jval *usage = msg ? jobj_get(msg, "usage") : NULL;
        if (usage) {
            jval *it = jobj_get(usage, "input_tokens");
            if (it && it->type == JV_NUM) st->input_tokens += atoi(it->num);
            jval *cr = jobj_get(usage, "cache_read_input_tokens");
            if (cr && cr->type == JV_NUM) st->cache_read_tokens += atoi(cr->num);
        }
    } else if (!strcmp(event, "content_block_start")) {
        jval *idxv = jobj_get(ev, "index");
        int idx = idxv ? atoi(idxv->num) : 0;
        cblock *b = get_block(st, idx);
        jval *cb = jobj_get(ev, "content_block");
        if (cb) {
            const char *t = jstr(jobj_get(cb, "type"));
            if (t) b->type = xstrdup(t);
            if (t && !strcmp(t, "tool_use")) {
                const char *id = jstr(jobj_get(cb, "id"));
                const char *nm = jstr(jobj_get(cb, "name"));
                if (id) b->id = xstrdup(id);
                if (nm) b->name = xstrdup(nm);
            }
        }
    } else if (!strcmp(event, "content_block_delta")) {
        jval *idxv = jobj_get(ev, "index");
        int idx = idxv ? atoi(idxv->num) : 0;
        cblock *b = get_block(st, idx);
        jval *delta = jobj_get(ev, "delta");
        if (!delta) { jval_free(ev); return; }
        const char *dtype = jstr(jobj_get(delta, "type"));
        if (!dtype) { jval_free(ev); return; }
        if (!strcmp(dtype, "thinking_delta")) {
            const char *t = jstr(jobj_get(delta, "thinking"));
            if (t) append_str(&b->thinking, t, strlen(t));
        } else if (!strcmp(dtype, "signature_delta")) {
            const char *t = jstr(jobj_get(delta, "signature"));
            if (t) append_str(&b->signature, t, strlen(t));
        } else if (!strcmp(dtype, "text_delta")) {
            const char *t = jstr(jobj_get(delta, "text"));
            if (t) append_str(&b->text, t, strlen(t));
        } else if (!strcmp(dtype, "input_json_delta")) {
            const char *t = jstr(jobj_get(delta, "partial_json"));
            if (t) append_str(&b->partial_json, t, strlen(t));
        }
    } else if (!strcmp(event, "message_delta")) {
        jval *delta = jobj_get(ev, "delta");
        if (delta) {
            const char *sr = jstr(jobj_get(delta, "stop_reason"));
            if (sr) st->stop_reason = xstrdup(sr);
        }
        jval *usage = jobj_get(ev, "usage");
        if (usage) {
            jval *ot = jobj_get(usage, "output_tokens");
            if (ot && ot->type == JV_NUM) st->output_tokens += atoi(ot->num);
        }
    }

    jval_free(ev);
}

/* ==================== Tools ==================== */
static char *exec_tool(const char *name, jval *input, int *is_error) {
    *is_error = 0;
    if (strcmp(name, "measure") != 0 && strcmp(name, "reverse") != 0) {
        *is_error = 1;
        char buf[256];
        snprintf(buf, sizeof(buf), "unknown tool: %s", name);
        return xstrdup(buf);
    }
    if (strcmp(name, "measure") == 0) {
        const char *text = jstr(jobj_get(input, "text"));
        const char *unit = jstr(jobj_get(input, "unit"));
        if (!text) text = "";
        if (!unit) unit = "";
        if (!strcmp(unit, "code_points")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%d", utf8_count(text));
            return xstrdup(buf);
        } else if (!strcmp(unit, "utf8_bytes")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%zu", strlen(text));
            return xstrdup(buf);
        } else if (!strcmp(unit, "utf16_units")) {
            char buf[64];
            snprintf(buf, sizeof(buf), "%d", utf16_count(text));
            return xstrdup(buf);
        } else {
            *is_error = 1;
            char buf[256];
            snprintf(buf, sizeof(buf), "unsupported unit: %s", unit);
            return xstrdup(buf);
        }
    }
    /* reverse */
    const char *text = jstr(jobj_get(input, "text"));
    if (!text) text = "";
    return utf8_reverse(text);
}

/* ==================== Print Blocks ==================== */
static void print_blocks(reply_state *st) {
    for (int i = 0; i < st->count; i++) {
        cblock *b = &st->blocks[i];
        if (!b->type) continue;
        if (!strcmp(b->type, "thinking")) {
            printf("thinking ");
            print_escaped(b->thinking ? b->thinking : "");
            printf("\n");
            printf("signature ");
            print_escaped(b->signature ? b->signature : "");
            printf("\n");
        } else if (!strcmp(b->type, "text")) {
            printf("text ");
            print_escaped(b->text ? b->text : "");
            printf("\n");
        } else if (!strcmp(b->type, "tool_use")) {
            printf("tool_use ");
            print_escaped(b->id ? b->id : "");
            putchar(' ');
            print_escaped(b->name ? b->name : "");
            putchar(' ');
            print_escaped(b->partial_json ? b->partial_json : "");
            printf("\n");
        }
    }
}

/* ==================== Build Request Body ==================== */
static void build_request_body(sb *body, const char *model, int max_tokens,
                               int thinking_budget, jval *system, jval *tools, jval *messages) {
    sb_appendc(body, '{');
    sb_append(body, "\"model\":", 8); jser_str(body, model); sb_appendc(body, ',');
    sb_append(body, "\"max_tokens\":", 13); sb_appendf(body, "%d", max_tokens); sb_appendc(body, ',');
    sb_append(body, "\"stream\":true,", 14);
    sb_append(body, "\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":", 43);
    sb_appendf(body, "%d", thinking_budget); sb_append(body, "},", 2);
    sb_append(body, "\"system\":", 9); jser_val(body, system); sb_appendc(body, ',');
    sb_append(body, "\"tools\":", 8); jser_val(body, tools); sb_appendc(body, ',');
    sb_append(body, "\"messages\":", 11); jser_val(body, messages);
    sb_appendc(body, '}');
}

/* ==================== Parse URL ==================== */
static void parse_url(const char *url, char *host, size_t hsz, int *port, char *path, size_t psz) {
    const char *p = url;
    if (!strncmp(p, "http://", 7)) p += 7;
    else if (!strncmp(p, "https://", 8)) p += 8;
    /* host:port */
    const char *slash = strchr(p, '/');
    const char *colon = NULL;
    const char *end = slash ? slash : p + strlen(p);
    for (const char *q = p; q < end; q++) if (*q == ':') { colon = q; break; }
    if (colon) {
        size_t hlen = colon - p;
        if (hlen >= hsz) hlen = hsz - 1;
        memcpy(host, p, hlen);
        host[hlen] = 0;
        *port = atoi(colon + 1);
    } else {
        size_t hlen = end - p;
        if (hlen >= hsz) hlen = hsz - 1;
        memcpy(host, p, hlen);
        host[hlen] = 0;
        *port = 80;
    }
    if (slash) {
        strncpy(path, slash, psz - 1);
        path[psz - 1] = 0;
    } else {
        path[0] = '/';
        path[1] = 0;
    }
}

/* ==================== Make Request ==================== */
static int make_request(const char *host, int port, const char *path,
                        const char *api_key, const char *body, size_t body_len,
                        sb *resp_body, int *status, jval **err_json) {
    int fd = http_connect(host, port);
    if (fd < 0) return -1;

    sb req = {0};
    sb_appendf(&req, "POST %s HTTP/1.1\r\n", path);
    sb_appendf(&req, "Host: %s:%d\r\n", host, port);
    sb_appendf(&req, "Content-Length: %zu\r\n", body_len);
    sb_appendf(&req, "x-api-key: %s\r\n", api_key);
    sb_append(&req, "anthropic-version: 2023-06-01\r\n", 31);
    sb_append(&req, "content-type: application/json\r\n", 30);
    sb_append(&req, "\r\n", 2);
    sb_append(&req, body, body_len);

    send_all(fd, req.d, req.len);
    free(req.d);

    /* Read response */
    sb resp = {0};
    read_all(fd, &resp);
    close(fd);

    /* Parse status line */
    const char *r = resp.d;
    size_t rlen = resp.len;
    if (rlen < 12) { free(resp.d); return -1; }
    if (strncmp(r, "HTTP/1.1 ", 9) && strncmp(r, "HTTP/1.0 ", 9)) { free(resp.d); return -1; }
    *status = atoi(r + 9);

    /* Find end of headers */
    const char *hdr_end = NULL;
    for (size_t i = 0; i + 3 < rlen; i++) {
        if (r[i] == '\r' && r[i+1] == '\n' && r[i+2] == '\r' && r[i+3] == '\n') {
            hdr_end = r + i + 4;
            break;
        }
    }
    if (!hdr_end) { free(resp.d); return -1; }

    /* Parse headers for content-length and transfer-encoding */
    size_t hdr_len = hdr_end - r;
    int is_chunked = 0;
    size_t content_length = 0;
    {
        char *hdrs = xmalloc(hdr_len + 1);
        memcpy(hdrs, r, hdr_len);
        hdrs[hdr_len] = 0;
        char *line = strtok(hdrs, "\r\n");
        while (line) {
            if (!strncasecmp(line, "transfer-encoding:", 18)) {
                if (strstr(line, "chunked")) is_chunked = 1;
            } else if (!strncasecmp(line, "content-length:", 15)) {
                content_length = strtoul(line + 15, NULL, 10);
            }
            line = strtok(NULL, "\r\n");
        }
        free(hdrs);
    }

    const char *body_start = hdr_end;
    size_t body_avail = rlen - (body_start - r);

    if (is_chunked) {
        size_t out_len;
        resp_body->d = decode_chunked(body_start, body_avail, &out_len);
        resp_body->len = out_len;
        resp_body->cap = out_len + 1;
    } else {
        if (body_avail < content_length) content_length = body_avail;
        resp_body->d = xmalloc(content_length + 1);
        memcpy(resp_body->d, body_start, content_length);
        resp_body->d[content_length] = 0;
        resp_body->len = content_length;
        resp_body->cap = content_length + 1;
    }

    free(resp.d);

    if (*status != 200 && err_json) {
        jval *ev = NULL;
        parse_json(resp_body->d, &ev);
        *err_json = ev;
    }
    return 0;
}

/* ==================== Main ==================== */
int main(int argc, char **argv) {
    if (argc < 3) return 1;
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    /* Read request.json */
    char cfg_path[4096];
    snprintf(cfg_path, sizeof(cfg_path), "%s/request.json", data_dir);
    FILE *f = fopen(cfg_path, "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long fsz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *cfg_raw = xmalloc(fsz + 1);
    fread(cfg_raw, 1, fsz, f);
    cfg_raw[fsz] = 0;
    fclose(f);

    jval *cfg = NULL;
    parse_json(cfg_raw, &cfg);
    free(cfg_raw);
    if (!cfg) return 1;

    const char *api_key = jstr(jobj_get(cfg, "api_key"));
    const char *model = jstr(jobj_get(cfg, "model"));
    int max_tokens = jnum_int(jobj_get(cfg, "max_tokens"));
    int thinking_budget = jnum_int(jobj_get(cfg, "thinking_budget"));
    jval *system = jobj_get(cfg, "system");
    const char *prompt = jstr(jobj_get(cfg, "prompt"));
    jval *tools = jobj_get(cfg, "tools");

    /* Parse URL */
    char host[256] = {0}, path[1024] = {0};
    int port = 80;
    parse_url(base_url, host, sizeof(host), &port, path, sizeof(path));
    /* Append /v1/messages */
    size_t plen = strlen(path);
    snprintf(path + plen, sizeof(path) - plen, "/v1/messages");

    int total_input = 0, total_output = 0, total_cache = 0;

    /* ===== Request 1 ===== */
    /* Build messages: [{"role":"user","content":<prompt>}] */
    jval *msg1 = jval_new(JV_ARR);
    msg1->arr.cap = 1;
    msg1->arr.items = xmalloc(sizeof(jval*));
    jval *user_msg = jval_new(JV_OBJ);
    user_msg->obj.cap = 2;
    user_msg->obj.keys = xmalloc(2 * sizeof(char*));
    user_msg->obj.vals = xmalloc(2 * sizeof(jval*));
    user_msg->obj.keys[0] = xstrdup("role");
    jval *rv = jval_new(JV_STR); rv->s = xstrdup("user");
    user_msg->obj.vals[0] = rv;
    user_msg->obj.keys[1] = xstrdup("content");
    jval *cv = jval_new(JV_STR); cv->s = xstrdup(prompt ? prompt : "");
    user_msg->obj.vals[1] = cv;
    user_msg->obj.count = 2;
    msg1->arr.items[0] = user_msg;
    msg1->arr.count = 1;

    sb body1 = {0};
    build_request_body(&body1, model, max_tokens, thinking_budget, system, tools, msg1);

    sb resp1 = {0};
    int status1 = 0;
    jval *err1 = NULL;
    if (make_request(host, port, path, api_key, body1.d, body1.len, &resp1, &status1, &err1) < 0) {
        printf("ERROR 0: connection failed\n");
        return 0;
    }
    free(body1.d);

    if (status1 != 200) {
        const char *etype = "", *emsg = "";
        if (err1) {
            jval *e = jobj_get(err1, "error");
            if (e) { etype = jstr(jobj_get(e, "type")) ? : ""; emsg = jstr(jobj_get(e, "message")) ? : ""; }
        }
        printf("ERROR %d %s: %s\n", status1, etype, emsg);
        return 0;
    }

    /* Parse SSE from resp1 */
    reply_state st1 = {0};
    parse_sse(resp1.d, resp1.len, sse_handler, &st1);
    free(resp1.d);

    total_input += st1.input_tokens;
    total_output += st1.output_tokens;
    total_cache += st1.cache_read_tokens;

    /* Print request 1 */
    printf("request 1\n");
    print_blocks(&st1);
    printf("stop_reason %s\n", st1.stop_reason ? st1.stop_reason : "");

    /* Execute tools */
    typedef struct { char *id; char *result; int is_error; } tool_result;
    tool_result *results = NULL;
    int nresults = 0;

    for (int i = 0; i < st1.count; i++) {
        cblock *b = &st1.blocks[i];
        if (!b->type || strcmp(b->type, "tool_use") != 0) continue;
        /* Parse input */
        jval *input = NULL;
        const char *pj = b->partial_json ? b->partial_json : "{}";
        parse_json(pj, &input);
        if (!input) { input = jval_new(JV_OBJ); }

        int is_err = 0;
        char *res = exec_tool(b->name ? b->name : "", input, &is_err);
        jval_free(input);

        results = realloc(results, (nresults + 1) * sizeof(tool_result));
        results[nresults].id = xstrdup(b->id ? b->id : "");
        results[nresults].result = res;
        results[nresults].is_error = is_err;
        nresults++;
    }

    /* Print results */
    for (int i = 0; i < nresults; i++) {
        if (results[i].is_error)
            printf("error ");
        else
            printf("result ");
        print_escaped(results[i].id);
        putchar(' ');
        print_escaped(results[i].result);
        printf("\n");
    }

    /* ===== Request 2 ===== */
    /* Build messages array: [user_msg, assistant_msg, tool_result_msg] */
    jval *msgs2 = jval_new(JV_ARR);
    msgs2->arr.cap = 3;
    msgs2->arr.items = xmalloc(3 * sizeof(jval*));

    /* Rebuild user message */
    jval *um = jval_new(JV_OBJ);
    um->obj.cap = 2;
    um->obj.keys = xmalloc(2 * sizeof(char*));
    um->obj.vals = xmalloc(2 * sizeof(jval*));
    um->obj.keys[0] = xstrdup("role");
    jval *ur = jval_new(JV_STR); ur->s = xstrdup("user");
    um->obj.vals[0] = ur;
    um->obj.keys[1] = xstrdup("content");
    jval *uc = jval_new(JV_STR); uc->s = xstrdup(prompt ? prompt : "");
    um->obj.vals[1] = uc;
    um->obj.count = 2;
    msgs2->arr.items[0] = um;

    /* Assistant message */
    jval *am = jval_new(JV_OBJ);
    am->obj.cap = 2;
    am->obj.keys = xmalloc(2 * sizeof(char*));
    am->obj.vals = xmalloc(2 * sizeof(jval*));
    am->obj.keys[0] = xstrdup("role");
    jval *ar = jval_new(JV_STR); ar->s = xstrdup("assistant");
    am->obj.vals[0] = ar;
    am->obj.keys[1] = xstrdup("content");
    jval *ac = jval_new(JV_ARR);
    ac->arr.cap = st1.count > 0 ? st1.count : 1;
    ac->arr.items = xmalloc(ac->arr.cap * sizeof(jval*));
    int ai = 0;
    for (int i = 0; i < st1.count; i++) {
        cblock *b = &st1.blocks[i];
        if (!b->type) continue;
        if (!strcmp(b->type, "thinking")) {
            jval *blk = jval_new(JV_OBJ);
            blk->obj.cap = 3;
            blk->obj.keys = xmalloc(3 * sizeof(char*));
            blk->obj.vals = xmalloc(3 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("thinking");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("thinking");
            jval *thv = jval_new(JV_STR); thv->s = xstrdup(b->thinking ? b->thinking : "");
            blk->obj.vals[1] = thv;
            blk->obj.keys[2] = xstrdup("signature");
            jval *sv = jval_new(JV_STR); sv->s = xstrdup(b->signature ? b->signature : "");
            blk->obj.vals[2] = sv;
            blk->obj.count = 3;
            ac->arr.items[ai++] = blk;
        } else if (!strcmp(b->type, "text")) {
            jval *blk = jval_new(JV_OBJ);
            blk->obj.cap = 2;
            blk->obj.keys = xmalloc(2 * sizeof(char*));
            blk->obj.vals = xmalloc(2 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("text");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("text");
            jval *txv = jval_new(JV_STR); txv->s = xstrdup(b->text ? b->text : "");
            blk->obj.vals[1] = txv;
            blk->obj.count = 2;
            ac->arr.items[ai++] = blk;
        } else if (!strcmp(b->type, "tool_use")) {
            jval *blk = jval_new(JV_OBJ);
            blk->obj.cap = 4;
            blk->obj.keys = xmalloc(4 * sizeof(char*));
            blk->obj.vals = xmalloc(4 * sizeof(jval*));
            blk->obj.keys[0] = xstrdup("type");
            jval *tv = jval_new(JV_STR); tv->s = xstrdup("tool_use");
            blk->obj.vals[0] = tv;
            blk->obj.keys[1] = xstrdup("id");
            jval *idv = jval_new(JV_STR); idv->s = xstrdup(b->id ? b->id : "");
            blk->obj.vals[1] = idv;
            blk->obj.keys[2] = xstrdup("name");
            jval *nv = jval_new(JV_STR); nv->s = xstrdup(b->name ? b->name : "");
            blk->obj.vals[2] = nv;
            blk->obj.keys[3] = xstrdup("input");
            jval *inp = NULL;
            const char *pj = b->partial_json ? b->partial_json : "{}";
            parse_json(pj, &inp);
            if (!inp) inp = jval_new(JV_OBJ);
            blk->obj.vals[3] = inp;
            blk->obj.count = 4;
            ac->arr.items[ai++] = blk;
        }
    }
    ac->arr.count = ai;
    am->obj.vals[1] = ac;
    am->obj.count = 2;
    msgs2->arr.items[1] = am;

    /* Tool result message */
    jval *trm = jval_new(JV_OBJ);
    trm->obj.cap = 2;
    trm->obj.keys = xmalloc(2 * sizeof(char*));
    trm->obj.vals = xmalloc(2 * sizeof(jval*));
    trm->obj.keys[0] = xstrdup("role");
    jval *trr = jval_new(JV_STR); trr->s = xstrdup("user");
    trm->obj.vals[0] = trr;
    trm->obj.keys[1] = xstrdup("content");
    jval *trc = jval_new(JV_ARR);
    trc->arr.cap = nresults > 0 ? nresults : 1;
    trc->arr.items = xmalloc(trc->arr.cap * sizeof(jval*));
    for (int i = 0; i < nresults; i++) {
        jval *blk = jval_new(JV_OBJ);
        blk->obj.cap = 4;
        blk->obj.keys = xmalloc(4 * sizeof(char*));
        blk->obj.vals = xmalloc(4 * sizeof(jval*));
        blk->obj.keys[0] = xstrdup("type");
        jval *tv = jval_new(JV_STR); tv->s = xstrdup("tool_result");
        blk->obj.vals[0] = tv;
        blk->obj.keys[1] = xstrdup("tool_use_id");
        jval *idv = jval_new(JV_STR); idv->s = xstrdup(results[i].id);
        blk->obj.vals[1] = idv;
        blk->obj.keys[2] = xstrdup("content");
        jval *cv2 = jval_new(JV_STR); cv2->s = xstrdup(results[i].result);
        blk->obj.vals[2] = cv2;
        blk->obj.count = 3;
        if (results[i].is_error) {
            blk->obj.keys[3] = xstrdup("is_error");
            jval *ie = jval_new(JV_BOOL); ie->b = 1;
            blk->obj.vals[3] = ie;
            blk->obj.count = 4;
        }
        trc->arr.items[i] = blk;
    }
    trc->arr.count = nresults;
    trm->obj.vals[1] = trc;
    trm->obj.count = 2;
    msgs2->arr.items[2] = trm;
    msgs2->arr.count = 3;

    sb body2 = {0};
    build_request_body(&body2, model, max_tokens, thinking_budget, system, tools, msgs2);

    printf("request 2\n");

    sb resp2 = {0};
    int status2 = 0;
    jval *err2 = NULL;
    if (make_request(host, port, path, api_key, body2.d, body2.len, &resp2, &status2, &err2) < 0) {
        printf("ERROR 0: connection failed\n");
        return 0;
    }
    free(body2.d);

    if (status2 != 200) {
        const char *etype = "", *emsg = "";
        if (err2) {
            jval *e = jobj_get(err2, "error");
            if (e) { etype = jstr(jobj_get(e, "type")) ? : ""; emsg = jstr(jobj_get(e, "message")) ? : ""; }
        }
        printf("ERROR %d %s: %s\n", status2, etype, emsg);
        return 0;
    }

    /* Parse SSE from resp2 */
    reply_state st2 = {0};
    parse_sse(resp2.d, resp2.len, sse_handler, &st2);
    free(resp2.d);

    total_input += st2.input_tokens;
    total_output += st2.output_tokens;
    total_cache += st2.cache_read_tokens;

    print_blocks(&st2);
    printf("stop_reason %s\n", st2.stop_reason ? st2.stop_reason : "");

    printf("usage input=%d output=%d cache_read=%d\n", total_input, total_output, total_cache);

    /* Cleanup */
    jval_free(cfg);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

// --- CSV Parsing (RFC 4180) ---
function parseCSV(content: string): string[][] {
  if (content.charCodeAt(0) === 0xFEFF) content = content.substring(1);
  const rows: string[][] = [];
  let i = 0;
  const len = content.length;

  while (i < len) {
    const row: string[] = [];
    let endOfRecord = false;

    while (!endOfRecord) {
      let field: string;
      if (i < len && content[i] === '"') {
        i++;
        let val = '';
        while (i < len) {
          if (content[i] === '"') {
            if (i + 1 < len && content[i + 1] === '"') {
              val += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            val += content[i];
            i++;
          }
        }
        field = val;
      } else {
        let val = '';
        while (i < len && content[i] !== ',' && content[i] !== '\r' && content[i] !== '\n') {
          val += content[i];
          i++;
        }
        field = val;
      }
      row.push(field);

      if (i < len && content[i] === ',') {
        i++;
      } else {
        if (i < len && content[i] === '\r') {
          i++;
          if (i < len && content[i] === '\n') i++;
        } else if (i < len && content[i] === '\n') {
          i++;
        }
        endOfRecord = true;
      }
    }

    if (row.length > 0 && !(row.length === 1 && row[0] === '')) {
      rows.push(row);
    }
  }
  return rows;
}

// --- JSON string escaping for tool results ---
function escStr(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 0x22) r += '\\"';
    else if (c === 0x5C) r += '\\\\';
    else if (c === 0x08) r += '\\b';
    else if (c === 0x0C) r += '\\f';
    else if (c === 0x0A) r += '\\n';
    else if (c === 0x0D) r += '\\r';
    else if (c === 0x09) r += '\\t';
    else if (c < 0x20) r += '\\u00' + c.toString(16).padStart(2, '0');
    else r += s[i];
  }
  return r + '"';
}

function serializeResult(obj: Record<string, string | number>): string {
  const keys = Object.keys(obj);
  let r = '{';
  for (let i = 0; i < keys.length; i++) {
    if (i > 0) r += ',';
    r += escStr(keys[i]) + ':';
    const v = obj[keys[i]];
    if (typeof v === 'string') r += escStr(v);
    else r += String(v);
  }
  return r + '}';
}

// --- Tool execution ---
function executeTool(
  name: string,
  argsStr: string,
  inventory: Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>,
  rates: Record<string, number>
): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const item = inventory.get(sku);
    if (item) {
      return serializeResult({
        sku: item.sku,
        name: item.name,
        price_cents: item.price_cents,
        currency: item.currency,
        stock: item.stock,
      });
    } else {
      return serializeResult({ error: `unknown sku: ${sku}` });
    }
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates[from]);
    const rateTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    // HALF_UP: (2*amount*rateTo + rateFrom) / (2*rateFrom)
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = Number(numerator / denominator);
    return serializeResult({ amount_cents: converted, currency: to });
  } else {
    return serializeResult({ error: `unknown tool: ${name}` });
  }
}

// --- HTTP POST ---
function httpPost(
  url: string,
  headers: Record<string, string>,
  body: string
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const req = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port ? parseInt(parsed.port, 10) : 80,
        path: parsed.pathname + parsed.search,
        method: 'POST',
        headers: {
          ...headers,
          'Content-Length': String(Buffer.byteLength(body, 'utf-8')),
          'Host': parsed.host,
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (chunk: Buffer) => chunks.push(chunk));
        res.on('end', () => {
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString('utf-8'),
          });
        });
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

// --- Extract raw JSON text of choices[0].message from response body ---
function extractRawMessage(responseBody: string): string | null {
  // Find "choices" at top level
  let pos = findKeyValueStart(responseBody, 0, 'choices', 1);
  if (pos < 0) return null;
  if (responseBody[pos] !== '[') return null;
  pos++; // skip '['
  pos = skipWS(responseBody, pos);
  if (responseBody[pos] !== '{') return null;
  // Now find "message" key inside this first object
  return findKeyInObject(responseBody, pos, 'message');
}

function skipWS(s: string, i: number): number {
  while (i < s.length && (s[i] === ' ' || s[i] === '\t' || s[i] === '\n' || s[i] === '\r')) i++;
  return i;
}

function findKeyValueStart(json: string, start: number, key: string, targetDepth: number): number {
  let depth = 0;
  let pos = start;
  let inStr = false;
  let esc = false;
  while (pos < json.length) {
    if (esc) { esc = false; pos++; continue; }
    if (inStr) {
      if (json[pos] === '\\') esc = true;
      else if (json[pos] === '"') inStr = false;
      pos++;
      continue;
    }
    if (json[pos] === '{' || json[pos] === '[') { depth++; pos++; continue; }
    if (json[pos] === '}' || json[pos] === ']') { depth--; pos++; continue; }
    if (json[pos] === '"') {
      const s = pos;
      pos++;
      while (pos < json.length) {
        if (json[pos] === '\\') { pos += 2; continue; }
        if (json[pos] === '"') break;
        pos++;
      }
      const k = json.substring(s + 1, pos);
      pos++; // skip closing "
      if (depth === targetDepth && k === key) {
        pos = skipWS(json, pos);
        if (json[pos] === ':') pos++;
        pos = skipWS(json, pos);
        return pos;
      }
      continue;
    }
    pos++;
  }
  return -1;
}

function findKeyInObject(json: string, objStart: number, key: string): string | null {
  let depth = 0;
  let pos = objStart;
  let inStr = false;
  let esc = false;
  while (pos < json.length) {
    if (esc) { esc = false; pos++; continue; }
    if (inStr) {
      if (json[pos] === '\\') esc = true;
      else if (json[pos] === '"') inStr = false;
      pos++;
      continue;
    }
    if (json[pos] === '{' || json[pos] === '[') { depth++; pos++; continue; }
    if (json[pos] === '}' || json[pos] === ']') {
      depth--;
      if (depth === 0) break;
      pos++;
      continue;
    }
    if (json[pos] === '"') {
      const s = pos;
      pos++;
      while (pos < json.length) {
        if (json[pos] === '\\') { pos += 2; continue; }
        if (json[pos] === '"') break;
        pos++;
      }
      const k = json.substring(s + 1, pos);
      pos++;
      if (depth === 1 && k === key) {
        pos = skipWS(json, pos);
        if (json[pos] === ':') pos++;
        pos = skipWS(json, pos);
        return extractValue(json, pos);
      }
      continue;
    }
    pos++;
  }
  return null;
}

function extractValue(json: string, pos: number): string {
  if (pos >= json.length) return '';
  const ch = json[pos];
  if (ch === '{' || ch === '[') {
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = pos; i < json.length; i++) {
      if (esc) { esc = false; continue; }
      if (inStr) {
        if (json[i] === '\\') esc = true;
        else if (json[i] === '"') inStr = false;
        continue;
      }
      if (json[i] === '"') { inStr = true; continue; }
      if (json[i] === '{' || json[i] === '[') depth++;
      if (json[i] === '}' || json[i] === ']') {
        depth--;
        if (depth === 0) return json.substring(pos, i + 1);
      }
    }
    return '';
  }
  if (ch === '"') {
    let i = pos + 1;
    while (i < json.length) {
      if (json[i] === '\\') { i += 2; continue; }
      if (json[i] === '"') return json.substring(pos, i + 1);
      i++;
    }
    return '';
  }
  let i = pos;
  while (i < json.length && json[i] !== ',' && json[i] !== '}' && json[i] !== ']' && json[i] !== ' ' && json[i] !== '\t' && json[i] !== '\n' && json[i] !== '\r') i++;
  return json.substring(pos, i);
}

// --- Build request body preserving raw assistant messages ---
function buildRequestBody(model: string, messages: any[], tools: any[]): string {
  let body = '{"model":' + JSON.stringify(model) + ',"messages":[';
  for (let i = 0; i < messages.length; i++) {
    if (i > 0) body += ',';
    if (messages[i].__raw) {
      body += messages[i].__raw;
    } else {
      body += JSON.stringify(messages[i]);
    }
  }
  body += '],"tools":' + JSON.stringify(tools) + ',"tool_choice":"auto"}';
  return body;
}

// --- Main ---
async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const taskJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8'));
  const csvContent = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const ratesJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8'));

  // Parse inventory
  const csvRows = parseCSV(csvContent);
  const inventory = new Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>();
  for (let i = 1; i < csvRows.length; i++) {
    const r = csvRows[i];
    if (r.length < 5) continue;
    inventory.set(r[0], {
      sku: r[0],
      name: r[1],
      price_cents: parseInt(r[2], 10),
      currency: r[3],
      stock: parseInt(r[4], 10),
    });
  }

  const { api_key, model, system, user, tools } = taskJson;

  const conversation: any[] = [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTokens = 0;
  let requestCount = 0;
  const output: string[] = [];
  let hadError = false;

  while (true) {
    const body = buildRequestBody(model, conversation, tools);

    const resp = await httpPost(`${baseUrl}/chat/completions`, {
      'Authorization': `Bearer ${api_key}`,
      'Content-Type': 'application/json',
    }, body);

    requestCount++;

    if (resp.status !== 200) {
      let errMsg = '';
      try {
        const errJson = JSON.parse(resp.body);
        errMsg = errJson?.error?.message ?? '';
      } catch {}
      output.push(`ERROR ${resp.status} ${errMsg}`);
      hadError = true;
      break;
    }

    const respJson = JSON.parse(resp.body);

    if (respJson.usage) {
      totalPrompt += respJson.usage.prompt_tokens ?? 0;
      totalCompletion += respJson.usage.completion_tokens ?? 0;
      totalTokens += respJson.usage.total_tokens ?? 0;
    }

    const choice = respJson.choices[0];
    const msg = choice.message;
    const finish = choice.finish_reason;

    if (finish === 'stop') {
      output.push(`FINAL ${msg.content}`);
      break;
    }

    // finish_reason === 'tool_calls'
    if (typeof msg.content === 'string') {
      output.push(`SAY ${msg.content}`);
    }

    const toolCalls: any[] = msg.tool_calls ?? [];

    for (const tc of toolCalls) {
      output.push(`CALL ${tc.id} ${tc.function.name}`);
    }

    const toolResults: string[] = [];
    for (const tc of toolCalls) {
      const result = executeTool(tc.function.name, tc.function.arguments, inventory, ratesJson.rates);
      toolResults.push(result);
      output.push(`RESULT ${tc.id} ${result}`);
    }

    // Append assistant message with raw text preserved
    const rawMsg = extractRawMessage(resp.body);
    if (rawMsg) {
      conversation.push({ __raw: rawMsg });
    } else {
      conversation.push({
        role: msg.role,
        content: msg.content ?? null,
        tool_calls: msg.tool_calls,
      });
    }

    // Append tool result messages
    for (let i = 0; i < toolCalls.length; i++) {
      conversation.push({
        role: 'tool',
        tool_call_id: toolCalls[i].id,
        content: toolResults[i],
      });
    }
  }

  if (!hadError) {
    output.push(`USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalTokens} requests=${requestCount}`);
  }

  process.stdout.write(output.join('\n') + '\n');
}

main().catch((e) => {
  process.stderr.write(String(e) + '\n');
  process.exit(1);
});

import * as fs from 'fs';
import * as path from 'path';

interface ColumnDef {
    name: string;
    isRowidAlias: boolean;
}

interface TableInfo {
    name: string;
    rootPage: number;
    columns: ColumnDef[];
}

interface RowData {
    rowid: bigint;
    values: Value[];
}

type Value =
    | { type: 'null' }
    | { type: 'integer'; value: bigint }
    | { type: 'real'; value: number }
    | { type: 'text'; bytes: Uint8Array }
    | { type: 'blob'; bytes: Uint8Array };

function readU16BE(buf: Buffer, offset: number): number {
    return (buf[offset] << 8) | buf[offset + 1];
}

function readU32BE(buf: Buffer, offset: number): number {
    return buf[offset] * 16777216 + buf[offset + 1] * 65536 + buf[offset + 2] * 256 + buf[offset + 3];
}

function readVarint(buf: Buffer, offset: number): [number, number] {
    let value = 0;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = value * 128 + (b & 0x7F);
            if ((b & 0x80) === 0) return [value, offset + i + 1];
        } else {
            value = value * 256 + b;
            return [value, offset + i + 1];
        }
    }
    return [value, offset + 9];
}

function readVarintBig(buf: Buffer, offset: number): [bigint, number] {
    let value = 0n;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = (value << 7n) | BigInt(b & 0x7F);
            if ((b & 0x80) === 0) return [value, offset + i + 1];
        } else {
            value = (value << 8n) | BigInt(b);
            return [value, offset + i + 1];
        }
    }
    return [value, offset + 9];
}

function toSigned64(value: bigint): bigint {
    if (value >= 0x8000000000000000n) {
        return value - 0x10000000000000000n;
    }
    return value;
}

function readSignedInt(data: Buffer, offset: number, numBytes: number): bigint {
    let value = 0n;
    for (let i = 0; i < numBytes; i++) {
        value = (value << 8n) | BigInt(data[offset + i]);
    }
    const bits = BigInt(numBytes * 8);
    const max = 1n << (bits - 1n);
    if (value >= max) {
        value -= (1n << bits);
    }
    return value;
}

function crc32(data: Uint8Array): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >>> 1) ^ 0xEDB88320;
            } else {
                crc = crc >>> 1;
            }
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(value: number): string {
    if (Object.is(value, -0)) return '-0.0';
    if (value === 0) return '0.0';

    const buf = new ArrayBuffer(8);
    const f64 = new Float64Array(buf);
    const u32 = new Uint32Array(buf);
    f64[0] = value;

    const hi = u32[1];
    const lo = u32[0];
    const bits = (BigInt(hi) << 32n) | BigInt(lo);
    const sign = (bits >> 63n) & 1n;
    const exp = Number((bits >> 52n) & 0x7FFn);
    const frac = bits & ((1n << 52n) - 1n);

    let m: bigint;
    let e: number;

    if (exp === 0) {
        m = frac;
        e = -1074;
    } else if (exp === 0x7FF) {
        return "NaN";
    } else {
        m = frac | (1n << 52n);
        e = exp - 1075;
    }

    let negative = sign === 1n;
    let intPart: bigint;
    let fracDigits: string;

    if (e >= 0) {
        intPart = m << BigInt(e);
        fracDigits = "0";
    } else {
        const negE = -e;
        const numerator = m * (5n ** BigInt(negE));
        const denominator = 10n ** BigInt(negE);
        intPart = numerator / denominator;
        const remainder = numerator % denominator;
        fracDigits = remainder.toString().padStart(negE, '0');
        fracDigits = fracDigits.replace(/0+$/, '');
        if (fracDigits.length === 0) fracDigits = '0';
    }

    let result = intPart.toString() + '.' + fracDigits;
    if (negative) result = '-' + result;
    return result;
}

function escapeText(bytes: Uint8Array): string {
    let result = '';
    let i = 0;
    while (i < bytes.length) {
        const b = bytes[i];
        if (b === 0x5C) { result += '\\\\'; i++; }
        else if (b === 0x22) { result += '\\"'; i++; }
        else if (b === 0x0A) { result += '\\n'; i++; }
        else if (b === 0x0D) { result += '\\r'; i++; }
        else if (b === 0x09) { result += '\\t'; i++; }
        else if (b < 0x20) { result += '\\x' + b.toString(16).toUpperCase().padStart(2, '0'); i++; }
        else if (b === 0x7F) { result += '\\x7F'; i++; }
        else if (b < 0x80) { result += String.fromCharCode(b); i++; }
        else {
            let seqLen = 1;
            if (b >= 0xC0 && b < 0xE0) seqLen = 2;
            else if (b >= 0xE0 && b < 0xF0) seqLen = 3;
            else if (b >= 0xF0) seqLen = 4;
            const end = Math.min(i + seqLen, bytes.length);
            const decoder = new TextDecoder('utf-8');
            result += decoder.decode(bytes.slice(i, end));
            i = end;
        }
    }
    return result;
}

function formatValue(val: Value): string {
    switch (val.type) {
        case 'null':
            return 'NULL';
        case 'integer':
            return val.value.toString();
        case 'real':
            return formatReal(val.value);
        case 'text':
            if (val.bytes.length <= 100) {
                return '"' + escapeText(val.bytes) + '"';
            } else {
                const crc = crc32(val.bytes);
                return `<TEXT len=${val.bytes.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
            }
        case 'blob':
            if (val.bytes.length <= 100) {
                return "X'" + Buffer.from(val.bytes).toString('hex').toUpperCase() + "'";
            } else {
                const crc = crc32(val.bytes);
                return `<BLOB len=${val.bytes.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
            }
    }
}

function parseRecord(data: Buffer): Value[] {
    let pos = 0;
    const [headerSize, pos1] = readVarint(data, pos);
    pos = pos1;

    const serialTypes: number[] = [];
    while (pos < headerSize) {
        const [st, newPos] = readVarint(data, pos);
        serialTypes.push(st);
        pos = newPos;
    }

    const values: Value[] = [];
    let dataPos = headerSize;

    for (const st of serialTypes) {
        if (st === 0) {
            values.push({ type: 'null' });
        } else if (st >= 1 && st <= 4) {
            const val = readSignedInt(data, dataPos, st);
            dataPos += st;
            values.push({ type: 'integer', value: val });
        } else if (st === 5) {
            const val = readSignedInt(data, dataPos, 6);
            dataPos += 6;
            values.push({ type: 'integer', value: val });
        } else if (st === 6) {
            const val = readSignedInt(data, dataPos, 8);
            dataPos += 8;
            values.push({ type: 'integer', value: val });
        } else if (st === 7) {
            const val = data.readDoubleBE(dataPos);
            dataPos += 8;
            values.push({ type: 'real', value: val });
        } else if (st === 8) {
            values.push({ type: 'integer', value: 0n });
        } else if (st === 9) {
            values.push({ type: 'integer', value: 1n });
        } else if (st >= 12 && st % 2 === 0) {
            const len = (st - 12) / 2;
            const bytes = new Uint8Array(data.subarray(dataPos, dataPos + len));
            dataPos += len;
            values.push({ type: 'blob', bytes });
        } else if (st >= 13 && st % 2 === 1) {
            const len = (st - 13) / 2;
            const bytes = new Uint8Array(data.subarray(dataPos, dataPos + len));
            dataPos += len;
            values.push({ type: 'text', bytes });
        } else {
            values.push({ type: 'null' });
        }
    }

    return values;
}

function readOverflowChain(buf: Buffer, firstPage: number, pageSize: number, reservedBytes: number, totalNeeded: number): Buffer {
    const U = pageSize - reservedBytes;
    const dataPerOverflow = U - 4;
    const chunks: Buffer[] = [];
    let remaining = totalNeeded;
    let pageNum = firstPage;

    while (pageNum !== 0 && remaining > 0) {
        const pageStart = (pageNum - 1) * pageSize;
        const nextPage = readU32BE(buf, pageStart);
        const toRead = Math.min(remaining, dataPerOverflow);
        chunks.push(Buffer.from(buf.subarray(pageStart + 4, pageStart + 4 + toRead)));
        remaining -= toRead;
        pageNum = nextPage;
    }

    return Buffer.concat(chunks);
}

function parseLeafCell(buf: Buffer, cellOffset: number, pageSize: number, reservedBytes: number): RowData {
    let pos = cellOffset;
    const [payloadSize, pos1] = readVarint(buf, pos);
    pos = pos1;
    const [rowidUnsigned, pos2] = readVarintBig(buf, pos);
    pos = pos2;

    const rowid = toSigned64(rowidUnsigned);

    const U = pageSize - reservedBytes;
    let localSize: number;
    if (payloadSize <= U - 35) {
        localSize = payloadSize;
    } else {
        localSize = Math.floor((U - 12) * 32 / 255) - 23;
        if (localSize < 35) localSize = 35;
    }
    if (localSize > payloadSize) localSize = payloadSize;

    let fullPayload: Buffer;
    if (payloadSize > localSize) {
        const localPayload = Buffer.from(buf.subarray(pos, pos + localSize));
        const overflowPageNum = readU32BE(buf, pos + localSize);
        const overflowData = readOverflowChain(buf, overflowPageNum, pageSize, reservedBytes, payloadSize - localSize);
        fullPayload = Buffer.concat([localPayload, overflowData]);
    } else {
        fullPayload = Buffer.from(buf.subarray(pos, pos + localSize));
    }

    const values = parseRecord(fullPayload);
    return { rowid, values };
}

function walkTableBTree(buf: Buffer, rootPage: number, pageSize: number, reservedBytes: number): RowData[] {
    const rows: RowData[] = [];
    walkPage(buf, rootPage, pageSize, reservedBytes, rows);
    return rows;
}

function walkPage(buf: Buffer, pageNum: number, pageSize: number, reservedBytes: number, rows: RowData[]) {
    const pageStart = (pageNum - 1) * pageSize;
    const headerOffset = pageNum === 1 ? 100 : 0;
    const pageType = buf[pageStart + headerOffset];

    if (pageType === 13) {
        // Leaf table b-tree
        const numCells = readU16BE(buf, pageStart + headerOffset + 3);
        const cellPtrStart = pageStart + headerOffset + 8;

        for (let i = 0; i < numCells; i++) {
            const cellOffset = readU16BE(buf, cellPtrStart + i * 2);
            const row = parseLeafCell(buf, pageStart + cellOffset, pageSize, reservedBytes);
            rows.push(row);
        }
    } else if (pageType === 5) {
        // Interior table b-tree
        const numCells = readU16BE(buf, pageStart + headerOffset + 3);
        const cellPtrStart = pageStart + headerOffset + 12;

        for (let i = 0; i < numCells; i++) {
            const cellOffset = readU16BE(buf, cellPtrStart + i * 2);
            const childPage = readU32BE(buf, pageStart + cellOffset);
            walkPage(buf, childPage, pageSize, reservedBytes, rows);
        }

        const rightMost = readU32BE(buf, pageStart + headerOffset + 8);
        walkPage(buf, rightMost, pageSize, reservedBytes, rows);
    }
}

function parseColumns(sql: string): ColumnDef[] {
    // Find the first '(' not inside a double-quoted string
    let openPos = -1;
    let inQuote = false;
    for (let i = 0; i < sql.length; i++) {
        if (sql[i] === '"') {
            inQuote = !inQuote;
        } else if (sql[i] === '(' && !inQuote) {
            openPos = i;
            break;
        }
    }
    if (openPos === -1) return [];

    // Find matching ')'
    let closePos = -1;
    let depth = 0;
    inQuote = false;
    for (let i = openPos; i < sql.length; i++) {
        if (sql[i] === '"') {
            inQuote = !inQuote;
        } else if (!inQuote) {
            if (sql[i] === '(') depth++;
            else if (sql[i] === ')') {
                depth--;
                if (depth === 0) { closePos = i; break; }
            }
        }
    }
    if (closePos === -1) return [];

    const defs = sql.substring(openPos + 1, closePos);

    // Split by commas not inside parentheses or double-quoted strings
    const parts: string[] = [];
    depth = 0;
    inQuote = false;
    let current = '';
    for (let j = 0; j < defs.length; j++) {
        if (defs[j] === '"') {
            inQuote = !inQuote;
            current += defs[j];
        } else if (!inQuote) {
            if (defs[j] === '(') { depth++; current += defs[j]; }
            else if (defs[j] === ')') { depth--; current += defs[j]; }
            else if (defs[j] === ',' && depth === 0) {
                parts.push(current);
                current = '';
            } else {
                current += defs[j];
            }
        } else {
            current += defs[j];
        }
    }
    if (current.trim().length > 0) parts.push(current);

    const columns: ColumnDef[] = [];
    for (let part of parts) {
        part = part.trim();
        if (part.length === 0) continue;

        let colName: string;
        let rest: string;
        if (part[0] === '"') {
            const end = part.indexOf('"', 1);
            colName = part.substring(1, end);
            rest = part.substring(end + 1);
        } else {
            let j = 0;
            while (j < part.length && /[a-zA-Z0-9_]/.test(part[j])) j++;
            colName = part.substring(0, j);
            rest = part.substring(j);
        }

        // Determine type word
        const restTrimmed = rest.trim();
        let typeWord = '';
        if (restTrimmed.length > 0 && /[a-zA-Z_]/.test(restTrimmed[0])) {
            let j = 0;
            while (j < restTrimmed.length && /[a-zA-Z0-9_]/.test(restTrimmed[j])) j++;
            typeWord = restTrimmed.substring(0, j);
        }

        // Check if type is followed by '(' (making it not a "single word")
        let typeFollowedByParen = false;
        if (typeWord.length > 0) {
            const afterType = restTrimmed.substring(typeWord.length);
            const afterTypeTrimmed = afterType.trimStart();
            if (afterTypeTrimmed.length > 0 && afterTypeTrimmed[0] === '(') {
                typeFollowedByParen = true;
            }
        }

        const isRowidAlias = typeWord.toUpperCase() === 'INTEGER' &&
                             !typeFollowedByParen &&
                             /\bPRIMARY\s+KEY\b/i.test(rest);

        columns.push({ name: colName, isRowidAlias });
    }

    return columns;
}

function main() {
    const dir = process.argv[2];
    if (!dir) {
        process.stderr.write("Usage: main.ts <directory>\n");
        process.exit(1);
    }

    const filePath = path.join(dir, 'db.sqlite');
    const fileBuf = fs.readFileSync(filePath);

    // Parse file header
    let pageSize = readU16BE(fileBuf, 16);
    if (pageSize === 1) pageSize = 65536;
    const reservedBytes = fileBuf[20];

    // Walk schema b-tree (rooted at page 1)
    const schemaRows = walkTableBTree(fileBuf, 1, pageSize, reservedBytes);

    // Find tables
    const tables: TableInfo[] = [];
    for (const row of schemaRows) {
        if (row.values.length < 5) continue;
        const typeVal = row.values[0];
        const nameVal = row.values[1];
        const rootPageVal = row.values[3];
        const sqlVal = row.values[4];

        if (typeVal.type !== 'text') continue;
        const typeStr = Buffer.from(typeVal.bytes).toString('utf-8');
        if (typeStr !== 'table') continue;

        if (nameVal.type !== 'text') continue;
        const name = Buffer.from(nameVal.bytes).toString('utf-8');
        if (name.startsWith('sqlite_')) continue;

        if (rootPageVal.type !== 'integer') continue;
        const rootPage = Number(rootPageVal.value);

        if (sqlVal.type !== 'text') continue;
        const sql = Buffer.from(sqlVal.bytes).toString('utf-8');

        const columns = parseColumns(sql);
        tables.push({ name, rootPage, columns });
    }

    // Sort by name (byte-wise)
    tables.sort((a, b) => {
        return Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8'));
    });

    // Output
    const outputLines: string[] = [];
    for (let t = 0; t < tables.length; t++) {
        if (t > 0) outputLines.push('');
        const table = tables[t];
        const rows = walkTableBTree(fileBuf, table.rootPage, pageSize, reservedBytes);

        outputLines.push(`TABLE ${table.name} rows=${rows.length}`);
        outputLines.push(`COLUMNS ${table.columns.map(c => c.name).join(', ')}`);

        for (const row of rows) {
            const vals: string[] = [];
            for (let c = 0; c < table.columns.length; c++) {
                const col = table.columns[c];
                if (col.isRowidAlias) {
                    vals.push(row.rowid.toString());
                } else if (c < row.values.length) {
                    vals.push(formatValue(row.values[c]));
                } else {
                    vals.push('NULL');
                }
            }
            outputLines.push(`${row.rowid}: ${vals.join(', ')}`);
        }
    }

    process.stdout.write(outputLines.join('\n') + '\n');
}

main();

import * as fs from 'fs';
import * as path from 'path';

interface ColumnDef {
    name: string;
    isRowidAlias: boolean;
}

interface TableInfo {
    name: string;
    rootPage: number;
    columns: ColumnDef[];
}

interface RowData {
    rowid: bigint;
    values: Value[];
}

type Value =
    | { type: 'null' }
    | { type: 'integer'; value: bigint }
    | { type: 'real'; value: number }
    | { type: 'text'; bytes: Uint8Array }
    | { type: 'blob'; bytes: Uint8Array };

function readU16BE(buf: Buffer, offset: number): number {
    return (buf[offset] << 8) | buf[offset + 1];
}

function readU32BE(buf: Buffer, offset: number): number {
    return buf[offset] * 16777216 + buf[offset + 1] * 65536 + buf[offset + 2] * 256 + buf[offset + 3];
}

function readVarint(buf: Buffer, offset: number): [number, number] {
    let value = 0;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = value * 128 + (b & 0x7F);
            if ((b & 0x80) === 0) return [value, offset + i + 1];
        } else {
            value = value * 256 + b;
            return [value, offset + i + 1];
        }
    }
    return [value, offset + 9];
}

function readVarintBig(buf: Buffer, offset: number): [bigint, number] {
    let value = 0n;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = (value << 7n) | BigInt(b & 0x7F);
            if ((b & 0x80) === 0) return [value, offset + i + 1];
        } else {
            value = (value << 8n) | BigInt(b);
            return [value, offset + i + 1];
        }
    }
    return [value, offset + 9];
}

function toSigned64(value: bigint): bigint {
    if (value >= 0x8000000000000000n) {
        return value - 0x10000000000000000n;
    }
    return value;
}

function readSignedInt(data: Buffer, offset: number, numBytes: number): bigint {
    let value = 0n;
    for (let i = 0; i < numBytes; i++) {
        value = (value << 8n) | BigInt(data[offset + i]);
    }
    const bits = BigInt(numBytes * 8);
    const max = 1n << (bits - 1n);
    if (value >= max) {
        value -= (1n << bits);
    }
    return value;
}

function crc32(data: Uint8Array): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >>> 1) ^ 0xEDB88320;
            } else {
                crc = crc >>> 1;
            }
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(value: number): string {
    if (Object.is(value, -0)) return '-0.0';
    if (value === 0) return '0.0';

    const buf = new ArrayBuffer(8);
    const f64 = new Float64Array(buf);
    const u32 = new Uint32Array(buf);
    f64[0] = value;

    const hi = u32[1];
    const lo = u32[0];
    const bits = (BigInt(hi) << 32n) | BigInt(lo);
    const sign = (bits >> 63n) & 1n;
    const exp = Number((bits >> 52n) & 0x7FFn);
    const frac = bits & ((1n << 52n) - 1n);

    let m: bigint;
    let e: number;

    if (exp === 0) {
        m = frac;
        e = -1074;
    } else if (exp === 0x7FF) {
        return "NaN";
    } else {
        m = frac | (1n << 52n);
        e = exp - 1075;
    }

    let negative = sign === 1n;
    let intPart: bigint;
    let fracDigits: string;

    if (e >= 0) {
        intPart = m << BigInt(e);
        fracDigits = "0";
    } else {
        const negE = -e;
        const numerator = m * (5n ** BigInt(negE));
        const denominator = 10n ** BigInt(negE);
        intPart = numerator / denominator;
        const remainder = numerator % denominator;
        fracDigits = remainder.toString().padStart(negE, '0');
        fracDigits = fracDigits.replace(/0+$/, '');
        if (fracDigits.length === 0) fracDigits = '0';
    }

    let result = intPart.toString() + '.' + fracDigits;
    if (negative) result = '-' + result;
    return result;
}

function escapeText(bytes: Uint8Array): string {
    let result = '';
    let i = 0;
    while (i < bytes.length) {
        const b = bytes[i];
        if (b === 0x5C) { result += '\\\\'; i++; }
        else if (b === 0x22) { result += '\\"'; i++; }
        else if (b === 0x0A) { result += '\\n'; i++; }
        else if (b === 0x0D) { result += '\\r'; i++; }
        else if (b === 0x09) { result += '\\t'; i++; }
        else if (b < 0x20) { result += '\\x' + b.toString(16).toUpperCase().padStart(2, '0'); i++; }
        else if (b === 0x7F) { result += '\\x7F'; i++; }
        else if (b < 0x80) { result += String.fromCharCode(b); i++; }
        else {
            let seqLen = 1;
            if (b >= 0xC0 && b < 0xE0) seqLen = 2;
            else if (b >= 0xE0 && b < 0xF0) seqLen = 3;
            else if (b >= 0xF0) seqLen = 4;
            const end = Math.min(i + seqLen, bytes.length);
            const decoder = new TextDecoder('utf-8');
            result += decoder.decode(bytes.slice(i, end));
            i = end;
        }
    }
    return result;
}

function formatValue(val: Value): string {
    switch (val.type) {
        case 'null':
            return 'NULL';
        case 'integer':
            return val.value.toString();
        case 'real':
            return formatReal(val.value);
        case 'text':
            if (val.bytes.length <= 100) {
                return '"' + escapeText(val.bytes) + '"';
            } else {
                const crc = crc32(val.bytes);
                return `<TEXT len=${val.bytes.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
            }
        case 'blob':
            if (val.bytes.length <= 100) {
                return "X'" + Buffer.from(val.bytes).toString('hex').toUpperCase() + "'";
            } else {
                const crc = crc32(val.bytes);
                return `<BLOB len=${val.bytes.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
            }
    }
}

function parseRecord(data: Buffer): Value[] {
    let pos = 0;
    const [headerSize, pos1] = readVarint(data, pos);
    pos = pos1;

    const serialTypes: number[] = [];
    while (pos < headerSize) {
        const [st, newPos] = readVarint(data, pos);
        serialTypes.push(st);
        pos = newPos;
    }

    const values: Value[] = [];
    let dataPos = headerSize;

    for (const st of serialTypes) {
        if (st === 0) {
            values.push({ type: 'null' });
        } else if (st >= 1 && st <= 4) {
            const val = readSignedInt(data, dataPos, st);
            dataPos += st;
            values.push({ type: 'integer', value: val });
        } else if (st === 5) {
            const val = readSignedInt(data, dataPos, 6);
            dataPos += 6;
            values.push({ type: 'integer', value: val });
        } else if (st === 6) {
            const val = readSignedInt(data, dataPos, 8);
            dataPos += 8;
            values.push({ type: 'integer', value: val });
        } else if (st === 7) {
            const val = data.readDoubleBE(dataPos);
            dataPos += 8;
            values.push({ type: 'real', value: val });
        } else if (st === 8) {
            values.push({ type: 'integer', value: 0n });
        } else if (st === 9) {
            values.push({ type: 'integer', value: 1n });
        } else if (st >= 12 && st % 2 === 0) {
            const len = (st - 12) / 2;
            const bytes = new Uint8Array(data.subarray(dataPos, dataPos + len));
            dataPos += len;
            values.push({ type: 'blob', bytes });
        } else if (st >= 13 && st % 2 === 1) {
            const len = (st - 13) / 2;
            const bytes = new Uint8Array(data.subarray(dataPos, dataPos + len));
            dataPos += len;
            values.push({ type: 'text', bytes });
        } else {
            values.push({ type: 'null' });
        }
    }

    return values;
}

function readOverflowChain(buf: Buffer, firstPage: number, pageSize: number, reservedBytes: number, totalNeeded: number): Buffer {
    const U = pageSize - reservedBytes;
    const dataPerOverflow = U - 4;
    const chunks: Buffer[] = [];
    let remaining = totalNeeded;
    let pageNum = firstPage;

    while (pageNum !== 0 && remaining > 0) {
        const pageStart = (pageNum - 1) * pageSize;
        const nextPage = readU32BE(buf, pageStart);
        const toRead = Math.min(remaining, dataPerOverflow);
        chunks.push(Buffer.from(buf.subarray(pageStart + 4, pageStart + 4 + toRead)));
        remaining -= toRead;
        pageNum = nextPage;
    }

    return Buffer.concat(chunks);
}

function parseLeafCell(buf: Buffer, cellOffset: number, pageSize: number, reservedBytes: number): RowData {
    let pos = cellOffset;
    const [payloadSize, pos1] = readVarint(buf, pos);
    pos = pos1;
    const [rowidUnsigned, pos2] = readVarintBig(buf, pos);
    pos = pos2;

    const rowid = toSigned64(rowidUnsigned);

    const U = pageSize - reservedBytes;
    let localSize: number;
    if (payloadSize <= U - 35) {
        localSize = payloadSize;
    } else {
        const X = Math.floor((U - 12) * 32 / 255) - 23;
        const M = Math.floor((U - 12) * 64 / 255) - 23;
        const range = M - X + 1;
        const K = ((payloadSize - M) % range + range) % range;
        if (K < X) {
            localSize = K;
        } else {
            localSize = M + K - X;
        }
    }

    let fullPayload: Buffer;
    if (payloadSize > localSize) {
        const localPayload = Buffer.from(buf.subarray(pos, pos + localSize));
        const overflowPageNum = readU32BE(buf, pos + localSize);
        const overflowData = readOverflowChain(buf, overflowPageNum, pageSize, reservedBytes, payloadSize - localSize);
        fullPayload = Buffer.concat([localPayload, overflowData]);
    } else {
        fullPayload = Buffer.from(buf.subarray(pos, pos + localSize));
    }

    const values = parseRecord(fullPayload);
    return { rowid, values };
}

function walkTableBTree(buf: Buffer, rootPage: number, pageSize: number, reservedBytes: number): RowData[] {
    const rows: RowData[] = [];
    walkPage(buf, rootPage, pageSize, reservedBytes, rows);
    return rows;
}

function walkPage(buf: Buffer, pageNum: number, pageSize: number, reservedBytes: number, rows: RowData[]) {
    const pageStart = (pageNum - 1) * pageSize;
    const headerOffset = pageNum === 1 ? 100 : 0;
    const pageType = buf[pageStart + headerOffset];

    if (pageType === 13) {
        const numCells = readU16BE(buf, pageStart + headerOffset + 3);
        const cellPtrStart = pageStart + headerOffset + 8;

        for (let i = 0; i < numCells; i++) {
            const cellOffset = readU16BE(buf, cellPtrStart + i * 2);
            const row = parseLeafCell(buf, pageStart + cellOffset, pageSize, reservedBytes);
            rows.push(row);
        }
    } else if (pageType === 5) {
        const numCells = readU16BE(buf, pageStart + headerOffset + 3);
        const cellPtrStart = pageStart + headerOffset + 12;

        for (let i = 0; i < numCells; i++) {
            const cellOffset = readU16BE(buf, cellPtrStart + i * 2);
            const childPage = readU32BE(buf, pageStart + cellOffset);
            walkPage(buf, childPage, pageSize, reservedBytes, rows);
        }

        const rightMost = readU32BE(buf, pageStart + headerOffset + 8);
        walkPage(buf, rightMost, pageSize, reservedBytes, rows);
    }
}

function parseColumns(sql: string): ColumnDef[] {
    let openPos = -1;
    let inQuote = false;
    for (let i = 0; i < sql.length; i++) {
        if (sql[i] === '"') {
            inQuote = !inQuote;
        } else if (sql[i] === '(' && !inQuote) {
            openPos = i;
            break;
        }
    }
    if (openPos === -1) return [];

    let closePos = -1;
    let depth = 0;
    inQuote = false;
    for (let i = openPos; i < sql.length; i++) {
        if (sql[i] === '"') {
            inQuote = !inQuote;
        } else if (!inQuote) {
            if (sql[i] === '(') depth++;
            else if (sql[i] === ')') {
                depth--;
                if (depth === 0) { closePos = i; break; }
            }
        }
    }
    if (closePos === -1) return [];

    const defs = sql.substring(openPos + 1, closePos);

    const parts: string[] = [];
    depth = 0;
    inQuote = false;
    let current = '';
    for (let j = 0; j < defs.length; j++) {
        if (defs[j] === '"') {
            inQuote = !inQuote;
            current += defs[j];
        } else if (!inQuote) {
            if (defs[j] === '(') { depth++; current += defs[j]; }
            else if (defs[j] === ')') { depth--; current += defs[j]; }
            else if (defs[j] === ',' && depth === 0) {
                parts.push(current);
                current = '';
            } else {
                current += defs[j];
            }
        } else {
            current += defs[j];
        }
    }
    if (current.trim().length > 0) parts.push(current);

    const columns: ColumnDef[] = [];
    for (let part of parts) {
        part = part.trim();
        if (part.length === 0) continue;

        let colName: string;
        let rest: string;
        if (part[0] === '"') {
            const end = part.indexOf('"', 1);
            colName = part.substring(1, end);
            rest = part.substring(end + 1);
        } else {
            let j = 0;
            while (j < part.length && /[a-zA-Z0-9_]/.test(part[j])) j++;
            colName = part.substring(0, j);
            rest = part.substring(j);
        }

        const restTrimmed = rest.trim();
        let typeWord = '';
        if (restTrimmed.length > 0 && /[a-zA-Z_]/.test(restTrimmed[0])) {
            let j = 0;
            while (j < restTrimmed.length && /[a-zA-Z0-9_]/.test(restTrimmed[j])) j++;
            typeWord = restTrimmed.substring(0, j);
        }

        let typeFollowedByParen = false;
        if (typeWord.length > 0) {
            const afterType = restTrimmed.substring(typeWord.length);
            const afterTypeTrimmed = afterType.trimStart();
            if (afterTypeTrimmed.length > 0 && afterTypeTrimmed[0] === '(') {
                typeFollowedByParen = true;
            }
        }

        const isRowidAlias = typeWord.toUpperCase() === 'INTEGER' &&
                             !typeFollowedByParen &&
                             /\bPRIMARY\s+KEY\b/i.test(rest);

        columns.push({ name: colName, isRowidAlias });
    }

    return columns;
}

function main() {
    const dir = process.argv[2];
    if (!dir) {
        process.stderr.write("Usage: main.ts <directory>\n");
        process.exit(1);
    }

    const filePath = path.join(dir, 'db.sqlite');
    const fileBuf = fs.readFileSync(filePath);

    let pageSize = readU16BE(fileBuf, 16);
    if (pageSize === 1) pageSize = 65536;
    const reservedBytes = fileBuf[20];

    const schemaRows = walkTableBTree(fileBuf, 1, pageSize, reservedBytes);

    const tables: TableInfo[] = [];
    for (const row of schemaRows) {
        if (row.values.length < 5) continue;
        const typeVal = row.values[0];
        const nameVal = row.values[1];
        const rootPageVal = row.values[3];
        const sqlVal = row.values[4];

        if (typeVal.type !== 'text') continue;
        const typeStr = Buffer.from(typeVal.bytes).toString('utf-8');
        if (typeStr !== 'table') continue;

        if (nameVal.type !== 'text') continue;
        const name = Buffer.from(nameVal.bytes).toString('utf-8');
        if (name.startsWith('sqlite_')) continue;

        if (rootPageVal.type !== 'integer') continue;
        const rootPage = Number(rootPageVal.value);

        if (sqlVal.type !== 'text') continue;
        const sql = Buffer.from(sqlVal.bytes).toString('utf-8');

        const columns = parseColumns(sql);
        tables.push({ name, rootPage, columns });
    }

    tables.sort((a, b) => {
        return Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8'));
    });

    const outputLines: string[] = [];
    for (let t = 0; t < tables.length; t++) {
        if (t > 0) outputLines.push('');
        const table = tables[t];
        const rows = walkTableBTree(fileBuf, table.rootPage, pageSize, reservedBytes);

        outputLines.push(`TABLE ${table.name} rows=${rows.length}`);
        outputLines.push(`COLUMNS ${table.columns.map(c => c.name).join(', ')}`);

        for (const row of rows) {
            const vals: string[] = [];
            for (let c = 0; c < table.columns.length; c++) {
                const col = table.columns[c];
                if (col.isRowidAlias) {
                    vals.push(row.rowid.toString());
                } else if (c < row.values.length) {
                    vals.push(formatValue(row.values[c]));
                } else {
                    vals.push('NULL');
                }
            }
            outputLines.push(`${row.rowid}: ${vals.join(', ')}`);
        }
    }

    process.stdout.write(outputLines.join('\n') + '\n');
}

main();

import Foundation

// MARK: - Utility Functions

func readVarint(_ data: [UInt8], _ offset: Int) -> (value: UInt64, size: Int) {
    let b0 = data[offset]
    if b0 < 241 {
        return (UInt64(b0), 1)
    }
    if b0 < 249 {
        return (UInt64(b0 - 241) * 256 + UInt64(data[offset + 1]), 2)
    }
    if b0 == 249 {
        let v = UInt64(data[offset+1]) * 65536 + UInt64(data[offset+2]) * 256 + UInt64(data[offset+3])
        return (v + 2288, 4)
    }
    if b0 == 250 {
        var v: UInt64 = 0
        for i in 1...4 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 5)
    }
    if b0 == 251 {
        var v: UInt64 = 0
        for i in 1...5 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 6)
    }
    if b0 == 252 {
        var v: UInt64 = 0
        for i in 1...6 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 7)
    }
    if b0 == 253 {
        var v: UInt64 = 0
        for i in 1...7 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 8)
    }
    var v: UInt64 = 0
    for i in 1...8 { v = v * 256 + UInt64(data[offset + i]) }
    return (v, 9)
}

func readBE16(_ data: [UInt8], _ off: Int) -> Int {
    return Int(data[off]) * 256 + Int(data[off + 1])
}

func readBE32(_ data: [UInt8], _ off: Int) -> Int {
    return Int(data[off]) * 16777216 + Int(data[off+1]) * 65536 + Int(data[off+2]) * 256 + Int(data[off+3])
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

// MARK: - Value Types

enum Value {
    case null
    case integer(Int64)
    case real(Double)
    case text([UInt8])
    case blob([UInt8])
}

struct Row {
    let rowid: Int64
    let values: [Value]
}

// MARK: - Main Program

let args = CommandLine.arguments
guard args.count >= 2 else {
    FileHandle.standardError.write("Usage: main <directory>\n".data(using: .utf8)!)
    exit(1)
}
let dir = args[1]
let filePath = "\(dir)/db.sqlite"
let fileData = try! Data(contentsOf: URL(fileURLWithPath: filePath))
let fileBytes = [UInt8](fileData)

// Parse file header
let pageSize = readBE16(fileBytes, 16)
let reservedBytes = Int(fileBytes[20])
let usableSize = pageSize - reservedBytes

func readPage(_ pageNum: Int) -> [UInt8] {
    let start = (pageNum - 1) * pageSize
    return Array(fileBytes[start..<(start + pageSize)])
}

func btreeHeaderOffset(_ pageNum: Int) -> Int {
    return pageNum == 1 ? 100 : 0
}

func payloadLocalSize(_ payloadSize: Int) -> Int {
    if payloadSize <= usableSize - 35 {
        return payloadSize
    }
    let x = usableSize - 4
    let y = x * 32 / 255 - 23
    let diff = payloadSize - y
    let mod = ((diff % x) + x) % x
    var nLocal = y + mod
    if nLocal > x {
        nLocal = y
    }
    return nLocal
}

func readCellFromLeafTable(_ page: [UInt8], _ cellOffset: Int) -> (rowid: Int64, payload: [UInt8]) {
    var offset = cellOffset
    let (payloadSize, psSize) = readVarint(page, offset)
    offset += psSize
    let (rowidRaw, ridSize) = readVarint(page, offset)
    offset += ridSize

    let ps = Int(payloadSize)
    let localSize = payloadLocalSize(ps)

    if ps <= localSize {
        let payload = Array(page[offset..<(offset + ps)])
        return (Int64(bitPattern: rowidRaw), payload)
    } else {
        let localPayload = Array(page[offset..<(offset + localSize)])
        offset += localSize
        let overflowPageNum = readBE32(page, offset)

        var result = localPayload
        var pageNum = overflowPageNum
        var remaining = ps - localSize

        while remaining > 0 && pageNum != 0 {
            let opage = readPage(pageNum)
            let nextPage = readBE32(opage, 0)
            let available = usableSize - 4
            let toRead = min(remaining, available)
            result.append(contentsOf: opage[4..<(4 + toRead)])
            remaining -= toRead
            pageNum = nextPage
        }

        return (Int64(bitPattern: rowidRaw), result)
    }
}

func parseRecord(_ payload: [UInt8]) -> [Value] {
    guard !payload.isEmpty else { return [] }

    var offset = 0
    let (headerSize, hsSize) = readVarint(payload, offset)
    offset += hsSize
    let headerEnd = Int(headerSize)

    let (numCols, ncSize) = readVarint(payload, offset)
    offset += ncSize

    var serialTypes: [UInt64] = []
    for _ in 0..<numCols {
        let (st, stSize) = readVarint(payload, offset)
        serialTypes.append(st)
        offset += stSize
    }

    var values: [Value] = []
    var dataOffset = headerEnd

    for st in serialTypes {
        if st == 0 {
            values.append(.null)
        } else if st == 1 {
            let v = Int8(bitPattern: payload[dataOffset])
            values.append(.integer(Int64(v)))
            dataOffset += 1
        } else if st == 2 {
            let raw = Int32(payload[dataOffset]) << 8 | Int32(payload[dataOffset + 1])
            let v = Int16(bitPattern: UInt16(truncatingIfNeeded: raw))
            values.append(.integer(Int64(v)))
            dataOffset += 2
        } else if st == 3 {
            var raw = Int32(payload[dataOffset]) << 16 | Int32(payload[dataOffset + 1]) << 8 | Int32(payload[dataOffset + 2])
            if raw >= 0x800000 { raw -= 0x1000000 }
            values.append(.integer(Int64(raw)))
            dataOffset += 3
        } else if st == 4 {
            let raw = Int32(bitPattern: UInt32(payload[dataOffset]) << 24 | UInt32(payload[dataOffset+1]) << 16 | UInt32(payload[dataOffset+2]) << 8 | UInt32(payload[dataOffset+3]))
            values.append(.integer(Int64(raw)))
            dataOffset += 4
        } else if st == 5 {
            var raw: Int64 = 0
            for i in 0..<6 { raw = raw << 8 | Int64(payload[dataOffset + i]) }
            if raw >= (1 << 47) { raw -= (1 << 48) }
            values.append(.integer(raw))
            dataOffset += 6
        } else if st == 6 {
            var raw: UInt64 = 0
            for i in 0..<8 { raw = raw << 8 | UInt64(payload[dataOffset + i]) }
            values.append(.integer(Int64(bitPattern: raw)))
            dataOffset += 8
        } else if st == 7 {
            var raw: UInt64 = 0
            for i in 0..<8 { raw = raw << 8 | UInt64(payload[dataOffset + i]) }
            let v = Double(bitPattern: raw)
            values.append(.real(v))
            dataOffset += 8
        } else if st == 8 {
            values.append(.integer(0))
        } else if st == 9 {
            values.append(.integer(1))
        } else if st >= 12 {
            let length = Int((st - 12) / 2)
            let isBlob = (st % 2) == 0
            let bytes = Array(payload[dataOffset..<(dataOffset + length)])
            if isBlob {
                values.append(.blob(bytes))
            } else {
                values.append(.text(bytes))
            }
            dataOffset += length
        } else {
            values.append(.null)
        }
    }

    return values
}

func walkBTree(_ pageNum: Int) -> [Row] {
    guard pageNum > 0 else { return [] }
    let page = readPage(pageNum)
    let headerOff = btreeHeaderOffset(pageNum)
    let pageType = page[headerOff]

    let numCells = readBE16(page, headerOff + 3)
    let cellPointerStart: Int
    if pageType == 2 || pageType == 5 {
        cellPointerStart = headerOff + 12
    } else {
        cellPointerStart = headerOff + 8
    }

    var rows: [Row] = []

    if pageType == 13 {
        // Leaf table page
        for i in 0..<numCells {
            let cellOffset = readBE16(page, cellPointerStart + i * 2)
            let (rowid, payload) = readCellFromLeafTable(page, cellOffset)
            let values = parseRecord(payload)
            rows.append(Row(rowid: rowid, values: values))
        }
    } else if pageType == 2 {
        // Interior table page
        for i in 0..<numCells {
            let cellOffset = readBE16(page, cellPointerStart + i * 2)
            let childPage = readBE32(page, cellOffset)
            rows.append(contentsOf: walkBTree(childPage))
        }
        let rightPage = readBE32(page, headerOff + 8)
        rows.append(contentsOf: walkBTree(rightPage))
    }

    return rows
}

// MARK: - CREATE TABLE Parsing

func parseCreateTableColumns(_ sql: String) -> [(name: String, isRowidAlias: Bool)] {
    let sqlBytes = Array(sql.utf8)

    // Find first '(' not inside double quotes
    var inQuote = false
    var openParen = -1
    var i = 0
    while i < sqlBytes.count {
        if sqlBytes[i] == 0x22 { inQuote.toggle() }
        else if sqlBytes[i] == 0x28 && !inQuote { openParen = i; break }
        i += 1
    }
    guard openParen >= 0 else { return [] }

    // Find matching ')'
    var depth = 0
    var closeParen = -1
    inQuote = false
    i = openParen
    while i < sqlBytes.count {
        if sqlBytes[i] == 0x22 { inQuote.toggle() }
        else if !inQuote {
            if sqlBytes[i] == 0x28 { depth += 1 }
            else if sqlBytes[i] == 0x29 {
                depth -= 1
                if depth == 0 { closeParen = i; break }
            }
        }
        i += 1
    }
    guard closeParen >= 0 else { return [] }

    // Extract definitions
    let defsStr = String(bytes: sqlBytes[(openParen+1)..<closeParen], encoding: .utf8) ?? ""

    // Split by commas at depth 0
    var defs: [String] = []
    var current = ""
    depth = 0
    inQuote = false
    for ch in defsStr {
        if ch == "\"" { inQuote.toggle(); current.append(ch) }
        else if !inQuote {
            if ch == "(" { depth += 1; current.append(ch) }
            else if ch == ")" { depth -= 1; current.append(ch) }
            else if ch == "," && depth == 0 {
                defs.append(current)
                current = ""
            } else {
                current.append(ch)
            }
        } else {
            current.append(ch)
        }
    }
    if !current.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        defs.append(current)
    }

    var columns: [(name: String, isRowidAlias: Bool)] = []

    for def in defs {
        let trimmed = def.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { continue }

        var colName: String
        var rest: String

        if trimmed.hasPrefix("\"") {
            let afterOpen = trimmed.index(after: trimmed.startIndex)
            if let closeIdx = trimmed[afterOpen...].firstIndex(of: "\"") {
                colName = String(trimmed[afterOpen..<closeIdx])
                rest = String(trimmed[trimmed.index(after: closeIdx)...])
            } else {
                colName = String(trimmed[afterOpen...])
                rest = ""
            }
        } else {
            var idx = trimmed.startIndex
            while idx < trimmed.endIndex && !trimmed[idx].isWhitespace && trimmed[idx] != "(" && trimmed[idx] != "," {
                idx = trimmed.index(after: idx)
            }
            colName = String(trimmed[trimmed.startIndex..<idx])
            rest = String(trimmed[idx...])
        }

        let restTrimmed = rest.trimmingCharacters(in: .whitespacesAndNewlines)
        var isRowidAlias = false

        if !restTrimmed.isEmpty {
            var typeEnd = restTrimmed.startIndex
            while typeEnd < restTrimmed.endIndex && !restTrimmed[typeEnd].isWhitespace && restTrimmed[typeEnd] != "(" && restTrimmed[typeEnd] != "," {
                typeEnd = restTrimmed.index(after: typeEnd)
            }
            let typeName = String(restTrimmed[restTrimmed.startIndex..<typeEnd])

            if typeName.uppercased() == "INTEGER" {
                let afterType = restTrimmed[typeEnd...]
                let afterTypeTrimmed = afterType.trimmingCharacters(in: .whitespacesAndNewlines)
                if !afterTypeTrimmed.hasPrefix("(") {
                    let normalized = def.split(whereSeparator: { $0.isWhitespace }).joined(separator: " ").uppercased()
                    isRowidAlias = normalized.contains("PRIMARY KEY")
                }
            }
        }

        columns.append((name: colName, isRowidAlias: isRowidAlias))
    }

    return columns
}

// MARK: - Output Formatting

func formatReal(_ d: Double) -> String {
    if d == 0 { return "0.0" }
    let negative = d < 0
    let abs_d = abs(d)
    var s = String(format: "%.8f", abs_d)
    if let dotPos = s.firstIndex(of: ".") {
        let afterDot = s.index(after: dotPos)
        var end = s.endIndex
        while end > afterDot && s[s.index(before: end)] == "0" {
            end = s.index(before: end)
        }
        if end == afterDot {
            end = s.index(after: afterDot)
        }
        s = String(s[..<end])
    }
    return (negative ? "-" : "") + s
}

func formatText(_ bytes: [UInt8]) -> String {
    if bytes.count > 100 {
        let crc = crc32(bytes)
        return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
    }
    var result = [UInt8]()
    result.append(0x22) // "
    for b in bytes {
        switch b {
        case 0x5C: result.append(contentsOf: [0x5C, 0x5C])
        case 0x22: result.append(contentsOf: [0x5C, 0x22])
        case 0x0A: result.append(contentsOf: [0x5C, 0x6E])
        case 0x0D: result.append(contentsOf: [0x5C, 0x72])
        case 0x09: result.append(contentsOf: [0x5C, 0x74])
        case 0x7F: result.append(contentsOf: Array("\\x7F".utf8))
        default:
            if b < 0x20 {
                result.append(contentsOf: Array(String(format: "\\x%02X", b).utf8))
            } else {
                result.append(b)
            }
        }
    }
    result.append(0x22) // "
    return String(bytes: result, encoding: .utf8) ?? ""
}

func formatBlob(_ bytes: [UInt8]) -> String {
    if bytes.count > 100 {
        let crc = crc32(bytes)
        return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
    }
    var result = "X'"
    for b in bytes {
        result += String(format: "%02X", b)
    }
    result += "'"
    return result
}

func formatValue(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .integer(let i): return "\(i)"
    case .real(let d): return formatReal(d)
    case .text(let bytes): return formatText(bytes)
    case .blob(let bytes): return formatBlob(bytes)
    }
}

// MARK: - Read Schema and Process Tables

let schemaRows = walkBTree(1)

struct TableInfo {
    let name: String
    let rootPage: Int
    let sql: String
}

var tables: [TableInfo] = []

for row in schemaRows {
    guard row.values.count >= 5 else { continue }

    guard case .text(let typeBytes) = row.values[0],
          String(bytes: typeBytes, encoding: .utf8) == "table" else { continue }

    guard case .text(let nameBytes) = row.values[1],
          let nameStr = String(bytes: nameBytes, encoding: .utf8),
          !nameStr.hasPrefix("sqlite_") else { continue }

    guard case .integer(let rp) = row.values[3] else { continue }

    guard case .text(let sqlBytes) = row.values[4],
          let sqlStr = String(bytes: sqlBytes, encoding: .utf8) else { continue }

    tables.append(TableInfo(name: nameStr, rootPage: Int(rp), sql: sqlStr))
}

// Sort by name in ascending byte-wise order
tables.sort { a, b in
    let aBytes = Array(a.name.utf8)
    let bBytes = Array(b.name.utf8)
    return aBytes.lexicographicallyPrecedes(bBytes)
}

// MARK: - Output

var output = ""
var firstTable = true

for table in tables {
    if !firstTable {
        output += "\n"
    }
    firstTable = false

    let columns = parseCreateTableColumns(table.sql)
    let rows = walkBTree(table.rootPage)

    output += "TABLE \(table.name) rows=\(rows.count)\n"

    let colNames = columns.map { $0.name }
    output += "COLUMNS \(colNames.joined(separator: ", "))\n"

    for row in rows {
        var line = "\(row.rowid): "
        var parts: [String] = []
        for i in 0..<columns.count {
            if columns[i].isRowidAlias {
                parts.append("\(row.rowid)")
            } else if i < row.values.count {
                parts.append(formatValue(row.values[i]))
            } else {
                parts.append("NULL")
            }
        }
        line += parts.joined(separator: ", ")
        output += line + "\n"
    }
}

print(output, terminator: "")

import Foundation

// MARK: - Utility Functions

func readVarint(_ data: [UInt8], _ offset: Int) -> (value: UInt64, size: Int) {
    let b0 = data[offset]
    if b0 < 241 {
        return (UInt64(b0), 1)
    }
    if b0 < 249 {
        return (UInt64(b0 - 241) * 256 + UInt64(data[offset + 1]), 2)
    }
    if b0 == 249 {
        let v = UInt64(data[offset+1]) * 65536 + UInt64(data[offset+2]) * 256 + UInt64(data[offset+3])
        return (v + 2288, 4)
    }
    if b0 == 250 {
        var v: UInt64 = 0
        for i in 1...4 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 5)
    }
    if b0 == 251 {
        var v: UInt64 = 0
        for i in 1...5 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 6)
    }
    if b0 == 252 {
        var v: UInt64 = 0
        for i in 1...6 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 7)
    }
    if b0 == 253 {
        var v: UInt64 = 0
        for i in 1...7 { v = v * 256 + UInt64(data[offset + i]) }
        return (v, 8)
    }
    var v: UInt64 = 0
    for i in 1...8 { v = v * 256 + UInt64(data[offset + i]) }
    return (v, 9)
}

func readBE16(_ data: [UInt8], _ off: Int) -> Int {
    return Int(data[off]) * 256 + Int(data[off + 1])
}

func readBE32(_ data: [UInt8], _ off: Int) -> Int {
    return Int(data[off]) * 16777216 + Int(data[off+1]) * 65536 + Int(data[off+2]) * 256 + Int(data[off+3])
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

// MARK: - Value Types

enum Value {
    case null
    case integer(Int64)
    case real(Double)
    case text([UInt8])
    case blob([UInt8])
}

struct Row {
    let rowid: Int64
    let values: [Value]
}

// MARK: - Main Program

let args = CommandLine.arguments
guard args.count >= 2 else {
    FileHandle.standardError.write("Usage: main <directory>\n".data(using: .utf8)!)
    exit(1)
}
let dir = args[1]
let filePath = "\(dir)/db.sqlite"
let fileData = try! Data(contentsOf: URL(fileURLWithPath: filePath))
let fileBytes = [UInt8](fileData)

// Parse file header
var pageSize = readBE16(fileBytes, 16)
if pageSize == 1 { pageSize = 65536 }
let reservedBytes = Int(fileBytes[20])
let usableSize = pageSize - reservedBytes

func readPage(_ pageNum: Int) -> [UInt8] {
    let start = (pageNum - 1) * pageSize
    return Array(fileBytes[start..<(start + pageSize)])
}

func btreeHeaderOffset(_ pageNum: Int) -> Int {
    return pageNum == 1 ? 100 : 0
}

func payloadLocalSize(_ payloadSize: Int) -> Int {
    let U = usableSize
    let X = U - 35
    if payloadSize <= X {
        return payloadSize
    }
    let M = ((U - 12) * 32 / 255) - 23
    let K = M + ((payloadSize - M) % (U - 4))
    if K <= X {
        return K
    } else {
        return M
    }
}

func readCellFromLeafTable(_ page: [UInt8], _ cellOffset: Int) -> (rowid: Int64, payload: [UInt8]) {
    var offset = cellOffset
    let (payloadSize, psSize) = readVarint(page, offset)
    offset += psSize
    let (rowidRaw, ridSize) = readVarint(page, offset)
    offset += ridSize

    let ps = Int(payloadSize)
    let localSize = payloadLocalSize(ps)

    if ps <= localSize {
        let payload = Array(page[offset..<(offset + ps)])
        return (Int64(bitPattern: rowidRaw), payload)
    } else {
        let localPayload = Array(page[offset..<(offset + localSize)])
        offset += localSize
        let overflowPageNum = readBE32(page, offset)

        var result = localPayload
        var pageNum = overflowPageNum
        var remaining = ps - localSize

        while remaining > 0 && pageNum != 0 {
            let opage = readPage(pageNum)
            let nextPage = readBE32(opage, 0)
            let available = usableSize - 4
            let toRead = min(remaining, available)
            result.append(contentsOf: opage[4..<(4 + toRead)])
            remaining -= toRead
            pageNum = nextPage
        }

        return (Int64(bitPattern: rowidRaw), result)
    }
}

func parseRecord(_ payload: [UInt8]) -> [Value] {
    guard !payload.isEmpty else { return [] }

    var offset = 0
    let (headerSize, hsSize) = readVarint(payload, offset)
    offset += hsSize
    let headerEnd = Int(headerSize)

    let (numCols, ncSize) = readVarint(payload, offset)
    offset += ncSize

    var serialTypes: [UInt64] = []
    for _ in 0..<numCols {
        if offset >= payload.count { break }
        let (st, stSize) = readVarint(payload, offset)
        serialTypes.append(st)
        offset += stSize
    }

    var values: [Value] = []
    var dataOffset = headerEnd

    for st in serialTypes {
        if st == 0 {
            values.append(.null)
        } else if st == 1 {
            let v = Int8(bitPattern: payload[dataOffset])
            values.append(.integer(Int64(v)))
            dataOffset += 1
        } else if st == 2 {
            let raw = Int16(bitPattern: UInt16(payload[dataOffset]) << 8 | UInt16(payload[dataOffset + 1]))
            values.append(.integer(Int64(raw)))
            dataOffset += 2
        } else if st == 3 {
            var raw = Int32(payload[dataOffset]) << 16 | Int32(payload[dataOffset + 1]) << 8 | Int32(payload[dataOffset + 2])
            if raw >= 0x800000 { raw -= 0x1000000 }
            values.append(.integer(Int64(raw)))
            dataOffset += 3
        } else if st == 4 {
            let raw = Int32(bitPattern: UInt32(payload[dataOffset]) << 24 | UInt32(payload[dataOffset+1]) << 16 | UInt32(payload[dataOffset+2]) << 8 | UInt32(payload[dataOffset+3]))
            values.append(.integer(Int64(raw)))
            dataOffset += 4
        } else if st == 5 {
            var raw: Int64 = 0
            for i in 0..<6 { raw = raw << 8 | Int64(payload[dataOffset + i]) }
            if raw >= (1 << 47) { raw -= (1 << 48) }
            values.append(.integer(raw))
            dataOffset += 6
        } else if st == 6 {
            var raw: UInt64 = 0
            for i in 0..<8 { raw = raw << 8 | UInt64(payload[dataOffset + i]) }
            values.append(.integer(Int64(bitPattern: raw)))
            dataOffset += 8
        } else if st == 7 {
            var raw: UInt64 = 0
            for i in 0..<8 { raw = raw << 8 | UInt64(payload[dataOffset + i]) }
            let v = Double(bitPattern: raw)
            values.append(.real(v))
            dataOffset += 8
        } else if st == 8 {
            values.append(.integer(0))
        } else if st == 9 {
            values.append(.integer(1))
        } else if st >= 12 {
            let isBlob = (st % 2) == 0
            let length: Int
            if isBlob {
                length = Int((st - 12) / 2)
            } else {
                length = Int((st - 13) / 2 + 1)
            }
            let bytes = Array(payload[dataOffset..<(dataOffset + length)])
            if isBlob {
                values.append(.blob(bytes))
            } else {
                values.append(.text(bytes))
            }
            dataOffset += length
        } else {
            values.append(.null)
        }
    }

    return values
}

func walkBTree(_ pageNum: Int) -> [Row] {
    guard pageNum > 0 else { return [] }
    let page = readPage(pageNum)
    let headerOff = btreeHeaderOffset(pageNum)
    let pageType = page[headerOff]

    let numCells = readBE16(page, headerOff + 3)
    let cellPointerStart: Int
    if pageType == 2 || pageType == 5 {
        cellPointerStart = headerOff + 12
    } else {
        cellPointerStart = headerOff + 8
    }

    var rows: [Row] = []

    if pageType == 13 {
        // Leaf table page
        for i in 0..<numCells {
            let cellOffset = readBE16(page, cellPointerStart + i * 2)
            let (rowid, payload) = readCellFromLeafTable(page, cellOffset)
            let values = parseRecord(payload)
            rows.append(Row(rowid: rowid, values: values))
        }
    } else if pageType == 2 {
        // Interior table page
        for i in 0..<numCells {
            let cellOffset = readBE16(page, cellPointerStart + i * 2)
            let childPage = readBE32(page, cellOffset)
            rows.append(contentsOf: walkBTree(childPage))
        }
        let rightPage = readBE32(page, headerOff + 8)
        rows.append(contentsOf: walkBTree(rightPage))
    }

    return rows
}

// MARK: - CREATE TABLE Parsing

func parseCreateTableColumns(_ sql: String) -> [(name: String, isRowidAlias: Bool)] {
    let sqlBytes = Array(sql.utf8)

    // Find first '(' not inside double quotes
    var inQuote = false
    var openParen = -1
    var i = 0
    while i < sqlBytes.count {
        if sqlBytes[i] == 0x22 { inQuote.toggle() }
        else if sqlBytes[i] == 0x28 && !inQuote { openParen = i; break }
        i += 1
    }
    guard openParen >= 0 else { return [] }

    // Find matching ')'
    var depth = 0
    var closeParen = -1
    inQuote = false
    i = openParen
    while i < sqlBytes.count {
        if sqlBytes[i] == 0x22 { inQuote.toggle() }
        else if !inQuote {
            if sqlBytes[i] == 0x28 { depth += 1 }
            else if sqlBytes[i] == 0x29 {
                depth -= 1
                if depth == 0 { closeParen = i; break }
            }
        }
        i += 1
    }
    guard closeParen >= 0 else { return [] }

    // Extract definitions
    let defsStr = String(bytes: sqlBytes[(openParen+1)..<closeParen], encoding: .utf8) ?? ""

    // Split by commas at depth 0
    var defs: [String] = []
    var current = ""
    depth = 0
    inQuote = false
    for ch in defsStr {
        if ch == "\"" { inQuote.toggle(); current.append(ch) }
        else if !inQuote {
            if ch == "(" { depth += 1; current.append(ch) }
            else if ch == ")" { depth -= 1; current.append(ch) }
            else if ch == "," && depth == 0 {
                defs.append(current)
                current = ""
            } else {
                current.append(ch)
            }
        } else {
            current.append(ch)
        }
    }
    if !current.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        defs.append(current)
    }

    var columns: [(name: String, isRowidAlias: Bool)] = []

    for def in defs {
        let trimmed = def.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { continue }

        var colName: String
        var rest: String

        if trimmed.hasPrefix("\"") {
            let afterOpen = trimmed.index(after: trimmed.startIndex)
            if let closeIdx = trimmed[afterOpen...].firstIndex(of: "\"") {
                colName = String(trimmed[afterOpen..<closeIdx])
                rest = String(trimmed[trimmed.index(after: closeIdx)...])
            } else {
                colName = String(trimmed[afterOpen...])
                rest = ""
            }
        } else {
            var idx = trimmed.startIndex
            while idx < trimmed.endIndex && !trimmed[idx].isWhitespace && trimmed[idx] != "(" && trimmed[idx] != "," {
                idx = trimmed.index(after: idx)
            }
            colName = String(trimmed[trimmed.startIndex..<idx])
            rest = String(trimmed[idx...])
        }

        let restTrimmed = rest.trimmingCharacters(in: .whitespacesAndNewlines)
        var isRowidAlias = false

        if !restTrimmed.isEmpty {
            var typeEnd = restTrimmed.startIndex
            while typeEnd < restTrimmed.endIndex && !restTrimmed[typeEnd].isWhitespace && restTrimmed[typeEnd] != "(" && restTrimmed[typeEnd] != "," {
                typeEnd = restTrimmed.index(after: typeEnd)
            }
            let typeName = String(restTrimmed[restTrimmed.startIndex..<typeEnd])

            if typeName.uppercased() == "INTEGER" {
                let afterType = restTrimmed[typeEnd...]
                let afterTypeTrimmed = afterType.trimmingCharacters(in: .whitespacesAndNewlines)
                if !afterTypeTrimmed.hasPrefix("(") {
                    let normalized = def.split(whereSeparator: { $0.isWhitespace }).joined(separator: " ").uppercased()
                    isRowidAlias = normalized.contains("PRIMARY KEY")
                }
            }
        }

        columns.append((name: colName, isRowidAlias: isRowidAlias))
    }

    return columns
}

// MARK: - Output Formatting

func formatReal(_ d: Double) -> String {
    if d == 0 { return "0.0" }
    let negative = d < 0
    let abs_d = abs(d)
    var s = String(format: "%.8f", abs_d)
    if let dotPos = s.firstIndex(of: ".") {
        let afterDot = s.index(after: dotPos)
        var end = s.endIndex
        while end > afterDot && s[s.index(before: end)] == "0" {
            end = s.index(before: end)
        }
        if end == afterDot {
            end = s.index(after: afterDot)
        }
        s = String(s[..<end])
    }
    return (negative ? "-" : "") + s
}

func formatText(_ bytes: [UInt8]) -> String {
    if bytes.count > 100 {
        let crc = crc32(bytes)
        return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
    }
    var result = [UInt8]()
    result.append(0x22) // "
    for b in bytes {
        switch b {
        case 0x5C: result.append(contentsOf: [0x5C, 0x5C])
        case 0x22: result.append(contentsOf: [0x5C, 0x22])
        case 0x0A: result.append(contentsOf: [0x5C, 0x6E])
        case 0x0D: result.append(contentsOf: [0x5C, 0x72])
        case 0x09: result.append(contentsOf: [0x5C, 0x74])
        case 0x7F: result.append(contentsOf: Array("\\x7F".utf8))
        default:
            if b < 0x20 {
                result.append(contentsOf: Array(String(format: "\\x%02X", b).utf8))
            } else {
                result.append(b)
            }
        }
    }
    result.append(0x22) // "
    return String(bytes: result, encoding: .utf8) ?? ""
}

func formatBlob(_ bytes: [UInt8]) -> String {
    if bytes.count > 100 {
        let crc = crc32(bytes)
        return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
    }
    var result = "X'"
    for b in bytes {
        result += String(format: "%02X", b)
    }
    result += "'"
    return result
}

func formatValue(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .integer(let i): return "\(i)"
    case .real(let d): return formatReal(d)
    case .text(let bytes): return formatText(bytes)
    case .blob(let bytes): return formatBlob(bytes)
    }
}

// MARK: - Read Schema and Process Tables

let schemaRows = walkBTree(1)

struct TableInfo {
    let name: String
    let rootPage: Int
    let sql: String
}

var tables: [TableInfo] = []

for row in schemaRows {
    guard row.values.count >= 5 else { continue }

    guard case .text(let typeBytes) = row.values[0],
          String(bytes: typeBytes, encoding: .utf8) == "table" else { continue }

    guard case .text(let nameBytes) = row.values[1],
          let nameStr = String(bytes: nameBytes, encoding: .utf8),
          !nameStr.hasPrefix("sqlite_") else { continue }

    guard case .integer(let rp) = row.values[3] else { continue }

    guard case .text(let sqlBytes) = row.values[4],
          let sqlStr = String(bytes: sqlBytes, encoding: .utf8) else { continue }

    tables.append(TableInfo(name: nameStr, rootPage: Int(rp), sql: sqlStr))
}

// Sort by name in ascending byte-wise order
tables.sort { a, b in
    let aBytes = Array(a.name.utf8)
    let bBytes = Array(b.name.utf8)
    return aBytes.lexicographicallyPrecedes(bBytes)
}

// MARK: - Output

var output = ""
var firstTable = true

for table in tables {
    if !firstTable {
        output += "\n"
    }
    firstTable = false

    let columns = parseCreateTableColumns(table.sql)
    let rows = walkBTree(table.rootPage)

    output += "TABLE \(table.name) rows=\(rows.count)\n"

    let colNames = columns.map { $0.name }
    output += "COLUMNS \(colNames.joined(separator: ", "))\n"

    for row in rows {
        var parts: [String] = []
        for i in 0..<columns.count {
            if columns[i].isRowidAlias {
                parts.append("\(row.rowid)")
            } else if i < row.values.count {
                parts.append(formatValue(row.values[i]))
            } else {
                parts.append("NULL")
            }
        }
        output += "\(row.rowid): \(parts.joined(separator: ", "))\n"
    }
}

print(output, terminator: "")

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

static uint8_t *g_data;
static size_t g_fsize;
static uint16_t g_psz;
static uint8_t g_resv;
static uint16_t g_usz;

static uint16_t be16(const uint8_t *p){ return (uint16_t)(p[0]<<8|p[1]); }
static uint32_t be32(const uint8_t *p){ return (uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3]; }
static int64_t be64(const uint8_t *p){ return (int64_t)((uint64_t)be32(p)<<32|be32(p+4)); }

static int rd_var(const uint8_t *d, size_t off, size_t lim, uint64_t *v){
    *v=0;
    for(int i=0;i<9;i++){
        if(off+i>=lim) return -1;
        uint8_t b=d[off+i];
        if(i<8){*v=(*v<<7)|(b&0x7f);if(!(b&0x80))return i+1;}
        else{*v=(*v<<8)|b;return 9;}
    }
    return -1;
}

static const uint8_t* getpg(uint32_t pg){ return g_data+(size_t)(pg-1)*g_psz; }

static uint32_t crc32_fn(const uint8_t *d, size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++){c^=d[i];for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;}
    return c^0xFFFFFFFF;
}

static int64_t sext(uint64_t v,int bits){
    if(bits>=64)return(int64_t)v;
    return(v&(1ULL<<(bits-1)))?(int64_t)(v|(~0ULL<<bits)):(int64_t)v;
}

typedef enum{VN,VI,VR,VT,VB}VT;
typedef struct{VT t;int64_t i;double d;uint8_t*p;size_t n;}Val;
typedef struct{Val*v;int nc;}Rec;
typedef struct{int64_t rid;Rec r;}Row;

static uint8_t* cell_payload(const uint8_t*pg,size_t co,size_t*sz){
    size_t pos=co;uint64_t ps,rid;
    int n=rd_var(pg,pos,g_usz,&ps);if(n<0){*sz=0;return NULL;}pos+=n;
    n=rd_var(pg,pos,g_usz,&rid);if(n<0){*sz=0;return NULL;}pos+=n;
    size_t X=(size_t)g_usz-35,U;
    if(ps<=X)U=(size_t)ps;
    else{U=(size_t)((g_usz-12)*((ps-12)/(g_usz+31))+12);if(U>X)U=X;}
    uint8_t*buf=malloc(ps?ps:1);if(!buf){perror("malloc");exit(1);}
    size_t rem=ps,tc=U;
    if(pos+tc>g_usz)tc=g_usz-pos;
    memcpy(buf,pg+pos,tc);rem-=tc;pos+=tc;
    if(rem){
        uint32_t ov=be32(pg+pos);
        while(rem&&ov){
            const uint8_t*op=getpg(ov);
            size_t av=(size_t)g_usz-4;tc=rem<av?rem:av;
            memcpy(buf+(ps-rem),op+4,tc);rem-=tc;
            ov=be32(op);
        }
    }
    *sz=ps;return buf;
}

static Rec parse_rec(const uint8_t*p,size_t psz){
    Rec r={NULL,0};if(!psz)return r;
    size_t pos=0;uint64_t hs;
    int n=rd_var(p,pos,psz,&hs);if(n<0)return r;
    size_t hend=(size_t)hs;pos+=n;
    int cnt=0;uint64_t st[4096];
    while(pos<hend){n=rd_var(p,pos,psz,&st[cnt]);if(n<0)break;pos+=n;cnt++;}
    r.nc=cnt;r.v=calloc(cnt,sizeof(Val));
    size_t dp=hend;
    for(int i=0;i<cnt;i++){
        uint64_t s=st[i];
        if(s==0){r.v[i].t=VN;}
        else if(s>=1&&s<=4){int b=(int)s;uint64_t v=0;for(int j=0;j<b;j++)v=v<<8|p[dp+j];r.v[i].t=VI;r.v[i].i=sext(v,b*8);dp+=b;}
        else if(s==5){uint64_t v=0;for(int j=0;j<6;j++)v=v<<8|p[dp+j];r.v[i].t=VI;r.v[i].i=sext(v,48);dp+=6;}
        else if(s==6){r.v[i].t=VI;r.v[i].i=be64(p+dp);dp+=8;}
        else if(s==7){union{uint64_t u;double d;}u;u.u=(uint64_t)be32(p+dp)<<32|be32(p+dp+4);r.v[i].t=VR;r.v[i].d=u.d;dp+=8;}
        else if(s==8){r.v[i].t=VI;r.v[i].i=0;}
        else if(s==9){r.v[i].t=VI;r.v[i].i=1;}
        else if(s>=12&&!(s&1)){size_t l=(size_t)((s-12)/2);r.v[i].t=VB;r.v[i].p=malloc(l?l:1);memcpy(r.v[i].p,p+dp,l);r.v[i].n=l;dp+=l;}
        else if(s>=13&&(s&1)){size_t l=(size_t)((s-13)/2);r.v[i].t=VT;r.v[i].p=malloc(l?l:1);memcpy(r.v[i].p,p+dp,l);r.v[i].n=l;dp+=l;}
    }
    return r;
}

static void walk(uint32_t pn,Row**rows,int*nr,int*cap){
    if(pn==0)return;
    const uint8_t*pg=getpg(pn);
    size_t ho=(pn==1)?100:0;
    uint8_t pt=pg[ho];
    uint16_t nc=be16(pg+ho+3);
    if(pt==13){
        for(int i=0;i<nc;i++){
            size_t co=be16(pg+ho+8+i*2);
            size_t psz;uint8_t*pl=cell_payload(pg,co,&psz);
            size_t pos=co;uint64_t tmp,rid;
            int n=rd_var(pg,pos,g_usz,&tmp);pos+=n;
            n=rd_var(pg,pos,g_usz,&rid);pos+=n;
            if(*nr>=*cap){*cap=*cap?*cap*2:64;*rows=realloc(*rows,*cap*sizeof(Row));}
            (*rows)[*nr].rid=(int64_t)rid;
            (*rows)[*nr].r=parse_rec(pl,psz);
            free(pl);(*nr)++;
        }
    }else if(pt==5){
        for(int i=0;i<nc;i++){
            size_t co=be16(pg+ho+12+i*2);
            walk(be32(pg+co),rows,nr,cap);
        }
        walk(be32(pg+ho+8),rows,nr,cap);
    }
}

typedef struct{char*type;char*name;char*tbl;int64_t rp;char*sql;}SEntry;

static char*val_text(Val*v){
    if(v->t!=VT)return NULL;
    char*s=malloc(v->n+1);memcpy(s,v->p,v->n);s[v->n]='\0';return s;
}

static void read_schema(SEntry**out,int*cnt){
    Row*rows=NULL;int nr=0,cap=0;
    walk(1,&rows,&nr,&cap);
    *out=malloc((nr+1)*sizeof(SEntry));*cnt=0;
    for(int i=0;i<nr;i++){
        if(rows[i].r.nc<5)continue;
        char*type=val_text(&rows[i].r.v[0]);
        char*name=val_text(&rows[i].r.v[1]);
        char*tbl=val_text(&rows[i].r.v[2]);
        int64_t rp=(rows[i].r.v[3].t==VI)?rows[i].r.v[3].i:0;
        char*sql=val_text(&rows[i].r.v[4]);
        if(!type||!name)continue;
        if(strcmp(type,"table")!=0)continue;
        if(strncmp(name,"sqlite_",7)==0)continue;
        (*out)[*cnt].type=type;(*out)[*cnt].name=name;
        (*out)[*cnt].tbl=tbl;(*out)[*cnt].rp=rp;(*out)[*cnt].sql=sql;
        (*cnt)++;
    }
}

static int cmp_se(const void*a,const void*b){
    return strcmp(((SEntry*)a)->name,((SEntry*)b)->name);
}
static int cmp_row(const void*a,const void*b){
    int64_t ra=((Row*)a)->rid,rb=((Row*)b)->rid;
    return ra<rb?-1:ra>rb?1:0;
}

static const char* find_open_paren(const char*sql){
    int inq=0;
    for(const char*p=sql;*p;p++){
        if(*p=='"')inq=!inq;
        else if(*p=='('&&!inq)return p;
    }
    return NULL;
}

static const char* find_close_paren(const char*open){
    int depth=0,inq=0;
    for(const char*p=open;*p;p++){
        if(*p=='"')inq=!inq;
        else if(!inq){
            if(*p=='(')depth++;
            else if(*p==')'){depth--;if(!depth)return p;}
        }
    }
    return NULL;
}

static int parse_cols(const char*sql,char***names,int**aliases){
    const char*op=find_open_paren(sql);
    if(!op){*names=NULL;*aliases=NULL;return 0;}
    const char*cp=find_close_paren(op);
    if(!cp){*names=NULL;*aliases=NULL;return 0;}
    const char*ds=op+1;
    const char*de=cp;
    int maxc=256;
    char**cols=malloc(maxc*sizeof(char*));
    int*al=malloc(maxc*sizeof(int));
    int ncol=0;
    const char*start=ds;
    int depth=0,inq=0;
    for(const char*q=ds;;q++){
        if(q>=de||(*q==','&&depth==0&&!inq)){
            int dlen=(int)(q-start);
            if(dlen>0){
                char*def=malloc(dlen+1);memcpy(def,start,dlen);def[dlen]='\0';
                const char*d=def;
                while(*d==' '||*d=='\t'||*d=='\n'||*d=='\r')d++;
                char*cn;
                if(*d=='"'){
                    d++;const char*s2=d;while(*d&&*d!='"')d++;
                    int l=(int)(d-s2);cn=malloc(l+1);memcpy(cn,s2,l);cn[l]='\0';
                }else{
                    const char*s2=d;
                    while(*d&&*d!=' '&&*d!='\t'&&*d!='\n'&&*d!='\r'&&*d!='('&&*d!=',')d++;
                    int l=(int)(d-s2);cn=malloc(l+1);memcpy(cn,s2,l);cn[l]='\0';
                }
                int alias=0;
                const char*tp=d;
                while(*tp==' '||*tp=='\t'||*tp=='\n'||*tp=='\r')tp++;
                const char*ts=tp;
                while(*tp&&((*tp>='A'&&*tp<='Z')||(*tp>='a'&&*tp<='z')||(*tp>='0'&&*tp<='9')||*tp=='_'))tp++;
                int tl=(int)(tp-ts);
                if(tl==7){
                    int match=1;const char*iw="INTEGER";
                    for(int k=0;k<7;k++){char c=ts[k];if(c>='a'&&c<='z')c-=32;if(c!=iw[k]){match=0;break;}}
                    if(match){
                        const char*after=tp;
                        while(*after==' '||*after=='\t'||*after=='\n'||*after=='\r')after++;
                        if(*after!='('){
                            char*up=malloc(dlen+1);
                            for(int k=0;k<dlen;k++)up[k]=(def[k]>='a'&&def[k]<='z')?def[k]-32:def[k];
                            up[dlen]='\0';
                            char*pp=strstr(up,"PRIMARY");
                            while(pp){
                                pp+=7;
                                while(*pp==' '||*pp=='\t'||*pp=='\n'||*pp=='\r')pp++;
                                if(strncmp(pp,"KEY",3)==0){alias=1;break;}
                                pp=strstr(pp,"PRIMARY");
                            }
                            free(up);
                        }
                    }
                }
                if(ncol>=maxc){maxc*=2;cols=realloc(cols,maxc*sizeof(char*));al=realloc(al,maxc*sizeof(int));}
                cols[ncol]=cn;al[ncol]=alias;ncol++;
                free(def);
            }
            start=q+1;
            if(q>=de)break;
        }
        if(q<de){
            if(*q=='"')inq=!inq;
            else if(!inq){
                if(*q=='(')depth++;
                else if(*q==')')depth--;
            }
        }
    }
    *names=cols;*aliases=al;return ncol;
}

static void print_real(double d){
    char buf[4096];
    snprintf(buf,sizeof(buf),"%.8f",d);
    /* strip trailing zeros after decimal point, keep at least one */
    char*dot=strchr(buf,'.');
    if(dot){
        char*end=buf+strlen(buf)-1;
        while(end>dot+1&&*end=='0')*end--='\0';
    }
    fputs(buf,stdout);
}

static void print_text(const uint8_t*p,size_t n){
    putchar('"');
    for(size_t i=0;i<n;i++){
        uint8_t c=p[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t*p,size_t n){
    printf("X'");
    for(size_t i=0;i<n;i++)printf("%02X",p[i]);
    printf("'");
}

static void print_val(Val*v){
    switch(v->t){
        case VN:printf("NULL");break;
        case VI:printf("%lld",(long long)v->i);break;
        case VR:print_real(v->d);break;
        case VT:
            if(v->n<=100)print_text(v->p,v->n);
            else printf("<TEXT len=%zu crc32=%08x>",v->n,crc32_fn(v->p,v->n));
            break;
        case VB:
            if(v->n<=100)print_blob(v->p,v->n);
            else printf("<BLOB len=%zu crc32=%08x>",v->n,crc32_fn(v->p,v->n));
            break;
    }
}

int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];
    snprintf(path,sizeof(path),"%s/db.sqlite",argv[1]);
    FILE*f=fopen(path,"rb");
    if(!f){perror(path);return 1;}
    fseek(f,0,SEEK_END);g_fsize=(size_t)ftell(f);fseek(f,0,SEEK_SET);
    g_data=malloc(g_fsize);
    if(fread(g_data,1,g_fsize,f)!=g_fsize){perror("read");return 1;}
    fclose(f);

    g_psz=be16(g_data+16);
    if(g_psz==1)g_psz=65536;
    g_resv=g_data[20];
    g_usz=g_psz-g_resv;

    SEntry*se=NULL;int secnt=0;
    read_schema(&se,&secnt);
    qsort(se,secnt,sizeof(SEntry),cmp_se);

    int first=1;
    for(int t=0;t<secnt;t++){
        char**colnames=NULL;int*colalias=NULL;int ncols=0;
        if(se[t].sql)ncols=parse_cols(se[t].sql,&colnames,&colalias);

        Row*rows=NULL;int nr=0,cap=0;
        walk((uint32_t)se[t].rp,&rows,&nr,&cap);
        qsort(rows,nr,sizeof(Row),cmp_row);

        if(!first)putchar('\n');
        first=0;

        printf("TABLE %s rows=%d\n",se[t].name,nr);
        printf("COLUMNS");
        for(int c=0;c<ncols;c++){
            if(c)printf(",");
            printf(" %s",colnames[c]);
        }
        putchar('\n');

        for(int r=0;r<nr;r++){
            printf("%lld:",(long long)rows[r].rid);
            for(int c=0;c<ncols;c++){
                if(c)printf(",");
                printf(" ");
                if(colalias&&colalias[c]){
                    printf("%lld",(long long)rows[r].rid);
                }else if(c<rows[r].r.nc){
                    print_val(&rows[r].r.v[c]);
                }else{
                    printf("NULL");
                }
            }
            putchar('\n');
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

static uint8_t *g_data;
static size_t g_fsize;
static uint32_t g_psz;
static uint8_t g_resv;
static uint16_t g_usz;

static uint16_t be16(const uint8_t *p){ return (uint16_t)(p[0]<<8|p[1]); }
static uint32_t be32(const uint8_t *p){ return (uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3]; }
static int64_t be64(const uint8_t *p){ return (int64_t)((uint64_t)be32(p)<<32|be32(p+4)); }

static int rd_var(const uint8_t *d, size_t off, size_t lim, uint64_t *v){
    *v=0;
    for(int i=0;i<9;i++){
        if(off+i>=lim) return -1;
        uint8_t b=d[off+i];
        if(i<8){*v=(*v<<7)|(b&0x7f);if(!(b&0x80))return i+1;}
        else{*v=(*v<<8)|b;return 9;}
    }
    return -1;
}

static const uint8_t* getpg(uint32_t pg){ return g_data+(size_t)(pg-1)*g_psz; }

static uint32_t crc32_fn(const uint8_t *d, size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++){c^=d[i];for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;}
    return c^0xFFFFFFFF;
}

static int64_t sext(uint64_t v,int bits){
    if(bits>=64)return(int64_t)v;
    return(v&(1ULL<<(bits-1)))?(int64_t)(v|(~0ULL<<bits)):(int64_t)v;
}

typedef enum{VN,VI,VR,VTX,VB}ValType;
typedef struct{ValType t;int64_t i;double d;uint8_t*p;size_t n;}Val;
typedef struct{Val*v;int nc;}Rec;
typedef struct{int64_t rid;Rec r;}Row;

static uint8_t* cell_payload(const uint8_t*pg,size_t co,size_t*sz){
    size_t pos=co;uint64_t ps,rid;
    int n=rd_var(pg,pos,g_usz,&ps);if(n<0){*sz=0;return NULL;}pos+=n;
    n=rd_var(pg,pos,g_usz,&rid);if(n<0){*sz=0;return NULL;}pos+=n;
    size_t X=(size_t)g_usz-35,U;
    if(ps<=X)U=(size_t)ps;
    else{U=(size_t)((g_usz-12)*((ps-12)/(g_usz+31))+12);if(U>X)U=X;}
    uint8_t*buf=malloc(ps?ps:1);if(!buf){perror("malloc");exit(1);}
    size_t rem=ps,tc=U;
    if(pos+tc>g_usz)tc=g_usz-pos;
    memcpy(buf,pg+pos,tc);rem-=tc;pos+=tc;
    if(rem){
        uint32_t ov=be32(pg+pos);
        while(rem&&ov){
            const uint8_t*op=getpg(ov);
            size_t av=(size_t)g_usz-4;tc=rem<av?rem:av;
            memcpy(buf+(ps-rem),op+4,tc);rem-=tc;
            ov=be32(op);
        }
    }
    *sz=ps;return buf;
}

static Rec parse_rec(const uint8_t*p,size_t psz){
    Rec r={NULL,0};if(!psz)return r;
    size_t pos=0;uint64_t hs;
    int n=rd_var(p,pos,psz,&hs);if(n<0)return r;
    size_t hend=(size_t)hs;pos+=n;
    int cnt=0;uint64_t st[4096];
    while(pos<hend){n=rd_var(p,pos,psz,&st[cnt]);if(n<0)break;pos+=n;cnt++;}
    r.nc=cnt;r.v=calloc(cnt,sizeof(Val));
    size_t dp=hend;
    for(int i=0;i<cnt;i++){
        uint64_t s=st[i];
        if(s==0){r.v[i].t=VN;}
        else if(s>=1&&s<=4){int b=(int)s;uint64_t v=0;for(int j=0;j<b;j++)v=v<<8|p[dp+j];r.v[i].t=VI;r.v[i].i=sext(v,b*8);dp+=b;}
        else if(s==5){uint64_t v=0;for(int j=0;j<6;j++)v=v<<8|p[dp+j];r.v[i].t=VI;r.v[i].i=sext(v,48);dp+=6;}
        else if(s==6){r.v[i].t=VI;r.v[i].i=be64(p+dp);dp+=8;}
        else if(s==7){union{uint64_t u;double d;}u;u.u=(uint64_t)be32(p+dp)<<32|be32(p+dp+4);r.v[i].t=VR;r.v[i].d=u.d;dp+=8;}
        else if(s==8){r.v[i].t=VI;r.v[i].i=0;}
        else if(s==9){r.v[i].t=VI;r.v[i].i=1;}
        else if(s>=12&&!(s&1)){size_t l=(size_t)((s-12)/2);r.v[i].t=VB;r.v[i].p=malloc(l?l:1);memcpy(r.v[i].p,p+dp,l);r.v[i].n=l;dp+=l;}
        else if(s>=13&&(s&1)){size_t l=(size_t)((s-13)/2);r.v[i].t=VTX;r.v[i].p=malloc(l?l:1);memcpy(r.v[i].p,p+dp,l);r.v[i].n=l;dp+=l;}
    }
    return r;
}

static void walk(uint32_t pn,Row**rows,int*nr,int*cap){
    if(pn==0)return;
    const uint8_t*pg=getpg(pn);
    size_t ho=(pn==1)?100:0;
    uint8_t pt=pg[ho];
    uint16_t nc=be16(pg+ho+3);
    if(pt==13){
        for(int i=0;i<nc;i++){
            size_t co=be16(pg+ho+8+i*2);
            size_t psz;uint8_t*pl=cell_payload(pg,co,&psz);
            size_t pos=co;uint64_t tmp,rid;
            int n=rd_var(pg,pos,g_usz,&tmp);pos+=n;
            n=rd_var(pg,pos,g_usz,&rid);pos+=n;
            if(*nr>=*cap){*cap=*cap?*cap*2:64;*rows=realloc(*rows,*cap*sizeof(Row));}
            (*rows)[*nr].rid=(int64_t)rid;
            (*rows)[*nr].r=parse_rec(pl,psz);
            free(pl);(*nr)++;
        }
    }else if(pt==5){
        for(int i=0;i<nc;i++){
            size_t co=be16(pg+ho+12+i*2);
            walk(be32(pg+co),rows,nr,cap);
        }
        walk(be32(pg+ho+8),rows,nr,cap);
    }
}

typedef struct{char*type;char*name;char*tbl;int64_t rp;char*sql;}SEntry;

static char*val_text(Val*v){
    if(v->t!=VTX)return NULL;
    char*s=malloc(v->n+1);memcpy(s,v->p,v->n);s[v->n]='\0';return s;
}

static void read_schema(SEntry**out,int*cnt){
    Row*rows=NULL;int nr=0,cap=0;
    walk(1,&rows,&nr,&cap);
    *out=malloc((nr+1)*sizeof(SEntry));*cnt=0;
    for(int i=0;i<nr;i++){
        if(rows[i].r.nc<5)continue;
        char*type=val_text(&rows[i].r.v[0]);
        char*name=val_text(&rows[i].r.v[1]);
        char*tbl=val_text(&rows[i].r.v[2]);
        int64_t rp=(rows[i].r.v[3].t==VI)?rows[i].r.v[3].i:0;
        char*sql=val_text(&rows[i].r.v[4]);
        if(!type||!name)continue;
        if(strcmp(type,"table")!=0)continue;
        if(strncmp(name,"sqlite_",7)==0)continue;
        (*out)[*cnt].type=type;(*out)[*cnt].name=name;
        (*out)[*cnt].tbl=tbl;(*out)[*cnt].rp=rp;(*out)[*cnt].sql=sql;
        (*cnt)++;
    }
}

static int cmp_se(const void*a,const void*b){
    return strcmp(((SEntry*)a)->name,((SEntry*)b)->name);
}
static int cmp_row(const void*a,const void*b){
    int64_t ra=((Row*)a)->rid,rb=((Row*)b)->rid;
    return ra<rb?-1:ra>rb?1:0;
}

static const char* find_open_paren(const char*sql){
    int inq=0;
    for(const char*p=sql;*p;p++){
        if(*p=='"')inq=!inq;
        else if(*p=='('&&!inq)return p;
    }
    return NULL;
}

static const char* find_close_paren(const char*open){
    int depth=0,inq=0;
    for(const char*p=open;*p;p++){
        if(*p=='"')inq=!inq;
        else if(!inq){
            if(*p=='(')depth++;
            else if(*p==')'){depth--;if(!depth)return p;}
        }
    }
    return NULL;
}

static int parse_cols(const char*sql,char***names,int**aliases){
    const char*op=find_open_paren(sql);
    if(!op){*names=NULL;*aliases=NULL;return 0;}
    const char*cp=find_close_paren(op);
    if(!cp){*names=NULL;*aliases=NULL;return 0;}
    const char*ds=op+1;
    const char*de=cp;
    int maxc=256;
    char**cols=malloc(maxc*sizeof(char*));
    int*al=malloc(maxc*sizeof(int));
    int ncol=0;
    const char*start=ds;
    int depth=0,inq=0;
    for(const char*q=ds;;q++){
        if(q>=de||(*q==','&&depth==0&&!inq)){
            int dlen=(int)(q-start);
            if(dlen>0){
                char*def=malloc(dlen+1);memcpy(def,start,dlen);def[dlen]='\0';
                const char*d=def;
                while(*d==' '||*d=='\t'||*d=='\n'||*d=='\r')d++;
                char*cn;
                if(*d=='"'){
                    d++;const char*s2=d;while(*d&&*d!='"')d++;
                    int l=(int)(d-s2);cn=malloc(l+1);memcpy(cn,s2,l);cn[l]='\0';
                }else{
                    const char*s2=d;
                    while(*d&&*d!=' '&&*d!='\t'&&*d!='\n'&&*d!='\r'&&*d!='('&&*d!=',')d++;
                    int l=(int)(d-s2);cn=malloc(l+1);memcpy(cn,s2,l);cn[l]='\0';
                }
                int alias=0;
                const char*tp=d;
                while(*tp==' '||*tp=='\t'||*tp=='\n'||*tp=='\r')tp++;
                const char*ts=tp;
                while(*tp&&((*tp>='A'&&*tp<='Z')||(*tp>='a'&&*tp<='z')||(*tp>='0'&&*tp<='9')||*tp=='_'))tp++;
                int tl=(int)(tp-ts);
                if(tl==7){
                    int match=1;const char*iw="INTEGER";
                    for(int k=0;k<7;k++){char c=ts[k];if(c>='a'&&c<='z')c-=32;if(c!=iw[k]){match=0;break;}}
                    if(match){
                        const char*after=tp;
                        while(*after==' '||*after=='\t'||*after=='\n'||*after=='\r')after++;
                        if(*after!='('){
                            char*up=malloc(dlen+1);
                            for(int k=0;k<dlen;k++)up[k]=(def[k]>='a'&&def[k]<='z')?def[k]-32:def[k];
                            up[dlen]='\0';
                            char*pp=strstr(up,"PRIMARY");
                            while(pp){
                                pp+=7;
                                while(*pp==' '||*pp=='\t'||*pp=='\n'||*pp=='\r')pp++;
                                if(strncmp(pp,"KEY",3)==0){alias=1;break;}
                                pp=strstr(pp,"PRIMARY");
                            }
                            free(up);
                        }
                    }
                }
                if(ncol>=maxc){maxc*=2;cols=realloc(cols,maxc*sizeof(char*));al=realloc(al,maxc*sizeof(int));}
                cols[ncol]=cn;al[ncol]=alias;ncol++;
                free(def);
            }
            start=q+1;
            if(q>=de)break;
        }
        if(q<de){
            if(*q=='"')inq=!inq;
            else if(!inq){
                if(*q=='(')depth++;
                else if(*q==')')depth--;
            }
        }
    }
    *names=cols;*aliases=al;return ncol;
}

static void print_real(double d){
    char buf[4096];
    snprintf(buf,sizeof(buf),"%.8f",d);
    char*dot=strchr(buf,'.');
    if(dot){
        char*end=buf+strlen(buf)-1;
        while(end>dot+1&&*end=='0')*end--='\0';
    }
    fputs(buf,stdout);
}

static void print_text(const uint8_t*p,size_t n){
    putchar('"');
    for(size_t i=0;i<n;i++){
        uint8_t c=p[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t*p,size_t n){
    printf("X'");
    for(size_t i=0;i<n;i++)printf("%02X",p[i]);
    printf("'");
}

static void print_val(Val*v){
    switch(v->t){
        case VN:printf("NULL");break;
        case VI:printf("%lld",(long long)v->i);break;
        case VR:print_real(v->d);break;
        case VTX:
            if(v->n<=100)print_text(v->p,v->n);
            else printf("<TEXT len=%zu crc32=%08x>",v->n,crc32_fn(v->p,v->n));
            break;
        case VB:
            if(v->n<=100)print_blob(v->p,v->n);
            else printf("<BLOB len=%zu crc32=%08x>",v->n,crc32_fn(v->p,v->n));
            break;
    }
}

int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];
    snprintf(path,sizeof(path),"%s/db.sqlite",argv[1]);
    FILE*f=fopen(path,"rb");
    if(!f){perror(path);return 1;}
    fseek(f,0,SEEK_END);g_fsize=(size_t)ftell(f);fseek(f,0,SEEK_SET);
    g_data=malloc(g_fsize);
    if(fread(g_data,1,g_fsize,f)!=g_fsize){perror("read");return 1;}
    fclose(f);

    g_psz=be16(g_data+16);
    if(g_psz==1)g_psz=65536;
    g_resv=g_data[20];
    g_usz=(uint16_t)(g_psz-g_resv);

    SEntry*se=NULL;int secnt=0;
    read_schema(&se,&secnt);
    qsort(se,secnt,sizeof(SEntry),cmp_se);

    int first=1;
    for(int t=0;t<secnt;t++){
        char**colnames=NULL;int*colalias=NULL;int ncols=0;
        if(se[t].sql)ncols=parse_cols(se[t].sql,&colnames,&colalias);

        Row*rows=NULL;int nr=0,cap=0;
        walk((uint32_t)se[t].rp,&rows,&nr,&cap);
        qsort(rows,nr,sizeof(Row),cmp_row);

        if(!first)putchar('\n');
        first=0;

        printf("TABLE %s rows=%d\n",se[t].name,nr);
        printf("COLUMNS");
        for(int c=0;c<ncols;c++){
            if(c)printf(",");
            printf(" %s",colnames[c]);
        }
        putchar('\n');

        for(int r=0;r<nr;r++){
            printf("%lld:",(long long)rows[r].rid);
            for(int c=0;c<ncols;c++){
                if(c)printf(",");
                printf(" ");
                if(colalias&&colalias[c]){
                    printf("%lld",(long long)rows[r].rid);
                }else if(c<rows[r].r.nc){
                    print_val(&rows[r].r.v[c]);
                }else{
                    printf("NULL");
                }
            }
            putchar('\n');
        }
    }
    return 0;
}

use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], offset: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut i = offset;
    loop {
        let byte = data[i];
        if i - offset == 8 {
            result = (result << 8) | (byte as u64);
            i += 1;
            break;
        }
        result = (result << 7) | (byte & 0x7F) as u64;
        i += 1;
        if byte & 0x80 == 0 {
            break;
        }
    }
    (result, i)
}

fn read_table_btree(
    data: &[u8],
    root_page: u32,
    page_size: usize,
    reserved_bytes: usize,
) -> Vec<(i64, Vec<Value>)> {
    let mut rows = Vec::new();
    walk_btree(data, root_page, page_size, reserved_bytes, &mut rows);
    rows.sort_by_key(|(rowid, _)| *rowid);
    rows
}

fn walk_btree(
    data: &[u8],
    page_num: u32,
    page_size: usize,
    reserved_bytes: usize,
    rows: &mut Vec<(i64, Vec<Value>)>,
) {
    if page_num == 0 {
        return;
    }
    let page_offset = (page_num as usize - 1) * page_size;
    let page = &data[page_offset..page_offset + page_size];
    let header_offset = if page_num == 1 { 100 } else { 0 };
    let page_type = page[header_offset];
    let cell_count =
        u16::from_be_bytes([page[header_offset + 3], page[header_offset + 4]]) as usize;
    let cell_ptr_start = header_offset + if page_type == 5 { 12 } else { 8 };

    if page_type == 5 {
        for i in 0..cell_count {
            let ptr = u16::from_be_bytes([
                page[cell_ptr_start + i * 2],
                page[cell_ptr_start + i * 2 + 1],
            ]) as usize;
            let child_page =
                u32::from_be_bytes([page[ptr], page[ptr + 1], page[ptr + 2], page[ptr + 3]]);
            walk_btree(data, child_page, page_size, reserved_bytes, rows);
        }
        let rightmost = u32::from_be_bytes([
            page[header_offset + 8],
            page[header_offset + 9],
            page[header_offset + 10],
            page[header_offset + 11],
        ]);
        walk_btree(data, rightmost, page_size, reserved_bytes, rows);
    } else if page_type == 10 {
        for i in 0..cell_count {
            let ptr = u16::from_be_bytes([
                page[cell_ptr_start + i * 2],
                page[cell_ptr_start + i * 2 + 1],
            ]) as usize;
            let (rowid, values) = read_leaf_cell(data, page_offset + ptr, page_size, reserved_bytes);
            rows.push((rowid, values));
        }
    }
}

fn read_leaf_cell(
    data: &[u8],
    cell_offset: usize,
    page_size: usize,
    reserved_bytes: usize,
) -> (i64, Vec<Value>) {
    let mut pos = cell_offset;
    let (_overflow_size, pos) = read_varint(data, pos);
    let (payload_len, pos) = read_varint(data, pos);
    let (rowid_u, pos) = read_varint(data, pos);
    let rowid = rowid_u as i64;

    let u = page_size - reserved_bytes;
    let payload_len_usize = payload_len as usize;
    let max_local = if payload_len_usize <= u - 35 {
        payload_len_usize
    } else {
        let m = ((u - 12) * 32 / 255) - 23;
        let k = m + ((payload_len_usize - m) % (u - 4));
        if k <= u - 35 {
            k
        } else {
            m
        }
    };

    let mut payload = data[pos..pos + max_local].to_vec();

    if payload_len_usize > max_local {
        let overflow_page = u32::from_be_bytes([
            data[pos + max_local],
            data[pos + max_local + 1],
            data[pos + max_local + 2],
            data[pos + max_local + 3],
        ]);
        let mut remaining = payload_len_usize - max_local;
        let mut page = overflow_page;
        while page != 0 && remaining > 0 {
            let po = (page as usize - 1) * page_size;
            let chunk = std::cmp::min(remaining, u - 4);
            payload.extend_from_slice(&data[po + 4..po + 4 + chunk]);
            remaining -= chunk;
            page = u32::from_be_bytes([data[po], data[po + 1], data[po + 2], data[po + 3]]);
        }
    }

    let values = parse_record(&payload);
    (rowid, values)
}

fn parse_record(payload: &[u8]) -> Vec<Value> {
    if payload.is_empty() {
        return Vec::new();
    }
    let (header_size, _) = read_varint(payload, 0);
    let header_size = header_size as usize;

    let mut serial_types = Vec::new();
    let mut p = 0;
    while p < header_size {
        let (st, new_p) = read_varint(payload, p);
        serial_types.push(st);
        p = new_p;
    }

    let mut values = Vec::new();
    let mut bp = header_size;

    for &st in &serial_types {
        let val = match st {
            0 => Value::Null,
            1 => {
                let v = payload[bp] as i8 as i64;
                bp += 1;
                Value::Integer(v)
            }
            2 => {
                let v = i16::from_be_bytes([payload[bp], payload[bp + 1]]) as i64;
                bp += 2;
                Value::Integer(v)
            }
            3 => {
                let mut b = [0u8; 4];
                if payload[bp] & 0x80 != 0 {
                    b[0] = 0xFF;
                }
                b[1..4].copy_from_slice(&payload[bp..bp + 3]);
                let v = i32::from_be_bytes(b) as i64;
                bp += 3;
                Value::Integer(v)
            }
            4 => {
                let v = i32::from_be_bytes([
                    payload[bp],
                    payload[bp + 1],
                    payload[bp + 2],
                    payload[bp + 3],
                ]) as i64;
                bp += 4;
                Value::Integer(v)
            }
            5 => {
                let mut b = [0u8; 8];
                if payload[bp] & 0x80 != 0 {
                    b[0] = 0xFF;
                    b[1] = 0xFF;
                }
                b[2..8].copy_from_slice(&payload[bp..bp + 6]);
                let v = i64::from_be_bytes(b);
                bp += 6;
                Value::Integer(v)
            }
            6 => {
                let v = i64::from_be_bytes([
                    payload[bp],
                    payload[bp + 1],
                    payload[bp + 2],
                    payload[bp + 3],
                    payload[bp + 4],
                    payload[bp + 5],
                    payload[bp + 6],
                    payload[bp + 7],
                ]);
                bp += 8;
                Value::Integer(v)
            }
            7 => {
                let v = f64::from_be_bytes([
                    payload[bp],
                    payload[bp + 1],
                    payload[bp + 2],
                    payload[bp + 3],
                    payload[bp + 4],
                    payload[bp + 5],
                    payload[bp + 6],
                    payload[bp + 7],
                ]);
                bp += 8;
                Value::Real(v)
            }
            8 => Value::Integer(0),
            9 => Value::Integer(1),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                let v = payload[bp..bp + len].to_vec();
                bp += len;
                Value::Blob(v)
            }
            n if n >= 13 => {
                let len = ((n - 13) / 2) as usize;
                let v = payload[bp..bp + len].to_vec();
                bp += len;
                Value::Text(v)
            }
            _ => Value::Null,
        };
        values.push(val);
    }
    values
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut crc = i;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
        table[i as usize] = crc;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = (crc >> 8) ^ table[((crc ^ b as u32) & 0xFF) as usize];
    }
    crc ^ 0xFFFFFFFF
}

fn format_value(val: &Value) -> String {
    match val {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => format!("{}", n),
        Value::Real(f) => format_real(*f),
        Value::Text(bytes) => format_text(bytes),
        Value::Blob(bytes) => format_blob(bytes),
    }
}

fn format_real(f: f64) -> String {
    let s = format!("{:.8}", f);
    let dot_pos = s.find('.').unwrap();
    let mut end = s.len();
    while end > dot_pos + 2 && s.as_bytes()[end - 1] == b'0' {
        end -= 1;
    }
    s[..end].to_string()
}

fn format_text(bytes: &[u8]) -> String {
    if bytes.len() > 100 {
        let crc = crc32(bytes);
        format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
    } else {
        let mut result: Vec<u8> = Vec::new();
        result.push(b'"');
        for &b in bytes {
            match b {
                b'\\' => result.extend_from_slice(b"\\\\"),
                b'"' => result.extend_from_slice(b"\\\""),
                b'\n' => result.extend_from_slice(b"\\n"),
                b'\r' => result.extend_from_slice(b"\\r"),
                b'\t' => result.extend_from_slice(b"\\t"),
                0x7F => {
                    result.extend_from_slice(b"\\x");
                    result.extend_from_slice(format!("{:02X}", b).as_bytes());
                }
                _ if b < 0x20 => {
                    result.extend_from_slice(b"\\x");
                    result.extend_from_slice(format!("{:02X}", b).as_bytes());
                }
                _ => result.push(b),
            }
        }
        result.push(b'"');
        String::from_utf8(result).unwrap()
    }
}

fn format_blob(bytes: &[u8]) -> String {
    if bytes.len() > 100 {
        let crc = crc32(bytes);
        format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
    } else {
        let mut s = String::from("X'");
        for &b in bytes {
            s.push_str(&format!("{:02X}", b));
        }
        s.push('\'');
        s
    }
}

fn parse_columns(sql: &str) -> (Vec<String>, Vec<bool>) {
    let sql_lower = sql.to_lowercase();
    let create_pos = sql_lower.find("create table").unwrap();
    let mut pos = create_pos + 12;

    while pos < sql.len() && sql.as_bytes()[pos].is_ascii_whitespace() {
        pos += 1;
    }

    if pos < sql.len() && sql.as_bytes()[pos] == b'"' {
        pos += 1;
        while pos < sql.len() && sql.as_bytes()[pos] != b'"' {
            pos += 1;
        }
        pos += 1;
    } else {
        while pos < sql.len()
            && !sql.as_bytes()[pos].is_ascii_whitespace()
            && sql.as_bytes()[pos] != b'('
        {
            pos += 1;
        }
    }

    while pos < sql.len() && sql.as_bytes()[pos].is_ascii_whitespace() {
        pos += 1;
    }

    pos += 1; // skip '('
    let content_start = pos;
    let mut depth = 1i32;
    while pos < sql.len() && depth > 0 {
        match sql.as_bytes()[pos] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            _ => {}
        }
        if depth > 0 {
            pos += 1;
        }
    }
    let content = &sql[content_start..pos];

    let defs = split_commas(content);
    let mut names = Vec::new();
    let mut is_alias = Vec::new();

    for def in &defs {
        let def = def.trim();
        if def.is_empty() {
            continue;
        }
        let (name, rest) = extract_column_name(def);
        names.push(name);
        is_alias.push(is_integer_primary_key(rest));
    }

    (names, is_alias)
}

fn split_commas(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut depth = 0i32;
    let mut in_quotes = false;
    let mut start = 0;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'"' => in_quotes = !in_quotes,
            b'(' if !in_quotes => depth += 1,
            b')' if !in_quotes => depth -= 1,
            b',' if depth == 0 && !in_quotes => {
                result.push(s[start..i].to_string());
                start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    result.push(s[start..].to_string());
    result
}

fn extract_column_name(def: &str) -> (String, &str) {
    if def.starts_with('"') {
        let end = def[1..].find('"').unwrap() + 1;
        let name = def[1..end].to_string();
        (name, &def[end + 1..])
    } else {
        let end = def
            .find(|c: char| c.is_whitespace() || c == '(')
            .unwrap_or(def.len());
        let name = def[..end].to_string();
        (name, &def[end..])
    }
}

fn is_integer_primary_key(rest: &str) -> bool {
    let trimmed = rest.trim_start();
    let lower = trimmed.to_lowercase();

    if !lower.starts_with("integer") {
        return false;
    }

    let after = &lower[7..];
    if !after.is_empty() {
        let c = after.as_bytes()[0];
        if c.is_ascii_alphanumeric() || c == b'_' {
            return false;
        }
    }

    let after_trimmed = after.trim_start();
    if after_trimmed.starts_with('(') {
        return false;
    }

    let words: Vec<&str> = lower.split_whitespace().collect();
    for i in 0..words.len().saturating_sub(1) {
        if words[i] == "primary" && words[i + 1] == "key" {
            return true;
        }
    }
    false
}

