                                Some(Value::Text(s)) => String::from_utf8_lossy(s).to_string(),
                                _ => String::new(),
                            };
                            tables.push((name_str, sql, *rp as u32));
                        }
                    }
                }
            }
        }
    }

    tables.sort_by(|a, b| a.0.cmp(&b.0));

    let mut first = true;
    for (name, sql, rootpage) in &tables {
        if !first {
