import Foundation

// MARK: - CSV Parser (RFC 4180)

func parseCSV(_ data: Data) -> [[String]] {
    var text = String(data: data, encoding: .utf8)!
    if text.hasPrefix("\u{FEFF}") {
        text = String(text.dropFirst())
    }
    var records: [[String]] = []
    var fields: [String] = []
    var i = text.startIndex
    let end = text.endIndex

    while i < end {
        var field = ""
        if text[i] == "\"" {
            i = text.index(after: i)
            while i < end {
                if text[i] == "\"" {
                    let next = text.index(after: i)
                    if next < end && text[next] == "\"" {
                        field.append("\"")
                        i = text.index(after: next)
                    } else {
                        i = next
                        break
                    }
                } else {
                    field.append(text[i])
                    i = text.index(after: i)
                }
            }
        } else {
            while i < end && text[i] != "," && text[i] != "\r" && text[i] != "\n" {
                field.append(text[i])
                i = text.index(after: i)
            }
        }
        fields.append(field)
        if i < end {
            if text[i] == "," {
                i = text.index(after: i)
            } else if text[i] == "\r" {
                i = text.index(after: i)
                if i < end && text[i] == "\n" {
                    i = text.index(after: i)
                }
                records.append(fields)
                fields = []
            } else if text[i] == "\n" {
                i = text.index(after: i)
                records.append(fields)
                fields = []
            }
        }
    }
    if !fields.isEmpty {
        records.append(fields)
    }
    return records
}

// MARK: - JSON String Encoder (compact, specific escaping)

func jsonStr(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\u{0C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if scalar.value < 0x20 {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

