import Foundation

// MARK: - CSV Parser (RFC 4180, byte-level)

func parseCSV(_ data: Data) -> [[String]] {
    var bytes = [UInt8](data)
    // Strip UTF-8 BOM
    if bytes.count >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF {
        bytes = Array(bytes[3...])
    }

    var records: [[String]] = []
    var fields: [String] = []
    var i = 0
    let n = bytes.count

    while i < n {
        var fieldBytes: [UInt8] = []
        if bytes[i] == 0x22 { // "
            i += 1
            while i < n {
                if bytes[i] == 0x22 { // "
                    if i + 1 < n && bytes[i + 1] == 0x22 { // ""
                        fieldBytes.append(0x22)
                        i += 2
                    } else {
                        i += 1 // skip closing quote
                        break
                    }
                } else {
                    fieldBytes.append(bytes[i])
                    i += 1
                }
            }
        } else {
            while i < n && bytes[i] != 0x2C && bytes[i] != 0x0D && bytes[i] != 0x0A {
                fieldBytes.append(bytes[i])
                i += 1
            }
        }
        fields.append(String(decoding: fieldBytes, as: UTF8.self))
        if i < n {
            if bytes[i] == 0x2C { // ,
                i += 1
            } else if bytes[i] == 0x0D { // \r
                i += 1
                if i < n && bytes[i] == 0x0A { // \n
                    i += 1
                }
                records.append(fields)
                fields = []
            } else if bytes[i] == 0x0A { // \n
                i += 1
                records.append(fields)
                fields = []
            }
        }
    }
    if !fields.isEmpty {
        records.append(fields)
    }
    return records
}

// MARK: - JSON String Encoder (compact, specific escaping)

func jsonStr(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\u{0C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if scalar.value < 0x20 {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

// MARK: - Tool Execution

typealias InventoryRow = (name: String, priceCents: Int, currency: String, stock: Int)

func executeTool(name: String, argumentsStr: String,
                 inventory: [String: InventoryRow],
                 rates: [String: Any]) -> String {
    let argsData = argumentsStr.data(using: .utf8)!
    let args = (try? JSONSerialization.jsonObject(with: argsData)) as? [String: Any] ?? [:]

    switch name {
    case "inventory_lookup":
        let sku = args["sku"] as? String ?? ""
        if let row = inventory[sku] {
            return "{\"sku\":\(jsonStr(sku)),\"name\":\(jsonStr(row.name)),\"price_cents\":\(row.priceCents),\"currency\":\(jsonStr(row.currency)),\"stock\":\(row.stock)}"
        } else {
            return "{\"error\":\(jsonStr("unknown sku: \(sku)"))}"
        }
    case "convert_currency":
        let amountCents = args["amount_cents"] as? Int ?? 0
        let from = args["from"] as? String ?? ""
        let to = args["to"] as? String ?? ""
        let rateFrom = rates[from] as? Int ?? 1
        let rateTo = rates[to] as? Int ?? 1
        let converted = (2 * amountCents * rateTo + rateFrom) / (2 * rateFrom)
        return "{\"amount_cents\":\(converted),\"currency\":\(jsonStr(to))}"
    default:
        return "{\"error\":\(jsonStr("unknown tool: \(name)"))}"
    }
}

// MARK: - HTTP Request

let sessionConfig = URLSessionConfiguration.default
sessionConfig.timeoutIntervalForRequest = 300
sessionConfig.httpAdditionalHeaders = nil
let sharedSession = URLSession(configuration: sessionConfig)

func sendRequest(url: String, apiKey: String, body: [String: Any]) -> (Int, Data) {
    let requestUrl = URL(string: url)!
    var request = URLRequest(url: requestUrl)
    request.httpMethod = "POST"
    request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    let bodyData = try! JSONSerialization.data(withJSONObject: body)
    request.httpBody = bodyData

    let sem = DispatchSemaphore(value: 0)
    var statusCode = 0
    var responseData = Data()

    let task = sharedSession.dataTask(with: request) { data, response, error in
        if let httpResponse = response as? HTTPURLResponse {
            statusCode = httpResponse.statusCode
        }
        if let d = data { responseData = d }
        sem.signal()
    }
    task.resume()
    sem.wait()

    return (statusCode, responseData)
}

