use std::env;
use std::fs;
use std::path::Path;

fn goertzel_power(block: &[i16], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = (x as f64) + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    let entries = fs::read_dir(Path::new(dir)).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".wav") {
            files.push(name);
        }
    }
    files.sort();

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];
    let digits: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut first_file = true;
    for name in &files {
        if !first_file {
            println!();
        }
        first_file = false;

        let path = Path::new(dir).join(name);
        let raw = fs::read(&path).unwrap();

        if raw.len() < 12 || &raw[0..4] != b"RIFF" || &raw[8..12] != b"WAVE" {
            println!("{}: unsupported", name);
            continue;
        }

        let mut fmt_body: Option<Vec<u8>> = None;
        let mut data_body: Option<Vec<u8>> = None;

        let mut pos = 12usize;
        while pos + 8 <= raw.len() {
            let chunk_id = &raw[pos..pos + 4];
            let chunk_size =
                u32::from_le_bytes([raw[pos + 4], raw[pos + 5], raw[pos + 6], raw[pos + 7]])
                    as usize;
            let body_start = pos + 8;
            let body_end = body_start + chunk_size;
            if body_end > raw.len() {
                break;
            }
            if chunk_id == b"fmt " {
                fmt_body = Some(raw[body_start..body_end].to_vec());
            } else if chunk_id == b"data" {
                data_body = Some(raw[body_start..body_end].to_vec());
            }
            pos = body_end + (chunk_size % 2);
        }

        let fmt_body = match fmt_body {
            Some(f) => f,
            None => {
                println!("{}: unsupported", name);
                continue;
            }
        };
        let data_body = match data_body {
            Some(d) => d,
            None => {
                println!("{}: unsupported", name);
                continue;
            }
        };

        if fmt_body.len() < 16 {
            println!("{}: unsupported", name);
            continue;
        }

        let format_tag = u16::from_le_bytes([fmt_body[0], fmt_body[1]]);
        let channels = u16::from_le_bytes([fmt_body[2], fmt_body[3]]) as usize;
        let sample_rate =
            u32::from_le_bytes([fmt_body[4], fmt_body[5], fmt_body[6], fmt_body[7]]) as usize;
        let bits_per_sample = u16::from_le_bytes([fmt_body[14], fmt_body[15]]) as usize;

        let effective_format = if format_tag == 0xFFFE {
            if fmt_body.len() >= 26 {
                u16::from_le_bytes([fmt_body[24], fmt_body[25]])
            } else {
                println!("{}: unsupported", name);
                continue;
            }
        } else {
            format_tag
        };

        if effective_format != 1 || bits_per_sample != 16 {
            println!("{}: unsupported", name);
            continue;
        }
        if (channels != 1 && channels != 2) || (sample_rate != 8000 && sample_rate != 16000) {
            println!("{}: unsupported", name);
            continue;
        }

        let frame_size = 2 * channels;
        let num_frames = data_body.len() / frame_size;
        let mut samples: Vec<i16> = Vec::with_capacity(num_frames);
        for i in 0..num_frames {
            let offset = i * frame_size;
            let sample = i16::from_le_bytes([data_body[offset], data_body[offset + 1]]);
            samples.push(sample);
        }

        let n = sample_rate / 50;
        let num_blocks = samples.len() / n;
        let rate_f = sample_rate as f64;

        let mut labels: Vec<Option<char>> = vec![None; num_blocks];

        for bi in 0..num_blocks {
            let block = &samples[bi * n..(bi + 1) * n];
            let e: f64 = block.iter().map(|&x| (x as f64) * (x as f64)).sum();

            if e < 1000000.0 * n as f64 {
                continue;
            }

            let mut r_low = [0.0f64; 4];
            let mut r_high = [0.0f64; 4];

            for fi in 0..4 {
                r_low[fi] = goertzel_power(block, low_freqs[fi], rate_f, n, e);
                r_high[fi] = goertzel_power(block, high_freqs[fi], rate_f, n, e);
            }

            let mut best_low = 0;
            let mut best_high = 0;
            for fi in 1..4 {
                if r_low[fi] > r_low[best_low] {
                    best_low = fi;
                }
                if r_high[fi] > r_high[best_high] {
                    best_high = fi;
                }
            }

            if r_low[best_low] >= 0.1
                && r_high[best_high] >= 0.1
                && (r_low[best_low] + r_high[best_high]) >= 0.6
            {
                labels[bi] = Some(digits[best_low][best_high]);
            }
        }

        // Bridging
        let mut bridged: Vec<Option<char>> = labels.clone();
        if num_blocks >= 3 {
            for bi in 1..num_blocks - 1 {
                if labels[bi].is_none() {
                    if let (Some(d1), Some(d2)) = (labels[bi - 1], labels[bi + 1]) {
                        if d1 == d2 {
                            bridged[bi] = Some(d1);
                        }
                    }
                }
            }
        }

        // Events
        let mut events: Vec<(char, usize, usize)> = Vec::new();
        let mut bi = 0;
        while bi < num_blocks {
            if let Some(d) = bridged[bi] {
                let start = bi;
                while bi < num_blocks && bridged[bi] == Some(d) {
                    bi += 1;
                }
                let end = bi;
                if end - start >= 2 {
                    events.push((d, start * 20, end * 20));
                }
            } else {
                bi += 1;
            }
        }

        println!(
            "{}: {} Hz, {} ch, {} blocks",
            name, sample_rate, channels, num_blocks
        );
        for (d, start, end) in &events {
            println!("{} {} {}", d, start, end);
        }
        let digits_str: String = events.iter().map(|(d, _, _)| *d).collect();
        println!("digits: {}", digits_str);
    }
}

#!/usr/bin/env python3
import sys
import socket
import os
import base64
import hashlib
import struct
import re


def parse_ws_url(url):
    match = re.match(r'ws://([^:/]+):(\d+)(/.*)', url)
    if not match:
        raise ValueError(f"Invalid URL: {url}")
    host = match.group(1)
    port = int(match.group(2))
    path = match.group(3)
    return host, port, path


class WSConnection:
    def __init__(self, sock):
        self.sock = sock
        self.buffer = b''

    def read_exact(self, n):
        while len(self.buffer) < n:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buffer += data
        result = self.buffer[:n]
        self.buffer = self.buffer[n:]
        return result

    def read_frame(self):
        header = self.read_exact(2)
        fin = (header[0] >> 7) & 1
        opcode = header[0] & 0x0F
        masked = (header[1] >> 7) & 1
        length = header[1] & 0x7F

        if length == 126:
            length = struct.unpack('!H', self.read_exact(2))[0]
        elif length == 127:
            length = struct.unpack('!Q', self.read_exact(8))[0]

        mask_key = None
        if masked:
            mask_key = self.read_exact(4)

        payload = self.read_exact(length) if length > 0 else b''

        if mask_key:
            payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))

        return fin, opcode, payload

    def send_frame(self, opcode, payload):
        frame = bytearray()
        frame.append(0x80 | opcode)

        mask_key = os.urandom(4)
        while mask_key == b'\x00\x00\x00\x00':
            mask_key = os.urandom(4)

        length = len(payload)
        if length <= 125:
            frame.append(0x80 | length)
        elif length <= 65535:
            frame.append(0x80 | 126)
            frame.extend(struct.pack('!H', length))
        else:
            frame.append(0x80 | 127)
            frame.extend(struct.pack('!Q', length))

        frame.extend(mask_key)
        masked_payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))
        frame.extend(masked_payload)

        self.sock.sendall(bytes(frame))

    def close(self):
        try:
            self.sock.close()
        except Exception:
            pass


def do_handshake(conn, host, port, path):
    key = base64.b64encode(os.urandom(16)).decode('ascii')

    request = (
        f"GET {path} HTTP/1.1\r\n"
        f"Host: {host}:{port}\r\n"
        f"Upgrade: websocket\r\n"
        f"Connection: Upgrade\r\n"
        f"Sec-WebSocket-Version: 13\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        f"\r\n"
    )

    conn.sock.sendall(request.encode('ascii'))

    header_data = b''
    while b'\r\n\r\n' not in header_data:
        data = conn.sock.recv(65536)
        if not data:
            raise ConnectionError("Connection closed during handshake")
        header_data += data

    sep = header_data.index(b'\r\n\r\n')
    headers_raw = header_data[:sep + 4]
    conn.buffer = header_data[sep + 4:]

    lines = headers_raw.split(b'\r\n')
    status_line = lines[0].decode('ascii')
    parts = status_line.split(' ', 2)
    status_code = int(parts[1])
    reason = parts[2] if len(parts) > 2 else ''

    headers = {}
    for line in lines[1:]:
        if b':' in line:
            name, value = line.split(b':', 1)
            headers[name.strip().lower().decode('ascii')] = value.strip().decode('ascii')

    return status_code, reason, headers, key


def handle_close(conn, payload, state):
    if len(payload) >= 2:
        code = struct.unpack('!H', payload[:2])[0]
        reason_bytes = payload[2:]
        reason_str = reason_bytes.decode('utf-8', errors='replace')
    else:
        code = 1005
        reason_str = ''

    if reason_str:
        print(f"closed {code} {reason_str}")
    else:
        print(f"closed {code}")

    if not state['sent_close']:
        close_payload = struct.pack('!H', code)
        conn.send_frame(8, close_payload)
        state['sent_close'] = True


def read_message(conn, state):
    """Read a complete message. Returns (opcode, payload) or None if closed/error."""
    while True:
        try:
            fin, opcode, payload = conn.read_frame()
        except ConnectionError:
            return None

        if opcode == 9:
            conn.send_frame(10, payload)
            continue

        if opcode == 10:
            continue

        if opcode == 8:
            handle_close(conn, payload, state)
            return None

        if opcode in (1, 2):
            msg_opcode = opcode
            msg_payload = payload

            while not fin:
                try:
                    fin2, opcode2, payload2 = conn.read_frame()
                except ConnectionError:
                    return None

                if opcode2 == 9:
                    conn.send_frame(10, payload2)
                    continue
                if opcode2 == 10:
                    continue
                if opcode2 == 8:
                    handle_close(conn, payload2, state)
                    return None

                msg_payload += payload2
                fin = fin2

            return (msg_opcode, msg_payload)

        continue


def process_session(url):
    try:
        host, port, path = parse_ws_url(url)
    except ValueError:
        return

    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((host, port))
    except (OSError, ConnectionError):
        return

    conn = WSConnection(sock)
    state = {'sent_close': False}

    try:
        status_code, reason, headers, key = do_handshake(conn, host, port, path)
    except (ConnectionError, Exception):
        conn.close()
        return

    if status_code != 101:
        print(f"handshake failed: {status_code} {reason}")
        conn.close()
        return

    expected_accept = base64.b64encode(
        hashlib.sha1((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode('ascii')).digest()
    ).decode('ascii')

    actual_accept = headers.get('sec-websocket-accept', None)
    if actual_accept != expected_accept:
        print("handshake failed: bad Sec-WebSocket-Accept")
        conn.close()
        return

    while True:
        msg = read_message(conn, state)
        if msg is None:
            break

        msg_opcode, msg_payload = msg

        if msg_opcode == 1:
            text = msg_payload.decode('utf-8')

            if text == 'BYE':
                close_payload = struct.pack('!H', 1000)
                conn.send_frame(8, close_payload)
                state['sent_close'] = True

                while True:
                    msg2 = read_message(conn, state)
                    if msg2 is None:
                        break
                break

            elif text.startswith('ADD '):
                parts = text.split(' ', 2)
                a = int(parts[1])
                b = int(parts[2])
                result = str(a + b)
                conn.send_frame(1, result.encode('utf-8'))
                print(f"{text} -> {result}")

            elif text.startswith('REV '):
                text_content = text[4:]
                reversed_text = text_content[::-1]
                conn.send_frame(1, reversed_text.encode('utf-8'))
                print(f"{text} -> {reversed_text}")

            elif text == 'SHA1':
                msg2 = read_message(conn, state)
                if msg2 is None:
                    break
                _, bin_payload = msg2
                hex_digest = hashlib.sha1(bin_payload).hexdigest()
                conn.send_frame(1, hex_digest.encode('utf-8'))
                print(f"SHA1 {len(bin_payload)} -> {hex_digest}")

        elif msg_opcode == 2:
            pass

    conn.close()


