import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> wavFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wavFiles.add(f);
            }
        }
        wavFiles.sort((a, b) -> {
            byte[] an = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getName().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        boolean first = true;
        for (File file : wavFiles) {
            if (!first) System.out.println();
            first = false;
            processFile(file);
        }
    }

    static void processFile(File file) throws Exception {
        String name = file.getName();
        byte[] data = Files.readAllBytes(file.toPath());

        if (data.length < 12) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F'
                || data[8] != 'W' || data[9] != 'A' || data[10] != 'V' || data[11] != 'E') {
            System.out.println(name + ": unsupported");
            return;
        }

        int pos = 12;
        byte[] fmtBody = null;
        byte[] dataBody = null;

        while (pos + 8 <= data.length) {
            String chunkId = new String(data, pos, 4, StandardCharsets.US_ASCII);
            int chunkSize = readInt32LE(data, pos + 4);
            pos += 8;

            if (chunkId.equals("fmt ")) {
                fmtBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            } else if (chunkId.equals("data")) {
                dataBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            }

            pos += chunkSize;
            if (chunkSize % 2 != 0) pos++;
        }

        if (fmtBody == null || dataBody == null) {
            System.out.println(name + ": unsupported");
            return;
        }

        int formatTag = readInt16LE(fmtBody, 0);
        int channels = readInt16LE(fmtBody, 2);
        int sampleRate = readInt32LE(fmtBody, 4);
        int bitsPerSample = readInt16LE(fmtBody, 10);

        int effectiveFormat = formatTag;
        if (formatTag == 0xFFFE) {
            if (fmtBody.length >= 26) {
                effectiveFormat = readInt16LE(fmtBody, 24);
            } else {
                System.out.println(name + ": unsupported");
                return;
            }
        }

        if (effectiveFormat != 1 || bitsPerSample != 16) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (channels < 1 || channels > 2) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (sampleRate != 8000 && sampleRate != 16000) {
            System.out.println(name + ": unsupported");
            return;
        }

        int frameSize = 2 * channels;
        int numFrames = dataBody.length / frameSize;
        short[] samples = new short[numFrames];
        for (int i = 0; i < numFrames; i++) {
            int offset = i * frameSize;
            samples[i] = (short) ((dataBody[offset] & 0xFF) | ((dataBody[offset + 1] & 0xFF) << 8));
        }

        int N = sampleRate / 50;
        int numBlocks = numFrames / N;

        double[] lowFreqs = {697, 770, 852, 941};
        double[] highFreqs = {1209, 1336, 1477, 1633};

        char[] digitMap = {
            '1', '2', '3', 'A',
            '4', '5', '6', 'B',
            '7', '8', '9', 'C',
            '*', '0', '#', 'D'
        };

        char[] blockLabels = new char[numBlocks];
        for (int b = 0; b < numBlocks; b++) {
            int start = b * N;
            double E = 0;
            for (int n = 0; n < N; n++) {
                double x = samples[start + n];
                E += x * x;
            }

            if (E < 1000000.0 * N) {
                blockLabels[b] = 0;
                continue;
            }

            double maxLowR = -1, maxHighR = -1;
            int maxLowIdx = -1, maxHighIdx = -1;

            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, start, N, lowFreqs[fi], sampleRate, E);
                if (r > maxLowR) {
                    maxLowR = r;
                    maxLowIdx = fi;
                }
            }
            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, start, N, highFreqs[fi], sampleRate, E);
                if (r > maxHighR) {
                    maxHighR = r;
                    maxHighIdx = fi;
                }
            }

            if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
                blockLabels[b] = digitMap[maxLowIdx * 4 + maxHighIdx];
            } else {
                blockLabels[b] = 0;
            }
        }

        char[] bridged = Arrays.copyOf(blockLabels, numBlocks);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (blockLabels[i] == 0 && blockLabels[i - 1] != 0 && blockLabels[i + 1] != 0
                    && blockLabels[i - 1] == blockLabels[i + 1]) {
                bridged[i] = blockLabels[i - 1];
            }
        }

        List<int[]> events = new ArrayList<>();
        List<Character> eventDigits = new ArrayList<>();

        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == 0) {
                i++;
                continue;
            }
            char d = bridged[i];
            int startBlock = i;
            while (i < numBlocks && bridged[i] == d) i++;
            int endBlock = i - 1;
            if (endBlock - startBlock + 1 >= 2) {
                events.add(new int[]{startBlock, endBlock});
                eventDigits.add(d);
            }
        }

        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        StringBuilder digits = new StringBuilder();
        for (int j = 0; j < events.size(); j++) {
            int[] ev = events.get(j);
            System.out.println(eventDigits.get(j) + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
            digits.append(eventDigits.get(j));
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int start, int N, double freq, double rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readInt32LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8)
                | ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }

    static int readInt16LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }
}

