import * as net from 'net';
import * as crypto from 'crypto';

class BufferedSocket {
  private buffer: Buffer = Buffer.alloc(0);
  private socket: net.Socket;
  private waiting: (() => void)[] = [];
  private closed: boolean = false;

  constructor(socket: net.Socket) {
    this.socket = socket;
    socket.on('data', (chunk: Buffer) => {
      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.wake();
    });
    socket.on('close', () => {
      this.closed = true;
      this.wake();
    });
    socket.on('error', () => {
      this.closed = true;
      this.wake();
    });
  }

  private wake(): void {
    while (this.waiting.length > 0) {
      const w = this.waiting.shift()!;
      w();
    }
  }

  private async waitForData(): Promise<void> {
    if (this.closed) return;
    await new Promise<void>(resolve => this.waiting.push(resolve));
  }

  async readBytes(n: number): Promise<Buffer | null> {
    while (this.buffer.length < n) {
      if (this.closed) return null;
      await this.waitForData();
    }
    const result = Buffer.from(this.buffer.subarray(0, n));
    this.buffer = this.buffer.subarray(n);
    return result;
  }

  async readUntilDoubleCRLF(): Promise<string | null> {
    const delim = Buffer.from([0x0D, 0x0A, 0x0D, 0x0A]);
    while (true) {
      const idx = this.buffer.indexOf(delim);
      if (idx !== -1) {
        const header = this.buffer.subarray(0, idx).toString('latin1');
        this.buffer = this.buffer.subarray(idx + 4);
        return header;
      }
      if (this.closed) return null;
      await this.waitForData();
    }
  }
}

function writeFrame(socket: net.Socket, opcode: number, payload: Buffer): void {
  const parts: Buffer[] = [];
  parts.push(Buffer.from([0x80 | opcode]));

  const len = payload.length;
  if (len <= 125) {
    parts.push(Buffer.from([0x80 | len]));
  } else if (len <= 65535) {
    parts.push(Buffer.from([0x80 | 126]));
    const ext = Buffer.alloc(2);
    ext.writeUInt16BE(len);
    parts.push(ext);
  } else {
    parts.push(Buffer.from([0x80 | 127]));
    const ext = Buffer.alloc(8);
    ext.writeBigUInt64BE(BigInt(len));
    parts.push(ext);
  }

  let maskKey: Buffer;
  do {
    maskKey = crypto.randomBytes(4);
  } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);
  parts.push(maskKey);

  const masked = Buffer.alloc(len);
  for (let i = 0; i < len; i++) {
    masked[i] = payload[i] ^ maskKey[i % 4];
  }
  parts.push(masked);

  socket.write(Buffer.concat(parts));
}

async function readFrame(bs: BufferedSocket): Promise<{ fin: boolean; opcode: number; payload: Buffer } | null> {
  const h = await bs.readBytes(2);
  if (!h) return null;

  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let payloadLen = h[1] & 0x7F;

  if (payloadLen === 126) {
    const ext = await bs.readBytes(2);
    if (!ext) return null;
    payloadLen = ext.readUInt16BE(0);
  } else if (payloadLen === 127) {
    const ext = await bs.readBytes(8);
    if (!ext) return null;
    payloadLen = Number(ext.readBigUInt64BE(0));
  }

  let maskKey: Buffer | null = null;
  if (masked) {
    maskKey = await bs.readBytes(4);
    if (!maskKey) return null;
  }

  let payload: Buffer;
  if (payloadLen > 0) {
    payload = await bs.readBytes(payloadLen);
    if (!payload) return null;
    if (maskKey) {
      for (let i = 0; i < payload.length; i++) {
        payload[i] ^= maskKey[i % 4];
      }
    }
  } else {
    payload = Buffer.alloc(0);
  }

  return { fin, opcode, payload };
}

function connect(host: string, port: number): Promise<net.Socket> {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection(port, host, () => {
      resolve(socket);
    });
    socket.on('error', reject);
  });
}

async function handleSession(url: string): Promise<void> {
  const parsed = new URL(url);
  const host = parsed.hostname;
  const port = parseInt(parsed.port) || 80;
  const path = parsed.pathname + parsed.search;

  let socket: net.Socket;
  try {
    socket = await connect(host, port);
  } catch {
    return;
  }

  const bs = new BufferedSocket(socket);

  const key = crypto.randomBytes(16).toString('base64');
  const request = `GET ${path} HTTP/1.1\r\nHost: ${host}:${port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${key}\r\n\r\n`;

  socket.write(request);

  const headerStr = await bs.readUntilDoubleCRLF();
  if (headerStr === null) {
    socket.destroy();
    return;
  }

  const lines = headerStr.split('\r\n');
  const statusLine = lines[0];
  const match = statusLine.match(/^HTTP\/\d\.\d (\d+) (.*)$/);

  if (!match) {
    socket.destroy();
    return;
  }

  const statusCode = parseInt(match[1]);
  const reason = match[2];

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reason}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');

  let acceptHeader: string | null = null;
  for (let i = 1; i < lines.length; i++) {
    const colonIdx = lines[i].indexOf(':');
    if (colonIdx === -1) continue;
    const name = lines[i].substring(0, colonIdx).trim().toLowerCase();
    const value = lines[i].substring(colonIdx + 1).trim();
    if (name === 'sec-websocket-accept') {
      acceptHeader = value;
    }
  }

  if (acceptHeader !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  await processFrames(bs, socket);
  socket.destroy();
}

async function processFrames(bs: BufferedSocket, socket: net.Socket): Promise<void> {
  let fragments: Buffer[] = [];
  let currentOpcode: number | null = null;
  let sentClose = false;
  let sha1Pending = false;

  function handleClose(payload: Buffer): void {
    let code: number;
    let reason: string;

    if (payload.length >= 2) {
      code = payload.readUInt16BE(0);
      reason = payload.subarray(2).toString('utf8');
    } else {
      code = 1005;
      reason = '';
    }

    if (!sentClose) {
      const closePayload = Buffer.alloc(2);
      closePayload.writeUInt16BE(code);
      writeFrame(socket, 8, closePayload);
      sentClose = true;
    }

    if (reason.length > 0) {
      console.log(`closed ${code} ${reason}`);
    } else {
      console.log(`closed ${code}`);
    }
  }

  async function handleCompleteMessage(opcode: number, payload: Buffer): Promise<void> {
    if (opcode === 1) {
      const text = payload.toString('utf8');

      if (text === 'BYE') {
        const closePayload = Buffer.from([0x03, 0xE8]);
        writeFrame(socket, 8, closePayload);
        sentClose = true;
        return;
      }

      if (text === 'SHA1') {
        sha1Pending = true;
        return;
      }

      if (text.startsWith('ADD ')) {
        const parts = text.substring(4).split(' ');
        const a = BigInt(parts[0]);
        const b = BigInt(parts[1]);
        const sum = a + b;
        const reply = sum.toString();
        writeFrame(socket, 1, Buffer.from(reply, 'utf8'));
        console.log(`${text} -> ${reply}`);
      } else if (text.startsWith('REV ')) {
        const text2 = text.substring(4);
        const reversed = Array.from(text2).reverse().join('');
        writeFrame(socket, 1, Buffer.from(reversed, 'utf8'));
        console.log(`REV ${text2} -> ${reversed}`);
      }
    } else if (opcode === 2) {
      if (sha1Pending) {
        sha1Pending = false;
        const hash = crypto.createHash('sha1').update(payload).digest('hex');
        writeFrame(socket, 1, Buffer.from(hash, 'utf8'));
        console.log(`SHA1 ${payload.length} -> ${hash}`);
      }
    }
  }

  while (true) {
    const frame = await readFrame(bs);
    if (!frame) break;

    switch (frame.opcode) {
      case 0:
        fragments.push(frame.payload);
        if (frame.fin) {
          const fullPayload = Buffer.concat(fragments);
          await handleCompleteMessage(currentOpcode!, fullPayload);
          fragments = [];
          currentOpcode = null;
        }
        break;

      case 1:
      case 2:
        if (frame.fin) {
          await handleCompleteMessage(frame.opcode, frame.payload);
        } else {
          fragments = [frame.payload];
          currentOpcode = frame.opcode;
        }
        break;

      case 8:
        handleClose(frame.payload);
        return;

      case 9:
        writeFrame(socket, 10, frame.payload);
        break;

      case 10:
        break;
    }
  }
}

async function main(): Promise<void> {
  const urls = process.argv.slice(2);
  for (let i = 0; i < urls.length; i++) {
    console.log(`session ${i + 1}`);
    await handleSession(urls[i]);
  }
}

main().then(() => process.exit(0));

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom RNG = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            try {
                handleSession(args[i]);
            } catch (Exception e) {
                // connection error, move on
            }
        }
        System.out.flush();
    }

    static void handleSession(String url) throws Exception {
        String rest = url.substring(5); // remove "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx == -1) {
            hostPort = rest;
            path = "/";
        } else {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        }

        String host;
        int port;
        int colonIdx = hostPort.lastIndexOf(':');
        if (colonIdx == -1) {
            host = hostPort;
            port = 80;
        } else {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        }

        Socket socket = new Socket();
        try {
            socket.connect(new InetSocketAddress(host, port), 30000);
            socket.setTcpNoDelay(true);
            InputStream in = new BufferedInputStream(socket.getInputStream());
            OutputStream out = socket.getOutputStream();

            // Generate Sec-WebSocket-Key
            byte[] keyBytes = new byte[16];
            RNG.nextBytes(keyBytes);
            String key = Base64.getEncoder().encodeToString(keyBytes);

            // Send handshake
            StringBuilder req = new StringBuilder();
            req.append("GET ").append(path).append(" HTTP/1.1\r\n");
            req.append("Host: ").append(host).append(":").append(port).append("\r\n");
            req.append("Upgrade: websocket\r\n");
            req.append("Connection: Upgrade\r\n");
            req.append("Sec-WebSocket-Version: 13\r\n");
            req.append("Sec-WebSocket-Key: ").append(key).append("\r\n");
            req.append("\r\n");
            out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
            out.flush();

            // Read response headers byte-by-byte until \r\n\r\n
            ByteArrayOutputStream headerBuf = new ByteArrayOutputStream();
            int state = 0;
            while (true) {
                int b = in.read();
                if (b == -1) return;
                headerBuf.write(b);
                if (b == '\r') {
                    state = (state == 2) ? 3 : 1;
                } else if (b == '\n') {
                    if (state == 1) state = 2;
                    else if (state == 3) break;
                    else state = 0;
                } else {
                    state = 0;
                }
            }

            String headerBlock = new String(headerBuf.toByteArray(), StandardCharsets.US_ASCII);
            String[] lines = headerBlock.split("\r\n");
            String statusLine = lines[0];
            String[] statusParts = statusLine.split(" ", 3);
            int statusCode = Integer.parseInt(statusParts[1]);
            String reasonPhrase = statusParts.length > 2 ? statusParts[2] : "";

            if (statusCode != 101) {
                System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
                return;
            }

            // Check Sec-WebSocket-Accept
            String accept = null;
            for (int i = 1; i < lines.length; i++) {
                int colon = lines[i].indexOf(':');
                if (colon == -1) continue;
                String name = lines[i].substring(0, colon).trim().toLowerCase();
                String value = lines[i].substring(colon + 1).trim();
                if (name.equals("sec-websocket-accept")) {
                    accept = value;
                }
            }

            String expectedAccept = computeAccept(key);
            if (accept == null || !accept.equals(expectedAccept)) {
                System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                return;
            }

            // Process WebSocket frames
            processFrames(in, out);
        } finally {
            try { socket.close(); } catch (IOException e) {}
        }
    }

    static void processFrames(InputStream in, OutputStream out) throws Exception {
        boolean sentClose = false;
        boolean pendingSHA1 = false;
        int msgOpcode = -1;
        ByteArrayOutputStream msgBuf = new ByteArrayOutputStream();

        while (true) {
            // Read frame header
            int b0 = readByte(in);
            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;

            int b1 = readByte(in);
            boolean masked = (b1 & 0x80) != 0;
            long len = b1 & 0x7F;

            if (len == 126) {
                int b2 = readByte(in);
                int b3 = readByte(in);
                len = ((b2 & 0xFF) << 8) | (b3 & 0xFF);
            } else if (len == 127) {
                len = 0;
                for (int i = 0; i < 8; i++) {
                    len = (len << 8) | (readByte(in) & 0xFF);
                }
            }

            byte[] maskKey = null;
            if (masked) {
                maskKey = readNBytes(in, 4);
            }

            byte[] payload = readNBytes(in, (int) len);

            if (masked && maskKey != null) {
                for (int i = 0; i < payload.length; i++) {
                    payload[i] ^= maskKey[i & 3];
                }
            }

            // Handle frame by opcode
            if (opcode == 8) { // Close
                int code = 1005;
                String reason = "";
                if (payload.length >= 2) {
                    code = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
                    reason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
                }
                if (reason.isEmpty()) {
                    System.out.println("closed " + code);
                } else {
                    System.out.println("closed " + code + " " + reason);
                }
                if (!sentClose) {
                    byte[] cp = new byte[]{(byte) (code >> 8), (byte) (code & 0xFF)};
                    try { sendFrame(out, 8, cp); } catch (IOException e) {}
                }
                return;
            }

            if (opcode == 9) { // Ping
                try { sendFrame(out, 10, payload); } catch (IOException e) {}
                continue;
            }

            if (opcode == 10) { // Pong
                continue;
            }

            // Data frame (0=continuation, 1=text, 2=binary)
            if (opcode != 0) {
                msgOpcode = opcode;
                msgBuf.reset();
            }
            msgBuf.write(payload);

            if (fin) {
                byte[] fullPayload = msgBuf.toByteArray();

                if (pendingSHA1) {
                    pendingSHA1 = false;
                    String hex = sha1Hex(fullPayload);
                    System.out.println("SHA1 " + fullPayload.length + " -> " + hex);
                    try { sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                } else if (msgOpcode == 1) {
                    String cmd = new String(fullPayload, StandardCharsets.UTF_8);
                    if (cmd.equals("BYE")) {
                        byte[] cp = new byte[]{0x03, (byte) 0xE8};
                        try { sendFrame(out, 8, cp); } catch (IOException e) {}
                        sentClose = true;
                    } else if (cmd.startsWith("ADD ")) {
                        String params = cmd.substring(4);
                        int sp = params.indexOf(' ');
                        long a = Long.parseLong(params.substring(0, sp));
                        long b = Long.parseLong(params.substring(sp + 1));
                        long sum = a + b;
                        String reply = Long.toString(sum);
                        System.out.println(cmd + " -> " + reply);
                        try { sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                    } else if (cmd.startsWith("REV ")) {
                        String text = cmd.substring(4);
                        String reversed = reverseCodePoints(text);
                        System.out.println(cmd + " -> " + reversed);
                        try { sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8)); } catch (IOException e) {}
                    } else if (cmd.equals("SHA1")) {
                        pendingSHA1 = true;
                    }
                }
            }
        }
    }

    static int readByte(InputStream in) throws IOException {
        int b = in.read();
        if (b == -1) throw new EOFException();
        return b;
    }

    static byte[] readNBytes(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = in.read(buf, off, n - off);
            if (r == -1) throw new EOFException();
            off += r;
        }
        return buf;
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        // FIN=1, RSV=0, opcode
        buf.write(0x80 | opcode);

        int len = payload.length;
        if (len <= 125) {
            buf.write(0x80 | len);
        } else if (len <= 65535) {
            buf.write(0x80 | 126);
            buf.write((len >> 8) & 0xFF);
            buf.write(len & 0xFF);
        } else {
            buf.write(0x80 | 127);
            long l = len;
            for (int i = 7; i >= 0; i--) {
                buf.write((int) ((l >>> (i * 8)) & 0xFF));
            }
        }

        // Masking key: 4 random bytes, not all zero
        byte[] mk = new byte[4];
        do {
            RNG.nextBytes(mk);
        } while (mk[0] == 0 && mk[1] == 0 && mk[2] == 0 && mk[3] == 0);
        buf.write(mk);

        // Masked payload
        for (int i = 0; i < payload.length; i++) {
            buf.write(payload[i] ^ mk[i & 3]);
        }

        out.write(buf.toByteArray());
        out.flush();
    }

    static String computeAccept(String key) throws Exception {
        String combined = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        byte[] digest = sha1.digest(combined.getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(digest);
    }

    static String sha1Hex(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder(40);
        for (byte b : digest) {
            sb.append(Character.forDigit((b >> 4) & 0xF, 16));
            sb.append(Character.forDigit(b & 0xF, 16));
        }
        return sb.toString();
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        for (int i = 0, j = cps.length - 1; i < j; i++, j--) {
            int tmp = cps[i];
            cps[i] = cps[j];
            cps[j] = tmp;
        }
        return new String(cps, 0, cps.length);
    }
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(p) = self {
            for (k, v) in p { if k == key { return Some(v); } }
        }
        None
    }
    fn as_str(&self) -> Option<&str> { if let Json::Str(s) = self { Some(s) } else { None } }
    fn as_num(&self) -> Option<f64> { if let Json::Num(n) = self { Some(*n) } else { None } }
}

struct JP { s: Vec<char>, p: usize }
impl JP {
    fn new(s: &str) -> Self { JP { s: s.chars().collect(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], ' '|'\t'|'\n'|'\r') { self.p += 1; } }
    fn peek(&self) -> Option<char> { self.s.get(self.p).copied() }
    fn eat(&mut self, c: char) { assert_eq!(self.s[self.p], c); self.p += 1; }
    fn lit(&mut self, w: &str) { for c in w.chars() { self.eat(c); } }
    fn val(&mut self) -> Json {
        self.ws();
        match self.peek().unwrap() {
            '"' => Json::Str(self.str()),
            '{' => self.obj(), '[' => self.arr(),
            't' => { self.lit("true"); Json::Bool(true) }
            'f' => { self.lit("false"); Json::Bool(false) }
            'n' => { self.lit("null"); Json::Null }
            _ => self.num(),
        }
    }
    fn str(&mut self) -> String {
        self.eat('"'); let mut r = String::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            if c == '"' { break; }
            if c == '\\' {
                let e = self.s[self.p]; self.p += 1;
                match e {
                    '"' => r.push('"'), '\\' => r.push('\\'), '/' => r.push('/'),
                    'b' => r.push('\u{0008}'), 'f' => r.push('\u{000C}'),
                    'n' => r.push('\n'), 'r' => r.push('\r'), 't' => r.push('\t'),
                    'u' => {
                        let cp = self.hex4();
                        if (0xD800..=0xDBFF).contains(&cp) {
                            self.eat('\\'); self.eat('u');
                            let cp2 = self.hex4();
                            r.push(char::from_u32(0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)).unwrap());
                        } else { r.push(char::from_u32(cp).unwrap()); }
                    }
                    _ => panic!(),
                }
            } else { r.push(c); }
        }
        r
    }
    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.s[self.p]; self.p += 1;
            v = v * 16 + match c {
                '0'..='9' => c as u32 - '0' as u32,
                'a'..='f' => c as u32 - 'a' as u32 + 10,
                'A'..='F' => c as u32 - 'A' as u32 + 10,
                _ => panic!(),
            };
        }
        v
    }
    fn num(&mut self) -> Json {
        let st = self.p;
        if self.s[self.p] == '-' { self.p += 1; }
        while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; }
        if self.p < self.s.len() && self.s[self.p] == '.' { self.p += 1; while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; } }
        if self.p < self.s.len() && (self.s[self.p] == 'e' || self.s[self.p] == 'E') { self.p += 1; if self.p < self.s.len() && (self.s[self.p] == '+' || self.s[self.p] == '-') { self.p += 1; } while self.p < self.s.len() && self.s[self.p].is_ascii_digit() { self.p += 1; } }
        Json::Num(self.s[st..self.p].iter().collect::<String>().parse().unwrap())
    }
    fn obj(&mut self) -> Json {
        self.eat('{'); let mut p = Vec::new(); self.ws();
        if self.peek() == Some('}') { self.p += 1; return Json::Obj(p); }
        loop {
            self.ws(); let k = self.str(); self.ws(); self.eat(':');
            let v = self.val(); p.push((k, v)); self.ws();
            if self.peek() == Some(',') { self.p += 1; } else { break; }
        }
        self.eat('}'); Json::Obj(p)
    }
    fn arr(&mut self) -> Json {
        self.eat('['); let mut a = Vec::new(); self.ws();
        if self.peek() == Some(']') { self.p += 1; return Json::Arr(a); }
        loop {
            a.push(self.val()); self.ws();
            if self.peek() == Some(',') { self.p += 1; } else { break; }
        }
        self.eat(']'); Json::Arr(a)
    }
}

fn pj(s: &str) -> Json { JP::new(s).val() }

fn es(s: &str) -> String {
    let mut r = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            _ => r.push(c),
        }
    }
    r.push('"'); r
}

fn sv(v: &Json) -> String {
    match v {
        Json::Null => "null".into(),
        Json::Bool(b) => if *b { "true".into() } else { "false".into() },
        Json::Num(n) => if *n == n.floor() && n.abs() < 1e15 { format!("{}", *n as i64) } else { format!("{}", n) },
        Json::Str(s) => es(s),
        Json::Arr(a) => format!("[{}]", a.iter().map(sv).collect::<Vec<_>>().join(",")),
        Json::Obj(o) => format!("{{{}}}", o.iter().map(|(k,v)| format!("{}:{}", es(k), sv(v))).collect::<Vec<_>>().join(",")),
    }
}

fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let d = if data.starts_with(&[0xEF, 0xBB, 0xBF]) { &data[3..] } else { data };
    let t: Vec<char> = String::from_utf8(d.to_vec()).unwrap().chars().collect();
    let mut rs = Vec::new(); let mut r = Vec::new(); let mut f = String::new();
    let mut i = 0; let mut q = false;
    while i < t.len() {
        if q {
            if t[i] == '"' {
                if i + 1 < t.len() && t[i + 1] == '"' { f.push('"'); i += 2; }
                else { q = false; i += 1; }
            } else { f.push(t[i]); i += 1; }
        } else {
            if t[i] == '"' { q = true; i += 1; }
            else if t[i] == ',' { r.push(f.clone()); f.clear(); i += 1; }
            else if t[i] == '\r' && i + 1 < t.len() && t[i + 1] == '\n' {
                r.push(f.clone()); f.clear(); rs.push(r.clone()); r.clear(); i += 2;
            } else { f.push(t[i]); i += 1; }
        }
    }
    if !f.is_empty() || !r.is_empty() { r.push(f); rs.push(r); }
    rs
}

fn http_post(url: &str, key: &str, body: &str) -> (u16, String) {
    let ws = url.strip_prefix("http://").unwrap();
    let (hp, path) = ws.split_once('/').unwrap();
    let (host, port) = if let Some((h, p)) = hp.split_once(':') {
        (h.to_string(), p.parse::<u16>().unwrap())
    } else { (hp.to_string(), 80u16) };
    let req = format!(
        "POST /{}/chat/completions HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        path, hp, key, body.len(), body
    );
    let mut s = TcpStream::connect((host.as_str(), port)).unwrap();
    s.write_all(req.as_bytes()).unwrap(); s.flush().unwrap();
    let mut buf = Vec::new(); let mut tmp = [0u8; 8192];
    loop {
        let n = s.read(&mut tmp).unwrap();
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
        if buf.windows(4).any(|w| w == b"\r\n\r\n") { break; }
    }
    let sp = buf.windows(4).position(|w| w == b"\r\n\r\n").unwrap();
    let hd = String::from_utf8_lossy(&buf[..sp]).to_string();
    let mut bb = buf[sp + 4..].to_vec();
    let st: u16 = hd.lines().next().unwrap().split_whitespace().nth(1).unwrap().parse().unwrap();
    let cl: usize = hd.lines()
        .find(|l| l.to_lowercase().starts_with("content-length:"))
        .map(|l| l.split(':').nth(1).unwrap().trim().parse().unwrap())
        .unwrap_or(0);
    while bb.len() < cl {
        let n = s.read(&mut tmp).unwrap();
        if n == 0 { break; }
        bb.extend_from_slice(&tmp[..n]);
    }
    (st, String::from_utf8(bb).unwrap())
}

fn exec_tool(name: &str, args_str: &str, inv: &[Vec<String>], rates: &Json) -> String {
    match name {
        "inventory_lookup" => {
            let a = pj(args_str);
            let sku = a.get("sku").unwrap().as_str().unwrap();
            for r in &inv[1..] {
                if r[0] == sku {
                    return format!(
                        "{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                        es(sku), es(&r[1]), r[2], es(&r[3]), r[4]
                    );
                }
            }
            format!("{{\"error\":{}}}", es(&format!("unknown sku: {}", sku)))
        }
        "convert_currency" => {
            let a = pj(args_str);
            let amt = a.get("amount_cents").unwrap().as_num().unwrap() as i64;
            let from = a.get("from").unwrap().as_str().unwrap();
            let to = a.get("to").unwrap().as_str().unwrap();
            let r = rates.get("rates").unwrap();
            let rf = r.get(from).unwrap().as_num().unwrap() as i64;
            let rt = r.get(to).unwrap().as_num().unwrap() as i64;
            let conv = (2 * amt * rt + rf) / (2 * rf);
            format!("{{\"amount_cents\":{},\"currency\":{}}}", conv, es(to))
        }
        _ => format!("{{\"error\":{}}}", es(&format!("unknown tool: {}", name))),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let url = &args[2];

    let task = pj(&fs::read_to_string(format!("{}/task.json", dir)).unwrap());
    let api_key = task.get("api_key").unwrap().as_str().unwrap().to_string();
    let model = task.get("model").unwrap().as_str().unwrap().to_string();
    let sys = task.get("system").unwrap().as_str().unwrap().to_string();
    let usr = task.get("user").unwrap().as_str().unwrap().to_string();
    let tools = task.get("tools").unwrap().clone();

    let inv = parse_csv(&fs::read(format!("{}/inventory.csv", dir)).unwrap());
    let rates = pj(&fs::read_to_string(format!("{}/rates.json", dir)).unwrap());

    let mut msgs = vec![
        Json::Obj(vec![("role".into(), Json::Str("system".into())), ("content".into(), Json::Str(sys))]),
        Json::Obj(vec![("role".into(), Json::Str("user".into())), ("content".into(), Json::Str(usr))]),
    ];

    let (mut tp, mut tc, mut tt, mut nr) = (0i64, 0i64, 0i64, 0i64);

    loop {
        let body = sv(&Json::Obj(vec![
            ("model".into(), Json::Str(model.clone())),
            ("messages".into(), Json::Arr(msgs.clone())),
            ("tools".into(), tools.clone()),
            ("tool_choice".into(), Json::Str("auto".into())),
        ]));
        nr += 1;
        let (st, rb) = http_post(url, &api_key, &body);

        if st != 200 {
            let e = pj(&rb);
            println!("ERROR {} {}", st, e.get("error").unwrap().get("message").unwrap().as_str().unwrap());
            process::exit(0);
        }

        let resp = pj(&rb);
        if let Some(u) = resp.get("usage") {
            tp += u.get("prompt_tokens").unwrap().as_num().unwrap() as i64;
            tc += u.get("completion_tokens").unwrap().as_num().unwrap() as i64;
            tt += u.get("total_tokens").unwrap().as_num().unwrap() as i64;
        }

        let choices = resp.get("choices").unwrap();
        let c0 = if let Json::Arr(a) = choices { &a[0] } else { panic!() };
        let msg = c0.get("message").unwrap();
        let fr = c0.get("finish_reason").unwrap().as_str().unwrap();

        if fr == "stop" {
            println!("FINAL {}", msg.get("content").unwrap().as_str().unwrap());
            break;
        }

        let content = msg.get("content");
        if let Some(Json::Str(s)) = content {
            println!("SAY {}", s);
        }

        let tcs = msg.get("tool_calls").unwrap();
        let calls = if let Json::Arr(a) = tcs { a } else { panic!() };

        for c in calls.iter() {
            println!("CALL {} {}",
                c.get("id").unwrap().as_str().unwrap(),
                c.get("function").unwrap().get("name").unwrap().as_str().unwrap());
        }

        let mut am = vec![("role".into(), Json::Str("assistant".into()))];
        am.push(("content".into(), content.cloned().unwrap_or(Json::Null)));
        am.push(("tool_calls".into(), tcs.clone()));
        msgs.push(Json::Obj(am));

        for c in calls.iter() {
            let id = c.get("id").unwrap().as_str().unwrap().to_string();
            let nm = c.get("function").unwrap().get("name").unwrap().as_str().unwrap().to_string();
            let ar = c.get("function").unwrap().get("arguments").unwrap().as_str().unwrap();
            let res = exec_tool(&nm, ar, &inv, &rates);
            println!("RESULT {} {}", id, res);
            msgs.push(Json::Obj(vec![
                ("role".into(), Json::Str("tool".into())),
                ("tool_call_id".into(), Json::Str(id)),
                ("content".into(), Json::Str(res)),
            ]));
        }
    }

    println!("USAGE prompt={} completion={} total={} requests={}", tp, tc, tt, nr);
}

import struct
import sys
import os
import datetime
import calendar


def days_from_civil(y, m, d):
    y -= m <= 2
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def civil_from_days(z):
    z += 719468
    era = (z if z >= 0 else z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    y += 1 if m <= 2 else 0
    return y, m, d


def unix_to_datetime(t):
    days = t // 86400
    rem = t % 86400
    y, m, d = civil_from_days(days)
    h = rem // 3600
    mi = (rem % 3600) // 60
    s = rem % 60
    return y, m, d, h, mi, s


def datetime_to_unix(y, m, d, h, mi, s):
    return days_from_civil(y, m, d) * 86400 + h * 3600 + mi * 60 + s


def format_offset(seconds):
    sign = '+' if seconds >= 0 else '-'
    seconds = abs(seconds)
    h = seconds // 3600
    m = (seconds % 3600) // 60
    s = seconds % 60
    if s != 0:
        return f"{sign}{h:02d}:{m:02d}:{s:02d}"
    else:
        return f"{sign}{h:02d}:{m:02d}"


def format_datetime(y, m, d, h, mi, s):
    return f"{y:04d}-{m:02d}-{d:02d}T{h:02d}:{mi:02d}:{s:02d}"


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = struct.unpack('>6i', data[20:44])
    block1_size = timecnt * 4 + timecnt * 1 + typecnt * 6 + charcnt + leapcnt * 8 + isstdcnt + isutcnt
    pos = 44 + block1_size

    isutcnt2, isstdcnt2, leapcnt2, timecnt2, typecnt2, charcnt2 = struct.unpack('>6i', data[pos+20:pos+44])
    pos += 44

    times = list(struct.unpack(f'>{timecnt2}q', data[pos:pos+timecnt2*8]))
    pos += timecnt2 * 8

    type_indices = list(data[pos:pos+timecnt2])
    pos += timecnt2

    types = []
    for i in range(typecnt2):
        utc_offset = struct.unpack('>i', data[pos:pos+4])[0]
        isdst = data[pos+4]
        abbr_idx = data[pos+5]
        types.append((utc_offset, isdst, abbr_idx))
        pos += 6

    abbrs_data = data[pos:pos+charcnt2]
    pos += charcnt2

    abbrs = []
    for i in range(typecnt2):
        idx = types[i][2]
        end = abbrs_data.index(0, idx)
        abbrs.append(abbrs_data[idx:end].decode('ascii'))

    pos += leapcnt2 * 12 + isstdcnt2 + isutcnt2

    if pos < len(data) and data[pos] == ord('\n'):
        pos += 1
    end = data.index(b'\n', pos)
    tz_string = data[pos:end].decode('ascii')

    return times, type_indices, types, abbrs, tz_string


def parse_posix_tz(tz_string):
    if not tz_string:
        return None

    pos = 0
    s = tz_string

    std_abbr, pos = parse_name(s, pos)
    std_offset, pos = parse_offset(s, pos)

    if pos >= len(s):
        return (std_abbr, std_offset, None, None, None, None)

    dst_abbr, pos = parse_name(s, pos)

    if pos < len(s) and (s[pos] in '+-' or s[pos].isdigit()):
        dst_offset, pos = parse_offset(s, pos)
    else:
        dst_offset = std_offset - 3600

    start_rule = None
    end_rule = None
    if pos < len(s) and s[pos] == ',':
        pos += 1
        start_rule, pos = parse_rule(s, pos)
        if pos < len(s) and s[pos] == ',':
            pos += 1
            end_rule, pos = parse_rule(s, pos)

    return (std_abbr, std_offset, dst_abbr, dst_offset, start_rule, end_rule)


def parse_name(s, pos):
    if pos < len(s) and s[pos] == '<':
        end = s.index('>', pos)
        name = s[pos+1:end]
        return name, end + 1
    else:
        start = pos
        while pos < len(s) and s[pos].isalpha():
            pos += 1
        return s[start:pos], pos


def parse_offset(s, pos):
    sign = 1
    if pos < len(s) and s[pos] == '-':
        sign = -1
        pos += 1
    elif pos < len(s) and s[pos] == '+':
        pos += 1

    h_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    hours = int(s[h_start:pos])

    minutes = 0
    seconds = 0
    if pos < len(s) and s[pos] == ':':
        pos += 1
        m_start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        minutes = int(s[m_start:pos])
        if pos < len(s) and s[pos] == ':':
            pos += 1
            sec_start = pos
            while pos < len(s) and s[pos].isdigit():
                pos += 1
            seconds = int(s[sec_start:pos])

    return sign * (hours * 3600 + minutes * 60 + seconds), pos


def parse_rule(s, pos):
    assert s[pos] == 'M'
    pos += 1
    m_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    month = int(s[m_start:pos])
    pos += 1
    w_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    week = int(s[w_start:pos])
    pos += 1
    d_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    day = int(s[d_start:pos])

    time_seconds = 2 * 3600
    if pos < len(s) and s[pos] == '/':
        pos += 1
        time_seconds, pos = parse_offset(s, pos)

    return (month, week, day, time_seconds), pos


def nth_weekday_of_month(year, month, day_of_week, week):
    py_dow = (day_of_week - 1) % 7
    first = datetime.date(year, month, 1)
    first_py_dow = first.weekday()
    days_ahead = (py_dow - first_py_dow) % 7
    first_occurrence = 1 + days_ahead

    if week <= 4:
        return first_occurrence + (week - 1) * 7
    else:
        last_day = calendar.monthrange(year, month)[1]
        last_date = datetime.date(year, month, last_day)
        last_py_dow = last_date.weekday()
        days_back = (last_py_dow - py_dow) % 7
        return last_day - days_back


def compute_transition_time(year, rule, tz_offset):
    month, week, day, time_seconds = rule
    day_of_month = nth_weekday_of_month(year, month, day, week)
    base = datetime_to_unix(year, month, day_of_month, 0, 0, 0)
    wall_secs = base + time_seconds
    return wall_secs + tz_offset


class TimeZone:
    def __init__(self, filepath):
        self.times, self.type_indices, self.types, self.abbrs, self.tz_string = parse_tzif(filepath)
        self.footer = parse_posix_tz(self.tz_string)

    def get_type_at(self, t):
        if not self.times or t < self.times[0]:
            offset, isdst, _ = self.types[0]
            return offset, isdst, self.abbrs[0]

        if t > self.times[-1]:
            return self._get_footer_type(t)

        lo, hi = 0, len(self.times) - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if self.times[mid] <= t:
                lo = mid
            else:
                hi = mid - 1

        type_idx = self.type_indices[lo]
        offset, isdst, _ = self.types[type_idx]
        return offset, isdst, self.abbrs[type_idx]

    def _get_footer_type(self, t):
        if self.footer is None:
            offset, isdst, _ = self.types[0]
            return offset, isdst, self.abbrs[0]

        std_abbr, std_offset, dst_abbr, dst_offset, start_rule, end_rule = self.footer

        if dst_abbr is None or start_rule is None:
            return -std_offset, 0, std_abbr

        y, m, d, h, mi, s = unix_to_datetime(t)
        year = y

        t_start = compute_transition_time(year, start_rule, std_offset)
        t_end = compute_transition_time(year, end_rule, dst_offset)

        if t_start < t_end:
            if t_start <= t < t_end:
                return -dst_offset, 1, dst_abbr
            else:
                return -std_offset, 0, std_abbr
        elif t_start > t_end:
            if t >= t_start or t < t_end:
                return -dst_offset, 1, dst_abbr
            else:
                return -std_offset, 0, std_abbr
        else:
            return -std_offset, 0, std_abbr

    def get_all_offsets(self):
        offsets = set()
        for offset, isdst, _ in self.types:
            offsets.add(offset)
        if self.footer:
            std_abbr, std_offset, dst_abbr, dst_offset, _, _ = self.footer
            offsets.add(-std_offset)
            if dst_abbr is not None:
                offsets.add(-dst_offset)
        return offsets

    def find_gap_transition(self, w_unix):
        for i in range(len(self.times)):
            t = self.times[i]
            if i == 0:
                offset_before = self.types[0][0]
            else:
                prev_idx = self.type_indices[i - 1]
                offset_before = self.types[prev_idx][0]
            cur_idx = self.type_indices[i]
            offset_after = self.types[cur_idx][0]
            if offset_after > offset_before:
                if t + offset_before <= w_unix < t + offset_after:
                    return (t, offset_before, offset_after)

        if self.footer and self.times:
            std_abbr, std_offset, dst_abbr, dst_offset, start_rule, end_rule = self.footer
            if dst_abbr is not None and start_rule is not None:
                y, _, _, _, _, _ = unix_to_datetime(w_unix)
                for year in [y - 1, y, y + 1]:
                    t_start = compute_transition_time(year, start_rule, std_offset)
                    t_end = compute_transition_time(year, end_rule, dst_offset)

                    if t_start > self.times[-1]:
                        off_before = -std_offset
                        off_after = -dst_offset
                        if off_after > off_before and t_start + off_before <= w_unix < t_start + off_after:
                            return (t_start, off_before, off_after)

                    if t_end > self.times[-1]:
                        off_before = -dst_offset
                        off_after = -std_offset
                        if off_after > off_before and t_end + off_before <= w_unix < t_end + off_after:
                            return (t_end, off_before, off_after)

        return None


def solve():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    with open(os.path.join(dir_path, 'queries.txt'), 'r') as f:
        lines = f.read().splitlines()

    tz_cache = {}

    def get_tz(filename):
        if filename not in tz_cache:
            tz_cache[filename] = TimeZone(os.path.join(dir_path, filename))
        return tz_cache[filename]

    results = []

    for line in lines:
        if not line.strip():
            continue

        parts = line.split(' ')
        query_type = parts[0]
        filename = parts[1]
        tz = get_tz(filename)

        if query_type == 'UTC':
            t = int(parts[2])
            offset, isdst, abbr = tz.get_type_at(t)
            local_t = t + offset
            y, m, d, h, mi, s = unix_to_datetime(local_t)
            local_str = format_datetime(y, m, d, h, mi, s)
            offset_str = format_offset(offset)
            results.append(f"{line} -> {local_str}{offset_str} {abbr}")

        elif query_type == 'LOCAL':
            time_str = parts[2]
            y = int(time_str[0:4])
            m = int(time_str[5:7])
            d = int(time_str[8:10])
            h = int(time_str[11:13])
            mi = int(time_str[14:16])
            s = int(time_str[17:19])
            w_unix = datetime_to_unix(y, m, d, h, mi, s)

            solutions = []
            for off in tz.get_all_offsets():
                t = w_unix - off
                actual_offset, isdst, abbr = tz.get_type_at(t)
                if actual_offset == off:
                    solutions.append((t, off, abbr))

            solutions.sort()

            if len(solutions) == 1:
                t, off, abbr = solutions[0]
                results.append(f"{line} -> {t} {format_offset(off)} {abbr}")
            elif len(solutions) >= 2:
                t1, off1, abbr1 = solutions[0]
                t2, off2, abbr2 = solutions[1]
                results.append(f"{line} -> {t1} {format_offset(off1)} {abbr1} | {t2} {format_offset(off2)} {abbr2}")
            else:
                gap = tz.find_gap_transition(w_unix)
                if gap:
                    T, off_before, off_after = gap
                    t = w_unix - off_before
                    actual_offset, isdst, abbr = tz.get_type_at(t)
                    local_t = t + actual_offset
                    ly, lm, ld, lh, lmi, ls = unix_to_datetime(local_t)
                    local_str = format_datetime(ly, lm, ld, lh, lmi, ls)
                    offset_str = format_offset(actual_offset)
                    results.append(f"{line} -> GAP {t} {local_str}{offset_str} {abbr}")
                else:
                    results.append(f"{line} -> GAP 0 1970-01-01T00:00:00+00:00 UTC")

    for r in results:
        print(r)


if __name__ == '__main__':
    solve()

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.time.*;

public class Main {
    static class TzifData {
        long[] transitionTimes;
        byte[] typeIndices;
        int[] offsets;
        boolean[] isDST;
        String[] abbrevs;
        String posixTZ;
        String stdName, dstName;
        int stdUTCOffset, dstUTCOffset;
        boolean hasDST;
        int startMonth, startWeek, startDay, startSec;
        int endMonth, endWeek, endDay, endSec;
    }

    static class TzInfo {
        int offset;
        String abbr;
        boolean isDST;
        TzInfo(int o, String a, boolean d) { offset = o; abbr = a; isDST = d; }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> queries = new ArrayList<>();
        for (String line : Files.readAllLines(Paths.get(dir, "queries.txt"))) {
            if (!line.trim().isEmpty()) queries.add(line);
        }

        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder sb = new StringBuilder();

        for (String query : queries) {
            String[] parts = query.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData data = cache.computeIfAbsent(fileName, f -> {
                try { return parseTzif(Paths.get(dir, f)); }
                catch (Exception e) { throw new RuntimeException(e); }
            });

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                sb.append(handleUTC(query, data, t)).append("\n");
            } else {
                String wallStr = parts[2];
                sb.append(handleLocal(query, data, wallStr)).append("\n");
            }
        }

        System.out.print(sb.toString());
    }

    static TzifData parseTzif(Path path) throws Exception {
        byte[] raw = Files.readAllBytes(path);
        ByteBuffer buf = ByteBuffer.wrap(raw);

        // First header: 44 bytes
        buf.position(0);
        buf.position(4); // skip magic
        buf.get(); // version
        buf.position(20); // skip 15 unused
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();

        // Skip first data block
        int block1Size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1
                + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(44 + block1Size);

        // Second header: 44 bytes
        buf.position(buf.position() + 4); // skip magic
        buf.get(); // version
        buf.position(buf.position() + 15); // skip 15 unused
        int isutcnt2 = buf.getInt();
        int isstdcnt2 = buf.getInt();
        int leapcnt2 = buf.getInt();
        int timecnt2 = buf.getInt();
        int typecnt2 = buf.getInt();
        int charcnt2 = buf.getInt();

        // Second data block
        long[] transitionTimes = new long[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            transitionTimes[i] = buf.getLong();
        }
        byte[] typeIndices = new byte[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            typeIndices[i] = buf.get();
        }
        int[] offsets = new int[typecnt2];
        boolean[] isDST = new boolean[typecnt2];
        int[] abbrIdx = new int[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            offsets[i] = buf.getInt();
            isDST[i] = buf.get() != 0;
            abbrIdx[i] = buf.get() & 0xFF;
        }
        byte[] chars = new byte[charcnt2];
        buf.get(chars);
        String[] abbrevs = new String[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            int start = abbrIdx[i];
            int end = start;
            while (end < chars.length && chars[end] != 0) end++;
            abbrevs[i] = new String(chars, start, end - start, "ASCII");
        }
        // Skip leap seconds, isstd, isut
        buf.position(buf.position() + leapcnt2 * 12 + isstdcnt2 + isutcnt2);

        // Footer: \n + POSIX TZ string + \n
        if (buf.remaining() > 0 && buf.get() == '\n') {}
        StringBuilder posix = new StringBuilder();
        while (buf.remaining() > 0) {
            byte b = buf.get();
            if (b == '\n') break;
            posix.append((char) b);
        }

        TzifData data = new TzifData();
        data.transitionTimes = transitionTimes;
        data.typeIndices = typeIndices;
        data.offsets = offsets;
        data.isDST = isDST;
        data.abbrevs = abbrevs;
        data.posixTZ = posix.toString();
        parsePosix(data);
        return data;
    }

    static void parsePosix(TzifData data) {
        String s = data.posixTZ;
        if (s.isEmpty()) {
            data.hasDST = false;
            data.stdName = "";
            data.stdUTCOffset = 0;
            return;
        }
        int pos = 0;
        data.hasDST = false;

        pos = parseName(s, pos, data, true);
        pos = parseOffset(s, pos, data, true);

        if (pos < s.length() && s.charAt(pos) != ',') {
            pos = parseName(s, pos, data, false);
            if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
                pos = parseOffset(s, pos, data, false);
            } else {
                data.dstUTCOffset = data.stdUTCOffset + 3600;
            }
            data.hasDST = true;

            if (pos < s.length() && s.charAt(pos) == ',') {
                pos++;
                pos = parseRule(s, pos, data, true);
                if (pos < s.length() && s.charAt(pos) == ',') {
                    pos++;
                    pos = parseRule(s, pos, data, false);
                }
            }
        }
    }

    static int parseName(String s, int pos, TzifData data, boolean isStd) {
        if (pos < s.length() && s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            String name = s.substring(pos + 1, end);
            if (isStd) data.stdName = name; else data.dstName = name;
            return end + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            String name = s.substring(start, pos);
            if (isStd) data.stdName = name; else data.dstName = name;
            return pos;
        }
    }

    static int parseOffset(String s, int pos, TzifData data, boolean isStd) {
        int sign = 1;
        if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) {
            if (s.charAt(pos) == '-') sign = -1;
            pos++;
        }
        int hours = 0, mins = 0, secs = 0;
        int start = pos;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
        hours = Integer.parseInt(s.substring(start, pos));
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            mins = Integer.parseInt(s.substring(start, pos));
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                start = pos;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                secs = Integer.parseInt(s.substring(start, pos));
            }
        }
        int totalSec = sign * (hours * 3600 + mins * 60 + secs);
        int utcOffset = -totalSec;
        if (isStd) data.stdUTCOffset = utcOffset;
        else data.dstUTCOffset = utcOffset;
        return pos;
    }

    static int parseRule(String s, int pos, TzifData data, boolean isStart) {
        if (pos < s.length() && s.charAt(pos) == 'M') {
            pos++;
            int start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int month = Integer.parseInt(s.substring(start, pos));
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int week = Integer.parseInt(s.substring(start, pos));
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int day = Integer.parseInt(s.substring(start, pos));

            int timeSec = 2 * 3600;
            if (pos < s.length() && s.charAt(pos) == '/') {
                pos++;
                int sign = 1;
                if (s.charAt(pos) == '+' || s.charAt(pos) == '-') {
                    if (s.charAt(pos) == '-') sign = -1;
                    pos++;
                }
                start = pos;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                int h = Integer.parseInt(s.substring(start, pos));
                int m = 0, sec = 0;
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    start = pos;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                    m = Integer.parseInt(s.substring(start, pos));
                    if (pos < s.length() && s.charAt(pos) == ':') {
                        pos++;
                        start = pos;
                        while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                        sec = Integer.parseInt(s.substring(start, pos));
                    }
                }
                timeSec = sign * (h * 3600 + m * 60 + sec);
            }

            if (isStart) {
                data.startMonth = month; data.startWeek = week;
                data.startDay = day; data.startSec = timeSec;
            } else {
                data.endMonth = month; data.endWeek = week;
                data.endDay = day; data.endSec = timeSec;
            }
        }
        return pos;
    }

    static TzInfo getInfoAt(TzifData data, long t) {
        if (data.transitionTimes.length == 0) {
            return getInfoFromPosix(data, t);
        }
        if (t < data.transitionTimes[0]) {
            return new TzInfo(data.offsets[0], data.abbrevs[0], data.isDST[0]);
        }
        if (t >= data.transitionTimes[data.transitionTimes.length - 1]) {
            return getInfoFromPosix(data, t);
        }
        int lo = 0, hi = data.transitionTimes.length - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (data.transitionTimes[mid] <= t) lo = mid;
            else hi = mid - 1;
        }
        int typeIdx = data.typeIndices[lo] & 0xFF;
        return new TzInfo(data.offsets[typeIdx], data.abbrevs[typeIdx], data.isDST[typeIdx]);
    }

    static TzInfo getInfoFromPosix(TzifData data, long t) {
        if (!data.hasDST) {
            return new TzInfo(data.stdUTCOffset, data.stdName, false);
        }
        int year = (int)(t / (365.25 * 86400) + 1970);
        for (int y = year - 1; y <= year + 1; y++) {
            long startUTC = computeStartUTC(data, y);
            long endUTC = computeEndUTC(data, y);
            if (startUTC <= endUTC) {
                if (t >= startUTC && t < endUTC) {
                    return new TzInfo(data.dstUTCOffset, data.dstName, true);
                }
            } else {
                if (t >= startUTC || t < endUTC) {
                    return new TzInfo(data.dstUTCOffset, data.dstName, true);
                }
            }
        }
        return new TzInfo(data.stdUTCOffset, data.stdName, false);
    }

    static long computeStartUTC(TzifData data, int year) {
        LocalDate date = findDate(year, data.startMonth, data.startWeek, data.startDay);
        long dateEpoch = date.toEpochDay() * 86400;
        return dateEpoch + data.startSec - data.stdUTCOffset;
    }

    static long computeEndUTC(TzifData data, int year) {
        LocalDate date = findDate(year, data.endMonth, data.endWeek, data.endDay);
        long dateEpoch = date.toEpochDay() * 86400;
        return dateEpoch + data.endSec - data.dstUTCOffset;
    }

    static LocalDate findDate(int year, int month, int week, int day) {
        LocalDate first = LocalDate.of(year, month, 1);
        int targetJavaDay = (day == 0) ? 7 : day;
        int firstJavaDay = first.getDayOfWeek().getValue();
        int diff = (targetJavaDay - firstJavaDay + 7) % 7;
        LocalDate firstOccurrence = first.plusDays(diff);
        if (week == 5) {
            LocalDate lastDayOfMonth = first.plusMonths(1).minusDays(1);
            int lastJavaDay = lastDayOfMonth.getDayOfWeek().getValue();
            int diff2 = (lastJavaDay - targetJavaDay + 7) % 7;
            return lastDayOfMonth.minusDays(diff2);
        } else {
            return firstOccurrence.plusDays((long)(week - 1) * 7);
        }
    }

    static String handleUTC(String query, TzifData data, long t) {
        TzInfo info = getInfoAt(data, t);
        long localSecs = t + info.offset;
        String localStr = secondsToWall(localSecs);
        String offsetStr = formatOffset(info.offset);
        return query + " -> " + localStr + offsetStr + " " + info.abbr;
    }

    static String handleLocal(String query, TzifData data, String wallStr) {
        long W = wallToSeconds(wallStr);

        Set<Integer> offsetsToTry = new TreeSet<>();
        for (int o : data.offsets) offsetsToTry.add(o);
        offsetsToTry.add(data.stdUTCOffset);
        if (data.hasDST) offsetsToTry.add(data.dstUTCOffset);

        List<Object[]> validSolutions = new ArrayList<>();

        for (int o : offsetsToTry) {
            long t = W - o;
            TzInfo info = getInfoAt(data, t);
            if (info.offset == o) {
                boolean dup = false;
                for (Object[] sol : validSolutions) {
                    if ((long) sol[0] == t) { dup = true; break; }
                }
                if (!dup) {
                    validSolutions.add(new Object[]{t, info});
                }
            }
        }

        validSolutions.sort((a, b) -> Long.compare((long) a[0], (long) b[0]));

        if (validSolutions.size() == 1) {
            long t = (long) validSolutions.get(0)[0];
            TzInfo info = (TzInfo) validSolutions.get(0)[1];
            return query + " -> " + t + " " + formatOffset(info.offset) + " " + info.abbr;
        } else if (validSolutions.size() >= 2) {
            long t1 = (long) validSolutions.get(0)[0];
            TzInfo i1 = (TzInfo) validSolutions.get(0)[1];
            long t2 = (long) validSolutions.get(1)[0];
            TzInfo i2 = (TzInfo) validSolutions.get(1)[1];
            return query + " -> " + t1 + " " + formatOffset(i1.offset) + " " + i1.abbr
                    + " | " + t2 + " " + formatOffset(i2.offset) + " " + i2.abbr;
        } else {
            return handleGap(query, data, W);
        }
    }

    static String handleGap(String query, TzifData data, long W) {
        // Check TZif transitions
        for (int i = 0; i < data.transitionTimes.length; i++) {
            long T = data.transitionTimes[i];
            int oldTypeIdx, newTypeIdx;
            if (i == 0) {
                oldTypeIdx = 0;
            } else {
                oldTypeIdx = data.typeIndices[i - 1] & 0xFF;
            }
            newTypeIdx = data.typeIndices[i] & 0xFF;
            int oldOffset = data.offsets[oldTypeIdx];
            int newOffset = data.offsets[newTypeIdx];

            if (newOffset > oldOffset) {
                long gapStart = T + oldOffset;
                long gapEnd = T + newOffset;
                if (W >= gapStart && W < gapEnd) {
                    long t = W - oldOffset;
                    TzInfo info = getInfoAt(data, t);
                    String localStr = secondsToWall(t + info.offset);
                    String offsetStr = formatOffset(info.offset);
                    return query + " -> GAP " + t + " " + localStr + offsetStr + " " + info.abbr;
                }
            }
        }

        // Check POSIX TZ transitions (only for times >= last TZif transition)
        if (data.hasDST) {
            long lastT = data.transitionTimes.length > 0
                    ? data.transitionTimes[data.transitionTimes.length - 1] : Long.MIN_VALUE;
            int year = (int)(W / (365.25 * 86400) + 1970);
            for (int y = year - 1; y <= year + 1; y++) {
                long startUTC = computeStartUTC(data, y);
                if (startUTC < lastT) continue;
                long gapStart = startUTC + data.stdUTCOffset;
                long gapEnd = startUTC + data.dstUTCOffset;
                if (data.dstUTCOffset > data.stdUTCOffset && W >= gapStart && W < gapEnd) {
                    long t = W - data.stdUTCOffset;
                    TzInfo info = getInfoAt(data, t);
                    String localStr = secondsToWall(t + info.offset);
                    String offsetStr = formatOffset(info.offset);
                    return query + " -> GAP " + t + " " + localStr + offsetStr + " " + info.abbr;
                }
            }
        }

        // Fallback (should not happen with valid input)
        return query + " -> GAP 0 1970-01-01T00:00:00+00:00 ?";
    }

    static long wallToSeconds(String s) {
        LocalDate date = LocalDate.parse(s.substring(0, 10));
        int h = Integer.parseInt(s.substring(11, 13));
        int m = Integer.parseInt(s.substring(14, 16));
        int sec = Integer.parseInt(s.substring(17, 19));
        return date.toEpochDay() * 86400L + h * 3600L + m * 60L + sec;
    }

    static String secondsToWall(long secs) {
        long epochDay = Math.floorDiv(secs, 86400);
        int rem = (int)(secs - epochDay * 86400);
        LocalDate date = LocalDate.ofEpochDay(epochDay);
        int h = rem / 3600;
        int m = (rem % 3600) / 60;
        int s = rem % 60;
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d",
                date.getYear(), date.getMonthValue(), date.getDayOfMonth(), h, m, s);
    }

    static String formatOffset(int offset) {
        if (offset == 0) return "+00:00";
        char sign = offset >= 0 ? '+' : '-';
        int abs = Math.abs(offset);
        int h = abs / 3600;
        int m = (abs % 3600) / 60;
        int s = abs % 60;
        if (s != 0) {
            return String.format("%c%02d:%02d:%02d", sign, h, m, s);
        } else {
            return String.format("%c%02d:%02d", sign, h, m);
        }
    }
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import java.time.*;

public class Main {
    static class TzifData {
        long[] transitionTimes;
        byte[] typeIndices;
        int[] offsets;
        boolean[] isDST;
        String[] abbrevs;
        String posixTZ;
        String stdName, dstName;
        int stdUTCOffset, dstUTCOffset;
        boolean hasDST;
        int startMonth, startWeek, startDay, startSec;
        int endMonth, endWeek, endDay, endSec;
    }

    static class TzInfo {
        int offset;
        String abbr;
        boolean isDST;
        TzInfo(int o, String a, boolean d) { offset = o; abbr = a; isDST = d; }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> queries = new ArrayList<>();
        for (String line : Files.readAllLines(Paths.get(dir, "queries.txt"))) {
            if (!line.trim().isEmpty()) queries.add(line);
        }

        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder sb = new StringBuilder();

        for (String query : queries) {
            String[] parts = query.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData data = cache.computeIfAbsent(fileName, f -> {
                try { return parseTzif(Paths.get(dir, f)); }
                catch (Exception e) { throw new RuntimeException(e); }
            });

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                sb.append(handleUTC(query, data, t)).append("\n");
            } else {
                String wallStr = parts[2];
                sb.append(handleLocal(query, data, wallStr)).append("\n");
            }
        }

        System.out.print(sb.toString());
    }

    static TzifData parseTzif(Path path) throws Exception {
        byte[] raw = Files.readAllBytes(path);
        ByteBuffer buf = ByteBuffer.wrap(raw);

        buf.position(0);
        buf.position(4);
        buf.get();
        buf.position(20);
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();

        int block1Size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1
                + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(44 + block1Size);

        buf.position(buf.position() + 4);
        buf.get();
        buf.position(buf.position() + 15);
        int isutcnt2 = buf.getInt();
        int isstdcnt2 = buf.getInt();
        int leapcnt2 = buf.getInt();
        int timecnt2 = buf.getInt();
        int typecnt2 = buf.getInt();
        int charcnt2 = buf.getInt();

        long[] transitionTimes = new long[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            transitionTimes[i] = buf.getLong();
        }
        byte[] typeIndices = new byte[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            typeIndices[i] = buf.get();
        }
        int[] offsets = new int[typecnt2];
        boolean[] isDST = new boolean[typecnt2];
        int[] abbrIdx = new int[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            offsets[i] = buf.getInt();
            isDST[i] = buf.get() != 0;
            abbrIdx[i] = buf.get() & 0xFF;
        }
        byte[] chars = new byte[charcnt2];
        buf.get(chars);
        String[] abbrevs = new String[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            int start = abbrIdx[i];
            int end = start;
            while (end < chars.length && chars[end] != 0) end++;
            abbrevs[i] = new String(chars, start, end - start, "ASCII");
        }
        buf.position(buf.position() + leapcnt2 * 12 + isstdcnt2 + isutcnt2);

        if (buf.remaining() > 0 && buf.get() == '\n') {}
        StringBuilder posix = new StringBuilder();
        while (buf.remaining() > 0) {
            byte b = buf.get();
            if (b == '\n') break;
            posix.append((char) b);
        }

        TzifData data = new TzifData();
        data.transitionTimes = transitionTimes;
        data.typeIndices = typeIndices;
        data.offsets = offsets;
        data.isDST = isDST;
        data.abbrevs = abbrevs;
        data.posixTZ = posix.toString();
        parsePosix(data);
        return data;
    }

    static void parsePosix(TzifData data) {
        String s = data.posixTZ;
        if (s.isEmpty()) {
            data.hasDST = false;
            data.stdName = "";
            data.stdUTCOffset = 0;
            return;
        }
        int pos = 0;
        data.hasDST = false;

        pos = parseName(s, pos, data, true);
        pos = parseOffset(s, pos, data, true);

        if (pos < s.length() && s.charAt(pos) != ',') {
            pos = parseName(s, pos, data, false);
            if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
                pos = parseOffset(s, pos, data, false);
            } else {
                data.dstUTCOffset = data.stdUTCOffset + 3600;
            }
            data.hasDST = true;

            if (pos < s.length() && s.charAt(pos) == ',') {
                pos++;
                pos = parseRule(s, pos, data, true);
                if (pos < s.length() && s.charAt(pos) == ',') {
                    pos++;
                    pos = parseRule(s, pos, data, false);
                }
            }
        }
    }

    static int parseName(String s, int pos, TzifData data, boolean isStd) {
        if (pos < s.length() && s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            String name = s.substring(pos + 1, end);
            if (isStd) data.stdName = name; else data.dstName = name;
            return end + 1;
        } else {
            int start = pos;
            while (pos < s.length() && Character.isLetter(s.charAt(pos))) pos++;
            String name = s.substring(start, pos);
            if (isStd) data.stdName = name; else data.dstName = name;
            return pos;
        }
    }

    static int parseOffset(String s, int pos, TzifData data, boolean isStd) {
        int sign = 1;
        if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) {
            if (s.charAt(pos) == '-') sign = -1;
            pos++;
        }
        int hours = 0, mins = 0, secs = 0;
        int start = pos;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
        hours = Integer.parseInt(s.substring(start, pos));
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            mins = Integer.parseInt(s.substring(start, pos));
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                start = pos;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                secs = Integer.parseInt(s.substring(start, pos));
            }
        }
        int totalSec = sign * (hours * 3600 + mins * 60 + secs);
        int utcOffset = -totalSec;
        if (isStd) data.stdUTCOffset = utcOffset;
        else data.dstUTCOffset = utcOffset;
        return pos;
    }

    static int parseRule(String s, int pos, TzifData data, boolean isStart) {
        if (pos < s.length() && s.charAt(pos) == 'M') {
            pos++;
            int start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int month = Integer.parseInt(s.substring(start, pos));
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int week = Integer.parseInt(s.substring(start, pos));
            pos++;
            start = pos;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            int day = Integer.parseInt(s.substring(start, pos));

            int timeSec = 2 * 3600;
            if (pos < s.length() && s.charAt(pos) == '/') {
                pos++;
                int sign = 1;
                if (s.charAt(pos) == '+' || s.charAt(pos) == '-') {
                    if (s.charAt(pos) == '-') sign = -1;
                    pos++;
                }
                start = pos;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                int h = Integer.parseInt(s.substring(start, pos));
                int m = 0, sec = 0;
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    start = pos;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                    m = Integer.parseInt(s.substring(start, pos));
                    if (pos < s.length() && s.charAt(pos) == ':') {
                        pos++;
                        start = pos;
                        while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
                        sec = Integer.parseInt(s.substring(start, pos));
                    }
                }
                timeSec = sign * (h * 3600 + m * 60 + sec);
            }

            if (isStart) {
                data.startMonth = month; data.startWeek = week;
                data.startDay = day; data.startSec = timeSec;
            } else {
                data.endMonth = month; data.endWeek = week;
                data.endDay = day; data.endSec = timeSec;
            }
        }
        return pos;
    }

    static TzInfo getInfoAt(TzifData data, long t) {
        if (data.transitionTimes.length == 0) {
            return getInfoFromPosix(data, t);
        }
        if (t < data.transitionTimes[0]) {
            return new TzInfo(data.offsets[0], data.abbrevs[0], data.isDST[0]);
        }
        if (t > data.transitionTimes[data.transitionTimes.length - 1]) {
            return getInfoFromPosix(data, t);
        }
        int lo = 0, hi = data.transitionTimes.length - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (data.transitionTimes[mid] <= t) lo = mid;
            else hi = mid - 1;
        }
        int typeIdx = data.typeIndices[lo] & 0xFF;
        return new TzInfo(data.offsets[typeIdx], data.abbrevs[typeIdx], data.isDST[typeIdx]);
    }

    static TzInfo getInfoFromPosix(TzifData data, long t) {
        if (!data.hasDST) {
            return new TzInfo(data.stdUTCOffset, data.stdName, false);
        }
        int year = (int)(t / (365.25 * 86400) + 1970);
        for (int y = year - 1; y <= year + 1; y++) {
            long startUTC = computeStartUTC(data, y);
            long endUTC = computeEndUTC(data, y);
            if (startUTC <= endUTC) {
                if (t >= startUTC && t < endUTC) {
                    return new TzInfo(data.dstUTCOffset, data.dstName, true);
                }
            } else {
                long endUTCNext = computeEndUTC(data, y + 1);
                if (t >= startUTC && t < endUTCNext) {
                    return new TzInfo(data.dstUTCOffset, data.dstName, true);
                }
            }
        }
        return new TzInfo(data.stdUTCOffset, data.stdName, false);
    }

    static long computeStartUTC(TzifData data, int year) {
        LocalDate date = findDate(year, data.startMonth, data.startWeek, data.startDay);
        long dateEpoch = date.toEpochDay() * 86400;
        return dateEpoch + data.startSec - data.stdUTCOffset;
    }

    static long computeEndUTC(TzifData data, int year) {
        LocalDate date = findDate(year, data.endMonth, data.endWeek, data.endDay);
        long dateEpoch = date.toEpochDay() * 86400;
        return dateEpoch + data.endSec - data.dstUTCOffset;
    }

    static LocalDate findDate(int year, int month, int week, int day) {
        LocalDate first = LocalDate.of(year, month, 1);
        int targetJavaDay = (day == 0) ? 7 : day;
        int firstJavaDay = first.getDayOfWeek().getValue();
        int diff = (targetJavaDay - firstJavaDay + 7) % 7;
        LocalDate firstOccurrence = first.plusDays(diff);
        if (week == 5) {
            LocalDate lastDayOfMonth = first.plusMonths(1).minusDays(1);
            int lastJavaDay = lastDayOfMonth.getDayOfWeek().getValue();
            int diff2 = (lastJavaDay - targetJavaDay + 7) % 7;
            return lastDayOfMonth.minusDays(diff2);
        } else {
            return firstOccurrence.plusDays((long)(week - 1) * 7);
        }
    }

    static String handleUTC(String query, TzifData data, long t) {
        TzInfo info = getInfoAt(data, t);
        long localSecs = t + info.offset;
        String localStr = secondsToWall(localSecs);
        String offsetStr = formatOffset(info.offset);
        return query + " -> " + localStr + offsetStr + " " + info.abbr;
    }

    static String handleLocal(String query, TzifData data, String wallStr) {
        long W = wallToSeconds(wallStr);

        Set<Integer> offsetsToTry = new TreeSet<>();
        for (int o : data.offsets) offsetsToTry.add(o);
        offsetsToTry.add(data.stdUTCOffset);
        if (data.hasDST) offsetsToTry.add(data.dstUTCOffset);

        List<Object[]> validSolutions = new ArrayList<>();

        for (int o : offsetsToTry) {
            long t = W - o;
            TzInfo info = getInfoAt(data, t);
            if (info.offset == o) {
                boolean dup = false;
                for (Object[] sol : validSolutions) {
                    if ((long) sol[0] == t) { dup = true; break; }
                }
                if (!dup) {
                    validSolutions.add(new Object[]{t, info});
                }
            }
        }

        validSolutions.sort((a, b) -> Long.compare((long) a[0], (long) b[0]));

        if (validSolutions.size() == 1) {
            long t = (long) validSolutions.get(0)[0];
            TzInfo info = (TzInfo) validSolutions.get(0)[1];
            return query + " -> " + t + " " + formatOffset(info.offset) + " " + info.abbr;
        } else if (validSolutions.size() >= 2) {
            long t1 = (long) validSolutions.get(0)[0];
            TzInfo i1 = (TzInfo) validSolutions.get(0)[1];
            long t2 = (long) validSolutions.get(1)[0];
            TzInfo i2 = (TzInfo) validSolutions.get(1)[1];
            return query + " -> " + t1 + " " + formatOffset(i1.offset) + " " + i1.abbr
                    + " | " + t2 + " " + formatOffset(i2.offset) + " " + i2.abbr;
        } else {
            return handleGap(query, data, W);
        }
    }

    static String handleGap(String query, TzifData data, long W) {
        // Check TZif transitions
        for (int i = 0; i < data.transitionTimes.length; i++) {
            long T = data.transitionTimes[i];
            int oldTypeIdx, newTypeIdx;
            if (i == 0) {
                oldTypeIdx = 0;
            } else {
                oldTypeIdx = data.typeIndices[i - 1] & 0xFF;
            }
            newTypeIdx = data.typeIndices[i] & 0xFF;
            int oldOffset = data.offsets[oldTypeIdx];
            int newOffset = data.offsets[newTypeIdx];

            if (newOffset > oldOffset) {
                long gapStart = T + oldOffset;
                long gapEnd = T + newOffset;
                if (W >= gapStart && W < gapEnd) {
                    long t = W - oldOffset;
                    TzInfo info = getInfoAt(data, t);
                    String localStr = secondsToWall(t + info.offset);
                    String offsetStr = formatOffset(info.offset);
                    return query + " -> GAP " + t + " " + localStr + offsetStr + " " + info.abbr;
                }
            }
        }

        // Check POSIX transitions
        if (data.hasDST) {
            long lastT = data.transitionTimes.length > 0
                    ? data.transitionTimes[data.transitionTimes.length - 1] : Long.MIN_VALUE;
            int year = (int)(W / (365.25 * 86400) + 1970);
            for (int y = year - 1; y <= year + 1; y++) {
                // Check start transition (gap if dst > std)
                if (data.dstUTCOffset > data.stdUTCOffset) {
                    long startUTC = computeStartUTC(data, y);
                    if (startUTC > lastT) {
                        long gapStart = startUTC + data.stdUTCOffset;
                        long gapEnd = startUTC + data.dstUTCOffset;
                        if (W >= gapStart && W < gapEnd) {
                            long t = W - data.stdUTCOffset;
                            TzInfo info = getInfoAt(data, t);
                            String localStr = secondsToWall(t + info.offset);
                            String offsetStr = formatOffset(info.offset);
                            return query + " -> GAP " + t + " " + localStr + offsetStr + " " + info.abbr;
                        }
                    }
                }
                // Check end transition (gap if std > dst)
                if (data.stdUTCOffset > data.dstUTCOffset) {
                    long endUTC = computeEndUTC(data, y);
                    if (endUTC > lastT) {
                        long gapStart = endUTC + data.dstUTCOffset;
                        long gapEnd = endUTC + data.stdUTCOffset;
                        if (W >= gapStart && W < gapEnd) {
                            long t = W - data.dstUTCOffset;
                            TzInfo info = getInfoAt(data, t);
                            String localStr = secondsToWall(t + info.offset);
                            String offsetStr = formatOffset(info.offset);
                            return query + " -> GAP " + t + " " + localStr + offsetStr + " " + info.abbr;
                        }
                    }
                }
            }
        }

        // Fallback (should not happen with valid input)
        return query + " -> GAP 0 1970-01-01T00:00:00+00:00 ?";
    }

    static long wallToSeconds(String s) {
        LocalDate date = LocalDate.parse(s.substring(0, 10));
        int h = Integer.parseInt(s.substring(11, 13));
        int m = Integer.parseInt(s.substring(14, 16));
        int sec = Integer.parseInt(s.substring(17, 19));
        return date.toEpochDay() * 86400L + h * 3600L + m * 60L + sec;
    }

    static String secondsToWall(long secs) {
        long epochDay = Math.floorDiv(secs, 86400);
        int rem = (int)(secs - epochDay * 86400);
        LocalDate date = LocalDate.ofEpochDay(epochDay);
        int h = rem / 3600;
        int m = (rem % 3600) / 60;
        int s = rem % 60;
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d",
                date.getYear(), date.getMonthValue(), date.getDayOfMonth(), h, m, s);
    }

    static String formatOffset(int offset) {
        if (offset == 0) return "+00:00";
        char sign = offset >= 0 ? '+' : '-';
        int abs = Math.abs(offset);
        int h = abs / 3600;
        int m = (abs % 3600) / 60;
        int s = abs % 60;
        if (s != 0) {
            return String.format("%c%02d:%02d:%02d", sign, h, m, s);
        } else {
            return String.format("%c%02d:%02d", sign, h, m);
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

#define MAX_ZONES 200
#define MAX_TYPES 256
#define MAX_TRANS 65536
#define ABBR_MAX 64
#define TZ_STR_MAX 256

typedef struct { int32_t utcoff; uint8_t isdst; uint8_t abbrind; } ttinfo_t;
typedef struct { int64_t time; uint8_t type; } trans_t;

typedef struct {
    char filename[256];
    int loaded;
    int ntrans;
    trans_t *trans;
    int ntypes;
    ttinfo_t *types;
    int charcnt;
    char *chars;
    char posix_str[TZ_STR_MAX];
    int has_dst;
    char std_name[ABBR_MAX];
    char dst_name[ABBR_MAX];
    int32_t posix_std_off;
    int32_t posix_dst_off;
    int start_month, start_week, start_dow, start_time;
    int end_month, end_week, end_dow, end_time;
} tzdata_t;

typedef struct { int32_t utcoff; char abbr[ABBR_MAX]; } local_type_t;

/* ===== Big-endian readers ===== */
static int32_t read_be32(const uint8_t *p) {
    return (int32_t)((uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|(uint32_t)p[3]);
}
static int64_t read_be64(const uint8_t *p) {
    return (int64_t)((uint64_t)p[0]<<56|(uint64_t)p[1]<<48|(uint64_t)p[2]<<40|(uint64_t)p[3]<<32|
                     (uint64_t)p[4]<<24|(uint64_t)p[5]<<16|(uint64_t)p[6]<<8|(uint64_t)p[7]);
}

/* ===== Calendar ===== */
static int is_leap(int y){return (y%4==0&&y%100!=0)||(y%400==0);}
static int dim(int y,int m){static const int d[]={0,31,28,31,30,31,30,31,31,30,31,30,31};return m==2&&is_leap(y)?29:d[m];}

static int64_t days_from_civil(int y,int m,int d){
    y-=m<=2;
    int64_t era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153*(m+(m>2?-3:9))+2)/5+d-1;
    unsigned doe=yoe*365+yoe/4-yoe/100+doy;
    return era*146097+(int64_t)doe-719468;
}
static void civil_from_days(int64_t z,int*y,int*m,int*d){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460+doe/36524-doe/146096)/365;
    int64_t yr=(int64_t)yoe+era*400;
    unsigned doy=doe-(365*yoe+yoe/4-yoe/100);
    unsigned mp=(5*doy+2)/153;
    unsigned dd=doy-(153*mp+2)/5+1;
    unsigned mm=mp+(mp<10?3:-9);
    *y=(int)(yr+(mm<=2));*m=(int)mm;*d=(int)dd;
}
static int64_t my_timegm(int y,int m,int d,int h,int mi,int s){
    return days_from_civil(y,m,d)*86400+h*3600+mi*60+s;
}
static void my_gmtime(int64_t t,int*y,int*m,int*d,int*h,int*mi,int*s){
    int64_t days=t/86400; int64_t sod=t%86400;
    if(sod<0){sod+=86400;days--;}
    civil_from_days(days,y,m,d);
    *h=(int)(sod/3600);*mi=(int)((sod%3600)/60);*s=(int)(sod%60);
}
static int day_of_week(int y,int m,int d){
    int64_t days=days_from_civil(y,m,d);
    int dow=(int)((days+4)%7); if(dow<0)dow+=7; return dow;
}
static int nth_dow(int year,int month,int dow,int week){
    int fdow=day_of_week(year,month,1);
    int fo=(dow-fdow+7)%7+1;
    if(week<=4) return fo+7*(week-1);
    int dm=dim(year,month);
    return fo+7*((dm-fo)/7);
}

/* ===== TZif parsing ===== */
static void parse_tzif(const char *dir,const char *fn,tzdata_t *tz){
    char path[512]; snprintf(path,sizeof(path),"%s/%s",dir,fn);
    FILE *f=fopen(path,"rb"); if(!f){perror(path);exit(1);}
    fseek(f,0,SEEK_END); long fsz=ftell(f); fseek(f,0,SEEK_SET);
    uint8_t *buf=(uint8_t*)malloc(fsz); fread(buf,1,fsz,f); fclose(f);
    uint8_t *p=buf;
    /* first header */
    int isut1=read_be32(p+20),isstd1=read_be32(p+24),leap1=read_be32(p+28),
        time1=read_be32(p+32),type1=read_be32(p+36),char1=read_be32(p+40);
    int bsz1=time1*4+time1+type1*6+char1+leap1*8+isstd1+isut1;
    p+=44+bsz1;
    /* second header */
    int isut=read_be32(p+20),isstd=read_be32(p+24),leap=read_be32(p+28),
        timecnt=read_be32(p+32),typecnt=read_be32(p+36),charcnt=read_be32(p+40);
    p+=44;
    tz->ntrans=timecnt;
    tz->trans=(trans_t*)malloc(sizeof(trans_t)*timecnt);
    for(int i=0;i<timecnt;i++){tz->trans[i].time=read_be64(p);p+=8;}
    for(int i=0;i<timecnt;i++){tz->trans[i].type=*p++;}
    tz->ntypes=typecnt;
    tz->types=(ttinfo_t*)malloc(sizeof(ttinfo_t)*typecnt);
    for(int i=0;i<typecnt;i++){tz->types[i].utcoff=read_be32(p);p+=4;tz->types[i].isdst=*p++;tz->types[i].abbrind=*p++;}
    tz->chars=(char*)malloc(charcnt+1);
    memcpy(tz->chars,p,charcnt); tz->chars[charcnt]='\0'; tz->charcnt=charcnt; p+=charcnt;
    p+=leap*12+isstd+isut;
    /* footer */
    if(*p=='\n')p++;
    int i=0; while(*p!='\n'&&*p!='\0'&&i<TZ_STR_MAX-1) tz->posix_str[i++]=*p++;
    tz->posix_str[i]='\0';
    free(buf);
}

/* ===== POSIX TZ parsing ===== */
static const char *p_name(const char *s,char *nm,int mx){
    if(*s=='<'){s++;int i=0;while(*s&&*s!='>'&&i<mx-1)nm[i++]=*s++;nm[i]='\0';if(*s=='>')s++;}
    else{int i=0;while(isalpha(*s)&&i<mx-1)nm[i++]=*s++;nm[i]='\0';}
    return s;
}
static const char *p_off(const char *s,int32_t *off){
    int sign=1;
    if(*s=='-'){sign=-1;s++;}else if(*s=='+'){s++;}
    int h=0,m=0,sc=0;
    while(isdigit(*s))h=h*10+(*s++-'0');
    if(*s==':'){s++;while(isdigit(*s))m=m*10+(*s++-'0');
        if(*s==':'){s++;while(isdigit(*s))sc=sc*10+(*s++-'0');}}
    *off=sign*(h*3600+m*60+sc); return s;
}
static const char *p_rule(const char *s,int *mo,int *wk,int *dw,int *tm){
    if(*s=='M'){s++;*mo=0;while(isdigit(*s))*mo=*mo*10+(*s++-'0');
        if(*s=='.')s++;*wk=0;while(isdigit(*s))*wk=*wk*10+(*s++-'0');
        if(*s=='.')s++;*dw=0;while(isdigit(*s))*dw=*dw*10+(*s++-'0');}
    *tm=7200;
    if(*s=='/'){s++;int sign=1;
        if(*s=='-'){sign=-1;s++;}else if(*s=='+'){s++;}
        int h=0,m=0,sc=0;
        while(isdigit(*s))h=h*10+(*s++-'0');
        if(*s==':'){s++;while(isdigit(*s))m=m*10+(*s++-'0');
            if(*s==':'){s++;while(isdigit(*s))sc=sc*10+(*s++-'0');}}
        *tm=sign*(h*3600+m*60+sc);}
    return s;
}
static void parse_posix(tzdata_t *tz){
    const char *s=tz->posix_str;
    if(!*s){tz->has_dst=0;tz->posix_std_off=0;tz->posix_dst_off=0;
        strcpy(tz->std_name,"UTC");strcpy(tz->dst_name,"");
        tz->start_month=1;tz->start_week=1;tz->start_dow=0;tz->start_time=7200;
        tz->end_month=1;tz->end_week=1;tz->end_dow=0;tz->end_time=7200;return;}
    s=p_name(s,tz->std_name,ABBR_MAX);
    s=p_off(s,&tz->posix_std_off);
    tz->has_dst=0;
    if(*s&&*s!=','){
        s=p_name(s,tz->dst_name,ABBR_MAX);
        tz->has_dst=1;
        if(*s&&*s!=',') s=p_off(s,&tz->posix_dst_off);
        else tz->posix_dst_off=tz->posix_std_off-3600;
        if(*s==','){s++;
            s=p_rule(s,&tz->start_month,&tz->start_week,&tz->start_dow,&tz->start_time);
            if(*s==',')s++;
            s=p_rule(s,&tz->end_month,&tz->end_week,&tz->end_dow,&tz->end_time);
        }else{
            tz->start_month=3;tz->start_week=2;tz->start_dow=0;tz->start_time=7200;
            tz->end_month=11;tz->end_week=1;tz->end_dow=0;tz->end_time=7200;
        }
    }
}

/* ===== DST / type lookup ===== */
static int64_t calc_start(tzdata_t *tz,int year){
    int d=nth_dow(year,tz->start_month,tz->start_dow,tz->start_week);
    int64_t mid=my_timegm(year,tz->start_month,d,0,0,0);
    return mid+tz->start_time+tz->posix_std_off;
}
static int64_t calc_end(tzdata_t *tz,int year){
    int d=nth_dow(year,tz->end_month,tz->end_dow,tz->end_week);
    int64_t mid=my_timegm(year,tz->end_month,d,0,0,0);
    return mid+tz->end_time+tz->posix_dst_off;
}
static int is_dst_at(tzdata_t *tz,int64_t t){
    if(!tz->has_dst)return 0;
    int y,m,d,h,mi,s; my_gmtime(t,&y,&m,&d,&h,&mi,&s);
    int64_t st=calc_start(tz,y),en=calc_end(tz,y);
    if(st<en) return t>=st&&t<en;
    if(st>en) return t>=st||t<en;
    return 0;
}
static local_type_t get_type_at(tzdata_t *tz,int64_t t){
    local_type_t r;
    if(tz->ntrans==0||t<tz->trans[0].time){
        r.utcoff=tz->types[0].utcoff;
        strncpy(r.abbr,tz->chars+tz->types[0].abbrind,ABBR_MAX-1);r.abbr[ABBR_MAX-1]='\0';
        return r;
    }
    if(t>tz->trans[tz->ntrans-1].time){
        if(!tz->has_dst){
            r.utcoff=-tz->posix_std_off;
            strncpy(r.abbr,tz->std_name,ABBR_MAX-1);r.abbr[ABBR_MAX-1]='\0';
        }else if(is_dst_at(tz,t)){
            r.utcoff=-tz->posix_dst_off;
            strncpy(r.abbr,tz->dst_name,ABBR_MAX-1);r.abbr[ABBR_MAX-1]='\0';
        }else{
            r.utcoff=-tz->posix_std_off;
            strncpy(r.abbr,tz->std_name,ABBR_MAX-1);r.abbr[ABBR_MAX-1]='\0';
        }
        return r;
    }
    int lo=0,hi=tz->ntrans-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->trans[mid].time<=t)lo=mid;else hi=mid-1;}
    int ti=tz->trans[lo].type;
    r.utcoff=tz->types[ti].utcoff;
    strncpy(r.abbr,tz->chars+tz->types[ti].abbrind,ABBR_MAX-1);r.abbr[ABBR_MAX-1]='\0';
    return r;
}

/* ===== Output formatting ===== */
static void fmt_off(int32_t off,char *buf){
    char sign=off>=0?'+':'-';
    int32_t ao=off>=0?off:-off;
    int h=ao/3600,m=(ao%3600)/60,s=ao%60;
    if(s) sprintf(buf,"%c%02d:%02d:%02d",sign,h,m,s);
    else  sprintf(buf,"%c%02d:%02d",sign,h,m);
}
static void fmt_local(int64_t ls,char *buf){
    int y,m,d,h,mi,s; my_gmtime(ls,&y,&m,&d,&h,&mi,&s);
    sprintf(buf,"%04d-%02d-%02dT%02d:%02d:%02d",y,m,d,h,mi,s);
}

/* ===== Main ===== */
int main(int argc,char *argv[]){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    const char *dir=argv[1];
    static tzdata_t zones[MAX_ZONES];
    int nz=0;
    char qp[512]; snprintf(qp,sizeof(qp),"%s/queries.txt",dir);
    FILE *qf=fopen(qp,"r"); if(!qf){perror(qp);return 1;}
    char line[1024];
    while(fgets(line,sizeof(line),qf)){
        int len=(int)strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]='\0';
        if(len==0)continue;
        char tp[16],fn[256],val[256];
        if(sscanf(line,"%15s %255s %255s",tp,fn,val)<3)continue;
        tzdata_t *tz=NULL;
        for(int i=0;i<nz;i++)if(strcmp(zones[i].filename,fn)==0){tz=&zones[i];break;}
        if(!tz){tz=&zones[nz++];memset(tz,0,sizeof(*tz));strncpy(tz->filename,fn,255);
            parse_tzif(dir,fn,tz);parse_posix(tz);}
        if(strcmp(tp,"UTC")==0){
            int64_t t=strtoll(val,NULL,10);
            local_type_t lt=get_type_at(tz,t);
            int64_t ls=t+lt.utcoff;
            char lstr[64],ostr[32];
            fmt_local(ls,lstr);fmt_off(lt.utcoff,ostr);
            printf("%s -> %s%s %s\n",line,lstr,ostr,lt.abbr);
        }else if(strcmp(tp,"LOCAL")==0){
            int y,mo,d,h,mi,s;
            sscanf(val,"%d-%d-%dT%d:%d:%d",&y,&mo,&d,&h,&mi,&s);
            int64_t W=my_timegm(y,mo,d,h,mi,s);
            /* collect unique offsets */
            int32_t offs[512];int no=0;
            for(int i=0;i<tz->ntypes;i++){
                int32_t o=tz->types[i].utcoff;int dup=0;
                for(int j=0;j<no;j++)if(offs[j]==o){dup=1;break;}
                if(!dup)offs[no++]=o;
            }
            if(tz->posix_str[0]){
                int32_t o1=-tz->posix_std_off,dup=0;
                for(int j=0;j<no;j++)if(offs[j]==o1){dup=1;break;}
                if(!dup)offs[no++]=o1;
                if(tz->has_dst){int32_t o2=-tz->posix_dst_off;dup=0;
                    for(int j=0;j<no;j++)if(offs[j]==o2){dup=1;break;}
                    if(!dup)offs[no++]=o2;}
            }
            /* find valid t */
            int64_t res[4];local_type_t rlt[4];int nr=0;
            for(int i=0;i<no;i++){
                int64_t t=W-offs[i];
                local_type_t lt=get_type_at(tz,t);
                if(t+lt.utcoff==W){res[nr]=t;rlt[nr]=lt;nr++;}
            }
            if(nr==1){
                char ostr[32];fmt_off(rlt[0].utcoff,ostr);
                printf("%s -> %lld %s %s\n",line,(long long)res[0],ostr,rlt[0].abbr);
            }else if(nr>=2){
                if(res[0]>res[1]){int64_t tmp=res[0];res[0]=res[1];res[1]=tmp;
                    local_type_t tl=rlt[0];rlt[0]=rlt[1];rlt[1]=tl;}
                char o1[32],o2[32];fmt_off(rlt[0].utcoff,o1);fmt_off(rlt[1].utcoff,o2);
                printf("%s -> %lld %s %s | %lld %s %s\n",line,
                    (long long)res[0],o1,rlt[0].abbr,(long long)res[1],o2,rlt[1].abbr);
            }else{
                /* gap */
                int64_t tg=0;int found=0;
                for(int i=0;i<tz->ntrans&&!found;i++){
                    int pt=(i==0)?0:tz->trans[i-1].type;
                    int ct=tz->trans[i].type;
                    int32_t oo=tz->types[pt].utcoff,no2=tz->types[ct].utcoff;
                    if(no2>oo){int64_t T=tz->trans[i].time;
                        if(T+oo<=W&&W<T+no2){tg=W-oo;found=1;}}
                }
                if(!found&&tz->has_dst){
                    int y2,mo2,d2,h2,mi2,s2;my_gmtime(W,&y2,&mo2,&d2,&h2,&mi2,&s2);
                    for(int yr=y2-1;yr<=y2+1&&!found;yr++){
                        int64_t Ts=calc_start(tz,yr);
                        int32_t oo=-tz->posix_std_off,no2=-tz->posix_dst_off;
                        if(no2>oo){if(Ts+oo<=W&&W<Ts+no2){tg=W-oo;found=1;}}
                    }
                }
                local_type_t lt=get_type_at(tz,tg);
                int64_t ls=tg+lt.utcoff;
                char lstr[64],ostr[32];fmt_local(ls,lstr);fmt_off(lt.utcoff,ostr);
                printf("%s -> GAP %lld %s%s %s\n",line,(long long)tg,lstr,ostr,lt.abbr);
            }
        }
    }
    fclose(qf);
    return 0;
}

import Foundation

// MARK: - Date/Time Utilities

func isLeapYear(_ y: Int) -> Bool {
    if y % 400 == 0 { return true }
    if y % 100 == 0 { return false }
    return y % 4 == 0
}

func daysInMonth(_ y: Int, _ m: Int) -> Int {
    let d = [31,28,31,30,31,30,31,31,30,31,30,31]
    if m == 2 && isLeapYear(y) { return 29 }
    return d[m-1]
}

func dayOfWeek(_ y: Int, _ m: Int, _ d: Int) -> Int {
    var y = y
    let t = [0,3,2,5,0,3,5,1,4,6,2,4]
    if m < 3 { y -= 1 }
    return ((y + y/4 - y/100 + y/400 + t[m-1] + d) % 7 + 7) % 7
}

func unixToComponents(_ t: Int) -> (year: Int, month: Int, day: Int, hour: Int, min: Int, sec: Int) {
    var days = t / 86400
    var secs = t % 86400
    if secs < 0 { secs += 86400; days -= 1 }
    let hour = secs / 3600
    let min = (secs % 3600) / 60
    let sec = secs % 60
    var z = days + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2)/153
    let d = doy - (153*mp+2)/5 + 1
    let m = mp + (mp < 10 ? 3 : -9)
    let year = y + (m <= 2 ? 1 : 0)
    return (year, m, d, hour, min, sec)
}

func componentsToUnix(_ year: Int, _ month: Int, _ day: Int, _ hour: Int, _ min: Int, _ sec: Int) -> Int {
    var y = year
    if month <= 2 { y -= 1 }
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let mp = (month + 9) % 12
    let doy = (153*mp + 2)/5 + day - 1
    let doe = yoe * 365 + yoe/4 - yoe/100 + doy
    let days = era * 146097 + doe - 719468
    return days * 86400 + hour * 3600 + min * 60 + sec
}

func formatOffset(_ gmtoff: Int) -> String {
    let sign = gmtoff >= 0 ? "+" : "-"
    let a = abs(gmtoff)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalTime(_ t: Int, _ gmtoff: Int) -> String {
    let lt = t + gmtoff
    let c = unixToComponents(lt)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", c.year, c.month, c.day, c.hour, c.min, c.sec) + formatOffset(gmtoff)
}

// MARK: - Data Structures

struct TypeRecord { let gmtoff: Int; let isdst: Bool; let abbrIndex: Int }
struct Transition { let time: Int; let typeIndex: Int }
struct MWDTime { let month: Int; let week: Int; let day: Int; let timeOfDay: Int }
struct FooterRule {
    let stdName: String; let stdOffset: Int
    let dstName: String?; let dstOffset: Int?
    let start: MWDTime?; let end: MWDTime?
}
struct TZifData {
    let transitions: [Transition]; let types: [TypeRecord]
    let abbreviations: [String]; let footer: FooterRule?
}

// MARK: - Binary Reading

func readBE32(_ d: [UInt8], _ o: Int) -> Int {
    (Int(d[o]) << 24) | (Int(d[o+1]) << 16) | (Int(d[o+2]) << 8) | Int(d[o+3])
}
func readBE32S(_ d: [UInt8], _ o: Int) -> Int {
    let v = readBE32(d, o)
    return v >= (1 << 31) ? v - (1 << 32) : v
}
func readBE64S(_ d: [UInt8], _ o: Int) -> Int {
    var v: Int64 = 0
    for i in 0..<8 { v = (v << 8) | Int64(d[o+i]) }
    return Int(v)
}

// MARK: - TZif Parsing

func parseTZif(_ data: [UInt8]) -> TZifData {
    var pos = 4 // skip magic
    pos += 16 // version + unused
    let _isutcnt1 = readBE32(data, pos); pos += 4
    let _isstdcnt1 = readBE32(data, pos); pos += 4
    let _leapcnt1 = readBE32(data, pos); pos += 4
    let _timecnt1 = readBE32(data, pos); pos += 4
    let _typecnt1 = readBE32(data, pos); pos += 4
    let _charcnt1 = readBE32(data, pos); pos += 4
    let block1Size = _timecnt1*4 + _timecnt1 + _typecnt1*6 + _charcnt1 + _leapcnt1*8 + _isstdcnt1 + _isutcnt1
    pos += block1Size

    // Second header
    pos += 4 // magic
    pos += 16 // version + unused
    let isutcnt = readBE32(data, pos); pos += 4
    let isstdcnt = readBE32(data, pos); pos += 4
    let leapcnt = readBE32(data, pos); pos += 4
    let timecnt = readBE32(data, pos); pos += 4
    let typecnt = readBE32(data, pos); pos += 4
    let charcnt = readBE32(data, pos); pos += 4

    var times = [Int](repeating: 0, count: timecnt)
    for i in 0..<timecnt { times[i] = readBE64S(data, pos); pos += 8 }
    var tidx = [Int](repeating: 0, count: timecnt)
    for i in 0..<timecnt { tidx[i] = Int(data[pos]); pos += 1 }
    var transitions = [Transition]()
    for i in 0..<timecnt { transitions.append(Transition(time: times[i], typeIndex: tidx[i])) }

    var types = [TypeRecord]()
    for _ in 0..<typecnt {
        let gmtoff = readBE32S(data, pos); pos += 4
        let isdst = data[pos] != 0; pos += 1
        let abbrIndex = Int(data[pos]); pos += 1
        types.append(TypeRecord(gmtoff: gmtoff, isdst: isdst, abbrIndex: abbrIndex))
    }

    var abbreviations = [String]()
    var abbrStart = pos
    for _ in 0..<charcnt {
        if data[pos] == 0 {
            let bytes = Array(data[abbrStart..<pos])
            abbreviations.append(String(bytes: bytes, encoding: .ascii) ?? "")
            abbrStart = pos + 1
        }
        pos += 1
    }

    pos += leapcnt * 12
    pos += isstdcnt
    pos += isutcnt

    // Footer
    if pos < data.count && data[pos] == 0x0A { pos += 1 }
    var footerStr = ""
    while pos < data.count && data[pos] != 0x0A {
        footerStr += String(UnicodeScalar(data[pos]))
        pos += 1
    }

    let footer: FooterRule? = footerStr.isEmpty ? nil : parsePOSIXTZ(footerStr)
    return TZifData(transitions: transitions, types: types, abbreviations: abbreviations, footer: footer)
}

// MARK: - POSIX TZ String Parsing

func parsePOSIXTZ(_ s: String) -> FooterRule {
    let chars = Array(s)
    var pos = 0

    func peek() -> Character? { pos < chars.count ? chars[pos] : nil }
    func next() -> Character { let c = chars[pos]; pos += 1; return c }

    func parseName() -> String {
        if peek() == "<" {
            next()
            var name = ""
            while let c = peek(), c != ">" { name.append(next()) }
            if peek() == ">" { next() }
            return name
        } else {
            var name = ""
            while let c = peek(), c.isLetter { name.append(next()) }
            return name
        }
    }

    func parseOff() -> Int {
        var sign = 1
        if peek() == "-" { sign = -1; next() }
        else if peek() == "+" { next() }
        var h = 0
        while let c = peek(), c.isNumber { h = h*10 + Int(String(next()))! }
        var m = 0, sec = 0
        if peek() == ":" {
            next()
            while let c = peek(), c.isNumber { m = m*10 + Int(String(next()))! }
            if peek() == ":" {
                next()
                while let c = peek(), c.isNumber { sec = sec*10 + Int(String(next()))! }
            }
        }
        return sign * (h*3600 + m*60 + sec)
    }

    func parseMWD() -> MWDTime {
        next() // 'M'
        var month = 0
        while let c = peek(), c.isNumber { month = month*10 + Int(String(next()))! }
        next() // '.'
        var week = 0
        while let c = peek(), c.isNumber { week = week*10 + Int(String(next()))! }
        next() // '.'
        var day = 0
        while let c = peek(), c.isNumber { day = day*10 + Int(String(next()))! }
        var tod = 2*3600
        if peek() == "/" {
            next()
            tod = parseOff()
        }
        return MWDTime(month: month, week: week, day: day, timeOfDay: tod)
    }

    let stdName = parseName()
    let stdOffset = parseOff()
    var dstName: String? = nil
    var dstOffset: Int? = nil
    var start: MWDTime? = nil
    var end: MWDTime? = nil

    if peek() != nil && peek() != "," {
        dstName = parseName()
        if peek() != nil && peek() != "," {
            dstOffset = parseOff()
        }
        if peek() == "," {
            next()
            start = parseMWD()
            if peek() == "," { next() }
            end = parseMWD()
        }
    }

    return FooterRule(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset, start: start, end: end)
}

// MARK: - MWD Date Computation

func findMWDDate(_ year: Int, _ month: Int, _ week: Int, _ dow: Int) -> Int {
    let dim = daysInMonth(year, month)
    let firstDOW = dayOfWeek(year, month, 1)
    let firstOcc = 1 + ((dow - firstDOW + 7) % 7)
    if week <= 4 {
        return firstOcc + (week - 1) * 7
    } else {
        let lastDOW = dayOfWeek(year, month, dim)
        return dim - ((lastDOW - dow + 7) % 7)
    }
}

func computeTransitionUTC(_ year: Int, _ mwd: MWDTime, _ offsetValue: Int) -> Int {
    let day = findMWDDate(year, mwd.month, mwd.week, mwd.day)
    let tod = mwd.timeOfDay
    let h: Int
    if tod >= 0 { h = tod / 3600 } else { h = (tod - 3599) / 3600 }
    let rem = tod - h * 3600
    let m = rem / 60
    let s = rem % 60
    let localTs = componentsToUnix(year, mwd.month, day, h, m, s)
    return localTs + offsetValue
}

// MARK: - Type Determination

func getDstOffsetValue(_ rule: FooterRule) -> Int {
    rule.dstOffset ?? (rule.stdOffset - 3600)
}

func footerTypeAt(_ t: Int, _ rule: FooterRule) -> (gmtoff: Int, isdst: Bool, abbr: String) {
    let std_gmtoff = -rule.stdOffset
    let dst_gmtoff = -(getDstOffsetValue(rule))

    if rule.start == nil || rule.end == nil || rule.dstName == nil {
        return (std_gmtoff, false, rule.stdName)
    }

    let comps = unixToComponents(t)
    let Y = comps.year
    let startUTC = computeTransitionUTC(Y, rule.start!, rule.stdOffset)
    let endUTC = computeTransitionUTC(Y, rule.end!, getDstOffsetValue(rule))

    let inDST: Bool
    if startUTC <= endUTC {
        inDST = (t >= startUTC && t < endUTC)
    } else {
        inDST = (t >= startUTC || t < endUTC)
    }

    if inDST {
        return (dst_gmtoff, true, rule.dstName!)
    } else {
        return (std_gmtoff, false, rule.stdName)
    }
}

func typeAt(_ t: Int, _ tzif: TZifData) -> (gmtoff: Int, isdst: Bool, abbr: String) {
    if tzif.transitions.isEmpty {
        if tzif.types.isEmpty { return (0, false, "UTC") }
        let tp = tzif.types[0]
        return (tp.gmtoff, tp.isdst, tzif.abbreviations.count > tp.abbrIndex ? tzif.abbreviations[tp.abbrIndex] : "")
    }

    if t < tzif.transitions[0].time {
        let tp = tzif.types[0]
        return (tp.gmtoff, tp.isdst, tzif.abbreviations.count > tp.abbrIndex ? tzif.abbreviations[tp.abbrIndex] : "")
    }

    if t > tzif.transitions.last!.time {
        if let footer = tzif.footer {
            return footerTypeAt(t, footer)
        }
        let lastIdx = tzif.transitions.last!.typeIndex
        let tp = tzif.types[lastIdx]
        return (tp.gmtoff, tp.isdst, tzif.abbreviations.count > tp.abbrIndex ? tzif.abbreviations[tp.abbrIndex] : "")
    }

    // Binary search for latest transition <= t
    var lo = 0, hi = tzif.transitions.count - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tzif.transitions[mid].time <= t { lo = mid } else { hi = mid - 1 }
    }
    let tp = tzif.types[tzif.transitions[lo].typeIndex]
    return (tp.gmtoff, tp.isdst, tzif.abbreviations.count > tp.abbrIndex ? tzif.abbreviations[tp.abbrIndex] : "")
}

// MARK: - Gap Detection

struct GapInfo { let gmtoffBefore: Int }

func findGap(W_naive: Int, tzif: TZifData) -> GapInfo? {
    struct Tr { let time: Int; let before: Int; let after: Int }
    var allTr: [Tr] = []

    for i in 0..<tzif.transitions.count {
        let tr = tzif.transitions[i]
        let beforeGmtoff: Int
        if i == 0 {
            beforeGmtoff = tzif.types.isEmpty ? 0 : tzif.types[0].gmtoff
        } else {
            beforeGmtoff = tzif.types[tzif.transitions[i-1].typeIndex].gmtoff
        }
        let afterGmtoff = tzif.types[tr.typeIndex].gmtoff
        allTr.append(Tr(time: tr.time, before: beforeGmtoff, after: afterGmtoff))
    }

    if let footer = tzif.footer, footer.start != nil, footer.end != nil, footer.dstName != nil {
        let std_gmtoff = -footer.stdOffset
        let dst_gmtoff = -(getDstOffsetValue(footer))
        let comps = unixToComponents(W_naive)
        let baseYear = comps.year
        let lastExplicit = tzif.transitions.isEmpty ? Int.min : tzif.transitions.last!.time

        for year in (baseYear - 1)...(baseYear + 1) {
            let startUTC = computeTransitionUTC(year, footer.start!, footer.stdOffset)
            if startUTC > lastExplicit && dst_gmtoff > std_gmtoff {
                allTr.append(Tr(time: startUTC, before: std_gmtoff, after: dst_gmtoff))
            }
        }
    }

    allTr.sort { $0.time < $1.time }

    for tr in allTr {
        if tr.after > tr.before {
            let gapStart = tr.time + tr.before
            let gapEnd = tr.time + tr.after
            if W_naive >= gapStart && W_naive < gapEnd {
                return GapInfo(gmtoffBefore: tr.before)
            }
        }
    }
    return nil
}

// MARK: - Main

let dir = CommandLine.arguments[1]
let queriesPath = dir + "/queries.txt"
let content = try! String(contentsOfFile: queriesPath, encoding: .utf8)
let lines = content.components(separatedBy: "\n")

var cache: [String: TZifData] = [:]

func loadTZif(_ name: String) -> TZifData {
    if let cached = cache[name] { return cached }
    let path = dir + "/" + name
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)
    let tzif = parseTZif(bytes)
    cache[name] = tzif
    return tzif
}

var outputLines: [String] = []

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }

    let fields = trimmed.components(separatedBy: " ")
    let queryType = fields[0]
    let fileName = fields[1]
    let tzif = loadTZif(fileName)

    if queryType == "UTC" {
        let t = Int(fields[2])!
        let info = typeAt(t, tzif)
        let local = formatLocalTime(t, info.gmtoff)
        outputLines.append("\(trimmed) -> \(local) \(info.abbr)")
    } else if queryType == "LOCAL" {
        let timeStr = fields[2]
        // Parse YYYY-MM-DDTHH:MM:SS
        let parts = timeStr.components(separatedBy: "T")
        let dateParts = parts[0].components(separatedBy: "-")
        let timeParts = parts[1].components(separatedBy: ":")
        let yr = Int(dateParts[0])!
        let mo = Int(dateParts[1])!
        let dy = Int(dateParts[2])!
        let hr = Int(timeParts[0])!
        let mi = Int(timeParts[1])!
        let sc = Int(timeParts[2])!
        let W_naive = componentsToUnix(yr, mo, dy, hr, mi, sc)

        // Collect possible gmtoffs
        var possibleGmtoffs = Set<Int>()
        for tp in tzif.types { possibleGmtoffs.insert(tp.gmtoff) }
        if let footer = tzif.footer {
            possibleGmtoffs.insert(-footer.stdOffset)
            if footer.dstName != nil {
                possibleGmtoffs.insert(-(getDstOffsetValue(footer)))
            }
        }

        var solutions: [(t: Int, gmtoff: Int, abbr: String)] = []
        for gmtoff in possibleGmtoffs {
            let t = W_naive - gmtoff
            let actual = typeAt(t, tzif)
            if actual.gmtoff == gmtoff {
                solutions.append((t: t, gmtoff: gmtoff, abbr: actual.abbr))
            }
        }

        solutions.sort { $0.t < $1.t }

        if solutions.count == 1 {
            let s = solutions[0]
            let offStr = formatOffset(s.gmtoff)
            outputLines.append("\(trimmed) -> \(s.t) \(offStr) \(s.abbr)")
        } else if solutions.count >= 2 {
            let partsStr = solutions.map { s -> String in
                let offStr = formatOffset(s.gmtoff)
                return "\(s.t) \(offStr) \(s.abbr)"
            }.joined(separator: " | ")
            outputLines.append("\(trimmed) -> \(partsStr)")
        } else {
            // Gap
            if let gap = findGap(W_naive: W_naive, tzif: tzif) {
                let t = W_naive - gap.gmtoffBefore
                let info = typeAt(t, tzif)
                let local = formatLocalTime(t, info.gmtoff)
                outputLines.append("\(trimmed) -> GAP \(t) \(local) \(info.abbr)")
            } else {
                // Fallback (shouldn't happen)
                outputLines.append("\(trimmed) -> GAP \(W_naive) \(formatLocalTime(W_naive, 0)) UTC")
            }
        }
    }
}

for ol in outputLines {
    print(ol)
}

import Foundation

// MARK: - Date/Time Utilities

func isLeapYear(_ y: Int) -> Bool {
    if y % 400 == 0 { return true }
    if y % 100 == 0 { return false }
    return y % 4 == 0
}

func daysInMonth(_ y: Int, _ m: Int) -> Int {
    let d = [31,28,31,30,31,30,31,31,30,31,30,31]
    if m == 2 && isLeapYear(y) { return 29 }
    return d[m-1]
}

func dayOfWeek(_ y: Int, _ m: Int, _ d: Int) -> Int {
    var y = y
    let t = [0,3,2,5,0,3,5,1,4,6,2,4]
    if m < 3 { y -= 1 }
    return ((y + y/4 - y/100 + y/400 + t[m-1] + d) % 7 + 7) % 7
}

func unixToComponents(_ t: Int) -> (year: Int, month: Int, day: Int, hour: Int, min: Int, sec: Int) {
    var days = t / 86400
    var secs = t % 86400
    if secs < 0 { secs += 86400; days -= 1 }
    let hour = secs / 3600
    let min = (secs % 3600) / 60
    let sec = secs % 60
    var z = days + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2)/153
    let d = doy - (153*mp+2)/5 + 1
    let m = mp + (mp < 10 ? 3 : -9)
    let year = y + (m <= 2 ? 1 : 0)
    return (year, m, d, hour, min, sec)
}

func componentsToUnix(_ year: Int, _ month: Int, _ day: Int, _ hour: Int, _ min: Int, _ sec: Int) -> Int {
    var y = year
    if month <= 2 { y -= 1 }
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let mp = (month + 9) % 12
    let doy = (153*mp + 2)/5 + day - 1
    let doe = yoe * 365 + yoe/4 - yoe/100 + doy
    let days = era * 146097 + doe - 719468
    return days * 86400 + hour * 3600 + min * 60 + sec
}

func formatOffset(_ gmtoff: Int) -> String {
    let sign = gmtoff >= 0 ? "+" : "-"
    let a = abs(gmtoff)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalTime(_ t: Int, _ gmtoff: Int) -> String {
    let lt = t + gmtoff
    let c = unixToComponents(lt)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", c.year, c.month, c.day, c.hour, c.min, c.sec) + formatOffset(gmtoff)
}

// MARK: - Data Structures

struct TypeRecord { let gmtoff: Int; let isdst: Bool; let abbrIndex: Int }
struct Transition { let time: Int; let typeIndex: Int }
struct MWDTime { let month: Int; let week: Int; let day: Int; let timeOfDay: Int }
struct FooterRule {
    let stdName: String; let stdOffset: Int
    let dstName: String?; let dstOffset: Int?
    let start: MWDTime?; let end: MWDTime?
}
struct TZifData {
    let transitions: [Transition]; let types: [TypeRecord]
    let abbrBytes: [UInt8]
    let footer: FooterRule?
}

func getAbbr(_ tzif: TZifData, _ offset: Int) -> String {
    guard offset >= 0 && offset < tzif.abbrBytes.count else { return "" }
    var end = offset
    while end < tzif.abbrBytes.count && tzif.abbrBytes[end] != 0 {
        end += 1
    }
    return String(bytes: tzif.abbrBytes[offset..<end], encoding: .ascii) ?? ""
}

// MARK: - Binary Reading

func readBE32(_ d: [UInt8], _ o: Int) -> Int {
    (Int(d[o]) << 24) | (Int(d[o+1]) << 16) | (Int(d[o+2]) << 8) | Int(d[o+3])
}
func readBE32S(_ d: [UInt8], _ o: Int) -> Int {
    let v = readBE32(d, o)
    return v >= (1 << 31) ? v - (1 << 32) : v
}
func readBE64S(_ d: [UInt8], _ o: Int) -> Int {
    var v: Int64 = 0
    for i in 0..<8 { v = (v << 8) | Int64(d[o+i]) }
    return Int(v)
}

// MARK: - TZif Parsing

func parseTZif(_ data: [UInt8]) -> TZifData {
    var pos = 4 // skip magic
    pos += 16 // version + unused
    let _isutcnt1 = readBE32(data, pos); pos += 4
    let _isstdcnt1 = readBE32(data, pos); pos += 4
    let _leapcnt1 = readBE32(data, pos); pos += 4
    let _timecnt1 = readBE32(data, pos); pos += 4
    let _typecnt1 = readBE32(data, pos); pos += 4
    let _charcnt1 = readBE32(data, pos); pos += 4
    let block1Size = _timecnt1*4 + _timecnt1 + _typecnt1*6 + _charcnt1 + _leapcnt1*8 + _isstdcnt1 + _isutcnt1
    pos += block1Size

    // Second header
    pos += 4 // magic
    pos += 16 // version + unused
    let isutcnt = readBE32(data, pos); pos += 4
    let isstdcnt = readBE32(data, pos); pos += 4
    let leapcnt = readBE32(data, pos); pos += 4
    let timecnt = readBE32(data, pos); pos += 4
    let typecnt = readBE32(data, pos); pos += 4
    let charcnt = readBE32(data, pos); pos += 4

    var times = [Int](repeating: 0, count: timecnt)
    for i in 0..<timecnt { times[i] = readBE64S(data, pos); pos += 8 }
    var tidx = [Int](repeating: 0, count: timecnt)
    for i in 0..<timecnt { tidx[i] = Int(data[pos]); pos += 1 }
    var transitions = [Transition]()
    for i in 0..<timecnt { transitions.append(Transition(time: times[i], typeIndex: tidx[i])) }

    var types = [TypeRecord]()
    for _ in 0..<typecnt {
        let gmtoff = readBE32S(data, pos); pos += 4
        let isdst = data[pos] != 0; pos += 1
        let abbrIndex = Int(data[pos]); pos += 1
        types.append(TypeRecord(gmtoff: gmtoff, isdst: isdst, abbrIndex: abbrIndex))
    }

    let abbrBytes = Array(data[pos..<(pos + charcnt)])
    pos += charcnt

    pos += leapcnt * 12
    pos += isstdcnt
    pos += isutcnt

    // Footer
    if pos < data.count && data[pos] == 0x0A { pos += 1 }
    var footerStr = ""
    while pos < data.count && data[pos] != 0x0A {
        footerStr += String(UnicodeScalar(data[pos]))
        pos += 1
    }

    let footer: FooterRule? = footerStr.isEmpty ? nil : parsePOSIXTZ(footerStr)
    return TZifData(transitions: transitions, types: types, abbrBytes: abbrBytes, footer: footer)
}

// MARK: - POSIX TZ String Parsing

func parsePOSIXTZ(_ s: String) -> FooterRule {
    let chars = Array(s)
    var pos = 0

    func peek() -> Character? { pos < chars.count ? chars[pos] : nil }
    func next() -> Character { let c = chars[pos]; pos += 1; return c }

    func parseName() -> String {
        if peek() == "<" {
            next()
            var name = ""
            while let c = peek(), c != ">" { name.append(next()) }
            if peek() == ">" { next() }
            return name
        } else {
            var name = ""
            while let c = peek(), c.isLetter { name.append(next()) }
            return name
        }
    }

    func parseOff() -> Int {
        var sign = 1
        if peek() == "-" { sign = -1; next() }
        else if peek() == "+" { next() }
        var h = 0
        while let c = peek(), c.isNumber { h = h*10 + Int(String(next()))! }
        var m = 0, sec = 0
        if peek() == ":" {
            next()
            while let c = peek(), c.isNumber { m = m*10 + Int(String(next()))! }
            if peek() == ":" {
                next()
                while let c = peek(), c.isNumber { sec = sec*10 + Int(String(next()))! }
            }
        }
        return sign * (h*3600 + m*60 + sec)
    }

    func parseMWD() -> MWDTime {
        next() // 'M'
        var month = 0
        while let c = peek(), c.isNumber { month = month*10 + Int(String(next()))! }
        next() // '.'
        var week = 0
        while let c = peek(), c.isNumber { week = week*10 + Int(String(next()))! }
        next() // '.'
        var day = 0
        while let c = peek(), c.isNumber { day = day*10 + Int(String(next()))! }
        var tod = 2*3600
        if peek() == "/" {
            next()
            tod = parseOff()
        }
        return MWDTime(month: month, week: week, day: day, timeOfDay: tod)
    }

    let stdName = parseName()
    let stdOffset = parseOff()
    var dstName: String? = nil
    var dstOffset: Int? = nil
    var start: MWDTime? = nil
    var end: MWDTime? = nil

    if peek() != nil && peek() != "," {
        dstName = parseName()
        if peek() != nil && peek() != "," {
            dstOffset = parseOff()
        }
        if peek() == "," {
            next()
            start = parseMWD()
            if peek() == "," { next() }
            end = parseMWD()
        }
    }

    return FooterRule(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset, start: start, end: end)
}

// MARK: - MWD Date Computation

func findMWDDate(_ year: Int, _ month: Int, _ week: Int, _ dow: Int) -> Int {
    let dim = daysInMonth(year, month)
    let firstDOW = dayOfWeek(year, month, 1)
    let firstOcc = 1 + ((dow - firstDOW + 7) % 7)
    if week <= 4 {
        return firstOcc + (week - 1) * 7
    } else {
        let lastDOW = dayOfWeek(year, month, dim)
        return dim - ((lastDOW - dow + 7) % 7)
    }
}

func computeTransitionUTC(_ year: Int, _ mwd: MWDTime, _ offsetValue: Int) -> Int {
    let day = findMWDDate(year, mwd.month, mwd.week, mwd.day)
    let tod = mwd.timeOfDay
    let h: Int
    if tod >= 0 { h = tod / 3600 } else { h = (tod - 3599) / 3600 }
    let rem = tod - h * 3600
    let m = rem / 60
    let s = rem % 60
    let localTs = componentsToUnix(year, mwd.month, day, h, m, s)
    return localTs + offsetValue
}

// MARK: - Type Determination

func getDstOffsetValue(_ rule: FooterRule) -> Int {
    rule.dstOffset ?? (rule.stdOffset - 3600)
}

func footerTypeAt(_ t: Int, _ rule: FooterRule) -> (gmtoff: Int, isdst: Bool, abbr: String) {
    let std_gmtoff = -rule.stdOffset
    let dst_gmtoff = -(getDstOffsetValue(rule))

    if rule.start == nil || rule.end == nil || rule.dstName == nil {
        return (std_gmtoff, false, rule.stdName)
    }

    let comps = unixToComponents(t)
    let Y = comps.year
    let startUTC = computeTransitionUTC(Y, rule.start!, rule.stdOffset)
    let endUTC = computeTransitionUTC(Y, rule.end!, getDstOffsetValue(rule))

    let inDST: Bool
    if startUTC <= endUTC {
        inDST = (t >= startUTC && t < endUTC)
    } else {
        inDST = (t >= startUTC || t < endUTC)
    }

    if inDST {
        return (dst_gmtoff, true, rule.dstName!)
    } else {
        return (std_gmtoff, false, rule.stdName)
    }
}

func typeAt(_ t: Int, _ tzif: TZifData) -> (gmtoff: Int, isdst: Bool, abbr: String) {
    if tzif.transitions.isEmpty {
        if tzif.types.isEmpty { return (0, false, "UTC") }
        let tp = tzif.types[0]
        return (tp.gmtoff, tp.isdst, getAbbr(tzif, tp.abbrIndex))
    }

    if t < tzif.transitions[0].time {
        let tp = tzif.types[0]
        return (tp.gmtoff, tp.isdst, getAbbr(tzif, tp.abbrIndex))
    }

    if t > tzif.transitions.last!.time {
        if let footer = tzif.footer {
            return footerTypeAt(t, footer)
        }
        let lastIdx = tzif.transitions.last!.typeIndex
        let tp = tzif.types[lastIdx]
        return (tp.gmtoff, tp.isdst, getAbbr(tzif, tp.abbrIndex))
    }

    // Binary search for latest transition <= t
    var lo = 0, hi = tzif.transitions.count - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tzif.transitions[mid].time <= t { lo = mid } else { hi = mid - 1 }
    }
    let tp = tzif.types[tzif.transitions[lo].typeIndex]
    return (tp.gmtoff, tp.isdst, getAbbr(tzif, tp.abbrIndex))
}

// MARK: - Gap Detection

struct GapInfo { let gmtoffBefore: Int }

func findGap(W_naive: Int, tzif: TZifData) -> GapInfo? {
    struct Tr { let time: Int; let before: Int; let after: Int }
    var allTr: [Tr] = []

    for i in 0..<tzif.transitions.count {
        let tr = tzif.transitions[i]
        let beforeGmtoff: Int
        if i == 0 {
            beforeGmtoff = tzif.types.isEmpty ? 0 : tzif.types[0].gmtoff
        } else {
            beforeGmtoff = tzif.types[tzif.transitions[i-1].typeIndex].gmtoff
        }
        let afterGmtoff = tzif.types[tr.typeIndex].gmtoff
        allTr.append(Tr(time: tr.time, before: beforeGmtoff, after: afterGmtoff))
    }

    if let footer = tzif.footer, footer.start != nil, footer.end != nil, footer.dstName != nil {
        let std_gmtoff = -footer.stdOffset
        let dst_gmtoff = -(getDstOffsetValue(footer))
        let comps = unixToComponents(W_naive)
        let baseYear = comps.year
        let lastExplicit = tzif.transitions.isEmpty ? Int.min : tzif.transitions.last!.time

        for year in (baseYear - 1)...(baseYear + 1) {
            let startUTC = computeTransitionUTC(year, footer.start!, footer.stdOffset)
            if startUTC > lastExplicit && dst_gmtoff > std_gmtoff {
                allTr.append(Tr(time: startUTC, before: std_gmtoff, after: dst_gmtoff))
            }
        }
    }

    allTr.sort { $0.time < $1.time }

    for tr in allTr {
        if tr.after > tr.before {
            let gapStart = tr.time + tr.before
            let gapEnd = tr.time + tr.after
            if W_naive >= gapStart && W_naive < gapEnd {
                return GapInfo(gmtoffBefore: tr.before)
            }
        }
    }
    return nil
}

// MARK: - Main

let dir = CommandLine.arguments[1]
let queriesPath = dir + "/queries.txt"
let content = try! String(contentsOfFile: queriesPath, encoding: .utf8)
let lines = content.components(separatedBy: "\n")

var cache: [String: TZifData] = [:]

func loadTZif(_ name: String) -> TZifData {
    if let cached = cache[name] { return cached }
    let path = dir + "/" + name
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)
    let tzif = parseTZif(bytes)
    cache[name] = tzif
    return tzif
}

var outputLines: [String] = []

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }

    let fields = trimmed.components(separatedBy: " ")
    let queryType = fields[0]
    let fileName = fields[1]
    let tzif = loadTZif(fileName)

    if queryType == "UTC" {
        let t = Int(fields[2])!
        let info = typeAt(t, tzif)
        let local = formatLocalTime(t, info.gmtoff)
        outputLines.append("\(trimmed) -> \(local) \(info.abbr)")
    } else if queryType == "LOCAL" {
        let timeStr = fields[2]
        let parts = timeStr.components(separatedBy: "T")
        let dateParts = parts[0].components(separatedBy: "-")
        let timeParts = parts[1].components(separatedBy: ":")
        let yr = Int(dateParts[0])!
        let mo = Int(dateParts[1])!
        let dy = Int(dateParts[2])!
        let hr = Int(timeParts[0])!
        let mi = Int(timeParts[1])!
        let sc = Int(timeParts[2])!
        let W_naive = componentsToUnix(yr, mo, dy, hr, mi, sc)

        // Collect possible gmtoffs
        var possibleGmtoffs = Set<Int>()
        for tp in tzif.types { possibleGmtoffs.insert(tp.gmtoff) }
        if let footer = tzif.footer {
            possibleGmtoffs.insert(-footer.stdOffset)
            if footer.dstName != nil {
                possibleGmtoffs.insert(-(getDstOffsetValue(footer)))
            }
        }

        var solutions: [(t: Int, gmtoff: Int, abbr: String)] = []
        for gmtoff in possibleGmtoffs {
            let t = W_naive - gmtoff
            let actual = typeAt(t, tzif)
            if actual.gmtoff == gmtoff {
                solutions.append((t: t, gmtoff: gmtoff, abbr: actual.abbr))
            }
        }

        solutions.sort { $0.t < $1.t }

        if solutions.count == 1 {
            let s = solutions[0]
            let offStr = formatOffset(s.gmtoff)
            outputLines.append("\(trimmed) -> \(s.t) \(offStr) \(s.abbr)")
        } else if solutions.count >= 2 {
            let partsStr = solutions.map { s -> String in
                let offStr = formatOffset(s.gmtoff)
                return "\(s.t) \(offStr) \(s.abbr)"
            }.joined(separator: " | ")
            outputLines.append("\(trimmed) -> \(partsStr)")
        } else {
            // Gap
            if let gap = findGap(W_naive: W_naive, tzif: tzif) {
                let t = W_naive - gap.gmtoffBefore
                let info = typeAt(t, tzif)
                let local = formatLocalTime(t, info.gmtoff)
                outputLines.append("\(trimmed) -> GAP \(t) \(local) \(info.abbr)")
            } else {
                outputLines.append("\(trimmed) -> GAP \(W_naive) \(formatLocalTime(W_naive, 0)) UTC")
            }
        }
    }
}

for ol in outputLines {
    print(ol)
}

import * as fs from 'fs';
import * as path from 'path';

// ============ Utility Functions ============

function pad(n: number, width: number): string {
  return String(Math.abs(n)).padStart(width, '0');
}

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

function daysInMonth(year: number, month: number): number {
  const days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) return 29;
  return days[month - 1];
}

function dayOfWeek(year: number, month: number, day: number): number {
  let y = year, m = month;
  if (m < 3) { m += 12; y -= 1; }
  const k = y % 100;
  const j = Math.floor(y / 100);
  let h = (day + Math.floor(13 * (m + 1) / 5) + k + Math.floor(k / 4) + Math.floor(j / 4) - 2 * j) % 7;
  if (h < 0) h += 7;
  return (h + 6) % 7; // 0=Sun, 1=Mon, ..., 6=Sat
}

function dateToUnix(year: number, month: number, day: number, hour: number, min: number, sec: number): number {
  return Math.floor(Date.UTC(year, month - 1, day, hour, min, sec) / 1000);
}

function unixToDate(t: number): { year: number; month: number; day: number; hour: number; min: number; sec: number } {
  const d = new Date(t * 1000);
  return {
    year: d.getUTCFullYear(),
    month: d.getUTCMonth() + 1,
    day: d.getUTCDate(),
    hour: d.getUTCHours(),
    min: d.getUTCMinutes(),
    sec: d.getUTCSeconds(),
  };
}

// ============ TZif Parsing ============

interface LocalTimeType {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TzifData {
  transitions: number[];
  typeIndices: number[];
  types: LocalTimeType[];
  abbrBytes: Buffer;
  posixTz: string;
}

function parseTzif(buffer: Buffer): TzifData {
  let pos = 0;

  // First header (44 bytes)
  pos += 4; // magic "TZif"
  pos += 1; // version
  pos += 15; // unused

  const isutcnt1 = buffer.readInt32BE(pos); pos += 4;
  const isstdcnt1 = buffer.readInt32BE(pos); pos += 4;
  const leapcnt1 = buffer.readInt32BE(pos); pos += 4;
  const timecnt1 = buffer.readInt32BE(pos); pos += 4;
  const typecnt1 = buffer.readInt32BE(pos); pos += 4;
  const charcnt1 = buffer.readInt32BE(pos); pos += 4;

  // Skip first data block
  pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

  // Second header (44 bytes)
  pos += 4; // magic "TZif"
  pos += 1; // version
  pos += 15; // unused

  const isutcnt2 = buffer.readInt32BE(pos); pos += 4;
  const isstdcnt2 = buffer.readInt32BE(pos); pos += 4;
  const leapcnt2 = buffer.readInt32BE(pos); pos += 4;
  const timecnt2 = buffer.readInt32BE(pos); pos += 4;
  const typecnt2 = buffer.readInt32BE(pos); pos += 4;
  const charcnt2 = buffer.readInt32BE(pos); pos += 4;

  // Second data block: 64-bit transition times
  const transitions: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    transitions.push(Number(buffer.readBigInt64BE(pos)));
    pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    typeIndices.push(buffer[pos]);
    pos += 1;
  }

  const types: LocalTimeType[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buffer.readInt32BE(pos); pos += 4;
    const isdst = buffer[pos]; pos += 1;
    const abbrIndex = buffer[pos]; pos += 1;
    types.push({ gmtoff, isdst, abbrIndex });
  }

  const abbrBytes = buffer.slice(pos, pos + charcnt2);
  pos += charcnt2;

  // Skip leap seconds (8+4 bytes each)
  pos += leapcnt2 * 12;
  // Skip isstd and isut flags
  pos += isstdcnt2 + isutcnt2;

  // Footer: newline, POSIX TZ string, newline
  pos += 1; // skip leading newline
  const footerStart = pos;
  const footerEnd = buffer.indexOf(0x0A, footerStart);
  const posixTz = footerEnd === -1 ? '' : buffer.toString('ascii', footerStart, footerEnd);

  return { transitions, typeIndices, types, abbrBytes, posixTz };
}

function getAbbreviation(tzif: TzifData, abbrIndex: number): string {
  let end = abbrIndex;
  while (end < tzif.abbrBytes.length && tzif.abbrBytes[end] !== 0) {
    end++;
  }
  return tzif.abbrBytes.toString('ascii', abbrIndex, end);
}

// ============ POSIX TZ String Parsing ============

interface MwdRule {
  month: number;
  week: number;
  day: number;
  time: number; // seconds from midnight
}

interface PosixTzRule {
  stdName: string;
  stdOffset: number; // amount to ADD to local to get UTC
  dstName?: string;
  dstOffset?: number;
  start?: MwdRule;
  end?: MwdRule;
}

function parsePosixTz(str: string): PosixTzRule {
  let pos = 0;

  function readName(): string {
    if (pos < str.length && str[pos] === '<') {
      pos++;
      let name = '';
      while (pos < str.length && str[pos] !== '>') {
        name += str[pos];
        pos++;
      }
      pos++; // skip >
      return name;
    } else {
      let name = '';
      while (pos < str.length && /[a-zA-Z]/.test(str[pos])) {
        name += str[pos];
        pos++;
      }
      return name;
    }
  }

  function readNum(): number {
    let n = 0;
    while (pos < str.length && str[pos] >= '0' && str[pos] <= '9') {
      n = n * 10 + (str[pos].charCodeAt(0) - 48);
      pos++;
    }
    return n;
  }

  function readOffset(): number {
    let sign = 1;
    if (pos < str.length && str[pos] === '+') { pos++; }
    else if (pos < str.length && str[pos] === '-') { sign = -1; pos++; }
    const hh = readNum();
    let mm = 0, ss = 0;
    if (pos < str.length && str[pos] === ':') {
      pos++;
      mm = readNum();
      if (pos < str.length && str[pos] === ':') {
        pos++;
        ss = readNum();
      }
    }
    return sign * (hh * 3600 + mm * 60 + ss);
  }

  function readMwd(): MwdRule {
    pos++; // skip 'M'
    const month = readNum();
    pos++; // skip '.'
    const week = readNum();
    pos++; // skip '.'
    const day = readNum();
    return { month, week, day, time: 7200 }; // default 02:00:00
  }

  const stdName = readName();
  const stdOffset = readOffset();

  let dstName: string | undefined;
  let dstOffset: number | undefined;
  let start: MwdRule | undefined;
  let end: MwdRule | undefined;

  if (pos < str.length && (/[a-zA-Z]/.test(str[pos]) || str[pos] === '<')) {
    dstName = readName();
    if (pos < str.length && (str[pos] === '+' || str[pos] === '-' || (str[pos] >= '0' && str[pos] <= '9'))) {
      dstOffset = readOffset();
    } else {
      dstOffset = stdOffset - 3600;
    }
  }

  if (pos < str.length && str[pos] === ',') {
    pos++; // skip ','
    start = readMwd();
    if (pos < str.length && str[pos] === '/') {
      pos++;
      start.time = readOffset();
    }
    if (pos < str.length && str[pos] === ',') {
      pos++;
      end = readMwd();
      if (pos < str.length && str[pos] === '/') {
        pos++;
        end.time = readOffset();
      }
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, start, end };
}

// ============ Time Zone Lookup ============

interface TypeInfo {
  gmtoff: number;
  abbr: string;
}

function mwdToUnix(rule: MwdRule, year: number, posixOffset: number): number {
  const { month, week, day, time } = rule;
  const dow1 = dayOfWeek(year, month, 1);
  let dayOfMonth: number;
  if (week <= 4) {
    const firstD = 1 + ((day - dow1 + 7) % 7);
    dayOfMonth = firstD + (week - 1) * 7;
  } else {
    const lastDay = daysInMonth(year, month);
    const dowLast = dayOfWeek(year, month, lastDay);
    dayOfMonth = lastDay - ((dowLast - day + 7) % 7);
  }
  return dateToUnix(year, month, dayOfMonth, 0, 0, 0) + time + posixOffset;
}

function getPosixTypeInfo(tzif: TzifData, t: number): TypeInfo {
  if (!tzif.posixTz || tzif.posixTz.trim() === '') {
    if (tzif.types.length > 0) {
      const type = tzif.types[0];
      return { gmtoff: type.gmtoff, abbr: getAbbreviation(tzif, type.abbrIndex) };
    }
    return { gmtoff: 0, abbr: 'UTC' };
  }

  const rule = parsePosixTz(tzif.posixTz);

  if (!rule.dstName || !rule.start || !rule.end || rule.dstOffset === undefined) {
    return { gmtoff: -rule.stdOffset, abbr: rule.stdName };
  }

  const year = unixToDate(t).year;
  const startUtc = mwdToUnix(rule.start, year, rule.stdOffset);
  const endUtc = mwdToUnix(rule.end, year, rule.dstOffset);

  let isDst: boolean;
  if (startUtc <= endUtc) {
    isDst = t >= startUtc && t < endUtc;
  } else {
    isDst = t >= startUtc || t < endUtc;
  }

  if (isDst) {
    return { gmtoff: -rule.dstOffset, abbr: rule.dstName };
  } else {
    return { gmtoff: -rule.stdOffset, abbr: rule.stdName };
  }
}

function getTypeInfo(tzif: TzifData, t: number): TypeInfo {
  if (tzif.transitions.length === 0) {
    return getPosixTypeInfo(tzif, t);
  }

  if (t < tzif.transitions[0]) {
    const type = tzif.types[0];
    return { gmtoff: type.gmtoff, abbr: getAbbreviation(tzif, type.abbrIndex) };
  }

  if (t > tzif.transitions[tzif.transitions.length - 1]) {
    return getPosixTypeInfo(tzif, t);
  }

  // Binary search for latest transition <= t
  let lo = 0, hi = tzif.transitions.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (tzif.transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  const type = tzif.types[tzif.typeIndices[lo]];
  return { gmtoff: type.gmtoff, abbr: getAbbreviation(tzif, type.abbrIndex) };
}

// ============ Formatting ============

function formatDateTime(year: number, month: number, day: number, hour: number, min: number, sec: number): string {
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}T${pad(hour, 2)}:${pad(min, 2)}:${pad(sec, 2)}`;
}

function formatOffset(gmtoff: number): string {
  const sign = gmtoff >= 0 ? '+' : '-';
  const abs = Math.abs(gmtoff);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  if (s !== 0) {
    return `${sign}${pad(h, 2)}:${pad(m, 2)}:${pad(s, 2)}`;
  }
  return `${sign}${pad(h, 2)}:${pad(m, 2)}`;
}

// ============ Gap Detection ============

function findGapTransition(tzif: TzifData, t_as_utc: number): { offBefore: number; offAfter: number } | null {
  // Check file transitions
  for (let i = 0; i < tzif.transitions.length; i++) {
    const T = tzif.transitions[i];
    const gmtoffAfter = tzif.types[tzif.typeIndices[i]].gmtoff;
    let gmtoffBefore: number;
    if (i === 0) {
      gmtoffBefore = tzif.types[0].gmtoff;
    } else {
      gmtoffBefore = tzif.types[tzif.typeIndices[i - 1]].gmtoff;
    }
    if (gmtoffAfter > gmtoffBefore) {
      if (T + gmtoffBefore <= t_as_utc && t_as_utc < T + gmtoffAfter) {
        return { offBefore: gmtoffBefore, offAfter: gmtoffAfter };
      }
    }
  }

  // Check boundary between last file transition and POSIX rules
  if (tzif.transitions.length > 0) {
    const lastT = tzif.transitions[tzif.transitions.length - 1];
    const lastGmtoff = tzif.types[tzif.typeIndices[tzif.transitions.length - 1]].gmtoff;
    const posixInfo = getPosixTypeInfo(tzif, lastT + 1);
    const posixGmtoff = posixInfo.gmtoff;
    if (posixGmtoff > lastGmtoff) {
      const T = lastT + 1;
      if (T + lastGmtoff <= t_as_utc && t_as_utc < T + posixGmtoff) {
        return { offBefore: lastGmtoff, offAfter: posixGmtoff };
      }
    }
  }

  // Check POSIX TZ string transitions (DST start = spring forward)
  if (tzif.posixTz && tzif.posixTz.trim() !== '') {
    const rule = parsePosixTz(tzif.posixTz);
    if (rule.dstName && rule.start && rule.end && rule.dstOffset !== undefined) {
      const stdGmtoff = -rule.stdOffset;
      const dstGmtoff = -rule.dstOffset;
      if (dstGmtoff > stdGmtoff) {
        const year = unixToDate(t_as_utc).year;
        for (let y = year - 1; y <= year + 1; y++) {
          const startUtc = mwdToUnix(rule.start, y, rule.stdOffset);
          if (startUtc + stdGmtoff <= t_as_utc && t_as_utc < startUtc + dstGmtoff) {
            return { offBefore: stdGmtoff, offAfter: dstGmtoff };
          }
        }
      }
    }
  }

  return null;
}

// ============ Query Handling ============

function handleUtcQuery(query: string, tzif: TzifData, t: number): string {
  const info = getTypeInfo(tzif, t);
  const localT = t + info.gmtoff;
  const d = unixToDate(localT);
  const localStr = formatDateTime(d.year, d.month, d.day, d.hour, d.min, d.sec);
  const offsetStr = formatOffset(info.gmtoff);
  return `${query} -> ${localStr}${offsetStr} ${info.abbr}`;
}

function handleLocalQuery(query: string, tzif: TzifData, wallClock: string): string {
  const [datePart, timePart] = wallClock.split('T');
  const [y, m, d] = datePart.split('-').map(Number);
  const [h, min, sec] = timePart.split(':').map(Number);

  const t_as_utc = dateToUnix(y, m, d, h, min, sec);

  // Collect all possible UTC offsets
  const offsets = new Set<number>();
  for (const type of tzif.types) {
    offsets.add(type.gmtoff);
  }
  if (tzif.posixTz && tzif.posixTz.trim() !== '') {
    const rule = parsePosixTz(tzif.posixTz);
    offsets.add(-rule.stdOffset);
    if (rule.dstName && rule.dstOffset !== undefined) {
      offsets.add(-rule.dstOffset);
    }
  }

  // Find all valid Unix times t where localTime(t) == wallClock
  const validTs: number[] = [];
  for (const off of offsets) {
    const t = t_as_utc - off;
    const info = getTypeInfo(tzif, t);
    if (t + info.gmtoff === t_as_utc) {
      validTs.push(t);
    }
  }

  validTs.sort((a, b) => a - b);

  // Deduplicate
  const uniqueTs: number[] = [];
  for (const t of validTs) {
    if (uniqueTs.length === 0 || uniqueTs[uniqueTs.length - 1] !== t) {
      uniqueTs.push(t);
    }
  }

  if (uniqueTs.length === 1) {
    const t = uniqueTs[0];
    const info = getTypeInfo(tzif, t);
    return `${query} -> ${t} ${formatOffset(info.gmtoff)} ${info.abbr}`;
  } else if (uniqueTs.length >= 2) {
    const [t1, t2] = uniqueTs;
    const info1 = getTypeInfo(tzif, t1);
    const info2 = getTypeInfo(tzif, t2);
    return `${query} -> ${t1} ${formatOffset(info1.gmtoff)} ${info1.abbr} | ${t2} ${formatOffset(info2.gmtoff)} ${info2.abbr}`;
  } else {
    // Gap: find the transition that caused it
    const gapInfo = findGapTransition(tzif, t_as_utc);
    if (gapInfo) {
      const t = t_as_utc - gapInfo.offBefore;
      const info = getTypeInfo(tzif, t);
      const localT = t + info.gmtoff;
      const d2 = unixToDate(localT);
      const localStr = formatDateTime(d2.year, d2.month, d2.day, d2.hour, d2.min, d2.sec);
      const offsetStr = formatOffset(info.gmtoff);
      return `${query} -> GAP ${t} ${localStr}${offsetStr} ${info.abbr}`;
    }
    // Fallback (should not happen)
    return `${query} -> GAP 0 1970-01-01T00:00:00+00:00 UTC`;
  }
}

// ============ Main ============

function main() {
  const dir = process.argv[2];
  const queriesPath = path.join(dir, 'queries.txt');
  const content = fs.readFileSync(queriesPath, 'utf-8');
  const lines = content.split('\n').filter(l => l.trim() !== '');

  const tzifCache: Map<string, TzifData> = new Map();

  function getTzif(filename: string): TzifData {
    if (!tzifCache.has(filename)) {
      const buffer = fs.readFileSync(path.join(dir, filename));
      tzifCache.set(filename, parseTzif(buffer));
    }
    return tzifCache.get(filename)!;
  }

  const output: string[] = [];

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (line === '') continue;
    const parts = line.split(' ');
    const qtype = parts[0];
    const filename = parts[1];
    const value = parts[2];

    const tzif = getTzif(filename);

    if (qtype === 'UTC') {
      const t = parseInt(value, 10);
      output.push(handleUtcQuery(line, tzif, t));
    } else if (qtype === 'LOCAL') {
      output.push(handleLocalQuery(line, tzif, value));
    }
  }

  process.stdout.write(output.join('\n') + '\n');
}

main();

use std::collections::HashMap;
use std::env;
use std::fs;

struct LocalTimeType {
    gmtoff: i32,
    isdst: u8,
    abbridx: u8,
}

struct TzifData {
    transitions: Vec<i64>,
    type_indices: Vec<u8>,
    types: Vec<LocalTimeType>,
    abbreviations: Vec<u8>,
    posix_rule: Option<PosixRule>,
}

struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start: Option<RuleTime>,
    end: Option<RuleTime>,
}

struct RuleTime {
    month: u32,
    week: u32,
    dow: u32,
    time: i32,
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp as i64 + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn day_of_week(year: i64, month: u32, day: u32) -> u32 {
    let days = days_from_civil(year, month, day);
    ((days % 7 + 7) % 7 + 4) % 7
}

fn days_in_month(year: i64, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 { 29 } else { 28 }
        }
        _ => 31,
    }
}

fn read_be_i32(data: &[u8], offset: usize) -> i32 {
    i32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_be_i64(data: &[u8], offset: usize) -> i64 {
    i64::from_be_bytes([
        data[offset], data[offset + 1], data[offset + 2], data[offset + 3],
        data[offset + 4], data[offset + 5], data[offset + 6], data[offset + 7],
    ])
}

fn parse_tzif(path: &str) -> TzifData {
    let data = fs::read(path).unwrap();

    let isutcnt1 = read_be_i32(&data, 20) as usize;
    let isstdcnt1 = read_be_i32(&data, 24) as usize;
    let leapcnt1 = read_be_i32(&data, 28) as usize;
    let timecnt1 = read_be_i32(&data, 32) as usize;
    let typecnt1 = read_be_i32(&data, 36) as usize;
    let charcnt1 = read_be_i32(&data, 40) as usize;

    let block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

    let off2 = 44 + block1_size;
    let isutcnt2 = read_be_i32(&data, off2 + 20) as usize;
    let isstdcnt2 = read_be_i32(&data, off2 + 24) as usize;
    let leapcnt2 = read_be_i32(&data, off2 + 28) as usize;
    let timecnt2 = read_be_i32(&data, off2 + 32) as usize;
    let typecnt2 = read_be_i32(&data, off2 + 36) as usize;
    let charcnt2 = read_be_i32(&data, off2 + 40) as usize;

    let mut pos = off2 + 44;

    let mut transitions = Vec::with_capacity(timecnt2);
    for i in 0..timecnt2 {
        transitions.push(read_be_i64(&data, pos + i * 8));
    }
    pos += timecnt2 * 8;

    let mut type_indices = Vec::with_capacity(timecnt2);
    for i in 0..timecnt2 {
        type_indices.push(data[pos + i]);
    }
    pos += timecnt2;

    let mut types = Vec::with_capacity(typecnt2);
    for i in 0..typecnt2 {
        let gmtoff = read_be_i32(&data, pos + i * 6);
        let isdst = data[pos + i * 6 + 4];
        let abbridx = data[pos + i * 6 + 5];
        types.push(LocalTimeType { gmtoff, isdst, abbridx });
    }
    pos += typecnt2 * 6;

    let abbreviations = data[pos..pos + charcnt2].to_vec();
    pos += charcnt2;

    pos += leapcnt2 * 12;
    pos += isstdcnt2;
    pos += isutcnt2;

    if pos < data.len() && data[pos] == b'\n' {
        pos += 1;
    }
    let footer_start = pos;
    while pos < data.len() && data[pos] != b'\n' {
        pos += 1;
    }
    let footer = String::from_utf8_lossy(&data[footer_start..pos]).to_string();

    let posix_rule = if footer.is_empty() {
        None
    } else {
        parse_posix_tz(&footer)
    };

    TzifData { transitions, type_indices, types, abbreviations, posix_rule }
}

fn parse_posix_tz(s: &str) -> Option<PosixRule> {
    let bytes = s.as_bytes();
    let mut pos = 0usize;

    let std_name = parse_tz_name(bytes, &mut pos)?;
    let std_offset = parse_tz_offset(bytes, &mut pos)?;

    if pos >= bytes.len() {
        return Some(PosixRule {
            std_name, std_offset,
            dst_name: None, dst_offset: None,
            start: None, end: None,
        });
    }

    let dst_name = parse_tz_name(bytes, &mut pos)?;

    let dst_offset = if pos < bytes.len() && (bytes[pos] == b'+' || bytes[pos] == b'-' || bytes[pos].is_ascii_digit()) {
        parse_tz_offset(bytes, &mut pos)?
    } else {
        std_offset - 3600
    };

    if pos < bytes.len() && bytes[pos] == b',' {
        pos += 1;
        let start = parse_rule_time(bytes, &mut pos)?;
        if pos < bytes.len() && bytes[pos] == b',' {
            pos += 1;
        }
        let end = parse_rule_time(bytes, &mut pos)?;
        Some(PosixRule {
            std_name, std_offset,
            dst_name: Some(dst_name), dst_offset: Some(dst_offset),
            start: Some(start), end: Some(end),
        })
    } else {
        Some(PosixRule {
            std_name, std_offset,
            dst_name: Some(dst_name), dst_offset: Some(dst_offset),
            start: None, end: None,
        })
    }
}

fn parse_tz_name(bytes: &[u8], pos: &mut usize) -> Option<String> {
    if *pos >= bytes.len() { return None; }
    if bytes[*pos] == b'<' {
        *pos += 1;
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos] != b'>' {
            *pos += 1;
        }
        let name = String::from_utf8_lossy(&bytes[start..*pos]).to_string();
        if *pos < bytes.len() { *pos += 1; }
        Some(name)
    } else {
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos].is_ascii_alphabetic() {
            *pos += 1;
        }
        if *pos - start < 3 { return None; }
        Some(String::from_utf8_lossy(&bytes[start..*pos]).to_string())
    }
}

fn parse_tz_offset(bytes: &[u8], pos: &mut usize) -> Option<i32> {
    let sign: i32 = if *pos < bytes.len() && bytes[*pos] == b'-' {
        *pos += 1; -1
    } else if *pos < bytes.len() && bytes[*pos] == b'+' {
        *pos += 1; 1
    } else {
        1
    };

    let h = parse_number(bytes, pos)?;
    let mut m = 0i32;
    let mut s = 0i32;
    if *pos < bytes.len() && bytes[*pos] == b':' {
        *pos += 1;
        m = parse_number(bytes, pos)?;
        if *pos < bytes.len() && bytes[*pos] == b':' {
            *pos += 1;
            s = parse_number(bytes, pos)?;
        }
    }

    Some(sign * (h * 3600 + m * 60 + s))
}

fn parse_number(bytes: &[u8], pos: &mut usize) -> Option<i32> {
    let start = *pos;
    while *pos < bytes.len() && bytes[*pos].is_ascii_digit() {
        *pos += 1;
    }
    if *pos == start { return None; }
    let s = std::str::from_utf8(&bytes[start..*pos]).ok()?;
    s.parse().ok()
}

fn parse_rule_time(bytes: &[u8], pos: &mut usize) -> Option<RuleTime> {
    if *pos >= bytes.len() || bytes[*pos] != b'M' { return None; }
    *pos += 1;

    let month = parse_number(bytes, pos)? as u32;
    if *pos < bytes.len() && bytes[*pos] == b'.' { *pos += 1; }
    let week = parse_number(bytes, pos)? as u32;
    if *pos < bytes.len() && bytes[*pos] == b'.' { *pos += 1; }
    let dow = parse_number(bytes, pos)? as u32;

    let time = if *pos < bytes.len() && bytes[*pos] == b'/' {
        *pos += 1;
        parse_tz_offset(bytes, pos)?
    } else {
        2 * 3600
    };

    Some(RuleTime { month, week, dow, time })
}

fn rule_to_date(year: i64, rule: &RuleTime) -> (i64, u32, u32) {
    let m = rule.month;
    let w = rule.week;
    let d = rule.dow;

    let first_dow = day_of_week(year, m, 1);
    let mut day: i64 = 1 + ((d as i64 - first_dow as i64 + 7) % 7);

    if w == 5 {
        let dim = days_in_month(year, m) as i64;
        while day + 7 <= dim {
            day += 7;
        }
    } else {
        day += (w as i64 - 1) * 7;
    }

    (year, m, day as u32)
}

fn get_abbr(tzif: &TzifData, type_idx: usize) -> String {
    let start = tzif.types[type_idx].abbridx as usize;
    let mut end = start;
    while end < tzif.abbreviations.len() && tzif.abbreviations[end] != 0 {
        end += 1;
    }
    String::from_utf8_lossy(&tzif.abbreviations[start..end]).to_string()
}

fn get_footer_type(t: i64, rule: &PosixRule) -> (i32, String) {
    let std_gmtoff = -rule.std_offset;
    if rule.dst_name.is_none() || rule.start.is_none() || rule.end.is_none() {
        return (std_gmtoff, rule.std_name.clone());
    }
    let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
    let dst_gmtoff = -dst_off_val;

    let (year, _, _) = civil_from_days(t.div_euclid(86400));

    let start_rule = rule.start.as_ref().unwrap();
    let end_rule = rule.end.as_ref().unwrap();

    let mut trans: Vec<(i64, i32, String)> = Vec::new();

    for y in (year - 2)..=(year + 2) {
        let (sy, sm, sd) = rule_to_date(y, start_rule);
        let start_ts = days_from_civil(sy, sm, sd) * 86400 + start_rule.time as i64 + rule.std_offset as i64;
        trans.push((start_ts, dst_gmtoff, rule.dst_name.clone().unwrap()));

        let (ey, em, ed) = rule_to_date(y, end_rule);
        let end_ts = days_from_civil(ey, em, ed) * 86400 + end_rule.time as i64 + dst_off_val as i64;
        trans.push((end_ts, std_gmtoff, rule.std_name.clone()));
    }

    trans.sort_by_key(|&(t, _, _)| t);

    let mut result = (std_gmtoff, rule.std_name.clone());
    for &(ts, gmtoff, ref abbr) in &trans {
        if ts <= t {
            result = (gmtoff, abbr.clone());
        } else {
            break;
        }
    }

    result
}

fn get_type_at(t: i64, tzif: &TzifData) -> (i32, String) {
    if tzif.transitions.is_empty() {
        if let Some(ref rule) = tzif.posix_rule {
            return get_footer_type(t, rule);
        }
        return (tzif.types[0].gmtoff, get_abbr(tzif, 0));
    }
    if t < tzif.transitions[0] {
        return (tzif.types[0].gmtoff, get_abbr(tzif, 0));
    }
    if t > *tzif.transitions.last().unwrap() {
        if let Some(ref rule) = tzif.posix_rule {
            return get_footer_type(t, rule);
        }
        let last_idx = tzif.transitions.len() - 1;
        let type_idx = tzif.type_indices[last_idx] as usize;
        return (tzif.types[type_idx].gmtoff, get_abbr(tzif, type_idx));
    }
    let idx = match tzif.transitions.binary_search(&t) {
        Ok(i) => i,
        Err(i) => i - 1,
    };
    let type_idx = tzif.type_indices[idx] as usize;
    (tzif.types[type_idx].gmtoff, get_abbr(tzif, type_idx))
}

fn local_to_utc(wall: i64, tzif: &TzifData) -> Vec<(i64, i32, String)> {
    let mut offsets: Vec<i32> = Vec::new();
    for t in &tzif.types {
        if !offsets.contains(&t.gmtoff) {
            offsets.push(t.gmtoff);
        }
    }
    if let Some(ref rule) = tzif.posix_rule {
        let std_gmtoff = -rule.std_offset;
        let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
        let dst_gmtoff = -dst_off_val;
        if !offsets.contains(&std_gmtoff) { offsets.push(std_gmtoff); }
        if !offsets.contains(&dst_gmtoff) { offsets.push(dst_gmtoff); }
    }

    let mut results: Vec<(i64, i32, String)> = Vec::new();
    for &g in &offsets {
        let t = wall - g as i64;
        let (actual_g, abbr) = get_type_at(t, tzif);
        if actual_g == g {
            results.push((t, g, abbr));
        }
    }

    results.sort_by_key(|&(t, _, _)| t);
    results
}

fn find_gap_transition(wall: i64, tzif: &TzifData) -> Option<(i64, i32)> {
    // Check TZif transitions
    for i in 0..tzif.transitions.len() {
        let t = tzif.transitions[i];
        let new_type_idx = tzif.type_indices[i] as usize;
        let new_gmtoff = tzif.types[new_type_idx].gmtoff;

        let old_gmtoff = if i == 0 {
            tzif.types[0].gmtoff
        } else {
            let prev_type_idx = tzif.type_indices[i - 1] as usize;
            tzif.types[prev_type_idx].gmtoff
        };

        if new_gmtoff > old_gmtoff {
            if wall >= t + old_gmtoff as i64 && wall < t + new_gmtoff as i64 {
                return Some((t, old_gmtoff));
            }
        }
    }

    // Check footer transitions
    if let Some(ref rule) = tzif.posix_rule {
        if let (Some(ref start_rule), Some(ref end_rule)) = (&rule.start, &rule.end) {
            let std_gmtoff = -rule.std_offset;
            let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
            let dst_gmtoff = -dst_off_val;

            let (year, _, _) = civil_from_days(wall.div_euclid(86400));

            if dst_gmtoff > std_gmtoff {
                for y in (year - 1)..=(year + 1) {
                    let (sy, sm, sd) = rule_to_date(y, start_rule);
                    let start_ts = days_from_civil(sy, sm, sd) * 86400 + start_rule.time as i64 + rule.std_offset as i64;
                    if wall >= start_ts + std_gmtoff as i64 && wall < start_ts + dst_gmtoff as i64 {
                        return Some((start_ts, std_gmtoff));
                    }
                }
            }

            if std_gmtoff > dst_gmtoff {
                for y in (year - 1)..=(year + 1) {
                    let (ey, em, ed) = rule_to_date(y, end_rule);
                    let end_ts = days_from_civil(ey, em, ed) * 86400 + end_rule.time as i64 + dst_off_val as i64;
                    if wall >= end_ts + dst_gmtoff as i64 && wall < end_ts + std_gmtoff as i64 {
                        return Some((end_ts, dst_gmtoff));
                    }
                }
            }
        }
    }

    None
}

fn format_offset(gmtoff: i32) -> String {
    let sign = if gmtoff >= 0 { '+' } else { '-' };
    let abs = gmtoff.unsigned_abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn parse_datetime(s: &str) -> (i64, u32, u32, u32, u32, u32) {
    let year: i64 = s[0..4].parse().unwrap();
    let month: u32 = s[5..7].parse().unwrap();
    let day: u32 = s[8..10].parse().unwrap();
    let hour: u32 = s[11..13].parse().unwrap();
    let min: u32 = s[14..16].parse().unwrap();
    let sec: u32 = s[17..19].parse().unwrap();
    (year, month, day, hour, min, sec)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let queries_content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();

    let mut tzif_cache: HashMap<String, TzifData> = HashMap::new();

    for line in queries_content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        let query_type = parts[0];
        let filename = parts[1];

        let tzif = tzif_cache.entry(filename.to_string())
            .or_insert_with(|| parse_tzif(&format!("{}/{}", dir, filename)));

        match query_type {
            "UTC" => {
                let t: i64 = parts[2].parse().unwrap();
                let (gmtoff, abbr) = get_type_at(t, tzif);
                let local = t + gmtoff as i64;
                let total_secs = local.rem_euclid(86400);
                let days = local.div_euclid(86400);
                let (year, month, day) = civil_from_days(days);
                let hour = (total_secs / 3600) as u32;
                let min = ((total_secs % 3600) / 60) as u32;
                let sec = (total_secs % 60) as u32;
                println!("{} -> {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}",
                    trimmed, year, month, day, hour, min, sec, format_offset(gmtoff), abbr);
            }
            "LOCAL" => {
                let wall_str = parts[2];
                let (year, month, day, hour, min, sec) = parse_datetime(wall_str);
                let wall_secs = days_from_civil(year, month, day) * 86400
                    + (hour as i64) * 3600 + (min as i64) * 60 + (sec as i64);

                let results = local_to_utc(wall_secs, tzif);

                if results.len() == 1 {
                    let (t, gmtoff, ref abbr) = results[0];
                    println!("{} -> {} {} {}", trimmed, t, format_offset(gmtoff), abbr);
                } else if results.len() >= 2 {
                    let (t1, g1, ref a1) = results[0];
                    let (t2, g2, ref a2) = results[1];
                    println!("{} -> {} {} {} | {} {} {}",
                        trimmed, t1, format_offset(g1), a1, t2, format_offset(g2), a2);
                } else {
                    let (_, old_gmtoff) = find_gap_transition(wall_secs, tzif).unwrap();
                    let t = wall_secs - old_gmtoff as i64;
                    let (gmtoff, abbr) = get_type_at(t, tzif);
                    let local = t + gmtoff as i64;
                    let total_secs = local.rem_euclid(86400);
                    let days = local.div_euclid(86400);
                    let (year, month, day) = civil_from_days(days);
                    let hour = (total_secs / 3600) as u32;
                    let min = ((total_secs % 3600) / 60) as u32;
                    let sec = (total_secs % 60) as u32;
                    println!("{} -> GAP {} {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}",
                        trimmed, t, year, month, day, hour, min, sec, format_offset(gmtoff), abbr);
                }
            }
            _ => {}
        }
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;

struct LocalTimeType {
    gmtoff: i32,
    isdst: u8,
    abbridx: u8,
}

struct TzifData {
    transitions: Vec<i64>,
    type_indices: Vec<u8>,
    types: Vec<LocalTimeType>,
    abbreviations: Vec<u8>,
    posix_rule: Option<PosixRule>,
}

struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start: Option<RuleTime>,
    end: Option<RuleTime>,
}

struct RuleTime {
    month: u32,
    week: u32,
    dow: u32,
    time: i32,
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp as i64 + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn day_of_week(year: i64, month: u32, day: u32) -> u32 {
    let days = days_from_civil(year, month, day);
    (((days % 7 + 7) % 7 + 4) % 7) as u32
}

fn days_in_month(year: i64, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 { 29 } else { 28 }
        }
        _ => 31,
    }
}

fn read_be_i32(data: &[u8], offset: usize) -> i32 {
    i32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_be_i64(data: &[u8], offset: usize) -> i64 {
    i64::from_be_bytes([
        data[offset], data[offset + 1], data[offset + 2], data[offset + 3],
        data[offset + 4], data[offset + 5], data[offset + 6], data[offset + 7],
    ])
}

fn parse_tzif(path: &str) -> TzifData {
    let data = fs::read(path).unwrap();

    let isutcnt1 = read_be_i32(&data, 20) as usize;
    let isstdcnt1 = read_be_i32(&data, 24) as usize;
    let leapcnt1 = read_be_i32(&data, 28) as usize;
    let timecnt1 = read_be_i32(&data, 32) as usize;
    let typecnt1 = read_be_i32(&data, 36) as usize;
    let charcnt1 = read_be_i32(&data, 40) as usize;

    let block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

    let off2 = 44 + block1_size;
    let isutcnt2 = read_be_i32(&data, off2 + 20) as usize;
    let isstdcnt2 = read_be_i32(&data, off2 + 24) as usize;
    let leapcnt2 = read_be_i32(&data, off2 + 28) as usize;
    let timecnt2 = read_be_i32(&data, off2 + 32) as usize;
    let typecnt2 = read_be_i32(&data, off2 + 36) as usize;
    let charcnt2 = read_be_i32(&data, off2 + 40) as usize;

    let mut pos = off2 + 44;

    let mut transitions = Vec::with_capacity(timecnt2);
    for i in 0..timecnt2 {
        transitions.push(read_be_i64(&data, pos + i * 8));
    }
    pos += timecnt2 * 8;

    let mut type_indices = Vec::with_capacity(timecnt2);
    for i in 0..timecnt2 {
        type_indices.push(data[pos + i]);
    }
    pos += timecnt2;

    let mut types = Vec::with_capacity(typecnt2);
    for i in 0..typecnt2 {
        let gmtoff = read_be_i32(&data, pos + i * 6);
        let isdst = data[pos + i * 6 + 4];
        let abbridx = data[pos + i * 6 + 5];
        types.push(LocalTimeType { gmtoff, isdst, abbridx });
    }
    pos += typecnt2 * 6;

    let abbreviations = data[pos..pos + charcnt2].to_vec();
    pos += charcnt2;

    pos += leapcnt2 * 12;
    pos += isstdcnt2;
    pos += isutcnt2;

    if pos < data.len() && data[pos] == b'\n' {
        pos += 1;
    }
    let footer_start = pos;
    while pos < data.len() && data[pos] != b'\n' {
        pos += 1;
    }
    let footer = String::from_utf8_lossy(&data[footer_start..pos]).to_string();

    let posix_rule = if footer.is_empty() {
        None
    } else {
        parse_posix_tz(&footer)
    };

    TzifData { transitions, type_indices, types, abbreviations, posix_rule }
}

fn parse_posix_tz(s: &str) -> Option<PosixRule> {
    let bytes = s.as_bytes();
    let mut pos = 0usize;

    let std_name = parse_tz_name(bytes, &mut pos)?;
    let std_offset = parse_tz_offset(bytes, &mut pos)?;

    if pos >= bytes.len() {
        return Some(PosixRule {
            std_name, std_offset,
            dst_name: None, dst_offset: None,
            start: None, end: None,
        });
    }

    let dst_name = parse_tz_name(bytes, &mut pos)?;

    let dst_offset = if pos < bytes.len() && (bytes[pos] == b'+' || bytes[pos] == b'-' || bytes[pos].is_ascii_digit()) {
        parse_tz_offset(bytes, &mut pos)?
    } else {
        std_offset - 3600
    };

    if pos < bytes.len() && bytes[pos] == b',' {
        pos += 1;
        let start = parse_rule_time(bytes, &mut pos)?;
        if pos < bytes.len() && bytes[pos] == b',' {
            pos += 1;
        }
        let end = parse_rule_time(bytes, &mut pos)?;
        Some(PosixRule {
            std_name, std_offset,
            dst_name: Some(dst_name), dst_offset: Some(dst_offset),
            start: Some(start), end: Some(end),
        })
    } else {
        Some(PosixRule {
            std_name, std_offset,
            dst_name: Some(dst_name), dst_offset: Some(dst_offset),
            start: None, end: None,
        })
    }
}

fn parse_tz_name(bytes: &[u8], pos: &mut usize) -> Option<String> {
    if *pos >= bytes.len() { return None; }
    if bytes[*pos] == b'<' {
        *pos += 1;
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos] != b'>' {
            *pos += 1;
        }
        let name = String::from_utf8_lossy(&bytes[start..*pos]).to_string();
        if *pos < bytes.len() { *pos += 1; }
        Some(name)
    } else {
        let start = *pos;
        while *pos < bytes.len() && bytes[*pos].is_ascii_alphabetic() {
            *pos += 1;
        }
        if *pos - start < 3 { return None; }
        Some(String::from_utf8_lossy(&bytes[start..*pos]).to_string())
    }
}

fn parse_tz_offset(bytes: &[u8], pos: &mut usize) -> Option<i32> {
    let sign: i32 = if *pos < bytes.len() && bytes[*pos] == b'-' {
        *pos += 1; -1
    } else if *pos < bytes.len() && bytes[*pos] == b'+' {
        *pos += 1; 1
    } else {
        1
    };

    let h = parse_number(bytes, pos)?;
    let mut m = 0i32;
    let mut s = 0i32;
    if *pos < bytes.len() && bytes[*pos] == b':' {
        *pos += 1;
        m = parse_number(bytes, pos)?;
        if *pos < bytes.len() && bytes[*pos] == b':' {
            *pos += 1;
            s = parse_number(bytes, pos)?;
        }
    }

    Some(sign * (h * 3600 + m * 60 + s))
}

fn parse_number(bytes: &[u8], pos: &mut usize) -> Option<i32> {
    let start = *pos;
    while *pos < bytes.len() && bytes[*pos].is_ascii_digit() {
        *pos += 1;
    }
    if *pos == start { return None; }
    let s = std::str::from_utf8(&bytes[start..*pos]).ok()?;
    s.parse().ok()
}

fn parse_rule_time(bytes: &[u8], pos: &mut usize) -> Option<RuleTime> {
    if *pos >= bytes.len() || bytes[*pos] != b'M' { return None; }
    *pos += 1;

    let month = parse_number(bytes, pos)? as u32;
    if *pos < bytes.len() && bytes[*pos] == b'.' { *pos += 1; }
    let week = parse_number(bytes, pos)? as u32;
    if *pos < bytes.len() && bytes[*pos] == b'.' { *pos += 1; }
    let dow = parse_number(bytes, pos)? as u32;

    let time = if *pos < bytes.len() && bytes[*pos] == b'/' {
        *pos += 1;
        parse_tz_offset(bytes, pos)?
    } else {
        2 * 3600
    };

    Some(RuleTime { month, week, dow, time })
}

fn rule_to_date(year: i64, rule: &RuleTime) -> (i64, u32, u32) {
    let m = rule.month;
    let w = rule.week;
    let d = rule.dow;

    let first_dow = day_of_week(year, m, 1);
    let mut day: i64 = 1 + ((d as i64 - first_dow as i64 + 7) % 7);

    if w == 5 {
        let dim = days_in_month(year, m) as i64;
        while day + 7 <= dim {
            day += 7;
        }
    } else {
        day += (w as i64 - 1) * 7;
    }

    (year, m, day as u32)
}

fn get_abbr(tzif: &TzifData, type_idx: usize) -> String {
    let start = tzif.types[type_idx].abbridx as usize;
    let mut end = start;
    while end < tzif.abbreviations.len() && tzif.abbreviations[end] != 0 {
        end += 1;
    }
    String::from_utf8_lossy(&tzif.abbreviations[start..end]).to_string()
}

fn get_footer_type(t: i64, rule: &PosixRule) -> (i32, String) {
    let std_gmtoff = -rule.std_offset;
    if rule.dst_name.is_none() || rule.start.is_none() || rule.end.is_none() {
        return (std_gmtoff, rule.std_name.clone());
    }
    let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
    let dst_gmtoff = -dst_off_val;

    let (year, _, _) = civil_from_days(t.div_euclid(86400));

    let start_rule = rule.start.as_ref().unwrap();
    let end_rule = rule.end.as_ref().unwrap();

    let mut trans: Vec<(i64, i32, String)> = Vec::new();

    for y in (year - 2)..=(year + 2) {
        let (sy, sm, sd) = rule_to_date(y, start_rule);
        let start_ts = days_from_civil(sy, sm, sd) * 86400 + start_rule.time as i64 + rule.std_offset as i64;
        trans.push((start_ts, dst_gmtoff, rule.dst_name.clone().unwrap()));

        let (ey, em, ed) = rule_to_date(y, end_rule);
        let end_ts = days_from_civil(ey, em, ed) * 86400 + end_rule.time as i64 + dst_off_val as i64;
        trans.push((end_ts, std_gmtoff, rule.std_name.clone()));
    }

    trans.sort_by_key(|&(t, _, _)| t);

    let mut result = (std_gmtoff, rule.std_name.clone());
    for &(ts, gmtoff, ref abbr) in &trans {
        if ts <= t {
            result = (gmtoff, abbr.clone());
        } else {
            break;
        }
    }

    result
}

fn get_type_at(t: i64, tzif: &TzifData) -> (i32, String) {
    if tzif.transitions.is_empty() {
        if let Some(ref rule) = tzif.posix_rule {
            return get_footer_type(t, rule);
        }
        return (tzif.types[0].gmtoff, get_abbr(tzif, 0));
    }
    if t < tzif.transitions[0] {
        return (tzif.types[0].gmtoff, get_abbr(tzif, 0));
    }
    if t > *tzif.transitions.last().unwrap() {
        if let Some(ref rule) = tzif.posix_rule {
            return get_footer_type(t, rule);
        }
        let last_idx = tzif.transitions.len() - 1;
        let type_idx = tzif.type_indices[last_idx] as usize;
        return (tzif.types[type_idx].gmtoff, get_abbr(tzif, type_idx));
    }
    let idx = match tzif.transitions.binary_search(&t) {
        Ok(i) => i,
        Err(i) => i - 1,
    };
    let type_idx = tzif.type_indices[idx] as usize;
    (tzif.types[type_idx].gmtoff, get_abbr(tzif, type_idx))
}

fn local_to_utc(wall: i64, tzif: &TzifData) -> Vec<(i64, i32, String)> {
    let mut offsets: Vec<i32> = Vec::new();
    for t in &tzif.types {
        if !offsets.contains(&t.gmtoff) {
            offsets.push(t.gmtoff);
        }
    }
    if let Some(ref rule) = tzif.posix_rule {
        let std_gmtoff = -rule.std_offset;
        let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
        let dst_gmtoff = -dst_off_val;
        if !offsets.contains(&std_gmtoff) { offsets.push(std_gmtoff); }
        if !offsets.contains(&dst_gmtoff) { offsets.push(dst_gmtoff); }
    }

    let mut results: Vec<(i64, i32, String)> = Vec::new();
    for &g in &offsets {
        let t = wall - g as i64;
        let (actual_g, abbr) = get_type_at(t, tzif);
        if actual_g == g {
            results.push((t, g, abbr));
        }
    }

    results.sort_by_key(|&(t, _, _)| t);
    results
}

fn find_gap_transition(wall: i64, tzif: &TzifData) -> Option<(i64, i32)> {
    // Check TZif transitions
    for i in 0..tzif.transitions.len() {
        let t = tzif.transitions[i];
        let new_type_idx = tzif.type_indices[i] as usize;
        let new_gmtoff = tzif.types[new_type_idx].gmtoff;

        let old_gmtoff = if i == 0 {
            tzif.types[0].gmtoff
        } else {
            let prev_type_idx = tzif.type_indices[i - 1] as usize;
            tzif.types[prev_type_idx].gmtoff
        };

        if new_gmtoff > old_gmtoff {
            if wall >= t + old_gmtoff as i64 && wall < t + new_gmtoff as i64 {
                return Some((t, old_gmtoff));
            }
        }
    }

    // Check footer transitions
    if let Some(ref rule) = tzif.posix_rule {
        if let (Some(ref start_rule), Some(ref end_rule)) = (&rule.start, &rule.end) {
            let std_gmtoff = -rule.std_offset;
            let dst_off_val = rule.dst_offset.unwrap_or(rule.std_offset - 3600);
            let dst_gmtoff = -dst_off_val;

            let (year, _, _) = civil_from_days(wall.div_euclid(86400));

            if dst_gmtoff > std_gmtoff {
                for y in (year - 1)..=(year + 1) {
                    let (sy, sm, sd) = rule_to_date(y, start_rule);
                    let start_ts = days_from_civil(sy, sm, sd) * 86400 + start_rule.time as i64 + rule.std_offset as i64;
                    if wall >= start_ts + std_gmtoff as i64 && wall < start_ts + dst_gmtoff as i64 {
                        return Some((start_ts, std_gmtoff));
                    }
                }
            }

            if std_gmtoff > dst_gmtoff {
                for y in (year - 1)..=(year + 1) {
                    let (ey, em, ed) = rule_to_date(y, end_rule);
                    let end_ts = days_from_civil(ey, em, ed) * 86400 + end_rule.time as i64 + dst_off_val as i64;
                    if wall >= end_ts + dst_gmtoff as i64 && wall < end_ts + std_gmtoff as i64 {
                        return Some((end_ts, dst_gmtoff));
                    }
                }
            }
        }
    }

    None
}

fn format_offset(gmtoff: i32) -> String {
    let sign = if gmtoff >= 0 { '+' } else { '-' };
    let abs = gmtoff.unsigned_abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn parse_datetime(s: &str) -> (i64, u32, u32, u32, u32, u32) {
    let year: i64 = s[0..4].parse().unwrap();
    let month: u32 = s[5..7].parse().unwrap();
    let day: u32 = s[8..10].parse().unwrap();
    let hour: u32 = s[11..13].parse().unwrap();
    let min: u32 = s[14..16].parse().unwrap();
    let sec: u32 = s[17..19].parse().unwrap();
    (year, month, day, hour, min, sec)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let queries_content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();

    let mut tzif_cache: HashMap<String, TzifData> = HashMap::new();

    for line in queries_content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        let query_type = parts[0];
        let filename = parts[1];

        let tzif = tzif_cache.entry(filename.to_string())
            .or_insert_with(|| parse_tzif(&format!("{}/{}", dir, filename)));

        match query_type {
            "UTC" => {
                let t: i64 = parts[2].parse().unwrap();
                let (gmtoff, abbr) = get_type_at(t, tzif);
                let local = t + gmtoff as i64;
                let total_secs = local.rem_euclid(86400);
                let days = local.div_euclid(86400);
                let (year, month, day) = civil_from_days(days);
                let hour = (total_secs / 3600) as u32;
                let min = ((total_secs % 3600) / 60) as u32;
                let sec = (total_secs % 60) as u32;
                println!("{} -> {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}",
                    trimmed, year, month, day, hour, min, sec, format_offset(gmtoff), abbr);
            }
            "LOCAL" => {
                let wall_str = parts[2];
                let (year, month, day, hour, min, sec) = parse_datetime(wall_str);
                let wall_secs = days_from_civil(year, month, day) * 86400
                    + (hour as i64) * 3600 + (min as i64) * 60 + (sec as i64);

                let results = local_to_utc(wall_secs, tzif);

                if results.len() == 1 {
                    let (t, gmtoff, ref abbr) = results[0];
                    println!("{} -> {} {} {}", trimmed, t, format_offset(gmtoff), abbr);
                } else if results.len() >= 2 {
                    let (t1, g1, ref a1) = results[0];
                    let (t2, g2, ref a2) = results[1];
                    println!("{} -> {} {} {} | {} {} {}",
                        trimmed, t1, format_offset(g1), a1, t2, format_offset(g2), a2);
                } else {
                    let (_, old_gmtoff) = find_gap_transition(wall_secs, tzif).unwrap();
                    let t = wall_secs - old_gmtoff as i64;
                    let (gmtoff, abbr) = get_type_at(t, tzif);
                    let local = t + gmtoff as i64;
                    let total_secs = local.rem_euclid(86400);
                    let days = local.div_euclid(86400);
                    let (year, month, day) = civil_from_days(days);
                    let hour = (total_secs / 3600) as u32;
                    let min = ((total_secs % 3600) / 60) as u32;
                    let sec = (total_secs % 60) as u32;
                    println!("{} -> GAP {} {:04}-{:02}-{:02}T{:02}:{:02}:{:02}{} {}",
                        trimmed, t, year, month, day, hour, min, sec, format_offset(gmtoff), abbr);
                }
            }
            _ => {}
        }
    }
}

import Foundation
import CryptoKit

// MARK: - SHA-1 helpers

func sha1Hex(_ bytes: [UInt8]) -> String {
    let digest = Insecure.SHA1.hash(data: Data(bytes))
    return digest.map { String(format: "%02x", $0) }.joined()
}

func computeAccept(key: String) -> String {
    let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    let combined = key + magic
    let digest = Insecure.SHA1.hash(data: Data(combined.utf8))
    return Data(digest).base64EncodedString()
}

// MARK: - Reverse by code point

func reverseByCodePoint(_ s: String) -> String {
    var result = ""
    for scalar in s.unicodeScalars.reversed() {
        result.unicodeScalars.append(scalar)
    }
    return result
}

// MARK: - Socket operations

func makeSocket(host: String, port: UInt16) -> Int32 {
    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    precondition(fd >= 0, "socket() failed")
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)
    let result = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockPtr in
            connect(fd, sockPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    precondition(result == 0, "connect() failed")
    return fd
}

func sendAll(fd: Int32, data: [UInt8]) {
    var offset = 0
    while offset < data.count {
        let n = data.withUnsafeBytes { buf in
            Darwin.send(fd, buf.baseAddress!.advanced(by: offset), data.count - offset, 0)
        }
        if n < 0 {
            if errno == EINTR { continue }
            preconditionFailure("send() failed")
        }
        offset += n
    }
}

// MARK: - Buffered Reader

final class BufferedReader {
    let fd: Int32
    var buffer: [UInt8] = []
    var pos: Int = 0

    init(fd: Int32) {
        self.fd = fd
    }

    func fill(minBytes: Int) -> Bool {
        while (buffer.count - pos) < minBytes {
            if pos > 0 {
                buffer.removeFirst(pos)
                pos = 0
            }
            var tmp = [UInt8](repeating: 0, count: 65536)
            let n = tmp.withUnsafeMutableBufferPointer { buf in
                recv(fd, buf.baseAddress, buf.count, 0)
            }
            if n < 0 {
                if errno == EINTR { continue }
                return false
            }
            if n == 0 { return false }
            buffer.append(contentsOf: tmp[0..<n])
        }
        return true
    }

    func readByte() -> UInt8? {
        if !fill(minBytes: 1) { return nil }
        let b = buffer[pos]
        pos += 1
        return b
    }

    func readBytes(_ n: Int) -> [UInt8]? {
        if n == 0 { return [] }
        if !fill(minBytes: n) { return nil }
        let result = Array(buffer[pos..<(pos + n)])
        pos += n
        return result
    }

    func readLine() -> String? {
        var line: [UInt8] = []
        while true {
            guard let b = readByte() else { return nil }
            line.append(b)
            if line.count >= 2 && line[line.count - 2] == 0x0D && line[line.count - 1] == 0x0A {
                return String(bytes: line[0..<line.count - 2], encoding: .utf8) ?? ""
            }
        }
    }
}

// MARK: - WebSocket Frame

struct Frame {
    let fin: Bool
    let opcode: UInt8
    let payload: [UInt8]
}

func readFrame(reader: BufferedReader) -> Frame? {
    guard let b0 = reader.readByte(), let b1 = reader.readByte() else { return nil }
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let masked = (b1 & 0x80) != 0
    var payloadLen = Int(b1 & 0x7F)

    if payloadLen == 126 {
        guard let bytes = reader.readBytes(2) else { return nil }
        payloadLen = (Int(bytes[0]) << 8) | Int(bytes[1])
    } else if payloadLen == 127 {
        guard let bytes = reader.readBytes(8) else { return nil }
        payloadLen = 0
        for b in bytes {
            payloadLen = (payloadLen << 8) | Int(b)
        }
    }

    var maskKey: [UInt8]? = nil
    if masked {
        maskKey = reader.readBytes(4)
        if maskKey == nil { return nil }
    }

    guard let payload = reader.readBytes(payloadLen) else { return nil }

    var finalPayload = payload
    if let key = maskKey {
        for i in 0..<finalPayload.count {
            finalPayload[i] ^= key[i % 4]
        }
    }

    return Frame(fin: fin, opcode: opcode, payload: finalPayload)
}

func sendFrame(fd: Int32, opcode: UInt8, payload: [UInt8]) {
    var frame: [UInt8] = []
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8((len >> 8) & 0xFF))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in (0..<8).reversed() {
            frame.append(UInt8((len >> (i * 8)) & 0xFF))
        }
    }

    var maskKey: [UInt8]
    repeat {
        maskKey = (0..<4).map { _ in UInt8.random(in: 0...255) }
    } while maskKey == [0, 0, 0, 0]

    frame.append(contentsOf: maskKey)

    var maskedPayload = payload
    for i in 0..<maskedPayload.count {
        maskedPayload[i] ^= maskKey[i % 4]
    }
    frame.append(contentsOf: maskedPayload)

    sendAll(fd: fd, data: frame)
}

// MARK: - URL Parsing

func parseURL(_ url: String) -> (host: String, port: UInt16, path: String) {
    let prefix = "ws://"
    let rest = String(url.dropFirst(prefix.count))
    guard let slashIdx = rest.firstIndex(of: "/") else {
        preconditionFailure("invalid URL: no path")
    }
    let hostPort = String(rest[rest.startIndex..<slashIdx])
    let path = String(rest[slashIdx...])
    guard let colonIdx = hostPort.lastIndex(of: ":") else {
        preconditionFailure("invalid URL: no port")
    }
    let host = String(hostPort[hostPort.startIndex..<colonIdx])
    let portStr = String(hostPort[hostPort.index(after: colonIdx)...])
    guard let port = UInt16(portStr) else {
        preconditionFailure("invalid URL: bad port")
    }
    return (host, port, path)
}

// MARK: - Command processing

func processTextCommand(text: String, fd: Int32, expectBinary: inout Bool, byeMode: inout Bool, sentClose: inout Bool) {
    if text.hasPrefix("ADD ") {
        let argsStr = String(text.dropFirst(4))
        let nums = argsStr.split(separator: " ")
        guard nums.count >= 2, let a = Int64(nums[0]), let b = Int64(nums[1]) else { return }
        let sum = a + b
        let reply = String(sum)
        sendFrame(fd: fd, opcode: 1, payload: Array(reply.utf8))
        print("\(text) -> \(reply)")
    } else if text.hasPrefix("REV ") {
        let content = String(text.dropFirst(4))
        let reversed = reverseByCodePoint(content)
        sendFrame(fd: fd, opcode: 1, payload: Array(reversed.utf8))
        print("\(text) -> \(reversed)")
    } else if text == "SHA1" {
        expectBinary = true
    } else if text == "BYE" {
        let closePayload: [UInt8] = [0x03, 0xE8]
        sendFrame(fd: fd, opcode: 8, payload: closePayload)
        sentClose = true
        byeMode = true
    }
}

// MARK: - Session handling

func handleSession(url: String) {
    let (host, port, path) = parseURL(url)
    let fd = makeSocket(host: host, port: port)
    let reader = BufferedReader(fd: fd)

    // Generate WebSocket key
    let keyBytes = (0..<16).map { _ in UInt8.random(in: 0...255) }
    let key = Data(keyBytes).base64EncodedString()

    // Send handshake request
    var request = "GET \(path) HTTP/1.1\r\n"
    request += "Host: \(host):\(port)\r\n"
    request += "Upgrade: websocket\r\n"
    request += "Connection: Upgrade\r\n"
    request += "Sec-WebSocket-Version: 13\r\n"
    request += "Sec-WebSocket-Key: \(key)\r\n"
    request += "\r\n"
    sendAll(fd: fd, data: Array(request.utf8))

    // Read response status line
    guard let statusLine = reader.readLine() else {
        Darwin.close(fd)
        return
    }

    // Parse status line
    let parts = statusLine.split(separator: " ", maxSplits: 2, omittingEmptySubsequences: false)
    guard parts.count >= 2, let statusCode = Int(parts[1]) else {
        Darwin.close(fd)
        return
    }
    let reasonPhrase = parts.count >= 3 ? String(parts[2]) : ""

    // Read response headers
    var acceptHeader: String? = nil
    while true {
        guard let line = reader.readLine() else {
            Darwin.close(fd)
            return
        }
        if line.isEmpty { break }
        if let colonIdx = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<colonIdx]).lowercased()
            let value = String(line[line.index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
            if name == "sec-websocket-accept" {
                acceptHeader = value
            }
        }
    }

    // Check status code
    if statusCode != 101 {
        print("handshake failed: \(statusCode) \(reasonPhrase)")
        Darwin.close(fd)
        return
    }

    // Check accept header
    let expectedAccept = computeAccept(key: key)
    if acceptHeader != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        Darwin.close(fd)
        return
    }

    // Main frame loop
    var messageBuffer: [UInt8] = []
    var messageOpcode: UInt8 = 0
    var inMessage = false
    var sentClose = false
    var expectBinary = false
    var byeMode = false

    while true {
        guard let frame = readFrame(reader: reader) else { break }

        switch frame.opcode {
        case 9: // Ping
            sendFrame(fd: fd, opcode: 10, payload: frame.payload)

        case 10: // Pong
            break

        case 8: // Close
            var code: Int = 1005
            var reason: String = ""
            if frame.payload.count >= 2 {
                code = (Int(frame.payload[0]) << 8) | Int(frame.payload[1])
                if frame.payload.count > 2 {
                    reason = String(bytes: frame.payload[2...], encoding: .utf8) ?? ""
                }
            }
            if reason.isEmpty {
                print("closed \(code)")
            } else {
                print("closed \(code) \(reason)")
            }
            if !sentClose {
                let closePayload: [UInt8] = [UInt8((code >> 8) & 0xFF), UInt8(code & 0xFF)]
                sendFrame(fd: fd, opcode: 8, payload: closePayload)
                sentClose = true
            }
            Darwin.close(fd)
            return

        case 1, 2: // Text or Binary (new message)
            if byeMode { break }
            inMessage = true
            messageOpcode = frame.opcode
            messageBuffer = frame.payload
            if frame.fin {
                inMessage = false
                if messageOpcode == 1 {
                    let text = String(bytes: messageBuffer, encoding: .utf8) ?? ""
                    processTextCommand(text: text, fd: fd, expectBinary: &expectBinary, byeMode: &byeMode, sentClose: &sentClose)
                } else if messageOpcode == 2 {
                    if expectBinary {
                        expectBinary = false
                        let hex = sha1Hex(messageBuffer)
                        sendFrame(fd: fd, opcode: 1, payload: Array(hex.utf8))
                        print("SHA1 \(messageBuffer.count) -> \(hex)")
                    }
                }
            }

        case 0: // Continuation
            if byeMode { break }
            if inMessage {
                messageBuffer.append(contentsOf: frame.payload)
                if frame.fin {
                    inMessage = false
                    if messageOpcode == 1 {
                        let text = String(bytes: messageBuffer, encoding: .utf8) ?? ""
                        processTextCommand(text: text, fd: fd, expectBinary: &expectBinary, byeMode: &byeMode, sentClose: &sentClose)
                    } else if messageOpcode == 2 {
                        if expectBinary {
                            expectBinary = false
                            let hex = sha1Hex(messageBuffer)
                            sendFrame(fd: fd, opcode: 1, payload: Array(hex.utf8))
                            print("SHA1 \(messageBuffer.count) -> \(hex)")
                        }
                    }
                }
            }

        default:
            break
        }
    }

    Darwin.close(fd)
}

