/* ==================== SHA-1 ==================== */
typedef struct {
    uint32_t state[5];
    uint64_t count;
    uint8_t buffer[64];
} SHA1_CTX;

static void sha1_transform(uint32_t state[5], const uint8_t buffer[64]) {
    uint32_t a, b, c, d, e, w[80];
    int i;
    for (i = 0; i < 16; i++)
        w[i] = ((uint32_t)buffer[i*4]<<24)|((uint32_t)buffer[i*4+1]<<16)|
               ((uint32_t)buffer[i*4+2]<<8)|((uint32_t)buffer[i*4+3]);
    for (i = 16; i < 80; i++) {
        uint32_t t = w[i-3]^w[i-8]^w[i-14]^w[i-16];
        w[i] = (t<<1)|(t>>31);
    }
    a=state[0]; b=state[1]; c=state[2]; d=state[3]; e=state[4];
    for (i = 0; i < 20; i++) {
        uint32_t f = (b&c)|((~b)&d);
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x5A827999;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 20; i < 40; i++) {
        uint32_t f = b^c^d;
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x6ED9EBA1;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 40; i < 60; i++) {
        uint32_t f = (b&c)|(b&d)|(c&d);
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x8F1BBCDC;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 60; i < 80; i++) {
        uint32_t f = b^c^d;
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0xCA62C1D6;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e;
}

static void sha1_init(SHA1_CTX *ctx) {
    ctx->state[0]=0x67452301; ctx->state[1]=0xEFCDAB89;
    ctx->state[2]=0x98BADCFE; ctx->state[3]=0x10325476;
    ctx->state[4]=0xC3D2E1F0; ctx->count=0;
}

static void sha1_update(SHA1_CTX *ctx, const uint8_t *data, size_t len) {
    size_t i = (size_t)(ctx->count & 63);
    ctx->count += len;
    while (len > 0) {
        size_t chunk = 64 - i;
        if (chunk > len) chunk = len;
        memcpy(ctx->buffer + i, data, chunk);
        i += chunk; data += chunk; len -= chunk;
        if (i == 64) { sha1_transform(ctx->state, ctx->buffer); i = 0; }
    }
    ctx->count -= (64 - (ctx->count & 63)); /* fix: just track total */
