        memcpy(ctx->buffer + i, data, chunk);
        offset += chunk; len -= chunk;
        if (len == 0) return;
        sha1_transform(ctx->state, ctx->buffer);
    }
    while (len >= 64) {
        sha1_transform(ctx->state, data + offset);
        offset += 64; len -= 64;
    }
    if (len > 0) memcpy(ctx->buffer, data + offset, len);
}

static void sha1_final(SHA1_CTX *ctx, uint8_t digest[20]) {
    uint64_t bits = ctx->count * 8;
    uint8_t pad = 0x80;
    sha1_update2(ctx, &pad, 1);
    pad = 0;
    while ((ctx->count & 63) != 56)
        sha1_update2(ctx, &pad, 1);
    uint8_t lenbuf[8];
    for (int i = 0; i < 8; i++) lenbuf[i] = (uint8_t)(bits >> (56 - i*8));
    sha1_update2(ctx, lenbuf, 8);
    for (int i = 0; i < 5; i++) {
        digest[i*4]   = (uint8_t)(ctx->state[i]>>24);
        digest[i*4+1] = (uint8_t)(ctx->state[i]>>16);
        digest[i*4+2] = (uint8_t)(ctx->state[i]>>8);
        digest[i*4+3] = (uint8_t)(ctx->state[i]);
    }
}

static void sha1_hash(const uint8_t *data, size_t len, uint8_t digest[20]) {
    SHA1_CTX ctx;
    sha1_init(&ctx);
    sha1_update2(&ctx, data, len);
    sha1_final(&ctx, digest);
}

/* ==================== Base64 ==================== */
static const char b64chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *base64_encode(const uint8_t *data, size_t len) {
    size_t out_len = 4 * ((len + 2) / 3);
    char *out = malloc(out_len + 1);
    size_t i, j;
    for (i = 0, j = 0; i < len; i += 3) {
        uint32_t n = ((uint32_t)data[i]) << 16;
        if (i+1 < len) n |= ((uint32_t)data[i+1]) << 8;
        if (i+2 < len) n |= ((uint32_t)data[i+2]);
        out[j++] = b64chars[(n >> 18) & 0x3F];
        out[j++] = b64chars[(n >> 12) & 0x3F];
        out[j++] = (i+1 < len) ? b64chars[(n >> 6) & 0x3F] : '=';
        out[j++] = (i+2 < len) ? b64chars[n & 0x3F] : '=';
    }
    out[j] = '\0';
    return out;
}

/* ==================== Buffered Reader ==================== */
typedef struct {
    int fd;
    uint8_t buf[65536];
    size_t pos, len;
} reader_t;

static void reader_init(reader_t *r, int fd) {
    r->fd = fd; r->pos = 0; r->len = 0;
}

static int reader_getc(reader_t *r) {
    if (r->pos >= r->len) {
        ssize_t n = read(r->fd, r->buf, sizeof(r->buf));
        if (n <= 0) return -1;
        r->pos = 0; r->len = (size_t)n;
    }
    return r->buf[r->pos++];
}

static int reader_read_exact(reader_t *r, uint8_t *dest, size_t n) {
    size_t got = 0;
    while (got < n) {
        if (r->pos < r->len) {
            size_t avail = r->len - r->pos;
            size_t chunk = avail < (n - got) ? avail : (n - got);
            memcpy(dest + got, r->buf + r->pos, chunk);
            r->pos += chunk;
            got += chunk;
        } else {
            ssize_t rd = read(r->fd, dest + got, n - got);
            if (rd <= 0) return -1;
            got += (size_t)rd;
        }
    }
    return 0;
}

/* ==================== WebSocket Frame I/O ==================== */
typedef struct {
    int fin;
    int opcode;
    uint8_t *payload;
    size_t payload_len;
} ws_frame_t;

static int ws_read_frame(reader_t *r, ws_frame_t *frame) {
    uint8_t hdr[2];
    if (reader_read_exact(r, hdr, 2) < 0) return -1;
    frame->fin = (hdr[0] >> 7) & 1;
    frame->opcode = hdr[0] & 0x0F;
    int masked = (hdr[1] >> 7) & 1;
    uint64_t plen = hdr[1] & 0x7F;
    if (plen == 126) {
        uint8_t ext[2];
        if (reader_read_exact(r, ext, 2) < 0) return -1;
        plen = ((uint64_t)ext[0] << 8) | ext[1];
    } else if (plen == 127) {
        uint8_t ext[8];
        if (reader_read_exact(r, ext, 8) < 0) return -1;
        plen = 0;
        for (int i = 0; i < 8; i++) plen = (plen << 8) | ext[i];
    }
    uint8_t mask_key[4] = {0};
    if (masked) {
        if (reader_read_exact(r, mask_key, 4) < 0) return -1;
    }
    frame->payload = NULL;
    frame->payload_len = (size_t)plen;
    if (plen > 0) {
        frame->payload = malloc((size_t)plen);
        if (reader_read_exact(r, frame->payload, (size_t)plen) < 0) {
            free(frame->payload); frame->payload = NULL; return -1;
        }
        if (masked) {
            for (size_t i = 0; i < (size_t)plen; i++)
                frame->payload[i] ^= mask_key[i & 3];
        }
    }
    return 0;
}

static void ws_frame_free(ws_frame_t *f) {
    free(f->payload); f->payload = NULL;
}

static int ws_send_frame(int fd, int fin, int opcode, const uint8_t *payload, size_t len) {
    uint8_t hdr[14]; /* max header size */
    size_t hlen = 0;
    hdr[0] = (fin ? 0x80 : 0) | (opcode & 0x0F);
    hdr[1] = 0x80; /* MASK bit set */
    hlen = 2;
    if (len <= 125) {
        hdr[1] |= (uint8_t)len;
    } else if (len <= 65535) {
        hdr[1] |= 126;
        hdr[2] = (uint8_t)(len >> 8);
        hdr[3] = (uint8_t)(len & 0xFF);
        hlen = 4;
    } else {
        hdr[1] |= 127;
        for (int i = 0; i < 8; i++)
            hdr[2+i] = (uint8_t)(len >> (56 - i*8));
        hlen = 10;
    }
    /* masking key - must not be all zero */
    uint8_t mk[4];
    do { arc4random_buf(mk, 4); } while (mk[0]==0 && mk[1]==0 && mk[2]==0 && mk[3]==0);
    memcpy(hdr + hlen, mk, 4);
    hlen += 4;
    /* masked payload */
    uint8_t *masked_payload = NULL;
    if (len > 0) {
        masked_payload = malloc(len);
        for (size_t i = 0; i < len; i++)
            masked_payload[i] = payload[i] ^ mk[i & 3];
    }
    /* write all */
    ssize_t total = hlen + len;
    uint8_t *out = malloc(total);
    memcpy(out, hdr, hlen);
    if (len > 0) memcpy(out + hlen, masked_payload, len);
    free(masked_payload);
    size_t written = 0;
    while (written < (size_t)total) {
        ssize_t w = write(fd, out + written, total - written);
        if (w <= 0) { free(out); return -1; }
        written += (size_t)w;
    }
    free(out);
    return 0;
}

/* ==================== UTF-8 ==================== */
static size_t utf8_decode(const uint8_t *s, size_t len, uint32_t *cp) {
    if (len == 0) return 0;
    if (s[0] < 0x80) { *cp = s[0]; return 1; }
    if ((s[0] & 0xE0) == 0xC0 && len >= 2) {
        *cp = ((uint32_t)(s[0] & 0x1F) << 6) | (s[1] & 0x3F); return 2;
    }
    if ((s[0] & 0xF0) == 0xE0 && len >= 3) {
        *cp = ((uint32_t)(s[0] & 0x0F) << 12) | ((uint32_t)(s[1] & 0x3F) << 6) | (s[2] & 0x3F); return 3;
    }
    if ((s[0] & 0xF8) == 0xF0 && len >= 4) {
        *cp = ((uint32_t)(s[0] & 0x07) << 18) | ((uint32_t)(s[1] & 0x3F) << 12) |
              ((uint32_t)(s[2] & 0x3F) << 6) | (s[3] & 0x3F); return 4;
    }
    *cp = s[0]; return 1; /* fallback */
}

static size_t utf8_encode(uint32_t cp, uint8_t *out) {
    if (cp < 0x80) { out[0] = (uint8_t)cp; return 1; }
    if (cp < 0x800) {
        out[0] = 0xC0 | (cp >> 6); out[1] = 0x80 | (cp & 0x3F); return 2;
    }
    if (cp < 0x10000) {
        out[0] = 0xE0 | (cp >> 12); out[1] = 0x80 | ((cp >> 6) & 0x3F);
        out[2] = 0x80 | (cp & 0x3F); return 3;
    }
    out[0] = 0xF0 | (cp >> 18); out[1] = 0x80 | ((cp >> 12) & 0x3F);
    out[2] = 0x80 | ((cp >> 6) & 0x3F); out[3] = 0x80 | (cp & 0x3F); return 4;
}

static uint8_t *utf8_reverse(const uint8_t *s, size_t len, size_t *out_len) {
    /* Decode to code points */
    uint32_t *cps = malloc(len * sizeof(uint32_t));
    size_t ncp = 0;
    size_t i = 0;
    while (i < len) {
        uint32_t cp;
        size_t sz = utf8_decode(s + i, len - i, &cp);
        cps[ncp++] = cp;
        i += sz;
    }
    /* Reverse */
    for (size_t j = 0; j < ncp / 2; j++) {
        uint32_t tmp = cps[j]; cps[j] = cps[ncp-1-j]; cps[ncp-1-j] = tmp;
    }
    /* Encode back */
    uint8_t *out = malloc(len + 4);
    size_t pos = 0;
    for (size_t j = 0; j < ncp; j++)
        pos += utf8_encode(cps[j], out + pos);
    free(cps);
    *out_len = pos;
    return out;
}

/* ==================== URL Parsing ==================== */
typedef struct {
    char host[256];
    int port;
    char path[1024];
} ws_url_t;

static int parse_ws_url(const char *url, ws_url_t *u) {
    const char *p = url;
    if (strncmp(p, "ws://", 5) != 0) return -1;
    p += 5;
    const char *slash = strchr(p, '/');
    if (!slash) return -1;
    size_t hostport_len = slash - p;
    char hostport[256];
    if (hostport_len >= sizeof(hostport)) return -1;
    memcpy(hostport, p, hostport_len);
    hostport[hostport_len] = '\0';
    char *colon = strrchr(hostport, ':');
    if (colon) {
        *colon = '\0';
        u->port = atoi(colon + 1);
        strncpy(u->host, hostport, sizeof(u->host)-1);
    } else {
        u->port = 80;
        strncpy(u->host, hostport, sizeof(u->host)-1);
    }
    u->host[sizeof(u->host)-1] = '\0';
    strncpy(u->path, slash, sizeof(u->path)-1);
    u->path[sizeof(u->path)-1] = '\0';
    return 0;
}

/* ==================== TCP Connection ==================== */
static int tcp_connect(const char *host, int port) {
    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    char portstr[16];
    snprintf(portstr, sizeof(portstr), "%d", port);
    if (getaddrinfo(host, portstr, &hints, &res) != 0) return -1;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
        close(fd); freeaddrinfo(res); return -1;
    }
    freeaddrinfo(res);
    return fd;
}

/* ==================== Handshake ==================== */
static int case_insensitive_contains(const char *haystack, const char *needle) {
    size_t hlen = strlen(haystack), nlen = strlen(needle);
    for (size_t i = 0; i + nlen <= hlen; i++) {
        int match = 1;
        for (size_t j = 0; j < nlen; j++) {
            char hc = haystack[i+j], nc = needle[j];
            if (hc >= 'A' && hc <= 'Z') hc += 32;
            if (nc >= 'A' && nc <= 'Z') nc += 32;
            if (hc != nc) { match = 0; break; }
        }
        if (match) return 1;
    }
    return 0;
}

/* Extract header value from response headers (case-insensitive name match) */
static char *extract_header(const char *headers, const char *name) {
    size_t nlen = strlen(name);
    const char *p = headers;
    while (*p) {
        /* Check if this line starts with the header name (case-insensitive) */
        int match = 1;
        for (size_t i = 0; i < nlen; i++) {
            char hc = p[i], nc = name[i];
            if (hc >= 'A' && hc <= 'Z') hc += 32;
            if (nc >= 'A' && nc <= 'Z') nc += 32;
            if (hc != nc) { match = 0; break; }
        }
        if (match && p[nlen] == ':') {
            const char *val = p + nlen + 1;
            while (*val == ' ' || *val == '\t') val++;
            const char *end = val;
            while (*end && *end != '\r' && *end != '\n') end++;
            size_t vlen = end - val;
            char *result = malloc(vlen + 1);
            memcpy(result, val, vlen);
            result[vlen] = '\0';
            return result;
        }
        /* Skip to next line */
        while (*p && *p != '\n') p++;
        if (*p == '\n') p++;
    }
    return NULL;
}

static int do_handshake(reader_t *r, int fd, const ws_url_t *url, char *ws_key) {
    /* Generate key */
    uint8_t key_bytes[16];
    arc4random_buf(key_bytes, 16);
    char *key_b64 = base64_encode(key_bytes, 16);
    strcpy(ws_key, key_b64);
    free(key_b64);

    /* Build request */
    char req[4096];
    snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        url->path, url->host, url->port, ws_key);

    size_t reqlen = strlen(req);
    size_t written = 0;
    while (written < reqlen) {
        ssize_t w = write(fd, req + written, reqlen - written);
        if (w <= 0) return -1;
        written += (size_t)w;
    }

    /* Read response headers */
    char hdr_buf[8192];
    size_t hdr_len = 0;
    /* Read until \r\n\r\n */
    int state = 0; /* 0=normal, 1=\r, 2=\r\n, 3=\r\n\r */
    while (state < 4 && hdr_len < sizeof(hdr_buf) - 1) {
        int c = reader_getc(r);
        if (c < 0) return -1;
        hdr_buf[hdr_len++] = (char)c;
        if (state == 0 && c == '\r') state = 1;
        else if (state == 1 && c == '\n') state = 2;
        else if (state == 2 && c == '\r') state = 3;
        else if (state == 3 && c == '\n') state = 4;
        else state = (c == '\r') ? 1 : 0;
    }
    hdr_buf[hdr_len] = '\0';

    /* Parse status line */
    int status_code = 0;
    char reason[256] = "";
    if (strncmp(hdr_buf, "HTTP/1.1 ", 9) != 0 && strncmp(hdr_buf, "HTTP/1.0 ", 9) != 0)
        return -1;
    sscanf(hdr_buf + 9, "%d", &status_code);
    /* Extract reason phrase */
    const char *space = strchr(hdr_buf + 9, ' ');
    if (space) {
        space++;
        const char *end = space;
        while (*end && *end != '\r' && *end != '\n') end++;
        size_t rlen = end - space;
        if (rlen >= sizeof(reason)) rlen = sizeof(reason) - 1;
        memcpy(reason, space, rlen);
        reason[rlen] = '\0';
    }

    if (status_code != 101) {
        printf("handshake failed: %d %s\n", status_code, reason);
        return -2; /* signal to skip to next session */
    }

    /* Verify Sec-WebSocket-Accept */
    char *accept = extract_header(hdr_buf, "Sec-WebSocket-Accept");
    if (!accept) {
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        return -2;
    }

    /* Compute expected accept */
    char concat[256];
    snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", ws_key);
    uint8_t digest[20];
    sha1_hash((const uint8_t *)concat, strlen(concat), digest);
    char *expected = base64_encode(digest, 20);

    if (strcmp(accept, expected) != 0) {
        free(accept); free(expected);
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        return -2;
    }
    free(accept); free(expected);
    return 0;
}

/* ==================== Message Reading ==================== */
typedef struct {
    int opcode;
    uint8_t *payload;
    size_t payload_len;
    int is_close;
    int is_ping;
    int is_pong;
} ws_message_t;

/* Read a complete data message (handling fragmentation and interleaved control frames) */
static int read_message(reader_t *r, int fd, ws_message_t *msg) {
    uint8_t *accum = NULL;
    size_t accum_len = 0;
    int msg_opcode = -1;

    for (;;) {
        ws_frame_t frame;
        if (ws_read_frame(r, &frame) < 0) {
            free(accum);
            return -1;
        }

        if (frame.opcode == 9) { /* ping */
            ws_send_frame(fd, 1, 10, frame.payload, frame.payload_len);
            ws_frame_free(&frame);
            continue;
        }
        if (frame.opcode == 10) { /* pong */
            ws_frame_free(&frame);
            continue;
        }
        if (frame.opcode == 8) { /* close */
            free(accum);
            msg->is_close = 1;
            msg->is_ping = 0;
            msg->is_pong = 0;
            msg->opcode = 8;
            msg->payload = frame.payload;
            msg->payload_len = frame.payload_len;
            return 0;
        }

        if (frame.opcode == 0) {
            /* continuation */
            if (accum == NULL) { /* error: continuation without start */
                ws_frame_free(&frame);
                return -1;
            }
            uint8_t *tmp = realloc(accum, accum_len + frame.payload_len);
            if (!tmp) { free(accum); ws_frame_free(&frame); return -1; }
            accum = tmp;
            memcpy(accum + accum_len, frame.payload, frame.payload_len);
            accum_len += frame.payload_len;
            if (frame.fin) {
                msg->opcode = msg_opcode;
                msg->payload = accum;
                msg->payload_len = accum_len;
                msg->is_close = 0; msg->is_ping = 0; msg->is_pong = 0;
                return 0;
            }
        } else if (frame.opcode == 1 || frame.opcode == 2) {
            /* start of new message */
            if (accum != NULL) { /* error: new message while fragmenting */
                free(accum);
            }
            msg_opcode = frame.opcode;
            accum = malloc(frame.payload_len + 1);
            memcpy(accum, frame.payload, frame.payload_len);
            accum_len = frame.payload_len;
            if (frame.fin) {
                msg->opcode = msg_opcode;
                msg->payload = accum;
                msg->payload_len = accum_len;
                msg->is_close = 0; msg->is_ping = 0; msg->is_pong = 0;
                return 0;
            }
        } else {
            /* unknown opcode, skip */
            ws_frame_free(&frame);
            continue;
        }
        ws_frame_free(&frame);
    }
}

/* ==================== Command Processing ==================== */
static void process_command(reader_t *r, int fd, const char *cmd_text) {
    if (strncmp(cmd_text, "ADD ", 4) == 0) {
        const char *args = cmd_text + 4;
        /* Parse two integers */
        const char *sp = strchr(args, ' ');
        if (!sp) return;
        char a_str[64], b_str[64];
        size_t alen = sp - args;
        if (alen >= sizeof(a_str)) alen = sizeof(a_str) - 1;
        memcpy(a_str, args, alen); a_str[alen] = '\0';
        const char *b_start = sp + 1;
        strncpy(b_str, b_start, sizeof(b_str)-1);
        b_str[sizeof(b_str)-1] = '\0';
        /* Trim trailing whitespace/newlines from b_str */
        size_t blen = strlen(b_str);
        while (blen > 0 && (b_str[blen-1]=='\r'||b_str[blen-1]=='\n'||b_str[blen-1]==' '))
            b_str[--blen] = '\0';

        long long a = strtoll(a_str, NULL, 10);
        long long b = strtoll(b_str, NULL, 10);
        long long sum = a + b;
        char reply[64];
        snprintf(reply, sizeof(reply), "%lld", sum);
        ws_send_frame(fd, 1, 1, (const uint8_t *)reply, strlen(reply));
        printf("ADD %s %s -> %s\n", a_str, b_str, reply);
    }
    else if (strncmp(cmd_text, "REV ", 4) == 0) {
        const char *text = cmd_text + 4;
        size_t text_len = strlen(text);
        /* Trim trailing \r\n */
        while (text_len > 0 && (text[text_len-1]=='\r'||text[text_len-1]=='\n'))
            text_len--;
        size_t rev_len;
        uint8_t *rev = utf8_reverse((const uint8_t *)text, text_len, &rev_len);
        ws_send_frame(fd, 1, 1, rev, rev_len);
        printf("REV %.*s -> %.*s\n", (int)text_len, text, (int)rev_len, rev);
        free(rev);
    }
    else if (strcmp(cmd_text, "SHA1") == 0 || strncmp(cmd_text, "SHA1\r\n", 6) == 0 ||
             strncmp(cmd_text, "SHA1\n", 5) == 0) {
        /* Read next binary message */
        ws_message_t bin_msg;
        if (read_message(r, fd, &bin_msg) < 0) return;
        if (bin_msg.is_close) {
            /* Handle close */
            if (bin_msg.payload_len >= 2) {
                int code = (bin_msg.payload[0] << 8) | bin_msg.payload[1];
                if (bin_msg.payload_len > 2) {
                    printf("closed %d %.*s\n", code, (int)(bin_msg.payload_len - 2), (char*)(bin_msg.payload + 2));
                } else {
                    printf("closed %d\n", code);
                }
            } else {
                printf("closed 0\n");
            }
            free(bin_msg.payload);
            return;
        }
        uint8_t digest[20];
        sha1_hash(bin_msg.payload, bin_msg.payload_len, digest);
        char hex[41];
        for (int i = 0; i < 20; i++)
            snprintf(hex + i*2, 3, "%02x", digest[i]);
        hex[40] = '\0';
        ws_send_frame(fd, 1, 1, (const uint8_t *)hex, 40);
        printf("SHA1 %zu -> %s\n", bin_msg.payload_len, hex);
        free(bin_msg.payload);
    }
    else if (strcmp(cmd_text, "BYE") == 0 || strncmp(cmd_text, "BYE\r\n", 5) == 0 ||
             strncmp(cmd_text, "BYE\n", 4) == 0) {
        /* Send close frame with code 1000 */
        uint8_t close_payload[2] = {0x03, 0xE8};
        ws_send_frame(fd, 1, 8, close_payload, 2);
        /* Read until server's close frame */
        for (;;) {
            ws_message_t msg;
            if (read_message(r, fd, &msg) < 0) return;
            if (msg.is_close) {
                if (msg.payload_len >= 2) {
                    int code = (msg.payload[0] << 8) | msg.payload[1];
                    if (msg.payload_len > 2) {
                        printf("closed %d %.*s\n", code, (int)(msg.payload_len - 2), (char*)(msg.payload + 2));
                    } else {
                        printf("closed %d\n", code);
                    }
                } else {
                    printf("closed 0\n");
                }
                free(msg.payload);
                return;
            }
            free(msg.payload);
        }
    }
}

/* ==================== Session ==================== */
static void handle_session(const char *url_str) {
    ws_url_t url;
    if (parse_ws_url(url_str, &url) < 0) return;

    int fd = tcp_connect(url.host, url.port);
    if (fd < 0) return;

    reader_t reader;
    reader_init(&reader, fd);

    char ws_key[64];
    int hs = do_handshake(&reader, fd, &url, ws_key);
    if (hs != 0) {
        close(fd);
        return;
    }

    int sent_close = 0;

    /* Main message loop */
    for (;;) {
        ws_message_t msg;
        if (read_message(&reader, fd, &msg) < 0) break;

        if (msg.is_close) {
            if (msg.payload_len >= 2) {
                int code = (msg.payload[0] << 8) | msg.payload[1];
                if (msg.payload_len > 2) {
                    printf("closed %d %.*s\n", code, (int)(msg.payload_len - 2), (char*)(msg.payload + 2));
                } else {
                    printf("closed %d\n", code);
                }
            } else {
                printf("closed 0\n");
            }
            if (!sent_close) {
                /* Send close back with same code, no reason */
                uint8_t cp[2];
                cp[0] = msg.payload[0]; cp[1] = msg.payload[1];
                ws_send_frame(fd, 1, 8, cp, 2);
            }
            free(msg.payload);
            break;
        }

        if (msg.opcode == 1) {
            /* Text message - command */
            /* Null-terminate for string operations */
            uint8_t *tmp = realloc(msg.payload, msg.payload_len + 1);
            msg.payload = tmp;
            msg.payload[msg.payload_len] = '\0';
            process_command(&reader, fd, (const char *)msg.payload);
            free(msg.payload);
        } else if (msg.opcode == 2) {
            /* Unexpected binary message outside SHA1 context - ignore */
            free(msg.payload);
        } else {
            free(msg.payload);
        }
    }

    close(fd);
}

/* ==================== Main ==================== */
int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        printf("session %d\n", i);
        fflush(stdout);
        handle_session(argv[i]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <time.h>

/* ==================== SHA-1 ==================== */
typedef struct {
    uint32_t state[5];
    uint64_t count;
    uint8_t buffer[64];
} SHA1_CTX;

static void sha1_transform(uint32_t state[5], const uint8_t buffer[64]) {
    uint32_t a, b, c, d, e, w[80];
    int i;
    for (i = 0; i < 16; i++)
        w[i] = ((uint32_t)buffer[i*4]<<24)|((uint32_t)buffer[i*4+1]<<16)|
               ((uint32_t)buffer[i*4+2]<<8)|((uint32_t)buffer[i*4+3]);
    for (i = 16; i < 80; i++) {
        uint32_t t = w[i-3]^w[i-8]^w[i-14]^w[i-16];
        w[i] = (t<<1)|(t>>31);
    }
    a=state[0]; b=state[1]; c=state[2]; d=state[3]; e=state[4];
    for (i = 0; i < 20; i++) {
        uint32_t f = (b&c)|((~b)&d);
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x5A827999;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 20; i < 40; i++) {
        uint32_t f = b^c^d;
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x6ED9EBA1;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 40; i < 60; i++) {
        uint32_t f = (b&c)|(b&d)|(c&d);
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0x8F1BBCDC;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    for (i = 60; i < 80; i++) {
        uint32_t f = b^c^d;
        uint32_t t = ((a<<5)|(a>>27))+f+e+w[i]+0xCA62C1D6;
        e=d; d=c; c=(b<<30)|(b>>2); b=a; a=t;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e;
}

static void sha1_init(SHA1_CTX *ctx) {
    ctx->state[0]=0x67452301; ctx->state[1]=0xEFCDAB89;
    ctx->state[2]=0x98BADCFE; ctx->state[3]=0x10325476;
    ctx->state[4]=0xC3D2E1F0; ctx->count=0;
}

static void sha1_update(SHA1_CTX *ctx, const uint8_t *data, size_t len) {
    size_t i = (size_t)(ctx->count & 63);
    ctx->count += len;
    size_t offset = 0;
    if (i > 0) {
        size_t chunk = 64 - i;
        if (chunk > len) chunk = len;
        memcpy(ctx->buffer + i, data, chunk);
        offset += chunk; len -= chunk;
        if (i + chunk == 64) {
            sha1_transform(ctx->state, ctx->buffer);
        }
        if (len == 0) return;
    }
    while (len >= 64) {
        sha1_transform(ctx->state, data + offset);
        offset += 64; len -= 64;
    }
    if (len > 0) memcpy(ctx->buffer, data + offset, len);
}

static void sha1_final(SHA1_CTX *ctx, uint8_t digest[20]) {
    uint64_t bits = ctx->count * 8;
    uint8_t pad = 0x80;
    sha1_update(ctx, &pad, 1);
    pad = 0;
    while ((ctx->count & 63) != 56)
        sha1_update(ctx, &pad, 1);
    uint8_t lenbuf[8];
    for (int i = 0; i < 8; i++) lenbuf[i] = (uint8_t)(bits >> (56 - i*8));
    sha1_update(ctx, lenbuf, 8);
    for (int i = 0; i < 5; i++) {
        digest[i*4]   = (uint8_t)(ctx->state[i]>>24);
        digest[i*4+1] = (uint8_t)(ctx->state[i]>>16);
        digest[i*4+2] = (uint8_t)(ctx->state[i]>>8);
        digest[i*4+3] = (uint8_t)(ctx->state[i]);
    }
}

static void sha1_hash(const uint8_t *data, size_t len, uint8_t digest[20]) {
    SHA1_CTX ctx;
    sha1_init(&ctx);
    sha1_update(&ctx, data, len);
    sha1_final(&ctx, digest);
}

/* ==================== Base64 ==================== */
static const char b64chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *base64_encode(const uint8_t *data, size_t len) {
    size_t out_len = 4 * ((len + 2) / 3);
    char *out = malloc(out_len + 1);
    size_t i, j;
    for (i = 0, j = 0; i < len; i += 3) {
        uint32_t n = ((uint32_t)data[i]) << 16;
        if (i+1 < len) n |= ((uint32_t)data[i+1]) << 8;
        if (i+2 < len) n |= ((uint32_t)data[i+2]);
        out[j++] = b64chars[(n >> 18) & 0x3F];
        out[j++] = b64chars[(n >> 12) & 0x3F];
        out[j++] = (i+1 < len) ? b64chars[(n >> 6) & 0x3F] : '=';
        out[j++] = (i+2 < len) ? b64chars[n & 0x3F] : '=';
    }
    out[j] = '\0';
    return out;
}

/* ==================== Buffered Reader ==================== */
typedef struct {
    int fd;
    uint8_t buf[65536];
    size_t pos, len;
} reader_t;

static void reader_init(reader_t *r, int fd) {
    r->fd = fd; r->pos = 0; r->len = 0;
}

static int reader_getc(reader_t *r) {
    if (r->pos >= r->len) {
        ssize_t n = read(r->fd, r->buf, sizeof(r->buf));
        if (n <= 0) return -1;
        r->pos = 0; r->len = (size_t)n;
    }
    return r->buf[r->pos++];
}

static int reader_read_exact(reader_t *r, uint8_t *dest, size_t n) {
    size_t got = 0;
    while (got < n) {
        if (r->pos < r->len) {
            size_t avail = r->len - r->pos;
            size_t chunk = avail < (n - got) ? avail : (n - got);
            memcpy(dest + got, r->buf + r->pos, chunk);
            r->pos += chunk;
            got += chunk;
        } else {
            ssize_t rd = read(r->fd, dest + got, n - got);
            if (rd <= 0) return -1;
            got += (size_t)rd;
        }
    }
    return 0;
}

/* ==================== WebSocket Frame I/O ==================== */
typedef struct {
    int fin;
    int opcode;
    uint8_t *payload;
    size_t payload_len;
} ws_frame_t;

static int ws_read_frame(reader_t *r, ws_frame_t *frame) {
    uint8_t hdr[2];
    if (reader_read_exact(r, hdr, 2) < 0) return -1;
    frame->fin = (hdr[0] >> 7) & 1;
    frame->opcode = hdr[0] & 0x0F;
    int masked = (hdr[1] >> 7) & 1;
    uint64_t plen = hdr[1] & 0x7F;
    if (plen == 126) {
        uint8_t ext[2];
        if (reader_read_exact(r, ext, 2) < 0) return -1;
        plen = ((uint64_t)ext[0] << 8) | ext[1];
    } else if (plen == 127) {
        uint8_t ext[8];
        if (reader_read_exact(r, ext, 8) < 0) return -1;
        plen = 0;
        for (int i = 0; i < 8; i++) plen = (plen << 8) | ext[i];
    }
    uint8_t mask_key[4] = {0};
    if (masked) {
        if (reader_read_exact(r, mask_key, 4) < 0) return -1;
    }
    frame->payload = NULL;
    frame->payload_len = (size_t)plen;
    if (plen > 0) {
        frame->payload = malloc((size_t)plen);
        if (!frame->payload) return -1;
        if (reader_read_exact(r, frame->payload, (size_t)plen) < 0) {
            free(frame->payload); frame->payload = NULL; return -1;
        }
        if (masked) {
            for (size_t i = 0; i < (size_t)plen; i++)
                frame->payload[i] ^= mask_key[i & 3];
        }
    }
    return 0;
}

static void ws_frame_free(ws_frame_t *f) {
    free(f->payload); f->payload = NULL;
}

static int ws_send_frame(int fd, int fin, int opcode, const uint8_t *payload, size_t len) {
    uint8_t hdr[14];
    size_t hlen = 0;
    hdr[0] = (fin ? 0x80 : 0) | (opcode & 0x0F);
    hdr[1] = 0x80;
    hlen = 2;
    if (len <= 125) {
        hdr[1] |= (uint8_t)len;
    } else if (len <= 65535) {
        hdr[1] |= 126;
        hdr[2] = (uint8_t)(len >> 8);
        hdr[3] = (uint8_t)(len & 0xFF);
        hlen = 4;
    } else {
        hdr[1] |= 127;
        for (int i = 0; i < 8; i++)
            hdr[2+i] = (uint8_t)(len >> (56 - i*8));
        hlen = 10;
    }
    uint8_t mk[4];
    do { arc4random_buf(mk, 4); } while (mk[0]==0 && mk[1]==0 && mk[2]==0 && mk[3]==0);
    memcpy(hdr + hlen, mk, 4);
    hlen += 4;
    uint8_t *masked_payload = NULL;
    if (len > 0) {
        masked_payload = malloc(len);
        if (!masked_payload) return -1;
        for (size_t i = 0; i < len; i++)
            masked_payload[i] = payload[i] ^ mk[i & 3];
    }
    ssize_t total = (ssize_t)(hlen + len);
    uint8_t *out = malloc((size_t)total);
    if (!out) { free(masked_payload); return -1; }
    memcpy(out, hdr, hlen);
    if (len > 0) memcpy(out + hlen, masked_payload, len);
    free(masked_payload);
    size_t written = 0;
    while (written < (size_t)total) {
        ssize_t w = write(fd, out + written, (size_t)total - written);
        if (w <= 0) { free(out); return -1; }
        written += (size_t)w;
    }
    free(out);
    return 0;
}

/* ==================== UTF-8 ==================== */
static size_t utf8_decode(const uint8_t *s, size_t len, uint32_t *cp) {
    if (len == 0) return 0;
    if (s[0] < 0x80) { *cp = s[0]; return 1; }
    if ((s[0] & 0xE0) == 0xC0 && len >= 2) {
        *cp = ((uint32_t)(s[0] & 0x1F) << 6) | (s[1] & 0x3F); return 2;
    }
    if ((s[0] & 0xF0) == 0xE0 && len >= 3) {
        *cp = ((uint32_t)(s[0] & 0x0F) << 12) | ((uint32_t)(s[1] & 0x3F) << 6) | (s[2] & 0x3F); return 3;
    }
    if ((s[0] & 0xF8) == 0xF0 && len >= 4) {
        *cp = ((uint32_t)(s[0] & 0x07) << 18) | ((uint32_t)(s[1] & 0x3F) << 12) |
              ((uint32_t)(s[2] & 0x3F) << 6) | (s[3] & 0x3F); return 4;
    }
    *cp = s[0]; return 1;
}

static size_t utf8_encode(uint32_t cp, uint8_t *out) {
    if (cp < 0x80) { out[0] = (uint8_t)cp; return 1; }
    if (cp < 0x800) {
        out[0] = 0xC0 | (uint8_t)(cp >> 6); out[1] = 0x80 | (uint8_t)(cp & 0x3F); return 2;
    }
    if (cp < 0x10000) {
        out[0] = 0xE0 | (uint8_t)(cp >> 12); out[1] = 0x80 | (uint8_t)((cp >> 6) & 0x3F);
        out[2] = 0x80 | (uint8_t)(cp & 0x3F); return 3;
    }
    out[0] = 0xF0 | (uint8_t)(cp >> 18); out[1] = 0x80 | (uint8_t)((cp >> 12) & 0x3F);
    out[2] = 0x80 | (uint8_t)((cp >> 6) & 0x3F); out[3] = 0x80 | (uint8_t)(cp & 0x3F); return 4;
}

static uint8_t *utf8_reverse(const uint8_t *s, size_t len, size_t *out_len) {
    uint32_t *cps = malloc((len + 1) * sizeof(uint32_t));
    size_t ncp = 0;
    size_t i = 0;
    while (i < len) {
        uint32_t cp;
        size_t sz = utf8_decode(s + i, len - i, &cp);
        cps[ncp++] = cp;
        i += sz;
    }
    for (size_t j = 0; j < ncp / 2; j++) {
        uint32_t tmp = cps[j]; cps[j] = cps[ncp-1-j]; cps[ncp-1-j] = tmp;
    }
    uint8_t *out = malloc(len + 4);
    size_t pos = 0;
    for (size_t j = 0; j < ncp; j++)
        pos += utf8_encode(cps[j], out + pos);
    free(cps);
    *out_len = pos;
    return out;
}

/* ==================== URL Parsing ==================== */
typedef struct {
    char host[256];
    int port;
    char path[1024];
} ws_url_t;

static int parse_ws_url(const char *url, ws_url_t *u) {
    const char *p = url;
    if (strncmp(p, "ws://", 5) != 0) return -1;
    p += 5;
    const char *slash = strchr(p, '/');
    if (!slash) return -1;
    size_t hostport_len = (size_t)(slash - p);
    char hostport[256];
    if (hostport_len >= sizeof(hostport)) return -1;
    memcpy(hostport, p, hostport_len);
    hostport[hostport_len] = '\0';
    char *colon = strrchr(hostport, ':');
    if (colon) {
        *colon = '\0';
        u->port = atoi(colon + 1);
        strncpy(u->host, hostport, sizeof(u->host)-1);
    } else {
        u->port = 80;
        strncpy(u->host, hostport, sizeof(u->host)-1);
    }
    u->host[sizeof(u->host)-1] = '\0';
    strncpy(u->path, slash, sizeof(u->path)-1);
    u->path[sizeof(u->path)-1] = '\0';
    return 0;
}

/* ==================== TCP Connection ==================== */
static int tcp_connect(const char *host, int port) {
    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    char portstr[16];
    snprintf(portstr, sizeof(portstr), "%d", port);
    if (getaddrinfo(host, portstr, &hints, &res) != 0) return -1;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
        close(fd); freeaddrinfo(res); return -1;
    }
    freeaddrinfo(res);
    return fd;
}

/* ==================== Handshake ==================== */
static char *extract_header(const char *headers, const char *name) {
    size_t nlen = strlen(name);
    const char *p = headers;
    while (*p) {
        int match = 1;
        for (size_t i = 0; i < nlen; i++) {
            if (p[i] == '\0' || p[i] == '\r' || p[i] == '\n') { match = 0; break; }
            char hc = p[i], nc = name[i];
            if (hc >= 'A' && hc <= 'Z') hc += 32;
            if (nc >= 'A' && nc <= 'Z') nc += 32;
            if (hc != nc) { match = 0; break; }
        }
        if (match && p[nlen] == ':') {
            const char *val = p + nlen + 1;
            while (*val == ' ' || *val == '\t') val++;
            const char *end = val;
            while (*end && *end != '\r' && *end != '\n') end++;
            size_t vlen = (size_t)(end - val);
            char *result = malloc(vlen + 1);
            memcpy(result, val, vlen);
            result[vlen] = '\0';
            return result;
        }
        while (*p && *p != '\n') p++;
        if (*p == '\n') p++;
    }
    return NULL;
}

static int do_handshake(reader_t *r, int fd, const ws_url_t *url, char *ws_key) {
    uint8_t key_bytes[16];
    arc4random_buf(key_bytes, 16);
    char *key_b64 = base64_encode(key_bytes, 16);
    strcpy(ws_key, key_b64);
    free(key_b64);

    char req[4096];
    snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        url->path, url->host, url->port, ws_key);

    size_t reqlen = strlen(req);
    size_t written = 0;
    while (written < reqlen) {
        ssize_t w = write(fd, req + written, reqlen - written);
        if (w <= 0) return -1;
        written += (size_t)w;
    }

    char hdr_buf[8192];
    size_t hdr_len = 0;
    int state = 0;
    while (state < 4 && hdr_len < sizeof(hdr_buf) - 1) {
        int c = reader_getc(r);
        if (c < 0) return -1;
        hdr_buf[hdr_len++] = (char)c;
        if (state == 0 && c == '\r') state = 1;
        else if (state == 1 && c == '\n') state = 2;
        else if (state == 2 && c == '\r') state = 3;
        else if (state == 3 && c == '\n') state = 4;
        else state = (c == '\r') ? 1 : 0;
    }
    hdr_buf[hdr_len] = '\0';

    int status_code = 0;
    char reason[256] = "";
    if (strncmp(hdr_buf, "HTTP/1.1 ", 9) != 0 && strncmp(hdr_buf, "HTTP/1.0 ", 9) != 0)
        return -1;
    sscanf(hdr_buf + 9, "%d", &status_code);
    const char *space = strchr(hdr_buf + 9, ' ');
    if (space) {
        space++;
        const char *end = space;
        while (*end && *end != '\r' && *end != '\n') end++;
        size_t rlen = (size_t)(end - space);
        if (rlen >= sizeof(reason)) rlen = sizeof(reason) - 1;
        memcpy(reason, space, rlen);
        reason[rlen] = '\0';
    }

    if (status_code != 101) {
        printf("handshake failed: %d %s\n", status_code, reason);
        return -2;
    }

    char *accept = extract_header(hdr_buf, "Sec-WebSocket-Accept");
    if (!accept) {
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        return -2;
    }

    char concat[256];
    snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", ws_key);
    uint8_t digest[20];
    sha1_hash((const uint8_t *)concat, strlen(concat), digest);
    char *expected = base64_encode(digest, 20);

    if (strcmp(accept, expected) != 0) {
        free(accept); free(expected);
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        return -2;
    }
    free(accept); free(expected);
    return 0;
}

/* ==================== Message Reading ==================== */
typedef struct {
    int opcode;
    uint8_t *payload;
    size_t payload_len;
    int is_close;
} ws_message_t;

static int read_message(reader_t *r, int fd, ws_message_t *msg) {
    uint8_t *accum = NULL;
    size_t accum_len = 0;
    int msg_opcode = -1;

    for (;;) {
        ws_frame_t frame;
        if (ws_read_frame(r, &frame) < 0) {
            free(accum);
            return -1;
        }

        if (frame.opcode == 9) {
            ws_send_frame(fd, 1, 10, frame.payload, frame.payload_len);
            ws_frame_free(&frame);
            continue;
        }
        if (frame.opcode == 10) {
            ws_frame_free(&frame);
            continue;
        }
        if (frame.opcode == 8) {
            free(accum);
            msg->is_close = 1;
            msg->opcode = 8;
            msg->payload = frame.payload;
            msg->payload_len = frame.payload_len;
            return 0;
        }

        if (frame.opcode == 0) {
            if (accum == NULL) {
                ws_frame_free(&frame);
                return -1;
            }
            uint8_t *tmp = realloc(accum, accum_len + frame.payload_len + 1);
            if (!tmp) { free(accum); ws_frame_free(&frame); return -1; }
            accum = tmp;
            if (frame.payload_len > 0)
                memcpy(accum + accum_len, frame.payload, frame.payload_len);
            accum_len += frame.payload_len;
            if (frame.fin) {
                msg->opcode = msg_opcode;
                msg->payload = accum;
                msg->payload_len = accum_len;
                msg->is_close = 0;
                return 0;
            }
        } else if (frame.opcode == 1 || frame.opcode == 2) {
            if (accum != NULL) {
                free(accum);
            }
            msg_opcode = frame.opcode;
            accum = malloc(frame.payload_len + 1);
            if (!accum) { ws_frame_free(&frame); return -1; }
            if (frame.payload_len > 0)
                memcpy(accum, frame.payload, frame.payload_len);
            accum_len = frame.payload_len;
            if (frame.fin) {
                msg->opcode = msg_opcode;
                msg->payload = accum;
                msg->payload_len = accum_len;
                msg->is_close = 0;
                return 0;
            }
        } else {
            ws_frame_free(&frame);
            continue;
        }
        ws_frame_free(&frame);
    }
}

/* ==================== Command Processing ==================== */
static void print_close(ws_message_t *msg) {
    if (msg->payload_len >= 2) {
        int code = (msg->payload[0] << 8) | msg->payload[1];
        if (msg->payload_len > 2) {
            printf("closed %d %.*s\n", code, (int)(msg->payload_len - 2), (char*)(msg->payload + 2));
        } else {
            printf("closed %d\n", code);
        }
    } else {
        printf("closed 0\n");
    }
}

static void process_command(reader_t *r, int fd, const char *cmd_text, size_t cmd_len) {
    if (cmd_len >= 4 && strncmp(cmd_text, "ADD ", 4) == 0) {
        const char *args = cmd_text + 4;
        const char *sp = memchr(args, ' ', cmd_len - 4);
        if (!sp) return;
        char a_str[64], b_str[64];
        size_t alen = (size_t)(sp - args);
        if (alen >= sizeof(a_str)) alen = sizeof(a_str) - 1;
        memcpy(a_str, args, alen); a_str[alen] = '\0';
        const char *b_start = sp + 1;
        size_t b_max = cmd_len - 4 - alen - 1;
        if (b_max >= sizeof(b_str)) b_max = sizeof(b_str) - 1;
        memcpy(b_str, b_start, b_max); b_str[b_max] = '\0';
        size_t blen = strlen(b_str);
        while (blen > 0 && (b_str[blen-1]=='\r'||b_str[blen-1]=='\n'||b_str[blen-1]==' '))
            b_str[--blen] = '\0';

        long long a = strtoll(a_str, NULL, 10);
        long long b = strtoll(b_str, NULL, 10);
        long long sum = a + b;
        char reply[64];
        snprintf(reply, sizeof(reply), "%lld", sum);
        ws_send_frame(fd, 1, 1, (const uint8_t *)reply, strlen(reply));
        printf("ADD %s %s -> %s\n", a_str, b_str, reply);
    }
    else if (cmd_len >= 4 && strncmp(cmd_text, "REV ", 4) == 0) {
        const char *text = cmd_text + 4;
        size_t text_len = cmd_len - 4;
        while (text_len > 0 && (text[text_len-1]=='\r'||text[text_len-1]=='\n'))
            text_len--;
        size_t rev_len;
        uint8_t *rev = utf8_reverse((const uint8_t *)text, text_len, &rev_len);
        ws_send_frame(fd, 1, 1, rev, rev_len);
        printf("REV %.*s -> %.*s\n", (int)text_len, text, (int)rev_len, rev);
        free(rev);
    }
    else if (cmd_len == 4 && strncmp(cmd_text, "SHA1", 4) == 0) {
        ws_message_t bin_msg;
        if (read_message(r, fd, &bin_msg) < 0) return;
        if (bin_msg.is_close) {
            print_close(&bin_msg);
            free(bin_msg.payload);
            return;
        }
        uint8_t digest[20];
        sha1_hash(bin_msg.payload, bin_msg.payload_len, digest);
        char hex[41];
        for (int i = 0; i < 20; i++)
            snprintf(hex + i*2, 3, "%02x", digest[i]);
        hex[40] = '\0';
        ws_send_frame(fd, 1, 1, (const uint8_t *)hex, 40);
        printf("SHA1 %zu -> %s\n", bin_msg.payload_len, hex);
        free(bin_msg.payload);
    }
    else if (cmd_len == 3 && strncmp(cmd_text, "BYE", 3) == 0) {
        uint8_t close_payload[2] = {0x03, 0xE8};
        ws_send_frame(fd, 1, 8, close_payload, 2);
        for (;;) {
            ws_message_t msg;
            if (read_message(r, fd, &msg) < 0) return;
            if (msg.is_close) {
                print_close(&msg);
                free(msg.payload);
                return;
            }
            free(msg.payload);
        }
    }
}

/* ==================== Session ==================== */
static void handle_session(const char *url_str) {
    ws_url_t url;
    if (parse_ws_url(url_str, &url) < 0) return;

    int fd = tcp_connect(url.host, url.port);
    if (fd < 0) return;

    reader_t reader;
    reader_init(&reader, fd);

    char ws_key[64];
    int hs = do_handshake(&reader, fd, &url, ws_key);
    if (hs != 0) {
        close(fd);
        return;
    }

    int sent_close = 0;

    for (;;) {
        ws_message_t msg;
        if (read_message(&reader, fd, &msg) < 0) break;

        if (msg.is_close) {
            print_close(&msg);
            if (!sent_close) {
                uint8_t cp[2];
                if (msg.payload_len >= 2) {
                    cp[0] = msg.payload[0]; cp[1] = msg.payload[1];
                } else {
                    cp[0] = 0x03; cp[1] = 0xE8;
                }
                ws_send_frame(fd, 1, 8, cp, 2);
            }
            free(msg.payload);
            break;
        }

        if (msg.opcode == 1) {
            uint8_t *tmp = realloc(msg.payload, msg.payload_len + 1);
            if (tmp) {
                msg.payload = tmp;
                msg.payload[msg.payload_len] = '\0';
                process_command(&reader, fd, (const char *)msg.payload, msg.payload_len);
            }
            free(msg.payload);
        } else if (msg.opcode == 2) {
            free(msg.payload);
        } else {
            free(msg.payload);
        }
    }

    close(fd);
}

/* ==================== Main ==================== */
int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        printf("session %d\n", i);
        fflush(stdout);
        handle_session(argv[i]);
    }
    return 0;
}
